INSERT INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score, created_at, google_place_id, category, cuisine, price_band, veg_flag, source, updated_at, verification_status, verification_notes, verified_at) VALUES
('100027', '1002', 'Tirumala Venkateswara Temple', 'Tirumala Temple', 'The world famous hilltop temple of Lord Venkateswara, among the most visited religious sites on earth.', '4-6 hours', 'Early Morning', 'Book Special Entry Darshan online weeks ahead; it saves hours of waiting.', 'Special Entry Darshan booking required', 'Andhra Pradesh', '1', '0', '5:00 AM', '', 'Slotted Sarva Darshan free (tokens at Tirupati counters, first-come first-served); Special Entry Darshan Rs 300/person online; Srivani VIP Break Darshan Rs 10,500/person (per 2026 TTD guides; homep...', 5.0, 5.0, 13.6833, 79.35, 'Tirumala, Tirupati, Andhra Pradesh', 'http://www.tirumala.org', 0.99, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'partial', 'Exists (TTD). No single official daily open/close published; darshan runs ~3 AM to ~1 AM varying by ticket type. File''s flat 4 AM-9 PM is a simplification. [Price source: tirumala.org (homepage/SSD counters) + 2026 TTD booking guides] Official TTD site; bookings on ttdevasthanams.ap.gov.in.', '2026-09-30'),
('100028', '1002', 'Padmavathi Temple, Tiruchanur', 'Padmavathi Temple', 'Temple of Goddess Padmavathi in Tiruchanur; tradition says Tirumala pilgrims visit here too.', '1-2 hours', 'Morning', 'Visit on Friday for the special abhishekam crowds and festive mood.', '', 'Andhra Pradesh', '0', '0', '', '', 'Free general darshan; Special Entry Darshan Rs 200/person; VIP Break ~Rs 500; sevas Rs 25-1,000 (e.g. Kumkum Archana Rs 200, Friday Abhishekam Rs 400).', 4.7, 4.6, 13.6, 79.45, 'Tiruchanur, Tirupati, Andhra Pradesh', '', 0.9, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'partial', 'Exists (TTD). No dedicated site; bookings via ttdevasthanams.ap.gov.in. Multiple sources: opens 4:50 AM (3:30 AM Fridays), closes ~9-9:30 PM, break ~12:30-3:30 PM. [Price source: templesmap.com, mandirtimings.com, pujanpujari.com] TTD-run; seva/darshan bookings via ttdevasthanams.ap.gov.in.', '2026-09-30'),
('100029', '1002', 'Kapila Theertham', 'Kapila Theertham', 'A temple at the base of a waterfall where Lord Shiva is worshipped; water flows over the shrine in monsoon.', '1 hour', 'Morning', 'Best just after monsoon when the falls are full.', '', 'Andhra Pradesh', '0', '0', '', '', 'free', 4.5, 4.6, 13.65, 79.42, 'Kapila Theertham Road, Tirupati, Andhra Pradesh', 'http://www.tirumala.org/TemplesAtTirupathi.aspx', 0.85, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'partial', 'Exists (TTD Kapileswara temple). Commonly: darshan 5 AM-12 PM & 4-8:30 PM; waterfall 6 AM-6 PM. File''s flat 6 AM-8 PM is a simplification. Official TTD listing exists; hours/prices not shown on the fetched page.', '2026-09-30'),
('100030', '1002', 'Chandragiri Fort', 'Chandragiri Fort', 'A 16th century fort palace of the Vijayanagara kings with a museum of Chola and Vijayanagara bronzes.', '2 hours', 'Evening', 'The light and sound show in the evening is worth staying for.', '', 'Andhra Pradesh', '0', '1', '', '6:00 PM', 'Fort Rs 20/adult, free for children under 15 (foreigners ~Rs 250); light & sound show Rs 30-50 general.', 4.3, 4.2, 13.58, 79.31, 'Chandragiri, Tirupati, Andhra Pradesh', NULL, 0.78, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'verified', 'Exists. File said 8 AM open; aptourism says 9 AM. [Price source: Wanderlog, indiamap.com, Justdial] Official website dead as of 2026-09-30; URL removed. APTDC page returned HTTP 500 on this pass; hours/prices corroborated via multiple third-party sources.', '2026-09-30'),
('100031', '1002', 'Sri Venkateswara Museum', 'TTD Museum Tirupati', 'Museum of temple art, old coins, musical instruments and ritual objects from the Tirumala tradition.', '1 hour', 'Morning', 'Good for understanding the temple history before climbing to Tirumala.', '', 'Andhra Pradesh', '0', '0', '', '', 'Entry reported free by multiple 2026 sources; an older TTD listing cited Rs 100 - unconfirmed.', 4.2, 4.1, 13.64, 79.42, 'Tirupati, Andhra Pradesh', '', 0.72, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'partial', 'Exists at Tirumala opp. Vaikuntham Queue Complex (official name Sri Venkateswara Dhyana Jnana Mandiram) - file coords point to Tirupati town, ~9 km off. Renovated/reopened Sep 2026; official TTD museum site lists 8 AM-8 PM daily, Rs.100 entry. File''s ''10 AM-5 PM, closed Monday'' looks outdated; confirm before publishing. [Price source: tirumalatirupati.in, velpu.com, Wanderlog] Renovated/reopened ~Sep 2026; earlier TTD Rs 100 entry claim now contradicted by ''free'' listings.', '2026-09-30'),
('100032', '1002', 'Govindaraja Temple', 'Govindaraja Temple', 'A large ancient Vishnu temple in the heart of Tirupati town with a towering gopuram.', '1 hour', 'Morning', 'Easy to combine with a walk through the old town markets.', '', 'Andhra Pradesh', '0', '0', '', '', 'Free entry; sevas Rs 10/person each (Suprabhatam, Thomala, Sahasranamarchana, Archananantara, Ekantha); special entrance Rs 5, quick darshan Rs 20.', 4.6, 4.5, 13.63, 79.42, 'Tirupati, Andhra Pradesh', 'https://www.tirumala.org/TemplesAtTirupathi.aspx', 0.86, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'verified', 'Exists (TTD). 5 AM-9 PM daily matches file; midday ritual breaks. [Price source: tirumala.org (official)] Seva bookings via ttdevasthanams.ap.gov.in.', '2026-09-30'),
('100033', '1002', 'Kodandarama Temple', 'Kodandarama Temple Tirupati', 'A serene Rama temple on the banks of the Swarnamukhi river, less crowded than the big shrines.', '1 hour', 'Morning', 'Peaceful at sunrise before the town wakes up.', '', 'Andhra Pradesh', '1', '0', '6:00 AM', '', 'Free darshan; no published ticket.', 4.3, 4.2, 13.62, 79.41, 'Tirupati, Andhra Pradesh', '', 0.76, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'partial', 'Exists (Sri Kodandarama Swamy Temple, Korlagunta, TTD). NOT on Swarnamukhi riverbanks - remove river claim from description (riverbank Kodandarama temple is Vontimitta, ~120 km away). Commonly 5 AM-9 PM. [Price source: gokshetra.com, tirumalatirupationline.com] TTD-run 10th-century temple at Korlagunta; sevas at counter/online.', '2026-09-30'),
('100034', '1002', 'ISKCON Temple Tirupati', 'ISKCON Tirupati', 'A modern Krishna temple complex with gardens, cultural programs and a calm prayer hall.', '1-2 hours', 'Evening', 'Attend the evening aarti for the full experience.', '', 'Andhra Pradesh', '0', '0', '', '', 'Entry free for all.', 4.4, 4.3, 13.61, 79.4, 'Tirupati, Andhra Pradesh', '', 0.79, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'partial', 'Exists. Commonly: morning 4:15 AM-1 PM, evening 4:30-8:30 PM; general darshan 7:30 AM-8:30 PM. File''s 7 AM-8:30 PM plausible but unverified from official source. [Price source: gokshetra.com, vishnu-travels.com] ISKCON Radha Govinda temple.', '2026-09-30'),
('100035', '1002', 'Silathoranam', 'Natural Rock Arch', 'A rare natural stone arch in the Tirumala hills, linked to the legend of the temple deity.', '30 minutes', 'Morning', 'It is on the Tirumala ghat road; stop on the way up or down.', '', 'Andhra Pradesh', '0', '0', '', '', 'Free or nominal gate charge; not officially published as ticketed.', 4.3, 4.4, 13.69, 79.36, 'Tirumala Hills, Tirupati, Andhra Pradesh', '', 0.77, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'partial', 'Exists (natural arch on Tirumala ghat road). Daylight access; no published hours. [Price source: prayanamam.com (2026, citing Incredible India)] Natural rock arch ~1 km north of Tirumala temple; daylight access.', '2026-09-30'),
('100036', '1002', 'Deer Park, Tirumala', 'Tirupati Deer Park', 'A green park with spotted deer and peacocks, popular with families in the evening.', '1 hour', 'Evening', 'Carry binoculars in winter for the birdlife.', '', 'Andhra Pradesh', '0', '0', '', '', 'No separate entry fee reported.', 3.9, 4.0, 13.66, 79.43, 'Tirupati, Andhra Pradesh', '', 0.65, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'renamed', 'Exists but at Tirumala (near SV Zoological Park, ~14 km from town), not Tirupati town as file coords suggest; spotted deer, peacocks, rabbits. Commonly 10 AM-5 PM, free - unverified from official source. [Price source: triphobo.com, airial.travel] On Alipiri footpath route; spotted deer, peacocks, rabbits.', '2026-09-30'),
('100037', '1002', 'Talakona Waterfalls', 'Talakona Falls', 'A 270-foot waterfall deep in the Seshachalam forest, reached by a scenic forest trek.', '3-4 hours', 'Morning', 'Go between October and February when the flow is strong and the forest is green.', '', 'Andhra Pradesh', '0', '0', '', '', 'Entry ~Rs 30-50/person (Indian), vehicle/camera charges extra - checkpoint rates, not officially published.', 4.5, 4.6, 13.81, 79.21, 'Talakona, Chittoor, Andhra Pradesh', '', 0.84, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'partial', 'Exists. Daylight hours only (~6 AM-7:30 PM), falls entry closes ~4 PM; forest dept controlled; no official published hours. [Price source: srivyasapooja.in, prayanamam.com, Wanderlog review] AP Forest Dept controls access; confirm at checkpoint, may close in heavy rain.', '2026-09-30'),
('100038', '1002', 'Sri Venkateswara National Park', 'SV National Park', 'A biosphere reserve in the Seshachalam hills with waterfalls, endemic plants and wildlife safaris.', 'Half day', 'Morning', 'Book the forest department safari in advance in season.', 'Safari booking recommended', 'Andhra Pradesh', '0', '0', '', '', 'Safari ~Rs 30, cycling ~Rs 25 (per velpu.com).', 4.1, 4.2, 13.7, 79.3, 'Seshachalam Hills, Tirupati, Andhra Pradesh', '', 0.71, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'partial', 'Exists (353 sq km biosphere reserve). Third-party listings: 8:30 AM-5:30 PM, Tuesday holiday, safari ~Rs.30; forest dept - confirm locally. [Price source: velpu.com] Biosphere reserve; third-party data only, confirm locally.', '2026-09-30'),
('100039', '1002', 'Regional Science Centre Tirupati', 'Science Centre Tirupati', 'An interactive science museum with a planetarium, fun for kids and school groups.', '2 hours', 'Morning', 'Check planetarium show timings at the entrance.', '', 'Andhra Pradesh', '0', '0', '', '', 'Science Centre Rs 45 general / Rs 20 organised student group / Rs 5 govt-school group; 3D film Rs 40/15/5; planetarium Rs 50/20/10; science shows Rs 20/10/5; free for uniformed personnel, physicall...', 4.1, 4.0, 13.63, 79.41, 'Tirupati, Andhra Pradesh', 'http://www.rsctirupati.org.in/', 0.7, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'verified', 'Exists (NCSM). File wrongly said closed Monday - it is open Mon-Sat. [Price source: rsctirupati.org.in (official)] NCSM centre, Alipiri-Zoo Park Rd.', '2026-09-30'),
('100040', '1002', 'Kanipakam Vinayaka Temple', 'Kanipakam Temple', 'A famous self-manifested Ganesha temple near Chittoor, known for resolving disputes.', '2 hours', 'Morning', 'It is a 75-minute drive; start early to return by afternoon.', '', 'Andhra Pradesh', '0', '0', '', '', 'No prices published on homepage; seva/ticket booking behind sign-in on official site.', 4.7, 4.6, 13.43, 79.14, 'Kanipakam, Chittoor, Andhra Pradesh', 'https://srikanipakadevasthanam.org/', 0.88, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'partial', 'Exists (Sri Varasiddhi Vinayaka). Commonly opens 4-4:30 AM, darshan till 9:30 PM; file''s 5 AM-9 PM plausible but unverified from official site. [Price source: srikanipakadevasthanam.org (official)] AP Endowments-run; has accommodation and donation services online.', '2026-09-30'),
('100041', '1002', 'Srikalahasti Temple', 'Srikalahasti', 'An ancient Shiva temple famous for Rahu-Ketu pujas, 36 km from Tirupati on the riverbank.', '2-3 hours', 'Morning', 'Rahu Ketu puja tickets are bought at the counter; mornings are less crowded.', '', 'Andhra Pradesh', '0', '0', '', '', 'Free temple entry; Rahu Ketu pooja tiers Rs 500 / 750 / 1,500 / 2,500 / 5,000.', 4.8, 4.7, 13.76, 79.7, 'Srikalahasti, Tirupati, Andhra Pradesh', NULL, 0.92, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'partial', 'Exists (Sri Kalahasteeswara, Pancha Bhoota Vayu sthalam). Commonly 5:30 AM-9 PM. Rahu Ketu pooja tickets are counter-only, same-day - no online booking; beware scam booking sites. [Price source: templetimings.in, srivyasapooja.in, gokshetra.com] Official website dead as of 2026-09-30; URL removed. Official site failed with upstream 429; book poojas only via aptemples.ap.gov.in or temple counter - beware scam booking sites.', '2026-09-30'),
('100042', '1002', 'Horsley Hills', 'Horsley Hills', 'A breezy hill station getaway with valleys, eucalyptus forests and adventure activities.', 'Full day', 'Morning', 'Carry a jacket; evenings are cool even in summer.', '', 'Andhra Pradesh', '1', '1', '6:00 AM', '6:00 PM', 'Entry ~INR 10/person (per MakeMyTrip).', 4.4, 4.5, 13.66, 78.4, 'Horsley Hills, Chittoor, Andhra Pradesh', '', 0.82, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'partial', 'Exists (well-known hill station, ~110 km from Tirupati). Fixed daily hours n/a - it''s a hill station, viewpoints are daytime. [Price source: makemytrip.com] Hill station; zoo inside Vana Vihara Park reportedly 8 AM-6:30 PM.', '2026-09-30'),
('100043', '1002', 'Alipiri Mettu', 'Alipiri Footpath', 'The ancient 3,550-step stone footpath pilgrims climb from Tirupati town to Tirumala.', '3-4 hours', 'Early Morning', 'Start before 5 AM with water; luggage counters exist at the base.', '', 'Andhra Pradesh', '1', '0', '5:00 AM', '', 'Free; free Divya Darshan tokens.', 4.6, 4.7, 13.65, 79.43, 'Alipiri, Tirupati, Andhra Pradesh', '', 0.87, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'partial', 'Exists (3,550 steps, ~11 km). Commonly opens 4-5 AM, closes 9-10 PM (supervised groups after 2 PM) - file''s 6 PM close too early. [Price source: prayanamam.com, tirupatitirumalainfo.com] 3,550 steps / ~11 km; free Divya Darshan tokens at start.', '2026-09-30'),
('100044', '1002', 'Srivari Mettu', 'Srivari Mettu', 'A shorter 2,388-step footpath to Tirumala through forest, preferred by many pilgrims.', '2-3 hours', 'Early Morning', 'Opens at 6 AM; the forest stretch is beautiful at dawn.', '', 'Andhra Pradesh', '1', '0', '6:00 AM', '', 'Free; free Divya Darshan tokens.', 4.5, 4.6, 13.6, 79.4, 'Srivari Mettu, Tirupati, Andhra Pradesh', '', 0.83, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'partial', 'Exists (2,388 steps, ~2 km). Commonly 6 AM-5:30/6 PM daily, no night trekking. Trailhead at Srinivasa Mangapuram ~12 km NW of Tirupati; file coords are town. [Price source: prayanamam.com, vidzone.in] 2,388 steps / ~2 km; starts at Srinivasa Mangapuram.', '2026-09-30'),
('100045', '1002', 'Kalyani Dam', 'Kalyani Dam', 'A scenic reservoir in the hills behind Tirupati, popular for quiet picnics and birdwatching.', '1-2 hours', 'Evening', 'Monsoon fills it best; carry snacks as shops are few.', '', 'Andhra Pradesh', '0', '1', '', '6:00 PM', 'Free entry.', 4.0, 4.1, 13.7, 79.45, 'Kalyani Dam, Tirupati, Andhra Pradesh', '', 0.68, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'partial', 'Exists (built 1977 across Swarnamukhi, ~18-20 km via Rangampet; drinking water source). Free entry; ~9 AM-5 PM per one source, daylight visits. Best post-monsoon. [Price source: tirumalatirupationline.com, lakevalleyresort.in] Check gate security on the day; may close in certain seasons.', '2026-09-30'),
('100046', '1002', 'TTD Gardens', 'TTD Ornamental Gardens', 'Landscaped gardens maintained by the temple trust with fountains and flower beds near Tirupati.', '1 hour', 'Evening', 'A calm evening stroll after temple visits.', '', 'Andhra Pradesh', '0', '0', '', '', 'No entrance fee (per MakeMyTrip).', 4.0, 4.0, 13.64, 79.42, 'Tirupati, Andhra Pradesh', '', 0.66, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'partial', 'Exists (TTD Dept of Gardens, 460 acres across Tirupati/Tirumala - working flower gardens, not a ticketed attraction). No published visitor hours; entry free per travel sources. [Price source: makemytrip.com] TTD Dept of Gardens working gardens (460 acres); no published visitor hours.', '2026-09-30'),
('100047', '1002', 'Hotel Bhimas, Tirupati', 'Bhimas Grand Restaurant', 'Popular pure-veg restaurant near the temple serving Andhra meals and tiffins.', '1 hour', 'Afternoon', 'The meals are filling; tiffins are best in the morning.', '', 'Andhra Pradesh', '0', '0', '', '', 'No Bhimas Grand tariff published; sister property ''Hotel Bhimas'' (42 G Car St) ~Rs 2,500+ via ClearTrip (Bhimas Deluxe listing).', 4.3, 4.2, 13.628, 79.419, 'Tirupati, Andhra Pradesh', NULL, 0.76, '2026-09-30 12:00:00', NULL, 'restaurant', 'South Indian', 'mid', 'veg', 'own', '2026-09-30 12:00:00', 'renamed', 'Bhimas group is real (Hotel Bhimas + Bhimas Paradise per hotelbhimas.com) but a ''Bhimas Grand'' property in Tirupati was not specifically confirmed - could be confused with Bhimas Deluxe Hotel. Hours unverified. [Price source: cleartrip.com, tripadvisor] Official website dead as of 2026-09-30; URL removed. hotelbhimas.com unresolvable (DNS fail); ''Bhimas Grand'' property name not specifically confirmed - verify before listing. Renamed: "Bhimas Grand" never confirmed; only Hotel Bhimas / Bhimas Paradise / Bhimas Deluxe found in Tirupati.', '2026-09-30'),
('100048', '1002', 'Bhimas Paradise', 'Bhimas Paradise Restaurant', 'Well known veg hotel restaurant serving Andhra and North Indian dishes.', '1 hour', 'Evening', 'Try the pulihora and gutti vankaya kura.', '', 'Andhra Pradesh', '0', '0', '', '', 'Rooms from ~Rs 3,743/night (superior); check-in/out 12:00 PM.', 4.2, 4.1, 13.629, 79.418, 'Tirupati, Andhra Pradesh', NULL, 0.74, '2026-09-30 12:00:00', NULL, 'restaurant', 'Andhra', 'mid', 'veg', 'own', '2026-09-30 12:00:00', 'partial', 'Exists (33-37 Renigunta Rd, Bhimas Paradise Hotel). magicpin lists 7 AM-10:30 PM daily - unverified from official source. [Price source: kayak.co.in] Official website dead as of 2026-09-30; URL removed. hotelbhimas.com unresolvable; listed at 33-37 Renigunta Rd.', '2026-09-30'),
('100049', '1002', 'Haritha Restaurant APTDC Tirupati', 'Haritha Tirupati', 'Government-run restaurant with dependable Andhra meals at budget prices.', '1 hour', 'Afternoon', 'Good fallback when temple-area restaurants are packed.', '', 'Andhra Pradesh', '0', '0', '', '', 'paid', 4.0, 4.0, 13.63, 79.42, 'Tirupati, Andhra Pradesh', '', 0.69, '2026-09-30 12:00:00', NULL, 'restaurant', 'Andhra', 'budget', 'veg-options', 'own', '2026-09-30 12:00:00', 'unverified', 'Haritha is APTDC''s hotel brand and its Tirupati property exists; restaurant hours unverified. No Tirupati-specific Haritha restaurant hours/prices found; other Haritha units (Palamaner) list Rs 400-1,400/person - not the Tirupati unit. No Tirupati-specific APTDC Haritha listing found (only Palamaner/Horsley/Amaravathi units).', '2026-09-30'),
('100050', '1002', 'Minerva Grand Tirupati', 'Minerva Grand', 'Hotel restaurant serving multi-cuisine with strong South Indian breakfast options.', '1 hour', 'Morning', 'The breakfast buffet suits families starting early for darshan.', '', 'Andhra Pradesh', '0', '0', '', '', 'Rooms from ~Rs 2,256/night (hoteldekho); official tariff card on minervahotels.in is a 2023 PDF (appears to be the Secunderabad property); check-in/out 12 PM.', 4.1, 4.0, 13.627, 79.421, 'Tirupati, Andhra Pradesh', '', 0.71, '2026-09-30 12:00:00', NULL, 'restaurant', 'Multi-cuisine', 'mid', 'veg-options', 'own', '2026-09-30 12:00:00', 'partial', 'Minerva Grand is a real Minerva Group hotel in Tirupati; restaurant hours unverified. [Price source: hoteldekho.com, travelweekly.com] 4-star, 69 rooms, Renigunta Rd; possibly now under Fortune ITC brand.', '2026-09-30'),
('100051', '1002', 'Udupi Sri Krishna Bhavan', 'Udupi Krishna Bhavan', 'Classic Udupi-style pure veg tiffin room popular for breakfast and filter coffee.', '45 minutes', 'Morning', 'Reach before 9 AM for fresh pongal and vada.', '', 'Andhra Pradesh', '0', '0', '', '', 'paid', 4.2, 4.1, 13.631, 79.417, 'Tirupati, Andhra Pradesh', '', 0.72, '2026-09-30 12:00:00', NULL, 'restaurant', 'South Indian', 'budget', 'veg', 'own', '2026-09-30 12:00:00', 'unverified', 'Plausible generic Udupi tiffin-room name; no specific listing confirmed. Hours unverified. No Tirupati-specific listing found; all matches are restaurants in other cities (Bengaluru, Gingee). No Tirupati-specific listing found; matches are in other cities.', '2026-09-30'),
('100052', '1002', 'Gokul Pure Veg', 'Gokul Restaurant', 'Simple pure vegetarian meals place near the railway station, quick and cheap.', '45 minutes', 'Afternoon', 'Ideal for a quick meal between trains.', '', 'Andhra Pradesh', '0', '0', '', '', 'paid', 3.9, 3.9, 13.626, 79.422, 'Tirupati, Andhra Pradesh', '', 0.64, '2026-09-30 12:00:00', NULL, 'restaurant', 'South Indian', 'budget', 'veg', 'own', '2026-09-30 12:00:00', 'unverified', 'Plausible generic veg meals place; no specific listing confirmed. Hours unverified. No Tirupati-specific listing found; matches are in Udupi, Karnataka. No Tirupati-specific listing found; matches are in other cities.', '2026-09-30');

