-- ---- PLACES: Araku Valley ----
INSERT INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score, created_at, google_place_id, category, cuisine, price_band, veg_flag, source, updated_at, verification_status, verification_notes, verified_at) VALUES
('100105', '1005', 'Borra Caves', 'Borra Caves', 'Million-year-old limestone caves with stalactites, stalagmites and a natural Shiva lingam deep inside.', '2 hours', 'Morning', 'Go before 10 AM to avoid the crowds that arrive with the tour buses.', '', 'Andhra Pradesh', '0', '0', '', '', 'Adult Rs 60, Child Rs 45, phone camera Rs 25, digital/still camera Rs 100, video camera Rs 100 (MakeMyTrip)', 4.8, 4.7, 18.28, 83.04, 'Borra Caves, Alluri Sitharama Raju, Andhra Pradesh', NULL, 0.92, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'verified', 'Exists. Hours 10 AM-5 PM daily match file. Ticket counter closed 1-2 PM. Entry Rs 60 adult / Rs 45 child. [Price source: web search (MakeMyTrip)] Official website dead as of 2026-09-30; URL removed. Listed official website borracaves.in failed to resolve in fetch check (dead as of 2026-09-30); hours and prices taken from web search instead.', '2026-09-30'),
('100106', '1005', 'Araku Tribal Museum', 'Tribal Museum Araku', 'Museum showcasing the art, crafts and lifestyle of the Eastern Ghats tribal communities.', '1-2 hours', 'Morning', 'The live craft demonstrations are the best part; ask at the counter.', '', 'Andhra Pradesh', '0', '0', '', '', 'Entry Rs 40 adult / Rs 20 child, camera Rs 50, boating Rs 20 (MakeMyTrip)', 4.3, 4.2, 18.33, 82.87, 'Araku Valley, Andhra Pradesh', '', 0.77, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'partial', 'Exists (opened 1996 by APTDC). Hours conflict across sources: file says closed Monday 10-5; eindiatourism says 9 AM-6 PM daily; MMT says 10 AM-5 PM. No authoritative source confirms Monday closure; no official website found. [Price source: web search (MakeMyTrip)] No official website; data from web search.', '2026-09-30'),
('100107', '1005', 'Araku Coffee Plantations', 'Coffee Estates Araku', 'Walk the famous Araku coffee estates that put Indian specialty coffee on the world map.', '2 hours', 'Morning', 'Book an estate walk; tasting fresh brews at source is the highlight.', 'Estate walk booking recommended', 'Andhra Pradesh', '0', '0', '', '', 'Entry Free (trawell.in)', 4.5, 4.6, 18.32, 82.86, 'Araku Valley, Andhra Pradesh', '', 0.85, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'partial', 'Generic estate entry; no single official site or published hours for Araku coffee estates as an attraction. [Price source: web search (trawell.in)] No official website; data from web search.', '2026-09-30'),
('100108', '1005', 'Katiki Waterfalls', 'Katiki Falls', 'Reached by a 4 km trek from Borra; a powerful monsoon waterfall in the forest.', '3-4 hours', 'Morning', 'Monsoon to early winter only; the trek is slippery after rain.', '', 'Andhra Pradesh', '0', '0', '', '', 'No entry fee; jeep Rs 200-300/person (thedilli.in)', 4.5, 4.6, 18.25, 83.0, 'Katiki, Alluri Sitharama Raju, Andhra Pradesh', '', 0.84, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'verified', 'Exists, ~7 km from Borra Caves. Free entry; jeep ~Rs 200/person to trek start. [Price source: web search (thedilli.in)] No official website; data from web search.', '2026-09-30'),
('100109', '1005', 'Padmapuram Botanical Gardens', 'Padmapuram Gardens', 'Botanical gardens with tree-top huts, toy train and exotic plants.', '1-2 hours', 'Morning', 'The tree-top hut stay needs advance booking through APTDC.', 'Tree-top hut booking required', 'Andhra Pradesh', '0', '0', '', '', 'Entry Rs 10-60 varies by source (eindiatourism: Rs 50 adult/Rs 30 child; thrillophilia: Rs 10; tripadvisor review: Rs 60 adult/40 child); toy train Rs 10-60', 4.2, 4.1, 18.33, 82.88, 'Araku Valley, Andhra Pradesh', NULL, 0.73, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'verified', 'Exists. Entry ~Rs 60-100/adult per recent reviews; toy train and tree-top huts confirmed. [Price source: web search (eindiatourism, thrillophilia, tripadvisor)] Official website wrong page as of 2026-09-30; URL removed. padmapuramgardens.com loads but is a parked GoDaddy for-sale page ($249) - wrong page for the gardens; hours/prices from web search.', '2026-09-30'),
('100110', '1005', 'Araku Coffee Museum', 'Coffee Museum Araku', 'A museum tracing the journey of Araku coffee from tribal farms to global cafes.', '1 hour', 'Morning', 'The tasting counter at the end is worth the entry fee alone.', '', 'Andhra Pradesh', '0', '0', '', '', 'Entry Rs 10 (trawell.in)', 4.1, 4.0, 18.325, 82.875, 'Araku Valley, Andhra Pradesh', '', 0.7, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'partial', 'Exists (Prakash Rao''s coffee museum, roots in 1950s, museum est. 2006). Hours conflict: trawell 8 AM-8 PM, meta.ai listing 9 AM-8 PM, file 10 AM-5 PM. No authoritative source; no official site. [Price source: web search (trawell.in)] No official website; data from web search.', '2026-09-30'),
('100111', '1005', 'Galikonda Viewpoint', 'Galikonda', 'One of the highest points on the Vizag-Araku road with sweeping valley views.', '30 minutes', 'Evening', 'Stop here on the drive up; the light is best late afternoon.', '', 'Andhra Pradesh', '0', '1', '', '6:00 PM', 'Entry Free (trawell.in)', 4.4, 4.5, 18.29, 82.92, 'Galikonda, Alluri Sitharama Raju, Andhra Pradesh', '', 0.81, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'partial', 'Real roadside viewpoint on Vizag-Araku road (~4300 ft, one of highest points in region). No published hours; open viewpoint. [Price source: web search (trawell.in)] No official website; data from web search.', '2026-09-30'),
('100112', '1005', 'Ananthagiri Hills', 'Ananthagiri', 'Coffee country hills with waterfalls, viewpoints and the start of the Araku rail journey.', 'Half day', 'Morning', 'The coffee plantations here are older and quieter than Araku town.', '', 'Andhra Pradesh', '1', '0', '6:00 AM', '', 'free', 4.4, 4.5, 18.23, 82.98, 'Ananthagiri, Alluri Sitharama Raju, Andhra Pradesh', '', 0.82, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'partial', 'Real hill region between Vizag and Araku. No fixed attraction hours. No dedicated listing found; same Ananthagiri area as the coffee plantations (100107). Ignore ''Ananthagiri'' results from Telangana (Vikarabad) - different place.', '2026-09-30'),
('100113', '1005', 'Chaparai Waterfalls', 'Chaparai Falls', 'A wide cascade over smooth rock slabs, popular for picnics in the rainy season.', '2 hours', 'Morning', 'The rocks are slippery; wear grip footwear.', '', 'Andhra Pradesh', '0', '0', '', '', 'No entry fee (MakeMyTrip); nominal Rs 10-30 per other sources', 4.3, 4.4, 18.35, 82.8, 'Chaparai, Alluri Sitharama Raju, Andhra Pradesh', '', 0.79, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'merged', 'Merged duplicate row 100114 (Dumbriguda Waterfalls = Chaparai Waterfalls). Exists near Dumbriguda, ~13 km from Araku. Chaparai IS Dumbriguda Falls (same waterfall as 100114 - duplicate row). Entry ~Rs 20; AI guides say 6 AM-6 PM, not authoritative. [Price source: web search (MakeMyTrip)] No official website; data from web search.', '2026-09-30'),
('100115', '1005', 'Matsyagundam', 'Matsyagundam Fish Pool', 'A sacred forest pool where mahseer fish are protected and fed by visitors.', '1 hour', 'Morning', 'Buy the fish feed sold at the entrance; the fish swarm up.', '', 'Andhra Pradesh', '0', '0', '', '', 'No Entry Fee (bestbus.in)', 4.0, 4.1, 18.17, 82.62, 'Matsyagundam, Alluri Sitharama Raju, Andhra Pradesh', '', 0.68, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'partial', 'Exists: sacred fish pool on Machkund river near Matham village, 15 km from Paderu, 35 km from Araku. File coords (18.40, 82.90) point near Araku town, ~35 km from the real site near Paderu (~18.17, 82.62). Coords need fixing. [Price source: web search (bestbus.in)] No official website; data from web search.', '2026-09-30'),
('100116', '1005', 'Tyda Park Jungle Bells', 'Tyda Nature Camp', 'APTDC nature camp with treehouses, zipline and forest trails between Vizag and Araku.', 'Half day', 'Morning', 'The zipline and burma bridge need advance slot booking.', 'Activity slots booking recommended', 'Andhra Pradesh', '0', '0', '', '', 'No entry fee listed (velpu.com); Tyda Jungle Resort stay: AC Rs 1,600-2,500 / non-AC Rs 1,200 (APTDC rate doc via scribd); LBB: stay options under INR 2,000', 4.2, 4.3, 18.25, 83.05, 'Tyda, Alluri Sitharama Raju, Andhra Pradesh', '', 0.76, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'mid', 'na', 'own', '2026-09-30 12:00:00', 'partial', 'Exists: APTDC Jungle Bells Nature Camp at Tyda, 75 km from Vizag. Bookable via APTDC; no published day-visitor hours. No official URL found in search. [Price source: web search (velpu.com, scribd APTDC tariff)] APTDC property (tripadvisor reviews confirm rooms owned by APTDC, bookable online); no own website.', '2026-09-30'),
('100117', '1005', 'Lambasingi', 'Lambasingi', 'The Kashmir of Andhra; the only place in South India that sees near-zero winter temperatures.', 'Full day', 'Morning', 'Visit December to January for the famous misty mornings and frost.', '', 'Andhra Pradesh', '1', '0', '6:00 AM', '', 'No entry ticket - it is a village', 4.5, 4.6, 17.83, 82.48, 'Lambasingi, Alluri Sitharama Raju, Andhra Pradesh', '', 0.86, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'partial', 'Exists (Kashmir of Andhra, winter frost). Distant day-trip: ~90-92 km / 2.5-3 hrs from Araku, not in Araku. No fixed hours. [Price source: web search] No official website; village, not a ticketed attraction.', '2026-09-30'),
('100118', '1005', 'Kothapalli Waterfalls', 'Kothapalli Falls', 'A tall seasonal waterfall in the forest near Gangaraju Madugula.', '2 hours', 'Morning', 'Monsoon season only; check flow before the drive.', '', 'Andhra Pradesh', '0', '0', '', '', 'Free (xploreall) / Rs 60 per person (vizagtourism.org.in) / INR 10 per person (hellovizag.in) - sources disagree', 4.0, 4.1, 17.9904, 82.479, 'Kothapalli, Alluri Sitharama Raju, Andhra Pradesh', '', 0.67, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'partial', 'Exists (Wikipedia: Kothapally Waterfalls, Gangaraju Madugula). File coords (18.20, 82.95) are ~55 km off; real coords ~17.9904, 82.4790, between Chintapalli and Paderu. Distant day-trip from Araku (~100 km), nearer Lambasingi. [Price source: web search (xploreall, vizagtourism.org.in, hellovizag.in)] No official website; price sources conflict.', '2026-09-30'),
('100119', '1005', 'Sangda Waterfalls', 'Sangda Falls', 'A lesser-known cascade in the Araku hills, good for solitude seekers.', '1-2 hours', 'Morning', 'A local guide helps; the trail is unmarked.', '', 'Andhra Pradesh', '0', '0', '', '', 'free', 4.0, 4.1, 18.28, 82.89, 'Sangda, Alluri Sitharama Raju, Andhra Pradesh', '', 0.66, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'partial', 'Exists near Sangda village, ~20 km from Araku. Sources disagree (thrillophilia 24/7 vs tripxl 6 AM-6 PM); no authoritative hours. No official website; no price info found in search.', '2026-09-30'),
('100120', '1005', 'Araku Valley Viewpoint', 'Valley Viewpoint Araku', 'Panoramic valley viewpoint near the town centre with coffee estate views.', '30 minutes', 'Evening', 'Sunset here with valley mist is the classic Araku photo.', '', 'Andhra Pradesh', '0', '1', '', '6:00 PM', 'Ambiguous - Madagada Sunrise Point: Entry Rs 60 per car (trawell.in)', 4.3, 4.4, 18.3273, 82.8741, 'Araku Valley, Andhra Pradesh', '', 0.78, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'partial', 'Generic entry for Araku town viewpoint; not a formally named attraction. Coords = Araku town center. [Price source: web search (trawell.in)] Ambiguous listing; search returned Madagada Sunrise Point as the likely match, not confirmed as the same place.', '2026-09-30'),
('100121', '1005', 'Rana Jilleda Waterfalls', 'Rana Jilleda Falls', 'A forest waterfall off the Araku trail, rarely crowded.', '1-2 hours', 'Morning', 'Best combined with the Chaparai falls trip.', '', 'Andhra Pradesh', '0', '0', '', '', 'Free / No Entry Fee (velpu.com, bestbus.in)', 4.0, 4.1, 18.35, 82.95, 'Rana Jilleda, Alluri Sitharama Raju, Andhra Pradesh', '', 0.65, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'partial', 'Exists, also called Araku Waterfalls; ~3-5 km from Padmapuram Gardens, 60 ft falls. No authoritative hours. [Price source: web search (velpu.com, bestbus.in)] No official website; hours vary by source.', '2026-09-30'),
('100122', '1005', 'Duduma Waterfalls', 'Duduma Falls', 'A spectacular 175 m waterfall on the Odisha border, a full day trip from Araku.', 'Full day', 'Morning', 'Carry food and water; facilities are minimal at the site.', '', 'Andhra Pradesh', '0', '0', '', '', 'No Entry Fee (bestbus.in)', 4.3, 4.4, 18.52, 82.67, 'Duduma, Odisha border, Andhra Pradesh', '', 0.8, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'partial', 'Exists but in ODISHA (Koraput dist), on AP-Odisha border, ~70-82 km from Araku. Full day trip, Machkund river, ~157-175 m. No reliable published hours. [Price source: web search (bestbus.in)] No official website; data from web search.', '2026-09-30'),
('100123', '1005', 'Paderu Viewpoint', 'Paderu', 'A tribal town viewpoint with valley panoramas on the Araku-Munchingput road.', '1 hour', 'Evening', 'The weekly tribal market here is worth timing your visit for.', '', 'Andhra Pradesh', '0', '1', '', '6:00 PM', 'Free entry (plantrip itinerary)', 4.1, 4.2, 18.08, 82.66, 'Paderu, Alluri Sitharama Raju, Andhra Pradesh', '', 0.69, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'partial', 'Generic entry; Paderu is a real tribal town ~70 km from Araku. No fixed hours. [Price source: web search (plantrip.io)] Roadside viewpoint in Paderu area; no fixed timings published.', '2026-09-30'),
('100124', '1005', 'Vizag Araku Railway Journey', 'Araku Rail Journey', 'The scenic 58-tunnel railway journey through the Eastern Ghats; half the Araku experience.', '4 hours', 'Morning', 'Book the Vistadome coach for glass-roof valley views.', 'Vistadome booking required', 'Andhra Pradesh', '0', '0', '', '', '2S fare INR 100, SL INR 180 (ixigo); Vistadome coach Rs 700-1,200/person (vistadometrip.com)', 4.8, 4.9, 18.33, 82.87, 'Araku Railway Station, Andhra Pradesh', '', 0.93, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'verified', 'Exists. File hours 6:45 AM-11:00 AM match the morning Vistadome/Kirandul passenger (VSKP dep ~6:45-6:50 AM, Araku arr ~10:55-11:00 AM). Return departs Araku ~3:45 PM. Timings subject to railway revisions; book via IRCTC. [Price source: web search (ixigo, vistadometrip.com)] Booking via IRCTC per verification notes; no own website.', '2026-09-30'),
('100125', '1005', 'Haritha Valley Resort Restaurant', 'Haritha Araku', 'APTDC resort restaurant serving Andhra meals with valley views.', '1 hour', 'Afternoon', 'The outdoor seating overlooks the coffee estates.', '', 'Andhra Pradesh', '0', '0', '', '', 'paid', 4.0, 4.0, 18.328, 82.872, 'Haritha Valley Resort, Araku, Andhra Pradesh', '', 0.68, '2026-09-30 12:00:00', NULL, 'restaurant', 'Andhra', 'budget', 'veg-options', 'own', '2026-09-30 12:00:00', 'partial', 'Exists: restaurant inside APTDC Haritha Valley Resort Araku (Araku Haritha Hill Resort Mayuri). No published restaurant hours. No official website; no menu prices found in search.', '2026-09-30'),
('100126', '1005', 'Araku Coffee House', 'Araku Coffee House', 'Cafe brewing single-estate Araku coffee with light snacks.', '1 hour', 'Morning', 'Try the pour-over made from the estate beans.', '', 'Andhra Pradesh', '0', '0', '', '', 'Price range up to INR 950 per person (restaurant-guru)', 4.2, 4.1, 18.327, 82.876, 'Araku Valley, Andhra Pradesh', '', 0.71, '2026-09-30 12:00:00', NULL, 'restaurant', 'Cafe', 'budget', 'veg', 'own', '2026-09-30 12:00:00', 'verified', 'Exists: historic cafe founded 1950s by Prakash Rao, attached to Coffee Museum near bus stand/Tribal Museum (livemint). File hours 8 AM-8 PM daily confirmed by restaurant-guru. [Price source: web search (restaurant-guru.in)] No official website; data from web search.', '2026-09-30'),
('100127', '1005', 'Araku Bamboo Chicken Stalls', 'Bamboo Chicken Stalls', 'Tribal street stalls cooking chicken inside bamboo over fire; the signature Araku food.', '1 hour', 'Evening', 'Eat it hot off the fire with the local chutney.', '', 'Andhra Pradesh', '0', '0', '', '', 'paid', 4.4, 4.3, 18.329, 82.871, 'Araku Valley, Andhra Pradesh', '', 0.79, '2026-09-30 12:00:00', NULL, 'restaurant', 'Tribal Street Food', 'budget', 'non-veg', 'own', '2026-09-30 12:00:00', 'partial', 'Generic street-food entry; bamboo chicken stalls are a real Araku phenomenon (also sold at Katiki trail). No fixed hours. No official website; hours from representative stall (Aadhivasi Bamboo Chicken, Araku Valley). Other stalls: Rukmani Araku Bamboo Chicken 9 AM-11 PM (justdial).', '2026-09-30'),
('100128', '1005', 'Jungle Bells Restaurant Tyda', 'Jungle Bells Tyda', 'APTDC camp restaurant serving meals to nature camp guests and visitors.', '1 hour', 'Afternoon', 'Call ahead; it primarily serves camp residents.', '', 'Andhra Pradesh', '0', '0', '', '', 'paid', 3.9, 3.9, 18.25, 83.05, 'Tyda, Alluri Sitharama Raju, Andhra Pradesh', '', 0.62, '2026-09-30 12:00:00', NULL, 'restaurant', 'Andhra', 'budget', 'veg-options', 'own', '2026-09-30 12:00:00', 'partial', 'Restaurant within APTDC Jungle Bells Nature Camp, Tyda. No published hours. No official website; hours approximate from a review.', '2026-09-30'),
('100129', '1005', 'Haritha Ananthagiri Restaurant', 'Haritha Ananthagiri', 'APTDC restaurant at the Ananthagiri resort with hill views.', '1 hour', 'Afternoon', 'Good lunch stop on the Vizag-Araku drive.', '', 'Andhra Pradesh', '0', '0', '', '', 'paid', 3.9, 3.9, 18.23, 82.98, 'Ananthagiri, Alluri Sitharama Raju, Andhra Pradesh', '', 0.63, '2026-09-30 12:00:00', NULL, 'restaurant', 'Andhra', 'budget', 'veg-options', 'own', '2026-09-30 12:00:00', 'partial', 'Exists: restaurant at APTDC Haritha Hill Resort, Ananthagiri (28 rooms, confirmed via APTDC tender doc). No published restaurant hours. No official website; matched to ''Haritha Restaurant, Ananthagiri'' listing.', '2026-09-30'),
('100130', '1005', 'Haritha Lambasingi Restaurant', 'Haritha Lambasingi', 'APTDC restaurant serving hot Andhra meals in the chilly hill town.', '1 hour', 'Afternoon', 'Hot meals taste best here in the December chill.', '', 'Andhra Pradesh', '0', '0', '', '', 'paid', 3.9, 4.0, 17.83, 82.48, 'Lambasingi, Alluri Sitharama Raju, Andhra Pradesh', '', 0.64, '2026-09-30 12:00:00', NULL, 'restaurant', 'Andhra', 'budget', 'veg-options', 'own', '2026-09-30 12:00:00', 'partial', 'Exists: restaurant at APTDC Lambasingi Haritha Resort (confirmed via bestbus, APTDC authorized agent). No published restaurant hours. ~90 km from Araku. No official website; no published hours or prices found in search.', '2026-09-30');

