INSERT INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score, created_at, google_place_id, category, cuisine, price_band, veg_flag, source, updated_at, verification_status, verification_notes, verified_at) VALUES
('100131', '1006', 'Mallikarjuna Jyotirlinga Temple', 'Srisailam Temple', 'One of the twelve Jyotirlingas and a Shakti Peetha, set above the Krishna gorge in the Nallamala forest.', '3-4 hours', 'Morning', 'Book darshan slots online in festival season; the temple town gets very crowded.', 'Darshan booking in peak season', 'Andhra Pradesh', '0', '0', '', '', 'Free general darshan; Seeghra Darshanam Rs 150; Athiseeghra Rs 300; Sparsha/VIP Rs 500 (web search)', 5.0, 4.9, 16.07, 78.87, 'Srisailam, Nandyal, Andhra Pradesh', 'https://www.srisailadevasthanam.org/', 0.97, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'verified', 'Official temple trust site confirmed. Coords ~0.6 km off real temple location. [Price source: web search (bloggymaster, pilgrimagetour, triphobo, eindiatourism)] Official site loads; homepage showed donations, accommodation and Srisaila TV sections but no hours/prices - hours/prices from web search. Darshan/seva tickets bookable online via the official site.', '2026-09-30'),
('100132', '1006', 'Srisailam Dam', 'Srisailam Dam', 'One of India largest dams across the Krishna, with spectacular gated views in the monsoon.', '1-2 hours', 'Evening', 'Monsoon visits when the crest gates are open are unforgettable.', '', 'Andhra Pradesh', '0', '1', '', '6:00 PM', 'Free (travellerkaka)', 4.6, 4.5, 16.09, 78.9, 'Srisailam Dam, Nandyal, Andhra Pradesh', '', 0.88, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'partial', 'Exists, free entry. No official published viewpoint hours; travel guides cite 8 AM-5 PM or sunrise-sunset; avoid 9 PM-6 AM (traffic restricted). [Price source: web search (travellerkaka, tripadvisor)] No official website; data from web search.', '2026-09-30'),
('100133', '1006', 'Patala Ganga', 'Patala Ganga', 'The Krishna gorge below the temple, reached by ropeway; the holy dip point for pilgrims.', '2 hours', 'Morning', 'Combine the ropeway ride with the holy dip for the full experience.', '', 'Andhra Pradesh', '0', '0', '', '', 'Ropeway adults Rs 50-60 / children Rs 35 (srisailamtourism, holidify, triphobo); Rs 80 return per reviews; boating Rs 50 adult / Rs 35 child', 4.5, 4.6, 16.06, 78.86, 'Patala Ganga, Srisailam, Andhra Pradesh', '', 0.85, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'verified', 'Real spelling also ''Pathala Ganga''/''Patal Ganga''. File''s 7 AM-6 PM hours were wrong; ropeway runs 6 AM-5:30 PM. [Price source: web search (srisailamtourism, holidify, triphobo)] No official website; data from web search.', '2026-09-30'),
('100134', '1006', 'Akkamahadevi Caves', 'Akkamahadevi Caves', 'River caves reached by boat through the Nallamala gorge, with a natural Shiva shrine inside.', '3 hours', 'Morning', 'Boat timings depend on water levels; confirm at the APTDC counter first.', '', 'Andhra Pradesh', '0', '0', '', '', 'No cave entry fee; boat Rs 250-350 (blogreadersindia) / Rs 400-600 (travellerkaka) / Rs 650 (wanderlog reviews) - sources disagree', 4.4, 4.5, 16.1, 78.83, 'Akkamahadevi Caves, Srisailam, Andhra Pradesh', '', 0.83, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'partial', 'Exists; also spelled ''Akka Mahadevi Caves''. No official published hours. APTDC boat leaves Pathala Ganga ~10:30 AM (be at counter by 9:30 AM); timing depends on water levels. Coords ~6 km from one map listing but within tolerance. [Price source: web search (blogreadersindia, travellerkaka, wanderlog)] No official website; boat price sources conflict.', '2026-09-30'),
('100135', '1006', 'Srisailam Tiger Reserve', 'Nagarjunasagar Srisailam Tiger Reserve', 'India largest tiger reserve; safaris through dense Nallamala forest with rich birdlife.', 'Half day', 'Morning', 'Book the safari in advance; sightings need patience and luck.', 'Safari booking required', 'Andhra Pradesh', '0', '0', '', '', 'Entry free; safari Rs 800 (velpu.com); ~Rs 1,000/head Nekkanti jungle ride, ~120 tickets/day, advance booking via nstr.co.in (traveler reports)', 4.5, 4.4, 16.0, 78.8, 'Srisailam Tiger Reserve, Nandyal, Andhra Pradesh', '', 0.84, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'mid', 'na', 'own', '2026-09-30 12:00:00', 'partial', 'Exists; India''s largest tiger reserve (~3,728 sq km). No single official published safari timetable found. Travel guides cite Tummalabailu jeep safaris ~7 AM-4 PM; forest checkposts close 9 PM. Safaris suspended Jul-Sep (monsoon). Confirm locally before visit. [Price source: web search (velpu.com, nstr.co.in, traveler reports)] Same reserve as 100144 (NSTR); no separate website.', '2026-09-30'),
('100136', '1006', 'Sakshi Ganapati Temple', 'Sakshi Ganapati', 'The customary first stop before the main darshan, on the road into Srisailam.', '30 minutes', 'Morning', 'Pilgrims traditionally visit here before the Jyotirlinga.', '', 'Andhra Pradesh', '0', '0', '', '', 'free', 4.3, 4.2, 16.075, 78.865, 'Srisailam, Nandyal, Andhra Pradesh', '', 0.74, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'partial', 'Exists; small temple a few km from main temple, traditional first stop. No published hours found (small roadside shrine). No own website (covered by srisailadevasthanam.org). No entry fee info found.', '2026-09-30'),
('100137', '1006', 'Hathakesvara Temple', 'Hathakesvara Temple', 'An ancient Shiva temple near Srisailam associated with the sage Hathakesvara.', '1 hour', 'Morning', 'A peaceful stop away from the main temple crowds.', '', 'Andhra Pradesh', '0', '0', '', '', 'Entry free', 4.2, 4.1, 16.065, 78.875, 'Srisailam, Nandyal, Andhra Pradesh', '', 0.71, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'partial', 'Exists; also spelled ''Hatakeswaram''. No official site or published hours found. [Price source: web search] No official website; data from web search.', '2026-09-30'),
('100138', '1006', 'Paladhara Panchadhara', 'Paladhara Panchadhara', 'Forest springs believed to have healing waters, a short drive from the temple.', '1 hour', 'Morning', 'The forest road is scenic; combine with the dam viewpoint.', '', 'Andhra Pradesh', '0', '0', '', '', 'No entry fee found', 4.2, 4.3, 16.05, 78.88, 'Srisailam, Nandyal, Andhra Pradesh', '', 0.72, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'partial', 'Exists; also spelled ''Phaladhara Panchadhara''. Forest springs near Srisailam. No published hours. [Price source: web search] ~150-160 steps down; no official website.', '2026-09-30'),
('100139', '1006', 'Shikharam Srisailam', 'Shikharam Viewpoint', 'The highest point around the temple town with views over the gorge and forest.', '1 hour', 'Evening', 'Sunset from here stretches across the Nallamala ridges.', '', 'Andhra Pradesh', '0', '1', '', '6:00 PM', 'free', 4.4, 4.5, 16.07, 78.86, 'Srisailam, Nandyal, Andhra Pradesh', '', 0.81, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'partial', 'Exists; highest peak near Srisailam (~2835 ft) with Sikhareswara Shiva temple. No published hours. No official website; no price info found.', '2026-09-30'),
('100140', '1006', 'Mallela Theertham Waterfalls', 'Mallela Theertham', 'A forest waterfall reached by a 350-step descent through the Nallamala.', '2-3 hours', 'Morning', 'The steps are steep; carry water and go early.', '', 'Andhra Pradesh', '0', '0', '', '', 'Rs 10/person (trawell.in; on-site board per tripadvisor review); car parking Rs 20; travelsetu says adult INR 50 / child 30 - sources disagree', 4.4, 4.5, 16.2, 78.95, 'Nagarjuna Sagar Road, Nagarkurnool district, Telangana', '', 0.82, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'verified', 'CORRECTION: actually in Telangana (Nagarkurnool/Mahabubnagar district), not Andhra Pradesh; ~58 km from Srisailam on Hyderabad road. File address ''Nandyal, Andhra Pradesh'' is wrong. [Price source: web search (trawell.in, velpu, travelsetu)] No official website; price sources conflict.', '2026-09-30'),
('100141', '1006', 'Srisailam Ropeway', 'Srisailam Ropeway', 'The ropeway gliding down the gorge to Patala Ganga with river views.', '1 hour', 'Evening', 'Evening rides have the best light over the gorge.', '', 'Andhra Pradesh', '0', '1', '', '6:00 PM', 'Rs 50 adult / Rs 35 child; Rs 80 return per reviews', 4.3, 4.4, 16.06, 78.86, 'Srisailam, Nandyal, Andhra Pradesh', '', 0.78, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'verified', 'Operated by APTDC. File''s 9 AM-6 PM hours were wrong; runs from 6 AM. [Price source: web search] Ropeway detail covered under 100133 Patala Ganga; no own website.', '2026-09-30'),
('100142', '1006', 'Octopus Viewpoint Srisailam', 'Octopus Viewpoint', 'Viewpoint over the Krishna reservoir where its arms wind like an octopus.', '30 minutes', 'Evening', 'A quick stop on the dam road with great photos.', '', 'Andhra Pradesh', '0', '1', '', '6:00 PM', 'free', 4.2, 4.3, 16.085, 78.895, 'Srisailam, Nandyal, Andhra Pradesh', '', 0.73, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'partial', 'Exists (hilltop viewpoint on dam road). One travel guide says open until ~6 PM; no official published hours. Direct fetch of official Telangana tourism Octopus page failed - search-based data only. Do not retry the fetch.', '2026-09-30'),
('100143', '1006', 'Nallamala Forest Chenchu Villages', 'Nallamala Chenchu Villages', 'Dense forest home of the Chenchu tribe; guided walks into their villages are possible.', 'Half day', 'Morning', 'Go with a forest department guide; this is core tiger habitat.', '', 'Andhra Pradesh', '0', '0', '', '', 'free', 4.1, 4.2, 16.0, 78.7, 'Nallamala Forest, Nandyal, Andhra Pradesh', '', 0.7, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'partial', 'Chenchu tribe/villages exist in Nallamala. Not a ticketed attraction with set hours; village visits need forest department permission/guide. Descriptive entry, keep as experience. No formal tour product; forest-dept jeep + contacts required, ~30 km trek (team-bhp). No ticket info found.', '2026-09-30'),
('100144', '1006', 'Ishtakameswari Temple', 'Ishtakameswari Temple', 'A forest temple where the goddess forehead is the idol; open on limited days.', '2 hours', 'Morning', 'Confirm the temple open days before making the forest drive.', '', 'Andhra Pradesh', '0', '0', '', '', 'free', 4.3, 4.2, 16.02, 78.78, 'Ishtakameswari, Nandyal, Andhra Pradesh', 'https://nstr.co.in', 0.74, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'verified', 'Exists ~20 km from Srisailam in tiger reserve forest. File''s 6 AM-6 PM was wrong; access is strictly via ticketed jungle ride 9 AM-2 PM. nstr.co.in is the NSTR official site per travel sources. Official site loads; no prices on homepage - hours/prices from web search where available.', '2026-09-30'),
('100145', '1006', 'Krishna Backwaters Boating Srisailam', 'Srisailam Boating', 'APTDC boats on the Krishna backwaters with gorge and forest views.', '1-2 hours', 'Evening', 'The evening slot has the calmest water and best light.', '', 'Andhra Pradesh', '0', '1', '', '6:00 PM', 'paid', 4.2, 4.1, 16.065, 78.87, 'Srisailam, Nandyal, Andhra Pradesh', NULL, 0.71, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'verified', 'APTDC boats operate from Patala Ganga. aptdc.gov.in is APTDC''s official site. Official website dead as of 2026-09-30; URL removed. aptdc.gov.in failed to load (dead as of 2026-09-30). APTDC Srisailam ropeway info may be on the APTDC booking portal - not verified.', '2026-09-30'),
('100146', '1006', 'Mahanandi Temple', 'Mahanandi', 'An ancient Shiva temple with crystal-clear spring pools you can bathe in.', '2 hours', 'Morning', 'The spring water stays cool year-round; carry a change of clothes.', '', 'Andhra Pradesh', '0', '0', '', '', 'Free entry; sevas: Suprabhatha Rs 100/person, Rudrabhishekam Rs 1000 (velpu)', 4.5, 4.4, 15.47, 78.62, 'Mahanandi, Nandyal, Andhra Pradesh', NULL, 0.83, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'partial', 'Exists (one of Nava Nandis). Sources conflict: 5:30 AM-9 PM no break vs 4:30 AM-1 PM / 2 PM-9:30 PM. File''s 5:30 AM-9 PM with 1-3 PM break is plausible but unverified. Distant day trip ~75-85 km from Srisailam. Website URL looks odd (mahanadi vs mahanandi) - verify before use. [Price source: web search (velpu)] Official website wrong page as of 2026-09-30; URL removed. www.mahanadi.com is a parked domain for sale via Afternic - wrong page; data from web search.', '2026-09-30'),
('100147', '1006', 'Ahobilam Temples', 'Ahobilam', 'The nine Narasimha temples spread across the Nallamala hills, a major pilgrimage trek.', 'Full day', 'Morning', 'The upper Ahobilam trek needs a full day; start at dawn.', '', 'Andhra Pradesh', '0', '0', '', '', 'General darshan Rs 50 (templesmap, yatradham); Kalyanotsavam ~Rs 3000; booking at booking.ahobilamtemple.com', 4.6, 4.5, 15.63, 78.72, 'Ahobilam, Nandyal, Andhra Pradesh', NULL, 0.86, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'partial', 'Exists (Nava Narasimha Kshetra, 9 temples). File coords (15.73, 78.72) are ~11 km north of Lower Ahobilam (~15.63, 78.72) - coords need fixing. Distant day trip ~90-100 km from Srisailam, near Allagadda. [Price source: web search (templesmap, yatradham)] Official website dead as of 2026-09-30; URL removed. ahobilamtemple.com failed to load (dead as of 2026-09-30); data from web search.', '2026-09-30'),
('100148', '1006', 'Belum Caves', 'Belum Caves', 'The second largest cave system in India with underground chambers and a natural waterfall.', '2 hours', 'Morning', 'The caves stay cool inside; good even in summer afternoons.', '', 'Andhra Pradesh', '0', '0', '', '', 'Entrance Fee Rs.50/adult (Indians), Rs.300/adult (Foreigners), Child Rs.35', 4.6, 4.5, 15.1, 78.11, 'Belum Caves, Nandyal, Andhra Pradesh', 'http://www.belumcaves.com/', 0.87, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'verified', 'Exists; second-largest cave system in India. File coords within ~0.3 km of listed location. Distant day trip ~150 km from Srisailam (Kolimigundla, Nandyal district). [Price source: official site (belumcaves.com)] Official site loads. Also offers Haritha hotel 22-bed dormitory, advance booking; contact 9705389600.', '2026-09-30'),
('100149', '1006', 'Yaganti Uma Maheshwara Temple', 'Yaganti Temple', 'Famous for the growing Nandi statue and the Pushkarini with year-round spring water.', '2 hours', 'Morning', 'See the Pushkarini; its water flow never stops even in drought.', '', 'Andhra Pradesh', '0', '0', '', '', 'Entry free; Abhishekam Rs 100, Rudrabhishekam Rs 750 (velpu)', 4.5, 4.4, 15.35, 78.13, 'Yaganti, Nandyal, Andhra Pradesh', '', 0.84, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'partial', 'Exists (growing Nandi, Pushkarini). No official site found (kurnoolcabs.com is a cab company). Sources commonly cite 6 AM-1 PM / 3 PM-8 PM but none official. File''s 6 AM-8 PM with 1-3 PM break is plausible but unverified. Distant day trip ~100 km from Srisailam. [Price source: web search (trawell.in, velpu)] No official website; data from web search.', '2026-09-30'),
('100150', '1006', 'Chenchu Lakshmi Tribal Museum', 'Srisailam Interpretation Centre', 'Forest department centre explaining the Nallamala ecology and tiger reserve.', '1 hour', 'Morning', 'Good primer before the safari.', '', 'Andhra Pradesh', '0', '0', '', '', 'Rs 10 (MakeMyTrip) / Rs 20 adult, Rs 10 child (srisailamtourism, worldorgs review)', 3.9, 3.9, 16.068, 78.872, 'Srisailam, Nandyal, Andhra Pradesh', '', 0.61, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'renamed', 'No ''Srisailam Sanctuary Interpretation Centre'' found by that name; the real equivalent is the Chenchu Lakshmi Tribal Museum. Recommend renaming the row. [Price source: web search (MakeMyTrip, srisailamtourism)] No official website; price sources conflict.', '2026-09-30'),
('100151', '1006', 'Haritha Srisailam Restaurant', 'Haritha Srisailam', 'APTDC restaurant serving Andhra meals to temple town visitors.', '1 hour', 'Afternoon', 'The meals are simple, filling and well priced.', '', 'Andhra Pradesh', '0', '0', '', '', 'paid', 4.0, 4.0, 16.069, 78.871, 'Srisailam, Nandyal, Andhra Pradesh', '', 0.67, '2026-09-30 12:00:00', NULL, 'restaurant', 'Andhra', 'budget', 'veg-options', 'own', '2026-09-30 12:00:00', 'partial', 'APTDC Haritha hotel/restaurant exists in Srisailam (tourism.ap.gov.in listing). Restaurant hours not independently published - unverified. No official website; no published hours/prices found. Traveler report (team-bhp, 2011, dated): Haritha hotel restaurant meals ~Rs 55 + tax.', '2026-09-30'),
('100152', '1006', 'Annapurna Mess Srisailam', 'Annapurna Mess Srisailam', 'Simple mess-style Andhra meals near the temple.', '1 hour', 'Afternoon', 'Quick and cheap; ideal between darshans.', '', 'Andhra Pradesh', '0', '0', '', '', 'paid', 3.9, 3.9, 16.07, 78.868, 'Srisailam, Nandyal, Andhra Pradesh', '', 0.62, '2026-09-30 12:00:00', NULL, 'restaurant', 'Andhra', 'budget', 'veg-options', 'own', '2026-09-30 12:00:00', 'unverified', 'Small local mess near temple; could not independently verify existence or hours - keep as provisional. Small local mess in Srisailam; no official website; no published hours found.', '2026-09-30'),
