INSERT INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score, created_at, google_place_id, category, cuisine, price_band, veg_flag, source, updated_at, verification_status, verification_notes, verified_at) VALUES
('100209', '1009', 'Pulicat Lake', 'Pulicat Lake', 'The second largest brackish water lagoon in India; flamingos arrive in winter.', 'Half day', 'Morning', 'November to February for the flamingo flocks; take a local boat.', '', 'Andhra Pradesh', '1', '0', '6:00 AM', '', 'free', 4.5, 4.6, 13.57, 80.17, 'Pulicat Lake, Tirupati, Andhra Pradesh', NULL, 0.85, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'partial', 'Exists: second-largest brackish-water lagoon in India, on the AP-Tamil Nadu border. Listed by AP Tourism Authority (Nellore district page, Flamingo Festival Jan-Feb). No published opening hours found. District flag: the Sullurpeta-area day trip sits in Tirupati district, not Nellore district proper. Official website dead as of 2026-09-30; URL removed. Official AP Tourism site returned HTTP 500 on 3 attempts (2026-09-30); do NOT retry. Flamingo Festival held Jan-Feb per AP Tourism (from verification notes).', '2026-09-30'),
('100210', '1009', 'Nelapattu Bird Sanctuary', 'Nelapattu Sanctuary', 'One of the largest pelican colonies in Southeast Asia.', '2-3 hours', 'Morning', 'October to March is the nesting season; mornings are most active.', '', 'Andhra Pradesh', '1', '0', '6:00 AM', '', 'paid', 4.4, 4.5, 13.825, 79.95, 'Nelapattu, Tirupati, Andhra Pradesh', 'https://forests.ap.gov.in/nelapattu.php', 0.83, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'partial', 'Exists: largest breeding ground for grey/spot-billed pelicans in SE Asia, sanctuary declared 1976; nesting season Oct-Mar confirmed. District flag: now in Tirupati district (near Doravarisatram/Sullurpeta). Coords (13.83, 79.80) are ~16 km west of the real sanctuary (~13.825, 79.950) - longitude should be ~79.95. Official page lists no hours; published timings vary, so hours unverified. Official AP Forest Dept page loads; publishes no visitor hours or entry prices.', '2026-09-30'),
('100211', '1009', 'Sriharikota SHAR Space Centre', 'Satish Dhawan Space Centre', 'ISRO spaceport; rocket launch viewings are open to the public via registration.', 'Half day', 'Morning', 'Register for launch viewings on the SHAR website well in advance.', 'Launch viewing registration required', 'Andhra Pradesh', '0', '0', '', '', 'paid', 4.7, 4.6, 13.72, 80.23, 'Sriharikota, Tirupati, Andhra Pradesh', 'https://lvg.shar.gov.in/VSCREGISTRATION/index.jsp', 0.89, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'partial', 'Exists: Satish Dhawan Space Centre (SHAR), ISRO''s launch facility on Sriharikota island. District flag: Sriharikota is in Tirupati district, day trip from Nellore. Current ''9:00 AM-5:00 PM daily'' is wrong - no regular daily visiting hours exist. Launch View Gallery registration portal loads; gallery is public with govt ID registration. No prices published.', '2026-09-30'),
('100212', '1009', 'Udayagiri Fort', 'Udayagiri Fort Nellore', 'A hill fort with temples and sweeping views over the plains.', '2-3 hours', 'Morning', 'The climb is moderate; start early to avoid the heat.', '', 'Andhra Pradesh', '1', '0', '6:00 AM', '', 'Entry ~Rs 20 for Indian visitors, higher for foreigners; photography fees may apply', 4.2, 4.1, 13.69, 79.31, 'Udayagiri, Nellore, Andhra Pradesh', 'https://spsnellore.ap.gov.in/udayagiri-fort-udayagiri/', 0.72, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'partial', 'Exists: hill fort in Udayagiri town, ~100 km from Nellore city, within Sri Potti Sriramulu Nellore district. ''Udayagiri Fort Nellore'' distinguishes it from the Tamil Nadu Udayagiri Fort (Kanyakumari) - name ok. [Price source: SPS Nellore district tourism site] Hours and indicative prices taken from the official district tourism page.', '2026-09-30'),
('100213', '1009', 'Sri Thalpagiri Ranganadha Swamy Temple', 'Ranganatha Temple Nellore', 'An ancient Vaishnavite temple on the Penna river with a tall gopuram.', '1-2 hours', 'Morning', 'The riverside setting is lovely in the early morning.', '', 'Andhra Pradesh', '1', '0', '6:00 AM', '', 'free', 4.4, 4.3, 14.44, 79.99, 'Nellore, Andhra Pradesh', '', 0.8, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'renamed', 'Exists, in Nellore city on the Penna River. Proper name is Sri Thalpagiri Ranganadha Swamy Temple, one of Nellore''s oldest Vaishnavite temples. No official temple website found. Published timings conflict and none from an official source, so hours unverified; the listed 1-3 PM break is not corroborated. Free entry (inheritage.foundation). Hours conflict across sources: 6 AM-6 PM (inheritage.foundation) vs 6 AM-12 PM + 4-8:30 PM (Wanderlog) vs 9:30 AM-6:30 PM (Justdial). Do not publish single hours without re-check.', '2026-09-30'),
('100214', '1009', 'Bara Shahid Dargah Nellore', 'Bara Shahid Dargah', 'The famous dargah known for the Rottela Panduga festival.', '1-2 hours', 'Morning', 'Visit during Rottela Panduga to see the famous roti-exchange ritual.', '', 'Andhra Pradesh', '0', '0', '', '', 'free', 4.5, 4.4, 14.45, 79.98, 'Nellore, Andhra Pradesh', '', 0.82, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'partial', 'Exists: ''shrine of the twelve martyrs'' dargah on Trunk Road, Ambedkar Nagar, Nellore city (alt spelling ''Bara Shaheed Dargah''). Famous for the annual Rottela Panduga (Rotiyaan ki Eid) urs in Muharram. No official website found; no reliable published hours - hours unverified. Hours per Justdial listing. Venue of the annual 3-day Rottela Panduga festival (see festival_rottela).', '2026-09-30'),
('100215', '1009', 'Jonnawada Sri Mallikarjuna Swamy Kamakshi Tayee Temple', 'Jonnavada Temple', 'A revered Kamakshi temple near Nellore town.', '1 hour', 'Morning', 'Fridays are the busiest; go early for a quick darshan.', '', 'Andhra Pradesh', '0', '0', '', '', 'free', 4.3, 4.2, 14.43, 79.93, 'Jonnavada, Nellore, Andhra Pradesh', NULL, 0.75, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'renamed', 'Exists. Confirmed on Nellore district govt tourist list: Sri Mallikarjuna Swamy Kamakshi Tayee Ammavari Temple, Jonnawada, Buchireddypalem Mandal, 15 km from Nellore, on the Penna river. Standard spelling is ''Jonnawada''. Precise coords from listing: 14.4790, 79.8911 (~7 km from DB coords, within tolerance). Fridays busiest confirmed by multiple sources. Official website dead as of 2026-09-30; URL removed. AP Temples portal returned HTTP 500 on 3 attempts (2026-09-30); do NOT retry.', '2026-09-30'),
('100216', '1009', 'Sri Penusila Lakshmi Narasimha Swamy Temple, Penchalakona', 'Penchalakona', 'A Lakshmi Narasimha temple set in the Veligonda hills.', '2 hours', 'Morning', 'The hill drive is scenic; combine with the nearby waterfalls in monsoon.', '', 'Andhra Pradesh', '0', '0', '', '', 'free', 4.4, 4.3, 14.32, 79.42, 'Penchalakona, Nellore, Andhra Pradesh', 'https://www.penchalakona.co.in/', 0.79, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'renamed', 'Exists. One of the Nava Narasimha temples; in Veligonda hills at Penchalakona, Rapur Mandal, Nellore district, ~70-83 km from Nellore town (not near the town). Precise coords 14.3366, 79.4103 (~2 km from DB coords). Temple site loads but is gallery-only; publishes no hours or prices.', '2026-09-30'),
('100217', '1009', 'Mypadu Beach', 'Mypadu Beach', 'A long sandy beach near Nellore, popular with locals on weekends.', '2-3 hours', 'Evening', 'Weekday evenings are quiet; weekends get crowded.', '', 'Andhra Pradesh', '0', '1', '', '6:00 PM', 'No entry fee reported', 4.3, 4.4, 14.5, 80.18, 'Mypadu, Nellore, Andhra Pradesh', '', 0.78, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'partial', 'Exists. Mypadu Beach in Nellore district, ~20-25 km from Nellore, maintained by APTDC; entry fees of Rs.15-20 planned from 2025 per Outlook Traveller. No official APTDC page found live; no authoritative source publishes visiting hours (third-party guides vary 4:30 AM-7:30 PM). Coords match Wikipedia (14.5068, 80.1788) within ~1 km. [Price source: thomascook.in / travelsetu / velpu / nayatrip.com (Google search 2026-09-30)] Multiple travel sources report no entry fee. Outlook Traveller reported AP govt planned a Rs 15-20 beach entry fee from 2025-01-01 including Maipadu - reported policy, implementation unverified.', '2026-09-30'),
('100218', '1009', 'Krishnapatnam Beach', 'Krishnapatnam Beach', 'A beach near the port town with fishing village life.', '2 hours', 'Evening', 'Watch the fishing boats return in the late afternoon.', '', 'Andhra Pradesh', '0', '1', '', '6:00 PM', 'free', 4.0, 4.1, 14.28, 80.13, 'Krishnapatnam, Nellore, Andhra Pradesh', 'https://spsnellore.ap.gov.in/krishnapatnam-beach-light-house-krishnapatnam/', 0.66, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'partial', 'Exists. In Nellore district, ~20 km south of Nellore, adjacent to Krishnapatnam Port and the lighthouse (ticketed 3-6 PM). No official source publishes beach visiting hours; third-party guides give ~6:30 AM-6:00 PM daily. Official district tourism page loads; notes best time Nov-Feb. No hours or prices published.', '2026-09-30'),
('100219', '1009', 'Somasila Dam', 'Somasila Dam', 'A dam on the Penna with a large reservoir and sunset views.', '1-2 hours', 'Evening', 'Evenings are pleasant; the reservoir reflects the sunset.', '', 'Andhra Pradesh', '0', '1', '', '6:00 PM', 'Free entry', 4.1, 4.2, 14.48, 79.3, 'Somasila, Nellore, Andhra Pradesh', '', 0.7, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'partial', 'Exists. Earth-fill dam on the Penna River at Somasila, Nellore district, ~90 km from Nellore; boating Oct-Feb. No official site found and no authoritative source publishes visiting hours (third-party guides say daylight hours, e.g. 9 AM-5 PM / 8 AM-6 PM). DB coords within ~1.5 km of Wikipedia coords (14.4894, 79.3053). [Price source: travelsetu / velpu (Google search 2026-09-30)] Entry reported free; hours conflict across sources - do not publish single hours without re-check.', '2026-09-30'),
('100220', '1009', 'Sri Vedagiri Lakshmi Narasimha Swamy Temple, Narasimhakonda', 'Narasimha Konda', 'A hilltop Narasimha temple overlooking Nellore town.', '1-2 hours', 'Morning', 'The climb is short and the town view is rewarding.', '', 'Andhra Pradesh', '1', '0', '6:00 AM', '', 'free', 4.2, 4.1, 14.43, 79.98, 'Nellore, Andhra Pradesh', 'https://spsnellore.ap.gov.in/sri-vedagiri-lakshimi-narasimha-swamy-temple-narasimhakonda/', 0.71, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'renamed', 'Exists. Hilltop Narasimha temple at Narasimhakonda, Nellore Rural, 14-16 km from Nellore and 5 km from Jonnawada, on the southern bank of the Penna (Pinakini) - it is NOT directly overlooking Nellore town. No official published hours; third-party sources say 6:30 AM-8:00 PM daily. DB coords consistent with district location data. Official district tourism page loads; notes Brahmotsavams held in May. No hours or prices published.', '2026-09-30'),
('100221', '1009', 'Chengalamma Temple Sullurpeta', 'Chengalamma Temple', 'A famous goddess temple in Sullurpeta town.', '1 hour', 'Morning', 'Tuesdays and Fridays draw the biggest crowds.', '', 'Andhra Pradesh', '0', '0', '', '', 'free', 4.3, 4.2, 13.7, 80.02, 'Sullurpeta, Tirupati, Andhra Pradesh', NULL, 0.74, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'verified', 'Exists: Sri Chengalamma Parameswari Temple, Sullurpeta - on banks of Kalangi river, ~1.2 km from Sullurpeta railway station. District flag: Sullurpeta is now in Tirupati district (post-2022 redistricting), not Nellore. Legend claims the doorless temple stays open 24 hrs and Justdial lists 6 AM-9 PM, but 6 AM-8 PM is the most-cited daily figure. Tue/Fri busiest note is consistent with devotee reports. Official website dead as of 2026-09-30; URL removed. Domain unresolvable / fetch failed (2026-09-30); do NOT retry. Record as dead/unknown.', '2026-09-30'),
('100222', '1009', 'Dugarajapatnam Beach', 'Dugarajapatnam Beach', 'A quiet beach near the historic port town.', '2 hours', 'Evening', 'One of the least crowded beaches in the region.', '', 'Andhra Pradesh', '0', '1', '', '6:00 PM', 'free', 4.0, 4.1, 13.98, 80.14, 'Dugarajapatnam, Tirupati, Andhra Pradesh', '', 0.65, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'partial', 'Exists: quiet beach by the historic port town of Dugarajapatnam (town at ~13.9834, 80.1159). Listed coords 14.3300, 80.1600 are ~38 km north of the real location - must be corrected to ~13.98, 80.14. District flag: Dugarajapatnam is in Tirupati district (Vakadu mandal), not Nellore. No official published visiting hours for a public beach. No place-specific results in Google search (2026-09-30). Context only: AP govt''s reported Rs 15-20 beach entry fee policy (Outlook Traveller) - implementation unverified.', '2026-09-30'),
('100223', '1009', 'Venkatagiri Fort', 'Venkatagiri Fort', 'A fort of the Venkatagiri rajas with palace ruins.', '2 hours', 'Morning', 'Combine with the Venkatagiri saree weaving town visit.', '', 'Andhra Pradesh', '0', '0', '', '', 'Rs 20 Indian / Rs 100 foreigner (tourtravelworld) vs no entry fee (travellerkaka)', 4.1, 4.0, 13.96, 79.58, 'Venkatagiri, Tirupati, Andhra Pradesh', '', 0.68, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'partial', 'Venkatagiri Fort exists: historic fort of the Recherla/Venkatagiri Rajas (early 18th c.) in Venkatagiri town. File coords (13.96, 79.58) match the town within ~1 km. No official published visiting hours found; travel sites vary (9/10 AM - 5 PM), unverified. District flag: Venkatagiri is in Tirupati district under the 2022 AP district reorganisation (older sources list Nellore). [Transcription fix 2026-09-30: replaced note that had been duplicated from the Venkatagiri handloom entry 100228.] [Price source: Google search 2026-09-30] Hours and prices conflict across sources - do not publish without re-check.', '2026-09-30'),
('100224', '1009', 'Tada Falls Ubbalamadugu', 'Tada Falls', 'A waterfall near Tada with a rocky trek through the forest.', '3-4 hours', 'Morning', 'Monsoon to winter only; the rocks are slippery.', '', 'Andhra Pradesh', '0', '0', '', '', 'Entry Rs 20-50/person (sources vary); parking Rs 50 (2-wheeler) / Rs 200-300 (car); camera Rs 50-150 (still/DSLR)', 4.4, 4.5, 13.62, 79.85, 'Tada, Tirupati, Andhra Pradesh', '', 0.81, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'verified', 'Exists: Tada Falls / Ubbalamadugu Falls in Siddulaiah Kona forest near Tada - ~100 m falls, 10 km rocky trek, forest-dept checkpoint with entry fee. District flag: Tada is in Tirupati district, not Nellore. Coords 13.6200, 79.8500 are within ~10 km of the falls area. Listed 7 AM-5 PM exceeds the checkpoint-regulated 8 AM-4 PM window. [Transcription fix 2026-09-30: ISRO SDSC URL removed; it belongs to the Sriharikota entries (100211/100225), not Tada Falls.] [Price source: Forest dept via exoticamp / YouTube summaries (Google search 2026-09-30)] Hours per forest-department-derived sources; price ranges vary by source.', '2026-09-30'),
('100225', '1009', 'SHAR Space Museum Sriharikota', 'Space Museum SHAR', 'The space museum at the Sriharikota spaceport with rocket models.', '1-2 hours', 'Morning', 'Combine with a launch viewing registration for the full experience.', '', 'Andhra Pradesh', '0', '0', '', '', 'free', 4.3, 4.2, 13.721, 80.231, 'Sriharikota, Tirupati, Andhra Pradesh', 'https://www.isro.gov.in/SDSC.html', 0.76, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'partial', 'Exists: ISRO/SDSC SHAR has a Space Museum & Public Outreach section (contact 08623-226380) and an exhibition gallery - accessible to the public via registered guided visits/launch view-gallery registration at lvg.shar.gov.in. No published daily visiting hours; entry requires prior online registration, so hours_verified=false. District flag: Sriharikota is in Tirupati district. Official ISRO SDSC page loads; publishes no visitor hours or ticket prices.', '2026-09-30'),
('100226', '1009', 'Kandaleru Dam', 'Kandaleru Dam', 'A major reservoir on the Kandaleru river supplying Chennai drinking water.', '1 hour', 'Evening', 'A quiet sunset stop on the Nellore hinterland drive.', '', 'Andhra Pradesh', '0', '1', '', '6:00 PM', 'Free entry', 4.0, 4.1, 14.3474, 79.594, 'Kandaleru, Nellore, Andhra Pradesh', '', 0.64, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'partial', 'Exists: Kandaleru Dam, earthen dam on the Kandaleru river (Telugu Ganga project), Rapur Mandal, SPSR Nellore district - correct district, ~57-60 km from Nellore. Listed coords 13.8300, 79.8500 are ~65 km off the dam''s real location (~14.3474, 79.5940) - must be corrected. Travel site velpu lists All Days 9 AM-6 PM matching current values, but no official authority publishes dam visitor hours. [Price source: velpu (Google search 2026-09-30)] Single-source hours/prices - treat as unverified.', '2026-09-30'),
('100227', '1009', 'Golagamudi Sri Venkaiah Swamy Temple', 'Golagamudi Temple', 'A famous Venkateswara temple near Nellore with a large devotee following.', '1-2 hours', 'Morning', 'Saturdays are the busiest; go early.', '', 'Andhra Pradesh', '0', '0', '', '', 'None published', 4.3, 4.2, 14.38, 79.93, 'Golagamudi, Nellore, Andhra Pradesh', '', 0.73, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'renamed', 'Real temple at Golagamudi (~7-12 km from Nellore) is dedicated to the saint Bhagavan Sri Venkaiah Swamy (an Avadhuta), NOT Lord Venkateswara - the current name is wrong. No authoritative hours published; crowd sources disagree (Justdial 6 AM-10 PM daily / Sat 5 AM-11 PM; Meta listing 6 AM-10 PM; a video gives darshan slots 6:30-11 AM, 12-2 PM, 4-6:30 PM). Listed coords are within ~6 km of the temple''s real location (~14.35, 79.97), acceptable. Saturdays being busiest is plausible (special sevas happen Thursdays and Saturdays). [Price source: sanatanavibes.in / Justdial (Google search 2026-09-30)] Darshan slots per sanatanavibes.in; Justdial shows broader 6 AM-10 PM - conflict. Daily Annadanam; Aradhana Utsavam in August. A YouTube description cites official sites www.venkaiahswamyashramgolagamudi.org and www.srivenkaiahswamy.org (not fetched in this pass).', '2026-09-30'),
('100228', '1009', 'Venkatagiri Saree Weaving Town', 'Venkatagiri Weavers', 'The handloom town famous for Venkatagiri cotton sarees.', '1-2 hours', 'Morning', 'Buy directly from weaver families for authentic sarees.', '', 'Andhra Pradesh', '0', '0', '', '', 'free', 4.0, 4.1, 13.961, 79.581, 'Venkatagiri, Tirupati, Andhra Pradesh', '', 0.66, '2026-09-30 12:00:00', NULL, 'attraction', NULL, 'budget', 'na', 'own', '2026-09-30 12:00:00', 'partial', 'Venkatagiri town (Tirupati district) is well-documented as the historic weaving centre of superfine Venkatagiri cotton sarees (GI-tagged Jamdani technique). As a town/working handloom cluster there are no official published visiting hours; daytime visiting for weaver families is reasonable. DIY textile trail among weavers'' homes; no organized visitor hours (Outlook Traveller textile trail; Mint revival story). Google search 2026-09-30.', '2026-09-30'),
('100229', '1009', 'Haritha Nellore Restaurant', 'Haritha Nellore', 'APTDC restaurant serving Andhra meals in Nellore town.', '1 hour', 'Afternoon', 'Try the Nellore chepala pulusu if it is on the menu.', '', 'Andhra Pradesh', '0', '0', '', '', 'paid', 4.0, 4.0, 14.441, 79.991, 'Nellore, Andhra Pradesh', 'https://tourism.ap.gov.in/', 0.66, '2026-09-30 12:00:00', NULL, 'restaurant', 'Andhra', 'budget', 'veg-options', 'own', '2026-09-30 12:00:00', 'partial', 'APTDC Haritha Hotel Nellore exists (behind D.K.W. College, Nellore, ~54 AC rooms, on-site restaurant and bar) - this record refers to its restaurant; ''Haritha Nellore Restaurant'' is an acceptable label but the property''s formal name is ''Haritha Hotel, Nellore''. Website is APTDC''s official site (no direct Nellore-hotel page surfaced). Coords are a town-centre approximation. No restaurant hours published by APTDC. Official site blocked by rate-limit during check (2026-09-30); re-verify URL before use. AP Tourism site blocked the fetch (2026-09-30); do NOT retry. Website status unknown - re-check manually.', '2026-09-30'),
('100231', '1009', 'Kritunga Restaurant Nellore', 'Kritunga Nellore', 'Andhra meals chain with traditional flavors and banana leaf service.', '1 hour', 'Afternoon', 'The veg meals are generous and well priced.', '', 'Andhra Pradesh', '0', '0', '', '', 'paid', 4.1, 4.0, 14.443, 79.993, 'Nellore, Andhra Pradesh', NULL, 0.68, '2026-09-30 12:00:00', NULL, 'restaurant', 'Andhra', 'mid', 'veg-options', 'own', '2026-09-30 12:00:00', 'partial', 'Kritunga Restaurant Nellore exists - Andhra/chain outlet at King''s Court Avenue, 1st Cross Road, Magunta Layout, Nellore (GST-registered ''KRITUNGA RESTAURANT NELLORE'', Magunta Layout, multiple outlets in Nellore). Banana-leaf Andhra meals/biryanis consistent with the chain''s style. No official per-outlet hours; crowd sources report split hours (11:30 AM-3:30 PM + 7-10:30 PM daily). Coords within ~2 km of the real outlet, acceptable. Official website wrong page as of 2026-09-30; URL removed. DOMAIN HIJACKED: kritungarestaurant.com now serves an Indonesian gambling site (''BROMO77''). FLAG FOR WEBSITE REMOVAL in SQL. kritungarestaurant.com hijacked (serves gambling site); URL removed.', '2026-09-30'),
('100232', '1009', 'Minerva Grand Nellore', 'Minerva Grand Nellore', 'Hotel restaurant serving Andhra and multi-cuisine.', '1 hour', 'Evening', 'Good family dinner option in Nellore.', '', 'Andhra Pradesh', '0', '0', '', '', 'paid', 4.0, 3.9, 14.444, 79.994, 'Nellore, Andhra Pradesh', NULL, 0.65, '2026-09-30 12:00:00', NULL, 'restaurant', 'Multi-cuisine', 'mid', 'veg-options', 'own', '2026-09-30 12:00:00', 'partial', 'Hotel Minerva Grand exists on Grand Trunk Road, Nellore (minervahotels.in); its restaurant is ''Blue Fox'' (multi-cuisine) plus ''On The Rocks'' bar - so the record is really the hotel''s Blue Fox restaurant. No official restaurant hours published. Coords within ~3 km of the hotel, acceptable. Official website dead as of 2026-09-30; URL removed. Site resolves to a bare Apache2 placeholder page - dead. FLAG FOR WEBSITE REMOVAL in SQL.', '2026-09-30'),
('100233', '1009', 'Rayalaseema Ruchulu Nellore', 'Rayalaseema Ruchulu Nellore', 'Spicy Andhra meals and biryanis with local Nellore touches.', '1 hour', 'Afternoon', 'Ask for the spice level; the default is fiery.', '', 'Andhra Pradesh', '0', '0', '', '', 'Rs 260 for two (Justdial) / Rs 300 for two (magicpin)', 4.0, 3.9, 14.445, 79.995, 'Nellore, Andhra Pradesh', '', 0.64, '2026-09-30 12:00:00', NULL, 'restaurant', 'Andhra', 'mid', 'veg-options', 'own', '2026-09-30 12:00:00', 'partial', 'A ''Rayalaseema Ruchulu'' restaurant exists in Nellore (Brundavanam, Kondareddy Building near Kanakamahal Centre; also a magicpin listing in Ambedkar Nagar) serving Andhra/biryani/seafood. Caution: several similar-name outlets exist (e.g., ''Mana Rayalaseema Ruchulu'' in Magunta Layout, flagged as possibly closed), and hours differ per outlet - Brundavanam outlet shows 10:00 AM-10:00 PM daily on Justdial (crowd-sourced, not authoritative), so listed 11:30 AM-11:00 PM is unverified. Coords are a town-centre approximation. [Price source: Justdial / magicpin (Google search 2026-09-30)] Price-for-two differs slightly by source.', '2026-09-30'),
('100234', '1009', 'Komala Vilas Nellore', 'Komala Vilas Nellore', 'South Indian tiffin centre for idli, dosa and meals.', '45 minutes', 'Morning', 'Quick breakfast before heading to Pulicat or SHAR.', '', 'Andhra Pradesh', '0', '0', '', '', 'Rs 1-200 per person', 3.9, 4.0, 14.446, 79.996, 'Nellore, Andhra Pradesh', '', 0.62, '2026-09-30 12:00:00', NULL, 'restaurant', 'South Indian', 'budget', 'veg', 'own', '2026-09-30 12:00:00', 'partial', 'Komala Vilas is a famous pure-veg tiffin/meals hotel in Nellore (Trunk Road / Babuji Colony listings; reviews say serving since 1936). Idli/dosa/meals tiffin-centre description matches. No official website or published hours found; crowd sources suggest early opening (~6-6:30 AM) until ~10-10:30 PM. Coords are a town-centre approximation. [Price source: restaurant-guru / yappe (Google search 2026-09-30)] Hours conflict across sources - do not publish without re-check.', '2026-09-30');

