INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000001, 331001, 'Our Lady of the Immaculate Conception Church', 'Church of Our Lady of the Immaculate Conception, Panjim', 'Panaji''s landmark whitewashed hilltop church, built in Portuguese Baroque style with a dramatic zigzag staircase. Originally a 1541 chapel for Portuguese sailors, it became a parish in 1600 and was rebuilt larger in 1609; it houses Goa''s second-largest church bell. It dominates Church Square and is the city''s most-photographed monument.', '45 minutes', 'Oct-Mar', 'Climb the stairs for the classic postcard view over Church Square and the Municipal Garden; attend an evening mass for the illuminated facade.', NULL, 'Goa', 0, 0, NULL, NULL, NULL, 5, 5, 15.49863, 73.82951, 'R. Emidio Gracia, Panaji, Goa 403001', 'http://icchurchpanjim.com/', 1.0);

