INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000002, 331001, 'Fontainhas (Latin Quarter)', 'Fontainhas Latin Quarter', 'Asia''s oldest and largest surviving Latin quarter, developed in the late 1700s around springs (''little fountain'') at the base of Altinho Hill. Narrow lanes lined with colour-washed Portuguese mansions, wrought-iron balconies and red-tiled roofs. Home to the Chapel of St Sebastian, the 31st January Bakery and art galleries.', '2 hours', 'Oct-Mar', 'Best explored on foot in the late afternoon; join a guided heritage walk (about 2.5 hours) starting near the Panjim Head Post Office to enter old Indo-Portuguese homes.', NULL, 'Goa', 0, 0, NULL, NULL, NULL, 5, 5, 15.4945, 73.831, 'Fontainhas, Altinho, Panaji, Goa 403001', NULL, 1.0);

