INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000003, 331001, 'Chapel of St. Sebastian', 'St Sebastian Chapel, Fontainhas', 'Small whitewashed 19th-century chapel (built 1818 per Lonely Planet; some sources say 1880) in the heart of Fontainhas. Notable for housing one of the few surviving relics of the Goan Inquisition: a striking crucifix from the Palace of the Inquisition in Old Goa, whose Christ has open eyes.', '20 minutes', 'Oct-Mar', 'Chapel may close in the afternoon; visit early morning or late afternoon. Its annual feast is celebrated on 20 January.', NULL, 'Goa', 0, 0, NULL, NULL, NULL, 4, 4, 15.49621, 73.83078, 'St Sebastian Road, Fontainhas, Altinho, Panaji, Goa 403001', NULL, 0.8);

