INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000004, 331001, 'Dona Paula Viewpoint', 'Dona Paula', 'Panaji''s iconic sea viewpoint at the tip of a headland where the Mandovi and Zuari rivers meet the Arabian Sea. Famous for panoramic sunsets, the white statue of Dona Paula, and breezy evening walks. Local legend ties the spot to the Viceroy''s daughter.', '1 hour', 'Oct-Mar', 'Visit before 9 AM on weekdays to beat the tourist rush; sunset is magical but crowded.', NULL, 'Goa', 0, 0, NULL, NULL, NULL, 5, 4, 15.45061, 73.80301, 'Dona Paula, Panaji, Goa 403004', NULL, 0.92);

