INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000005, 331001, 'Miramar Beach', 'Miramar Beach', 'Panaji''s main city beach, one of only two beaches in the capital (with Caranzalem), at the confluence of the Mandovi River and the Arabian Sea. Originally named Porta de Gaspar Dias by the Portuguese; hosted beach volleyball at the 2014 Lusofonia Games. Popular for evening strolls and sunsets, not swimming.', '1-2 hours', 'Oct-Mar', 'Best for walks and sunset views; swimming is not advisable due to currents. Migratory birds (gulls, plovers) visit in winter.', NULL, 'Goa', 0, 0, NULL, NULL, NULL, 4, 4, 15.48306, 73.80722, 'Miramar, Panaji, Goa 403001', NULL, 0.8);

