INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000006, 331001, 'Goa State Museum (Adil Shah Palace)', 'Goa State Museum', 'Goa''s state archaeological museum housed in Adil Shah''s Palace, the former palace of the Bijapur Sultanate founder that later served as the Portuguese Governor''s residence and then Goa''s Legislative Assembly. Collections span geology, ancient history, Portuguese-era art, numismatics and the Goa freedom struggle. Entry is free.', '1 hour', 'Oct-Mar', 'Tucked behind the Patto bridge near Kadamba Bus Stand; small collection takes about 20-45 minutes to see.', NULL, 'Goa', 0, 0, NULL, NULL, 'Free entry', 3, 3, 15.50082, 73.82999, 'EDC Complex, Old Secretariat (Adil Shah Palace), Patto, Panaji, Goa 403001', NULL, 0.6);

