INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000007, 331001, 'Mandovi River Cruise (Santa Monica Jetty)', 'Mandovi River Sunset Cruise', 'One-hour sunset cruises departing from Santa Monica Jetty (and Captain of Ports/Panaji Jetty) along the Mandovi River to the Miramar point. Cruises feature Goan folk dance, music and DJ entertainment. Evening sailings around 6 PM are the signature experience; dinner and day-long backwater cruises also run on select days.', '1-2 hours', 'Oct-Mar', 'Arrive by 5:30 PM to secure a spot; weekends can mean 1-2 hour waits. Buy tickets at the jetty counter rather than from touts.', NULL, 'Goa', 0, 0, NULL, NULL, 'Sunset cruise approx Rs. 300–500 per person (published operator rates vary; e.g. Goa Tourism listed Rs. 300, private operators from Rs. 450)', 5, 4, 15.501, 73.832, 'Santa Monica Jetty, Panaji, Goa 403001', NULL, 0.92);

