INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000008, 331001, 'Salim Ali Bird Sanctuary', 'Dr. Salim Ali Bird Sanctuary', 'Goa''s only bird sanctuary (1988), a 178-hectare mangrove island on Chorao Island named after India''s pioneer ornithologist. Home to kingfishers, egrets, herons, cormorants, eagles, marsh crocodiles, otters and mudskippers. Accessible only by ferry from Ribandar, followed by a canoe ride or mangrove walk; there is a birdwatching tower.', '2-3 hours', 'Oct-Mar (early morning)', 'Best at 8 AM or a couple of hours before sunset; boat trips depend on tides. Bring binoculars; forest department boat rides seat 10-12 and cost around Rs. 750-900.', NULL, 'Goa', 0, 0, NULL, NULL, 'Rs. 10–20 per person (Indians), Rs. 100 (foreigners); camera fees extra', 4, 4, 15.5103, 73.8658, 'Chorao Island (via Ribandar Ferry Wharf), Tiswadi, Goa 403004', NULL, 0.8);

