INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000009, 331001, 'Goa Science Centre & Planetarium', 'Goa Science Centre', 'Interactive science museum on Marine Highway, Miramar (established 2001 as a joint NCSM–Goa government project) spread over 5 acres with Fun Science and Ocean galleries, a digital planetarium, 3D film shows and an outdoor science park. Good family stop near Miramar Beach.', '2-3 hours', 'Year-round', 'Planetarium shows run at fixed slots (11 AM, 1 PM, 3 PM, 5 PM); arrive early on weekends to pick show timings.', NULL, 'Goa', 0, 0, NULL, NULL, 'Science Centre entry Rs. 10–20/person; Planetarium Rs. 15–30; 3D show Rs. 15–20 (published rates vary)', 3, 4, 15.47743, 73.80908, 'New Marine Highway, Miramar, Panaji, Goa 403001', NULL, 0.68);

