INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000010, 331001, 'Kala Academy', 'Kala Academy, Campal', 'Goa''s apex cultural institution, founded February 1970, in a Charles Correa-designed building at Campal overlooking the Mandovi. Home to the Dinanath Mangeshkar auditorium, open-air amphitheatre and exhibition hall, hosting theatre, music, dance and the International Film Festival of India events.', '1-2 hours', 'Oct-Mar (event season)', 'Check the event calendar — catching a play, concert or IFFI screening here is the real experience; the gardens are a quiet riverside pause.', 'Event tickets depend on the show; no booking needed to see the building and gardens.', 'Goa', 0, 0, NULL, NULL, NULL, 3, 4, 15.49424, 73.81767, 'Dayanand Bandodkar Marg, Campal, Panaji, Goa 403001', NULL, 0.68);

