INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000019, 331001, 'Casino ships on the Mandovi (Deltin Royale)', 'Deltin Royale Casino, Panaji', 'Panaji''s offshore floating casinos, anchored on the Mandovi and boarded from Panaji Jetty — the biggest is Deltin Royale. A major draw for Goa''s nightlife: gaming floors, live entertainment, dinner and drinks on board. Strictly 21+ with valid ID.', '3-4 hours', 'Year-round (evening)', 'Entry packages vary by day and package; book online in advance for weekend nights. Carry a valid government photo ID (21+).', 'Book tickets online or via the casino''s booking office; boarding is from Panaji Jetty past Santa Monica Jetty.', 'Goa', 0, 0, NULL, NULL, NULL, 4, 4, 15.5025, 73.834, 'Panaji Jetty, Panaji, Goa 403001', NULL, 0.8);

