INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000021, 331001, 'Ritz Classic', 'Ritz Classic, Panjim', 'Panaji''s legendary fish-thali institution — locals and visitors queue for the Goan fish thali (fish curry, clams, prawns, fried fish), kingfish fry and butter-garlic calamari. Multiple city outlets; the classic one is the busy first-floor spot on 18th June Road.', '1 hour', 'Year-round (lunch)', 'The Goan fish thali is the must-order; lunch hours are the liveliest and queues form at peak season.', NULL, 'Goa', 0, 0, NULL, NULL, NULL, 5, 5, 15.49857, 73.82666, '1st Floor, Wagle Vision Building, 18th June Rd, Panaji, Goa 403001', NULL, 1.0);

