INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000022, 331001, 'Kokni Kanteen', 'Kokni Kanteen Goa', 'Nostalgic eatery on Dr Dada Vaidya Road serving traditional Kokni (Saraswat) Goan home food since 1972 — seafood thalis with sol kadhi, bangda (mackerel) fry in banana leaves, and desserts like serradura and bebinca. Housed in a Portuguese-era bungalow near Mahalaxmi Temple, with vintage 1970s decor.', '1 hour', 'Year-round', 'Expect a short wait at lunch; the seafood thali and bangda fry are the signature orders.', NULL, 'Goa', 0, 0, NULL, NULL, NULL, 5, 5, 15.49666, 73.827, 'Dr Dada Vaidya Rd, Near Mahalaxmi Temple, Altinho, Panaji, Goa 403001', NULL, 1.0);

