INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000023, 331001, 'Mum''s Kitchen', 'Mum''s Kitchen, Miramar', 'Award-winning Goan restaurant (since 1997) in a converted house on the Panjim–Miramar road, run entirely by women. Dedicated to preserving near-extinct Goan recipes collected from mothers across Goa — pomfret recheado, xac xac, bimbli curries — with a full bar.', '1.5 hours', 'Year-round', 'Book ahead for weekends; try the recheado preparations and homemade bebinca.', 'Reservations recommended for dinner/weekends (+91 98221 75559).', 'Goa', 0, 0, NULL, NULL, 'Rs. 1,500 – Rs. 2,000 (published TripAdvisor price range)', 5, 5, 15.4827, 73.8075, '854, Martins Building, D.B. Marg, Miramar, Panaji, Goa 403001', NULL, 1.0);

