INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000024, 331001, 'Viva Panjim', 'Viva Panjim Family Restaurant and Bar', 'Family-run Goan restaurant in a 150-year-old Indo-Portuguese heritage home in Fontainhas'' Latin Quarter. Serves old Goan recipes — pork sorpotel, vindaloo, cafreal, butter-garlic squid, serradura — on a quiet veranda. Cozy, authentic and affordable.', '1-1.5 hours', 'Year-round (evening)', 'Walk to Rua 31 de Janeiro in Fontainhas behind Mary Immaculate High School; evenings are the best experience.', NULL, 'Goa', 0, 0, NULL, NULL, NULL, 5, 5, 15.4965, 73.83131, 'H.No. 178, Rua 31 de Janeiro, Behind Mary Immaculate High School, Fontainhas, Panaji, Goa 403001', 'http://www.vivapanjim.com/', 1.0);

