INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000025, 331001, 'The Fisherman''s Wharf, Panjim', 'The Fisherman''s Wharf, Panjim', 'The Panjim outpost of Goa''s well-known seafood chain (originally on the River Sal at Mobor, since 2005), set in a heritage home at Campal with oyster-shell windows and bamboo decor. Goan seafood classics — stuffed crabs, lobster, prawn balchão, cafreal — plus live music, a bar and riverside ambience.', '1.5 hours', 'Year-round (evening)', 'Ask for an outdoor table; live music nights are the liveliest. Good pick for a special dinner.', NULL, 'Goa', 0, 0, NULL, NULL, NULL, 4, 4, 15.4942, 73.8288, 'House No 13, 139, 18th June Rd, Beside Taj Vivanta, Campal, Panaji, Goa 403001', 'https://www.thefishermanswharf.in/', 0.8);

