INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3310001, 331, 331001, 'Goa Carnival', 'Feb', 'Goa''s famous pre-Lent street carnival; Panaji hosts the main float parade led by King Momo (in 2026 the Panaji grand parade ran on Feb 14, from New Patto Bridge to Campal Ground). Colourful floats, music bands and dance troupes across the city.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3310002, 331, 331001, 'Shigmo Festival', 'Mar', 'Goa''s spring harvest festival with vibrant folk dances, traditional music and colourful float parades; Panaji hosts one of the state''s biggest parades (in 2026 the Panaji parade was on March 7, part of a March 5-18 statewide celebration across 19 centres).');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3310003, 331, 331001, 'Feast of St. Sebastian', 'Jan', 'Annual parish feast of Fontainhas'' Chapel of St. Sebastian, celebrated on 20 January with community festivities around the chapel.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3310004, 331, 331001, 'Feast of Our Lady of Livrament', 'Nov', 'Mid-November street fair outside the Chapel of St. Sebastian in Fontainhas, celebrating the Feast of Our Lady of Livrament.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3310005, 331, 331001, 'Sao Joao', 'Jun', 'Monsoon festival honouring St. John the Baptist, celebrated across Goa (including Panaji) on June 24 with the tradition of young men jumping into wells and rivers; linked to the onset of the monsoon.');

