INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000027, 331002, 'Church of the Holy Spirit', 'Church of the Holy Spirit', 'Margao''s grandest landmark church, first built by Jesuit missionaries in 1564, destroyed in 1571 and rebuilt from 1645 in Indo-Baroque style. Its white façade, gilt-and-crystal interiors and pipe organ make it one of Goa''s finest churches, dominating the Largo da Igreja (Church Square) at the city''s entrance.', '30-45 minutes', 'Oct-Mar', 'Visit outside mass times if you want quiet interior viewing; dress respectfully. The annual feast falls around Pentecost (May).', NULL, 'Goa', 0, 0, NULL, NULL, NULL, 5, 5, 15.2773, 73.9614, 'Holy Spirit Rd, Borda, Margao, Goa 403601', NULL, 1.0);

