INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000028, 331002, 'Monte Hill and Chapel of Our Lady of Piety', 'Monte Hill and Chapel of Our Lady of Piety', 'A 19th-century chapel (built 1820, dedicated to Our Lady of Piety/Nossa Senhora da Piedade) crowning Monte Hill, Margao''s highest point. The chapel is often locked, but the hilltop is the city''s classic viewpoint with a bird''s-eye panorama over Margao and the Salcete countryside.', '45 minutes-1 hour', 'Oct-Mar', 'Go at sunset for the best light and views; the serpentine drive up Padre Miranda Road is steep and narrow.', NULL, 'Goa', 0, 0, NULL, NULL, NULL, 4, 4, 15.284, 73.9805, 'Padre Miranda Rd, Monte Hill, Margao, Goa 403601', NULL, 0.8);

