INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000029, 331002, 'Margao Municipal Market (Mercado de Afonso de Albuquerque)', 'Margao Municipal Market', 'South Goa''s busiest and most colourful market, the covered Mercado de Afonso de Albuquerque (locally ''Pimplapedd'') plus the old Mercado Velho, selling fresh fish and produce, spices, textiles and Goan handicrafts. The best place in Margao to see everyday Goan life unfold.', '1-2 hours', 'Oct-Mar', 'Come in the morning for the fish and produce action; bargain politely. Pick up kokum, Goan sausages (chorizo) and bebinca from the food stalls.', NULL, 'Goa', 0, 0, NULL, NULL, NULL, 5, 4, 15.2723, 73.9634, 'Near Gandhi Market Rd, Margao, Goa 403601', NULL, 0.92);

