INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000030, 331002, 'Municipal Garden (Praça Jorge Barreto)', 'Municipal Garden (Praça Jorge Barreto)', 'The colonial-era Municipal Garden (Praça Jorge Barreto) at the heart of town, flanked by the red-washed 1905 Municipal building and library; its northern section was developed by the Aga Khan. A shaded green break between Margao''s restaurants and offices, directly opposite Our Lady of Grace Church.', '30 minutes', 'Oct-Mar', 'Combine with Longuinhos, Café Tato or Our Lady of Grace Church, all within a short walk of the garden.', NULL, 'Goa', 0, 0, NULL, NULL, NULL, 3, 3, 15.2758, 73.9602, 'Margao, Goa 403601', NULL, 0.6);

