INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000031, 331002, 'Colva Beach', 'Colva Beach', 'The closest and liveliest beach to Margao (~6 km), a long powder-white stretch lined with coconut palms, beach shacks and watersports operators. A family favourite with parasailing, jet-skiing and sunset promenades; the sea meets the Assolna river at Mobor at its southern end.', 'Half day', 'Oct-Mar', 'Watersports run roughly 9 AM-6 PM; the stretch near Mobor is quieter. Watch for shack touts; swim only where lifeguards are posted.', NULL, 'Goa', 0, 0, NULL, NULL, NULL, 5, 4, 15.2763, 73.921, 'Colva, Salcete, Goa 403708', NULL, 0.92);

