INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000032, 331002, 'Benaulim Beach', 'Benaulim Beach', 'A quieter, golden-sand beach just south of Colva (~7-8 km from Margao), favoured by those escaping the crowds. Gentle waves, fishing boats and a sleepy village behind the dunes make it ideal for long walks and calm swimming.', 'Half day', 'Oct-Mar', 'Combine with a visit to Goa Chitra museum, which sits just inland in Benaulim village.', NULL, 'Goa', 0, 0, NULL, NULL, NULL, 4, 4, 15.2576, 73.91, 'Benaulim, Salcete, Goa 403716', NULL, 0.8);

