INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000033, 331002, 'Sernabatim Beach', 'Sernabatim Beach', 'A serene, less-commercialised white-sand beach between Colva and Benaulim (~7 km from Margao). Fringed by coconut palms with few shacks, it suits visitors seeking quiet over action.', '2-3 hours', 'Oct-Mar', 'Carry water and snacks — facilities are minimal compared to Colva. Best in the morning before the breeze picks up.', NULL, 'Goa', 0, 0, NULL, NULL, NULL, 3, 4, 15.2533, 73.9077, 'Sernabatim, Salcete, Goa 403708', NULL, 0.68);

