INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000034, 331002, 'Menezes-Braganza House', 'Menezes-Braganza House', 'A 450-year-old Indo-Portuguese mansion on Chandor''s village square (~13-15 km east of Margao), among the largest colonial homes in Goa. Two wings (Menezes Braganza and Braganza Pereira) hold Belgian chandeliers, rosewood furniture, Chinese porcelain, Italian marble floors and a chapel relic of St. Francis Xavier.', '1-1.5 hours', 'Oct-Mar', 'The family members often guide the tour themselves — the stories are the highlight. Call ahead, as the house is a private residence.', 'Call ahead (+91 70380 66882) to confirm someone is home for a tour', 'Goa', 0, 0, NULL, NULL, 'No fixed entry fee; donations towards upkeep appreciated (suggested ~Rs 50 per person)', 5, 5, 15.261523, 74.043468, 'Guddi-Chandor Rd, Chandor, Salcete, Goa 403714', NULL, 1.0);

