INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000035, 331002, 'Ancestral Goa (Big Foot Museum)', 'Ancestral Goa (Big Foot Museum)', 'An open-air museum recreating a Goan village of a century ago, in Loutolim (~9-10 km from Margao). Highlights include India''s longest laterite sculpture (Sant Mirabai), artisan workshops, a feni distillery demo, spice farm and an audio-guided walk through traditional homes. Across the road is the 19th-century Casa Araujo Alvares (Alvares Mansion).', '1.5-2 hours', 'Oct-Mar', 'Go in the morning or late afternoon to avoid midday heat; the Alvares Mansion opposite is a worthwhile separate visit.', NULL, 'Goa', 0, 0, NULL, NULL, 'Rs 100 per adult, Rs 50 per child (3-10 yrs); Rs 20 still camera, extra for Sound & Light show (Outlook Traveller)', 4, 4, 15.33977, 73.986646, 'Main Rd, Loutolim, Salcete, Goa 403718', NULL, 0.8);

