INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000036, 331002, 'Goa Chitra Museum', 'Goa Chitra Museum', 'An ethnographic museum on an organic farm in Benaulim, curated by artist-restorer Victor Hugo Gomes, with 4,000+ artefacts of Goa''s agrarian life — bullock carts, pottery, palanquins, lanterns and old farm implements. Guided tours explain traditional Goan technology and rural lifestyle.', '1-2 hours', 'Oct-Mar', 'Take a taxi and ask the driver to wait — return transport is hard to find. Guided tours are included in the ticket.', NULL, 'Goa', 0, 0, NULL, NULL, 'Rs 100 Indian adults, Rs 300 foreign nationals, Rs 50 students and senior citizens (holidaylandmark.com)', 4, 4, 15.264864, 73.941477, 'St. John the Baptist Church Rd, Mondo-Waddo, Benaulim, Salcete, Goa 403716', NULL, 0.8);

