INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000037, 331002, 'Pandit Jawaharlal Nehru Stadium (Fatorda Stadium)', 'Pandit Jawaharlal Nehru Stadium (Fatorda Stadium)', 'Goa''s principal football stadium (~15,000+ capacity) in Fatorda, home to FC Goa and the national team''s former home ground. Matchdays bring a rare electric atmosphere to South Goa''s sporting calendar.', '2-3 hours (match)', 'Sep-May (football season)', 'Check FC Goa / ISL fixtures in advance — a match night here is the experience, the stadium itself isn''t a walk-in attraction.', NULL, 'Goa', 0, 0, NULL, NULL, NULL, 3, 3, 15.2847, 73.9614, 'Fatorda, Margao, Goa 403602', NULL, 0.6);

