INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000038, 331002, 'Ravindra Bhavan', 'Ravindra Bhavan', 'South Goa''s principal cultural complex (est. 2008), run by the Goa Directorate of Art & Culture. It houses the 1,069-seat Pai Tiatrist Joao Agostinho Fernandes auditorium, a conference hall, black-box theatre and open-air stage, hosting tiatr, theatre, concerts, poetry slams and exhibitions.', '2-3 hours (event)', 'Year-round', 'Check the Facebook page ''RavindraBhavanMargao'' for the month''s programme — tiatr performances are the most authentically Goan.', 'Event tickets are usually sold at the venue or via event organisers; check the centre''s event calendar', 'Goa', 0, 0, NULL, NULL, NULL, 3, 4, 15.285389, 73.962951, 'Opposite Swimming Pool, Fatorda, Margao, Goa 403602', NULL, 0.68);

