INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000039, 331002, 'Our Lady of Grace Church', 'Our Lady of Grace Church', 'A modern circular church (built 1970, once a military chapel) opposite the Municipal Garden, famed for its colourful mosaic murals, mosaic-lined interior and its Goan snack vendors around the entrance steps. Celebrates its annual feast on the first Sunday of February.', '30 minutes', 'Oct-Mar', 'Visit around morning mass times for the local Goan snacks sold by vendors near the entrance.', NULL, 'Goa', 0, 0, NULL, NULL, NULL, 3, 4, 15.273416, 73.958933, 'Isidorio Baptista Rd, Pajifond, Margao, Goa 403601', 'https://www.gracechurchmargao.com/', 0.68);

