INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000043, 331002, 'Pandava Caves (Aquem)', 'Pandava Caves', 'A compact 6th-century rock-cut cave behind St. Sebastian''s Church in Aquem, believed to be of Buddhist origin — a rare pre-Portuguese relic inside a modern Goan city. A short, curiosity-driven stop rather than a full outing.', '20 minutes', 'Oct-Mar', 'Combine with the neighbouring St. Sebastian Church; the caves are small and take only minutes.', NULL, 'Goa', 0, 0, NULL, NULL, NULL, 2, 3, 15.2742, 73.9835, 'Aquem, Margao, Goa 403601', NULL, 0.48);

