INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000044, 331002, 'St. Sebastian Church (Aquem)', 'St. Sebastian Church', 'The parish church of Aquem suburb, standing next to the old St. Sebastian Chapel (popularly the ''Pandava Copel''). A working neighbourhood church with a calm courtyard, representative of Margao''s Catholic parish life.', '20-30 minutes', 'Oct-Mar', 'Visit together with the Pandava Caves directly behind it.', NULL, 'Goa', 0, 0, NULL, NULL, NULL, 2, 3, 15.2735, 73.985, 'Aquem, Margao, Goa 403601', NULL, 0.48);

