INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000045, 331002, 'Cabo de Rama Fort', 'Cabo de Rama Fort', 'A medieval clifftop fort ~20-30 km south of Margao, taken by the Portuguese in the 1760s and later used as a prison until 1955. Ruined ramparts, rusting cannons and a working chapel (Capela de Santo António) overlook the Arabian Sea with sweeping views up the coast towards Colva.', '2 hours', 'Oct-Mar', 'Go by scooter or taxi; the sunset views over the cliffs are the payoff. The site is partly inhabited — respect the seminary/church area.', NULL, 'Goa', 0, 0, NULL, NULL, 'Entry generally free (traveloka.com)', 4, 4, 15.08806, 73.91991, 'Cabo de Rama, Canacona, South Goa, Goa 403702', NULL, 0.8);

