INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000047, 331002, 'Longuinhos Bar, Restaurant & Confectioners', 'Longuinhos Bar, Restaurant & Confectioners', 'Since 1950, Margao''s most famous institution: a vintage Goan bar-restaurant opposite the Municipal Council with wood panelling, an art-deco logo and a former Portuguese-era billiards hall (now the AC section). Famous for chorizo scrambled eggs, pork sorpotel, Goan sausage rolls and early-morning samosas; the confectionery counter does takeaway pastries.', '1 hour', 'Year-round', 'Go early in the morning for the famous samosas — they sell out fast. Order at your table, not the counter, for quicker service.', NULL, 'Goa', 0, 0, NULL, NULL, '~Rs 1,000 for two (Justdial)', 5, 4, 15.271978, 73.957679, 'Dr Antonio Dias Building, Opp Municipality Office, Luis Miranda Rd, Margao, Goa 403601', NULL, 0.92);

