INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000048, 331002, 'Martin''s Corner', 'Martin''s Corner', 'A landmark open-air Goan seafood restaurant in Betalbatim village (~8 km from Margao), famous for its king crab masala, xacuti, chonak recheado and feni cocktails like the Martin''s Special, with live music in season. Widely cited as the quintessential South Goa Goan dining experience.', '1.5-2 hours', 'Oct-Mar', 'Weekend evenings are packed and parking is limited — arrive early or book. Try the bebinca with ice cream for dessert.', 'Booking accepted; recommended on weekends', 'Goa', 0, 0, NULL, NULL, '~Rs 1,600 for two approx (EazyDiner)', 5, 5, 15.303789, 73.914293, '69, Binwaddo, Betalbatim, Salcete, Goa 403713', NULL, 1.0);

