INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000049, 331002, 'Cafe Tato', 'Cafe Tato', 'A beloved old-style Margao café opposite the Municipal Garden, known for filter coffee, bhaji pav, misal pav and South/North Indian thalis. Its fish thali upstairs and vegetarian counter downstairs make it a local lunch institution.', '45 minutes-1 hour', 'Year-round', 'Morning breakfast (misal pav, chai) is the highlight; it''s always busy — expect quick but no-frills service.', NULL, 'Goa', 0, 0, NULL, NULL, 'Budget: ~Rs 150-400 per person (Justdial, restaurant-guru)', 4, 4, 15.2762, 73.9606, 'Apna Bazaar Complex, Valaulikar Rd, Opp Margao Municipal Garden, Margao, Goa 403601', NULL, 0.8);

