INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000050, 331002, 'Alcove''s Restaurant & Bar', 'Alcove''s Restaurant & Bar', 'A small twin-level Goan-Chinese eatery near Cine Vishant in Pajifond, praised for homely pork vindaloo, chicken xacuti, pork sausage chilli fry and butter chicken at honest prices. A local favourite for unpretentious Goan bar-food dining.', '1 hour', 'Year-round', 'It''s a tiny ~25-seat place — arrive before the dinner rush for a table.', NULL, 'Goa', 0, 0, NULL, NULL, NULL, 3, 4, 15.271533, 73.96711, 'Shop No 3, Vishant Rd, Pajifond, Margao, Goa 403601', NULL, 0.68);

