INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3310006, 331, 331002, 'Margao Carnival', 'Feb', 'Goa''s pre-Lent street carnival; Margao''s float parade runs from Holy Spirit Church to the Margao Municipal Council Square, one of the state''s biggest south-Goa celebrations. In the 2026 edition the Margao parade fell on 15 February.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3310007, 331, 331002, 'Feast of Our Lady of Grace Church', 'Feb', 'Annual feast of Margao''s modern landmark church (built 1970), celebrated on the first Sunday of February with masses, processions and community feasts.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3310008, 331, 331002, 'Shigmo', 'Mar', 'Goa''s traditional spring harvest festival with colourful float parades, folk dance and music; Margao hosts one of the state-level Shigmo parades (5-18 March in 2026).');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3310009, 331, 331002, 'Feast of the Holy Spirit Church', 'May', 'Annual parish feast of Margao''s landmark 17th-century church, celebrated around Pentecost (reported as Sunday 15 May in recent coverage) with concelebrated feast mass and parish celebrations.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3310010, 331, 331002, 'São João', 'Jun', 'Catholic monsoon festival (24 June) celebrated across Salcete/Margao with the tradition of jumping into wells and rivers; neighbourhood processions and feasting.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3310011, 331, 331002, 'Ganesh Chaturthi', 'Aug-Sep', 'Major Hindu festival celebrated widely across Goa; Margao sees large public pandals, immersion processions and household celebrations.');

