INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000053, 331003, 'Naval Aviation Museum', 'Indian Naval Aviation Museum', 'Asia''s only naval aviation museum, set on a hillock at Bogmalo a few km from Vasco. The outdoor park displays 13 decommissioned aircraft including the Sea Harrier, Sea Hawk and Sea King, while the indoor gallery covers the history of the Indian Naval Air Arm with armaments, uniforms and photographs.', '2 hours', 'Oct-Mar', 'Wear comfortable shoes for the outdoor aircraft park; carry a photo ID as it is a naval installation area.', NULL, 'Goa', 0, 0, NULL, NULL, 'INR 50 adults, INR 30 children', 5, 4, 15.374808, 73.83893, 'Bogmalo Road, Bogmalo, Mormugao, Goa 403806', NULL, 0.92);

