INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000054, 331003, 'Bogmalo Beach', 'Bogmalo Beach', 'A small, curving bay about a mile of sandy beach just outside Vasco, near Dabolim airport. Calm, family-friendly waters with shacks, water sports and scuba diving operators, and good sunset views.', '2-3 hours', 'Oct-Mar', 'One of the cleanest beaches near Vasco; shacks serve fresh seafood. Combine with the Naval Aviation Museum next door.', NULL, 'Goa', 0, 0, NULL, NULL, NULL, 5, 4, 15.37352, 73.82113, 'Bogmalo, Mormugao, Goa 403806', NULL, 0.92);

