INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000055, 331003, 'Mormugao Fort', 'Fort of Mormugao', 'A ruined 1624 Portuguese coastal fort on the headland above Mormugao harbour, built on orders of Viceroy Dom Francisco da Gama to defend the Zuari river mouth. Little survives beyond ramparts, bastions, a restored cross and a wall chapel, but the views over the harbour, ships and sea are striking.', '1 hour', 'Oct-Mar', 'Reach it via the lane to the right of the MPT Sagarmala gate; log personal details at the gate. Visit alongside Pilot Point, ~500 m away.', NULL, 'Goa', 0, 0, NULL, NULL, NULL, 4, 3, 15.40943, 73.79486, 'Alto Desterro, Sada, Vasco da Gama, Goa 403804', NULL, 0.72);

