INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000056, 331003, 'Japanese Garden', 'Japanese Garden, Sada', 'A landscaped garden atop the Sada headland near the Mormugao fort ruins, built in collaboration with Japan. Terraced lawns and paths open to panoramic views of the Arabian Sea, harbour and Grandmother''s Hole beach below; a popular evening sunset spot.', '1-2 hours', 'Oct-Mar', 'Go at sunset for the best views; combine with the fort ruins and the beach below the garden.', NULL, 'Goa', 0, 0, NULL, NULL, NULL, 4, 4, 15.40771, 73.78657, 'C Type Road, Mormugao-Headland Sada, Vasco da Gama, Goa 403804', NULL, 0.8);

