INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000064, 331003, 'Vasco Municipal Market', 'Vasco da Gama Municipal Market', 'Vasco''s bustling central market on Swatantra Path, selling fresh fish and seafood, spices, produce, Goan sweets and household goods. A lively slice of everyday Goan town life and a good place to taste the local flavours.', '1-2 hours', 'Year-round', 'Go in the morning when the fish section is at its liveliest; the market gets especially busy during Vasco Saptah week.', NULL, 'Goa', 0, 0, NULL, NULL, NULL, 3, 3, 15.39652, 73.81, 'Swatantra Path, Vasco da Gama, Goa 403802', NULL, 0.6);

