INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000066, 331003, 'Shri Damodar Temple', 'Shri Damodar Temple, Vasco', 'The small Damodar temple in Vaddem, Vasco, which is the main venue of the annual Vasco Saptah festival. It houses the sacred coconut brought from the Shri Damodar Sansthan at Zambaulim in 1898, commemorating the end of the epidemic that gave rise to the Saptah.', '30 minutes', 'Jul-Aug', 'Visit on a Monday or Thursday evening around 9 pm when lamps are lit and devotional songs are sung; it is at its most vibrant during Saptah week in Shravan.', NULL, 'Goa', 0, 0, NULL, NULL, NULL, 3, 3, 15.39886, 73.82533, 'New Vaddem Road, Vaddem, Vasco da Gama, Goa 403802', NULL, 0.6);

