INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000067, 331003, 'Pilot Point', 'Pilot Point Viewpoint', 'An open roadside viewpoint on the uphill Mormugao Port Trust road with sweeping views of Mormugao harbour, cargo ships being loaded and unloaded, and part of Vasco town. Simple and unmaintained, but a good photo and sunset stop.', '30 minutes', 'Oct-Mar', 'Easy roadside parking; combine with the Mormugao Fort ruins about 500 m away.', NULL, 'Goa', 0, 0, NULL, NULL, NULL, 3, 3, 15.39798, 73.81127, 'F L Gomes Road / Mormugao Port Trust Road, Vasco da Gama, Goa 403802', NULL, 0.6);

