INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 331000067, 'insert', 'bulk', 'Verified via multiple Tripadvisor reviews describing it as the Mormugao port viewpoint with benches and steel rails, ~500 m walk from Mormugao Fort. Geocode match ''Pilot Point, F L Gomes Road'' at 15.39798, 73.81127.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000068, 331003, 'Mormugao Harbour', 'Mormugao Port Harbour', 'One of India''s oldest and most important ports, dominating the Vasco waterfront with container ships, ore carriers and the breakwater. The harbour road area offers views of port operations and the sea; cruise boats and dolphin trips also depart from the harbour side.', '1 hour', 'Oct-Mar', 'The harbour itself is a working port — enjoy views from Harbour Road and Pilot Point; boat trips to Grand Island and dolphin-watching leave from nearby jetties.', NULL, 'Goa', 0, 0, NULL, NULL, NULL, 3, 3, 15.40157, 73.80456, 'Harbour Road, Vasco da Gama, Goa 403803', NULL, 0.6);

