INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 331000068, 'insert', 'bulk', 'Mormugao Port''s significance verified via Wikipedia (Mormugao) and TripXL''s Vasco attractions guide. Geocoder returned street-level match on Harbour Road (15.40157, 73.80456); coords are approximate to the harbour viewing area.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000069, 331003, 'Grand Island Boat Trips', 'Grande Island (Ilha Grande) Boat Trips', 'Day-long boat excursions from the Vasco/Mormugao coast to Grande Island (Ilha Grande), a small rocky island in the Arabian Sea west of Vasco. Packages typically include dolphin spotting en route, snorkeling, fishing, a BBQ lunch at Monkey Beach and sometimes scuba diving.', 'Full day', 'Oct-Apr', 'Book through a reputable operator; trips usually start around 8-9 am and include meals. Sea can be rough — carry motion-sickness tablets.', 'Recommended in peak season (Dec-Jan)', 'Goa', 0, 0, NULL, NULL, 'Packages typically around INR 1,400-2,000 per person including boat, meals and activities', 5, 4, 15.344, 73.791, 'Boat trips depart from jetties around Mormugao/Vasco and Sancoale', NULL, 0.92);

