INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 331000069, 'insert', 'bulk', 'Island and trip details verified via goavilla.co.uk (''small rocky island just off the coast of Dabolim airport... west of Vasco da Gama in the Mormugao peninsula''), touristinindia.com (package ~INR 2000) and Wanderlog reviews. Coords 15.344, 73.791 are an approximate offshore position of the island west of the Mormugao peninsula; exact island coords could not be pinpointed from a published source, so treat as approximate. Departure jetties are around Vasco/Sancoale/Coco Jetty.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000070, 331003, 'St Jacinto Island', 'Sao Jacinto Island', 'A small, forested inhabited island in the Zuari estuary near Dabolim, connected to the mainland by a causeway. It has an old white church dedicated to St Hyacinth, a defunct Portuguese-era lighthouse and quiet village lanes; residents have long resisted outside development, keeping it green and tranquil.', '1-2 hours', 'Oct-Mar', 'It is a residential village — be respectful, keep noise down and do not litter; the island has an annual church feast on the last Sunday of September.', NULL, 'Goa', 0, 0, NULL, NULL, NULL, 4, 4, 15.4061, 73.8635, 'Sao Jacinto Island, Zuari estuary, Mormugao, Goa', NULL, 0.8);

