INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000071, 331003, 'Goa Kayaking', 'Goa Kayaking - Zuari River', 'Vasco-based eco-tourism operator (est. 2009) running guided kayaking expeditions on the Zuari river, mangroves and backwaters near Chicalim and Sao Jacinto Island. Trips are typically 2-3.5 hours in the morning, tide-dependent, with equipment included.', '3 hours', 'Oct-Apr', 'Trips are tide-dependent, so confirm the day''s launch time when booking; mornings are calmest. Book directly via their website or phone.', 'Recommended — trips depend on tides and group size', 'Goa', 0, 0, NULL, NULL, NULL, 4, 5, 15.395232, 73.833166, 'No. 6, Plot No. 721/A, Airport Road, Chicalim, Goa 403711', 'http://www.goakayaking.com/', 0.88);

