INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000072, 331003, '1930 Vasco Mall', '1930 Vasco Mall', 'Vasco''s main shopping mall on Swatantra Path in Vaddem, with fashion stores (Fabindia, Unlimited), jewellery, a K Sera Sera miniplex cinema, dining outlets and a gym. The town''s central retail and entertainment hub.', '2 hours', 'Year-round', 'Useful for a rainy-day break; the miniplex is handy for an evening movie.', NULL, 'Goa', 0, 0, NULL, NULL, NULL, 2, 3, 15.39771, 73.83051, 'Swatantra Path, Opposite The HQ Hotel, Vaddem, Vasco da Gama, Goa 403802', NULL, 0.48);

