INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3310012, 331, 331003, 'Vasco Saptah', 'Jul-Aug', 'Vasco''s signature week-long festival, held from the 6th day of the Hindu month of Shravan. Commemorates the 1898/1899 epidemic believed to have been ended by Lord Damodar''s blessings; features 24-hour non-stop bhajans, a tableau procession, nightly cultural programmes and a large mela fair along Swatantra Path, with the Shri Damodar Temple in Vaddem as the main venue.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3310013, 331, 331003, 'Feast of St Andrew', 'Nov', 'Patronal feast of Vasco''s St Andrew''s Church on 30 November, celebrated with novenas, a feast mass and processions through the town, drawing the city''s Catholic community.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3310014, 331, 331003, 'Goa Carnival', 'Feb', 'Goa''s pre-Lent street carnival, celebrated across the state including Vasco, with float parades, music, dance and the King Momo procession in the days before Ash Wednesday.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3310015, 331, 331003, 'Shigmo', 'Mar', 'Goa''s spring folk festival of colours, celebrated with street parades of floats, traditional folk dances and gulal, observed in towns across Goa including Vasco.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3310016, 331, 331003, 'Sao Joao', 'Jun', 'The Catholic monsoon festival honouring St John the Baptist, celebrated across Goa with young men jumping into wells and streams, feni, and festive processions; observed in Vasco''s Catholic neighbourhoods.');

