INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000079, 331004, 'Mapusa Friday Market (Mapusa Municipal Market)', 'Mapusa Friday Market', 'Mapusa''s famous Friday market is the commercial heartbeat of North Goa, where vendors from across Goa and neighbouring states sell spices, cashew nuts, dried fish, Goan chorizo sausages, toddy and feni, fresh produce, pottery, textiles and handicrafts. While the market functions daily, Fridays are the main market day with the full buzz, bargaining and the widest variety of goods.', '1-2 hours', 'Oct-Mar, Friday mornings', 'Arrive early on Friday for the full market; carry cash, bargain politely, and try the local Goan sausages, bebinca and cashew feni stalls.', NULL, 'Goa', 0, 0, NULL, NULL, 'Entry free', 5, 4, 15.58917, 73.81213, 'Municipal Market, Market Road, Mapusa, Goa 403507', NULL, 0.92);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (331000079, 331000079, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Sun 7:00 AM-8:00 PM; Mon-Sat 9:00 AM-8:30 PM (per Wanderlog/LBB listings); the full Friday bazaar atmosphere is best in the morning');

