INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000080, 331004, 'Mapusa Municipal Fish Market', 'Mapusa Municipal Fish Market', 'The dedicated fish market inside the Mapusa municipal complex is where locals buy the day''s catch: fresh fish, prawns, crabs, lobster and dried fish alongside pottery and handicrafts stalls. It is a lively, sensory slice of everyday Goan life, best visited in the morning when the catch arrives.', '30-45 minutes', 'Oct-Mar, mornings', 'Go in the morning for the freshest catch and watch the fast-paced bargaining; the dried-fish section is a local specialty.', NULL, 'Goa', 0, 0, NULL, NULL, NULL, 3, 4, 15.58823, 73.81296, 'Municipal Complex, Anjuna-Mapusa Road, Mapusa, Goa 403507', NULL, 0.68);

