INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000081, 331004, 'St. Jerome Church (Our Lady of Miracles / Milagres Church)', 'St. Jerome Church', 'St. Jerome Church, founded in 1594 by Franciscan priest Fr. Jeronimo do Espirito Santo and rebuilt several times since, is Mapusa''s principal Catholic church and one of Goa''s oldest parishes. Its Baroque facade, three altars and golden altar work draw devotees year-round, and it is better known locally as the Church of Our Lady of Milagres (Miracles) for its miracle-granting shrine.', '30-45 minutes', 'Oct-Mar', 'Dress modestly; visit during the Milagres Feast (15 days after Easter) to see the church at its most festive, but expect large crowds.', NULL, 'Goa', 0, 0, NULL, NULL, NULL, 4, 4, 15.5896, 73.81937, 'Market Road, Angod, Mapusa, Goa 403507', NULL, 0.8);

