INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000082, 331004, 'Shri Dev Bodgeshwar Sansthan (Bodgeshwar Temple)', 'Shri Dev Bodgeshwar Sansthan', 'Shri Dev Bodgeshwar Sansthan, dedicated to Kanakeshwar Baba (locally Bodgeshwar or Angavani, the wish-fulfilling deity), is Mapusa''s most famous Hindu shrine, set amid paddy fields at the town''s entrance. The temple, built around an ancient banyan tree and beautifully lit at night, is regarded as the guardian of Mapusa and draws thousands for its annual January zatra.', '45 minutes-1 hour', 'Oct-Mar; evenings for the lit-up temple', 'Visit in the evening when the temple is illuminated; remove footwear before entering the sanctum and dress modestly.', NULL, 'Goa', 0, 0, NULL, NULL, NULL, 5, 4, 15.58578, 73.80526, 'Calangute-Mapusa Road, Mapusa, Goa 403507', NULL, 0.92);

