INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000083, 331004, 'Shree Maruti Mandir (Dhular, Mapusa)', 'Shree Maruti Mandir', 'Shree Maruti Mandir is Mapusa''s local Hanuman temple, serving the Dhular/Dangui Colony neighbourhood on the town''s western edge. It is a quiet neighbourhood shrine popular with local devotees, especially on Tuesdays and Saturdays which are considered auspicious for Hanuman worship.', '20-30 minutes', 'Oct-Mar', 'A neighbourhood temple rather than a tourist sight; combine with the nearby Duler Stadium area. Note this is distinct from the famous Maruti Temple on Altinho hill in Panaji.', NULL, 'Goa', 0, 0, NULL, NULL, NULL, 3, 3, 15.60032, 73.79903, 'Xelpem, Dangui Colony, Dhular, Balkrishna Bhosale Marg, Mapusa, Goa 403507', NULL, 0.6);

