INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000084, 331004, 'Duler Stadium (Duler Football Stadium)', 'Duler Stadium', 'Duler Stadium, officially Duler Football Stadium, is a 10,000-capacity AstroTurf football ground in Mapusa owned by the Goa Football Association. It hosts Goa Professional League matches and was once home to clubs like Dempo, Salgaocar and Sporting Goa; locals also use it for morning walks and exercise.', '1-2 hours (match)', 'Oct-Mar; match evenings', 'Check the Goa Football Association''s Goa Professional League schedule if you want to catch a live match; carry sun protection as spectator stands have little shade.', NULL, 'Goa', 0, 0, NULL, NULL, NULL, 3, 4, 15.59849, 73.81615, 'Duler Ground Road, Dangui Colony, Duler, Mapusa, Goa 403507', NULL, 0.68);

