INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000090, 331004, 'The Attic (Gallery Attic)', 'The Attic (Gallery Attic)', 'The Attic (Gallery Attic) is an art gallery and antiques space in Camarcazana near Mapusa, housed in an old titled Goan bungalow. It displays contemporary Goan art alongside painstakingly restored old Goan furniture, curios, glassware and wrought-iron artefacts — described by visitors as a trip back in time into Goa''s material heritage.', '45 minutes-1 hour', 'Oct-Mar', 'Call ahead to confirm opening hours before visiting; the gallery doubles as an antiques shop, so browse the restored furniture section.', NULL, 'Goa', 0, 0, NULL, NULL, NULL, 3, 4, 15.60259, 73.83019, 'H. No. 69, Near Mount Carmel Chapel, Camarcazana (Karaswaddo), Mapusa, Goa', 'http://www.galleryattic.com/', 0.68);

