INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000091, 331004, 'Saibaba Temple (Verla-Canca)', 'Saibaba Temple', 'The Saibaba Temple at Verla-Canca is a popular local shrine on Mapusa''s western fringe, near the road towards Canca and Parra. It draws steady local devotion, particularly on Thursdays which are sacred to Sai Baba.', '30 minutes', 'Oct-Mar; Thursdays', 'Thursday evenings see the most devotees; remove footwear before entering.', NULL, 'Goa', 0, 0, NULL, NULL, NULL, 3, 3, 15.58911, 73.7983, 'Demello Waddo, Canca, Verla-Canca, Mapusa, Goa 403510', NULL, 0.6);

