INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000092, 331004, 'St. Diogo Church (Guirim)', 'St. Diogo Church', 'St. Diogo Church in Guirim, founded in 1604 and shared between the villages of Guirim and Sangolda, is one of the oldest churches in Bardez — the 13th of the 24 churches erected in the taluka. Its main altar is dedicated to patron St. Diogo with ornate side altars, three bells (two claimed by Sangolda, one by Guirim, per local legend) and a major renovation for its 400th anniversary in 2004.', '30-45 minutes', 'Oct-Mar', 'About 2 km from Mapusa on the national highway; the feast of St. Diogo is celebrated on November 14.', NULL, 'Goa', 0, 0, NULL, NULL, NULL, 3, 4, 15.56169, 73.80315, 'Guirim, Bardez, Goa 403507', NULL, 0.68);

