INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000093, 331004, 'St. Anne''s Church (Parra)', 'St. Anne''s Church', 'St. Anne''s Church in Parra shot to fame as the church featured in the Bollywood film Dear Zindagi, and its whitewashed facade against swaying palms is now one of North Goa''s most photographed churches. The parish church of Parra village, it sits at the start of the famous coconut-tree-lined road.', '30 minutes', 'Oct-Mar', 'Combine with the Parra coconut tree road right beside it; early morning light is best for photographs.', NULL, 'Goa', 0, 0, NULL, NULL, NULL, 4, 4, 15.57897, 73.7795, 'Parra, Bardez, Goa 403510', NULL, 0.8);

