INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000094, 331004, 'Parra Coconut Tree Road (Dear Zindagi Road)', 'Parra Coconut Tree Road', 'The coconut-tree-lined road through Parra village — popularised as the ''Dear Zindagi road'' after the film shot scenes here — is North Goa''s most famous Instagram spot, with towering palms forming a green canopy over the lane. Travellers stop here for photos, especially at golden hour.', '20-30 minutes', 'Oct-Mar, early morning or late afternoon', 'Park safely off the narrow road and be mindful of traffic while taking photos; combine with St. Anne''s Church.', NULL, 'Goa', 0, 0, NULL, NULL, NULL, 4, 4, 15.5805, 73.7812, 'Parra-Guirim Road, Parra, Bardez, Goa', NULL, 0.8);

