INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000095, 331004, 'Our Lady of Health Chapel', 'Our Lady of Health Chapel', 'Our Lady of Health Chapel is a small chapel in the Mapusa/Duler area, recorded in OpenStreetMap near Faith Community Church and about a kilometre from Duler Stadium. Like Mapusa''s other chapels it is a quiet neighbourhood worship space.', '10-15 minutes', 'Year-round', 'A minor local chapel; of interest mainly to those mapping Mapusa''s many neighbourhood shrines.', NULL, 'Goa', 0, 0, NULL, NULL, NULL, 2, 3, 15.59192, 73.82007, 'Mapusa, Bardez, Goa (near Duler)', NULL, 0.48);

