INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000096, 331004, 'St. Elizabeth Church (Ucassaim)', 'St. Elizabeth Church', 'St. Elizabeth Church is the parish church of Ucassaim village, just east of Mapusa on the Aldona road. A typical Goan village parish church, it anchors the quiet, green village of Ucassaim.', '20 minutes', 'Year-round', 'Combine with a drive through the green Ucassaim village; the church is a parish church, so visit outside service hours.', NULL, 'Goa', 0, 0, NULL, NULL, NULL, 2, 3, 15.58061, 73.83659, 'Aldona Road, Ucassaim, Bardez, Goa 403507', NULL, 0.48);

