INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000097, 331004, 'Old Municipal Buildings (Altinho, Mapusa)', 'Mapusa Municipal Council Heritage Building', 'The colonial-era municipal buildings on Mapusa''s Altinho hill are among the few Portuguese-period civic structures surviving in the town, now housing the Mapusa Municipal Council. They are a modest heritage sight — best appreciated from the outside as part of a walk around central Mapusa.', '15 minutes', 'Oct-Mar', 'View from outside; the council offices are working government buildings, not a museum.', NULL, 'Goa', 0, 0, NULL, NULL, NULL, 2, 3, 15.59401, 73.8142, 'Hutatma Vinayak Sapte Marg, Altinho, Mapusa, Goa 403507', NULL, 0.48);

