INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000098, 331004, 'Our Lady of Assumption Chapel (Guirim)', 'Our Lady of Assumption Chapel', 'Our Lady of Assumption Chapel is a chapel with its own chaplain within the parish of St. Diogo Church, Guirim. It serves the Guirim village community and, like the parish church, reflects the area''s deep-rooted Catholic heritage.', '15 minutes', 'Year-round', 'A small village chapel; ask locally for directions as it is not signposted for tourists.', NULL, 'Goa', 0, 0, NULL, NULL, NULL, 2, 3, 15.57661, 73.80924, 'Guirim, Bardez, Goa 403507', NULL, 0.48);

