INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000099, 331004, 'Navtara Veg Restaurant', 'Navtara Veg Restaurant', 'Navtara is Mapusa''s go-to pure-vegetarian restaurant, part of a popular Goan chain, known for South Indian staples like benne dosa and idli-vada served from early morning. It is a favourite breakfast and lunch stop for locals and travellers passing through Mapusa.', '45 minutes-1 hour', 'Oct-Mar', 'Go for breakfast — the benne (butter) dosa is the signature order; expect a wait at peak morning hours.', NULL, 'Goa', 0, 0, NULL, NULL, '₹750 for two (JustDial)', 4, 4, 15.58694, 73.80686, 'Swatantryasenani Peter Alwares Marg, Mapusa, Goa 403507', NULL, 0.8);

