INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000100, 331004, 'Kamalabai Sea Food Restaurant', 'Kamalabai Sea Food Restaurant', 'Kamalabai is a well-known seafood restaurant in Khorlim, Mapusa, serving Goan fish preparations — fish thali, fried fish, prawn and crab dishes — at local prices. It is a local favourite for an unpretentious Goan seafood meal away from the beach-shack circuit.', '1 hour', 'Oct-Mar', 'Order the Goan fish thali for the best value; lunch is the main meal here.', NULL, 'Goa', 0, 0, NULL, NULL, '₹1,050 for two (JustDial)', 4, 4, 15.59125, 73.80413, 'Khorlim, Mapusa, Goa 403507', NULL, 0.8);

