INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000101, 331004, 'Soul Curry – Multi Cuisine Restaurant & Bar', 'Soul Curry', 'Soul Curry is a colourful, informal multi-cuisine restaurant and bar at Peddem on the Mapusa highway, serving Goan, North Indian and Chinese dishes plus cocktails. Reviewers recommend the solkadi, spring rolls and aloo paratha with curd; it is a popular family-dining stop on the highway.', '1-1.5 hours', 'Oct-Mar', 'Try the solkadi (kokum cooler) with your meal; easy to reach by car on the highway with parking.', NULL, 'Goa', 0, 0, NULL, NULL, '₹1,200 for two (JustDial)', 4, 4, 15.6036, 73.82506, 'NH66, Peddem, Mapusa, Goa 403507', NULL, 0.8);

