INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000102, 331004, 'Reis Corner', 'Reis Corner', 'Reis Corner is a long-standing eatery on Mapusa''s Market Road, popular with locals for Goan and Indian comfort food at budget prices. It is the kind of no-frills town restaurant where market shoppers stop for lunch.', '45 minutes-1 hour', 'Oct-Mar', 'Combine with a Friday market visit — it is right on Market Road, a short walk from the bazaar.', NULL, 'Goa', 0, 0, NULL, NULL, '₹750 for two (JustDial)', 3, 4, 15.58683, 73.81278, 'Market Road, Mapusa, Goa 403507', NULL, 0.68);

