INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000103, 331004, 'Cremeux (Bakery & Confectionery)', 'Cremeux', 'Cremeux is Mapusa''s beloved bakery and confectionery on Market Road, famous for Goan sweets — bebinca, dodol, coconut sweets, pastries and biscuits. Locals and visitors stock up here on bebinca and other festive treats.', '20-30 minutes', 'Oct-Mar', 'Buy bebinca to take home — it travels well; the shop is busiest in the evenings and before festivals.', NULL, 'Goa', 0, 0, NULL, NULL, '₹550 for two (JustDial); bebinca approx ₹160 (JustDial menu listing)', 4, 4, 15.5906, 73.81222, 'Mapusa Market Road, Mapusa, Goa 403507', NULL, 0.8);

