INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000104, 331004, 'Ruchira Restaurant (Hotel Satyaheera)', 'Ruchira Restaurant', 'Ruchira is the rooftop restaurant on the 5th floor of Hotel Satyaheera at Hutatma Chowk in central Mapusa, serving North Indian, Chinese and Goan dishes. The rooftop seating gives it an edge over other town restaurants for an evening meal with a view over Mapusa.', '1-1.5 hours', 'Oct-Mar, evenings', 'Ask for rooftop seating in the evening; the hotel location at Hutatma Chowk makes it easy to find.', NULL, 'Goa', 0, 0, NULL, NULL, '₹1,000 for two (JustDial)', 3, 4, 15.59114, 73.81033, '5th Floor, Hotel Satyaheera, Hutatma Chowk, Mapusa, Goa 403507', NULL, 0.68);

