INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3310017, 331, 331004, 'Milagres Feast (Milagr Saibinnichem Fest)', 'Apr-May', 'Annual feast of Our Lady of Miracles (Milagr Saibinnichem Fest) at St. Jerome Church, held on the 15th day after Easter, so it falls in April or May depending on the year. Thousands of Catholic and Hindu devotees throng the church for the novenas and feast day.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3310018, 331, 331004, 'Bodgeshwar Zatra', 'Jan', 'Annual week-long zatra (temple fair) at Shri Dev Bodgeshwar Sansthan, held in January, with over a hundred stalls selling clothes, footwear, utensils, food and games plus amusement rides like the giant wheel; evenings are very crowded. Sundays are observed as the deity''s special day with heavy footfall.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3310019, 331, 331004, 'Shigmo', 'Mar', 'Goa''s state spring festival (Shigmotsav) celebrated in the Phalguna month; colourful float parades with folk dance, music and mythological tableaux are held across 19 centres in the state, with the Mapusa parade taking place in early March (Mapusa was a parade centre on March 8 in 2026).');

-- city: Ponda (id 1075)
INSERT OR IGNORE INTO cities (id, state_id, city_name, latitude, longitude) VALUES (331005, 331, 'Ponda', 15.401, 74.0126);

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000105, 331005, 'Shri Manguesh Temple', 'Shri Manguesh Temple, Mangeshi', 'One of Goa''s most revered Hindu temples, dedicated to Lord Mangesh (Shiva). The deity''s linga was moved here from Cortalim in 1560 to escape Portuguese persecution; the present structure blends Goan and Maratha architecture, with a towering deepastambha and a golden kalasha added in 1973.', '1–2 hours', 'October to March; early morning for aarti and smaller crowds', 'Dress modestly (covered shoulders and knees); the temple canteen serves simple vegetarian meals to devotees.', 0, 'Goa', 0, 0, NULL, NULL, NULL, 10, 8, 15.44494, 73.96643, 'Mangeshi, Priol, Ponda, Goa 403401', 'https://shrimangesh.com', 1.84);

