INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000106, 331005, 'Shri Shantadurga Temple', 'Shri Shantadurga Temple, Kavlem', 'Goa''s most famous goddess temple, dedicated to Shantadurga — the peaceful form of Durga who mediated between Vishnu and Shiva. The idol was shifted from Keloshi in 1566; the present temple was built between 1713 and 1738 and renovated in 1966, set amid lush greenery with a grand tank and deepastambha.', '1–2 hours', 'October to March; mornings for aarti', 'Combine with the Mangeshi temple nearby; the temple canteen offers vegetarian meals to devotees.', 0, 'Goa', 0, 0, NULL, NULL, NULL, 10, 8, 15.39638, 73.98606, 'Kavlem (Kavale), Ponda, Goa 403401', 'https://shreeshantadurga.com', 1.84);

