INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000107, 331005, 'Shri Nagesh Temple', 'Shri Nagesh Temple, Bandora', 'An ancient Shiva temple at Bandora bearing a 1413 AD stone inscription, renovated in 1780. Quieter than Ponda''s big-name temples, it draws devotees of Lord Nagesh (a form of Shiva) and is known for its serene, forested setting.', '45–60 minutes', 'October to March; mornings', 'Pair with the nearby Ramnath and Mahalakshmi temples in Bandora — all three sit within a couple of kilometres of each other.', 0, 'Goa', 0, 0, NULL, NULL, NULL, 8, 7, 15.40741, 73.98394, 'Bandiwade, Donshiwado, Bandora, Ponda, Goa 403401', NULL, 1.52);

