INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000108, 331005, 'Shri Mahalakshmi Temple', 'Shri Mahalakshmi Temple, Bandora', 'A prominent 19th-century temple dedicated to Goddess Mahalakshmi in her serene Satvik form, wearing a linga on her head. It houses two idols — one smuggled from Colva during the 16th-century Portuguese persecution — and is famed for its Friday palki utsav, Konkani architecture, devotee rooms and canteen.', '1–2 hours', 'October to March; Friday evenings for the palki utsav', 'Photography is not allowed inside the sanctum and modest dress is required; book abhishek at the reception between 7:30–9:30 am.', 0, 'Goa', 0, 0, NULL, NULL, 'Free entry; free parking', 9, 8, 15.40642, 73.97969, 'Shree Mahalaxmi Saunsthan, Bandiwade, Bandora, Ponda, Goa 403401', NULL, 1.72);

