INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000109, 331005, 'Shri Ramnath Temple', 'Shri Ramnath Temple, Ramnathim, Bandora', 'A major Panchayatan temple dedicated to Ramnath — the unified form of Vishnu (Hari) and Shiva (Hara). The deity was moved from Loutolim in 1566 and the temple rebuilt in 1905; the complex also houses Shanteri, Kamakshi, Lakshmi Narayan, Ganapati, Betal and Kalbhairav shrines.', '1 hour', 'October to March; mornings', 'One of the five great temples of the Goud Saraswat community; visit together with the Nagesh and Mahalakshmi temples nearby.', 0, 'Goa', 0, 0, NULL, NULL, NULL, 8, 7, 15.39884, 73.98094, 'Shree Ramnath Devasthan, Ramnathi, Ponda, Goa 403401', 'https://ramnathi.org', 1.52);

