INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000110, 331005, 'Shri Kamakshi Temple', 'Shri Kamakshi Temple, Shiroda', 'A late-16th-century temple dedicated to Goddess Kamakshi, whose idol was smuggled out of Raia between 1564–68 during Portuguese persecution. An important Shakti shrine of the Goud Saraswat community, set in the quiet village of Shiroda.', '1 hour', 'October to March; mornings', 'Combine with a drive through Shiroda''s countryside; the temple is about 12 km south of Ponda town.', 0, 'Goa', 0, 0, NULL, NULL, NULL, 8, 7, 15.32053, 74.03368, 'Shiroda, Ponda, Goa 403103', 'https://shreekamakshisaunsthan.org', 1.52);

