INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000111, 331005, 'Shri Mhalasa Narayani Temple', 'Shri Mhalasa Narayani Temple, Mardol', 'The most popular temple of Mhalasa Narayani — the Mohini avatar of Vishnu and kuladevata of many Saraswat, Karhade and Daivajna families. Over 450 years old, it is famous for its huge brass bell (once used for truth ordeals accepted in Portuguese courts) and its large brass samai oil lamps.', '1–2 hours', 'October to March; mornings', 'Look for the giant brass bell at the entrance and the temple''s collection of large brass oil lamps.', 0, 'Goa', 0, 0, NULL, NULL, NULL, 9, 7, 15.44064, 73.97287, 'Mardol, Priol, Ponda, Goa 403404', 'https://mahalasa.org', 1.64);

