INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 331000111, 'insert', 'bulk', 'mahalasa.org fetched and confirmed as the devotional portal prominently covering the Mardol temple (''the most popular temple of Supreme Mother Mahalasa is at Mardol in Goa''). A separate saunsthan site (shreemahalasasaunsthanmardol.org) could not be fetched and was excluded. Coordinates from geocoder. Published hours conflict (6am–9pm vs 7am–8:30pm vs split windows) — left null.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000112, 331005, 'Shri Navdurga Temple', 'Shri Navdurga Temple, Madkai', 'Famous for its unique stone idol of the fierce goddess Mahishasuramardini with a distinctively tilted head. Thousands gather here each November (Kartika) for the annual zatra from Vidya Chaturthi to Dashami; Navratri is also celebrated with great pomp.', '1 hour', 'November during the annual zatra; otherwise October to March mornings', 'Visit in November for the zatra to see the temple at its most vibrant; the temple has a pilgrim rest house (agrashala) with limited rooms.', 0, 'Goa', 0, 0, NULL, NULL, NULL, 7, 7, 15.418767, 73.943516, 'Madkai (Marcaim), Ponda, Goa 403404', NULL, 1.4);

