INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000113, 331005, 'Shri Maha Ganapati Temple', 'Shri Maha Ganapati Temple, Khandola', 'One of Goa''s oldest Ganesha temples. The original idol was rescued from Divar island after the Portuguese destroyed the temple around 1540, sheltered at Khandepar and Narve, and finally installed at Khandola around 1750; the present idol was consecrated on 31 January 1969.', '45–60 minutes', 'October to March; mornings', 'Time your visit for the morning or evening aarti (8–9 am / 6–6:30 pm per the temple''s site).', 0, 'Goa', 0, 0, NULL, NULL, NULL, 7, 6, 15.514041, 73.967373, 'Khandola, Betki, Marcel, Goa 403107', 'https://mahaganapatikhandola.com', 1.32);

