INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000114, 331005, 'Shri Devki Krishna Temple', 'Shri Devki Krishna Temple, Marcel', 'A Krishna temple at Orgao, Marcel, best known as the venue of Chikhal Kalo — Goa''s exuberant monsoon mud festival celebrated on Ashadha Dwadashi, when devotees reenact Krishna''s childhood games in rain-soaked slush.', '45–60 minutes (half a day during Chikhal Kalo)', 'July for Chikhal Kalo; otherwise October to March', 'Plan around Chikhal Kalo (July) for the famous mud festivities; expect crowds and wear clothes you don''t mind ruining.', 0, 'Goa', 0, 0, NULL, NULL, NULL, 6, 6, 15.51491, 73.96069, 'Orgao, Marcel, Ponda, Goa 403107', NULL, 1.2);

