INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000115, 331005, 'Shri Vijayadurga Temple', 'Shri Vijayadurga Temple, Keri', 'A 1560-era temple dedicated to Goddess Vijayadurga, whose deity was moved from Sancoale to the valleys of Keri. Renowned for its rare Kaavi art — the ancient Goan craft of reddish-brown murals — and a majestic deepastambha that lights up during the annual jatra.', '1 hour', 'October to March; evenings when the deepastambha is lit', 'Look closely at the Kaavi murals — a fading Goan art form rarely seen elsewhere.', 0, 'Goa', 0, 0, NULL, NULL, NULL, 7, 7, 15.467263, 73.997967, 'Shree Vijayadurga Sansthan, Keri, Ponda, Goa 403401', 'https://shrivijayadurga.org', 1.4);

