INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000116, 331005, 'Shri Shantadurga Shankhwaleshwari Temple', 'Shri Shantadurga Shankhwaleshwari Temple, Veling', 'A distinct Shantadurga shrine at Gothan, Veling, revered as Shankhwaleshwari. A 266-year-old manuscript, the ''Kokanakhyan'', records the ancient glory of Sankhavali village where it stands — a quieter alternative to the famous Kavlem temple.', '45–60 minutes', 'October to March; mornings', 'A peaceful stop on the Mardol–Priol temple circuit, minutes from the Mhalasa temple.', 0, 'Goa', 0, 0, NULL, NULL, NULL, 6, 6, 15.430156, 73.972452, 'Gauthan, Veling, Mardol, Ponda, Goa 403401', 'https://shreeshantadurgaveling.com', 1.2);

