INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000117, 331005, 'Sahakari Spice Farm', 'Sahakari Spice Farm, Curti', 'A lush organic spice plantation on the Ponda–Belgaum highway at Curti, offering guided walks through spice, fruit and medicinal-plant groves, plus a Goan lunch buffet at its rustic farm restaurant.', '3–4 hours', 'October to March; mornings', 'Go hungry — the entry price typically bundles the tour with a generous Goan lunch buffet.', 0, 'Goa', 0, 0, NULL, NULL, 'INR 400–500 per adult, typically including guided tour and Goan lunch buffet (reports vary — confirm when booking)', 8, 8, 15.409651, 74.024079, 'Ponda–Belgaum Highway, Curti, Ponda, Goa', 'https://sahakarispicefarm.com', 1.6);

