INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000120, 331005, 'Pascoal Spice Farm', 'Pascoal Spice Farm, Khandepar', 'An award-winning 50-acre organic spice farm on the banks of the Khandepar river, with guided spice tours covering 2,500+ plant species, bamboo river-rafting, cultural shows, swimming pools, and a home-cooked Goan lunch.', '3–4 hours', 'October to March; mornings', 'The entry fee covers both the guided tour and lunch — arrive by late morning to fit both in.', 0, 'Goa', 0, 0, NULL, NULL, 'Adults INR 400, children over 5 INR 200, under 5 free (tripinic); entry covers guided tour and lunch', 7, 8, 15.39192, 74.02039, 'Belgaum Road, opposite Nestle India, Khandepar, Ponda, Goa 403401', NULL, 1.48);

