INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000121, 331005, 'Butterfly Conservatory of Goa', 'Butterfly Conservatory of Goa (Mystic Woods), Priol', 'A tranquil conservatory near Pisgal, Priol, where visitors walk through landscaped gardens fluttering with native butterflies — a gentle, family-friendly break from temple-hopping.', '1–2 hours', 'October to March; sunny mornings', 'Go on a sunny morning when butterflies are most active; closed on Mondays.', 0, 'Goa', 0, 0, NULL, NULL, '≈INR 100–150 per person (sources vary)', 6, 7, 15.42953, 74.0125, 'Near Pisgal, Priol, Ponda, Goa 403401', NULL, 1.28);

