INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000122, 331005, 'Bondla Wildlife Sanctuary', 'Bondla Wildlife Sanctuary, Usgao', 'Goa''s smallest wildlife sanctuary (about 8 sq km) at Usgao-Ganjem — an easy family outing with a mini zoo, deer park, nature trails and birdwatching, popular with school groups and children.', '3–4 hours', 'October to March; mornings', 'Arrive at opening (9 am) for the best wildlife sightings; carry water — facilities inside are basic.', 0, 'Goa', 0, 0, NULL, NULL, 'Adults Rs.50, children Rs.25, foreigners Rs.50; still camera Rs.30, video camera Rs.150; parking 2-wheeler Rs.25 / 3-wheeler Rs.40 / 4-wheeler Rs.100 (goa-tourism.org.in, 2025)', 8, 7, 15.440118, 74.10638, 'Usgao-Ganjem, Ponda, Goa 403105', NULL, 1.52);

