INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000123, 331005, 'Safa Shahouri Masjid', 'Safa Shahouri Masjid, Shahapur', 'Goa''s oldest surviving mosque, built around 1560 by Bijapuri ruler Ibrahim Adil Shah I. An ASI-protected Monument of National Importance with a terracotta-tiled prayer hall, a large laterite masonry water tank with 40+ mihrab-style hammams, and a charbagh-style garden.', '30–45 minutes', 'October to March; early morning or late afternoon', 'Combine with the Sahakari Spice Farm nearby; dress respectfully and remove footwear before entering the prayer hall.', 0, 'Goa', 0, 0, NULL, NULL, 'Free entry', 7, 6, 15.40592, 74.00013, 'Shahapur, Ponda, Goa (about 2 km from Ponda centre)', NULL, 1.32);

