INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000124, 331005, 'Shri Saptakoteshwar Temple', 'Shri Saptakoteshwar Temple, Narve', 'A historic Shiva temple rebuilt by Chhatrapati Shivaji in 1668 after earlier destruction, renovated and reopened in February 2022. One of Goa''s most important Shaivite shrines, drawing large crowds for Gokulashtami.', '1 hour', 'October to March; Gokulashtami for the big festival', 'About 19 km north of Ponda in Bicholim taluka — best combined with a wider temple-circuit day trip.', 0, 'Goa', 0, 0, NULL, NULL, NULL, 7, 7, 15.55433, 73.93744, 'Deul Wada, Naroa (Narve), Bicholim, Goa 403504', NULL, 1.4);

