INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 331000124, 'insert', 'bulk', 'No official site found. Coordinates from geocoder (Shri Saptakoteshwar Temple, Deul Wada, Naroa, Bicholim 403504) — high-relevance match. Hours 6am–7pm per trawell. Located ~19 km north of Ponda in Bicholim taluka — included as a major temple-circuit excursion. Anjunem Dam (~25 km, Sattari taluka) was considered as the 20th attraction but dropped: it is far from Ponda and a 2025 travel vlog reported visitor access restrictions (unverified).', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000125, 331005, 'Tilve Bhojanalaya', 'Tilve Bhojanalaya', 'A beloved no-frills Goan eatery on NH 17B near Nageshi, famous for its fish thali — generous portions of fried fish, curry, rice and solkadhi at local prices. A favourite of locals and temple-circuit travellers alike.', '1 hour', 'Lunch (arrive before 2 pm) or dinner', 'Go for the fish thali; it draws lunch crowds, so arrive early. Note: ''Tilve Mithai Ghar'' is a different business — don''t confuse the two.', 0, 'Goa', 0, 0, NULL, NULL, '≈₹450 for two (Justdial)', 8, 8, 15.404636, 73.982829, 'Gram Nageshi, Donshiwado, NH 17B, Ponda, Goa 403401', NULL, 1.6);

