INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000130, 331005, 'Padmavati Restaurant', 'Padmavati Restaurant', 'A casual, budget-friendly Indian and seafood restaurant on the Ponda bypass near Curti, praised for cheap, tasty portions — fish curry, fried fish and chicken-crispy are local favourites.', '1 hour', 'Lunch or dinner', '''Tasty food at cheap rates'' — a good value stop on the bypass; delivery and takeaway available.', 0, 'Goa', 0, 0, NULL, NULL, '≈₹550 for two (Justdial)', 6, 7, 15.413251, 74.010084, 'By Pass Road, Curti, Ponda, Goa 403401', NULL, 1.28);

