INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 331000130, 'insert', 'bulk', 'Coordinates from a business listing page — approximate. Hours 11am–11:30pm daily per restaurant-guru and open-hours.in. Also listed at House 21, Block 8, Haveli, Curti, Near Sai Service, Ponda. Justdial rating 3.8 (~521 ratings); phone +91 88068 48464 per listings.', 'pipeline');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3310020, 331, 331005, 'Shigmo', 'March', 'Goa''s biggest Hindu spring festival, celebrated with vibrant float parades, folk dances and gulal; Ponda hosts one of the major Shigmo parades, drawing crowds from across the state.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3310021, 331, 331005, 'Mangeshi Jatra (Jatrotstav)', 'January–February', 'The annual chariot festival of Shri Manguesh Temple at Mangeshi, held in the Hindu month of Magha, with the deity''s palanquin procession and thousands of devotees.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3310022, 331, 331005, 'Shri Navdurga Zatra, Madkai', 'November', 'The annual zatra of Shri Navdurga Temple, Madkai, held during Kartika from Vidya Chaturthi to Dashami; Navratri is also celebrated here with great pomp.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3310023, 331, 331005, 'Chikhal Kalo', 'July', 'Goa''s exuberant monsoon mud festival at Shri Devki Krishna Temple, Marcel, on Ashadha Dwadashi — devotees play in rain-soaked slush reenacting Lord Krishna''s childhood games (held 24–26 Jul in 2026, 5–7 Jul in 2025).');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3310024, 331, 331005, 'Shri Vijayadurga Jatra', 'January–February', 'The annual jatra of Shri Vijayadurga Temple at Keri, famed for the lighting of its majestic deepastambha and the temple''s rare Kaavi-art murals.');

