INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000131, 331006, 'Calangute Beach', 'Calangute Beach', 'The ''Queen of Beaches'' and the busiest stretch of sand in North Goa, Calangute draws domestic and international visitors with its long golden shoreline, buzzing beach shacks, and water sports. Sunbathe on a sunbed with a cold drink, swim in the gentle slope, and stay for the sunset party atmosphere.', '2-3 hours', 'Nov-Feb', 'Sunbeds are usually free if you order food or drinks at a shack; swim only in lifeguard-patrolled zones.', NULL, 'Goa', 0, 0, NULL, NULL, 'Free entry', 5, 4, 15.5448, 73.7545, 'Calangute Beach, Calangute, Bardez, Goa 403516', NULL, 0.92);

