INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000132, 331006, 'Baga Beach', 'Baga Beach', 'Just north of Calangute, Baga is North Goa''s nightlife and water-sports hub, with a lively shoreline lined by shacks, clubs and the famous Tito''s Lane. It also hosts a leisurely Saturday flea market and is a short walk or ride from Calangute beach.', '2-3 hours', 'Nov-Feb', 'Come for the Saturday flea market and stay for the evening shack parties; evenings get crowded on weekends.', NULL, 'Goa', 0, 0, NULL, NULL, 'Free entry', 5, 4, 15.5565, 73.754, 'Baga Beach, Baga, Bardez, Goa 403516', NULL, 0.92);

