INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000133, 331006, 'Water Sports at Calangute Beach', 'Water Sports at Calangute Beach', 'Calangute''s shoreline is one of North Goa''s main water-sports zones, offering parasailing, jet skiing, banana boat rides, speed-boat trips and dolphin-sighting cruises. Operators typically begin in the afternoon when winds pick up and run until sunset.', '1-2 hours', 'Oct-Mar', 'Water sports start in the afternoon when the wind is right; agree on the price and duration before you start.', 'Not required; book on the beach with licensed operators.', 'Goa', 0, 0, NULL, NULL, NULL, 4, 4, 15.5455, 73.754, 'Calangute Beach, Calangute, Bardez, Goa 403516', NULL, 0.8);

