INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 331000133, 'insert', 'bulk', 'Activity cluster verified via travelmarg (afternoon timing) and MakeMyTrip (parasailing, jet skiing, banana boats). Scuba diving/snorkelling nearby priced ~INR 3,200/dive and ~INR 1,000/session per Treebo (operators Dive Goa, King''s Scuba) — price placed in hours/cost for the specific entry, not here.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000134, 331006, 'St. Alex Church', 'St. Alex Church, Calangute', 'A grand 1741 Portuguese-era parish church in the heart of Calangute village, famous for its twin towers and a false dome (cupola falsa) modelled on St. Peter''s Basilica in Rome. It remains an active parish with daily masses and a gilded altar, rococo pulpit and seven altars.', '45 minutes', 'Oct-Mar', 'Visit around the 8:45 AM Sunday English mass for the full choir experience; dress modestly.', NULL, 'Goa', 0, 0, NULL, NULL, 'Free entry', 4, 4, 15.543, 73.754, 'Calangute, Bardez, Goa 403516', NULL, 0.8);

