INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000135, 331006, 'St. Anthony''s Chapel', 'St. Anthony''s Chapel', 'A small, charming chapel that stands curiously in the centre of a roundabout in Calangute town. A quick photo stop and local landmark often noted in Calangute travel guides.', '10 minutes', 'Oct-Mar', 'It sits on a busy roundabout — photograph from the sidewalk, not the road.', NULL, 'Goa', 0, 0, NULL, NULL, 'Free entry', 2, 3, 15.5457, 73.757, 'Beach Road roundabout, Calangute, Bardez, Goa', NULL, 0.48);

