INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000137, 331006, 'Tibetan Market, Calangute', 'Tibetan Market, Calangute', 'A well-known row of Tibetan-run stalls in central Calangute selling silver jewellery, semi-precious stones, wooden Buddha and Hindu statues, singing bowls and Himalayan handicrafts. A good alternative to the main market for gifts and spiritual artefacts.', '45 minutes', 'Oct-Mar', 'Check silver for hallmarks and bargain; similar stalls cluster together so compare prices.', NULL, 'Goa', 0, 0, NULL, NULL, 'Free entry', 3, 3, 15.5442, 73.7593, 'Near beach road, Calangute, Bardez, Goa 403516', NULL, 0.6);

