INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000138, 331006, 'Saturday Night Market (Ingo''s Night Bazaar), Arpora', 'Saturday Night Market, Arpora', 'Goa''s most famous night bazaar, held every Saturday at Arpora grounds near Baga. Three fields of stalls — Indian handicrafts and carpets below, a global food court and central stage in the middle, and designer boutiques up top — with live music, DJs and bars into the night.', '3-4 hours', 'Nov-Mar', 'Arrive by 7 PM to beat the worst crowds; entry is free but ATMs run out — carry cash.', NULL, 'Goa', 0, 0, NULL, NULL, 'Free entry (per Curly Tales)', 5, 4, 15.567239, 73.765178, 'Aguada-Siolim Road, Arpora, Bardez, Goa', NULL, 0.92);

