INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 331000138, 'insert', 'bulk', 'Timing 6 PM-late verified via airial.travel and Curly Tales; season Nov-Apr via Outlook Traveller. CAVEAT: some business listings flag the market as permanently closed, likely due to past government disruptions — verify it is operating before visiting.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000139, 331006, 'Fort Aguada', 'Fort Aguada', 'A 17th-century Portuguese fort (built 1609-1612) on Sinquerim headland, once guarding the Mandovi estuary with a vast 2.3-million-gallon water cistern and Asia''s oldest lighthouse (1864). Now an ASI-protected monument, it offers sweeping Arabian Sea views and is a favourite sunset and Bollywood filming spot.', '2-3 hours', 'Nov-Feb', 'Visit for sunset; wear comfortable footwear as you will climb and walk the ramparts.', NULL, 'Goa', 0, 0, NULL, NULL, 'Free entry (per Tusk Travel, indiamap, MakeMyTrip)', 5, 5, 15.492253, 73.773746, 'Fort Aguada Road, Sinquerim, Candolim, Bardez, Goa 403515', NULL, 1.0);

