INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000140, 331006, 'Aguada Port and Jail Complex (Fort Aguada Jail Museum)', 'Aguada Port and Jail Complex', 'The lower Aguada fort''s historic jail — Goa''s former central prison, operational until 2015 — now converted into a heritage jail museum by the Goa government. It sits beside the old fort with views over Sinquerim beach.', '1 hour', 'Nov-Feb', 'Combine with Fort Aguada upper fort in one trip; the complex is a short walk downhill from the lighthouse.', NULL, 'Goa', 0, 0, NULL, NULL, NULL, 3, 4, 15.492633, 73.777123, 'Aguada-Siolim Road, Sinquerim, Bardez, Goa', NULL, 0.68);

