INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000141, 331006, 'Aguada Lighthouse', 'Aguada Lighthouse', 'The 13-metre, four-storey 1864 lighthouse inside Fort Aguada — once the oldest lighthouse in Asia, guiding ships with a coconut-oil lamp and later a rotating catoptric lamp. The original tower is now closed to the public; a newer lighthouse nearer the cliff edge can be climbed for a small fee.', '30 minutes', 'Nov-Feb', 'The new lighthouse offers the best photo angle of the fort and sea; visit within the fort''s open hours.', NULL, 'Goa', 0, 0, NULL, NULL, 'Small fee for the new lighthouse (per mycyclingdiary)', 4, 4, 15.492094, 73.774066, 'Fort Aguada, Sinquerim, Bardez, Goa', NULL, 0.8);

