INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000152, 331006, 'Infantaria', 'Infantaria Restaurant and Bar', 'A Calangute institution for all-day breakfast since 1989 — English breakfasts, pancakes, Goan sausages, ros omelette and a famous in-house bakery (pastel de nata, bebinca, death by chocolate). Casual, always busy, and a rite of passage for Goa regulars.', '1 hour', 'Oct-Mar', 'Go early for breakfast to avoid the rush; save room for the bakery desserts.', NULL, 'Goa', 0, 0, NULL, NULL, 'Around INR 800-1,300 for two (published estimates)', 5, 4, 15.546666, 73.760417, '5/181, Calangute-Baga Road, opposite Ticlo Resort, Calangute, Goa 403516', NULL, 0.92);

