INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000153, 331006, 'Pousada by the Beach', 'Pousada by the Beach', 'A sea-facing garden restaurant at the end of Holiday Street in Gaura Vaddo, run by the much-loved host Neville. Goan-Portuguese and seafood cooking in a rustic old-Goa setting with sunbeds, shrubs between you and the beach, and magical sunsets.', '2 hours', 'Oct-Mar', 'It is daytime-oriented (open 11 AM-7 PM) — come for a long lazy lunch; sunbed day-use is INR 900/person adjustable against food and drinks.', 'Reservations recommended; call ahead.', 'Goa', 0, 0, NULL, NULL, 'Around INR 1,079-2,248 per person price range (per Tripadvisor); sunbed day-use INR 900/person adjustable against consumption', 4, 5, 15.53457, 73.758291, 'Holiday Street, Gaura Vaddo, Calangute, Goa 403516', NULL, 0.88);

