INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000154, 331006, 'Fat Fish Restaurant and Bar', 'Fat Fish Restaurant and Bar', 'A much-loved open-air seafood restaurant on the Calangute-Arpora road, blending Goan-Portuguese and Hindu Saraswat cooking since 2012. The Special Goan Fish Thali (lunch only) — fish curry, tisrya, crab xacuti, tarle sukha — is the headline act.', '1.5 hours', 'Oct-Mar', 'The fish thali is lunch-only and the place gets packed at peak hours — arrive early or be ready to wait.', NULL, 'Goa', 0, 0, NULL, NULL, 'INR 400-1,000 per person (per Tripadvisor); ~INR 1,000 for two (per WhatsHot)', 4, 4, 15.556368, 73.763865, 'Calangute-Arpora Road, Sim Vaddo, Arpora, Calangute, Goa 403516', 'http://www.fatfishgoa.com/', 0.8);

