INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000155, 331006, 'Cafe Roma Beach Shack', 'Cafe Roma Beach Shack', 'A peaceful family-run beach shack (25+ years under host Anthony) on the quieter stretch between Calangute and Candolim beaches. Fresh seafood, Italian staples like gnocchi and bruschetta, Goan dishes, strong coffee and fast Wi-Fi — the anti-party shack for digital nomads and sunset seekers.', '1.5-2 hours', 'Oct-Mar', 'No loud music here — come for calm; it doubles as a good work-from-beach spot with plug sockets.', NULL, 'Goa', 0, 0, NULL, NULL, 'INR 200-400 per person (per restaurant-guru); ~INR 500-550 for two (per Zomato/EazyDiner)', 3, 4, 15.531527, 73.759123, 'H. No. 249A, Gauravaddo, Holiday Street, Calangute, Goa 403515', 'http://www.caferoma.in/', 0.68);

