INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3310028, 331, 331006, 'Christmas and New Year beach celebrations', 'Dec', 'Peak-season beach parties, live music and fireworks along Calangute and Baga beaches through the Christmas-New Year week.');

