INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000157, 331007, 'Anjuna Beach', 'Anjuna Beach', 'The beach that put Anjuna on the map - a rocky, dramatic stretch of the Arabian Sea coast that was the heart of Goa''s 1960s hippie scene and one of the birthplaces of Goa trance. Known for red laterite rocks, big sunset views, beach shacks like Curlies, and a party atmosphere rather than safe swimming.', '2-3 hours', 'Nov-Feb', 'Swimming is risky on the rocky stretches (no safe swim zone per TravelTriangle) - the southern sandy end is the best bet for a dip; come before sunset for the cliff views.', NULL, 'Goa', 0, 0, NULL, NULL, 'Free entry', 5, 4, 15.57638, 73.74611, 'Anjuna Beach, Anjuna, Bardez, Goa 403509', NULL, 0.92);

