INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000158, 331007, 'Anjuna Flea Market', 'Anjuna Flea Market', 'Goa''s most famous flea market, started by hippies in the late 1960s as an open-air goods exchange and now a sprawling Wednesday bazaar of clothes, jewellery, handicrafts, spices and street food with live music and fire dancers.', '2-3 hours', 'Nov-Mar', 'Arrive by 9 AM for the full spread and easier bargaining; vendors offer better discounts after 6 PM as they pack up.', NULL, 'Goa', 0, 0, NULL, NULL, 'Free entry', 5, 4, 15.57229, 73.74247, 'Monteiro Vaddo, Anjuna, Goa 403509', NULL, 0.92);

