INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3310029, 331, 331007, 'Goa Carnival', 'Feb', 'Goa''s pre-Lent street carnival with float parades, music and dancing across the state, including the North Goa belt around Anjuna; the 2026 edition ran Feb 13-17 per the Goa tourism department.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3310030, 331, 331007, 'Shigmo', 'Mar', 'Goa''s spring harvest festival with folk dances and colourful float parades across 19 centres in the state, including Bardez taluka; the 2026 edition ran Mar 5-18 per the Goa tourism department.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3310031, 331, 331007, 'Sao Joao', 'Jun', 'Catholic feast of St. John the Baptist on Jun 24, marked by well-jumping, kopel flower crowns, feni and decorated boat parades (sangodd); boats arrive from Anjuna for the famous Siolim boat parade on the Chapora river.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3310032, 331, 331007, 'HillTop Festival', 'Feb', 'Annual multi-day psytrance festival at HillTop, Vagator, usually in February (2024 edition Feb 25-27; listed as ''February annually''), with international and local trance acts across multiple stages.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3310033, 331, 331007, 'Christmas-New Year trance parties', 'Dec', 'Peak-season marathon trance parties at HillTop and Anjuna''s beach shacks through the Christmas-New Year week, the busiest party fortnight of the Goan season.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3310034, 331, 331007, 'Feast of St. Michael the Archangel', 'Sep-Oct', 'Annual parish feast of St. Michael''s Church, Anjuna, with masses, processions and village festivities; sources conflict on the exact date (Sept 29 vs first Sunday of October), so shown as Sep-Oct.');

-- city: Palolem (id 1078)
INSERT OR IGNORE INTO cities (id, state_id, city_name, latitude, longitude) VALUES (331008, 331, 'Palolem', 15.01, 74.0233);

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000183, 331008, 'Palolem Beach', 'Palolem Beach', 'A crescent-shaped mile-long bay framed by coconut palms and rocky headlands, Palolem is South Goa''s signature beach. Its calm, shallow waters make it one of Goa''s safest swimming beaches, lined with seasonal beach huts, shacks and dolphin-boat operators.', '2-4 hours', 'Oct-Mar', 'Shacks and water activities operate Oct-May; the monsoon (Jun-Sep) brings rough seas and most beach infrastructure shuts down.', 'No entry ticket; book boat trips and beach huts a day or two ahead in peak season (Dec-Jan).', 'Goa', 0, 0, NULL, NULL, 'No entry fee', 5, 5, 15.01155, 74.02145, 'Palolem Beach, Canacona 403702, India', NULL, 1.0);

