INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000191, 331008, 'Cola Beach', 'Cola Beach', 'A hidden crescent beach about 30 minutes north of Palolem, famous for its freshwater lagoon tucked behind the sand. Reachable by a steep walk down from the cliffs — the lagoon swim followed by the sea is the draw.', 'Half day', 'Oct-Mar', 'The last stretch is a steep dirt track — scooters and sturdy shoes only. Lagoon water level is best in winter.', NULL, 'Goa', 0, 0, NULL, NULL, 'No entry fee', 4, 5, 15.0574, 73.97151, 'Cola Beach, Canacona 403702, India', NULL, 0.88);

