INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000195, 331008, 'Leopard Valley', 'Leopard Valley', 'An open-air jungle nightclub between Palolem and Agonda that hosts international DJs, psytrance and techno nights under the trees. One of South Goa''s flagship electronic-music venues in season.', '3-5 hours', 'Nov-Apr', 'Nights run late; check their social pages for the event calendar — it only operates on event nights in season.', 'Tickets at the door or online for headline nights; prices vary by event.', 'Goa', 0, 0, NULL, NULL, NULL, 3, 4, 15.03391, 74.01449, 'Canacona 403702, India', NULL, 0.68);

