INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000196, 331008, 'Dolphin-watching boat tours', 'Dolphin-watching boat tours', 'Early-morning boat trips from Palolem Beach to spot wild dolphins, often combined with visits to Butterfly Beach and Honeymoon Beach. The classic Palolem morning activity.', '2-3 hours', 'Oct-Mar', 'Boats leave around sunrise (6-7 AM) when seas are calmest and dolphins most active; negotiate price and confirm what''s included before boarding.', 'Book the evening before through your hut or any beach operator in peak season.', 'Goa', 0, 0, NULL, NULL, NULL, 5, 4, 15.0115, 74.0214, 'Palolem Beach, Canacona 403702, India', NULL, 0.92);

