INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000197, 331008, 'Sea kayaking', 'Sea kayaking', 'Rent a kayak from the beach and paddle the calm bay — out to Monkey Island, along the headlands or at sunset. Several kiosks (e.g. Samson''s Kiosk near Cocos Beach Resort) rent by the hour with life vests included.', '1-2 hours', 'Oct-Mar', 'Early morning or sunset paddles are calmest; monsoon seas are not suitable. You may spot dolphins from a kayak on calm mornings.', NULL, 'Goa', 0, 0, NULL, NULL, NULL, 4, 5, 15.0115, 74.0214, 'Palolem Beach, Canacona 403702, India', NULL, 0.88);

