INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3310035, 331, 331008, 'Goa Carnival', 'Feb-Mar', 'Goa''s big pre-Lent street festival with parades, floats, music and dancing across the state; Canacona hosts its own celebrations and Palolem''s beach crowd joins the party season.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3310036, 331, 331008, 'Shigmo', 'Mar', 'Goa''s spring festival of colour and folk dance; the Shri Mallikarjun Temple at Sristhal celebrates Shigmotsav, drawing devotees from across Canacona.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3310037, 331, 331008, 'Sao Joao', 'Jun', 'The monsoon Catholic festival where revellers jump into wells and streams to honour St. John the Baptist — celebrated in villages around Canacona with music, feni and new-rain feasts.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3310038, 331, 331008, 'Ganesh Chaturthi', 'Aug-Sep', 'One of Goa''s most important Hindu festivals; Canacona''s homes and temples install Ganesh idols with days of prayers, music and festive food.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3310039, 331, 331008, 'Christmas and New Year''s Eve beach parties', 'Dec-Jan', 'Palolem''s peak party fortnight — Silent Noise, Leopard Valley and the beach shacks run headline nights; the beach fills with bonfires, live music and midnight celebrations.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3310040, 331, 331008, 'Olive Ridley turtle nesting season', 'Nov-Feb', 'Not a festival but a seasonal wildlife event: Olive Ridley turtles nest on Galgibaga, Agonda and nearby beaches; forest-department hatcheries guard nests and release hatchlings.');

