INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3310041, 331, 331009, 'Feast of St Francis Xavier', 'December 3 (novena November 23 - December 2)', 'Old Goa''s biggest annual religious festival, centered on the Basilica of Bom Jesus. Novena Masses run Nov 23-Dec 2, with the main feast on Dec 3.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3310042, 331, 331009, 'Exposition of the Sacred Relics of St Francis Xavier', 'Once every ~10 years, typically November-January; most recent: November 2024 - January 2025', 'Held once a decade at the Basilica of Bom Jesus; the saint''s relics are brought down for public veneration over ~45 days, drawing millions of pilgrims.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3310043, 331, 331009, 'Christmas in Old Goa', 'December 25', 'Midnight Mass and celebrations at Se Cathedral and the Old Goa churches; the heritage churches are lit and decorated.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3310044, 331, 331009, 'Goa Carnival', 'February (pan-Goa, 4 days before Lent)', 'Float parade and festivities across Goa including Old Goa; Portuguese-era tradition with King Momo presiding.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3310045, 331, 331009, 'Shigmo', 'March (pan-Goa)', 'Goa''s spring folk festival with street parades, gulal, floats and folk dances in villages across the state, including areas around Old Goa.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3310046, 331, 331009, 'Bonderam', 'Late August', 'Flag festival of Divar Island (Piedade village, ~3 km from Old Goa) — mock flag battles with toy weapons, a traditional harvest-season celebration.');

-- city: Colva (id 1080)
