INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000235, 331010, 'Colva Beach', 'Colva Beach', 'Colva is South Goa''s best-known family beach: a long, wide stretch of powdery white sand (ground shell fragments give it a shimmering look) with gentle water sports, shacks and a lively-but-relaxed evening scene. It is 6 km from Margao and about 40 km from Dabolim Airport, making it one of the most accessible beaches in South Goa.', '3-4 hours', 'Oct-Mar', 'Swim near lifeguard-patrolled zones; the sea can be rough in monsoon (Jun-Sep) when water sports shut down.', NULL, 'Goa', 0, 0, NULL, NULL, 'Free entry', 5, 5, 15.2795, 73.9155, 'Colva Beach, Salcete, Goa 403708', NULL, 1.0);

