INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000236, 331010, 'Our Lady of Mercy Church (Igreja de Nossa Senhora das Merces)', 'Our Lady of Mercy Church', 'The 17th-century whitewashed Colva Church, Igreja de Nossa Senhora das Merces, founded in 1630 and rebuilt in the 1700s. It enshrines the venerated Menino Jesus statue, said to have been recovered from a 17th-century shipwreck off Mozambique, and is the focus of Colva''s famous annual Fama feast.', '45 minutes', 'Oct (Fama feast), Nov-Feb', 'Visit outside Mass times for a quiet look at the altar and the Menino Jesus shrine; dress respectfully.', NULL, 'Goa', 0, 0, NULL, NULL, 'Free entry', 5, 4, 15.2781, 73.9213, 'Colva Beach Rd, near Infant Jesus High School, Colva, Goa 403708', NULL, 0.92);

