INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000237, 331010, 'Betalbatim Beach', 'Betalbatim Beach', 'A quiet, ~3.8 km stretch of golden-white sand just north of Colva, known for clear water, pine trees fringing the shore (unusual for Goa) and good sunsets. Less developed than Colva, with a few shacks; a classic escape from crowds, and dolphin-spotting trips can be arranged with local fishermen.', '2-3 hours', 'Oct-Mar', 'No direct public transport; arrive by taxi or scooter. Bargain politely for fisherman dolphin trips.', NULL, 'Goa', 0, 0, NULL, NULL, 'Free entry', 4, 4, 15.29255, 73.90812, 'Betalbatim, Salcete, Goa 403708', NULL, 0.8);

