INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000243, 331010, 'Ancestral Goa (Big Foot Museum)', 'Ancestral Goa (Big Foot Museum)', 'An open-air heritage museum in Loutolim village recreating Goan rural life as it was a century ago: miniature Goan houses for different occupations, a feni distillery, spice yard, handicraft centre and the giant laterite sculpture of Sant Mirabai (India''s longest laterite sculpture, Limca Book of Records).', '1-2 hours', 'Oct-Mar', 'Go in the morning or late afternoon to avoid midday heat; guided tour comes with entry.', NULL, 'Goa', 0, 0, NULL, NULL, '₹50 adults / ₹25 children (one source, Apr 2026, lists ₹150 per person; camera ₹20)', 4, 4, 15.34, 73.981, 'Cross Museum, Main Road, Loutolim, Goa 403718', NULL, 0.8);

