INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 331000243, 'insert', 'bulk', 'Hours 9am-6pm consistent across sources. Entry fee varies by source (₹50 adult vs ₹150 per person, Apr 2026) — flagged in cost field. Coordinates approximate to Loutolim.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000244, 331010, 'Goa Chitra Museum', 'Goa Chitra Museum', 'India''s top-rated contemporary ethnographic museum (ASI-cited), founded by Victor Hugo Gomes on an organic farm. Goa Chitra holds 4000+ artefacts of Goan agrarian life; the adjoining Goa Chakra (India''s first transport museum) and Goa Cruti (colonial-life collection) complete the trio. Guided tours are the way to see it.', '2-3 hours', 'Oct-Mar', 'The guided tour is included and strongly recommended; allow 2-3 hours for all three museums. (Official site: goachitramuseums.com — not fetched, so not listed above.)', NULL, 'Goa', 0, 0, NULL, NULL, '~₹300 per person for all three museums incl. guided tour (per travel reports)', 5, 5, 15.264858, 73.941346, 'H.No. 498, Near Auxilium High School, Benaulim, Goa 403716', NULL, 1.0);

