INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000245, 331010, 'St. John the Baptist Church (Benaulim)', 'St. John the Baptist Church', 'The hilltop church of Monte Benaulim, one of Goa''s most famous parish churches. Founded by the Jesuits at Colva in 1581 and moved to Benaulim in 1596, it is noted for its beautiful altar, views over the village, and the annual Sao Joao feast (24 June). St. Joseph Vaz was baptised here.', '45 minutes', 'Oct-Mar', 'Combine with Goa Chitra Museum and Benaulim Beach for a half-day heritage circuit.', NULL, 'Goa', 0, 0, NULL, NULL, 'Free entry', 4, 4, 15.2606, 73.9417, 'Monte Benaulim, Benaulim, Goa 403716', NULL, 0.8);

