INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000247, 331010, 'Figueiredo Mansion (Casa Figueiredo)', 'Figueiredo Mansion', 'A 400+ year-old Indo-Portuguese family mansion (built 1590), part museum and part homestay. Guided tours walk through the ballroom, dining room, music room and family chapel amid Belgian chandeliers, Chinese porcelain and carved rosewood — one of the best-preserved colonial homes in Goa.', '1.5 hours', 'Oct-Mar', 'Join one of the fixed-time guided tours; photography policies vary, ask on arrival.', NULL, 'Goa', 0, 0, NULL, NULL, '₹350 per person (guided visit)', 4, 5, 15.3424, 73.985, 'Loutolim, Goa 403718', NULL, 0.88);

