INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000248, 331010, 'Menezes Braganza House (Chandor)', 'Menezes Braganza House', 'The grandest of Goa''s colonial mansions: a 17th-century Indo-Portuguese house split between two descendant families (Menezes Braganza and Braganza Pereira wings). See the 24-window facade, the grand ballroom with Italian marble and Belgian crystal, a chapel holding a relic of St. Francis Xavier, and a library of 5,000+ books.', '1.5-2 hours', 'Oct-Mar', 'Call ahead so the family can receive you; the guided tour is personal and worth the trip. (Official site: menezesbragancahouse.com — not fetched, so not listed above.)', NULL, 'Goa', 0, 0, NULL, NULL, 'No fixed fee; donations for upkeep (one source: nominal admission)', 4, 5, 15.261523, 74.043468, 'Guddi - Chandor Rd, Chandor, Goa 403714', NULL, 0.88);

