INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000252, 331010, 'Dolphin-Spotting Boat Trips (Colva/Benaulim)', 'Dolphin-Spotting Boat Trips', 'Early-morning boat trips from Colva and Benaulim to spot dolphins in the Arabian Sea, a signature South Goa experience. Local fishermen and tour operators run the rides, most popular at sunrise.', '1-2 hours', 'Oct-Mar', 'Go as early as possible for the best sightings; seas are calmer and dolphins more active.', NULL, 'Goa', 0, 0, NULL, NULL, 'Pay per trip with operators (rates not published)', 4, 4, 15.276, 73.9125, 'Departure: Colva / Benaulim beaches, Salcete, Goa', NULL, 0.8);

