INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000255, 331010, 'Boomerang Beach Restaurant and Bar', 'Boomerang Beach Restaurant and Bar', 'A much-loved Colva beachfront shack and bar with a round bar, live music daily, and Goan-Indian-seafood plus international dishes — from jumbo prawns and kokum-based cocktails to tandoor grills. A favourite for sunset drinks and private beach parties.', '1.5-2 hours', 'Oct-Mar', 'Go around sunset for the live music; they also host beach parties and weddings for up to ~200 guests. (Official site boomerangcolva.com not fetched, so not listed above.)', NULL, 'Goa', 0, 0, NULL, NULL, 'Mid-range (price level moderate)', 4, 4, 15.278953, 73.913018, '4th Ward, Colva Beach Rd, Colva, Goa 403708', NULL, 0.8);

