INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000256, 331010, 'Kentuckee Seafood Restaurant', 'Kentuckee Seafood Restaurant', 'A long-running Colva Beach Road spot for fresh seafood and cocktails with late hours (open till 3 am per Justdial) and live music. Menu leans continental-steakhouse as well (monkey gland steak, chicken steak Diane), alongside seafood.', '1-1.5 hours', 'Year-round', 'One of the few late-night options around Colva; useful for post-beach evenings.', NULL, 'Goa', 0, 0, NULL, NULL, '~₹1,300 for two (per Justdial)', 3, 3, 15.2795, 73.9145, 'Colva Beach Road, Colva, Goa 403708', NULL, 0.6);

