INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (331000257, 331010, 'Sagar Kinara Pure Veg Restaurant', 'Sagar Kinara Pure Veg Restaurant', 'A pure-veg restaurant right by Colva Beach — a rarity among the seafood-heavy strip — serving Indian and Goan vegetarian fare like the Sagar Kinara Special Veg, veg tiranga and cashew nut makhani.', '1 hour', 'Year-round', 'Best veg option in the immediate beach area; go for thalis or the house specials.', NULL, 'Goa', 0, 0, NULL, NULL, '~₹750 for two (per Justdial)', 3, 3, 15.279, 73.914, 'Colva Beach, Colva, Goa 403708', NULL, 0.6);

