INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3310047, 331, 331010, 'Colva Fama (Feast of Menino Jesus)', 'Oct', 'Colva''s biggest feast: the second Monday of October marks the ceremonial opening of the Menino Jesus (Infant Jesus) shrine at Our Lady of Mercy Church, drawing thousands of pilgrims for early-morning Mass, a procession of the 17th-century statue and fireworks.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3310048, 331, 331010, 'Sao Joao (Feast of St. John the Baptist, Benaulim)', 'Jun', 'Feast of St. John the Baptist at the church on Monte Benaulim (June 24). After Mass, the Goa-wide Sao Joao tradition sees young men in leafy crowns jumping into wells and streams, singing ''Viva San Joao''.');

