INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000001, 332001, 'Sabarmati Ashram (Gandhi Ashram)', 'Sabarmati Ashram', 'Mahatma Gandhi''s headquarters from 1917 to 1930, from where he launched the Dandi March and the Salt Satyagraha. The riverside ashram houses the Gandhi Smarak Sangrahalaya museum with his letters, photographs, personal effects and charkha, plus the Upasna Mandir prayer ground, Hriday Kunj (his home) and Vinoba Kutir.', '2-3 hours', 'November to February; early morning for the calmest visit', 'Reach by 10 AM to do the museum before the crowds; shoes off in Hriday Kunj; keep phones on silent.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 5, 5, 23.05974, 72.57998, 'Gandhi Smarak Sangrahalaya, Ahmedabad 380027', 'https://gandhiashramsabarmati.org', 1.0);

