INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000002, 332001, 'Adalaj Stepwell (Adalaj Vav)', 'Adalaj Stepwell', 'Five-storey stepwell built in 1498/99 (Samvat 1555 per the Sanskrit inscription) by Queen Rudabai, wife of the Vaghela chief Veersinh, in memory of her husband. Famed for its carved pillars, octagonal well shaft and the Kalp Vriksha (''tree of life'') motifs; among Gujarat''s finest stepwells. Day trip about 18 km north of Ahmedabad.', '1-2 hours', 'November to February; late afternoon light is best for photography', 'Look for the ''tree of life'' Kalp Vriksha carving on the first level; combine with Gandhinagar''s Akshardham on the same day.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 5, 4, 23.1658, 72.5806, 'Adalaj, Gandhinagar, Gujarat 382421', NULL, 0.92);

