INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000003, 332001, 'Sidi Saiyyed Mosque (Sidi Saiyyed Ni Jali)', 'Sidi Saiyyed Mosque', 'Mosque built in 1572-73, world-famous for its exquisite carved stone lattice (jali) windows - especially the ''Tree of Life'' panel, now the symbol of Ahmedabad and the logo of IIM Ahmedabad. One of the finest examples of Indo-Islamic architecture in the city.', '45 minutes - 1 hour', 'November to February; morning light streaming through the jalis', 'Visit between 8-10 AM when sunlight streams through the Tree of Life jali for the classic photograph.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 4, 4, 23.02699, 72.58104, 'Mirzapur Road, Lal Darwaza, Bhadra, Ahmedabad 380001', NULL, 0.8);

