INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000004, 332001, 'Sarkhej Roza', 'Sarkhej Roza', 'Serene complex of Indo-Islamic buildings around a large artificial lake, centred on the tomb of the Sufi saint Ahmad Khattu Ganj Baksh, spiritual mentor of the Gujarat sultans. The mosque, mausoleum and pavilions are considered a precursor to the Indo-Saracenic style.', '1-2 hours', 'November to February; evening for the calmest atmosphere', 'Remove footwear and cover your head before entering the shrine; keep voices low - it is an active place of worship.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 3, 4, 22.99415, 72.50519, 'Makarba, Ahmedabad 380051', NULL, 0.68);

