INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000005, 332001, 'Calico Museum of Textiles', 'Calico Museum of Textiles', 'India''s premier textile museum, founded by the Sarabhai family, holding one of the world''s finest collections of Indian fabrics - Mughal and regional embroidery, pichhwais, religious textiles and royal costumes. Entry is only via the guided 10:30 AM tour; no photography; under-10s not allowed.', '2 hours', 'November to February', 'Book weeks ahead - only 20 visitors per tour; no photography inside; under-10s are not allowed.', 'Advance online booking is mandatory via calicomuseum.org (visitor slots limited to 20 per tour)', 'Gujarat', 0, 0, NULL, NULL, 'Free', 5, 5, 23.05461, 72.59219, 'The Retreat, Shahibaug, Ahmedabad 380004', 'https://calicomuseum.org', 1.0);

