INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000007, 332001, 'Kankaria Lake', 'Kankaria Lake', 'Vast polygonal lakefront built in 1451 by Sultan Qutbuddin Ahmad Shah II as Hauz-e-Qutub. The 2.25 km promenade has a toy train, balloon safari, kids'' city, zoo, butterfly park and the annual Kankaria Carnival; joggers enter free 4-8 AM, general entry Rs 25 adult / Rs 10 child.', '2-3 hours', 'November to February; evenings are liveliest', 'Go on a weekday evening to avoid crowds; the toy train and boating tickets sell out on weekends.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Rs 10-25', 4, 4, 23.00742, 72.59837, 'Maninagar, Ahmedabad 380008', NULL, 0.8);

