INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000008, 332001, 'Jama Masjid (Jumma Masjid)', 'Jama Masjid', 'Ahmedabad''s great congregational mosque, built in 1424 by Ahmed Shah I, founder of the city. Its vast pillared courtyard - 260 pillars supporting 15 domes - is among the largest and most beautiful mosques in India.', '45 minutes - 1 hour', 'November to February; early morning outside prayer times', 'Avoid prayer times (especially Friday noon); dress modestly and remove shoes before entering the courtyard.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 4, 4, 23.02422, 72.58694, 'Gandhi Road, Khadia, Ahmedabad 380001', NULL, 0.8);

