INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000010, 332001, 'Dada Harir Vav (Bai Harir Stepwell)', 'Dada Harir Vav', 'Quiet five-storey stepwell built in 1499 by Bai Harir Sultani, superintendent of the royal harem. With its carved Solanki-style pillars and a small mosque and tomb on the same campus, it is Ahmedabad''s finest in-city stepwell - free and rarely crowded.', '45 minutes - 1 hour', 'November to February; mid-morning light inside the well', 'Walk down to the lowest level for the best carvings; combine with the nearby Hutheesing Temple.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 3, 4, 23.040753, 72.605755, 'Asarwa, Ahmedabad', NULL, 0.68);

