INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000011, 332001, 'Nal Sarovar Bird Sanctuary', 'Nal Sarovar', 'Gujarat''s largest wetland bird sanctuary and a Ramsar site (declared 24 September 2012), about 60 km west of Ahmedabad. Winter brings flamingos, pelicans, cranes and ducks in the thousands; sunrise boat rides among the reeds are the classic experience. Open roughly 6 AM-5:30 PM.', 'Half day', 'November to February (peak migratory season); arrive by sunrise for birding', 'Start at sunrise from the Vekaria/boating side; carry binoculars and a warm layer for the boat ride.', NULL, 'Gujarat', 1, 0, NULL, NULL, NULL, 5, 5, 22.81917, 72.06355, 'Nal Sarovar Bird Sanctuary, near Sanand, Ahmedabad district, Gujarat', NULL, 1.0);

