INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000012, 332001, 'Lothal (Harappan Site & Museum)', 'Lothal', 'The 4,500-year-old Harappan port city, about 85 km southwest of Ahmedabad, with the world''s earliest known dock - a marvel of ancient engineering. The on-site archaeological museum (10 AM-5 PM, closed Fridays) displays beads, seals and tools excavated here.', 'Half day', 'November to February; mornings before the heat', 'Visit the museum first for context, then walk the excavated dock and warehouse remains; avoid Fridays.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 4, 4, 22.520981, 72.25017, 'Saragwala, Dholka, Ahmedabad district, Gujarat', NULL, 0.8);

