INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000013, 332001, 'Sun Temple, Modhera', 'Modhera Sun Temple', 'The 11th-century (1026-27 AD) Solanki-era Sun Temple built by King Bhimdev I, about 100 km north of Ahmedabad. The three-part complex - Surya Kund (stepped tank with 108 shrines), Sabha Mandap and Guda Mandap - is covered in exquisite carvings of gods, dancers and celestial beings.', '2-3 hours', 'November to February; early morning', 'Walk the Surya Kund''s 108 mini-shrines; stay for the Modhera Dance Festival (Uttarardha Mahotsav) in January if the dates align.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 5, 5, 23.58319, 72.13351, 'Modhera, Mehsana district, Gujarat', NULL, 1.0);

