INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000014, 332001, 'Sabarmati Riverfront', 'Sabarmati Riverfront', '11.25 km of continuous promenade, parks, gardens and event spaces along both banks of the Sabarmati. Home to the kite-shaped Atal Bridge (Rs 30 adult), the Flower Park and Glow Garden, river cruises and cycle tracks; the promenade itself is free, generally open 9 AM-9 PM.', '2-3 hours', 'November to February; sunset at the Atal Bridge', 'Buy Atal Bridge tickets at the upper-level counter (exact change helps); the bridge + Flower Park combo ticket is the best value.', NULL, 'Gujarat', 0, 1, NULL, NULL, 'Free (promenade)', 4, 4, 23.063013, 72.592509, 'Sabarmati Riverfront, Ahmedabad', NULL, 0.8);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (332000014, 332000014, '09:00-21:00', '09:00-21:00', '09:00-21:00', '09:00-21:00', '09:00-21:00', '09:00-21:00', '09:00-21:00', 'Promenade generally 9:00 AM-9:00 PM. Atal Bridge 9 AM-9 PM daily with tickets (Rs 30 adult, Rs 15 child) per published guides; river cruises ticketed separately.');

