INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000015, 332001, 'Law Garden Night Market', 'Law Garden Night Market', 'Ahmedabad''s beloved evening bazaar, famous for chaniya choli, bandhani, mirror-work kurtis and junk jewellery at bargain prices. Dozens of stalls line Law Garden after the late afternoon; bargaining is expected and the adjoining street-food lane fuels the shopping.', '1-2 hours', 'Year-round; evenings after 6 PM', 'Bargain hard - start at half the quoted price; check stitching and mirror-work quality before buying.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 3, 4, 23.025312, 72.560465, 'Netaji Road, Ellisbridge, Ahmedabad', NULL, 0.68);

