INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000016, 332001, 'Manek Chowk', 'Manek Chowk', 'The old city''s living square: a vegetable market by morning, jewellery bazaar by afternoon, and after about 9 PM one of India''s most famous late-night street-food hubs - kulfi, pav bhaji, dosa, bhaji pav and Gwalia kulfi falooda, served till past 1 AM.', '2-3 hours', '9 PM onwards for the night food market', 'Eat where the queues are; carry cash - many stalls don''t take cards; the kulfi sandwich is a must.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 4, 4, 23.02114, 72.59035, 'Khadia, Ahmedabad 380001', NULL, 0.8);

