INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000017, 332001, 'Bhadra Fort & Teen Darwaza', 'Bhadra Fort and Teen Darwaza', 'The 1411-15 fort-palace of Ahmed Shah I, founder of Ahmedabad, whose massive Teen Darwaza (triple gateway) remains the ceremonial heart of the old city. The fort complex now hosts government offices; the Teen Darwaza square stays lively with markets day and night.', '1 hour', 'November to February; daytime', 'Pair with Sidi Saiyyed Mosque and Manek Chowk - all three sit within the old walled city.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 3, 3, 23.02346, 72.58153, 'Court Road, Ahmedabad', NULL, 0.6);

