INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000018, 332001, 'Sardar Vallabhbhai Patel National Memorial', 'Sardar Vallabhbhai Patel National Memorial', 'Museum in the Moti Shahi Mahal (Shahibaug) dedicated to Sardar Vallabhbhai Patel, with his personal effects, photographs and documents on the freedom struggle and the integration of the princely states. Open 9:30 AM-5 PM, closed Mondays; entry Rs 20 adult / Rs 10 child; 3D show Sat-Sun 7-7:45 PM.', '1-2 hours', 'November to February', 'Time a weekend visit for the 7 PM 3D show; combine with the Calico Museum in Shahibaug.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Rs 10-20', 3, 4, 23.060688, 72.590785, 'Moti Shahi Mahal, Shahibaug, Ahmedabad', NULL, 0.68);

