INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000019, 332001, 'Jhulta Minar (Sidi Bashir Mosque)', 'Jhulta Minar', 'The ''Shaking Minarets'' of the Sidi Bashir Mosque (1452), near Ahmedabad Junction railway station. Only the two three-storey minarets and central arch survive - the mosque body was destroyed in 1753. Shaking one minaret makes the other vibrate while the connecting passage stays still; the mechanism remains unexplained. No climbing or demonstrations since 1981.', '30-60 minutes', 'November to February; weekday mornings for fewer crowds', 'View from the street outside; do not attempt to climb or shake the minarets - entry to the towers is prohibited.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 3, 3, 23.02776, 72.60093, 'Station Road, Kalupur, Ahmedabad 380002', NULL, 0.6);

