INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000020, 332001, 'Akshardham Temple, Gandhinagar', 'Akshardham', 'The BAPS Swaminarayan Akshardham in Gandhinagar (about 25 km from Ahmedabad): a pink-sandstone temple complex with an intricately carved mandir, Sahajanand Van garden and the after-sunset Sat-Chit-Anand water show. Open Tue-Sun 10 AM-7:30 PM, closed Mondays; temple and gardens free, exhibitions ticketed.', 'Half day', 'November to February; stay for the evening water show', 'No phones or cameras allowed inside - deposit them at the locker; plan 4-5 hours including the water show.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free (temple & gardens)', 5, 4, 23.229414, 72.67402, 'Akshardham, Gandhinagar, Gujarat', 'https://www.akshardham.com/gujarat/', 0.92);

