INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000026, 332001, 'Toran Dining Hall', 'Toran Dining Hall', 'No-frills, much-loved Gujarati dining hall (35 years in business per Justdial) serving unlimited thali - farsan, hot phulkas, shrikhand, rotis and subzis - at honest prices. 11 AM-3 PM and 7-10 PM; roughly Rs 950-1000 for two.', '1 hour', 'Lunch', 'A local favourite for an affordable unlimited thali; go at noon to get the freshest batches.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Rs 950-1000 (for two)', 3, 4, 23.03727, 72.56674, 'Ground Floor, Neelkamal Complex, Opposite Sales India, Ashram Road, Ahmedabad 380009', NULL, 0.68);

