INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3320001, 332, 332001, 'International Kite Festival', 'January', 'Gujarat''s flagship kite festival held on the Sabarmati Riverfront around Uttarayan (14 January): the sky fills with kites as international flyers join lakhs of locals on rooftops; kite markets across the old city sell for weeks beforehand.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3320002, 332, 332001, 'Kankaria Carnival', 'December', 'Week-long cultural festival (25-31 December) at the Kankaria Lakefront: food stalls, folk performances, adventure activities and fireworks marking the new year at the lake.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3320003, 332, 332001, 'Modhera Dance Festival (Uttarardha Mahotsav)', 'January', 'Classical dance festival held in the third week of January against the illuminated Sun Temple at Modhera (~100 km from Ahmedabad), organised by Gujarat Tourism.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3320004, 332, 332001, 'Navratri', 'September-October', 'Nine nights of garba and dandiya-raas across Ahmedabad''s grounds and clubs - the city''s biggest celebration, with all-night dancing, traditional chaniya choli and festive food.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3320005, 332, 332001, 'Ahmedabad Rath Yatra (Jagannath)', 'June-July', 'The 150+ year-old Jagannath Rath Yatra from the Jamalpur temple on Ashadhi Bij - Ahmedabad''s largest religious procession with decorated chariots, elephants and lakhs of devotees.');

-- city: Surat (id 1052)
INSERT OR IGNORE INTO cities (id, state_id, city_name, latitude, longitude) VALUES (332002, 332, 'Surat', 21.1702, 72.8311);

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000027, 332002, 'Dumas Beach', 'Dumas Beach', 'Surat''s most famous beach, about 20 km southwest of the city on the Arabian Sea, known for its dark grey-black sand and wide shoreline. Popular for evening walks, sunsets and beachside street food stalls; local legend calls it haunted, which adds to its fame. Swimming is discouraged due to strong currents.', '2-3 hours', 'October to March; evenings for sunset', 'Go for sunset and the food stalls; do not swim — currents are strong and the beach is officially unsafe for bathing.', NULL, 'Gujarat', 0, 1, NULL, '18:30', 'Free', 5, 4, 21.08484, 72.70949, 'Dumas, Surat, Gujarat 394550', NULL, 0.92);

