INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000028, 332002, 'Surat Castle (Old Fort)', 'Surat Castle (Old Fort)', 'A 16th-century fort built around 1540 under Sultan Mahmud III of Gujarat, later a key Mughal and then British stronghold guarding the Tapi river trade. Today it houses government offices and offers river views; it anchors Surat''s old-city heritage walk. The fort''s layered Islamic and European-influenced architecture reflects Surat''s port-city past.', '1-2 hours', 'October to March, mornings', 'Combine with a walk through the old Chowk area; exterior and river views are the main draw since offices occupy the interior.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 4, 3, 21.1963, 72.818, 'Nehru Bridge, Chowk, Surat, Gujarat 395003', NULL, 0.72);

