INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000029, 332002, 'Dutch Garden', 'Dutch Garden', 'A European-style landscaped garden in Nanpura built around the colonial-era Dutch and English tombs and cemeteries of Surat''s 17th-century trading past. It blends quiet lawns and walking paths with genuine heritage — the tombs of Dutch East India Company merchants. A calm green break in the busy old city.', '1 hour', 'October to March; mornings and evenings', 'Look for the old Dutch tombs and cemetery monuments — the garden''s history is its real attraction, not just the lawns.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 3, 3, 21.19151, 72.81484, 'Nanpura, Surat, Gujarat 395014', NULL, 0.6);

