INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000030, 332002, 'Sardar Patel Museum', 'Sardar Patel Museum', 'Surat''s main multipurpose museum, founded in 1890 (as the Winchester Museum) and renamed after independence; it now sits in the Science Centre complex at City Light. Collections span wood, metal, ivory and stone antiques, old oil paintings, miniatures, textiles, manuscripts and terracotta. Good for Surat''s history, zari textiles and the diamond-industry story.', '2 hours', 'Year-round; weekday mornings are quietest', 'Pair it with the Science Centre and planetarium next door — the combined complex fills a full family morning.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Rs 20', 4, 3, 21.17042, 72.79549, 'City Light Road, behind Science Centre, Surat, Gujarat 395007', NULL, 0.72);

