INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000031, 332002, 'Gopi Talav', 'Gopi Talav', 'A historic lake in the old city redeveloped by the Surat Municipal Corporation with landscaped promenades, boating, food courts and evening lighting. Named after Malik Gopi, the 16th-century merchant who shaped old Surat. A favourite local evening hangout rather than a grand monument.', '1-2 hours', 'Evenings for lights and boating', 'Go after dark when the lake is lit; boating charges apply at the counter — carry cash.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 3, 3, 21.18977, 72.82842, 'Rustampura, Surat, Gujarat 395002', NULL, 0.6);

