INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000032, 332002, 'Sarthana Nature Park and Zoo', 'Sarthana Nature Park and Zoo', 'Surat''s municipal zoo, officially the Dr. Shyamaprasad Mukherjee Zoological Garden, spread over about 81 acres (32.78 ha) at Sarthana. Houses lions, tigers, leopards, bears, crocodiles, deer and many birds, plus a nature park for walks and picnics. One of the most affordable family outings in the city.', '3-4 hours', 'October to March; 10 AM to 1 PM to see animals active', 'Arrive at opening (10 AM) — animals are most active in the morning and crowds build by noon. Carry water; food options are basic.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Rs 15', 4, 4, 21.23234, 72.89879, 'Opposite Old Sarthana Octroi Naka, Surat-Kamrej Road, Sarthana, Surat, Gujarat 395006', 'https://www.suratmunicipal.gov.in/Services/NatureParkHome', 0.8);

