INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000033, 332002, 'Jagdishchandra Bose Aquarium', 'Jagdishchandra Bose Aquarium', 'A large public aquarium at Pal/Adajan inaugurated on 1 March 2014 and named after scientist Jagadish Chandra Bose; described as India''s first multidisciplinary underwater aquarium. Features marine and freshwater sections, sharks, jellyfish, stingrays and a glass tunnel. A solid family stop, especially in summer.', '1-2 hours', 'Year-round; weekday afternoons are less crowded', 'Avoid weekends and public holidays — it gets packed. The glass tunnel is the highlight; budget 1-2 hours.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 4, 4, 21.18466, 72.79179, 'Adajan Gam, Adajan, Surat, Gujarat 395009', NULL, 0.8);

