INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000034, 332002, 'ISKCON Temple, Surat', 'ISKCON Temple, Surat', 'Surat''s ISKCON temple at Jahangirpura, a major Krishna devotional centre with a grand shikhara-style complex, daily aartis, kirtans and a vegetarian prasadam hall. Draws large crowds on Janmashtami and weekends. Peaceful gardens around the temple make it a calm visit.', '1-2 hours', 'Mornings or during evening aarti', 'Time your visit for the evening aarti for the full experience; prasadam meals are available at the temple hall.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 3, 4, 21.24142, 72.78892, 'Jahangirpura, Surat, Gujarat 395005', NULL, 0.68);

