INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000035, 332002, 'Chintamani Jain Temple', 'Chintamani Jain Temple', 'A celebrated 17th-century Jain temple in the Shahpore area, built late in Aurangzeb''s reign (around 1699). Its plain exterior hides extraordinary interiors: carved wooden pillars and brackets with vegetable-dye paintings, plus rare paintings of Acharya Hemachandra and Solanki king Kumarpal. One of Surat''s finest heritage interiors.', '1 hour', 'Mornings', 'Photography inside requires permission from the trustees — ask before shooting. Dress modestly as it is an active place of worship.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 4, 4, 21.2023, 72.82226, 'Shahpore Main Road, Surat, Gujarat 395003', NULL, 0.8);

