INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000036, 332002, 'Ambika Niketan Temple', 'Ambika Niketan Temple', 'One of Surat''s most beloved temples, on the banks of the Tapi at Athwalines. The two-storey shrine built in 1969 houses Ashtabhuja Ambika (eight-armed form of Shakti), with smaller shrines to Ram, Sita, Shiva and Laxminarayan. Throngs with devotees during Navratri; the riverside setting is part of the experience.', '1-2 hours', 'Mornings; Navratri for the festive atmosphere', 'Walk down to the river ovaro (steps) beside the temple for the Tapi view; expect crowds and narrow lanes around the temple during festivals.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 4, 4, 21.1783, 72.793, 'Dumas Road, Parle Point, Athwalines, Surat, Gujarat 395007', NULL, 0.8);

