INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000037, 332002, 'Tapi Riverfront', 'Tapi Riverfront', 'Surat''s developing riverfront promenade along the Tapi at Adajan, with walkways, seating and river views. Popular for morning walks and relaxed evenings watching the river. The weir-cum-causeway area nearby is a known local sunset point.', '1 hour', 'Mornings and evenings', 'Best as a relaxed evening stroll; combine with dinner in Adajan afterwards.', NULL, 'Gujarat', 0, 1, NULL, '18:30', 'Free', 3, 3, 21.19545, 72.80997, 'J P Nagar Road, Adajan, Surat, Gujarat 395009', NULL, 0.6);

