INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000038, 332002, 'Sneh Rashmi Botanical Garden', 'Sneh Rashmi Botanical Garden', 'A large municipal botanical garden in the Bhesan area run by the Surat Municipal Corporation, with themed plant sections, lawns and walking trails. A quieter alternative to the city-centre parks, good for nature walks and family picnics.', '1-2 hours', 'October to March; mornings', 'Carry water and snacks — facilities inside are limited; good for a slow morning walk.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 3, 3, 21.2204, 72.76415, 'Bhesan Road, Bhesan, Surat, Gujarat 395005', NULL, 0.6);

