INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000039, 332002, 'Millennium Textile Market', 'Millennium Textile Market', 'One of Surat''s landmark wholesale textile markets near Sahara Darwaja, in the heart of the city''s fabric-trading district. Surat is India''s largest man-made fabric hub, and this market is where sarees, dress materials and fabrics trade in bulk. Lively, crowded and very ''Surat''.', '1-2 hours', 'Weekday mornings for business; afternoons for browsing', 'Many shops are wholesale-only — ask before expecting retail; bargain politely and keep valuables secure in the crowds.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 3, 3, 21.18898, 72.84124, 'Sahara Darwaja, Umarwada, Surat, Gujarat 395002', NULL, 0.6);

