INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000040, 332002, 'Aqua Imagicaa Water Park, Surat (Amaazia)', 'Aqua Imagicaa Water Park (Amaazia), Surat', 'Surat''s big water and amusement park on Canal Road, formerly branded Amaazia and now operating as Aqua Imagicaa Water Park. Rides span thrill slides (King Kobra, Twister, Kamikaze), family rides and a kids'' zone plus a wave pool. The main summer/weekend family outing in the city.', 'Full day (5-6 hours)', 'March to June (summer); avoid monsoon closures', 'Book online for weekends; carry swimwear and a change of clothes — costume and locker rentals cost extra at the gate.', 'Online booking available; weekends sell out — book ahead', 'Gujarat', 0, 0, NULL, NULL, NULL, 4, 4, 21.19408, 72.86529, 'Canal Road, Opp. Dumbal Transport Godown, Magob, Parvat Patiya, Surat, Gujarat 395010', NULL, 0.8);

