INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000041, 332002, 'Suvali Beach (day trip)', 'Suvali Beach', 'A quieter black-sand beach near Hazira, about 25 km southwest of Surat — a day trip for those who find Dumas too crowded. Known for calm sunrise and sunset views over the Arabian Sea and a more local, uncommercial feel. The nearby Suvali village has historic Portuguese-era associations.', '2-3 hours', 'October to March; sunrise or sunset', 'There are few facilities — carry food and water, and leave before dark as the area is isolated.', NULL, 'Gujarat', 1, 1, '06:30', '18:30', 'Free', 3, 3, 21.164, 72.628, 'Suvali, Hazira, Surat, Gujarat', NULL, 0.6);

