INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000042, 332002, 'National Salt Satyagraha Memorial, Dandi (day trip)', 'National Salt Satyagraha Memorial, Dandi', 'About 45 km south of Surat, the National Salt Satyagraha Memorial at Dandi commemorates Gandhi''s 1930 Salt March endpoint. The memorial complex includes statues of the marchers, a lake, solar trees and exhibits on the march. A significant national-heritage day trip from Surat.', 'Half day', 'October to March', 'Combine with Dandi beach nearby; allow a half day including the drive from Surat.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 4, 4, 20.89144, 72.80218, 'Dandi, Jalalpore, Navsari, Gujarat 396439', NULL, 0.8);

