INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000043, 332002, 'Iranshah Atash Behram, Udvada (day trip)', 'Iranshah Atash Behram, Udvada', 'About 35 km south of Surat, Udvada is the global spiritual capital of the Parsi Zoroastrian community and home to the sacred Iranshah Atash Behram — the oldest continuously burning fire temple fire in India, brought from Iran over a thousand years ago. The village also has heritage Parsi homes and a small museum. Non-Parsis cannot enter the fire temple sanctum but can see the complex from outside.', 'Half day', 'October to March', 'Non-Parsis are not permitted inside the Atash Behram — respect the restriction; try the famous Parsi-style lunch at a local eatery instead.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 4, 4, 20.4624, 72.91703, 'Udvada, Pardi, Valsad, Gujarat 396185', NULL, 0.8);

