INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000044, 332002, 'Tithal Beach, Valsad (day trip)', 'Tithal Beach, Valsad', 'A popular black-sand beach at Valsad, about 40 km south of Surat and an easy day trip. Known for its long shoreline, sunset views and beachside food stalls. More developed for tourists than Suvali, with the Swaminarayan temple nearby.', '2-3 hours', 'October to March; evenings', 'Go for the sunset; the beach is at its best on weekday evenings when crowds are thinner.', NULL, 'Gujarat', 0, 1, NULL, '18:30', 'Free', 3, 3, 20.59795, 72.8953, 'Tithal, Valsad, Gujarat 396001', NULL, 0.6);

