INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000045, 332002, 'Ukai Dam (day trip)', 'Ukai Dam', 'About 100 km east of Surat, the Ukai Dam on the Tapi is Gujarat''s second-largest reservoir. The dam viewpoint and surrounding gardens draw day-trippers, especially in the monsoon and just after, when the reservoir is full. A relaxed picnic-style outing rather than a major attraction.', 'Half day', 'July to February, when the reservoir is full', 'Carry food — options near the dam are limited; the viewpoint is best in the late afternoon light.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 3, 3, 21.23718, 73.57699, 'Ukai, Songadh, Tapi, Gujarat 394670', NULL, 0.6);

