INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000046, 332002, 'Vansda National Park (day trip)', 'Vansda National Park', 'A 24 sq km national park in Navsari district, roughly 100 km southeast of Surat, protecting dense moist-deciduous Sahyadri forest on the Ambika river. Home to leopards, hyenas, barking deer, four-horned antelope and 200+ bird species, plus the Gira waterfalls nearby. Entry is via the Kilad gate on the Waghai-Vansda road; a Gujarat forest-department campsite supports ecotourism.', 'Full day', 'November to March', 'This is a full-day trip — start early from Surat; carry binoculars for birding and confirm safari slots with the forest department beforehand.', 'Safaris and the Kilad campsite are managed by the Gujarat Forest Department — book/confirm in advance', 'Gujarat', 0, 0, NULL, NULL, NULL, 4, 4, 20.733, 73.467, 'Vansda, Navsari, Gujarat', NULL, 0.8);

