INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000047, 332002, 'Sasumaa Gujarati Thali', 'Sasumaa Gujarati Thali', 'One of Surat''s best-known Gujarati thali restaurants, serving an unlimited traditional thali with farsan, shaak, dal-kadhi, rotli, rice, sweets and chaas. A local favourite for festive family lunches; it gets packed by 2 PM on weekends. Pure vegetarian.', '1 hour', 'Lunch (11:30 AM-3:30 PM) or dinner (7-10:30 PM)', 'Go for lunch to get the full thali spread; arrive before 1 PM on weekends to avoid the rush.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Rs 340', 5, 4, 21.183106, 72.814791, 'Mangal Deep Complex, Ring Rd, opp. Vanita Vishram Ground, Majura Gate, Surat, Gujarat 395001', NULL, 0.92);

