INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000048, 332002, 'Kansar Gujarati Thali', 'Kansar Gujarati Thali', 'A long-running Surat institution for the unlimited Gujarati thali — homely, pocket-friendly and popular with families and bachelors alike. Serves the classic spread: shaak, dal, kadhi, farsan, rotli, khichdi, sweets and buttermilk. Also has a branch at Trinity Business Park, LP Savani Road, Adajan.', '1 hour', 'Lunch or dinner hours', 'The unlimited thali is the point — come hungry; takeaway tiffins are also popular with locals.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 4, 4, 21.18374, 72.81433, 'President Plaza, 101-104 Ring Road, near Old RTO, Nanpura, Surat, Gujarat 395001', NULL, 0.8);

