INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 332000048, 'insert', 'bulk', 'Real, operating restaurant confirmed via Tripadvisor (285 reviews, ranked #16 of 1033 Surat restaurants) and top-rated.online (4K reviews, #2 Gujarati restaurant in Surat). No verifiable official website found (directory listings show dead/placeholder domains) — official_website null. Coordinates from map geocoder at President Plaza, Ring Road (21.18374, 72.81433).', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000049, 332002, 'Jalaram Khichdi', 'Jalaram Khichdi', 'A Surat-born brand (since 2003) famous for its Rajwadi Khichdi, grown from a single food stall into a multi-branch Gujarati and Punjabi vegetarian restaurant. The Parle Point outlet is the flagship; a second branch is at Marvella Corridor, New VIP Road, Vesu. Known for homely, generously spiced khichdi-kadhi comfort food.', '1 hour', 'Lunch (11 AM-3:30 PM) or dinner (7-11 PM)', 'Order the Rajwadi Khichdi with Maharaj Kadhi — that is the signature combination locals swear by.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 5, 4, 21.170597, 72.788759, 'L-17,18,19 Anmol Complex, Near Sargam Shopping Centre, Parle Point, Surat, Gujarat 395007', 'https://www.jalaramkhichdi.in/', 0.92);

