INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000050, 332002, 'Gopal Khaman House (Gopaal Loccho)', 'Gopal Khaman House (Gopaal Loccho)', 'A famous old-city Surat eatery in Zampa Bazaar, synonymous with Surati locho — the steamed, crumbled khaman snack topped with sev, pomegranate, chutneys and butter. Also serves khaman, dhokla and other Gujarati farsan. A genuine street-food institution locals queue at for breakfast and evening snacks.', '30-45 minutes', 'Morning for fresh khaman; evenings for locho', 'This is the place to try authentic Surati locho — go early in the day when the khaman is freshest.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 5, 4, 21.203913, 72.836176, '6/397, Kharadi Sheri, Zampa Bazaar, Surat, Gujarat', 'http://www.gopalkhamanhouse.com/', 0.92);

