INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000051, 332002, 'Jalaram Khichadi Kadhi Center', 'Jalaram Khichadi Kadhi Center', 'A beloved lunch-only Kathiyawadi eatery in old-city Mahidharpura, famous for its palak khichadi and kadhi served fast to a noon-hour crowd. Hygienic, quick and cheap — the kind of no-frills local lunch spot Surat is famous for. Opens only for lunch and closes Sundays.', '30-45 minutes', '11:30 AM-1 PM on weekdays (before the noon rush)', 'It is lunch-only and the noon rush is real — arrive by 11:30 AM. Try the palak khichadi, the house signature.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 4, 4, 21.20402, 72.83306, '6/1508, Arihant Darshan, Kansara Sheri Rd, Hira Bazar, Mahidharpura, Surat, Gujarat 395003', NULL, 0.8);

