INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000052, 332002, 'Maakhan Bhog', 'Maakhan Bhog', 'A well-known Surat sweets and snacks brand with a busy Adajan outlet, famous locally for Surati specialties including ghari (the festive sweet Surat is known for), farsan and chaat. A good stop to taste Surat''s mithai culture; also a useful take-home sweets shop.', '30 minutes', 'Evenings', 'Ask for seasonal Surati specials — ghari around festive season and ponk items in winter are the local favourites.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 4, 4, 21.20254, 72.78919, 'Honey Park Road, Adajan, Surat, Gujarat 395009', NULL, 0.8);

