INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3320006, 332, 332002, 'Chandi Padvo', 'October', 'Surat''s own firecracker festival celebrated the day after Dussehra, when the city famously bursts crackers through the night; a uniquely Surati tradition tied to the diamond and textile merchant community.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3320007, 332, 332002, 'Navratri', 'September-October', 'Nine nights of garba and dandiya raas; Surat hosts some of Gujarat''s biggest garba venues and the whole city dances through the nights.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3320008, 332, 332002, 'Diwali', 'October-November', 'Festival of lights celebrated across Surat with fireworks, sweets (notably Surati ghari) and new clothes; markets in the old city stay packed late.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3320009, 332, 332002, 'Uttarayan (Makar Sankranti)', 'January', 'The kite festival on Makar Sankranti; Surat''s skies fill with kites and rooftops host kite-flying parties with undhiyu and jalebi.');

