INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000053, 332003, 'Laxmi Vilas Palace', 'Laxmi Vilas Palace', 'Laxmi Vilas Palace is the four-times-the-size-of-Buckingham-Palace royal residence of the Gaekwads of Baroda, built 1878-1890 for Sayajirao Gaekwad III in Indo-Saracenic style. Still the private residence of the Gaekwad family, it opens select interiors to visitors, including the Darbar Hall with its Venetian mosaics, stained glass and the famous elephant-gun armoury; the palace grounds also host Navratri celebrations.', '2-3 hours', 'October to March', 'Carry a government photo ID; palace security is tight. Go on a weekday morning to avoid crowds and combine with the Fateh Singh Museum on the campus.', 'Tickets on the official Gaekwar Enterprise booking portal; walk-ins also accepted', 'Gujarat', 0, 0, NULL, NULL, 'Rs 150-250 (Indian adults, approx); higher for foreign nationals; museum combo extra', 5.0, 4.7, 22.293896, 73.191801, 'J N Marg, near Polo Ground, Vadodara, Gujarat 390001, India', 'https://lvpbooking.gaekwarenterprise.com/homepage', 0.976);

