INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 332000053, 'insert', 'bulk', 'Confirmed real. Coordinates from the palace''s own booking site (lvpbooking.gaekwarenterprise.com, fetched 2026-09-30: genuine Gaekwar Enterprise portal, header ''Lukshmi Villas Palace'', ''constructed by the Gaekwar family''). Hours (Tue-Sun 9:30-17:00, closed Mon) and fee band (Rs 150-250 Indian adults, higher for foreign nationals, museum combo extra) cross-checked against bharattravelguru.com, inheritage.foundation, nativeplanet.com and captureatrip.com.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000054, 332003, 'Maharaja Fateh Singh Museum', 'Maharaja Fateh Singh Museum', 'The Maharaja Fateh Singh Museum, housed in the former school for the Gaekwad royal children on the Laxmi Vilas Palace campus, holds one of India''s finest collections of paintings by Raja Ravi Varma, including commissioned royal portraits, plus European art, marble and bronze sculptures, and Mughal-period artefacts. The collection was assembled by Sayajirao Gaekwad III and is displayed in a building next to the palace''s Motibaug cricket ground.', '1-2 hours', 'October to March', 'Buy the combo ticket with the palace; photography rules are strict inside the galleries.', 'Not required; tickets at the counter', 'Gujarat', 0, 0, NULL, NULL, 'Rs 60-80 (Indian adult, approx)', 4.5, 4.3, 22.28968, 73.191345, 'Lukshmi Vilas Palace Estate, J N Marg, Vadodara, Gujarat 390001, India', NULL, 0.884);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (332000054, 332000054, NULL, '9:30 AM - 5:30 PM', '9:30 AM - 5:30 PM', '9:30 AM - 5:30 PM', '9:30 AM - 5:30 PM', '9:30 AM - 5:30 PM', '9:30 AM - 5:30 PM', 'Open Tuesday-Sunday 9:30 AM to 5:30 PM; closed Monday. Justdial lists identical hours; webindia123 lists a seasonal split-hours variant (10-12:30 and 2:30-5:30 in summer), so confirm before visiting.');

