INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 332000054, 'insert', 'bulk', 'Confirmed real: gujarattourism.com listing places it on the LVP campus (22.28968, 73.191345); Justdial confirms Tue-Sun 9:30-17:30 hours; Triphobo/TripAdvisor reviews give Rs 60-80 Indian-adult fee band. No official website found.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000055, 332003, 'Sayaji Baug', 'Sayaji Baug (Kamati Baug)', 'Sayaji Baug (Kamati Baug) is Vadodara''s 45-hectare central garden, laid out in 1879 by Sayajirao Gaekwad III on the banks of the Vishvamitri and counted among western India''s largest public gardens. It bundles the Baroda Museum & Picture Gallery, the Sardar Patel Planetarium, the Sayaji Baug Zoo and a toy train, making it the city''s default family outing and morning-walk circuit.', '2-4 hours', 'October to March', 'Arrive at opening for the quietest walks; the museum, zoo and planetarium each charge separate small tickets on top of free garden entry.', 'Not required', 'Gujarat', 1, 0, '06:45', NULL, 'Free (garden); museum/zoo/planetarium ticketed separately', 4.5, 4.3, 22.313111, 73.187989, 'Sayaji Baug, Sayajigunj, Vadodara, Gujarat 390005, India', NULL, 0.884);

