INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000056, 332003, 'Baroda Museum & Picture Gallery', 'Baroda Museum & Picture Gallery', 'The Baroda Museum & Picture Gallery, inside Sayaji Baug, was founded by Sayajirao Gaekwad III in 1894 and is one of Gujarat''s oldest museums. Its galleries cover geology, archaeology, natural history and art, with Egyptian mummies, Tibetan art, Mughal miniatures and European paintings among the highlights.', '1-2 hours', 'October to March', 'Visit mid-morning to cover the museum before the afternoon zoo crowd; carry change for the Rs 10 entry.', 'Not required', 'Gujarat', 0, 0, NULL, NULL, 'Rs 10 (adult) / Rs 5 (child)', 4.0, 4.0, 22.313111, 73.187989, 'Sayaji Baug, Sayajigunj, Vadodara, Gujarat 390005, India', NULL, 0.8);

