INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000057, 332003, 'Sardar Patel Planetarium', 'Sardar Patel Planetarium', 'The Sardar Patel Planetarium, inside Sayaji Baug, is Vadodara''s digital sky theatre running short astronomy shows in three languages. Each 35-minute show covers the solar system and the night sky and is a favourite stop for school groups and families visiting the garden.', '1 hour', 'October to March', 'Pick the English show at 5 PM; arrive 15 minutes early as seats fill fast on weekends.', 'Not required', 'Gujarat', 0, 0, NULL, NULL, 'Rs 7 (adult) / Rs 5 (child)', 3.5, 3.8, 22.313111, 73.187989, 'Sayaji Baug, Sayajigunj, Vadodara, Gujarat 390005, India', NULL, 0.724);

