INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000058, 332003, 'Sayaji Baug Zoo', 'Sayaji Baug Zoo', 'The Sayaji Baug Zoo, inside Sayaji Baug, dates to 1879 and is one of western India''s oldest zoological gardens. It houses lions, tigers, leopards, elephants, crocodiles and a large bird collection in enclosures spread across the garden, and remains a staple family visit despite its vintage enclosures.', '1-2 hours', 'October to March', 'Use the morning slot (8:00-11:30 AM) when animals are most active; the afternoon slot opens at 2:30 PM.', 'Not required', 'Gujarat', 0, 0, NULL, NULL, 'Rs 10 (adult) / Rs 5 (child)', 3.5, 3.5, 22.313111, 73.187989, 'Sayaji Baug, Sayajigunj, Vadodara, Gujarat 390005, India', NULL, 0.7);

