INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000059, 332003, 'EME Temple (Dakshinamurthy Temple)', 'EME Temple (Dakshinamurthy Temple)', 'The EME Temple, built in 1966 by the Indian Army''s Electrical and Mechanical Engineers (EME) School, is a one-of-a-kind aluminium-clad geodesic temple dedicated to Dakshinamurthy, a form of Shiva. Designed along Buckminster Fuller''s geodesic-dome principle, it blends symbols of all major faiths (Hindu kalash, Islamic dome, Christian tower, Buddhist finial, Jain entrance), and its lawns display over 100 ancient stone statues from the 6th to 16th centuries.', '1-1.5 hours', 'October to March', 'Carry a government ID for the army-gate check, leave cameras at the gate (photography is strictly prohibited), and walk the 200 m from the gate to the dome.', 'Not required', 'Gujarat', 0, 0, NULL, NULL, 'Free', 4.5, 4.5, 22.33163, 73.19167, 'EME School campus, EME Rd, Fatehgunj, Vadodara, Gujarat 390002, India', NULL, 0.9);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (332000059, 332000059, '6:30 AM - 8:30 PM', '6:30 AM - 8:30 PM', '6:30 AM - 8:30 PM', '6:30 AM - 8:30 PM', '6:30 AM - 8:30 PM', '6:30 AM - 8:30 PM', '6:30 AM - 8:30 PM', 'Open daily 6:30 AM to 8:30 PM; free entry; government ID required at the army gate; photography prohibited. No official website found.');

