INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 332000059, 'insert', 'bulk', 'Confirmed real: Wikipedia (EME_Temple) and OpenStreetMap/mapcarta.com/W322435731 both place it at 22.33163, 73.19167 (matches gujarattourism.com listing 22.331307, 73.191753; an earlier Wikipedia-derived estimate of 22.2931, 73.1589 was incorrect and discarded). Hours and free entry from holidify.com/makemytrip.com; TripAdvisor reviews confirm the ID check and photography ban. No official website found.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000060, 332003, 'Sursagar Lake', 'Sursagar Lake (Chand Talao)', 'Sursagar Lake (Chand Talao) is Vadodara''s historic central lake, rebuilt in stone masonry in the 18th century and retaining water year-round. Its centrepiece is a 111-ft Sarveshwar Mahadev (Shiva) statue installed between 1996 and 2002; it is the city''s favourite sunset-and-evening promenade, with boating, weekend lighting and Mahashivratri illumination.', '1-2 hours', 'October to March', 'Go at sunset for the best view of the Shiva statue; weekend evenings have special lighting. Avoid driving here at peak traffic hours.', 'Not required', 'Gujarat', 0, 1, NULL, '18:15', 'Free (boating extra, nominal)', 4.0, 4.2, 22.30083, 73.20361, 'Sursagar, Mandvi, Vadodara, Gujarat 390001, India', NULL, 0.816);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (332000060, 332000060, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Public lake promenade; no gated entry. Sources conflict: gujaratdarshanguide.com lists 7:00 AM-9:00 PM while blogs call it effectively 24 hours, so hours are left unpublished; visit during daylight/evening hours.');

