INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000061, 332003, 'Kirti Mandir', 'Kirti Mandir', 'Kirti Mandir, the ''Temple of Fame'', is the Gaekwad family cenotaph built in 1936 by Sayajirao Gaekwad III on the cremation ground of the royal family near Kalaghoda. Its marble interiors carry fine murals depicting scenes from the Mahabharata, Ramayana and the life of Sayajirao, and it commemorates fifty years of his rule.', '45 minutes - 1 hour', 'October to March', 'Combine with nearby Mandvi Gate and Nyaya Mandir in the old city; mornings are quietest.', 'Not required', 'Gujarat', 0, 0, NULL, NULL, 'Free', 3.8, 4.0, 22.307511, 73.190896, 'Kalaghoda, Vadodara, Gujarat 390001, India', NULL, 0.776);

