INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000062, 332003, 'Nyaya Mandir', 'Nyaya Mandir (Temple of Justice)', 'Nyaya Mandir, the ''Temple of Justice'', is Vadodara''s Indo-Saracenic district court building opened on 30 November 1896. Designed by architect Robert Chisholm with Byzantine-inspired arches and domes, it is one of Baroda''s grandest colonial-era public buildings and still houses the Vadodara District Court, so visitors admire it from outside.', '20-30 minutes', 'October to March', 'It is a working courthouse - admire the facade and photograph it from the street; combine with Sursagar Lake and Khanderao Market nearby.', 'Not required', 'Gujarat', 0, 0, NULL, NULL, 'Free (exterior viewing)', 3.5, 3.5, 22.2966, 73.2015, 'Chamaraja Rd, near Sursagar, Vadodara, Gujarat 390001, India', NULL, 0.7);

