INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000063, 332003, 'Tambekar Wada', 'Tambekar Wada', 'Tambekar Wada is the 19th-century multistoreyed Maratha wooden mansion that was once the residence of Bhau Tambekar, diwan of Baroda (1849-54). Its walls, doors, ceilings and jali work carry about 300 polychrome Maratha-style murals - among Gujarat''s finest - depicting Krishna''s life, the Mahabharata, Ganesha and Anglo-Maratha battle scenes; most have been restored by the Archaeological Survey of India (dated 1874 per ASI).', '45 minutes - 1 hour', 'October to March', 'Interiors are poorly lit, so carry a phone torch for the murals; ask the caretaker for context on the restoration.', 'Not required', 'Gujarat', 0, 0, NULL, NULL, 'Free', 4.0, 4.1, 22.302804, 73.199151, 'Tambekar no Khancho, Pratap Rd, Raopura, Vadodara, Gujarat 390001, India', NULL, 0.808);

