INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000064, 332003, 'Champaner-Pavagadh Archaeological Park', 'Champaner-Pavagadh Archaeological Park', 'Champaner-Pavagadh Archaeological Park, about 50 km from Vadodara, is a UNESCO World Heritage Site (2004) preserving the 8th-16th-century capital of the Gujarat Sultanate. Its highlights include the Jami Masjid - a masterpiece of Indo-Islamic architecture - the Saat Kaman arches, the helical stepwell, Hindu and Jain temples on Pavagadh Hill, and fort ramparts spread over 1,329 hectares.', '4-6 hours (full day with Kalika Mata Temple)', 'October to March', 'Start early and combine the park with the Kalika Mata Temple ropeway (separate entry below); carry water - the site is sprawling with limited shade.', 'Not required', 'Gujarat', 0, 0, NULL, NULL, 'Rs 30-40 (Indian) / Rs 500-600 (foreign)', 5.0, 4.6, 22.4846, 73.5329, 'Champaner, Panchmahal district, Gujarat 389360, India', NULL, 0.968);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (332000064, 332000064, '8:30 AM - 5:00 PM', '8:30 AM - 5:00 PM', '8:30 AM - 5:00 PM', '8:30 AM - 5:00 PM', '8:30 AM - 5:00 PM', '8:30 AM - 5:00 PM', '8:30 AM - 5:00 PM', 'Daily 8:30 AM-5:00 PM per travel guides. UNESCO-listed site (World Heritage since 2004); about 50 km / 1 hour from Vadodara - a day trip.');

