INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000065, 332003, 'Ajwa-Nimeta Garden', 'Ajwa-Nimeta Garden', 'Ajwa-Nimeta Garden is Vadodara Municipal Corporation''s landscaped garden and picnic spot around 23 km east of the city, beside the Ajwa reservoir. Families come for the lawns, boating and especially the evening musical fountain and laser show; Nimeta is the adjoining garden across the Vishvamitri.', '2-3 hours', 'October to March', 'Go in the evening for the musical fountain; combine with a sunset at the Ajwa reservoir.', 'Not required', 'Gujarat', 0, 1, NULL, '18:15', 'Rs 20 (adult) / Rs 15 (child)', 3.8, 4.0, 22.374577, 73.383708, 'Ajwa, Vadodara, Gujarat 390019, India', NULL, 0.776);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (332000065, 332000065, '10:30 AM - 9:00 PM', '10:30 AM - 9:00 PM', '10:30 AM - 9:00 PM', '10:30 AM - 9:00 PM', '10:30 AM - 9:00 PM', '10:30 AM - 9:00 PM', '10:30 AM - 9:00 PM', '10:30 AM-9:00 PM per travelsetu.com (thrillophilia.com says 8 AM-9 PM - minor conflict). The VMC page vmc.gov.in/AjvaGarden.aspx could not be loaded at research time (HTTP 500), so it is not listed as official site.');

