INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000066, 332003, 'Jambughoda Wildlife Sanctuary', 'Jambughoda Wildlife Sanctuary', 'Jambughoda Wildlife Sanctuary, about 70 km southeast of Vadodara in the Panchmahal region, is a dry-teak forest reserve known for leopards, sloth bears, hyenas and rich birdlife. There are no jeep safaris - visitors explore on guided nature walks and forest rest-house stays, making it a quiet offbeat nature day trip.', '4-6 hours (full day)', 'October to March', 'Book a forest-department guide at the gate; carry water and sturdy shoes - this is walking-only forest.', 'Not required for day visits; forest rest houses bookable via Gujarat Forest Department', 'Gujarat', 0, 0, NULL, NULL, 'Rs 50 (Indian) / Rs 100 (foreign)', 3.8, 4.2, 22.3656, 73.6289, 'Jambughoda, Panchmahal district, Gujarat 389390, India', NULL, 0.792);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (332000066, 332000066, '6:00 AM - 7:00 PM', '6:00 AM - 7:00 PM', '6:00 AM - 7:00 PM', '6:00 AM - 7:00 PM', '6:00 AM - 7:00 PM', '6:00 AM - 7:00 PM', '6:00 AM - 7:00 PM', '6:00 AM-7:00 PM per travel references. Coordinate is the sanctuary''s approximate centre per Wikipedia - treat as approximate within the forest area.');

