INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 332000066, 'insert', 'bulk', 'Confirmed real: Wikipedia Jambughoda Wildlife Sanctuary (fee Rs 50/100, coordinates 22.3656, 73.6289). No jeep safari - guided nature walks only. No official visitor website found.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000067, 332003, 'Hathni Mata Waterfall', 'Hathni Mata Waterfall', 'Hathni Mata Waterfall, about 75-80 km from Vadodara near Shivrajpur, is a seasonal monsoon cascade plunging into a rocky valley in the Jambughoda hills. It draws weekend crowds July-October for the falls, the small Hathni Mata shrine and roadside corn-and-chai stalls; outside the monsoon the stream runs dry.', '2-3 hours', 'July to October (monsoon only)', 'Go on a weekday to dodge weekend crowds; wear grippy footwear - the rocks are slippery, and avoid the edge during heavy flow.', 'Not required', 'Gujarat', 0, 0, NULL, NULL, 'Free (parking Rs 50 for cars)', 3.8, 4.3, 22.4589, 73.6528, 'Near Shivrajpur, Panchmahal district, Gujarat 389390, India', NULL, 0.8);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (332000067, 332000067, '6:00 AM - 6:00 PM', '6:00 AM - 6:00 PM', '6:00 AM - 6:00 PM', '6:00 AM - 6:00 PM', '6:00 AM - 6:00 PM', '6:00 AM - 6:00 PM', '6:00 AM - 6:00 PM', '6 AM-6 PM daylight hours; monsoon-only attraction (July-October). No official website found.');

