INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 332000067, 'insert', 'bulk', 'Confirmed real: coordinates from tripoto.com (22.4589, 73.6528); free entry with Rs 50 car parking; monsoon-only season. No official website found.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000068, 332003, 'Dabhoi Fort (Hira Gate)', 'Dabhoi Fort (Hira Gate)', 'Dabhoi Fort, about 35 km southeast of Vadodara, is one of the rare surviving examples of Hindu military architecture, its fortification ascribed to the Chaulukya (Solanki) king Jayasimha Siddharaja (1093-1143). The star attraction is Hira Gate (Hira Bhagol), the exquisitely carved eastern gateway named after its architect Hiradhar, flanked by the Vadodara, Champaner and Nandod gates; the town was also the birthplace of poet Dayaram.', '1.5-2 hours', 'October to March', 'Visit Hira Gate in morning light for the carvings; it is an open town monument, so pair it with the old Jain/Hindu temples in Dabhoi town.', 'Not required', 'Gujarat', 0, 0, NULL, NULL, 'Free', 4.0, 4.3, 22.133389, 73.426619, 'Hira Bhagol, Dabhoi, Vadodara district, Gujarat 391110, India', NULL, 0.824);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (332000068, 332000068, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Open historical monument; best visited during daylight hours. Justdial lists 9 AM-5 PM and Meta listings 8 AM-8 PM, but airial.travel states no ticket and daylight access only - hours left unpublished rather than asserted.');

