INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000069, 332003, 'Kalika Mata Temple and Pavagadh Ropeway', 'Kalika Mata Temple and Pavagadh Ropeway', 'The Kalika Mata Temple crowns Pavagadh Hill at 827-832 m, about 50 km from Vadodara - a 10th-11th-century Shakti Peetha where the goddess is worshipped as a painted red head (mukhwato) flanked by Kali and Bahucharamata, originally a Jain shrine. Most pilgrims ride the ropeway from the Maachi plateau to the summit, then climb 200-300 steps to the sanctum; the full climb on foot is some 2,000 steps.', '4-5 hours (half day with Champaner)', 'October to March', 'Ride the ropeway up and walk down (or vice versa); Navratri draws huge crowds, so expect long ropeway queues then.', 'Not required; ropeway tickets at the counter', 'Gujarat', 0, 0, NULL, NULL, 'Ropeway ~Rs 150 (adult) / ~Rs 80 (child); temple entry free', 4.8, 4.5, 22.46111, 73.51167, 'Pavagadh Hill, Panchmahal district, Gujarat 389360, India', NULL, 0.936);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (332000069, 332000069, '5:00 AM - 7:00 PM', '5:00 AM - 7:00 PM', '5:00 AM - 7:00 PM', '5:00 AM - 7:00 PM', '5:00 AM - 7:00 PM', '5:00 AM - 7:00 PM', '5:00 AM - 7:00 PM', 'Temple darshan 5 AM-7 PM per templedarshantime.com; ropeway roughly 7 AM-6 PM. A vimarsana listing gives 8:30 AM-10 PM - hours should be confirmed before visiting. No official website found.');

