INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000070, 332003, 'Khanderao Market', 'Khanderao Market', 'Khanderao Market is Vadodara''s palatial 1906-07 Indo-Saracenic market hall on Palace Road, designed by Robert Chisholm as a gift marking Sayajirao Gaekwad III''s silver jubilee. Today it houses Vadodara Municipal Corporation offices upstairs and a bustling vegetable-and-flower market on the ground floor - a landmark heritage building that doubles as a working market.', '30-45 minutes', 'October to March', 'Walk the Palace Road stretch in the morning to see the facade in good light and browse the flower sellers below.', 'Not required', 'Gujarat', 0, 0, NULL, NULL, 'Free', 3.5, 3.8, 22.296525, 73.201351, 'Palace Rd, Khanderao Market, Vadodara, Gujarat 390001, India', NULL, 0.724);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (332000070, 332000070, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Heritage market building with VMC offices and veg/flower market; no published visitor hours for the landmark itself, so hours are left unpublished. A location listing gives the market office 4 AM-7:30 PM.');

