INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000071, 332003, 'Mandvi Gate', 'Mandvi Gate', 'Mandvi Gate is the historic north gate of Vadodara''s old royal enclosure, a square stone pavilion with three bold arched openings on each of its four sides, built by Sultan Muzaffar between 1511 and 1526, renovated in 1736, with upper storeys added by Ganpatrao in 1856. It stands at the centre of the old city''s four-way junction, surrounded by a busy market.', '20-30 minutes', 'October to March', 'Walk the old-city lanes around Mandvi for the market and street food; the gate is best photographed from a distance at the junction.', 'Not required', 'Gujarat', 0, 0, NULL, NULL, 'Free', 3.5, 3.7, 22.300162, 73.210663, 'Mandvi Cir, Sulemani Pol, Mandvi, Vadodara, Gujarat 390001, India', NULL, 0.716);

