INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000072, 332003, 'Raopura Tower (Maharani Chimnabai Clock Tower)', 'Raopura Tower (Maharani Chimnabai Clock Tower)', 'Raopura Tower, formally the Maharani Chimnabai Clock Tower, is a five-storey 1896 clock tower in the Raopura old-city square with a London-made clock. One of Vadodara''s surviving colonial landmarks, it anchors the busy Raopura junction and is lit up at night.', '15-20 minutes', 'October to March', 'Pair with Tambekar Wada and Mandvi Gate on an old-city walking circuit; evenings show the tower lit.', 'Not required', 'Gujarat', 0, 0, NULL, NULL, 'Free', 3.2, 3.5, 22.303972, 73.20075, 'Raopura, Vadodara, Gujarat 390001, India', NULL, 0.664);

