INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000073, 332003, 'Sasumaa Gujarati Thali', 'Sasumaa Gujarati Thali', 'Sasumaa is one of Vadodara''s best-known unlimited Gujarati thali restaurants, famous for its hot, traditional thalis with changing seasonal shaaks, farsan, kadhi, rotis and sweets served the ''athithi devo bhav'' way. Its celebrity guest wall and decade-long following make it the classic first stop for visitors wanting the definitive Vadodara thali experience.', '1-1.5 hours', 'October to March', 'Arrive right at lunch opening (11:30 AM) to beat the weekend queue; ask for the sweet of the day - it changes.', 'Not required; walk-ins accepted', 'Gujarat', 0, 0, NULL, NULL, 'Rs 225-350 per person (approx)', 4.7, 4.4, 22.310074, 73.175184, '1/2, Gokulesh Complex, R.C. Dutt Road, Alkapuri, Vadodara, Gujarat 390007, India', 'https://sasumaagujaratithali.com', 0.916);

