INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000074, 332003, 'Kansaar Gujarati Thali', 'Kansaar Gujarati Thali', 'Kansaar has served authentic Gujarati thalis near Vadodara station for over 25 years (est. 1991), known for generous unlimited thalis with curries, bajra rotis, dhokla, papdi chaat, two sweets and chaas. It is a neighbourhood institution for locals as well as travellers arriving by train.', '1-1.5 hours', 'October to March', 'It is ~0.5 km from Vadodara railway station - ideal for a thali right after arrival; the lunch crowd is heavy.', 'Not required', 'Gujarat', 0, 0, NULL, NULL, '~Rs 290 per person (approx)', 4.2, 4.1, 22.309221, 73.182838, 'Nautillus Building, 101, Station Rd, opposite Hotel Surya Lane, Sayajigunj, Vadodara, Gujarat 390005, India', NULL, 0.832);

