INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000075, 332003, 'Jay Mahakali Sev Usal', 'Jay Mahakali Sev Usal (Kirti Stambh Wala)', 'Jay Mahakali Sev Usal (the ''Kirti Stambh Wala'') is Vadodara''s most famous sev-usal joint - the spicy white-peas usal topped with crisp sev, green chutney, hot tarri, onions, lemon and buns that locals call the city''s signature dish. The humble fast-food outlet near Kirti Stambh now runs multiple branches (Kirtistambh, Subhanpura, Waghodiya Road, Diwalipura) and even sells ready-to-cook sev-usal packs.', '30-45 minutes', 'October to March', 'Order butter or cheese sev-usal and follow it with a glass of chaas; mid-afternoon avoids the lunch rush.', 'Not required', 'Gujarat', 0, 0, NULL, NULL, '~Rs 100-150 per person (approx, street food)', 4.6, 4.5, 22.295686, 73.198219, 'GF 14/15, Prathamesh Plazza, B/H Neharu Bhavan, Kirti Stambh, Palace Rd, Vadodara, Gujarat 390001, India', 'https://jaymahakalisevusal.in/', 0.912);

