INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000076, 332003, 'Mandap - The Authentic Gujarati Thali Restaurant', 'Mandap (Hotel Express Towers)', 'Mandap, inside Hotel Express Towers on R.C. Dutt Road, has served ''homespun'' Gujarati thalis since 1974 and won the Times Food Award for Best Gujarati Restaurant (2008). The bronze-plate (kasa ni thali) lunch and dinner serve farsan, three vegetables, kathol, thepla-poori-phulka, tuvar dal, kadhi, khichdi and a sweet of the day, with festival specials like fafda-jalebi on Sundays and matla undhiyu at Uttarayan.', '1-1.5 hours', 'October to March', 'Sunday lunch brings fafda and jalebi; reservations help at dinner on weekends.', 'Recommended on weekends; reservations via hotel', 'Gujarat', 0, 0, NULL, NULL, '~Rs 300-500 for two (approx)', 4.4, 4.2, 22.310244, 73.169186, 'Hotel Express Towers, R.C. Dutt Road, Alkapuri, Vadodara, Gujarat 390007, India', 'https://expresshotelsindia.com/express-towers-vadodara/restaurants/mandap/', 0.864);

