INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000077, 332003, 'Bayleaf Multi Cuisine Restaurant', 'Bayleaf Multi Cuisine Restaurant (Hotel Express Residency)', 'Bayleaf, the multi-cuisine restaurant at Hotel Express Residency in Alkapuri (est. 1986), serves North Indian, Chinese, Italian and continental fare on a leafy lawn-side dining floor - Vadodara''s go-to hotel restaurant for family celebrations and business dinners. Known for paneer specialities, rogan josh, kaju masala and candlelight cabanas overlooking the green lawns.', '1-2 hours', 'October to March', 'Ask for lawn-side seating in the evening; service can be slow at peak hours.', 'Recommended for weekends; reservations via hotel', 'Gujarat', 0, 0, NULL, NULL, '~Rs 1,050 for two (approx)', 4.0, 4.1, 22.312283, 73.172039, 'Hotel Express Residency, 18/19, Dr Rustom Cama Marg, Alkapuri, Vadodara, Gujarat 390007, India', NULL, 0.808);

