INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000078, 332003, 'Sankalp Restaurant', 'Sankalp Restaurant (Race Course)', 'Sankalp''s Race Course branch is Vadodara''s long-running South Indian fine-dine spot (21+ years), known for crisp Mysore masala dosas, jaali dosas, cheese utthapams and filter coffee in a family dining room. Part of the 150+ outlet Sankalp group, it is the default South Indian dinner for Alkapuri and Race Course residents.', '1-1.5 hours', 'October to March', 'Go for lunch for the best thali deals; weekends get busy so reserve ahead.', 'Not required; reservations recommended on weekends', 'Gujarat', 0, 0, NULL, NULL, '~Rs 600-1,200 for two (approx)', 4.0, 4.2, 22.311611, 73.164636, '101/102, 1st Floor, Spenta Complex, Race Course Rd, opp. Axis Bank, Vadiwadi, Vadodara, Gujarat 390007, India', NULL, 0.816);

