INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000079, 332004, 'Watson Museum', 'Watson Museum', 'Founded in 1888 and named after Colonel John Watson, this is one of Gujarat''s oldest museums, housed in the Queen Victoria Memorial Institute building inside Jubilee Garden. Its collection includes 13th-century artifacts, Indus Valley objects, a rare 3rd-century inscribed tablet, paintings, textiles, coins and woodwork, plus the famous copy of the Shah Jahan begum''s portrait. It is Rajkot''s principal museum stop and pairs naturally with a Jubilee Garden visit.', '1-2 hours', 'October-February; daytime', 'Closed on Wednesdays — plan around it; photography rules vary by gallery, ask at the counter.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Rs 5', 5, 4, 22.300431, 70.801866, 'Jawahar Road, Opp BSNL Office, Jubilee Garden, Rajkot 360001', NULL, 0.92);

