INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000080, 332004, 'Rotary Midtown Dolls Museum', 'Rotary Midtown Dolls Museum', 'A museum holding some 1,400-1,600 dolls from over 100 countries, established on 24 December 2004 by the Rotary Club of Rajkot Midtown. The collection includes folk-costume dolls from around the world and is a rare doll museum in India. It is a compact, kid-friendly stop near Rajkot Junction.', '1 hour', 'October-February; daytime', 'Combine with a visit to the nearby Ramakrishna Ashram on Dr Yagnik Road; closed on Mondays.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Rs 25-40', 4, 4, 22.2965, 70.7965, '2nd Floor, Nagrik Bank Bhavan, Dr Yagnik Road, Opp Heera Panna Complex, Rajkot 360001', NULL, 0.8);

