INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000081, 332004, 'Mahatma Gandhi Museum', 'Mahatma Gandhi Museum', 'The former Alfred High School where Mahatma Gandhi studied and passed his matriculation in 1887, converted into a museum opened on 30 September 2018. It has 39 interactive galleries tracing Gandhi''s life, from his Rajkot childhood to the freedom movement, with a light and sound show included. It is Rajkot''s flagship Gandhi institution.', '2-3 hours', 'October-February; daytime', 'Allow at least 2 hours for the 39 galleries; the light and sound show runs in the evening.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Rs 25', 5, 5, 22.2969, 70.7976, 'Alfred High School Road, Rajkot 360001', NULL, 1.0);

