INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000082, 332004, 'Kaba Gandhi No Delo', 'Kaba Gandhi No Delo', 'The childhood home where Mahatma Gandhi lived from about age six for roughly 11 years, now converted into the Gandhi Smriti museum. It preserves rooms and memorabilia from the Gandhi family''s Rajkot years, including photographs and personal effects. Entry is free or a token amount, making it an easy add-on to the Alfred High School museum.', '30-60 minutes', 'October-February; daytime', 'Pair with the Mahatma Gandhi Museum nearby; call ahead to confirm opening hours as listings disagree.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 4, 4, 22.298, 70.802, 'Ghee Kanta (Gheekantha) Road, Rajkot 360001', NULL, 0.8);

