INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000083, 332004, 'Race Course', 'Race Course', 'Rajkot''s large central public ground, a former racecourse turned into the city''s main open space for morning walks, jogging, exhibitions and community events. It hosts the annual Janmashtami Lok Mela, Saurashtra''s biggest fair. It is more a locals'' recreation space than a tourist sight, but the evening atmosphere is lively.', '30-60 minutes', 'October-March; early morning or evening', 'Go early morning to see the city''s walkers and joggers; check if the Janmashtami Lok Mela is on during your visit.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 2, 3, 22.3062, 70.79, 'Race Course Road, Sadar, Rajkot 360001', NULL, 0.48);

