INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000084, 332004, 'Jubilee Garden', 'Jubilee Garden', 'A colonial-era public garden adjoining the Race Course, with heritage structures including the Watson Museum and Lang Library in its heritage zone. It is a free, shady city-centre park popular for evening strolls. Combine it with the Watson Museum, which sits inside the garden.', '1 hour', 'October-February; late afternoon or evening', 'Visit the Watson Museum inside the garden, then walk to the nearby Grand Thakar for a Gujarati thali lunch.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 3, 3, 22.2995, 70.8015, 'Jawahar Road, Rajkot 360001', NULL, 0.6);

