INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000085, 332004, 'Shri O. V. Sheth Regional Community Science Centre and Planetarium', 'Community Science Centre and Planetarium', 'The Shri O. V. Sheth Regional Community Science Center, established by the Saurashtra Education Foundation and Rajkot Municipal Corporation and working in science popularization since 1997 (national award 2008). It includes interactive science exhibits, a planetarium and children''s activities at Nehru Udyan on the Race Course Ring Road. A solid family stop, especially for school-age children.', '2-3 hours', 'October-February; daytime', 'Check the official site for planetarium show timings; combine with an Aji Dam Garden evening.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 4, 4, 22.299416, 70.790118, 'Nehru Udyan, Race Course Ring Road, Rajkot 360005', 'https://sciencecenterrajkot.org/', 0.8);

