INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000086, 332004, 'Aji Dam Garden', 'Aji Dam Garden', 'An earthen dam built in 1952-54 (2,426 m long), the lifeline of Rajkot''s water supply, with an RMC-maintained garden on its banks. The garden has a walkway atop the dam, an amusement park, food courts and seasonal boating; migratory birds visit in winter. It is Rajkot''s most popular evening picnic spot and sunset viewpoint.', '2-3 hours', 'October-February; late afternoon for the sunset', 'Arrive by 5 PM to walk the dam top before sunset; food courts on site, boating is seasonal.', NULL, 'Gujarat', 0, 1, NULL, '18:15', 'Free', 4, 4, 22.2707, 70.8361, 'Aji Dam, near Bhakti Nagar, Rajkot (about 8 km from Rajkot Junction)', NULL, 0.8);

