INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000087, 332004, 'Nyari Dam', 'Nyari Dam', 'A dam and reservoir about 5-10 km from Rajkot on Nyari Dam Road, a popular local picnic and sunset spot. Winter brings birdwatching (Sykes''s Lark, Baya Weaver, migratory ducks) to the reservoir edges. It is an open-access natural area with no ticketed entry — best as a relaxed daylight outing.', '2-3 hours', 'October-February; sunset for the light', 'Bring binoculars in winter for waterbirds; it is a sunset spot, so plan to leave by dusk.', NULL, 'Gujarat', 0, 1, NULL, '18:15', 'Free', 3, 4, 22.2597, 70.7417, 'Nyari Dam Road, Rajkot 360005', NULL, 0.68);

