INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000088, 332004, 'Lal Pari Lake', 'Lal Pari Lake', 'A lake about 5 km from Rajkot, an exotic natural spot and one of the city''s major birdwatching venues, hosting black-tailed godwit, rosy pastor, pelican, spoonbill and large roosts of migratory birds. It sits adjacent to Pradyuman Park and Randarda Lake. Best visited at dawn when the birds are most active.', '1-2 hours', 'October-February; dawn for birdwatching', 'Go at sunrise with binoculars; combine with the Pradyuman Zoo next door.', NULL, 'Gujarat', 1, 0, '06:35', NULL, 'Free', 3, 4, 22.3, 70.845, 'Near Pradyuman Park / Marketing Yard, Rajkot 360002', NULL, 0.68);

