INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000089, 332004, 'Pradyuman Zoological Park', 'Pradyuman Zoological Park', 'Rajkot''s zoo, spread over 137 acres near Lal Pari Lake; established in 1992 near Aji Dam and relocated to its present site in 2010. It houses Gir lions, tigers, leopards and a reptile house, and the lake area attracts migratory birds from October to February. It is the main family wildlife outing in Rajkot.', '3-4 hours', 'October-February; morning', 'Closed on Fridays; mornings are best for active animals — the Gir lions are the headline exhibit.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Rs 20', 4, 4, 22.299198, 70.839575, 'Near Lal Pari Lake, Marketing Yard Road, Rajkot 360002', NULL, 0.8);

