INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000090, 332004, 'Shri Ramakrishna Ashram', 'Shri Ramakrishna Ashram', 'The Ramakrishna Mission ashram in Rajkot, founded on 5 March 1927 and on its present Dr Yagnik Road site since 5 October 1935 (land granted by the Thakore Saheb of Rajkot). Its temple, inaugurated in 1979 and resembling Belur Math, has a library, bookstore, medical centre and a Vivekananda museum. A serene stop for temple architecture and the mission''s social work.', '1-2 hours', 'October-February; morning or evening aarti', 'Respect the midday temple closure (12-4 PM); the bookstall sells authentic mission literature.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 3, 4, 22.299, 70.795, 'Dr Yagnik Road, Rajkot 360001', 'http://www.rkmrajkot.org/', 0.68);

