INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000091, 332004, 'BAPS Shri Swaminarayan Mandir', 'BAPS Shri Swaminarayan Mandir', 'The BAPS Shri Swaminarayan Mandir on Kalavad Road, whose construction was decided by Yogiji Maharaj and which was completed in 1998. The main deities are Laxminarayan Dev, HariKrishna Maharaj and Ghanshyam Maharaj. It is a major devotional centre with large Diwali and Annakut celebrations.', '1-2 hours', 'October-February; morning or evening darshan', 'Time your visit for the Annakut festival after Diwali for the grand food-mountain offering.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 4, 4, 22.28, 70.7885, 'Kalavad Road, near Mota Mava, Rajkot', NULL, 0.8);

