INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000093, 332004, 'Ishwariya Park (Shri Ishwariya Mahadev)', 'Ishwariya Park', 'A 77-acre RMC garden inaugurated in 2008, on the Rajkot-Jamnagar Highway at Madhapar village, with a lake, musical fountain, golf course and jogging tracks. The adjacent Ishwariya Mahadev temple houses a Swayambhu (self-manifested) Shiva linga and draws devotees alongside picnickers. A pleasant half-day outing combining garden and temple.', '2-3 hours', 'October-February; late afternoon', 'Visit the Swayambhu Shiva temple inside the complex; boating on the lake is reported closed — check locally.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Rs 20', 3, 3, 22.317, 70.755, 'Madhapar, Rajkot-Jamnagar Highway, Rajkot (about 7 km from Rajkot Junction)', NULL, 0.6);

