INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000094, 332004, 'Funworld', 'Funworld', 'A compact (~5 acre) amusement park on the Race Course Ring Road, Rajkot''s main family funfair-style attraction. Rides include a Sky Train roller coaster, Hara Kiri, Tora Tora, a water merry-go-round and a 4D theatre, with individual rides Rs 10-30 and combo tickets around Rs 200 for 10-12 rides. Evening-oriented and popular with local families.', '2-3 hours', 'October-March; evenings', 'Buy the combo ticket if you plan multiple rides; go after 5 PM when it is livelier and cooler.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Rs 10-34', 2, 3, 22.307, 70.791, 'Race Course Ring Road, Opp Bahumali Building, Sadar, Rajkot 360001', NULL, 0.48);

