INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000095, 332004, 'Shree Khodaldham Temple, Kagvad', 'Shree Khodaldham Temple, Kagvad', 'The grand temple of Maa Khodiyar at Kagvad, inaugurated in January 2017, built in Mahameru Prasad Maru-Gurjara style (289 ft x 253 ft x 159 ft) with around 650 statues. It is about 60-65 km from Rajkot on the Rajkot-Jetpur highway, 14 km from Jetpur, and one of Saurashtra''s biggest modern pilgrimage complexes. Free entry; allow a half day with travel.', 'Half day (2-3 hours at site, ~63 km day trip)', 'October-February; morning', 'It is a ~1.5 hour drive from Rajkot — start early and combine with the Jalaram Mandir at Virpur nearby.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 5, 5, 21.791209, 70.687588, 'Kagvad, Rajkot district, Gujarat (on the Rajkot-Jetpur highway, about 63 km from Rajkot)', 'https://www.khodaldhamtrust.org/', 1.0);

