INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 332000095, 'insert', 'bulk', 'Confirmed real and documented: official trust site khodaldhamtrust.org (fetched live 2026-09-30) is the genuine Shree Khodal Dham Trust site; Wikipedia documents the Maa Khodiyar temple inaugurated Jan 2017, Maru-Gurjara style dimensions, ~650 statues, 14 km from Jetpur, ~63 km from Rajkot; coordinates from the trust site''s embedded map (21.791209, 70.687588). DAY TRIP: ~63 km from Rajkot.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000096, 332004, 'Khambhalida Buddhist Caves', 'Khambhalida Buddhist Caves', 'Three rock-cut limestone Buddhist caves from the 4th century AD, near Gondal in Rajkot district, discovered in 1958 by archaeologist P. P. Pandya and maintained by the Archaeology Department of Gujarat. The central chaitya cave has a worn stupa with Bodhisattva and Vajrapani sentinel statues flanking the doorway. A quiet, offbeat day trip for history lovers, free to enter.', '1-2 hours at site, ~70 km day trip', 'October-February; morning', 'Combine with Gondal''s palaces (Naulakha Palace) on the same day; carry water — facilities are minimal.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 4, 4, 21.87, 70.73, 'Near Khambhalida village, Gondal taluka, Rajkot district (about 70 km from Rajkot)', NULL, 0.8);

