INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000097, 332004, 'Naulakha Palace, Gondal', 'Naulakha Palace, Gondal', 'A riverside palace in Gondal, about 40 km from Rajkot, some 260 years old and developed for Maharaja Bhagwat Sinhji''s silver jubilee. It houses eclectic museums of royal artefacts, horse-drawn carriages, vintage cars (including a 1910 New Engine and 1940s American cars), toys and teapots, plus a library holding the first Gujarati dictionary. One of Saurashtra''s best palace museums.', '2-3 hours at site, ~40 km day trip', 'October-February; daytime', 'Don''t skip the vintage-car and carriage museums inside; plan around the midday lunch break.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Rs 60-300', 4, 4, 21.9622, 70.8006, 'Gondal, Rajkot district, Gujarat (about 40 km from Rajkot, on the Gondali river)', NULL, 0.8);

