INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 332000097, 'insert', 'bulk', 'Confirmed real and documented: visitor guides document Naulakha Palace in Gondal (~40 km from Rajkot) on the Gondali river, royal artefacts/carriage/vintage-car/toy museums and the library with the first Gujarati dictionary; 9 AM-6 PM, closed Sundays, lunch break. Coordinates approximate to Gondal town. DAY TRIP: ~40 km from Rajkot.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000098, 332004, 'Shree Jalaram Mandir, Virpur', 'Shree Jalaram Mandir, Virpur', 'The temple at the residence and samadhi of saint Jalaram Bapa (born 1799) in Virpur village, about 55 km from Rajkot near Jetpur. Uniquely, the temple accepts no donations of any kind (since 2000) and serves free khichdi-kadhi prasad to all visitors (10 AM-2 PM and 6-9 PM). It is one of Gujarat''s most beloved pilgrimage stops and pairs well with Khodaldham at nearby Kagvad.', '1-2 hours at site, ~55 km day trip', 'October-February; morning', 'Time your visit for the free khichdi-kadhi prasad (10 AM-2 PM / 6-9 PM); do not offer donations — the temple refuses them.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 4, 4, 21.8233, 70.7128, 'Virpur, Rajkot district, Gujarat (about 55 km from Rajkot, near Jetpur)', NULL, 0.8);

