INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000099, 332004, 'The Grand Thakar', 'The Grand Thakar', 'Rajkot''s most famous Gujarati thali restaurant, a tradition since 1965, in the c/o The Grand Thakar Hotel on Jawahar Road opposite Jubilee Garden. It serves an unlimited Gujarati thali — puran poli, basundi, dals, sabjis and farsan — alongside multi-cuisine vegetarian dishes. A landmark family restaurant; the 80 Feet Road branch serves the same chain menu.', '1-1.5 hours', 'Lunch or dinner; avoid peak weekend dinner rush', 'Order the unlimited Gujarati thali — the signature; weekends fill up, so arrive before 1 PM for lunch.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Rs 750', 5, 4, 22.301786, 70.801176, 'Jawahar Road, Opp Jubilee Garden, Rajkot 360001', NULL, 0.92);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (332000099, 332000099, '11:30-15:30, 19:00-23:00', '11:30-15:30, 19:00-23:00', '11:30-15:30, 19:00-23:00', '11:30-15:30, 19:00-23:00', '11:30-15:30, 19:00-23:00', '11:30-15:30, 19:00-23:00', '11:30-15:30, 19:00-23:00', 'Split lunch/dinner shifts per TripAdvisor listing (11:30 AM-3:30 PM, 7-11 PM); the 80 Feet Road branch reports 11 AM-11 PM; about Rs 750 for two; pure veg');

