INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000100, 332004, 'Adingo Restaurant', 'Adingo Restaurant', 'A long-standing (26+ years) pure-vegetarian multi-cuisine restaurant at Limda Chowk, known for Chinese, Punjabi, Gujarati, North Indian and Kathiyawadi dishes. Signature items include Gujarati thali, undhiyu, grilled paneer and khichdi. It is a reliable all-day family dining option in the city centre.', '1-1.5 hours', 'Lunch or dinner', 'Good one-stop veg family restaurant near the station; the Gujarati thali and undhiyu are the local favourites.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Rs 750', 4, 4, 22.2964, 70.7992, 'Ground Floor, Toran Apartment, Opp Shashtri Medan, Limda Chowk, Rajkot 360001', NULL, 0.8);

