INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000101, 332004, 'Gir Gamthi Kathiyawadi Zayka', 'Gir Gamthi Kathiyawadi Zayka', 'A popular evening-only Kathiyawadi restaurant on the 150 Feet Ring Road near Munjka, serving authentic Saurashtra-style food — bajra rotla, ringan no olo, sev-tameta, lasaniya bateta and buttermilk. Pure vegetarian, budget-friendly (below Rs 500 price range), with thousands of directory ratings. It opens only for dinner, so plan accordingly.', '1-1.5 hours', 'Dinner (opens 7 PM)', 'Dinner-only (7-11 PM) — go hungry for the full Kathiyawadi spread with rotla and olo.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 4, 4, 22.28317, 70.737958, 'Near Kalawad Road, Munjka, 150 Feet Ring Road, Rajkot', NULL, 0.8);

