INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000102, 332004, 'Sankalp Restaurant', 'Sankalp Restaurant', 'Rajkot''s branch of the well-known Sankalp Group (150+ restaurants, founded by Dr Kailash Goenka, first flagship in Ahmedabad), serving authentic South Indian food — masala dosa, podi idli, uttapam, vada — plus North Indian and Chinese. A clean, family-oriented vegetarian restaurant on Race Course Road with takeaway service.', '45-90 minutes', 'Lunch or dinner', 'Try the masala dosa with coconut chutney; off-peak hours are quieter for families.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Rs 650', 4, 4, 22.298125, 70.790202, 'Near Jilla Panchayat Chowk, Race Course Road, Rajkot 360001', NULL, 0.8);

