INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000103, 332004, 'Pandya''z Rasthal', 'Pandya''z Rasthal', 'A Gujarati/Kathiyawadi restaurant on the 150 Feet Ring Road near Raiya Circle, serving Saurashtra-style thalis in a family setting. Open 11 AM-10 PM daily with a mid-range price of about Rs 580 for two. A dependable Kathiyawadi lunch option on the city''s western ring road.', '1 hour', 'Lunch or dinner', 'Order the Kathiyawadi thali with bajra rotla; handy lunch stop if you are touring the western ring road.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Rs 580', 3, 4, 22.29954, 70.768975, '3 & 4 West Gate Complex, Nagrik Sahakari Bank, 150 Feet Ring Rd, near Raiya Circle, Rajkot', NULL, 0.68);

