INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000104, 332004, 'Non Stop Kathiyawadi', 'Non Stop Kathiyawadi', 'A Kathiyawadi restaurant on Kalawad Road (Raiya Road area) with rooftop seating, open long hours from 7:30 AM to 11 PM. It serves Saurashtra-style Kathiyawadi food at a budget price of about Rs 550 for two and is pure vegetarian. A local-favourite spot for an authentic Kathiyawadi breakfast or dinner.', '1 hour', 'Breakfast or dinner', 'Ask for the rooftop tables at dinner; good early-breakfast option since it opens at 7:30 AM.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Rs 550', 3, 4, 22.278, 70.772, 'Near Tea Post, Kalawad Road, Raiya Road, Rajkot', NULL, 0.68);

