INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3320014, 332, 332004, 'Janmashtami Lok Mela', 'August-September', 'Saurashtra''s biggest annual fair, held on the Race Course Ground during the Krishna Janmashtami (Satam-Aathma) period. The 2026 edition ran 2-6 September as ''Virasatthi Vikas Lok Mela 2026'' with daily cultural programmes in the late afternoon and evening.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3320015, 332, 332004, 'Navratri', 'September-October', 'The nine-night festival of the Goddess celebrated with garba and dandiya-raas dancing at venues across Rajkot; one of Gujarat''s most famous festivals and a major draw for visitors.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3320016, 332, 332004, 'Diwali and Annakut', 'October-November', 'The Diwali festival of lights is celebrated across the city, with the Annakut (Govardhan Puja) mountain-of-food offering at the BAPS Shri Swaminarayan Mandir as a major devotional attraction.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3320017, 332, 332004, 'Makar Sankranti (Uttarayan)', 'January', 'Gujarat''s kite festival on Makar Sankranti; the skies over Rajkot fill with kites and rooftops host traditional kite-flying with undhiyu and jalebi.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3320018, 332, 332004, 'Holi', 'March', 'The spring festival of colours celebrated in Rajkot with gulal and traditional festivities.');

-- city: Gandhinagar (id 1055)
INSERT OR IGNORE INTO cities (id, state_id, city_name, latitude, longitude) VALUES (332005, 332, 'Gandhinagar', 23.2235, 72.65);

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000105, 332005, 'Swaminarayan Akshardham Temple', 'Swaminarayan Akshardham Temple', 'Gandhinagar''s crown jewel: a BAPS Swaminarayan temple complex inaugurated on 30 October 1992, built from pink sandstone with more than 200 carved murtis. Beyond the main mandir there are the Sahajanand Van gardens, three exhibition halls (Hall of Values, a giant-screen film and a cultural boat ride) and the Sat-Chit-Anand musical fountain and water show held after sunset. Mobile phones and cameras are not allowed inside; modest dress is required.', '4-5 hours', 'October to March; arrive late afternoon and stay for the sunset water show', 'Deposit phones and cameras in the free cloakroom before entering; exhibition tickets cost extra (about Rs 60 adult / Rs 40 child); closed on Mondays.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 5, 5, 23.229414, 72.67402, 'J Road, Sector 20, Gandhinagar, Gujarat 382021', 'https://akshardham.com/gujarat', 1.0);

