INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000106, 332005, 'Dandi Kutir', 'Dandi Kutir', 'The world''s largest museum dedicated to one person''s life - Mahatma Gandhi - housed in a giant salt-mound-shaped building inside the Mahatma Mandir complex. Uses 3D holography, projection mapping and a 360-degree theatre to walk visitors through the Dandi March and Gandhi''s life; run by the Government of Gujarat.', '1.5-2 hours', 'October to February; weekday mornings', 'Tours run in batches of about 50 every 30 minutes; no photography inside; allow 1.5-2 hours.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Rs 10', 4, 4, 23.232797, 72.631413, 'Salt Mount Road, Sector 13C, Gandhinagar, Gujarat 382016', 'http://dandi-kutir.com/', 0.8);

