INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000107, 332005, 'Indroda Dinosaur and Fossil Park', 'Indroda Dinosaur and Fossil Park', 'India''s only dinosaur museum and fossil park, spread over roughly 400 hectares and run by the GEER Foundation. Displays fossils and petrified eggs excavated at Raiyoli (one of the world''s largest dinosaur excavation sites and second-largest hatchery), plus life-size dinosaur replicas, a zoo, botanical garden, cactus garden and wilderness trails.', '2-3 hours', 'October to March; mornings', 'Carry drinking water - no food stalls inside and outside snacks are not allowed; wear walking shoes for the long trails.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Rs 30', 5, 4, 23.192, 72.648, 'Indroda Nature Park, Gandhinagar, Gujarat 382007', NULL, 0.92);

