INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000108, 332005, 'Sarita Udhyan', 'Sarita Udhyan', 'A 30-acre riverside garden on the banks of the Sabarmati in Sector 9, among Gandhinagar''s favourite picnic spots. Offers boating, a children''s toy train, a botanical garden, butterfly park, deer park and long jogging paths through dense greenery.', '2 hours', 'October to March; early mornings for birdwatching', 'Come early morning for the best bird activity; boating and the toy train are the main draws.', NULL, 'Gujarat', 0, 1, NULL, '18:00', 'Free', 4, 4, 23.203207, 72.6589, 'Near Sabarmati River, Indroda, Sector 9, Gandhinagar, Gujarat 382007', NULL, 0.8);

