INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000113, 332005, 'Sant Sarovar Dam', 'Sant Sarovar Dam', 'A dam on the Sabarmati at Indroda, behind Sarita Udhyan, popular with locals for its sunset views and monsoon overflow. The dam site itself is a restricted/prohibited area and the main gate is often closed, so treat it as a scenic stop rather than a full outing; entry is free.', '1 hour', 'Monsoon (June-September); evenings for sunset', 'Go in the monsoon when the dam overflows; carry your own water and snacks - there are no stalls.', NULL, 'Gujarat', 0, 1, NULL, '18:00', 'Free', 3, 3, 23.199312, 72.663271, 'Sant Sarovar Road, Indroda, Gandhinagar, Gujarat 382421', NULL, 0.6);

