INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000114, 332005, 'Shree Swaminarayan Temple, Sector 23', 'Shree Swaminarayan Temple, Sector 23', 'A prominent Swaminarayan temple of the Narnarayan Dev (Kalupur) tradition, founded on 18 February 1976 and opened on 30 April 1979. The complex also houses the Kashtbhanjan Hanumanji shrine and is known for its disciplined, clean premises and regular katha and satsang programmes.', '1 hour', 'Year-round; Saturday mornings for Hanumanji prayers', 'Visit on a Saturday morning for the Hanumanji prayers; dress modestly.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 4, 4, 23.24036, 72.64787, 'Mandir Chowk, Sector 23, Gandhinagar, Gujarat 382024', 'https://www.hkshastri.org/', 0.8);

