INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000119, 332005, 'Adalaj Stepwell (day trip)', 'Adalaj Stepwell', 'A five-storey stepwell (vav) built in 1498-1499 in memory of Rana Veer Singh of the Vaghela dynasty and completed for Queen Rudabai. Famous for its Indo-Islamic fusion carvings - elephants, leaves, geometric patterns - and its cool lower chambers; an ASI-protected monument and the classic half-day trip from Gandhinagar.', '1-2 hours', 'October to March; mornings for the best light on the carvings', 'The lower levels stay cool even in summer; combine with Trimandir Adalaj nearby.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 5, 5, 23.16691, 72.58024, 'Adalaj, Gandhinagar district, Gujarat 382421 (about 15 km from Gandhinagar)', NULL, 1.0);

