INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000120, 332005, 'Trimandir, Adalaj (day trip)', 'Trimandir, Adalaj', 'A non-sectarian temple inspired by Dada Bhagwan, opened 29 December 2002. The two-storey pink-sandstone complex houses Simandhar Swami alongside shrines to Shiva, Krishna, Amba, Hanuman and others; entry is free, with morning aarti at 7 AM and evening aarti at 6:45 PM.', '1-2 hours', 'Year-round; mornings or evenings for aarti', 'Dress modestly and remove shoes; combine with Adalaj Stepwell, a few minutes away.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 4, 4, 23.1783, 72.572, 'Adalaj, Gandhinagar district, Gujarat 382421 (about 10 km from Gandhinagar)', 'https://trimandir.org/', 0.8);

