INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000123, 332005, 'Sabarmati Ashram (day trip)', 'Sabarmati Ashram', 'Gandhi''s home from 1917 to 1930 and the starting point of the Dandi March. The riverside ashram preserves Hriday Kunj (his cottage), the Upasana Mandir prayer ground and a museum of letters, photographs and personal effects.', '2 hours', 'October to March; late afternoons for the riverbank', 'Walk the riverside path at sunset after the museum; photography rules vary by section.', NULL, 'Gujarat', 0, 1, NULL, '18:00', 'Free', 5, 5, 23.0605, 72.5809, 'Ashram Road, Ahmedabad, Gujarat 380027 (about 25 km from Gandhinagar)', 'https://www.gandhiashramsabarmati.org/', 1.0);

