INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000124, 332005, 'Swapna Srushti Water Park (day trip)', 'Swapna Srushti Water Park', 'A large water park, resort and adventure park spread over about 130 acres on the Gandhinagar-Mahudi highway near Amarnath Dham. Water slides, wave pools, waterfalls and rain dance; part of the Swapna Srushti Resort and Club.', 'Full day', 'October to March; weekdays to avoid crowds', 'Go on a weekday to avoid crowds; carry swimwear - costumes and lockers are rented on site.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 3, 4, 23.373247, 72.723048, 'Amarapur Village, Nr. Amarnath Dham, Gram Bharati Cross Road, Gandhinagar-Mahudi Highway, Gujarat 382735 (about 15 km from Gandhinagar)', NULL, 0.68);

