INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000131, 332006, 'Takhteshwar Temple', 'Takhteshwar Temple', 'A white-marble Shiva temple built in 1893 and named after Maharaja Takhtasinhji, set on a hillock on a high plinth with a tall shikhara that makes it a city landmark. From the top there are panoramic views over Bhavnagar city and the Gulf of Khambhat. It is one of the most-visited temples in Bhavnagar.', '1-2 hours', 'October-February; early morning or evening for the breeze and views', 'Climb to the top for the city panorama; modest dress is expected and the site is most pleasant at sunset.', NULL, 'Gujarat', 0, 1, NULL, '18:15', 'Free', 5, 4, 21.7538, 72.1478, 'Takhteshwar Hill, near Kalanala, Bhavnagar, Gujarat 364001', NULL, 0.92);

