INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000132, 332006, 'Nilambag Palace', 'Nilambag Palace', 'A heritage palace built in 1894 as a royal residence for the Bhavnagar princely state, designed by British architect William Emerson, who also designed the Victoria Memorial in Calcutta. It now operates as a heritage hotel set in a large estate, and non-guests commonly visit for its Mor Bagh restaurant and to see the colonial-era architecture, portraits and courtyards.', '1-2 hours', 'October-February', 'You don''t need to stay here to eat at the Mor Bagh restaurant — it is the easiest way to see the palace interior.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 4, 4, 21.751, 72.1395, 'Nilambaug Circle, Bhavnagar, Gujarat 364002', NULL, 0.8);

