INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000133, 332006, 'Barton Library and Museum', 'Barton Library and Museum', 'A two-storeyed heritage building from 1895 designed for a road junction, built in ashlar stone masonry with Gothic arch windows and a sloping Mangalore-tiled roof. It is one of the oldest libraries in Gujarat and also houses the Barton Museum, which holds Saurashtra folk-art objects, coins, weapons, musical instruments, sculptures and Gandhi memorabilia.', '1-2 hours', 'October-February; weekday daytime', 'Combine with Gandhi Smriti nearby; both are heritage institutions in the old city core.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 3, 3, 21.7715, 72.153, 'Barton Library, central Bhavnagar (near Crescent Circle/Clock Tower), Bhavnagar, Gujarat', NULL, 0.6);

