INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000134, 332006, 'Victoria Park', 'Victoria Park', 'A 500-acre man-made forest set up in 1888 by Maharaja Takhtasinhji, described as one of the oldest man-made forests in India, on the edges of Gaurishankar Lake. It has a walking track, a watch tower overlooking Krishna Kunj Lake, nurseries, a picnic area, and nearly 224 recorded bird species including peacocks, bee-eaters and owls.', '2-3 hours', 'October-February; early morning for birdwatching', 'Go early for birds; do not carry food — it is prohibited because it attracts animals.', NULL, 'Gujarat', 1, 0, '06:35', NULL, 'Rs 20', 4, 4, 21.7519, 72.1271, 'Near Gaurishankar Lake, Bhavnagar, Gujarat', NULL, 0.8);

