INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000135, 332006, 'Gaurishankar Lake (Bor Talav)', 'Gaurishankar Lake (Bor Talav)', 'A large man-made lake built in 1872 under Dewan Gaurishankar Oza as the city''s water reservoir, locally called Bor Talav, spread over about 381 hectares beside Victoria Park. It is Bhavnagar''s main picnic and evening-stroll spot with a boat house, nearby Pil Garden and views of Bhav Vilas Palace; migratory birds visit in winter.', '2-3 hours', 'October-February; sunrise or sunset', 'Best at sunrise or sunset for photography; check locally for boating availability and pond-side food stalls.', NULL, 'Gujarat', 1, 1, '06:35', '18:15', 'Rs 10', 4, 4, 21.7565, 72.1285, 'Bor Talav, Bhavnagar, Gujarat', NULL, 0.8);

