INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000136, 332006, 'Gangajalia (Ganga Deri)', 'Gangajalia (Ganga Deri)', 'A white-marble temple to Ganga-Devi built in 1893, with a chhatri, pavilion and marble bridge, standing in the middle of a former tank (Gangajalia Talav). It was designed by Sir John Griffith, principal of the Sir J J School of Arts, Bombay, and is a distinctive colonial-era landmark in the old city.', '30-60 minutes', 'October-February; morning', 'Walk the marble bridge across the tank for the classic view of the white temple against the water.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 3, 4, 21.7751, 72.1442, 'Gangajalia Talav, Bhavnagar, Gujarat', NULL, 0.68);

