INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000137, 332006, 'BAPS Shri Swaminarayan Mandir (Aksharwadi Temple)', 'BAPS Shri Swaminarayan Mandir (Aksharwadi Temple)', 'The BAPS Shri Swaminarayan Mandir in Bhavnagar, commonly called Aksharwadi Temple, opened in 2006 on Waghawadi Road about 4 km from the railway station. It is a large, well-maintained complex with a carved stone temple, spacious landscaped grounds and regular Sunday evening sabha, and is one of the city''s busiest places of worship.', '1-2 hours', 'October-February; morning or evening aarti', 'Allow time for the full campus — gardens and exhibition areas sit beyond the main temple.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 4, 4, 21.7541, 72.1419, 'Waghawadi Road, Aksharwadi, Bhavnagar, Gujarat 364002', NULL, 0.8);

