INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000138, 332006, 'Gandhi Smriti', 'Gandhi Smriti', 'A memorial museum in Bhavnagar dedicated to Mahatma Gandhi, housing photographs and items linked to his life, including his time as a student in Bhavnagar. The Barton Museum and Gandhi Smriti together form the city''s main heritage-museum stop in the northeast old city near the clock tower.', '1 hour', 'October-February; daytime', 'Pair it with the Barton Museum in the same visit; both sit near the old clock tower.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 3, 3, 21.772, 72.1535, 'Crescent Circle, Bhavnagar, Gujarat', NULL, 0.6);

