INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000139, 332006, 'Pil Garden (Bal Batika)', 'Pil Garden (Bal Batika)', 'A public garden adjoining Gaurishankar Lake, also called Bal-Batika, with a fountain, playground, children''s play area and a small zoo. It is the lake area''s main family stop, often visited together with Bor Talav and Victoria Park.', '1-2 hours', 'October-February; late afternoon', 'Best combined with a Bor Talav evening walk; the children''s play area makes it a family anchor.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 3, 3, 21.759, 72.1315, 'Near Gaurishankar Lake, Bhavnagar, Gujarat', NULL, 0.6);

