INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000140, 332006, 'Town Hall (Darbar Hall)', 'Town Hall (Darbar Hall)', 'The 1932 Town Hall of Bhavnagar, formerly the Darbar Hall of the princely state, where the coronation of Sir Krishnakumarsinhji took place. It is an imposing colonial-style structure set in a laid-out garden, notable as a heritage building to view from outside.', '30 minutes', 'October-February; daytime', 'View as a heritage stop on an old-city walk with Barton Library and Gandhi Smriti; it is primarily an exterior sight.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 2, 2, 21.7745, 72.154, 'Near Crescent Circle, Bhavnagar, Gujarat', NULL, 0.4);

