INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000141, 332006, 'Khodiyar Mandir', 'Khodiyar Mandir (city)', 'A well-known Hindu temple to Goddess Khodiyar in Bhavnagar city, listed among the city''s sightseeing stops. It is distinct from the larger and older Khodiyar Mata complex at Rajpara Dham on the Bhavnagar-Rajkot highway, which is a separate excursion.', '30-60 minutes', 'October-February; morning', 'If you want the major pilgrimage complex, head to Rajpara Dham (~20 km) instead — this is the city temple.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 2, 3, 21.7552, 72.1485, 'Bhavnagar, Gujarat', NULL, 0.48);

