INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000142, 332006, 'Shree Swaminarayan Mandir, Mahatma Gandhi Road', 'Shree Swaminarayan Mandir, Mahatma Gandhi Road', 'A Swaminarayan temple on Mahatma Gandhi Road in Bhavnagar''s old city, serving the local devotee community with daily darshan. It is a quieter, city-centre alternative to the large Aksharwadi (BAPS) complex.', '30-60 minutes', 'Morning or evening darshan', 'Visit in the old-city walk between the market streets and the clock tower area.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 2, 3, 21.782, 72.1458, 'Mahatma Gandhi Road, Bhavnagar, Gujarat', NULL, 0.48);

