INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000143, 332006, 'Brahma Kund, Sihor', 'Brahma Kund, Sihor', 'A stepped temple tank in Sihor, about 25-30 km from Bhavnagar, believed to have been built or refurbished by Chaulukya king Jayasimha Siddharaja (12th century) and mentioned in the Skanda Purana and Prabandha-Chintamani. It is a State Protected Monument (S-GJ-35) ringed with small shrines and stone sculptures of Hindu deities; its waters are traditionally considered miraculous.', '1-2 hours', 'October-February; morning', 'Roads inside Sihor''s old town are narrow — ask locals for the lane to the kund; combine with Gautameshwar Lake nearby.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 3, 3, 21.7055, 72.002, 'Sihor, Bhavnagar district, Gujarat (near the southern wall of the old town)', NULL, 0.6);

