INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000144, 332006, 'Vallabhipur', 'Vallabhipur (ancient capital)', 'Vallabhipur, about 38 km from Bhavnagar, was the ancient capital of the Maitraka dynasty and a famed seat of learning in the 5th-8th centuries. Today it is an archaeological area where old coins, copper plates and seals have been excavated, testifying to its antiquity — a short excursion for history-minded visitors.', '2-3 hours', 'October-February; morning', 'A half-day add-on with Sihor; there is little visitor infrastructure, so carry water and go with a local driver.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 2, 3, 21.787, 71.876, 'Vallabhipur, Bhavnagar district, Gujarat', NULL, 0.48);

