INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000145, 332006, 'Blackbuck National Park, Velavadar', 'Blackbuck National Park, Velavadar', 'Blackbuck National Park at Velavadar, about 42-47 km (roughly an hour) north of Bhavnagar, protects 34 sq km of Bhal-region grassland and is famous for its large blackbuck herds, Indian wolves and the world''s largest winter roost of harriers. There are two daily safari sessions (morning ~6:30 AM and afternoon ~3 PM); the park is closed 15 June-15 October for the monsoon and blackbuck breeding season.', 'Half day (3-4 hours)', 'December-March (best for migratory birds and harrier roost); closed 15 June-15 October', 'Go for the morning safari to see the harrier roost lift off at dawn (November-February); bring binoculars and drive slowly — animals cross the tracks.', 'Recommended — the forest department issues limited daily safari permits and a guide is compulsory, so arrange the visit in advance.', 'Gujarat', 1, 0, '06:35', NULL, 'Rs 400', 5, 5, 22.0353, 72.0494, 'Velavadar, Bhavnagar district, Gujarat 364313', NULL, 1.0);

