INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 332000145, 'insert', 'bulk', 'Confirmed real and documented: yatradham.org documents entry fees (Rs 400 weekdays, Rs 500 weekends), safari timings, compulsory guide, and 15 June-15 October closure; trawell.in documents timings 6:30 AM-1 PM & 3-6:30 PM, guide compulsion, and ~42-60 km distance from Bhavnagar. Coordinates approximate to Velavadar.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000146, 332006, 'Shatrunjaya Jain Temples, Palitana', 'Shatrunjaya Jain Temples, Palitana', 'The Palitana temple complex on Shatrunjaya Hill, about 56 km from Bhavnagar, is considered the holiest pilgrimage site in Jainism, with some 863 marble temples built over 900 years across two hills and the saddle between them. Pilgrims climb roughly 3,750 stone steps (about 3.5 km, ~2 hours up) to the summit; entry is free, no advance booking is needed, and the hills are closed to pilgrims for four months during the monsoon.', 'Full day (5-7 hours)', 'October-February; start the climb before sunrise', 'Carry water and wear modest clothing; photography is restricted in the temples; doli (carried chair) services are available for the ascent.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 5, 5, 21.4816, 71.7937, 'Shatrunjaya Hill, Palitana, Bhavnagar district, Gujarat', NULL, 1.0);

