INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 332000146, 'insert', 'bulk', 'Confirmed real and documented: Wikipedia documents Shatrunjaya as Jainism''s most sacred pilgrimage site, Palitana 56 km from Bhavnagar, ~3,750 steps, ~3.5 km climb, hills closed 4 months in monsoon, and the Kartik Purnima yatra; airial.travel confirms ~6 AM opening, no entry fee, modest dress, 1.5-2 hour drive from Bhavnagar. Coordinates of the summit temple area (21.4816, 71.7937).', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000147, 332006, 'Nishkalank Mahadev Temple, Koliyak', 'Nishkalank Mahadev Temple, Koliyak', 'A Shiva temple on a platform in the sea about 1-1.5 km off Koliyak beach, roughly 25 km from Bhavnagar, with five Shiva lingas that submerge at high tide. It is reachable only at low tide — devotees walk across the exposed seabed in roughly 2-3 hour windows twice a day that shift daily with the lunar cycle — so there are no fixed darshan hours. Entry is free; legend links the spot to the Pandavas after the Mahabharata war.', '2-3 hours', 'October-February; check the day''s tide tables before going', 'Check Bhavnagar tide timings (bhavnagar.city publishes a tide timetable) and never attempt the walk at high tide; the famous Bhadarvi fair is in Shravan (July-August).', NULL, 'Gujarat', 1, 0, '06:35', NULL, 'Free', 4, 4, 21.601, 72.2869, 'Koliyak Beach, Ghogha, Bhavnagar district, Gujarat', NULL, 0.8);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (332000147, 332000147, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'No fixed hours — accessible only during low-tide windows (~2-3 hours, twice daily, shifting ~50 minutes each day); return to shore before the tide comes back');

