INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 332000147, 'insert', 'bulk', 'Confirmed real and documented: hindutva.online documents the sea-platform shrine ~1 km off Koliyak beach, low-tide-only access in 2-3 hour windows, free entry, best months October-February; blog.yatradham.org documents ~25 km from Bhavnagar and the Shravan Bhadarvi fair; bhavnagar.city publishes tide timings. Coordinates (21.6010, 72.2869) from public location listings.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000148, 332006, 'Khodiyar Mata Mandir, Rajpara', 'Khodiyar Mata Mandir, Rajpara', 'A major Khodiyar Mata temple at Rajpara Dham on the Bhavnagar-Rajkot highway, about 20-22 km from Bhavnagar city, built in 1911 by the king of Bhavnagar state. Set beside Tataniya Dharo lake (with a ropeway over the water), it has dharamshalas for pilgrims and is especially crowded on major Hindu festivals and Purnima.', '2-3 hours', 'October-February; morning aarti', 'Try the ropeway over Tataniya Dharo lake for an aerial view of the temple; expect crowds on Purnima and festivals.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 4, 4, 21.7287, 72.0104, 'Rajpara Dham, Bhavnagar-Rajkot Highway, Bhavnagar district, Gujarat', NULL, 0.8);

