INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 332000148, 'insert', 'bulk', 'Confirmed real: gosahin.com documents the Rajpara Khodiyar Mata Mandir built in 1911 by the Bhavnagar king, on Tataniya Dharo Lake, with ropeway and dharamshalas; triphobo lists the Rajpara Dham address on the Bhavnagar-Rajkot highway with strong ratings. Hours from listings are unverified — left null. Coordinates approximate to the Rajpara approach area.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000149, 332006, 'Alang Ship-Breaking Yard', 'Alang Ship-Breaking Yard', 'The Alang-Sosiya ship-recycling yard, about 50 km (45-60 minutes) south of Bhavnagar, is one of the world''s largest ship-breaking facilities, stretching about 10 km along the coast. It is a restricted working industrial site, not a normal tourist attraction: entry needs prior permission, photography inside is prohibited, but visitors can view the yards from the coastal road and browse the huge salvage market for ship fittings and furniture.', '2-3 hours', 'November-February', 'Do not expect to walk in — arrange permission in advance and stay with authorised escorts; the coastal road viewpoint and salvage bazaar are the realistic sights.', 'Advance permission from the Gujarat Maritime Board Port Officer is required to enter the yard; arrange before visiting.', 'Gujarat', 0, 0, NULL, NULL, NULL, 3, 3, 21.4036, 72.1833, 'Alang, Bhavnagar district, Gujarat (coast road off Bhavnagar-Talaja road)', NULL, 0.6);

