INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 332000149, 'insert', 'bulk', 'Confirmed real and documented: travelsetu''s Alang FAQs document the yard ~10 km along the coast, restricted access requiring special permission, photography prohibition, and November-February as the sensible visiting season; cruisemapper documents ~50 km / 45-60 min from Bhavnagar and the permission requirement from the Port Officer. Coordinates approximate to Alang. No public ticket — cost null.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000150, 332006, 'Gopnath Beach and Mahadev Temple', 'Gopnath Beach and Mahadev Temple', 'Gopnath Beach and the ~700-year-old Gopnath Mahadev Temple on the Gulf of Khambhat, 75 km from Bhavnagar and 22 km from Talaja — the trip''s longest excursion. The seaside Shiva temple is where the devotional poet Narsinh Mehta is said to have had his spiritual experience; nearby stand the Bhavnagar royal family''s colonial-style Gopnath Bungalow (now a heritage hotel) and the old fort of the Gohil kings. The beach has high tidal disparity, so it suits walks rather than swimming.', 'Half to full day', 'October-February; afternoon to sunset', 'Not a swimming beach (muddy, rocky, big tides) — go for the temple, the sea views and the sunset; Talaja''s Buddhist caves and Jain hill temples can be combined on the way.', NULL, 'Gujarat', 1, 1, '06:35', '18:15', 'Free', 3, 3, 21.205, 72.105, 'Gopnath, Talaja taluka, Bhavnagar district, Gujarat', NULL, 0.6);

