INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000151, 332006, 'Mor Bagh Restaurant, Nilambag Palace Hotel', 'Mor Bagh Restaurant, Nilambag Palace Hotel', 'Mor Bagh is the multi-cuisine restaurant inside the Nilambag Palace heritage hotel, serving Indian, Chinese, Italian and Jain preparations in a former royal palace with courtyards and princely portraits. It is one of the few places in Bhavnagar serving non-vegetarian food (chicken, mutton, fish), alongside a full vegetarian menu; the official menu lists dishes from about Rs 65 (pani puri) to Rs 650 (veg sizzler). Gujarat is a dry state — no alcohol is served.', '1-2 hours', 'Lunch or dinner; cooler months', 'The palace setting is the draw — dress smartly and ask for a courtyard table; confirm vegetarian/Jain options when ordering.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Rs 250-350', 4, 4, 21.751, 72.1395, 'Nilambag Palace Hotel, Nilambaug Circle, Bhavnagar, Gujarat 364002', 'https://nilambagpalace.com/promotion/RestaurantMenuVeg.pdf', 0.8);

