INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000152, 332006, 'Gallops Food Plaza', 'Gallops Food Plaza', 'A large, busy pure-veg food plaza on the Ahmedabad-Bhavnagar highway, Justdial-verified and one of the highest-footfall restaurants in the Bhavnagar listings with tens of thousands of ratings. It serves multi-cuisine vegetarian food (Gujarati, Punjabi, Chinese, South Indian) and is a standard halt for travellers on the highway.', '45-90 minutes', 'Lunch or dinner', 'Useful early-morning breakfast stop on the highway; it opens at 6 AM.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 4, 4, 21.762, 72.18, 'Ahmedabad-Bhavnagar Highway, Bhav Anand Nagar, Bhavnagar, Gujarat', NULL, 0.8);

