INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000153, 332006, 'Vishala Park Restaurant', 'Vishala Park Restaurant', 'A well-rated pure-vegetarian restaurant in Vidya Nagar serving Gujarati and multi-cuisine vegetarian food, with a listed price of about Rs 260 for two. It is a long-standing local favourite with over 2,000 ratings on its directory listing.', '45-90 minutes', 'Lunch or dinner', 'Good budget Gujarati-veg option; go for lunch thali-style meals.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Rs 260', 3, 4, 21.752, 72.157, 'Vidhya Nagar, Bhavnagar, Gujarat', NULL, 0.68);

