INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000154, 332006, 'Dada Ni Vadi Kathiyavadi Restaurant', 'Dada Ni Vadi Kathiyavadi Restaurant', 'A pure-vegetarian Kathiyawadi restaurant on Bhavnagar-Sidsar Road specialising in the Saurashtra-style Kathiyawadi thali — bajra rotla, ringan no olo, sev-tameta, buttermilk and jaggery. Evening-oriented (opens around 7 PM), it is the go-to spot for an authentic local thali dinner.', '1-1.5 hours', 'Dinner (opens 7 PM)', 'Go hungry and order the full Kathiyawadi thali; arrive soon after 7 PM as it is dinner-focused.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 4, 4, 21.745, 72.13, 'Bhavnagar-Sidsar Road, Bhavnagar, Gujarat', NULL, 0.8);

