INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000156, 332006, 'Shree Raj Khodiyar Restaurant', 'Shree Raj Khodiyar Restaurant', 'A pure-vegetarian restaurant near Nilambaug Circle serving Gujarati and multi-cuisine vegetarian food, open long hours (from 11 AM to about midnight). It is a convenient dinner option close to Nilambag Palace with several hundred ratings on its directory listing.', '45-90 minutes', 'Dinner; open late', 'Handy late-evening veg dinner near Nilambaug Circle after a palace visit.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 3, 3, 21.75, 72.14, 'Dev Baug, Nilambaug Circle, Bhavnagar, Gujarat', NULL, 0.6);

