INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3320023, 332, 332006, 'Shatrunjay Teerth Yatra (Kartik Purnima)', 'October-November', 'The annual Shatrunjay Teerth Yatra is held on Kartik Purnima (the full-moon day of the Kartik month), when thousands of Jains gather at the base of Shatrunjaya Hill near Palitana for the sacred hill circumambulation; devotees believe a yatra on this day is a once-in-a-lifetime event.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3320024, 332, 332006, 'Bhadarvi Mela (Nishkalank Mahadev)', 'July-August', 'The famous annual fair at Nishkalank Mahadev Temple on Koliyak beach, held in the month of Shravan. The fair is traditionally inaugurated with a flag hoisted by descendants of Bhavnagar''s royal family, and the flag reportedly stands through the tides all year.');

