INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000157, 332007, 'Lakhota Palace & Museum', 'Lakhota Palace and Museum', 'Lakhota Palace is an 18th-19th century fort-palace built by the rulers of Nawanagar, standing on an island in the middle of Ranmal (Lakhota) Lake and reached by an arched stone bridge. It now houses the Lakhota Museum with sculptures from the 9th to 18th centuries, pottery, coins, a whale skeleton and frescoes of Jadeja Rajput battles. The guardroom at the entrance still displays muskets, swords and powder flasks from its days as a fort.', '1.5-2 hours', 'October to March', 'Visit the museum in the morning slot and stay on for an evening walk around the lit lake; the musical fountain show runs at night near the palace.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Rs 25', 5, 4, 22.46476, 70.06958, 'Lakhota Lake, Government Colony, Jamnagar 361001, Gujarat', NULL, 0.92);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (332000157, 332000157, '10:30 AM - 2:00 PM, 2:30 PM - 5:30 PM', '10:30 AM - 2:00 PM, 2:30 PM - 5:30 PM', NULL, '10:30 AM - 2:00 PM, 2:30 PM - 5:30 PM', '10:30 AM - 2:00 PM, 2:30 PM - 5:30 PM', '10:30 AM - 2:00 PM, 2:30 PM - 5:30 PM (closed on 2nd and 4th Saturdays)', '10:30 AM - 2:00 PM, 2:30 PM - 5:30 PM', 'Closed on Wednesdays, 2nd and 4th Saturdays and public holidays. Foreigner entry Rs 100.');

