INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000158, 332007, 'Lakhota Lake (Ranmal Lake)', 'Lakhota Lake (Ranmal Lake)', 'Ranmal Lake, better known as Lakhota Lake, is the scenic water body at the heart of old Jamnagar, encircling the Lakhota Palace island. A paved promenade with benches rings the lake and is popular with locals for morning walks, evening strolls and birdwatching (pelicans, gulls, ducks). The lake area is lit at night and hosts a musical fountain/laser show.', '1-2 hours', 'October to March; evenings year-round', 'Come at sunrise for birdwatching and at sunset for the lit-up palace view; entry is free in the early morning hours (5-9 AM) per visitor reports.', NULL, 'Gujarat', 1, 1, '06:41', '18:39', 'Rs 10', 5, 4, 22.4662, 70.068, 'Ranmal Lake, Government Colony, Jamnagar 361001, Gujarat', NULL, 0.92);

