INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 332000158, 'insert', 'bulk', 'Lake identity, promenade, boating, birdlife and night lighting confirmed via trawell.in and Zeezest; lake timings 5 AM-10 PM, lake entry Rs 10 and fountain Rs 25 from trawell.in. Coordinates approximate point on the lake shore within 1 km of geocoded Lakhota Lake point.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000159, 332007, 'Bala Hanuman Temple', 'Bala Hanuman Temple', 'The Bala Hanuman Temple stands on the southeastern side of Lakhota Lake and is famous for the continuous chanting of the Ram Dhun (''Shri Ram, Jai Ram, Jai Jai Ram'') that has run 24 hours a day since 1 August 1964, earning it a place in the Guinness Book of Records. Devotees chant in shifts round the clock, and visitors may join in, especially during the difficult night sessions. Early evening, around aarti time, is the most atmospheric time to visit.', '45 minutes - 1 hour', 'October to March; early evening for aarti', 'Visit in the early evening for the aarti and the full effect of the non-stop chanting; dress modestly and keep voices low inside the sanctum.', NULL, 'Gujarat', 0, 1, NULL, '18:39', 'Free', 5, 5, 22.46235, 70.07096, 'Shri Prembhikshuji Marg, Government Colony, Jamnagar 361001, Gujarat', NULL, 1.0);

