INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 332000159, 'insert', 'bulk', 'Temple location (SE side of Ranmal/Lakhota Lake), continuous Ram Dhun since 1 Aug 1964 and Guinness record confirmed via Zeezest and the Ranmal Lake Scribd document. Coordinates from map geocoder (Shri Prambhikshu Ji Marg, Government Colony). No published darshan hours found.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000160, 332007, 'Bhujia Kotha', 'Bhujia Kotha', 'Bhujia Kotha (also called the Kotha Bastion) is a 174-year-old tower near Lakhota Lake, built between 1839 and 1852 as the arsenal and watchtower of Nawanagar and once considered the tallest building in Saurashtra. Damaged in the 2001 earthquake, it was restored by the Jamnagar Municipal Corporation with the ASI at a cost of Rs 25 crore, with Phase 1 inaugurated by the Prime Minister on 20 September 2025. It reopened to tourists on 19 March 2026 and is being linked with Khambhaliya Gate and Lakhota Museum in a heritage chain.', '45 minutes - 1 hour', 'October to March', 'Combine with Lakhota Lake and the museum in one walk; it is within 1 km of the Bala Hanuman Temple and Khambhalia Gate.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 4, 4, 22.46689, 70.0719, 'Near Lakhota Lake, Kadiawad, Jamnagar 361001, Gujarat', NULL, 0.8);

