INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 332000160, 'insert', 'bulk', 'Reopening to tourists from 19 March 2026, 1839-1852 construction, Rs 25 crore restoration with ASI and 20 Sep 2025 inauguration confirmed via Latestly (ANI) and webindia123; coordinates are an approximate point on the eastern edge of Lakhota Lake (geocoder could not resolve the tower itself) within ~500 m of the lake.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000161, 332007, 'Pratap Vilas Palace', 'Pratap Vilas Palace', 'Pratap Vilas Palace was built by Jam Ranjitsinhji between 1907 and 1915 in an Indo-Saracenic style overlaid with European influences, said to echo Kolkata''s Victoria Memorial, with three glass domes and pillars carved with birds, animals and creepers. It was designed as a guest house for royal guests and never lived in by the Maharaja; its grounds were converted into a nature park in 1968. It is not routinely open to the public - permission must be sought from the Darbargadh Palace office - so most visitors admire the facade and domes from the gates.', '30-45 minutes', 'October to March, daytime', 'Do not plan the day around entering - go for the exterior architecture and photography, and check locally about permission before visiting.', 'Prior permission from the Darbargadh Palace office is required; interiors may remain closed even with permission.', 'Gujarat', 0, 0, NULL, NULL, 'Rs 100', 4, 3, 22.47893, 70.05592, 'Park Colony, Jamnagar 361008, Gujarat', NULL, 0.72);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (332000161, 332000161, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Not open to the public; visits only with prior permission from Darbargadh Palace. trawell.in lists 11 AM - 5 PM and Rs 100 per person where permission is granted.');

