INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 332000161, 'insert', 'bulk', '1907-1915 construction, Indo-Saracenic/European style, glass domes and permission-only access confirmed via jamnagaronline.in, trawell.in and travelsetu FAQs; TripAdvisor visitor reviews corroborate that gates are usually closed to the public. Coordinates from map geocoder (Park Colony).', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000162, 332007, 'Darbargadh Palace', 'Darbargadh Palace', 'Darbargadh is the original palace residence of the Jam Sahibs of Nawanagar, evolved over centuries, reflecting a fusion of Rajput and European architectural styles. In front of it, Jam Ranjitsinhji commissioned two notable urban-design projects: the Willingdon Crescent arcade and Chelmsford Market. It remains the ceremonial heart of the old city and the office from which permissions for Pratap Vilas Palace visits are sought.', '30-45 minutes', 'October to March', 'View the facade together with Willingdon Crescent opposite; ask at the office here about Pratap Vilas Palace visit permissions.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 4, 3, 22.46541, 70.0801, 'Ashapura Road, Kadiawad, Jamnagar 361001, Gujarat', NULL, 0.72);

