INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000163, 332007, 'Willingdon Crescent', 'Willingdon Crescent', 'Willingdon Crescent is a distinctive horseshoe-shaped, two-storeyed arcaded market in front of Darbargadh, commissioned by Jam Ranjitsinhji with semi-circular arches at both levels, decorative plasterwork and a balustrade. It is one of Jamnagar''s most photographed heritage streetscapes and still functions as a busy bazaar for bandhani textiles, brassware and everyday goods. It pairs naturally with a Darbargadh and old-city walk.', '45 minutes - 1 hour', 'October to March; mornings for shopping', 'Best photographed in morning light; bargain politely and try the street-food stalls around Gandhi Chowk.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 4, 4, 22.46416, 70.07987, 'Gandhi Chowk, Kadiawad, Jamnagar 361001, Gujarat', NULL, 0.8);

