INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000164, 332007, 'Khambhalia Gate', 'Khambhalia Gate', 'Khambhalia Gate is one of the historic gates of old Jamnagar''s fortified wall, standing near Lakhota Lake within walking distance of Bhujia Kotha and the Bala Hanuman Temple. It is a popular photo stop on the lake heritage circuit and is being linked with Bhujiya Kotha and the Lakhota Museum through a single-entry heritage chain. The gate anchors the old-city edge of the lake promenade.', '15-30 minutes', 'October to March', 'Combine with the lake circuit on foot; the gate photographs well with the old-city rooftops behind it.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 3, 3, 22.46137, 70.07143, 'Government Colony, Jamnagar 361001, Gujarat', NULL, 0.6);

