INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000165, 332007, 'Vardhman Shah''s Jain Temple', 'Vardhman Shah''s Jain Temple', 'Vardhman Shah''s Jain Temple, in the crowded Chandi Bazar of the old city, is one of Jamnagar''s four great marble Jain temples built between 1574 and 1622. Its foundation stone was laid in 1612 during the reign of Jam Jasaji and the shrine was completed in 1620, with 52 small ''deri'' shrines added around it in 1622. Dedicated to Tirthankar Adinath, it is known for intricate marble carving and a vibrant, colourful interior.', '45 minutes - 1 hour', 'October to March; early morning to avoid market crowds', 'Park 1-2 km away and take an auto-rickshaw into Chandi Bazar; remove leather items and shoes before entering the sanctum.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 4, 4, 22.465, 70.077, 'Chandi Bazar, Kadiawad, Jamnagar 361001, Gujarat', NULL, 0.8);

