INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000166, 332007, 'Shantinath Mandir', 'Shantinath Mandir (Raisi Shah''s Jain Temple)', 'The Shantinath Mandir is among Jamnagar''s celebrated old marble Jain temples in the old-city cluster around Chandi Bazar. Jamnagar''s Jain heritage is anchored by four marble temples raised between 1574 and 1622 - Vardhman Shah''s, Raisi Shah''s (dedicated to Tirthankar Shantinath), Sheth''s and Vasupujya Swami''s - of which Raisi Shah''s is noted for gold-inlay work on its sanctum dome, mirrored ceilings and geometric marble floors. Morning visits are recommended for the calmest darshan.', '30-45 minutes', 'October to March; mornings', 'Visit in the morning when the marble interiors are at their best; combine with Vardhman Shah''s temple and the Chandi Bazar walk.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 4, 4, 22.46432, 70.07759, 'Bhagwan Mahaveer Swami Circle, Kadiawad, Jamnagar 361001, Gujarat', NULL, 0.8);

