INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 332000166, 'insert', 'bulk', 'Jamnagar''s four marble Jain temples (1574-1622) and Raisi Shah''s dedication to Shantinath with gold-inlay sanctum dome confirmed via jainsamaj.org (Ahimsa Foundation) and the Jamnagar religious-demographics Scribd doc; Shantinath Mandir listed among Jamnagar attractions on travelsetu. Coordinates from map geocoder (Bhagwan Mahaveer Swami Circle, Kadiawad); identification of this mandir with Raisi Shah''s temple is probable but not certain - flagged.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000167, 332007, 'Bhidbhanjan Mahadev Temple', 'Bhidbhanjan Mahadev Temple', 'Bhidbhanjan Mahadev is a historic Shiva temple of Jamnagar, built by the Jam Saheb, located near the Town Hall in the old city. It is counted among the city''s notable Shiv temples alongside Badri Kedar Nath, Nilkanth Mahadev and Kashi Vishwanath. The temple draws steady local devotion and is an easy add-on to the Lakhota Lake and old-city circuit.', '30 minutes', 'October to March; mornings and evenings', 'Combine with the lake promenade walk; Maha Shivratri sees special crowds here.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 3, 3, 22.46951, 70.0688, 'Maharishi Arvind Marg, Patrakar Colony, Jamnagar 361001, Gujarat', NULL, 0.6);

