INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000168, 332007, 'Bohra Hajira', 'Bohra Hajira', 'Bohra Hajira is the magnificent mausoleum-dargah of the Dawoodi Bohra community in Jamnagar, a domed memorial to a revered Muslim saint standing on the banks of the river near the Rajkot highway. It is regarded as a heritage monument worth visiting for its architecture and serene compound. Visitors wishing to take photographs should seek permission at the office inside the compound.', '30-45 minutes', 'October to March', 'Dress conservatively and ask at the compound office before photographing the mausoleum.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 3, 3, 22.47546, 70.08353, 'Zakavi Mohalla, Nageshwar Colony, Jamnagar 361008, Gujarat', NULL, 0.6);

