INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000169, 332007, 'Ratan Bai Masjid', 'Ratan Bai Masjid', 'Ratan Bai Masjid is a historic mosque in the old city near Jain Derasar Road, listed among Jamnagar''s heritage places of worship. It reflects the city''s long-standing Muslim community, which forms about a fifth of the district''s population, and sits within the old-city fabric close to the Jain temple cluster. Modest dress and quiet conduct are expected of visitors.', '20-30 minutes', 'October to March; outside prayer times', 'Visit outside the five daily prayers and dress modestly; combine with the nearby Jain temples walk.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 3, 3, 22.46654, 70.0772, 'Jain Derasar Road, Panchasar, Kadiawad, Jamnagar 361001, Gujarat', NULL, 0.6);

