INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000170, 332007, 'Dhanvantari Mandir', 'Dhanvantari Mandir (Ayurved University)', 'The Dhanvantari Mandir stands on the campus of Jamnagar''s famed Ayurved University (now the Institute of Teaching and Research in Ayurveda), built under the personal supervision of Dr Pranjivan Manekchand Mehta, then chief medical officer of the Guru Govindsingh Hospital. Jamnagar is renowned as a centre of Ayurvedic learning, and the temple to Dhanvantari, the divine physician, is its spiritual anchor. The leafy university campus makes a calm, offbeat stop.', '30-45 minutes', 'October to March', 'Ask at the campus gate about visitor access; combine with a drive past Pratap Vilas Palace nearby.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 3, 3, 22.47667, 70.06248, 'Ayurved University Marg, Jamnagar 361008, Gujarat', NULL, 0.6);

