INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000171, 332007, 'BAPS Shri Swaminarayan Mandir', 'BAPS Shri Swaminarayan Mandir', 'The BAPS Shri Swaminarayan Mandir on the Khambhaliya Bypass is Jamnagar''s grand modern Swaminarayan temple, inaugurated in 2014 and marking its tenth anniversary in March 2024. Built and managed by the Bochasanwasi Akshar Purushottam Swaminarayan Sanstha, it is known for intricate marble carvings, manicured lawns and gardens, and a family-friendly campus with the Premvati restaurant serving affordable meals. It has become one of the city''s most visited weekend spots, a few minutes from the airport.', '1-2 hours', 'October to March; evenings', 'Go in the late afternoon to enjoy the gardens in daylight and the lit temple after dusk; try a meal at the Premvati restaurant inside.', NULL, 'Gujarat', 0, 1, NULL, '18:39', 'Free', 4, 4, 22.45372, 70.02852, 'Pramukh Swami Maharaj Marg, Khambhaliya Bypass, near Samarpan Hospital, Ajanta Society, Jamnagar 361006, Gujarat', 'https://www.baps.org/', 0.8);

