INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000172, 332007, 'Teen Batti Chowk', 'Teen Batti Chowk', 'Teen Batti is the famous triple-lamp junction of old Jamnagar, a landmark chowk where three historic lamp posts once lit the crossroads. It anchors a busy old-city neighbourhood of eateries and shops - Hotel Aram, Hotel Kalpana and the Swati Restaurant all cluster around it - and remains a handy navigation landmark. It is best experienced as a quick stop on an old-city food and heritage walk.', '15-30 minutes', 'October to March; evenings for the food stalls', 'Use it as the starting point for an old-city evening food walk - several well-known local eateries are within a few minutes on foot.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 2, 3, 22.47166, 70.07041, 'SH-26, Patrakar Colony, Jamnagar 361001, Gujarat', NULL, 0.48);

