INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000173, 332007, 'Jogger''s Park', 'Jogger''s Park (Gulab Kunvarba Udhyan)', 'Jogger''s Park, also called Gulab Kunvarba Udhyan, is a popular green lung near the Palace Ground in Jamnagar, busiest in the mornings with walkers and runners. It is a simple, pleasant city park for a morning stroll or an evening sit-out, especially in winter when locals lounge in the sun. It pairs well with a Pratap Vilas Palace drive-by, being in the same part of town.', '45 minutes - 1 hour', 'October to March; mornings', 'Go early morning to join the local walking crowd; carry water as facilities are basic.', NULL, 'Gujarat', 1, 0, '06:41', NULL, 'Free', 2, 3, 22.47999, 70.05501, 'Paras Society Road, Park Colony, Jamnagar 361008, Gujarat', NULL, 0.48);

