INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000174, 332007, 'Khijadiya Bird Sanctuary', 'Khijadiya Bird Sanctuary', 'Khijadiya Bird Sanctuary is a Ramsar wetland site (designated 13 April 2021) about 12 km north-east of Jamnagar, unique for combining freshwater lakes with salt and freshwater marshlands. Over 300 bird species have been recorded, including Dalmatian pelican, greater and lesser flamingo, painted stork, common crane and the endangered Indian skimmer. Winter (November-February) brings thousands of migratory waterbirds from Central Asia along the Central Asian Flyway.', '2-3 hours', 'November to February', 'Arrive early morning with binoculars; carry water and snacks as there are no shops inside.', NULL, 'Gujarat', 1, 0, '06:41', NULL, NULL, 5, 5, 22.5241, 70.1214, 'Khijadiya village, ~12 km north-east of Jamnagar, Gujarat', NULL, 1.0);

