INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 332000174, 'insert', 'bulk', 'Ramsar designation (site 2464, 13 Apr 2021), 12 km from Jamnagar, 300+ species and freshwater/salt marsh ecology confirmed via Wikipedia and the Ramsar Sites Information Service. Coordinates 22.5241, 70.1214 from Ramsar/Wikipedia (22 deg 31''27'''' N, 70 deg 07''17'''' E).', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000175, 332007, 'Narara Marine National Park', 'Narara Marine National Park', 'Narara is the mainland reef-walk section of the Marine National Park in the Gulf of Kutch, about 60 km from Jamnagar towards Dwarka. At low tide the sea recedes to reveal a living reef where guides point out octopus, puffer fish, sea stars, anemones, crabs, sea cucumbers and corals, with flamingos and pelicans in the old salt pans on the approach road. Entry is by Forest Department permit issued at the Narara office, and the coral walk is only possible in the 2-3 hour low-tide window.', 'Half day (3-4 hours on the reef)', 'October to March', 'Wear strapped rubber footwear for the sharp reef, carry all food and water, and hire the guide at the entry gate - the walk takes 3-4 hours with no shelter.', 'Forest Department permit required (issued on the spot at Narara); visit must be timed to low tide - check tide timings with the forest office before going.', 'Gujarat', 0, 1, NULL, '18:39', 'Rs 100', 5, 5, 22.46459, 69.72532, 'Narara Reef, Marine National Park Road, near Vadinar, Lalpur, Gujarat 361010', NULL, 1.0);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (332000175, 332000175, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Timings depend entirely on the day''s low tide (typically a 2-3 hour window); forest office opens around 9 AM. Confirm tide times with the forest office before visiting.');

