INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 332000175, 'insert', 'bulk', 'Narara reef walk, ~60 km from Jamnagar toward Dwarka, permit-on-the-spot system and Rs 100 Indian entry (+25% weekends/holidays) confirmed via coloursofgujarat.com; tide-dependent access and marine life confirmed via trawell.in and TripAdvisor reviews; park established 1982 per Wikipedia. Coordinates from map geocoder (Narara Reef, Marine National Park Road, Lalpur).', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000176, 332007, 'Pirotan Island', 'Pirotan Island', 'Pirotan Island is the best-known of the 42 islands of the Marine National Park in the Gulf of Kutch, famed for coral reefs, mangroves and intertidal marine life - crabs, jellyfish, octopus, starfish and seahorses visible without entering the water. The island (reef at approx 22 deg 35''03'''' N, 69 deg 57''26'''' E) is reached by hired boat from Bedi or Nava Port near Jamnagar, timed around high tide. There is no food, drinking water or stay facility on the island, so visitors must carry everything and travel with a guide.', 'Full day', 'November to March', 'Go in a group of 25-50 via an organiser if possible; carry all food and water, and do not collect shells, coral or stones - it is a protected area.', 'Forest Department permit from Jamnagar required; boats must be hired from Bedi or Nava Port and trips are tide-dependent - book through a tour organiser.', 'Gujarat', 0, 0, NULL, NULL, NULL, 4, 5, 22.5842, 69.9573, 'Marine National Park, Gulf of Kutch (boats from Bedi / Nava Port, Jamnagar)', NULL, 0.88);

