INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000177, 332007, '360 The Rooftop Restaurant', '360 The Rooftop Restaurant (Hotel Aram)', '360 The Rooftop Restaurant is the rooftop dining outlet of heritage Hotel Aram, a heritage hotel run in an Art-Deco-era building that belonged to the Jadejas of Nawanagar for the past 40 years. Gujarat Tourism calls the rooftop an all-round-view perch ideal for evenings; the hotel also runs the ground-floor Aram Restaurant (Indian and Chinese). Travel booking listings note the rooftop serves Chinese, Indian and pizza, and recent guest reviews praise the Gujarati thali.', '1.5-2 hours', 'Evenings', 'Go in the evening for the rooftop view of the town; the ground-floor Aram Restaurant serves Indian and Chinese food through the day.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Rs 200-400', 4, 4, 22.48907, 70.05168, 'Hotel Aram, Bedi Road, Opp DKV College, Indradeep Society, Jamnagar 361008, Gujarat', NULL, 0.8);

