INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 332000177, 'insert', 'bulk', 'Restaurant existence verified via Gujarat Tourism (gtbooking: rooftop restaurant 360 with all-round town view at Hotel Aram), travelated (Aram Restaurant Indian/Chinese, 360 Rooftop Chinese/Indian/pizza) and a Sep 2025 Cleartrip review naming ''360 Roof'' as one of Jamnagar''s oldest/best restaurants. Price band Rs 200-400 and ''opens 7 PM'' from the Google Hotels business card for the rooftop. Coordinates geocoded to Bedi Road (Hotel Aram''s road); approximate - within ~1 km of the actual building.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000178, 332007, '7 Seas Restaurant', '7 Seas Restaurant', '7 Seas is the long-running restaurant inside Hotel President at Teen Batti, serving Indian and Asian food. Reviewers highlight its fried chicken, fried fish, lassi and prompt service. Ranked #6 of 111 restaurants in Jamnagar on TripAdvisor (3.8/5 from 77 reviews) with the listing managed by the business itself.', '1-1.5 hours', 'Lunch or dinner', 'Convenient central stop near Teen Batti; reviewers recommend the fried chicken, fried fish and lassi.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Rs 200-1000', 4, 4, 22.47063, 70.0712, 'Hotel President, Limbda Line, Teen Batti Road, Jamnagar 361001, Gujarat', 'http://www.hotelpresident.in/', 0.8);

