INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000179, 332007, 'Spicy Bite Multicuisine Restaurant', 'Spicy Bite Multicuisine Restaurant', 'Spicy Bite is a popular multicuisine restaurant at Digjam Circle serving Chinese, Indian, Italian and Mexican food. It holds 4.9/5 from 151 TripAdvisor reviews with reviews as recent as January 2026, and reviewers praise the biryani, tandoori chicken, egg curry and mocktails. Justdial rates it 4.5/5 from 314 ratings.', '1-1.5 hours', 'Lunch or dinner', 'Good pick for groups that want veg and non-veg plus continental options; try the biryani or the tandoori platter.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Rs 550 for two', 4, 4, 22.47029, 70.04228, '2nd Floor, Vinayak Plaza, Digjam Circle, Aerodrome Road, Jamnagar 361006, Gujarat', NULL, 0.8);

