INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000180, 332007, 'Annapurna Restaurant', 'Annapurna Restaurant', 'Annapurna is a budget Gujarati eatery in the Jamnagar Market area, ranked #5 among the best restaurants in Jamnagar District on Wanderlog. It serves unlimited Gujarati thalis for lunch and dinner with quick service and takeaway options; reviewers mention buttermilk, parathas, vagharelo rotolo and shrikhand. Renowned travel vlogger Harish Bali has recommended it.', '1 hour', 'Lunch (11 AM - 3:30 PM)', 'Visit at lunch for the freshest unlimited thali spread; skip advance coupons, per one reviewer''s experience.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 4, 3, 22.47519, 70.1014, 'Mohan Nagar, Gulabnagar, Jamnagar 361001, Gujarat', NULL, 0.72);

