INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000181, 332007, 'Sankalp - The Taste of South', 'Sankalp - The Taste of South', 'Sankalp - The Taste of South is Jamnagar''s outlet of the Sankalp South Indian vegetarian chain (listed on the chain''s official locations page). It serves dosa, idli, uttapam, biryani and filter coffee from all four South Indian states in a family-friendly dining room.', '1 hour', 'Lunch or dinner', 'Try the Super Paper Dosa or Panchavarna Uttapam, the chain''s signature items.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Rs 500', 4, 4, 22.48357, 70.05774, 'First Floor, Dhiraj Building, 4 Patel Colony Corner, Near St. Ann''s School, Pandit Nehru Marg, Jamnagar, Gujarat', 'https://sankalprestaurants.com/', 0.8);

