INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000182, 332007, 'Prasadam Restaurant & Banquet', 'Prasadam Restaurant & Banquet', 'Prasadam Restaurant & Banquet is the multi-cuisine restaurant of The Sky Imperial group at Hotel Kailash, serving Punjabi, Gujarati, Chinese, South Indian, pizza and snacks, plus a banquet venue for weddings and parties. It holds 4.4/5 from 14 TripAdvisor reviews (#8 of 111 restaurants in Jamnagar) with the listing managed by the business, and 4.8/5 from 262 reviews on restaurant-guru.', '1-1.5 hours', 'Lunch or dinner', 'Also books banquets and events; Chinese dishes are the most recommended by reviewers.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Rs 200-400', 4, 4, 22.46015, 70.03535, 'The Sky Imperial Hotel Kailash, Near Samarpan Hospital, Ajanta Society, Jamnagar 361006, Gujarat', 'https://www.theskyimperial.com/Hotels/Prasadam-Jamnagar', 0.8);

