INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3320025, 332, 332007, 'Jamnagar Lok Mela', 'August-September', 'Jamnagar Municipal Corporation-organised fair that runs from Janmashtami Day till the end of the Shravan month, drawing 4-5 lakh visitors with shopping stalls, food, rides, cultural shows and public-awareness booths.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3320026, 332, 332007, 'Navratri', 'September-October', 'Nine nights of garba and dandiya raas across the city; Jamnagar is noted for the traditional Indhoni Raas Garba, where women dance with a flaming indhoni (pot-holder) balanced on their heads.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3320027, 332, 332007, 'Krishna Janmashtami', 'August-September', 'Birth anniversary of Lord Krishna celebrated on a grand scale in Jamnagar, with fairs held at Jamnagar and nearby Dwarka and special festivities at Krishna temples across the city.');

-- city: Junagadh (id 1058)
INSERT OR IGNORE INTO cities (id, state_id, city_name, latitude, longitude) VALUES (332008, 332, 'Junagadh', 21.5222, 70.4579);

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000183, 332008, 'Girnar Hill & Girnar Ropeway', 'Girnar Hill & Girnar Ropeway', 'Girnar is Gujarat''s highest and most sacred mountain, a 10,000-step pilgrimage climb through Jain and Hindu shrines to the summit. The Girnar Ropeway (Udankhatola), Asia''s longest at 2.1 km, rises to the Ambaji temple at 850 m and offers sweeping views over Junagadh and the Saurashtra plains.', '4-6 hours', 'October to March', 'Take the ropeway up and walk the upper steps to the Neminath and Dattatreya shrines; start early to avoid the midday heat.', NULL, 'Gujarat', 1, 0, '07:00', NULL, 'INR 699 adult / INR 350 child (ropeway round trip)', 5, 5, 21.49472, 70.50556, 'Bhavnath Taleti, Junagadh, Gujarat 362004', 'https://udankhatola.com/destination/Girnar', 1.0);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (332000183, 332000183, '07:00-17:00', '07:00-17:00', '07:00-17:00', '07:00-17:00', '07:00-17:00', '07:00-17:00', '07:00-17:00', 'Ropeway timings 7 AM-5 PM from the official udankhatola.com Girnar page; hill itself accessible sunrise to sunset for pilgrims.');

