INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000184, 332008, 'Neminath Jain Temple, Girnar', 'Neminath Jain Temple, Girnar', 'The largest and oldest of the Girnar Jain temples, dedicated to Neminath, the 22nd tirthankara. Completed in 1129 CE by Sajjana, governor of Saurashtra, it is celebrated for its carved marble facade and black-marble idol with cowrie-shell eyes, maintained by the Anandji Kalyanji Trust.', '1-2 hours', 'October to March', 'Combine with the Ambaji ropeway stop; remove footwear and dress modestly - strict Jain temple rules apply.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 4, 5, 21.52672, 70.52319, 'Neminath Temple, Girnar Hill, Junagadh, Gujarat', NULL, 0.88);

