INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000185, 332008, 'Bhavnath Mahadev Temple', 'Bhavnath Mahadev Temple', 'Ancient Shiva temple at the base of Girnar housing a self-emerged (swayambhu) Shivling. The legendary Mrigi Kund inside the compound is where Naga sadhus bathe before the midnight procession of the five-day Maha Shivratri fair, one of Gujarat''s great religious spectacles.', '1 hour', 'October to March; Maha Shivratri (Feb-Mar)', 'Visit at dusk for evening aarti; the temple is the starting point of the Girnar Lili Parikrama.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 4, 4, 21.5274, 70.5018, 'Bhavnath Mahadev, Taleti, Girnar, Junagadh, Gujarat 362004', NULL, 0.8);

