INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000186, 332008, 'Uparkot Fort', 'Uparkot Fort', 'A 2,300-year-old hill fort with Mauryan origins, rebuilt by Chudasama king Graharipu around 940-982 CE. Inside its walls are the Adi-Kadi Vav and Navghan Kuvo stepwells, ancient Buddhist caves, the 15th-century Jama Masjid, and the massive Neelam and Manek cannons.', '3-4 hours', 'October to March', 'Allow a half day to cover the fort''s scattered monuments; carry water - there is little shade.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 5, 4, 21.5236831, 70.4695183, 'Uparkot Fort, Junagadh, Gujarat', NULL, 0.92);

