INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000188, 332008, 'Navghan Kuvo', 'Navghan Kuvo', 'A deep rock-cut well inside Uparkot Fort reached by a remarkable circular staircase carved around its shaft. Built in the Western Satrap/Maitraka era or under 11th-century king Navghan, it shows how the fort''s garrisons secured water through sieges.', '30 minutes', 'October to March', 'Look for the birds nesting in the shaft walls.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 3, 3, 21.5225, 70.468, 'Inside Uparkot Fort, Junagadh, Gujarat', NULL, 0.6);

