INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000190, 332008, 'Ashoka''s Major Rock Edicts (Girnar)', 'Ashoka''s Major Rock Edicts (Girnar)', 'Fourteen edicts of Emperor Ashoka inscribed on a huge boulder around 257 BCE in Brahmi script - the beginning of Junagadh''s written history. The same rock carries Sanskrit inscriptions by Rudradaman I (c. 150 CE) and Skandagupta (c. 450 CE), protected in a pavilion built in 1900.', '30-45 minutes', 'October to March', 'Read the information boards - they explain the Brahmi inscriptions in plain English.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'INR 25 per person (reported by visitors)', 4, 4, 21.525081, 70.479463, 'Bhavnath Taleti Rd, Tabudi Vav, Mullawada, Junagadh, Gujarat 362002', NULL, 0.8);

