INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3320028, 332, 332008, 'Bhavnath Maha Shivratri Fair', 'February-March', 'A five-day fair at the Bhavnath Mahadev Temple culminating on Maha Shivratri night, when Naga sadhus process with elephants, drums and conch shells and take a holy bath in the Mrigi Kund. One of Gujarat''s greatest religious gatherings.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3320029, 332, 332008, 'Girnar Lili Parikrama', 'October-November', 'A five-day circumambulation of the Girnar hills (about 36 km) held around Kartik Purnima, starting from the Bhavnath temple. Thousands of pilgrims, sadhus and travellers walk the parikrama path.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3320030, 332, 332008, 'Damodar Kund Bhadarvi Amavasya Fair', 'August-September', 'A large fair held at the sacred Damodar Kund lake on Bhadrapada Amavasya (no-moon day), drawing devotees for holy dips and religious rituals at the Girnar foothills.');

