INSERT OR IGNORE INTO cities (id, state_id, city_name, latitude, longitude) VALUES (332009, 332, 'Porbandar', 21.63, 69.6);

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000209, 332009, 'Kirti Mandir', 'Kirti Mandir (Mahatma Gandhi Birthplace Memorial)', 'The birthplace memorial of Mahatma Gandhi, born in this ancestral home of the Karamchand Gandhi family on 2 October 1869. The present three-storey memorial, built in 1950, houses life-size statues of Gandhi, rare photographs of his life and personal memorabilia, making it Porbandar''s most visited heritage site.', '1-1.5 hours', 'Morning; October to March', 'Combine with Sudama Temple and the Darbargadh Fort ruins, all within a short walk of each other.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 5, 5, 21.641361, 69.600907, 'Kirti Mandir Road, MG Road, Porbandar, Gujarat 360575', NULL, 1.0);

