INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000210, 332009, 'Sudama Temple', 'Sudama Temple (World''s Only Sudama Temple)', 'The only temple in the world dedicated to Sudama, Lord Krishna''s childhood friend from the Mahabharata. Built between 1902 and 1907 by Shri Ram Devji Jethwa and renovated by Bhavsinhji Maharaja, this white-marble shrine has a mirror-tiled maze (Lakh Chaurasi), intricate pillars and murals depicting Krishna washing Sudama''s feet.', '45-60 minutes', 'Morning; October to March', 'Look for the mural of Krishna washing Sudama''s feet — it is the temple''s signature artwork.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 5, 4, 21.6425, 69.6097, 'Sudama Chowk, Porbandar, Gujarat 360575', NULL, 0.92);

