INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000211, 332009, 'Porbandar Bird Sanctuary', 'Porbandar Bird Sanctuary', 'India''s smallest bird sanctuary (established 1988; managed by the Gujarat Forest Department from 1990), sitting opposite Kamla Nehru Park on Chhaya Road. Its small lakes and wetlands host flamingos, pelicans and around 150 resident and migratory bird species in winter — best from November to February.', '1-2 hours', 'November to February, early morning', 'Bring binoculars — winter mornings bring the most migratory birds.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 4, 4, 21.637296, 69.618215, 'Chhaya Road, opposite Kamla Nehru Park, Porbandar, Gujarat 360575', NULL, 0.8);

