INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000212, 332009, 'Chowpatty Beach', 'Chowpatty Beach', 'Porbandar''s long sandy city beach along Marine Drive, with seating areas, a skating rink and a pedestrian walkway. It is the city''s best sunset spot and its Chowpati ground hosts the annual Janmashtami fair.', '1-2 hours', 'Sunset; October to March', 'Come at sunset — the promenade fills with locals and the views over the Arabian Sea are the best in the city.', NULL, 'Gujarat', 0, 1, NULL, NULL, 'Free', 4, 4, 21.6315, 69.6145, 'Marine Drive, Chowpatty, Porbandar, Gujarat 360575', NULL, 0.8);

