INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000213, 332009, 'Bharat Mandir', 'Bharat Mandir (Temple of India)', 'The ''Temple of India'' at Khapat, New Porbandar, opposite Tara Mandir. Its floor carries a relief map of India, and its carved pillars and statues honour India''s freedom fighters — a quick, unusual patriotic stop.', '30-45 minutes', 'Morning; combine with Tara Mandir across the road', 'Visit together with Tara Mandir — the two stand directly opposite each other.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Rs 4', 3, 3, 21.656135, 69.617607, 'Khapat, New Porbandar, opposite Tara Mandir, Porbandar, Gujarat 360575', NULL, 0.6);

