INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000214, 332009, 'Tara Mandir', 'Tara Mandir (Nehru Planetarium)', 'Porbandar''s planetarium (established 1977), dedicated to the Non-Cooperation Movement and funded by a donation from philanthropist Nanjibhai Mehta. It screens astronomy shows in Gujarati, Hindi and English, and sits opposite Bharat Mandir at Khapat, New Porbandar.', '1 hour', 'Late afternoon show (4:00-7:00 PM)', 'Shows run in Gujarati, Hindi and English — ask at the counter for the English showtime.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Rs 20 (adult) / Rs 10 (child)', 3, 4, 21.654956, 69.617471, 'Khapat, New Porbandar, opposite Bharat Mandir, Porbandar, Gujarat 360575', NULL, 0.68);

