INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000215, 332009, 'Huzoor Palace', 'Huzoor Palace (Raj Mahal)', 'The early-20th-century palace of Rana Natwarsinhji, Porbandar''s last maharaja, built in European neo-classical style at the terminal end of Marine Drive. It remains the royal residence, so tourists are not allowed inside — it is admired from the outside, where its grounds are opened to the public during Navratri for the traditional nazar viewing of the royal family.', '20-30 minutes (exterior viewing)', 'Evening, along the Marine Drive walk', 'Exterior viewing only — combine with a Marine Drive sunset walk.', NULL, 'Gujarat', 0, 1, NULL, NULL, 'Free', 3, 3, 21.628, 69.613, 'Marine Drive, Porbandar, Gujarat 360575', NULL, 0.6);

