INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000216, 332009, 'Darbargadh Fort and Sartanji Choro', 'Darbargadh Fort & Sartanji Choro', 'The remnants of the Jethwa royal citadel built under Rana Sartanji (reign 1757-1813; one source dates the work to 1784): a carved stone gateway, four gates and three baris (wells), plus the three-storey Rajput summer pavilion of Sartanji Choro whose pillars are carved with musicians — right next to Sudama Temple.', '30-45 minutes', 'Morning, combined with Sudama Temple', 'The carved musicians on the pavilion pillars are the highlight; view from the lane beside Sudama Temple.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 3, 3, 21.6418, 69.609, 'Sudama Puri, Bhatia Bazar, Old Porbandar, Porbandar, Gujarat 360575', NULL, 0.6);

