INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000217, 332009, 'Shri Hari Mandir, Sandipani Vidyaniketan', 'Shri Hari Mandir (Sandipani)', 'A white-marble temple managed by Rameshbhai Oza within the Sandipani Vidyaniketan complex, opposite Porbandar Airport. Its highlight is the 7:00 PM Sandhya Aarti, when 150+ Rishi Kumars (students) chant together — one of the city''s most atmospheric spiritual experiences.', '45-60 minutes', 'Evening, around the 7:00 PM Sandhya Aarti', 'Arrive by 6:30 PM to be seated for the 7:00 PM Sandhya Aarti with the Rishi Kumars.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 4, 4, 21.63514, 69.67143, 'Maharshi Sandipani Marg, opposite Porbandar Airport, Raghavav, Porbandar, Gujarat 360560', NULL, 0.8);

