INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000218, 332009, 'Ramdhun Temple', 'Ramdhun Temple', 'A temple at Panch Hatdi inspired by Prem Bhikshuji Maharaj, famous for its non-stop, round-the-clock chanting of the Ramdhun — one of Porbandar''s most distinctive spiritual experiences, running day and night.', '30 minutes', 'Any time; evenings are liveliest', 'Drop in late evening when the chanting is at its most intense.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 4, 4, 21.6429, 69.607464, 'Panch Hatdi, Porbandar, Gujarat 360575', NULL, 0.8);

