INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000223, 332009, 'Madhavpur Beach', 'Madhavpur Beach (day trip)', 'A long, relatively quiet beach about 60 km southeast of Porbandar on NH-51 at Madhavpur Ghed, part of the wider Madhavpur coastal stretch on the Arabian Sea. Good for a relaxed seaside stop, with the Madhavrai Temple and the Madhavpur Mela grounds nearby; best from October to March.', '2-3 hours (half day with the temple)', 'October to March; late afternoon for sunset', 'Few facilities on the beach — carry water and snacks, and combine with Madhavrai Temple.', NULL, 'Gujarat', 0, 1, NULL, NULL, 'Free', 3, 4, 21.27982, 69.9354, 'Madhavpur, NH-51, Porbandar, Gujarat 362230', NULL, 0.68);

