INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000224, 332009, 'Madhavrai Temple', 'Madhavrai Temple, Madhavpur (day trip)', 'A 13th-century temple of Krishna as Madhavrai at Madhavpur Ghed (~60 km from Porbandar), marking the legendary site of Krishna and Rukmini''s wedding. The current structure was rebuilt by Shri Rupaniba, Queen of Porbandar, in 1840 beside the old ruins; the five-day Madhavpur Mela (March-April, from Ram Navami) commemorates the wedding here.', '1 hour', 'Morning; during the Madhavpur Mela (March-April)', 'Time your visit for the Madhavpur Mela if possible — the temple fair transforms the village.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 4, 4, 21.299291, 70.025139, 'Madhavpur (Ghed), Porbandar, Gujarat 362230', NULL, 0.8);

