INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 332000224, 'insert', 'bulk', '13th-century Madhavrai (Krishna) temple at Madhavpur Ghed, Krishna-Rukmini wedding legend, rebuilt 1840 by Shri Rupaniba per Wikipedia''s Madhavpur Ghed article; village coordinates 21.2993, 70.0251 from Wikipedia — pin is the village center, approximate within ~1 km. Distance from Porbandar noted in summary.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000225, 332009, 'Navlakha Temple, Ghumli', 'Navlakha Temple, Ghumli (day trip)', 'An 11th-century Sun temple built by Jethwa rulers at Ghumli (~45 km from Porbandar) — Gujarat''s oldest Sun temple, with the largest temple base in the state (45.72 x 30.48 m). Named ''Navlakha'' for its Rs 9 lakh construction cost, it is built in Maru-Gurjara (Solanki) style with the signature three entwining elephant tusks; a Ganesha shrine (Ganesh Dehra) stands outside, and the ASI took up restoration in 2011.', '1-2 hours', 'Morning; October to March', 'Pair with Bileshwar Shiva Temple nearby — the two make one full day trip.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 4, 4, 21.90403, 69.75758, 'Ghumli, Bhanvad, Devbhoomi Dwarka, Gujarat 360510', NULL, 0.8);

