INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000226, 332009, 'Bileshwar Shiva Temple', 'Bileshwar Shiva Temple (day trip)', 'An 11th-century Shiva temple near Ghumli in Ranavav taluka (~50 km from Porbandar), dating to the Solanki era, set in a quiet rural landscape. It is usually paired with the Navlakha Temple visit as the second stop of the Ghumli day trip.', '45-60 minutes', 'Morning, with the Navlakha Temple', 'Combine with Navlakha Temple at Ghumli — the two are a natural pair.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 3, 3, 21.7812, 69.77737, 'Bileshwar, Ranavav, Porbandar, Gujarat 360550', NULL, 0.6);

