INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000227, 332009, 'Dwarkadhish Temple, Dwarka', 'Dwarkadhish Temple, Dwarka (day trip)', 'One of the Char Dham pilgrimage sites, about 105 km from Porbandar in Dwarka on the banks of the Gomti river: a five-storey Maru-Gurjara temple of Krishna as Dwarkadhish, with a 78 m spire and 72 pillars; the present structure dates to the 15th-16th century. It is the natural long day trip from Porbandar for pilgrims.', 'Full day (2-3 hours at the temple + travel)', 'October to March; morning darshan 6:00-9:00 AM', 'Note the two daily darshan windows — plan to arrive well before the 1:00 PM closing of the morning session.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 5, 5, 22.2378861, 68.9675611, 'Dwarka, Devbhoomi Dwarka, Gujarat 361335', 'https://www.dwarkadhish.org', 1.0);

