INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000228, 332009, 'Barda Wildlife Sanctuary', 'Barda Wildlife Sanctuary (day trip)', 'About 15 km from Porbandar in the Barda Hills: a 192.31 sq km sanctuary being developed as the second home of the Asiatic lion under the Gir-Barda Project (1979) — a male lion recolonized it naturally in 2023. It also shelters leopards, wolves, chinkara, hyenas, nilgai and rich birdlife, and was once the private hunting ground of the Jamnagar and Porbandar royals.', 'Half day to full day', 'October to March', 'Check permit/entry requirements with the forest department in advance — it is a working wildlife sanctuary, not a casual park.', 'Check forest department entry requirements in advance', 'Gujarat', 0, 0, NULL, NULL, NULL, 4, 4, 21.78659, 69.72404, 'Barda Hills, Ranavav, Porbandar, Gujarat 360545', NULL, 0.8);

