INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3320031, 332, 332009, 'Janmashtami', 'August-September', 'Krishna''s birthday is celebrated at Sudama Temple and Dwarka-side shrines, and the Chowpati ground at Chowpatty Beach hosts Porbandar''s annual Janmashtami fair.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3320032, 332, 332009, 'Navratri', 'September-October', 'The nine-night festival is celebrated across the city; the Huzoor Palace grounds are opened to the public during Navratri for the traditional nazar (viewing) of the royal family.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3320033, 332, 332009, 'Madhavpur Mela', 'March-April', 'A five-day fair held at Madhavpur Ghed (~60 km, Porbandar district) starting on Ram Navami, commemorating the wedding of Krishna and Rukmini at the Madhavrai Temple, with folk performances from Gujarat and North-Eastern states under the Ek Bharat Shreshtha Bharat initiative.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3320034, 332, 332009, 'Gandhi Jayanti', 'October', '2 October marks Mahatma Gandhi''s birth anniversary with special ceremonies at Kirti Mandir, his birthplace memorial.');

