INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000235, 332010, 'Rani ki Vav', 'Rani ki Vav (Queen''s Stepwell), Patan', 'The crown jewel of Patan and a UNESCO World Heritage Site (2014) - an 11th-century stepwell built in 1063 by Queen Udayamati in memory of her husband King Bhimdev I of the Chaulukya dynasty. Descending seven stories into the earth, its walls are carved with more than 500 principal sculptures of gods, apsaras and ornamental motifs, making it the finest and most ornate stepwell in India.', '2-3 hours', 'October to March; mornings before 11 AM for the best light on the sculptures', 'Enter the lowest levels - the finest Vishnu Dashavatar panels are at the deepest gallery; carry water as the site has little shade', 0, 'Gujarat', 0, 0, NULL, NULL, 'Rs 40', 5, 5, 23.858968, 72.101928, 'Rani ki Vav Road, Patan, Gujarat 384265', NULL, 1.0);

