INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000236, 332010, 'Rani ki Vav 3D Projection Mapping Show', 'Rani ki Vav 3D Projection Mapping Show', 'An evening 3D projection-mapping (light and sound) show staged at Rani ki Vav that projects the story of the stepwell, its builders and its sculptures onto the vav''s walls after dark. Run per the Gujarat Tourism schedule in two slots each evening.', '30-45 minutes', 'Year-round; slots run after sunset', 'Arrive 15-20 minutes before your slot; the 7:30 PM show has better viewing as it is less crowded than the second', 0, 'Gujarat', 0, 0, NULL, NULL, NULL, 4, 5, 23.858968, 72.101928, 'Rani ki Vav, Patan, Gujarat 384265', NULL, 0.88);

