INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000237, 332010, 'Sahastralinga Talav', 'Sahastralinga Talav, Patan', 'A vast 12th-century artificial lake built by the Chaulukya king Jayasimha Siddharaja (reigned 1093-1143), covering about 5 sq km and once fed by the Saraswati river. Its ruins - terraces, shrines and inlets - were excavated in 1936, revealing the ''bakasthana'' mound; a peaceful sunset spot on Patan''s west side.', '1-2 hours', 'October to March; late afternoon for sunset over the water', 'Combine with Rani ki Vav in one half-day - they are under 3 km apart; the lake is prettiest around sunset', 0, 'Gujarat', 0, 1, NULL, NULL, NULL, 4, 4, 23.85042, 72.11491, 'SH-10, Chidiya Darwaza-Meghan Bazar, Patan, Gujarat 384265', NULL, 0.8);

