INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000238, 332010, 'Patan Patola Heritage Museum', 'Patan Patola Heritage Museum', 'Patan''s heritage museum of its world-famous Patola silk, maintained by the Salvi family - the traditional weavers of the double-ikat Patola sari, a craft practised in Patan for over 800 years. See looms in action, a single sari taking 4-6 months to weave, and displays on the dyeing and tying process.', '1-2 hours', 'October to March; any time during opening hours', 'Ask to see the weaving demonstration and the family tree of the Salvi weavers - the resident artisans happily explain the double-ikat process', 0, 'Gujarat', 0, 0, NULL, NULL, 'Rs 10', 4, 4, 23.85574, 72.1073, 'Kalika Road, Patola House, Opp. New Kalika Mandir, Patan, Gujarat 384265', NULL, 0.8);

