INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 332000238, 'insert', 'bulk', 'Hours 10 AM-6 PM from Gujarat Tourism''s museum page; entry fee Rs 10 from trawell.in, though travelsetu.com lists free entry - noted in cost_source. The Salvi family of Patan are the documented hereditary Patola weavers. No dedicated official website found, so official_website is null.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000239, 332010, 'Panchasara Parshwanath Jain Derasar', 'Panchasara Parshwanath Jain Derasar, Patan', 'One of Patan''s oldest and most revered Jain temples, dedicated to Parshwanath, in the Panchasara quarter - the original settlement from which Patan grew. The derasar was renovated by the minister Vastupal in 1240 and remains an active Svetambara pilgrimage stop with fine marble carving.', '45-60 minutes', 'October to March; morning darshan hours', 'Dress modestly and remove leather items before entering, per Jain temple custom; photography is usually restricted inside the sanctum', 0, 'Gujarat', 0, 0, NULL, NULL, NULL, 3, 4, 23.85393, 72.11704, 'Panchasara, Patan, Gujarat 384265', NULL, 0.68);

