INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000240, 332010, 'Khan Sarovar', 'Khan Sarovar, Patan', 'A large historic lake on Patan''s southern edge, a quiet local spot for an evening walk with views across the water. A low-key contrast to the monument-heavy sightseeing circuit.', '30-60 minutes', 'October to March; late afternoon to sunset', 'Good sunset photography spot; pair with an evening visit after the museums close', 0, 'Gujarat', 0, 1, NULL, NULL, NULL, 2, 3, 23.84252, 72.11156, 'Khan Sarovar, Patan, Gujarat 384265', NULL, 0.48);

