INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000246, 332010, 'Modhera Sun Temple', 'Sun Temple, Modhera', 'DAY TRIP from Patan (~35 km): the 11th-century Sun Temple built by Bhimdev I (1026-27), one of India''s great surviving sun temples. The east-facing sanctum, the ornate sabha mandapa and the stepped Surya Kund tank with 108 shrines make it a half-day essential; it hosts the January dance festival.', '2-3 hours (half-day trip from Patan)', 'October to March; early morning for sunrise light on the sanctum', 'Walk down into the Surya Kund tank for the classic photograph; a sound-and-light show runs in the evening after closing hours', 0, 'Gujarat', 1, 0, NULL, NULL, 'Rs 25', 5, 4, 23.58319, 72.13351, 'Modhera, Gujarat 384212', NULL, 0.92);

