INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000247, 332010, 'Vadnagar Archaeological Experiential Museum', 'Vadnagar Archaeological Experiential Museum', 'DAY TRIP from Patan (~60 km): India''s first experiential archaeological museum, opened to the public in February 2025, tracing 2,500 years of Vadnagar''s continuous habitation - the town associated with Alexander, Buddhism and the Solankis. Pair it with the 12th-century Kirti Torana arches, 17th-century Hatkeshwar Mahadev temple and Sharmishtha Lake.', '2-3 hours at the museum; full-day trip with Vadnagar sights', 'October to March', 'Buy tickets on arrival; the museum''s 9 galleries take a full 2 hours - see the Kirti Torana arches (10 min away) in the same trip', 0, 'Gujarat', 0, 0, NULL, NULL, 'Rs 150', 4, 4, 23.78522, 72.64504, 'Vadnagar, Gujarat 384355', NULL, 0.8);

