INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000248, 332010, 'Rudra Mahalaya Ruins', 'Rudra Mahalaya Ruins, Siddhpur', 'DAY TRIP from Patan (~30 km): the dramatic ruins of the Rudra Mahalaya - a 12th-century Chaulukya Shiva temple complex begun in 943 CE and completed in 1140, later destroyed in 1296 and 1414. Two towering torans (porches) and a mosque portion survive as an ASI-protected monument.', '1-2 hours; half-day trip with Siddhpur', 'October to March; morning or late afternoon', 'Combine with Bindu Sarovar and a walk past Siddhpur''s Bohra havelis with their carved wooden facades', 0, 'Gujarat', 0, 0, NULL, NULL, NULL, 4, 3, 23.91917, 72.37917, 'Siddhpur, Gujarat 384151', NULL, 0.72);

