INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000249, 332010, 'Bindu Sarovar', 'Bindu Sarovar, Siddhpur', 'DAY TRIP from Patan (~28 km): one of Hinduism''s five sacred sarovars and the ''Matru Gaya'' - the holy site for matru-shraddha (rites for mothers), mentioned in the Rig Veda. A serene stepped tank ringed by small shrines, central to Siddhpur''s religious life.', '45-60 minutes; half-day trip with Siddhpur', 'October to March; early morning', 'Visit the same morning as the Rudra Mahalaya ruins; the sarovar is most atmospheric just after sunrise', 0, 'Gujarat', 0, 0, NULL, NULL, NULL, 3, 3, 23.90887, 72.363522, 'Siddhpur, Gujarat 384151', NULL, 0.6);

