INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000250, 332010, 'Bahucharaji Temple', 'Bahucharaji Temple, Becharaji', 'DAY TRIP from Patan (~45 km): the temple of Bahucharaji Mata, kuldevi of the transgender community and a major Shakti shrine of North Gujarat, built in 1839 by the Gaikwad Sarkar. Lively fairs are held on Chaitra and Ashadhi Purnima.', '1-2 hours; half-day trip from Patan', 'October to March; morning darshan', 'The temple town gets crowded on Purnima days - visit on a weekday for a calmer darshan', 0, 'Gujarat', 0, 0, NULL, NULL, NULL, 3, 3, 23.49936, 72.04679, 'Becharaji, Gujarat 384210', NULL, 0.6);

