INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000251, 332010, 'Taranga Jain Temples', 'Taranga Jain Temples (Taranga Hill)', 'DAY TRIP from Patan (~65 km): a major Jain pilgrimage center on Taranga Hill, with 14 Svetambara and 5 Digambara temples in the Maru-Gurjara style. The Ajitnath temple was built in 1161 by the Chaulukya king Kumarapala under Acharya Hemachandra; Kartik and Chaitra full moons draw big pilgrimages.', '3-4 hours; half to full-day trip from Patan', 'October to March; morning for the hill climb', 'The hilltop shrines involve a climb - start early, carry water, and allow 3+ hours; sunrises from the hill are well regarded', 0, 'Gujarat', 1, 0, NULL, NULL, NULL, 4, 4, 23.96639, 72.75472, 'Taranga, Mehsana, Gujarat 384325', NULL, 0.8);

