INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000252, 332010, 'Umiya Mata Temple', 'Umiya Mata Temple, Unjha', 'DAY TRIP from Patan (~26 km): the principal temple of Umiya Mata, kuldevi of the Kadva Patidar community, in the market town of Unjha - famous for its cumin and spice market. An easy, short excursion from Patan.', '1-2 hours; half-day trip from Patan', 'October to March; morning or evening', 'Combine with a stroll through Unjha''s famous spice market - one of Asia''s largest cumin markets', 0, 'Gujarat', 0, 0, NULL, NULL, 'Free', 3, 3, 23.79923, 72.38277, 'Unjha, Gujarat 384170', NULL, 0.6);

