INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000253, 332010, 'Shankheshwar Jain Temple', 'Shankheshwar Jain Temple (Shankheshwar Parshwanath)', 'DAY TRIP from Patan (~57 km): one of Jainism''s most important pilgrimage sites - the Shankheshwar Parshwanath temple on the banks of the Rupen river, founded in 1098 CE (1155 VS). The present marble temple with its 41-meter shikhara draws lakhs of devotees, especially on Purnima.', '2-3 hours; half-day trip from Patan', 'October to March; morning darshan', 'Purnima days are very crowded - book any stay in advance and arrive early; the riverbank setting is pleasant at dusk', 0, 'Gujarat', 0, 0, NULL, NULL, NULL, 4, 4, 23.508139, 71.787667, 'Shankheshwar, Gujarat 384246', NULL, 0.8);

