INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000254, 332010, 'Ambaji Temple', 'Ambaji Temple (Arasuri Ambaji Mata), Banaskantha', 'DAY TRIP from Patan (~90 km): one of the 51 Shakti Peethas, where Goddess Sati''s heart is believed to have fallen. Uniquely, there is no idol - devotees worship the gold-plated Shri Visa Yantra in the sanctum. Managed by the Shri Arasuri Ambaji Mata Devasthan Trust; pair with the Gabbar Hill ropeway.', '2-3 hours; full-day trip from Patan', 'October to March; avoid Bhadarvi Poonam week unless attending the fair', 'Take the ropeway up Gabbar Hill (4 km from the main temple) for panoramic views; the Gabbar light-and-sound show was temporarily suspended as of mid-2026 - check the official site', 0, 'Gujarat', 0, 0, NULL, NULL, 'Free', 4, 4, 24.335853, 72.850249, 'Ambaji, Danta Taluka, Banaskantha, Gujarat 385110', 'http://www.ambajitemple.in/', 0.8);

