INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3320035, 332, 332010, 'Uttarardha Mahotsav (Modhera Dance Festival)', 'January (3rd week)', 'Three-day classical dance festival organized by Gujarat Tourism on the temple premises during the third week of January, following Uttarayan. Dancers from across India perform against the illuminated 11th-century Sun Temple backdrop.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3320036, 332, 332010, 'Bhadarvi Poonam Mela, Ambaji', 'August-September (Bhadrapada Purnima)', 'The biggest fair at the Ambaji Shakti Peeth on the full moon of Bhadrapada; millions of devotees, many walking as foot pilgrims, visit the shrine and Gabbar Hill during the festive period.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3320037, 332, 332010, 'Taranga Kartik and Chaitra Purnima Melas', 'November & April (Kartik & Chaitra Purnima)', 'The two main annual full-moon pilgrimages at the Taranga Jain temples, drawing large Jain congregations to the 12th-century Ajitnath temple complex.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3320038, 332, 332010, 'Bahucharaji Fairs', 'April & July (Chaitra & Ashadhi Purnima)', 'Traditional annual fairs at the Bahucharaji Mata temple on the full moons of Chaitra and Ashadh, attracting devotees from across North Gujarat.');

