INSERT OR IGNORE INTO cities (id, state_id, city_name, latitude, longitude) VALUES (332011, 332, 'Bharuch', 21.7, 72.97);

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000261, 332011, 'Golden Bridge', 'Golden Bridge (Narmada Bridge)', 'The 1,412-metre iron Golden Bridge spans the Narmada between Bharuch and Ankleshwar. Built by the British and completed on 16 May 1881 for the Bombay, Baroda and Central India Railway at a cost of Rs 45.65 lakh, it was originally called the Narmada Bridge and earned its ''golden'' name from the huge expenditure incurred. It served the Mumbai-Ahmedabad highway for 140 years and remains an iconic heritage landmark of the city.', '30-45 minutes', 'October to February; early morning or sunset for the best river views', 'View it from the Narmada riverfront viewpoints; heavy through-traffic has been restricted since the new bridge opened, so expect a quieter heritage crossing.', NULL, 'Gujarat', 0, 1, NULL, NULL, NULL, 5, 4, 21.693255, 73.004936, 'Across the Narmada River between Bharuch and Ankleshwar, Gujarat', NULL, 0.92);

