INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000262, 332011, 'Narmada Park', 'Narmada Park', 'Narmada Park is a public riverside park in Bharuch set on the banks of the Narmada River. It offers landscaped greenery, evening walks, boating and picnic spots with wide views of the river. It is a popular family outing spot for locals and visitors alike.', '1-2 hours', 'October to February; evenings for the river breeze', 'Come in the evening for the river breeze and sunset; carry drinking water and confirm boating availability locally.', NULL, 'Gujarat', 0, 1, NULL, NULL, NULL, 3, 3, 21.7221, 73.03792, 'Service Road, Ganesh Shrishti, Vadadla, Bharuch 392011, Gujarat', NULL, 0.6);

