INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000263, 332011, 'Bhrigu Rishi Temple', 'Bhrigu Rishi Temple', 'One of Gujarat''s most sacred temples, the Bhrigu Rishi Temple stands on the east of Bharuch in the Dandia Bazar area on the banks of the Narmada. Bharuch was originally called ''Bhrigukachchha'' after this temple, honouring Maharishi Bhrigu, who is credited with the first Indian astrological work, the Bhrigu Samhita. It draws pilgrims from across India and abroad.', '45 minutes - 1 hour', 'October to February; early morning for aarti', 'Pair the visit with nearby Dashashwamedh Ghat on the same morning walk.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 5, 4, 21.69818, 72.99456, 'Dandia Bazar, Old Town, Bharuch 392001, Gujarat', NULL, 0.92);

