INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000264, 332011, 'Jama Masjid', 'Jama Masjid', 'Bharuch''s historic Jama Masjid is an old Islamic monument in the Lal Bazar area of the old town, near the base of the hill that carries Lallubhai Haveli. It is counted among the city''s noted Islamic buildings alongside the 1326 Eidgah and the Madresa Mosque, reflecting Bharuch''s centuries of Sultanate and Mughal-era history.', '30 minutes', 'October to February; daytime', 'Dress modestly and avoid prayer times; combine with an old-town walk.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 3, 3, 21.69193, 72.98199, 'Lal Bazar, Old Town, Bharuch 392001, Gujarat', NULL, 0.6);

