INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000265, 332011, 'Dashashwamedh Ghat', 'Dashashwamedh Ghat', 'Dashashwamedh Ghat sits on the Narmada bank near Dandia Bazar and is one of Bharuch''s holiest spots. Legend says King Mahabali performed ten ashwamedha sacrifices here and that Lord Vishnu, in the disguise of Vamana, measured the universe here. The ghat hosts old temples including Ambaji Mata, Umiya Mata, Narmada Mata, Kotirudreshwar Mahadev and Vamana temples.', '45 minutes - 1 hour', 'Early morning, year-round', 'Visit at early morning hours for the most peaceful spiritual experience, as the district tourism page recommends.', NULL, 'Gujarat', 1, 0, NULL, NULL, NULL, 4, 4, 21.697, 73.001, 'Narmada riverbank near Dandia Bazar, Bharuch 392001, Gujarat', NULL, 0.8);

