INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000266, 332011, 'Bharuch Fort', 'Bharuch Fort', 'Bharuch''s roughly 1,000-year-old fort, attributed to Solanki king Siddhraj Jaysinh, stands on a hilltop overlooking the Narmada. Within its walls are the Collector''s office, Civil Courts, the old Dutch factory, a church and the Victoria Clock Tower. About 3 km away lie early Dutch tombs and Parsee Towers of Silence, along with other monuments built by the Dutch, Portuguese and British.', '1-2 hours', 'October to February; daytime', 'Walk the old-town approach up to the hilltop for the river view; ask locally about access to the Dutch tombs.', NULL, 'Gujarat', 0, 1, NULL, NULL, NULL, 4, 4, 21.69129, 72.97956, 'Old Town (fort hill), Bharuch 392001, Gujarat', NULL, 0.8);

