INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000267, 332011, 'Gurudwara Chadar Saheb', 'Gurudwara Chadar Saheb', 'Gurudwara Chadar Saheb in the Kasak/Maktampur area marks Guru Nanak Dev''s 15th-century visit to Bharuch. Legend says that when a boatman refused him passage across the Narmada, the Guru crossed over on his cloth sheet (chadar). The gurudwara was later built on the site where he landed.', '30-45 minutes', 'October to February; daytime', 'Cover your head and remove shoes before entering, as at any gurudwara.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 3, 3, 21.7015, 73.00233, 'Maktampur, Bharuch 393010, Gujarat', NULL, 0.6);

