INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000268, 332011, 'Lallubhai Haveli', 'Lallubhai Haveli', 'The Lallubhai Haveli is an 18th-century mansion in old Bharuch erected in 1791 AD by Lallubhai, an ex-diwan of the last Nawab of Bharuch. The one-storeyed building (with one second-floor room) is noted for richly carved woodwork, matchlock-gun placements and underground passages, and stands on a hilltop above the Narmada with the Jama Masjid at its base.', '30-45 minutes', 'October to February; daytime', 'Admire the carved woodwork from outside; check locally whether the interiors are open to visitors.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 3, 3, 21.69486, 72.98624, 'Lallubhai Chakla, Old Town, Bharuch 392001, Gujarat', NULL, 0.6);

