INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000269, 332011, 'BAPS Shri Swaminarayan Mandir (Zadeshwar)', 'BAPS Shri Swaminarayan Mandir, Zadeshwar', 'The BAPS Shri Swaminarayan Mandir on the Zadeshwar side of Bharuch (on NH-8) is known for its intricate traditional carvings and serene atmosphere. The district tourism page notes it draws huge numbers of devotees from Bharuch and nearby areas. Bharuch''s older Swaminarayan Temple in Dandia Bazar is about 175 years old.', '45 minutes - 1 hour', 'October to February; morning or evening aarti hours', 'Visit during morning or evening aarti for the full experience.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 4, 4, 21.72571, 73.03249, 'Zadeshwar, NH-8, Bharuch 392012, Gujarat', NULL, 0.8);

