INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000270, 332011, 'Narmada Mata Temple', 'Narmada Mata Temple', 'The 150-year-old Narmada Mata Temple in the Dandia Bazar area is dedicated to Goddess Narmada herself. It stands close to the Bhrigu Rishi Temple and Dashashwamedh Ghat, making the Dandia Bazar riverbank a compact pilgrimage circuit.', '30 minutes', 'October to February; morning', 'Combine with the Bhrigu Rishi Temple and Dashashwamedh Ghat on the same walk.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 3, 3, 21.6981, 72.9966, 'Dandia Bazar, Old Town, Bharuch 392001, Gujarat', NULL, 0.6);

