INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000272, 332011, 'Katopore Bazar', 'Katopore Bazar', 'Katopore Bazar is Bharuch''s crowded but fascinating traditional bazaar in the old town. It is the place to browse everyday Gujarati shopping — textiles, household goods and street snacks — amid the city''s old commercial lanes.', '1-2 hours', 'October to February; mornings or late afternoons', 'Go in the morning or late afternoon; bargain politely.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 3, 3, 21.69418, 72.98056, 'Katopor Bazar Road, Old Town, Bharuch 392001, Gujarat', NULL, 0.6);

