INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000273, 332011, 'Raichand Deepchand Library', 'Raichand Deepchand Library', 'Bharuch hosts one of Gujarat''s oldest libraries: the Raichand Deepchand Library, started in 1858, with a collection of around 200,000 (two lakh) books. It is a quiet heritage stop for book lovers in the old town.', '30-45 minutes', 'Weekday daytime', 'Check locally for visitor and reading-room access.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 2, 3, 21.69135, 72.97919, 'Old Town, Bharuch 392001, Gujarat', NULL, 0.48);

