INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000274, 332011, 'Nav Nathas', 'Nav Nathas (Nine Swayambhu Shivalingas)', 'The Nav Nathas are nine swayambhu (self-manifested) Shivalingas scattered across old Bharuch: Kamnath, Jwalnath, Somnath, Bhimnath, Gangnath, Bhootnath, Pingalnath, Siddhnath and Kashi Vishwanath. Tradition says they have existed since time immemorial and that it was because of them that Bhrigu Rishi chose Bharuch for his ashram. Visiting them makes a ready-made old-city temple trail.', '2-3 hours (trail)', 'October to February; mornings', 'Ask a local for the visiting sequence; the shrines are small neighbourhood temples.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 3, 4, 21.695, 72.983, 'Various locations across Old Town, Bharuch 392001, Gujarat', NULL, 0.68);

