INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000275, 332011, 'Kabirvad', 'Kabirvad', 'Kabirvad is a river island in the Narmada about 16 km east of Bharuch, reached by boat from the Shuklatirth side. Its giant banyan grove — associated with the 15th-century mystic-poet Kabir, who is said to have meditated here — covers more than 2.5 acres (canopy about 17,520 sq m) with thousands of trunks. The island also has a Kabir temple, a lotus-shaped marble temple, a Kabir museum and Narmada boat rides.', 'Half day (3-4 hours including boat ride)', 'October to February; clear mornings', 'Boats run from the Shuklatirth/Kabirmadhi side; carry water and snacks as the island has limited facilities.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 5, 5, 21.7633869, 73.140089, 'Kabirvad river island, Narmada River, Bharuch district, Gujarat (boat from Shuklatirth)', NULL, 1.0);

