INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000276, 332011, 'Shuklatirth', 'Shuklatirth', 'Shuklatirth is an ancient pilgrim village on the Narmada about 16-18 km east of Bharuch, on the way to Kabirvad. It hosts old temples including the Shukleshwar Mahadev Temple — linked to the legend of Chanakya''s liberation — and the Omkarnath Vishnu Mandir with its tall white self-manifested Vishnu idol. A five-day Kartik Purnima fair draws thousands here each year.', 'Half day', 'October to February; Kartik Purnima fair (Oct-Nov) is the liveliest time', 'Combine with Kabirvad in a single half-day trip.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 4, 4, 21.753667, 73.121511, 'Shuklatirth, Bharuch district, Gujarat 392030', NULL, 0.8);

