INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000277, 332011, 'Kadia Dungar Caves', 'Kadia Dungar Caves', 'About 40 km south of Bharuch near Zazpor village (Jhagadia taluka), the Kadia Dungar hill holds seven rock-cut caves carved in the 1st-2nd century AD, with vihara-style architecture, monolithic lion pillars and a brick stupa at the foot of the hill. It is one of Gujarat''s oldest Buddhist sites and is also sacred to Jains.', 'Half day (2-3 hours)', 'October to February; just after the monsoon the hill is at its greenest', 'Carry food and water — there are no facilities at the site; beware of monkeys near the foothill ashram.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 4, 4, 21.673742, 73.272278, 'Kadia Dungar, near Zazpor village, Jhagadia taluka, Bharuch district, Gujarat', NULL, 0.8);

