INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000278, 332011, 'Gumandev Temple', 'Gumandev Temple', 'About 20 km south of Bharuch near Jhagadia, the very old Gumandev Temple is dedicated to Lord Hanuman and draws devotees from around the world. A fair is held here every Saturday in the month of Shravan, when devotees walk in from Bharuch and Ankleshwar.', 'Half day', 'Shravan Saturdays for the fair; otherwise October to February', 'Shravan Saturdays are festive but crowded — go early in the day.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 3, 3, 21.69705, 73.09454, 'SH-165, Jhagadia, Bharuch district, Gujarat 393001', NULL, 0.6);

