INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000279, 332011, 'Stambheshwar Mahadev', 'Stambheshwar Mahadev Temple', 'About 45 km from Bharuch at Kavi Kamboi (Jambusar), the Stambheshwar Mahadev Temple sits at the confluence of the Mahi River and the sea. Its 4-foot Shivalinga submerges during high tide and re-emerges at low tide, so darshan is only possible at low tide. Legend links the linga to Kartikeya, who installed it after slaying the demon Tarakasura.', 'Half day to full day (plan around tide timings)', 'October to February; plan strictly around low-tide timings', 'Check local tide timings before going — the temple is only accessible during low tide.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 5, 4, 22.2496, 72.5263, 'Kavi Kamboi, Jambusar, Bharuch district, Gujarat', NULL, 0.92);

