INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000280, 332011, 'Statue of Unity, Ekta Nagar', 'Statue of Unity', 'About 90 km east of Bharuch at Ekta Nagar (Kevadia), the 182-metre Statue of Unity — the world''s tallest statue — honours Sardar Vallabhbhai Patel and was inaugurated on 31 October 2018. The campus holds 20-30 attractions including the 153-metre viewing gallery, Valley of Flowers, Jungle Safari, the Sardar Sarovar Dam viewpoint, Ekta Cruise and the evening laser show.', 'Full day (2 days ideal)', 'October to February (best: November-December)', 'Arrive before 9 AM to beat the crowds; plan two days if you want the Jungle Safari and the evening laser show too.', 'Book tickets online in advance at soutickets.in; the Viewing Gallery frequently sells out 2-3 days ahead in peak season (October-February) and on weekends.', 'Gujarat', 0, 0, NULL, NULL, NULL, 5, 5, 21.838, 73.7191, 'Ekta Nagar (Kevadia), Narmada district, Gujarat 393151', 'https://www.soutickets.in', 1.0);

