INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000285, 332011, 'Skylight (Regenta Central)', 'Skylight (Regenta Central Harimangla)', 'Skylight is the multi-cuisine restaurant at Regenta Central Harimangla on Old NH-8, Bholav. As the hotel''s all-day dining venue it is the most upscale sit-down option on the Bharuch bypass, with buffet spreads and a la carte Indian, Chinese and continental dishes.', '1-1.5 hours', 'Lunch or dinner', 'The dependable premium option if you want hotel-style dining on the bypass.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 4, 4, 21.7252, 73.00693, 'Regenta Central Harimangla, Old NH-8, Bholav, Bharuch 392012, Gujarat', NULL, 0.8);

