INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3320039, 332, 332011, 'Meghraja Festival', 'August-September', 'Unique to Bharuch — celebrated nowhere else in India. A 5.5-foot idol of Meghraj (Lord Indra) is sculpted from Narmada river soil and worshipped for 25 days in the month of Shravan; a fair (mela) is organised during the last four days of the festival.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3320040, 332, 332011, 'Gumandev Shravan Fair', 'July-August', 'Every Saturday in the month of Shravan, a fair gathers at the Gumandev Hanuman temple near Jhagadia (about 20 km from Bharuch), with devotees walking in from Bharuch and Ankleshwar.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3320041, 332, 332011, 'Shuklatirth Kartik Purnima Fair', 'October-November', 'A five-day fair at the Shuklatirth temples on the Narmada (about 16-18 km from Bharuch) around Kartik Purnima, drawing thousands of devotees for holy dips and darshan.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3320042, 332, 332011, 'Ayyapa Mandala Pooja Procession', 'December', 'At the end of December, the Shree Vishnu Ayyapa Temple on Zadeshwar Road (managed by Bharuch''s Kerala community) takes out a festive procession marking the pious Mandalamaasam, with devotees from across the district joining in.');

