INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000287, 332012, 'Amul Dairy Museum (Dr. Verghese Kurien Memorial)', 'Amul Dairy Museum', 'Headquarters of the Kaira District Co-operative Milk Producers'' Union (Amul), the institution behind India''s White Revolution. The on-campus Dairy Museum, also known as Dr V. Kurien''s Museum (opened 26 November 2000), traces the cooperative''s story with a photo gallery, auditorium and documentaries. A guided walk through the butter and dry-milk plant is available for booked visitors.', '2-3 hours', 'November to February (cooler months, per Gujarat Tourism)', 'Book your slot in advance and carry a photo ID; photography is allowed in the museum but not inside the factory.', 'Prior online booking required via Amul''s visit-booking portal (booking link published on amuldairy.com)', 'Gujarat', 0, 0, NULL, NULL, 'Free', 5, 4, 22.5533, 72.9489, 'Amul Dairy Campus, Amul Dairy Road, Anand, Gujarat 388001', 'https://amuldairy.com', 0.92);

