INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000288, 332012, 'Amul Chocolate Factory, Mogar', 'Amul Chocolate Factory, Mogar', 'Amul''s chocolate plant at Mogar village, about 4-9 km east of Anand on the Anand-Vadodara highway, where bean-to-bar chocolate production happens in a fully automated plant. Guided factory tours run in the afternoon and end at the factory outlet for fresh chocolates. Industrial visits here are documented by multiple university engineering departments.', '2 hours', 'October to February', 'Wear closed shoes and comfortable clothing; photography is restricted inside the plant - check with your guide.', 'Prior online booking required via Amul''s visit-booking portal', 'Gujarat', 0, 0, NULL, NULL, 'Free', 4, 4, 22.522, 73.018, 'Mogar village, on NH-48 (Anand-Vadodara highway), Anand district, Gujarat', 'https://amuldairy.com', 0.8);

