INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000289, 332012, 'BAPS Shri Swaminarayan Mandir, Anand', 'BAPS Shri Swaminarayan Mandir, Anand', 'The main BAPS Swaminarayan temple of Anand town, near Goya Talav, built in the sect''s characteristic ornate style with carved pillars, domes and a radiant sanctum. Daily sabhas and five aartis structure the day; Diwali and Annakut celebrations are noteworthy here.', '1-2 hours', 'October to March; evenings for aarti', 'Visit during morning or evening aarti for the full experience; dress modestly and remove footwear at the entrance.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 4, 4, 22.553388, 72.954358, 'Goya Talav, Anand, Gujarat 388001', 'http://www.baps.org/Anand', 0.8);

