INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000290, 332012, 'Sardar Vallabhbhai Patel and Vithalbhai Patel Memorial, Karamsad', 'Sardar Patel Memorial, Karamsad', 'Memorial complex on 7 acres at Karamsad, about 6 km from Anand, honouring Sardar Vallabhbhai Patel and his elder brother Veer Vithalbhai Patel. It holds the Sardars'' personal belongings including the Bharat Ratna, a photo gallery of their lives and the Bardoli Satyagraha, an auditorium and landscaped gardens. The memorial was established in 1975 and is managed by the Sardar Patel Trust.', '1-2 hours', 'October to March', 'Pair the visit with the ancestral home across the road; the Sardar''s Bharat Ratna and Mountbatten''s tea set are the headline exhibits.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Rs 15', 4, 4, 22.539129, 72.896991, '17, Anand-Sojitra Road, Karamsad, Gujarat 388325 (about 6 km west of Anand)', NULL, 0.8);

