INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000291, 332012, 'Sardar Patel''s Ancestral Home, Karamsad', 'Sardar Patel''s Ancestral Home', 'The preserved childhood/ancestral home of Sardar Vallabhbhai Patel, standing just across the road from the memorial complex at Karamsad. Visitors see the original family house and its surroundings as part of the same heritage stop.', '30-45 minutes', 'October to March', 'Walk over from the memorial across the road - the two sites are a single half-day stop.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 3, 3, 22.5403, 72.8936, 'Near Sardar Patel Memorial, Karamsad, Gujarat 388325', NULL, 0.6);

