INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000292, 332012, 'ISKCON Temple (Sri Sri Radha Giridhari), Vallabh Vidyanagar', 'ISKCON Temple, Vallabh Vidyanagar', 'The ISKCON temple of Vallabh Vidyanagar, enshrining Sri Sri Radha Giridhari. A well-kept modern temple known for its kirtans, clean premises and the Friday-evening khichdi prasadam; Janmashtami is celebrated here on a large scale.', '1 hour', 'Evenings, around 7pm, for kirtan and aarti', 'Time your visit for the evening aarti and try the famous Friday-evening khichdi prasadam.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 3, 4, 22.556, 72.9235, 'Mota Bazar, Opp. B&B Polytechnic College, Vallabh Vidyanagar, Anand, Gujarat 388120', NULL, 0.68);

