INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000293, 332012, 'Shree Lambhvel Hanumanji Temple', 'Shree Lambhvel Hanumanji Temple', 'Famous swayambhu (self-manifested) Hanumanji temple at Lambhvel village, just 2 km from Anand on the Anand-Kanjari road, set in a large campus with devotee facilities and a marriage hall. The temple draws thousands of devotees, especially on Saturdays and Tuesdays, and hosts a huge fair on Kali Chaudas, the day before Diwali.', '1 hour', 'Saturday or Tuesday mornings; October-November for the Kali Chaudas fair', 'Go on a Saturday or Tuesday for the liveliest darshan; the Kali Chaudas fair is the biggest event of the year here.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 4, 4, 22.577948, 72.938402, 'Nadiad-Anand Road, Lambhvel, Gujarat 388315 (about 2-3 km from Anand)', NULL, 0.8);

