INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000294, 332012, 'Jitodia Vaijnath Mahadev Temple', 'Jitodia Vaijnath Mahadev Temple', 'Ancient Shiva temple at Jitodia village, a few kilometres from Anand, believed by local legend to date to the 11th century with a lingam said to have been installed by Bhima of the Pandavas during their exile. The complex includes smaller shrines to Hanumanji, Mataji and Sai Baba, and draws steady local devotion.', '45 minutes', 'Mornings; Maha Shivratri', 'Ask the pujari about the temple''s legend - the story of the buried lingam is the heart of this place.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 3, 3, 22.5301, 72.9612, 'Jitodia village, near Anand, Gujarat', NULL, 0.6);

