INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000296, 332012, 'Shree Rokadiya Hanumanji Temple, Anand', 'Shree Rokadiya Hanumanji Temple', 'Well-maintained Hanumanji temple in central Anand, behind the Arts College near Goya, with a large clean campus and parking. It is a popular local worship spot with extended evening hours on Tuesdays and Saturdays.', '45 minutes', 'Tuesday or Saturday evenings', 'Combine with a visit to the nearby BAPS mandir and Goya Talav - all three are within a kilometre.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 2, 3, 22.555074, 72.953139, 'Shree Rokadiyadev Hanumanji Marg, behind P.M. Patel Arts College, Anand, Gujarat 388001', NULL, 0.48);

