INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000300, 332012, 'Goya Talav (Goya Lake)', 'Goya Talav', 'Small urban lake in central Anand, next to the BAPS Swaminarayan mandir, referenced as a local landmark (the mandir''s own address is ''Goya Talav''). A quiet spot for a short lakeside pause; evenings are the nicest time.', '30 minutes', 'Evenings, around sunset', 'Walk here after the BAPS mandir darshan - it is a five-minute stroll away.', NULL, 'Gujarat', 0, 1, NULL, NULL, NULL, 1, 2, 22.5525, 72.9555, 'Near Goya Talav, Anand, Gujarat 388001', NULL, 0.28);

