INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 332000300, 'insert', 'bulk', 'Lake''s existence as a real Anand landmark confirmed via the official BAPS Anand page (mandir address ''Goya Talav, Anand'') and local restaurant addresses citing ''near Goya Lake''; coordinates approximate. Minor/local spot included to round out the in-city list.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000301, 332012, 'Shri Ranchhodraiji Temple, Dakor', 'Ranchhodraiji Temple, Dakor', 'One of Gujarat''s most important Vaishnavite pilgrimage centres, about 30 km from Anand, dedicated to Lord Krishna as Ranchhodraiji (''he who left the battlefield''). The temple, enclosed by a fort wall on the banks of the holy Gomti lake, was built in 1772 AD with 8 domes and 24 turrets; the black-touchstone idol sits on an ornate silver-and-gold throne presented by the Gaekwad of Baroda. Full-moon days draw an ocean of pilgrims.', '2-3 hours', 'October to March; full-moon (Punam) days are the most vibrant', 'Arrive before the 12 noon closure or plan for the 4pm session; on Punam days expect very large crowds - go early.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 5, 4, 22.754384, 73.149092, 'Dakor, Dist. Kheda, Gujarat 388225 (about 30 km northeast of Anand)', 'https://www.ranchhodraiji.org/', 0.92);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (332000301, 332000301, '06:00-12:00, 16:00-19:00', '06:00-12:00, 16:00-19:00', '06:00-12:00, 16:00-19:00', '06:00-12:00, 16:00-19:00', '06:00-12:00, 16:00-19:00', '06:00-12:00, 16:00-19:00', '06:00-12:00, 16:00-19:00', 'Per Gujarat Tourism: 6am-12 noon and 4pm-7pm daily; closed 12-4pm. Detailed aarti/bhog schedule varies on Punam days.');

