INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 332000301, 'insert', 'bulk', 'Temple history (built 1772 AD), architecture (8 domes, 24 turrets, Gomti lake) and 6am-12/4pm-7pm visiting hours confirmed via Gujarat Tourism''s official portal; official temple website ranchhodraiji.org fetched live on 2026-09-30 and verified genuine (active temple trust site with 2026 Purnima updates); festival calendar (Kartik/Falgun/Chaitra/Aso Punams, Janmashtami etc.) from gujuland. Day trip: ~30 km from Anand.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000302, 332012, 'Manilaxmi Jain Tirth, Manej', 'Manilaxmi Jain Tirth', 'Striking modern Jain pilgrimage complex at Manej village, about 30 km from Anand on the Vadodara-Bhavnagar highway, spread over 44 acres and dedicated to Lord Munisuvrat Swami (20th Tirthankar). The white-marble temple, opened to the public in February 2017 after construction began in 2009, is famed for its intricate carving and spectacular evening lighting. A dharamshala and sattvic Jain restaurant serve pilgrims.', '2 hours', 'Evenings, when the temple is lit up', 'Photography is prohibited inside the temple; stay for the evening lighting, which is the highlight.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 4, 4, 22.445516, 72.730212, 'NH-8, near Big Canal, Manej, Anand, Gujarat 388150 (about 30 km southwest of Anand)', 'http://manilaxmitirth.com/', 0.8);

