INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000303, 332012, 'Champaner-Pavagadh Archaeological Park', 'Champaner-Pavagadh Archaeological Park', 'UNESCO World Heritage Site (inscribed 2004) about 55 km from Anand, combining the 15th-16th century Islamic city of Champaner - with mosques, stepwells and palaces of Sultan Mahmud Begada - and the sacred Pavagadh hill, crowned by the Kalika Mata temple, one of Gujarat''s great Shakti shrines. Ropeway access to the hilltop temple is available.', 'Full day', 'October to March', 'Plan a full day: Champaner''s mosques in the morning, then the ropeway up Pavagadh for the Kalika Mata temple in the afternoon.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 5, 5, 22.483, 73.533, 'Champaner-Pavagadh, Panchmahal district, Gujarat (about 55 km east of Anand)', NULL, 1.0);

