INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000304, 332012, 'Laxmi Vilas Palace, Vadodara', 'Laxmi Vilas Palace', 'One of India''s grandest royal residences, about 40 km from Anand in Vadodara, built in 1890 by Maharaja Sayajirao Gaekwad III in Indo-Saracenic style - reputedly four times the size of Buckingham Palace. Part of the still-occupied palace and the Maharaja Fateh Singh Museum (with Raja Ravi Varma paintings, armoury and sculpture galleries) are open to visitors with an audio guide.', '2-3 hours', 'October to March', 'Go in the morning (9:30-10am) to avoid the midday heat; photography is restricted inside the palace.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Rs 250', 5, 4, 22.2806, 73.1769, 'Nehru Road, Vadodara, Gujarat 390001 (about 40 km southeast of Anand)', NULL, 0.92);

