INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000305, 332012, 'Shree Santram Mandir, Nadiad', 'Shree Santram Mandir', 'Revered temple of Santram Maharaj (the ''Girnari Bava'' who came to Nadiad in the early 19th century and took jivant samadhi on Magh Purnima, 1830) in the heart of Nadiad, about 18 km from Anand. The temple trust runs wide humanitarian work - an eye hospital, dispensary, radiology and pathology services - and offers free prasad meals to pilgrims.', '1-2 hours', 'Mornings or evenings', 'Photography is strictly prohibited inside the Samadhi-sthan; do not miss the free prasad meal served to visitors.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 3, 4, 22.6947, 72.859, 'Shri Santram Mandir Marg, Shanti Nagar, Nadiad, Gujarat 387001 (about 18 km north of Anand)', NULL, 0.68);

