INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000306, 332012, 'Borsad Stepwell', 'Borsad Stepwell', 'Seven-storey stepwell in Borsad town, about 17 km from Anand, built in 1497 by Vasu Soma and his family with 13 arches and a Sanskrit inscription dated Samvat 1553. A protected Monument of National Importance (N-GJ-69) under the Archaeological Survey of India - a fine, less-visited example of Gujarat''s stepwell architecture.', '45 minutes', 'October to March, mornings', 'Look for the Sanskrit inscription recording its 1497 construction - one of the few dated stepwells in the region.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 3, 3, 22.412, 72.9, 'Borsad town, Anand district, Gujarat (about 17 km southwest of Anand)', NULL, 0.6);

