INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000307, 332012, 'Umiya Annapurna Kathiyawadi Restaurant', 'Umiya Annapurna Kathiyawadi Restaurant', 'Popular Kathiyawadi restaurant at Rajodpura in Anand, serving authentic Kathiyawadi thalis and regional Gujarati dishes. It is the restaurant recommended as ''Ummia Annapurna Kathiawad'' in published Anand day-itineraries for a classic Kathiyawadi lunch.', '1 hour', 'Lunch or dinner', 'Order the Kathiyawadi thali with bajra rotla, sev-tameta and lasaniya batata for the full local spread.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 4, 4, 22.558507, 72.985818, 'Rajodpura, Anand, Gujarat', NULL, 0.8);

