INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3320043, 332, 332012, 'Navratri', 'September-October', 'Gujarat''s most famous festival: nine nights of garba and dandiya-raas dancing, fasting and late-night celebrations in neighbourhoods and clubs across Anand, Vallabh Vidyanagar and nearby towns.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3320044, 332, 332012, 'Kali Chaudas Fair, Lambhvel Hanumanji Temple', 'October-November', 'On Kali Chaudas, the day before Diwali, a huge fair is held at the Shree Lambhvel Hanumanji Temple, drawing thousands of devotees from Anand and surrounding villages with great faith and devotion.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3320045, 332, 332012, 'Dakor Purnima Fairs', 'October-November', 'Full-moon fairs at Dakor''s Ranchhodraiji Temple, about 30 km from Anand. The full moon days of the Kartik, Falgun, Chaitra and Aso months draw an ocean of pilgrims; festivals like Janmashtami, Nanda Mahotsava, Hindola, Rath Yatra, Holi, Dussehra and Annakut are also celebrated with great zeal.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3320046, 332, 332012, 'Uttarayan (Makar Sankranti)', 'January', 'The January kite festival: rooftops across Anand and Charotar fill with kite-flyers from dawn, with traditional undhiyu, jalebi and fafda on the menu.');

-- city: Mandvi (id 1063)
