INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000313, 332013, 'Mandvi Beach', 'Mandvi Beach', 'Mandvi Beach is a long, clean stretch of golden sand on the Gulf of Kutch, widely rated one of Gujarat''s best beaches. Visitors come for swimming, camel and horse rides, parasailing and water sports in season, and calm sunset views over the Arabian Sea. The beach sits 3-4 km south of Mandvi town and is the town''s star attraction.', '2-3 hours', 'October to February; evenings for sunsets', 'Carry water and sun protection; check with local operators before swimming as there are no published lifeguard timings.', NULL, 'Gujarat', 0, 1, NULL, NULL, NULL, 5, 5, 22.823213, 69.343329, 'Mandvi Beach, Mandvi, Kutch, Gujarat 370465', NULL, 1.0);

