INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 332000313, 'insert', 'bulk', 'Beach and its activities confirmed from Wikipedia (Mandvi), rannutsav.in and Forbes India. Coordinates 22.823213, 69.343329 from a published Mandvi Beach listing; within ~1km of the beach stretch south of town.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000314, 332013, 'Vijay Vilas Palace', 'Vijay Vilas Palace', 'Vijay Vilas Palace is a 1929 red-sandstone summer palace built during the reign of Maharao Khengarji III for his son Yuvraj Vijayaraji, blending Rajput, Mughal and Victorian styles. It is famous as a Bollywood filming location for Lagaan and Hum Dil De Chuke Sanam, and still partly serves as the Kutch royal family''s residence. The palace has its own museum, gardens and private beach, about 7 km from Mandvi town.', '1.5-2 hours', 'October to March', 'Visit in the morning slot (9-1) for softer light and fewer crowds; the terrace offers the best panoramic views.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Rs 20', 5, 4, 22.821, 69.387, 'Vijay Vilas Palace Road, Kathda, Mandvi Rural, Gujarat 370465', NULL, 0.92);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (332000314, 332000314, '09:00-13:00, 15:00-18:00', '09:00-13:00, 15:00-18:00', '09:00-13:00, 15:00-18:00', '09:00-13:00, 15:00-18:00', '09:00-13:00, 15:00-18:00', '09:00-13:00, 15:00-18:00', '09:00-13:00, 15:00-18:00', 'Midday break 13:00-15:00. Upper residential floors are reserved for the royal family.');

