INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 332000314, 'insert', 'bulk', 'Entry fee Rs 20/person, camera Rs 50, and hours 9am-1pm / 3pm-6pm from Government of India''s India Cine Hub page. History and architecture from Wikipedia. Coordinates approximate (~22.821, 69.387 at Kathda, ~7km from town per govt page); exact coords not published - cross-check recommended.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000315, 332013, 'Mandvi Shipbuilding Yard', 'Mandvi Shipbuilding Yard', 'Mandvi is a 400-year-old shipbuilding centre where master carpenters (Kharva community) still build wooden dhows by traditional hand techniques on the banks of the Rukmavati river. At its 18th-century peak Mandvi merchants owned a fleet of 400 vessels trading with East Africa, Arabia and the Malabar coast. Visitors can watch the boat-building sheds in action - one of the few surviving hand-built wooden shipyards in India.', '45-60 minutes', 'October to February, daytime working hours', 'Ask permission before photographing workers up close; combine with a walk across the Rukmavati Bridge.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 5, 4, 22.84, 69.359, 'Banks of Rukmavati River, Mandvi, Kutch, Gujarat 370465', NULL, 0.92);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (332000315, 332000315, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Working shipyard; no published visitor hours. Best seen during daytime working hours.');

