INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000316, 332013, '72 Jinalaya Jain Temple (Bauter Jinalaya)', '72 Jinalaya Jain Temple', '72 Jinalaya (also called Bauter Jinalaya) is a major Jain pilgrimage complex about 10-11 km from Mandvi on the Mundra-Mandvi road, built in 1982 in memory of Gun Sagar Suriswarji Maharaj. Set on roughly 80 acres of white marble, a central octagonal shrine to Lord Mahavir is surrounded by 72 smaller shrines dedicated to the Tirthankaras, all covered in intricate stone carving. The complex has a dharamshala and bhojanalaya for pilgrims.', '1.5-2 hours', 'October to March, early morning', 'Dress modestly and remove footwear before entering; the on-site bhojanalaya serves simple satvik meals to visitors.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 4, 5, 22.894334, 69.410212, '72 Jinalaya, Gunnagar, Talwana Village, Mandvi Rural, Gujarat 370460', NULL, 0.88);

