INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 332000316, 'insert', 'bulk', 'Complex, 1982 origin, 80 acres and dharamshala confirmed by Rann Utsav''s official tent-city site (tentcity.rannutsavgujarat.in). Coordinates 22.894334, 69.410212 from a published map listing for a point immediately beside the temple on the Mandvi-Bhuj road.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000317, 332013, 'Rukmavati Bridge', 'Rukmavati Bridge', 'The Rukmavati Bridge, built in 1883, spans the Rukmavati river between Mandvi city and Salaya and is described as the longest existing structure of its kind in India. It was constructed by Vishram Karman Chawda of the Kutchi Mistri community, who also built the Mandvi port docks the same year. The bridge offers good views of the river, the shipbuilding yards and evening birdlife.', '30 minutes', 'Evenings', 'Walk across at sunset for views of the shipyards; combine with the Mandvi Fort remnants nearby.', NULL, 'Gujarat', 0, 1, NULL, NULL, 'Free', 3, 3, 22.836, 69.358, 'Mundra-Mandvi Road over Rukmavati River, Mandvi, Gujarat 370465', NULL, 0.6);

