INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000318, 332013, 'Wind Farms Beach', 'Wind Farms Beach', 'About 7 km west of Mandvi town, the coastline is lined with giant windmills - the site of Asia''s first wind-farm project, commissioned in 1983. The beach is quieter than Mandvi Beach and is a favourite for photography and evening walks, especially at sunset when the rotating blades silhouette against the sky. Seasonal parasailing and water sports are also offered here.', '1-2 hours', 'October to February; sunset', 'Go at golden hour for the classic windmill-silhouette photos; carry snacks as facilities are limited.', NULL, 'Gujarat', 0, 1, NULL, NULL, NULL, 4, 4, 22.823, 69.285, 'Wind Farms Beach, west of Mandvi, Gujarat 370465', NULL, 0.8);

