INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000319, 332013, 'Shyamji Krishna Varma Memorial (Kranti Teerth)', 'Shyamji Krishna Varma Memorial (Kranti Teerth)', 'Kranti Teerth, also called the Shyamji Krishna Varma Memorial, is a 52-acre memorial 3-5 km from Mandvi honouring the Mandvi-born revolutionary Shyamji Krishna Varma (1857-1930), founder of India House in London. Built in 2010 and maintained by GMDC, it houses a replica of London''s India House, the ashes of Varma and his wife, and the Viranjali photo gallery. It is an educational stop on India''s freedom-struggle history.', '2-3 hours', 'October to February', 'An S.T. bus runs from Mandvi S.T. depot at 11:00 AM reaching Kranti Teerth at 11:15 (per Gujarat Tourism); guides are available on site.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 4, 4, 22.855, 69.38, 'Salaya-Maska Road, near Shyamji Krishna Varma Smarak, Mandvi, Gujarat 370465', NULL, 0.8);

