INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000320, 332013, 'Topansar Lake', 'Topansar Lake', 'Topansar Lake sits in the heart of Mandvi city and is one of its key landmarks. In winter thousands of seagulls visit the lake, making it a pleasant spot for morning walks and birdwatching. The Shitla Mata Temple on Layja Road stands just opposite the lake, where a walkway was under construction.', '30-45 minutes', 'November to February (migratory birds)', 'Visit early morning in winter for the best bird activity and soft light for photography.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 3, 3, 22.838, 69.351, 'Topansar Lake, Mandvi, Kutch, Gujarat 370465', NULL, 0.6);

