INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 332000320, 'insert', 'bulk', 'Lake and winter seagull visits confirmed from Wikipedia (Mandvi). Coordinates approximate in the town centre; no published exact pin.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000321, 332013, 'Mandvi Port', 'Mandvi Port', 'Mandvi Port, built in 1580 by Rao Khengarji I, was once among India''s busiest ports - in the late 18th and early 19th centuries it anchored a triangular trade route between Oman, Mandvi and the Punjab-Sindh hinterland. Today it is a sleepy lighterage port with wooden sailboats on the water, and merchants once gathered at the fort bastion Hodiyo Kotho to watch for incoming ships. The port area gives a real sense of Mandvi''s maritime past.', '45 minutes', 'October to February', 'Combine with the shipbuilding yards and lighthouse; the foreshore is best explored on foot in the cooler morning hours.', NULL, 'Gujarat', 0, 1, NULL, NULL, NULL, 3, 3, 22.828, 69.356, 'Mandvi Port, Mandvi, Kutch, Gujarat 370465', NULL, 0.6);

