INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000322, 332013, 'Mandvi Fort', 'Mandvi Fort', 'Mandvi was originally a fortified town enclosed by a stone-masonry fort wall about 8 m high and 1.2 m wide, with ruins still visible near the Brahmapuri area. The fortress was built in the mid-16th century; four gates and six bastions were preserved as protected monuments after later demolitions. The surviving gates and wall fragments are a quick heritage stop near the Rukmavati bridge.', '30 minutes', 'October to February', 'Look for the old gates and bastions around the Brahmapuri area; pair it with the Rukmavati Bridge walk.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 3, 3, 22.834941, 69.357474, 'Mandvi Fort, near Mandvi Bridge, Mandvi, Gujarat 370465', NULL, 0.6);

