INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000323, 332013, 'Mandvi Lighthouse', 'Mandvi Lighthouse', 'Mandvi''s lighthouse stands near the port and was newly constructed for country-craft sea transportation after the 2001 Gujarat earthquake destroyed the earlier structure. An earlier candy-striped lighthouse with an oil-wick lamp was fitted here in 1872 to aid maritime navigation. It remains a working aid to navigation and a landmark on the Mandvi foreshore.', '20 minutes', 'October to February', 'Best viewed/photographed from the port foreshore; access to the tower itself is not a published visitor facility.', NULL, 'Gujarat', 0, 1, NULL, NULL, NULL, 2, 3, 22.826, 69.355, 'Mandvi Lighthouse, near Mandvi Port, Mandvi, Gujarat 370465', NULL, 0.48);

