INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000324, 332013, 'Bandhani Bazaar (Mandvi Market)', 'Bandhani Bazaar (Mandvi Market)', 'Mandvi''s old bazaars are known for Bandhani (tie-dye) production and country crafts, and remain a working market town rather than a tourist set-piece. Shoppers find Bandhani fabrics, Kutchi handicrafts, traditional silver jewellery and local snacks like the town''s famous dabeli. Azad Chowk nearby is known for local favourites such as khari daar and toss.', '1-2 hours', 'October to February; evenings', 'Bargain politely and try the dabeli - Wikipedia notes it was invented in Mandvi in the 1960s by Keshavji Gabha Chudasama.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 4, 4, 22.83, 69.353, 'Main Bazaar, Mandvi, Kutch, Gujarat 370465', NULL, 0.8);

