INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000325, 332013, 'Shree Swaminarayan Temple, Mandvi', 'Shree Swaminarayan Temple, Mandvi', 'Mandvi''s Swaminarayan temple in the main city is about 157 years old, with a newer, larger temple now standing on the Mandvi-Naliya main road. The Swaminarayan movement has deep 19th-century roots in the town. It is an active place of worship and a fine example of the town''s living religious heritage.', '30-45 minutes', 'Mornings and evenings', 'Visit during morning or evening aarti; dress modestly as with all temples.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 3, 3, 22.832, 69.354, 'Shree Swaminarayan Temple, Mandvi, Kutch, Gujarat 370465', NULL, 0.6);

