INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000326, 332013, 'Kashi Vishvanath Beach (Salaya)', 'Kashi Vishvanath Beach', 'Kashi Vishvanath Beach (also spelt Kasi Vishvanath) lies across the Rukmavati bridge on the Salaya side, east of the river, and takes its name from the Shiva temple nearby. It is a quieter alternative to the main Mandvi Beach with clean sand and a local, uncommercialised feel. The beach is about 12-13 km east of Mandvi town along the coast.', '1-2 hours', 'October to February', 'A good pick for a quieter beach day; facilities are minimal, so carry what you need.', NULL, 'Gujarat', 0, 1, NULL, NULL, NULL, 3, 3, 22.816, 69.372, 'Near Kashi Vishwanath Temple, Salaya, Mandvi Rural, Gujarat 370465', NULL, 0.6);

