INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 332000326, 'insert', 'bulk', 'Beach and its naming after the nearby Shiva temple confirmed from Wikipedia (Mandvi) and onefivenine; travalour confirms it sits east of the river past Salaya. Coordinates approximate on the Salaya-side coast.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000327, 332013, 'Rawalpeer Temple and Beach', 'Rawalpeer Temple and Beach', 'The Rawalpeer (Ravalpir) temple, about 6 km from Mandvi, is sacred to Raval Pir - a 14th-century figure famed for destroying missionaries who disturbed devotees of Dhoramnath on Dhinodhar Hills. The present temple was rebuilt in 1819 (Samvat 1876) by Seth Sundarji and Jetha Shivji, and a clean beach lies nearby. It combines a heritage shrine with a quiet seaside stop.', '1 hour', 'October to February', 'Combine the temple with its beach; carry water as the spot has few facilities.', NULL, 'Gujarat', 0, 1, NULL, NULL, 'Free', 3, 4, 22.812736, 69.390381, 'Ravalpeer Beach Temple, Mandvi Taluka, Gujarat 370465', NULL, 0.68);

