INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000328, 332013, 'Ambe Dham Shakti Tirth, Godhra', 'Ambe Dham Shakti Tirth', 'Ambe Dham (Shree Ambedham Shakti Tirth) at Godhra village is a large modern Shakti temple complex about 15-20 minutes from Mandvi, roughly 12 km away. The complex is known for intricate golden mirror-work on the dome interior and includes a food court, exhibition hall, a replica of the Vaishno Devi shrine with a hill structure, and large gardens. It draws both devotees and tourists.', '1.5-2 hours', 'October to February', 'Allow extra time for the gardens and the Vaishno Devi replica; the on-site food court is handy for a meal stop.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 3, 3, 22.917177, 69.26649, 'Shree Ambedham Shakti Tirth, Godhra, Mandvi Rural, Gujarat', NULL, 0.6);

