INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000329, 332013, 'Bhadreshwar Jain Temple', 'Bhadreshwar Jain Temple (Vasai Jain Temple)', 'Bhadreshwar Jain Temple (Vasai Jain Temple), about 69 km east of Mandvi past Mundra, is considered one of the oldest Jain temples in India, dedicated to Ajitnath. Renovated repeatedly across the centuries - including after the 2001 earthquake - it stands in white marble surrounded by 44 shrines. Nearby are 12th-century mosques and the Lal Shahbaz Dargah, making Bhadreshwar a layered heritage stop.', '2-3 hours', 'September to February', 'This is a day trip (~69 km each way, ~1.5 hours by taxi); the temple bhojanalaya serves very affordable meals.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 4, 4, 22.911694, 69.90389, 'Vasai Jain Teerth, Mahavirnagar, Bhadreshwar, Mundra, Kutch, Gujarat 370410', NULL, 0.8);

