INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000330, 332013, 'Roha Fort', 'Roha Fort', 'Roha Fort (Roha Sumari Fort), about 48 km from Mandvi in Nakhatrana taluka, sits 800 feet above sea level on Roha Hill covering 16 acres. The fort complex was built up over generations of Roha jagir lords and completed in the 1550s-18th century; it holds a Krishna temple, palace rooms and memorials to 120 Soomra Rajput princesses. Gujarati poet Kalapi wrote romantic poems here, drawn by its peacocks and peaceful setting.', '2 hours', 'October to February', 'Sunrise and sunset give the best light for the ruins; watch for snakes and carry your own water and snacks.', NULL, 'Gujarat', 1, 1, NULL, NULL, 'Free', 4, 4, 23.20056, 69.26972, 'Roha Fort, Roha Village, Nakhatrana Taluka, Kutch, Gujarat', NULL, 0.8);

