INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000331, 332013, 'Aina Mahal, Bhuj', 'Aina Mahal', 'Aina Mahal (Palace of Mirrors), about 60 km from Mandvi in Bhuj, is an 18th-century palace built around 1750 by Rao Lakhpatji and designed by Ram Singh Malam. Its halls glitter with mirrors, Venetian glass chandeliers, Delft tiles and a famed ''europeanerie'' collection of clocks, paintings and mechanical toys. Damaged in the 2001 earthquake, part of it is restored and now houses the Aina Mahal Trust Museum.', '1.5-2 hours', 'October to February', 'Pair with neighbouring Prag Mahal and the Kutch Museum for a full Bhuj heritage day from Mandvi.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 5, 5, 23.2553, 69.66877, 'Aina Mahal, Darbargadh, Bhuj, Kutch, Gujarat 370001', NULL, 1.0);

