INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000332, 332013, 'Kutch Museum, Bhuj', 'Kutch Museum', 'The Kutch Museum in Bhuj, about 60 km from Mandvi, is Gujarat''s oldest museum, founded in 1877 as the Fergusson Museum. Set opposite Hamirsar Lake in an Italian-Gothic building, it holds Kshatrapa inscriptions, Kutchi textiles, arms, musical instruments, coins and the famous carved wooden ''Airavat'' elephant made in Mandvi. It was India''s first museum to go online as a virtual museum in 2010.', '1.5-2 hours', 'October to February', 'Combine with Hamirsar Lake (right opposite) and the Aina Mahal/Prag Mahal complex nearby.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 4, 5, 23.24861, 69.66639, 'Kutch Museum, opposite Hamirsar Lake, Bhuj, Gujarat 370001', NULL, 0.88);

