INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000333, 332013, 'Shyam Restaurant', 'Shyam Restaurant', 'Shyam Restaurant on Swamiji Sheri is a vegetarian Punjabi and multi-cuisine restaurant in Mandvi town. Its published online menu covers soups, Chinese, paneer dishes, dals, breads, biryanis, sizzlers, pizzas and beverages, with most mains priced Rs 170-280. It offers dine-in, pickup and delivery, and publishes daily opening hours of 11 AM to 10 PM.', '45-60 minutes', 'Lunch and dinner', 'Good fallback for familiar North Indian/Chinese veg food; pre-order is available per the site.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Rs 250', 4, 4, 22.83637, 69.348151, 'R8PX+G72, Swamiji Sheri, Mandvi, Gujarat 370465', 'https://shyamrestaurant.mandvi.online/', 0.8);

