INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000334, 332013, 'OSHO Restaurant', 'OSHO Restaurant', 'OSHO Restaurant near Bhid Gate is known for its Gujarati vegetarian thali and is frequently recommended to visitors as a must-try meal in Mandvi. Tour itineraries (e.g. JustWravel''s Kutch circuit) specifically route travellers here for the thali. It serves Gujarati staples including jalebi alongside the thali.', '45 minutes', 'Lunch (thali)', 'Go for lunch to get the full thali experience; it is a local favourite, not a tourist-trap.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 4, 4, 22.831556, 69.352982, 'Near Bhid Gate, K.T. Shah Road, Mandvi, Gujarat 370465', NULL, 0.8);

