INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000335, 332013, 'Irani Hotel', 'Irani Hotel', 'Irani Hotel on Mandvi-Layja Road is a long-running veg/non-veg restaurant and lodging serving biryani, manchurian, roti and similar multi-cuisine fare. A published local listing shows it currently open with daily hours of 6 AM to 11 PM and a moderate price level. It sits close to the town centre, convenient for travellers staying in Mandvi.', '45 minutes', 'Lunch and dinner', 'Handy early-morning option (reported 6 AM opening); confirm hours locally as they are not officially published.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 3, 3, 22.836781, 69.348828, 'Mandvi - Layja Road, Mandvi, Gujarat 370465', NULL, 0.6);

