INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3320047, 332, 332013, 'Rann Utsav', 'November-February', 'Gujarat''s flagship desert festival held at Dhordo in the White Rann, about 150 km from Mandvi; most travellers combine it with a Mandvi beach-and-heritage leg in the same trip. Folk music, dance, crafts and full-moon desert nights.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3320048, 332, 332013, 'Navratri', 'September-October', 'Nine nights of garba and dandiya dancing celebrated with great enthusiasm across Kutch, including community garba grounds in Mandvi town.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3320049, 332, 332013, 'Uttarayan (Makar Sankranti)', 'January', 'Gujarat''s famous kite festival; Mandvi''s beaches and rooftops fill with kite-flyers and the sky over the Gulf of Kutch is crowded with colourful kites.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3320050, 332, 332013, 'Maha Shivratri at Kashi Vishvanath', 'February-March', 'The Shiva temple at Salaya, after which Kashi Vishvanath Beach is named, sees special night-long prayers and crowds of devotees on Maha Shivratri.');

-- city: Pavagadh (id 1064)
INSERT OR IGNORE INTO cities (id, state_id, city_name, latitude, longitude) VALUES (332014, 332, 'Pavagadh', 22.47, 73.52);

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000339, 332014, 'Kalika Mata Temple', 'Shree Mahakali Mataji Temple, Pavagadh', 'Ancient Hindu goddess temple at the ~800 m summit of Pavagadh Hill, dating to the 10th-11th centuries and one of the 51 Shakti Peethas, where the right toe of Goddess Sati is believed to have fallen. It houses three goddess images (Kalika Mata in the centre, Kali and Bahucharamata) and forms part of the Champaner-Pavagadh Archaeological Park, a UNESCO World Heritage Site. Pilgrims reach it by the ropeway from Maachi or by climbing roughly 2,000 steps.', '2-3 hours', 'October to February; 6:00-8:00 AM to beat the crowds', 'Use the ropeway from Maachi (6-minute ride), then climb the final ~250 steps to the temple; carry water and avoid peak Navratri days if you dislike crowds.', 'Ropeway tickets can be booked online in advance on udankhatola.com', 'Gujarat', 1, 1, NULL, NULL, 'Free', 5, 5, 22.46111, 73.51167, 'Pavagadh Hill summit, Halol, Panchmahal, Gujarat 389360', NULL, 1.0);

