INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 332000339, 'insert', 'bulk', 'Existence, 10th-11th c. dating, Shakti Peetha status, three goddess images, UNESCO WHS inclusion, 762-827 m elevation and ropeway access (commissioned 1986) confirmed from Wikipedia ''Kalika Mata Temple, Pavagadh'' (coords 22.46111N 73.51167E in infobox) and the official Gujarat Tourism page. Navratri crowds and Chaitra Sud 8 fair documented on Wikipedia and in the Gazetteers cited there.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000340, 332014, 'Maa Mahakalika Udan Khatola Ropeway', 'Pavagadh Ropeway', 'Mono-cable ropeway from Maachi to near the Kalika Mata Temple summit, commissioned in 1986 and operated by Udan Khatola (Usha Breco). It is 763 m long with a 297 m vertical rise and a ~6-minute ride in enclosed 6-passenger cabins, and is the main access for elderly and mobility-limited pilgrims. Online slot booking is available and roughly 250 steps remain from the top station to the temple.', '30-45 minutes round trip (excluding queues)', 'Early morning to avoid long queues; avoid monsoon storms and peak Navratri days', 'Buy tickets at the Maachi counter or online; there is no priority boarding for online tickets, so arrive early during festivals.', 'Online advance booking available at udankhatola.com; ticket valid 90 days from purchase', 'Gujarat', 0, 1, NULL, NULL, 'Rs 150', 5, 4, 22.46819, 73.52304, 'Maa Mahakalika Udan Khatola, Maachi, Po. Pavagadh - 389360, Panchmahal, Gujarat', 'https://udankhatola.com/destination/kali-devi', 0.92);

