INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 332000340, 'insert', 'bulk', 'Official operator page udankhatola.com fetched 2026-09-30 and confirmed genuine (Usha Breco; serves multiple ropeway destinations incl. Pavagadh ''Kali Devi''). Pricing list on the official page shows Rs 150 adult / Rs 80 child; a published Udan Khatola booking confirmation states ''NORMAL TICKET (Pavagadh Maa Mahakalika Udankhatola) ... Round Trip Ropeway Journey ... 150''. Timings 6:00 AM-6:45 PM appear only in third-party guides (not on the official site), so hours left null; periodic maintenance closures reported in press guides.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000341, 332014, 'Lakulish Temple', 'Lakulisa Temple, Mauliya Plateau', 'The earliest temple on Pavagadh Hill, a 10th-century shrine on the Mauliya plateau dedicated to Lakulish, founder of the Pashupata Shaivite school. Now largely in ruins, it retains the garbhagriha and parts of the mandapa with fine Nagara-style stone carvings of Dakshinamurti Shiva, Ganesha, Gajantaka Shiva and other deities. It stands by Chasiya Talav and is listed among the ASI monuments of the Champaner-Pavagadh Archaeological Park.', '30-60 minutes', 'October to February; morning light is best for the carvings', 'Combine with Chasiya Talav on the same plateau; wear sturdy shoes as the ruins are on uneven ground.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 4, 4, 22.4625, 73.5135, 'Mauliya Plateau, Pavagadh Hill, Halol, Panchmahal, Gujarat 389360', NULL, 0.8);

