INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000342, 332014, 'Pavagadh Jain Temples', 'Pavagadh Jain Temple Complex (Navalakka Group)', 'A group of Digambar Jain temples on Pavagadh Hill in three clusters: the Navalakka temples near the Naqqarkhana gate, the Suparshvanatha and Chandraprabha group, and the Parshva temples near the Dudhia tank. Built of white stone in the 14th-15th centuries with elaborately carved Tirthankara images, they were damaged under Mahmud Begada and repaired in 1880. The complex includes a 30-ft Bahubali statue, a dharmshala, a Jain restaurant and gardens.', '1-2 hours', 'October to February; morning', 'Respect temple norms (no leather items inside); the Jain bhojanshala in the complex serves simple meals.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 4, 4, 22.462, 73.5195, 'Pavagadh Hill (near Dudhia Talav), Halol, Panchmahal, Gujarat 389360', NULL, 0.8);

