INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000343, 332014, 'Sadan Shah Pir Dargah', 'Sadan Shah Pir Dargah', 'The shrine of the Sufi saint Sadan Shah Pir beside the Kalika Mata Temple at the Pavagadh summit, revered by Muslims as well as Hindus. The old temple complex once carried the dargah in its domed spire; during the 2022 redevelopment the dargah was amicably shifted to a spot next to the temple and a new shikhara was built. It symbolises the shared Hindu-Muslim sacred geography of the hill.', '20-30 minutes', 'With the Kalika Mata Temple darshan', 'Combine with the temple visit; maintain the decorum expected at both shrines.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 3, 3, 22.4612, 73.5119, 'Adjacent to Kalika Mata Temple, Pavagadh Hill summit, Halol, Panchmahal, Gujarat 389360', NULL, 0.6);

