INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000344, 332014, 'Machi Haveli', 'Machi Plateau (Machi Haveli)', 'The 490-m plateau midway up Pavagadh Hill that is the last point accessible by road and the base of the ropeway. It holds the Machi Haveli rest house for pilgrims, small hotels, and the Annapurna and Teliya talaos. GSRTC buses run up to Machi from Halol and Champaner, and most pilgrims begin the final ascent from here.', '30-60 minutes', 'Morning, before the ropeway queues build', 'Park at Machi and take the ropeway from here; basic eateries and rest rooms are available at this level.', NULL, 'Gujarat', 1, 0, NULL, NULL, 'Free', 3, 3, 22.468, 73.523, 'Machi, Pavagadh Hill, Halol, Panchmahal, Gujarat 389360', NULL, 0.6);

