INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000345, 332014, 'Saat Kaman', 'Saat Kaman (Seven Arches)', 'A terrace of seven massive sandstone arches (six now survive, one lost to natural elements) on the southern edge of the Champaner-Pavagadh fortifications along the Pavagadh Hill Road. Part of the historic hill-fort fabric, the arches span a deep ravine and demonstrate sophisticated Sultanate-period structural engineering. It is a quiet, breezy photography stop with views over the Champaner plain.', '30-45 minutes', 'Late afternoon for photography; October to February', 'Carry your own water and snacks - there are no shops nearby; do not litter at this unguarded monument.', NULL, 'Gujarat', 0, 1, NULL, NULL, 'Free', 4, 4, 22.469, 73.528, 'Pavagadh Hill Road, near Champaner, Halol, Panchmahal, Gujarat 389360', NULL, 0.8);

