INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000346, 332014, 'Navlakha Kothar', 'Navlakha Kothar (Nine-Lakh Granary)', 'A T-shaped brick storehouse with a large central dome on the edge of the Navlakhi valley, north of Pavagadh''s highest peak. Listed among the ASI monuments of the Champaner-Pavagadh Archaeological Park, it is believed to have served as a granary for the hill fort and shows Mughal-era utilitarian architecture. It is reached on the hill trek above Machi.', '30 minutes', 'October to February; morning', 'Best seen as part of the hill walk; the structure is a ruin with no facilities nearby.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 3, 3, 22.465, 73.522, 'Navlakhi Valley, Pavagadh Hill, Halol, Panchmahal, Gujarat 389360', NULL, 0.6);

