INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 332000346, 'insert', 'bulk', 'ASI-listed monument (Navlakha Kothar on Pavagadh Hill), T-shaped brick structure with domes used as a food storehouse, located on the Navlakhi valley edge per the ASI monument list and travalour.com. Coordinates approximate.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000347, 332014, 'Ancient Fort Gates of Pavagadh', 'Pavagadh Hill Fort Gates (Atak, Budhiya, Gulan Bulan, Moti)', 'The chain of fortified gateways on the old pilgrim-cum-military path up Pavagadh Hill: Atak Gate (Gate 1), Budhiya Gate (Gate 2, with three gateways and rock-cut steps), Gulan Bulan Gate (Gate 5 near Machi) and Moti/Sadanshah Gate (Gate 3), plus the Buland Darwaza (Gate 6). Listed as ASI monuments, they punctuate the steep ascent with bastions, cells and natural rock ledges.', '1-2 hours (as part of the hill climb)', 'October to February; morning', 'Trek the old path instead of the ropeway once to experience the gates; wear grip shoes - the rock-cut steps are steep.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 4, 4, 22.464, 73.52, 'Summit path, Pavagadh Hill, Halol, Panchmahal, Gujarat 389360', NULL, 0.8);

