INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 332000347, 'insert', 'bulk', 'Six numbered gates (Atak, Budhiya, Moti/Sadanshah, Gate 4 with bastion, Gulan Bulan near Machi, Buland Darwaza) listed as ASI monuments in the Champaner-Pavagadh monument list (imvoyager/upscwithnikhil); the Freelibrary scholarly article confirms the pilgrim path''s gate sequence including rock-cut Budhiya Darwaza. Coordinates approximate (along the summit path).', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000348, 332014, 'Sat Manzil and Patai Raval Palace Ruins', 'Sat Manzil (Seven-Storey Palace Ruins)', 'The ruins of Sat Manzil, a seven-storeyed structure between gates 4 and 5 on the Pavagadh ascent, alongside the scattered remains of Patai Raval''s palace passed on the path to the summit. Listed as ASI monuments, they are the last Rajput palace remnants before Mahmud Begada''s 1484 conquest, built of local rhyolite and sandstone.', '30-45 minutes', 'October to February; morning', 'Look for these ruins midway up the old path; they are unmarked, so a local guide helps.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 3, 3, 22.4655, 73.5215, 'Between Gates 4 and 5, Pavagadh Hill path, Halol, Panchmahal, Gujarat 389360', NULL, 0.6);

