INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000349, 332014, 'Dudhia Talav', 'Dudhia Talav (Doodhiya Lake)', 'A historic lake on Pavagadh Hill beside the Parshva Jain temple group, part of the hill''s medieval water-management system. The Champaner-Pavagadh water-trail proposals describe a circumambulatory path around the Dudhiya and Chasiya talaos with repaired ghats for pilgrims and the local community. It is a calm, green spot below the summit path.', '20-30 minutes', 'Monsoon and winter, when the lake is full', 'Visit with the nearby Jain temples; the ghats are the best vantage point.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 3, 3, 22.4628, 73.5192, 'Near Jain temples, Pavagadh Hill, Halol, Panchmahal, Gujarat 389360', NULL, 0.6);

