INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000350, 332014, 'Chasiya Talav', 'Chasiya Talav (Chhasiya Lake)', 'A historic lake on the Mauliya plateau of Pavagadh Hill, beside which the 10th-century Lakulish Temple stands on a peninsula jutting into the water. Together with Dudhia and Teliya, it is one of the hill''s three named lakes and part of its medieval water system. The setting is scenic and little-visited.', '20-30 minutes', 'Monsoon and winter', 'Combine with the Lakulish Temple on the same plateau.', NULL, 'Gujarat', 0, 1, NULL, NULL, 'Free', 3, 3, 22.462, 73.513, 'Mauliya Plateau, Pavagadh Hill, Halol, Panchmahal, Gujarat 389360', NULL, 0.6);

