INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000351, 332014, 'Champaner-Pavagadh Archaeological Park', 'Champaner-Pavagadh Archaeological Park (UNESCO World Heritage Site)', 'A UNESCO World Heritage Site (inscribed 2004) spread over 1,329 ha around Champaner town and Pavagadh Hill, about 5 km apart. It preserves the only complete and unchanged pre-Mughal Islamic city alongside Hindu and Jain monuments from the 8th to 16th centuries - some 114 monuments including mosques, temples, stepwells, gates, granaries and tombs. Champaner, founded in the 8th century, was Mahmud Begada''s capital Muhammadabad after his 1484 conquest.', 'Full day (Champaner circuit + Pavagadh hill)', 'November to February', 'Start at the ASI ticket office in Champaner for Saher ki Masjid, then cover Jami Masjid, Kevda and Nagina mosques by auto; wear sun protection as the sites are spread out.', 'ASI ticketed monuments (e.g. inside the citadel) - tickets at the site', 'Gujarat', 0, 0, NULL, NULL, 'Free', 5, 5, 22.5, 73.5, 'Champaner, Halol, Panchmahal, Gujarat 389360', NULL, 1.0);

