INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000352, 332014, 'Jami Masjid', 'Jama Masjid, Champaner', 'The grand congregational mosque of Mahmud Begada''s capital, built in 1513 over 25 years just outside the Champaner citadel''s east gate. A Monument of National Importance (N-GJ-91), it blends Hindu-Jain craftsmanship with Islamic design: two 30-m minarets, 172 pillars, seven mihrabs, a central dome and carved stone jalis. It is considered one of the finest mosques in western India and a model for later mosque architecture.', '45-60 minutes', 'Morning or late afternoon; November to February', 'Look up at the carved ceilings and the lattice jalis; the entry porch carving is the most photographed detail.', NULL, 'Gujarat', 0, 1, NULL, NULL, 'Free', 5, 5, 22.4859, 73.5371, 'Near East Gate, Champaner, Halol, Panchmahal, Gujarat 389360', NULL, 1.0);

