INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000353, 332014, 'Kevda Masjid', 'Kevda Masjid and Cenotaph', 'A 15th-century mosque and cenotaph in the Champaner countryside, built under Mahmud Begada and listed as Monuments of National Importance (N-GJ-93, 95). It has globe-like domes, two carved minarets with narrow stairs, a double-storeyed prayer hall and a cenotaph showing the fusion of Hindu and Islamic styles. Quieter than the Jami Masjid, it is a favourite with photographers.', '30-45 minutes', 'Late afternoon (golden hour); November to February', 'Climb the narrow minaret stairs for views of the surrounding farmland and other mosques on the horizon.', NULL, 'Gujarat', 0, 1, NULL, NULL, 'Free', 4, 4, 22.486, 73.5316, 'Champaner countryside, Halol, Panchmahal, Gujarat 389360', NULL, 0.8);

