INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000354, 332014, 'Nagina Masjid', 'Nagina Masjid (Jewel Mosque)', 'The ''Jewel Mosque'' of Champaner, a 15th-century Mahmud Begada-era mosque built of pure white stone with three large domes, two intricately carved minarets and a two-storey prayer hall. Its adjacent cenotaph has exquisite geometric and floral carving. A Monument of National Importance (N-GJ-96, 97) within the UNESCO park, it sits in open countryside about 1.2 km south of the citadel.', '30-45 minutes', 'Late afternoon; November to February', 'Study the cenotaph''s geometric carvings up close - they are among the finest in the park.', NULL, 'Gujarat', 0, 1, NULL, NULL, 'Free', 4, 4, 22.4905, 73.5316, 'Champaner countryside, Halol, Panchmahal, Gujarat 389360', NULL, 0.8);

