INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000355, 332014, 'Saher ki Masjid', 'Sahar ki Masjid (Shehrka Masjid)', 'The elegant city mosque inside the Champaner citadel, behind the ASI ticket office, believed to have been the private royal mosque of the Sultans. It has five mehrabs, a large central dome with smaller flanking domes and minarets, and a rectangular ablution tank on its platform. Listed among the ASI monuments of the park.', '20-30 minutes', 'Morning; November to February', 'Buy your citadel entry ticket at the ticket office first - the mosque is right behind it.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 4, 4, 22.4825, 73.5295, 'Inside the Citadel, Champaner, Halol, Panchmahal, Gujarat 389360', NULL, 0.8);

