INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000356, 332014, 'Helical Stepwell', 'Helical Vav (Helical Stepwell), Champaner', 'A 16th-century stepwell in Champaner whose 1.2-m-wide staircase spirals down along the wall of the well shaft - an unusual design among the region''s stepwells. Listed among the ASI monuments of the Champaner-Pavagadh Archaeological Park, it is a striking example of Sultanate-period water architecture.', '20-30 minutes', 'Morning; November to February', 'Photograph from the top of the shaft to capture the full spiral of the staircase.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 4, 4, 22.481, 73.532, 'Champaner, Halol, Panchmahal, Gujarat 389360', NULL, 0.8);

