INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000357, 332014, 'Kabutarkhana and Wada Talao', 'Kabutarkhana Pavilion and Wada Talao', 'The Kabutarkhana (House of Pigeons), the Champaner kings'' summer pavilion, standing on the north bank of Wada (Vada) Talao near the Khajuri Masjid. Listed among the ASI monuments, the pavilion catches the cool breeze off the lake - the old water-wise system of interconnected tanks that fed the Sultanate city. Devotees and birdlife gather around the tank.', '30-45 minutes', 'Late afternoon; November to February', 'Walk the tank embankment at dusk for the pavilion''s reflection in the water.', NULL, 'Gujarat', 0, 1, NULL, NULL, 'Free', 4, 4, 22.4785, 73.534, 'North bank of Wada Talao, Champaner, Halol, Panchmahal, Gujarat 389360', NULL, 0.8);

