INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000358, 332014, 'Jambughoda Wildlife Sanctuary', 'Jambughoda Wildlife Sanctuary', 'A wildlife sanctuary in Panchmahal district about 20 km south of Pavagadh/Champaner (70 km from Vadodara), declared in 1989-90 under the Wildlife Protection Act. Once the private hunting estate of the Ranas of Jambughoda, its dry deciduous teak forest shelters leopards, sloth bears, hyenas, jackals and deer, with the Targol and Kada reservoirs attracting birds. Three community-run eco campsites (Dhanpari, Bhat, Targol) offer guided nature walks and stays.', 'Half to full day', 'October to March', 'Book the Dhanpari eco campsite through the forest department in advance; there are no jeep safaris - only guided nature walks.', 'Eco-campsite stays must be booked in advance via the Gujarat Forest Department (Vadodara division)', 'Gujarat', 0, 0, NULL, NULL, 'Rs 50', 3, 4, 22.369, 73.628, 'Jambughoda, Panchmahal, Gujarat', NULL, 0.68);

