INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 332000358, 'insert', 'bulk', 'Location 20 km from Pavagadh/Champaner and 70 km from Vadodara, establishment 1989/1990 under the Wildlife Protection Act, former hunting estate of the Ranas of Jambughoda, fauna (leopard, sloth bear, hyena) and eco campsites confirmed via Wikipedia ''Jambughoda Wildlife Sanctuary'', travelworldplanet.com and luxevista.in guides. Entry fee Rs 50/adult Indian per travelworldplanet (subject to forest-department revision). Coordinates approximate (Jambughoda town area).', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000359, 332014, 'Annapurna Bhawan', 'Annapurna Bhawan (Temple Bhojanalay)', 'The temple-run food facility near the Kalika Mata Temple on Pavagadh Hill serving simple vegetarian meals to pilgrims at about Rs 20 per person. It is the most convenient meal stop at the summit level, alongside the temple trust''s prasadam counter (Rs 50 per box). Basic shops selling snacks and lunch options also line the return path.', '30-45 minutes', '11:00 AM - 2:00 PM for lunch', 'Expect simple, no-frills meals; carry cash as digital payments may be unreliable on the hill.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Rs 20', 3, 3, 22.4615, 73.5115, 'Near Kalika Mata Temple, Pavagadh Hill, Halol, Panchmahal, Gujarat 389360', NULL, 0.6);

