INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 332000359, 'insert', 'bulk', 'Annapurna Bhawan near the temple offering simple food at Rs 20/person, plus temple-trust prasadam at Rs 50/box, reported in the Wanderlog Pavagadh travel guide (published travel content, no login required). Coordinates approximate (summit level near the temple).', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000360, 332014, 'Jain Temple Bhojanshala', 'Pavagadh Jain Temple Bhojanshala', 'The dining hall within the Pavagadh Jain temple complex on the hill, serving simple vegetarian Jain meals to pilgrims and visitors. The complex also has a dharmshala (guesthouse) and gardens, making it the main sit-down food option on the hill besides the temple bhojanalay.', '30-45 minutes', '11:00 AM - 2:00 PM for lunch', 'Meals follow Jain dietary norms (no onion/garlic); ask at the temple office for meal timings.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 3, 3, 22.462, 73.5195, 'Pavagadh Jain Temple complex, Pavagadh Hill, Halol, Panchmahal, Gujarat 389360', NULL, 0.6);

