INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 332000360, 'insert', 'bulk', '''The entire complex houses a Dharmshala or guesthouse, a Jain restaurant and gardens'' - Wikipedia ''Monuments of Champaner-Pavagadh Archaeological Park''. Cost marked Free as no published price; donations/tokens typically apply at such bhojanshalas. Coordinates approximate (Jain temple cluster).', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000361, 332014, 'Champaner Heritage Resort (in-house dining)', 'Champaner Heritage Resort Restaurant', 'The in-house dining at the Champaner Heritage Resort, a 40-acre heritage property near Bhamaria village off the Champaner-Jambughoda road, about 11 km from the Champaner Fort. Listed on the official Gujarat Tourism accommodation page, it serves multi-cuisine meals to guests and is the most reliable sit-down restaurant option near the UNESCO site; recent guest reviews (Aug 2026) describe the food positively.', '1 hour', 'Lunch or dinner; call ahead if not a resident guest', 'Non-resident dining availability varies - confirm with the resort before driving out; it is ~11 km from the monuments.', 'Call the resort ahead to confirm non-guest dining', 'Gujarat', 0, 0, NULL, NULL, NULL, 3, 4, 22.405659, 73.552399, 'Village Bhamaria, Off Champaner-Jambughoda Road, Panchmahal, Gujarat', NULL, 0.68);

