INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 332000361, 'insert', 'bulk', 'Resort confirmed operating: listed on the official Gujarat Tourism accommodation page (crawled 1 day ago) and with recent guest reviews from Aug 2026 describing on-site food; ''Serves food'' attribute in the listing. The resort''s own domain (champanerheritageresort.com) failed to resolve when checked on 2026-09-30, so official_website is null. Coordinates 22.405659N 73.552399E from the listing''s exact location. ~11 km from Champaner Fort per Gujarat Tourism.', 'pipeline');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3320051, 332, 332014, 'Navratri at Kalika Mata Temple', 'September-October', 'The nine-night festival of the Goddess draws lakhs of devotees to Pavagadh; the temple trust opens the inner sanctum from about 5 AM, with special buses (50+ extra ST buses from Champaner Taleti to Machi), CCTV cover, police and private security. Bhaskar reported over one lakh pilgrims on the 6th-7th days of Aso Navratri, with continuous garba and darshan queues through all nine nights.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3320052, 332, 332014, 'Chaitra Sud Ashtami Fair', 'March-April', 'The annual fair on the 8th day of the waxing moon in the month of Chaitra at the Kalika Mata Temple, attended by thousands of devotees. Documented in the 19th-century Gazetteers and still held; devotees of Kalika Mata traditionally worship here by beating bell-metal cymbals.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3320053, 332, 332014, 'Chaitra Purnima Fair', 'April', 'The annual fair on the full-moon day of Chaitra, when large Hindu gatherings come to the summit temple for special poojas, alongside the Dasara (Dussehra) gatherings in autumn.');

-- city: Champaner (id 1065)
