INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000362, 332015, 'Jama Masjid, Champaner', 'Jami Masjid', 'The principal Friday mosque of Sultan Mahmud Begada''s 16th-century capital, completed in 1513. It has twelve domes, two 30-metre carved minarets and a forest of 172 pillars, and is the best-preserved of Champaner''s mosques. Part of the UNESCO World Heritage-listed Champaner-Pavagadh Archaeological Park.', '1-2 hours', 'October to March, early morning for soft light on the carvings', 'Footwear must be removed before entering; dress modestly. Take a local auto-rickshaw between the spread-out monuments.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Rs 35', 5, 5, 22.4858869, 73.534987, 'Champaner, Panchmahal, Gujarat 389360', NULL, 1.0);

