INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000363, 332015, 'Kevda Masjid', 'Kevda Masjid and Cenotaph', 'A 15th-century mosque in the archaeological park with five globe-like domes, two minarets and narrow stairs, known for integrating natural and vegetal forms into its carved stonework. A square cenotaph with a fluted dome and an old ablution tank stand beside it. An ASI Monument of National Importance within the UNESCO park.', '45 minutes', 'October to March', 'Combine with Nagina Masjid and the helical stepwell on a single auto-rickshaw circuit; the complex is spread over a few kilometres.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 5, 4, 22.489371, 73.531351, 'Champaner, Panchmahal, Gujarat 389360', NULL, 0.92);

