INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000364, 332015, 'Nagina Masjid', 'Nagina Masjid and Cenotaph', 'The ''Jewel Mosque'', built in the 15th century under Mahmud Begada, named for the white-stone finish of its construction. It has three domes, two minarets and finely carved geometrical and vegetal motifs. Its cenotaph stands immediately alongside. An ASI Monument of National Importance within the UNESCO park.', '30-45 minutes', 'October to March', 'Visit alongside Kevda Masjid nearby; the white-stone domes photograph best in morning light.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 4, 4, 22.4941482, 73.5290356, 'Champaner, Panchmahal, Gujarat 389360', NULL, 0.8);

