INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000365, 332015, 'Sahar ki Masjid', 'Sahar ki Masjid', 'A former mosque inside the old citadel walls, described by visitors as the royal family''s private mosque, with elegant proportions and carved interiors. Traveler reports note that an entry fee is charged here. An ASI Monument of National Importance (Bohrani) within the UNESCO park.', '30-45 minutes', 'October to March, early morning', 'Ask at the site for the ASI''s Indian World Heritage Series booklet on Champaner, reported available on request.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Rs 35', 4, 4, 22.4836217, 73.529406, 'Champaner, Panchmahal, Gujarat 389360', NULL, 0.8);

