INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000375, 332015, 'Champaner Citadel Walls and Gates', 'Citadel Walls and Bhadra Gates', 'The surviving fortifications of Mahmud Begada''s 16th-century capital, including the East and South Bhadra Gates and stretches of citadel and city wall rising toward Pavagadh hill. The walls are ASI Monuments of National Importance within the UNESCO park.', '45 minutes', 'October to March, early morning', 'The walls frame Sahar ki Masjid and Jami Masjid; walk the east gate stretch for the best masonry views.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 3, 3, 22.483365, 73.531211, 'Champaner, Panchmahal, Gujarat 389360', NULL, 0.6);

