INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000376, 332015, 'Kalika Mata Temple, Pavagadh', 'Kalika Mata Temple', 'A 10th-11th century hilltop shrine to Mahakali on the 800-metre Pavagadh summit, about 5 km from Champaner, and one of the 51 Shakti Peethas. The central idol is only the red-painted head (mukhwato). Reachable by a 5 km forest trail or the ropeway from the midway station.', 'Half day', 'October to March; Navratri draws the largest crowds', 'Take the ropeway up to skip the steep climb; carry water and sturdy shoes if walking. Photography is restricted inside the inner sanctum.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 5, 4, 22.46111, 73.51167, 'Pavagadh Hill, Panchmahal, Gujarat 389360', NULL, 0.92);

