INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000377, 332015, 'Jain Temples, Pavagadh', 'Jain Temples of Pavagadh', 'A group of ancient Jain temples on Pavagadh hill, part of the fort and ruined Hindu and Jain temples complex protected by ASI on the hilltop, about 5-6 km from Champaner. Pavagadh was an ancient Jain pilgrimage centre before the hill fort era.', '1-2 hours', 'October to March', 'Combine with the Kalika Mata temple and fort gates on the same hill circuit; the old stone path has many steps.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 4, 4, 22.466935, 73.515211, 'Pavagadh Hill, Panchmahal, Gujarat 389360', NULL, 0.8);

