INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000378, 332015, 'Pavagadh Fort Gates (Atak Gate onwards)', 'Pavagadh Fort Gates', 'The chain of fortified gateways up Pavagadh hill — Atak Gate (No.1), Budhiya Gate (No.2), Moti/Sadanshah Gate (No.3), Gate No.4 with its bastion, Sat Manzil and the higher gates — built along the steep ascent to the hill fort, about 5-6 km from Champaner. All are ASI Monuments of National Importance within the UNESCO park.', '2-3 hours', 'October to March, early morning', 'This is a real climb on old stone steps; carry water and allow 2-3 hours if walking the full gate sequence.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 4, 4, 22.4764002, 73.530729, 'Pavagadh Hill, Panchmahal, Gujarat 389360', NULL, 0.8);

