INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3320054, 332, 332015, 'Navratri at Pavagadh Kalika Mata Temple', 'September-October', 'The hilltop Mahakali temple is one of Gujarat''s biggest Navratri pilgrimage centres. Large crowds of devotees gather on Pavagadh hill during the nine nights of worship of Goddess Shakti, with the hill illuminated and special rituals held at the shrine.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3320055, 332, 332015, 'Chaitra Fair at Pavagadh', 'March-April', 'A traditional fair is held at the Kalika Mata temple on the hill on Chitra sud 8, attended by thousands of devotees, continuing a centuries-old pilgrimage tradition.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3320056, 332, 332015, 'Dasara Gathering at Pavagadh', 'October', 'Large gatherings of devotees assemble at the Kalika Mata temple at Dasara, alongside the temple''s ongoing festival calendar, drawing pilgrims of all communities to the hill.');

