INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000388, 332016, 'Swaraj Ashram', 'Swaraj Ashram', 'The 1928 Bardoli Satyagraha headquarters of Sardar Vallabhbhai Patel, now a living memorial complex in the heart of Bardoli. The grounds host the Sardar Patel Art Gallery, the Mukul Trust and Sardar Kanya Vidhyalaya institutions, and frequently host local festivals, trade fairs and cultural programs. Gujarat CM Bhupendra Patel visited the ashram in June 2026. The Aitihasik Ambo (historic mango tree linked to the satyagraha) stands in this area.', '1-2 hours', 'October to March; early morning or late afternoon', 'Combine with the Sardar Patel museum nearby; ask locally about the art gallery and any ongoing events on the grounds.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 5, 4, 21.127537, 73.108361, 'Station Road, opposite Bardoli College, Bardoli, Gujarat 394601', NULL, 0.92);

