INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 332000388, 'insert', 'bulk', 'Existence and location confirmed via map location data (Station Rd opp. College, Bardoli) and the airial.travel Bardoli guide; the ashram remains active (Gujarat CM Bhupendra Patel visited 2026-06-12 per ANI/Daily Prabhat/LatestLY coverage). The previously listed official site swarajashram.business.site returned HTTP 404 when fetched on 2026-09-30, so no official website is listed.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000389, 332016, 'Sardar Vallabhbhai Patel National Memorial Museum', 'Sardar Vallabhbhai Patel National Memorial Museum', 'Government-run memorial museum at Sardar Baug in Bardoli dedicated to Sardar Vallabhbhai Patel, spread over about 20 rooms with rare photographs, dioramas, digital displays and a short film chronicling his life from the Bardoli Satyagraha to the integration of the princely states. One of the key heritage stops in the town.', '1-2 hours', 'October to March', 'Go on a weekday morning to avoid crowds; the museum is closed on Wednesdays.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 5, 4, 21.126118, 73.108862, 'Station Road, Sardar Baug, Bhuvneshwari Nagar Society, Bardoli, Gujarat 394601', NULL, 0.92);

