INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000390, 332016, 'BAPS Shri Swaminarayan Mandir, Sankri', 'BAPS Shri Swaminarayan Mandir, Sankri', 'Large, well-maintained BAPS Swaminarayan temple on Sankri Main Road east of Bardoli town, popular with devotees and rated among the top religious places in the Bardoli area. Ornate carved architecture with daily aarti and a peaceful campus; a good family and photography stop.', '1 hour', 'October to March; mornings or evenings for aarti', 'Dress modestly and remove footwear before entering the inner sanctum; mornings are the calmest.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 5, 4, 21.157622, 73.161558, 'Sankri Main Road, Sankri, Bardoli, Gujarat 394601', NULL, 0.92);

