INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000402, 332016, 'Dumas Beach', 'Dumas Beach', 'Surat''s most famous beach, about 21 km southwest of Surat (roughly 55 km from Bardoli), known for its dark grey-black sand and wide shoreline. Popular for evening walks, sunsets and beachside street food stalls like Lashkari Bhajiya; local legend calls it haunted, which adds to its fame. Swimming is discouraged due to strong currents. A good half-day coastal outing from Bardoli.', '2-3 hours', 'October to March; evenings for sunset', 'Go for sunset and the food stalls; do not swim - currents are strong and the beach is unsafe for bathing. The Dariya Ganesh Temple sits adjacent to the beach.', NULL, 'Gujarat', 0, 1, NULL, '18:30', 'Free', 5, 4, 21.08484, 72.70949, 'Dumas, Surat, Gujarat 394550', NULL, 0.92);

