INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000403, 332016, 'Dutch Garden', 'Dutch Garden', 'Historic riverside garden in Nanpura, Surat (about 35 km from Bardoli), once the Dutch East India Company cemetery area, now a quiet European-style landscaped park on the Tapi riverfront. Good for a relaxed morning or evening stroll combined with old-city Surat sightseeing.', '1 hour', 'October to March; mornings or evenings', 'Combine with a Tapi riverfront walk and Nanpura market; mornings are quietest.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 4, 4, 21.19151, 72.81484, 'Dutch Garden Road, Nanpura, Surat, Gujarat 395001', NULL, 0.8);

