INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 332000403, 'insert', 'bulk', 'Confirmed via triphobo.com Surat guide (Dutch Garden Rd, Nanpura, Surat; free entry per triphobo Q&A) and airial.travel Surat guide; coordinates verified with map geocoder (21.19151, 72.81484). Distance approx 35 km from Bardoli. Official hours not published by any authoritative source.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000404, 332016, 'Ambika Niketan Temple', 'Ambika Niketan Temple', 'Prominent Shakti temple on the banks of the Tapi river at Athwalines, Surat (about 35 km from Bardoli), built in 1969 by devotee Smt Bharati Maiya. The two-storied temple houses the eight-armed Ashtabhuja Ambika idol plus shrines of Shiva, Ram-Sita and Lakshminarayan; Navratri is celebrated with great fervor. The trust also runs charitable services.', '1-2 hours', 'October to March; mornings or evenings for aarti (7 AM and 7 PM)', 'Visit during Navratri for the festive decorations and garba; morning aarti at 7 AM is the calmest.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 5, 4, 21.178275, 72.793086, 'Dumas Road, Parle Point, Athwalines, Surat, Gujarat 395007', 'https://shriambikaniketantrust.org/', 0.92);

