INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000405, 332016, 'Sarthana Nature Park & Zoo', 'Sarthana Nature Park & Zoo', 'Dr. Shyamaprasad Mukherjee Zoological Garden - Surat''s zoo and nature park on the Surat-Kamrej highway (about 40 km from Bardoli), spread over 81 acres along the Tapi with animals in simulated natural habitats. Run by the Surat Municipal Corporation; a solid family half-day trip.', '3-4 hours', 'October to March', 'Go right at opening (10 AM) when animals are most active; carry water - it is a large campus.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Rs 30', 5, 4, 21.232338, 72.89879, 'Surat-Kamrej Road, opposite old Sarthana octroi naka, Surat, Gujarat 395006', 'https://www.suratmunicipal.gov.in/Services/NatureParkHome', 0.92);

