INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000406, 332016, 'Ukai Dam', 'Ukai Dam', 'One of Gujarat''s largest reservoirs (also called Vallabh Sagar) on the Tapi river, built in 1972 - about 60 km from Bardoli. The dam and its vast water body draw visitors for sunsets, bird watching, boating and photography, especially in winter. Surrounding villages and the Giri waterfalls nearby add to the outing.', '2-3 hours', 'October to March', 'Evening is best for sunset views over the reservoir; winters bring migratory birds.', NULL, 'Gujarat', 0, 1, NULL, NULL, NULL, 4, 4, 21.25609, 73.594882, 'Ukai, Fort-Songadh, Tapi District, Gujarat', NULL, 0.8);

