INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000407, 332016, 'Vansda National Park', 'Vansda National Park', 'National park in the Sahyadri/Western Ghats foothills of the Dang region (about 95 km from Bardoli), dense moist-deciduous forest home to leopards, wild boar, barking deer, civets, pangolins and 150+ bird species. Entry from the Kilad village gate; drive through the 4 km designated route in your own vehicle with a guide. A full-day nature trip from Bardoli, combinable with Kilad campsite stays.', '4-6 hours (full day trip)', 'November to February; park closed mid-June to mid-October (monsoon)', 'Start early (8 AM) for the best wildlife sightings; carry water and snacks - no food stalls inside; two-wheelers not allowed.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Rs 20', 5, 4, 20.76386, 73.48631, 'Waghai-Ahwa Road, Vaghai, Vansda, Gujarat 394730', NULL, 0.92);

