INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000414, 332017, 'Shree Dwarkadhish Temple', 'Dwarkadhish Temple (Jagat Mandir)', 'The principal temple of Dwarka, dedicated to Lord Krishna as Dwarkadhish, King of Dwarka. One of the four Char Dham pilgrimage sites, the 5-storey Jagat Mandir rises ~43 m on 72 pillars and is the spiritual heart of the city; general darshan is free.', '1–2 hours', 'Early morning (6:30–8 AM) or evening aarti, October–March', 'The temple closes 1:00–5:00 PM (Anosar); time your visit for the morning or evening darshan window.', 0, 'Gujarat', 0, 0, NULL, NULL, 'Free (general darshan); special entry ₹200, donor ₹500+', 5, 5, 22.2381, 68.96724, 'Shree Dwarkadhish Temple, Dwarka, Devbhumi Dwarka, Gujarat 361335', 'https://www.dwarkadhish.org/', 1.0);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (332000414, 332000414, '6:30 AM – 1:00 PM, 5:00 PM – 9:30 PM', '6:30 AM – 1:00 PM, 5:00 PM – 9:30 PM', '6:30 AM – 1:00 PM, 5:00 PM – 9:30 PM', '6:30 AM – 1:00 PM, 5:00 PM – 9:30 PM', '6:30 AM – 1:00 PM, 5:00 PM – 9:30 PM', '6:30 AM – 1:00 PM, 5:00 PM – 9:30 PM', '6:30 AM – 1:00 PM, 5:00 PM – 9:30 PM', 'Closed 1:00–5:00 PM daily (Anosar). Timings from the temple''s official timetable fact-sheet PDF (uploaded May 2022); festival schedules differ (e.g., Janmashtami darshan runs past midnight).');

