INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000416, 332017, 'Nageshwar Jyotirlinga', 'Nageshwar Jyotirlinga Temple', 'One of the 12 Jyotirlingas, ~16 km from Dwarka at Darukavanam, with an ~80-ft seated Shiva statue in the complex. General darshan is free; the midday closure makes morning or evening the practical window.', '1–2 hours', 'Morning or evening, October–March', 'Pair it with Gopi Talav, about 5 km away, to fill the afternoon.', 0, 'Gujarat', 0, 0, NULL, NULL, 'Free (general darshan)', 5, 5, 22.33613, 69.0866, 'Dwadash Jyotirlinga Shri Nageshwar Mahadev Temple, Darukavanam, Okhamandal, Devbhumi Dwarka, Gujarat 361335', NULL, 1.0);

