INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000417, 332017, 'Rukmini Devi Temple', 'Rukmini Devi Temple', 'A 12th-century temple ~2 km from Dwarka town dedicated to Rukmini, Krishna''s queen, whose idol is adorned with intricate carvings. The legend of Durvasa''s curse explains why it stands apart from the Dwarkadhish Temple.', '45 minutes – 1 hour', 'Morning or late afternoon, October–March', 'Combine with Dwarka Beach/Sunset Point nearby; it''s a short auto ride from the main temple.', 0, 'Gujarat', 0, 0, NULL, NULL, 'Free', 4, 4, 22.25698, 68.96443, 'Rukmini Temple, Ghanshyam Nagar, Dwarka, Devbhumi Dwarka, Gujarat 361335', NULL, 0.8);

