INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000418, 332017, 'Gomti Ghat', 'Gomti Ghat', 'The sacred riverfront steps on the Gomti river right behind the Dwarkadhish Temple, where pilgrims take a holy dip before darshan. A short walk downstream leads to the Gomti–Arabian Sea confluence and the Sudama Setu.', '30–45 minutes', 'Sunrise, October–March', 'Do the traditional sequence: holy dip at the ghat first, then temple darshan.', 0, 'Gujarat', 1, 1, '06:50', '18:30', 'Free', 4, 4, 22.2381, 68.96869, 'Gomti Ghat, behind Dwarkadhish Temple, Dwarka, Devbhumi Dwarka, Gujarat 361335', NULL, 0.8);

