INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000440, 332018, 'Shri Somnath Jyotirlinga Temple', 'Somnath Temple (First Jyotirlinga)', 'The first of the twelve Jyotirlingas, the Somnath Temple at Prabhas Patan stands on the Arabian Sea coast in the Chalukya (Māru-Gurjara) style with a 150-foot shikhara. It was destroyed and rebuilt multiple times over a thousand years; the present temple was reconstructed after independence on the resolve of Sardar Vallabhbhai Patel and inaugurated by President Dr Rajendra Prasad on 11 May 1951.', '2-3 hours', 'October to March; early morning 6:00-8:00 AM for the quietest darshan', 'Mobile phones, cameras, smartwatches and leather items are strictly prohibited inside; use the free lockers at the main gate and arrive by 6:45 PM if you want a good spot for the 7:00 PM Sandhya Aarti.', NULL, 'Gujarat', 1, 1, NULL, NULL, 'Free', 5, 5, 20.888, 70.4012, 'Somnath, Prabhas Patan, Gir Somnath, Gujarat 362268', 'https://www.somnath.org', 1.0);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (332000440, 332000440, '06:00-21:00', '06:00-21:00', '06:00-21:00', '06:00-21:00', '06:00-21:00', '06:00-21:00', '06:00-21:00', 'Aartis at 7:00 AM (Mangala), 12:00 PM (Madhyahna) and 7:00 PM (Sandhya); closing varies 9:00-10:00 PM by source/season. Timings cross-checked across templetimings.in, mandirtimings.com, tirumalaonline.in; official timings listed at somnath.org.');

