INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 332000440, 'insert', 'bulk', 'Darshan hours 6:00 AM-9:00 PM and aartis 7:00 AM / 12:00 PM / 7:00 PM confirmed across multiple published timing guides; free general darshan confirmed. somnath.org fetched 2026-09-30 and loads as the official Shree Somnath Trust site (online booking portal). 1951 reconstruction by Patel / inauguration by Rajendra Prasad from dharmapedia + ClearIAS-style history pieces.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000441, 332018, 'Jay Somnath Sound and Light Show', 'Jay Somnath Sound & Light Show', 'A 45-60 minute narrated audio-visual show staged in the open-air theatre on the sea-facing side of the Somnath Temple complex, telling the temple''s history of repeated destruction and reconstruction. Narration is offered in Hindi, Gujarati and English. It is suspended during the monsoon (roughly July-September) when sea conditions make the open-air show unviable.', '1-1.5 hours', 'Evening, October to May (after attending the 7:00 PM Sandhya Aarti); seats fill fast so be seated by ~7:50 PM', 'Attend the 7:00 PM Sandhya Aarti first, exit by 7:45 PM and buy show tickets at the counter near the temple entrance — tickets cannot be booked online.', 'Not available — tickets only at the on-site counter near the temple entrance', 'Gujarat', 0, 1, NULL, NULL, 'Rs 25', 5, 4, 20.8885, 70.4006, 'Open-air theatre, Shree Somnath Temple complex, Prabhas Patan, Gujarat 362268', NULL, 0.92);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (332000441, 332000441, '20:00-21:00', '20:00-21:00', '20:00-21:00', '20:00-21:00', '20:00-21:00', '20:00-21:00', '20:00-21:00', 'Some sources list 7:45 PM-8:45 PM; Trust schedules vary seasonally and the show is cancelled in heavy rain/monsoon. Verify locally or at somnath.org on the day.');

