INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 332000441, 'insert', 'bulk', 'Show timing 8:00-9:00 PM, ticket price Rs 25-50 (tripadvisor review cites Rs 25 adult / Rs 15 child; guides cite Rs 30-50), on-site counter only, and monsoon suspension confirmed across templetimings.in, dubaiuae.in, tirumalaonline.in and nearestmetrostation.com guides.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000442, 332018, 'Baan Stambh', 'Baan Stambh (Arrow Pillar)', 'A stone pillar on the sea-protection wall of the Somnath Temple complex bearing a Sanskrit inscription stating that there is no land mass in a straight line from this point to the South Pole. The Shree Somnath Trust describes it as indicating an unobstructed sea route southward — a popular symbol of ancient Indian maritime and geographical knowledge.', '15-30 minutes', 'Morning for sea views; pairs naturally with the temple darshan', 'Stand at the seawall just south of the temple and look due south — the Arabian Sea stretches to the horizon with no land between you and Antarctica.', NULL, 'Gujarat', 0, 1, NULL, NULL, 'Free', 4, 4, 20.8878, 70.4021, 'Sea-protection wall, Shree Somnath Temple complex, Prabhas Patan, Gujarat 362268', NULL, 0.8);

