INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 332000442, 'insert', 'bulk', 'Existence, location on the temple seawall and the Sanskrit inscription about no land between the point and the South Pole confirmed via indiaworldeye.com, dharmapedia wiki and Wanderlog; the Shree Somnath Trust''s own description (nearest land ~9,936 km away) cited in a 2026 analysis video. No ticketed entry; hours follow the temple complex.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000443, 332018, 'Somnath Beach', 'Somnath Beach', 'The clean, serene beach directly behind and beside the Somnath Temple on the Arabian Sea. It is best for walks, sunrise/sunset viewing and photography rather than swimming, as the sea can be rough and strong currents are common. The beach adjoins the temple promenade and is calmest at dawn before the pilgrim crowds arrive.', '30-60 minutes', 'Sunrise or sunset; October to March', 'Best enjoyed as a stroll before or after darshan; swimming is not advised. Visit at sunrise for near-empty sands and views of the temple spire from the shore.', NULL, 'Gujarat', 1, 1, NULL, NULL, 'Free', 4, 4, 20.8868, 70.3978, 'Behind Shree Somnath Temple, Prabhas Patan, Gujarat 362268', NULL, 0.8);

