INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000444, 332018, 'Somnath Promenade', 'Somnath Promenade', 'A ~1.5 km sea-facing walkway along the Somnath coastline developed under the PRASHAD (Pilgrimage Rejuvenation and Spiritual, Heritage Augmentation Drive) scheme at a cost of over Rs 47 crore, announced by the PMO in August 2021. It connects the temple complex area along the shore with landscaping, lighting and seating, making it the best evening walk in town after darshan.', '30-60 minutes', 'Evening, after the Sandhya Aarti', 'Walk the full stretch at dusk when the temple is illuminated; it is lit in the evenings and much quieter than the temple courtyard.', NULL, 'Gujarat', 0, 1, NULL, NULL, 'Free', 3, 4, 20.889, 70.4035, 'Sea-facing promenade, Somnath coast, Prabhas Patan, Gujarat 362268', NULL, 0.68);

