INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000445, 332018, 'Triveni Sangam', 'Triveni Sangam (Confluence of Hiran, Kapila, Saraswati)', 'The sacred confluence of the three holy rivers Hiran, Kapila and Saraswati, about 1.5-2 km east of the Somnath Temple. Pilgrims bathe here for moksha; tradition holds that the Pandavas bathed here and that Lord Krishna took his last bath here before departing his mortal body. The Gita Mandir, Lakshminarayan Temple and several other shrines stand on its ghats.', '45-60 minutes', 'Early morning for bathing rituals; sunset for views', 'Combine with Gita Mandir, Dehotsarg Tirth and Suraj Mandir, all clustered within a kilometre along the ghats.', NULL, 'Gujarat', 1, 1, NULL, NULL, 'Free', 5, 4, 20.8872, 70.4088, 'Triveni Ghat, Prabhas Patan, Somnath, Gujarat 362268', NULL, 0.92);

