INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000446, 332018, 'Gita Mandir', 'Gita Mandir (Birla Temple)', 'A white-marble Krishna temple on the banks of the Triveni Sangam, built by the Birla family in 1970 (also called Birla Mandir). Its 18 marble pillars carry verses of the Shrimad Bhagavad Gita engraved in Sanskrit, and the hall is designed so devotees'' bhajans echo inside. Tradition places it where Lord Krishna rested after walking ~4 km from Bhalka Tirth.', '30-45 minutes', 'Morning; combine with Triveni Sangam', 'Read the Gita shlokas on the 18 pillars and stand in the centre of the echoing hall — the acoustics are the temple''s signature.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 4, 4, 20.8859, 70.4096, 'Triveni Ghat, Prabhas Patan, Somnath, Gujarat 362268', NULL, 0.8);

