INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 332000446, 'insert', 'bulk', 'Built by the Birla family in 1970, 18 marble pillars with Gita verses, Krishna idols with Lakshminarayan and Sita-Ram on either side, and the 4 km walk tradition from Bhalka confirmed via triphobo.com and the Gujarat tourism listing (coloursofgujarat.com).', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000447, 332018, 'Dehotsarg Tirth', 'Dehotsarg Tirth (Golokdham Tirth)', 'The spot near the Triveni Sangam where Lord Krishna is believed to have given up his mortal body and departed for Golokdham after walking from Bhalka Tirth. A small temple complex marks the site. It is one of the three great Krishna leela sthals of Prabhas Kshetra, alongside Bhalka Tirth and the Gita Mandir.', '30 minutes', 'Morning, as part of the Triveni temple circuit', 'Visit after Bhalka Tirth and Gita Mandir to follow the Krishna-leela sequence: wound, rest, and dehotsarg (departure).', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 4, 3, 20.8847, 70.4108, 'Near Triveni Ghat, Prabhas Patan, Somnath, Gujarat 362268', NULL, 0.72);

