INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000448, 332018, 'Shree Parshuram Temple', 'Shree Parshuram Temple', 'An ancient temple on the banks of the Triveni dedicated to Lord Parshuram, the sixth avatar of Vishnu, where he is believed to have done penance for years. The premises contain two ancient kunds (holy water tanks) and the shrine stands on the Triveni ghats amid the cluster of Somnath''s older temples.', '30 minutes', 'Morning, with the Triveni circuit', 'Descend to the two ancient kunds within the temple premises — they are the temple''s oldest features.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 3, 3, 20.8864, 70.4076, 'Triveni Ghat, Prabhas Patan, Somnath, Gujarat 362268', NULL, 0.6);

