INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000449, 332018, 'Lakshminarayan Temple', 'Lakshminarayan Temple', 'A large, imposing temple on the Triveni ghats dedicated to Lakshminarayan (Lord Vishnu with Lakshmi). It is one of the principal Vishnu shrines of Prabhas Kshetra and sits on the ghats close to the Gita Mandir, forming part of the standard Triveni temple circuit.', '20-30 minutes', 'Morning, with the Triveni circuit', 'Visit right after the Gita Mandir — the two temples are within a short walk on the same ghats.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 3, 3, 20.8856, 70.4092, 'Triveni Ghat, Prabhas Patan, Somnath, Gujarat 362268', NULL, 0.6);

