INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 332000449, 'insert', 'bulk', 'Location on the Triveni ghats and Lakshminarayan as the presiding deity confirmed via testbook.com''s Somnath guide and triphobo.com''s listing.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000450, 332018, 'Suraj Mandir', 'Suraj Mandir (Sun Temple)', 'An ancient temple dedicated to Surya, the Sun God, on the northern side of Triveni Ghat, believed to be nearly as old as the original Somnath Temple (traditionally ~5,000 years old). Above the entrance doorway sits an image of Surya riding seven horses with his two wives; the walls carry fine sculptures of elephants, lions and deity niches of Vishnu-Lakshmi, Brahma-Saraswati and Shiva-Parvati.', '30-45 minutes', 'Early morning, when the east-facing temple catches the rising sun', 'Look for the image of Surya with seven horses above the doorway and the small kund (pond) steps nearby; sunset views here are also good.', NULL, 'Gujarat', 1, 1, NULL, NULL, 'Free', 4, 4, 20.8886, 70.4112, 'Northern side of Triveni Ghat, Prabhas Patan, Somnath, Gujarat 362268', NULL, 0.8);

