INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000451, 332018, 'Kamnath Mahadev Temple', 'Kamnath Mahadev Temple', 'A roughly 200-year-old Shiva temple complex opposite the Triveni Sangam, built by King Mayurdhwaj. The name ''Kamnath'' means the fulfiller of desires. The complex has a holy pond and kunds whose waters are believed to cure ailments, and a cave associated with Adi Shankaracharya''s meditation.', '45-60 minutes', 'Morning; combine with Panch Pandav Gufa directly opposite', 'The temple sits directly across from Panch Pandav Gufa — cover both in one stop on the Triveni circuit.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 4, 4, 20.8876, 70.4126, 'Near Triveni Sangam Ghat, Prabhas Patan, Somnath, Gujarat 362268', NULL, 0.8);

