INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000452, 332018, 'Panch Pandav Gufa', 'Panch Pandav Gufa (Panch Pandav Cave)', 'A cave complex near Triveni Sangam, opposite the Kamnath Mahadev Temple, where the five Pandavas are believed to have taken refuge during their exile in the Mahabharata era. The site combines the cave shrine with a small temple, and sits on the outskirts route of Somnath''s temple circuit.', '30-45 minutes', 'Morning, with Kamnath Mahadev Temple', 'The caves are compact — 30 minutes is plenty; pair with Kamnath Mahadev directly across the road.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 3, 3, 20.8881, 70.4132, 'Near Kamnath Mahadev Temple, Prabhas Patan, Somnath, Gujarat 362268', NULL, 0.6);

