INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 332000452, 'insert', 'bulk', 'Pandava exile legend and location near/outskirts of Somnath confirmed via faceofgujarat.in and virtualtourist.com; position opposite Kamnath Mahadev Temple confirmed by tripadvisor review excerpts.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000453, 332018, 'Shri Ahilyabai Temple', 'Ahilyabai Temple (Old Somnath Temple)', 'The old Somnath temple standing within the main temple complex, built by Rajmata Ahilyabai Holkar of Indore in 1783 (renovated 1950) after the shrine''s repeated destructions. It enshrines a Shivlinga that is still actively worshipped and sits adjacent to the new Jyotirlinga temple, so it is covered naturally during the main darshan.', '30 minutes', 'During temple hours, alongside the main darshan', 'Look for this older shrine just beside the main temple — many visitors walk past it; it carries the pre-1951 worship continuity of Somnath.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 4, 4, 20.8883, 70.4008, 'Shree Somnath Temple complex, Prabhas Patan, Gujarat 362268', NULL, 0.8);

