INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 332000453, 'insert', 'bulk', 'Built by Ahilyabai Holkar (1783), enshrining an actively worshipped Shivlinga beside the main temple, confirmed via templesmap.com nearby-attractions listing and Wanderlog Kamnath excerpt; Gujarat tourism listing notes the old temple renovated in 1950.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000454, 332018, 'Bhalka Tirth', 'Bhalka Tirth', 'The sacred site about 4-5 km east of the Somnath Temple on the Prabhas-Veraval highway where Lord Krishna is believed to have been accidentally struck by the hunter Jara''s arrow while resting in meditation under a peepal tree — marking the end of the Dwapar Yuga. The temple houses Krishna in a reclining (tribhangi) posture, a tulsi tree growing through the roof, and two Shiva lingas.', '45-60 minutes', 'Morning; reachable by taxi/auto from near the Somnath Temple', 'Follow the Krishna-leela trail: Bhalka Tirth (wounding) → Gita Mandir (rest) → Dehotsarg Tirth (departure).', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 5, 4, 20.8812, 70.429, 'Bhalka, Prabhas-Veraval Highway, Gujarat 362265', NULL, 0.92);

