INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 332000454, 'insert', 'bulk', 'Jara''s arrow legend, ~4-5 km distance from the Somnath Temple, reclining Krishna idol and the tulsi tree confirmed via faceofgujarat.in, virtualtourist.com and webindia123.com; hours 6:00 AM-7:30 PM from the Gujarat tourism listing.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000455, 332018, 'Prabhas Patan Museum', 'Prabhas Patan Museum', 'An archaeological museum near the Somnath Temple (by the check post), established in 1951 and maintained by the Government of Gujarat. It displays nearly 3,500 objects across art, archaeology and natural history — stone sculptures, 11th-12th century toranas and idols (Agni, Uma Maheshwara, Vishnu, Natya Bhairava), inscriptions, pottery shards, seashells and a glass case holding waters of the world''s rivers and seas.', '1 hour', 'Late morning, 10:30 AM-1:00 PM', 'The sculpture gallery of temple fragments from earlier Somnath shrines is the highlight — it shows what the pre-destruction temples looked like.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Rs 5', 3, 3, 20.8912, 70.4046, 'Near Check Post, Prabhas Patan, Somnath, Gujarat 362268', NULL, 0.6);

