INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 332000455, 'insert', 'bulk', 'Established 1951, ~3,500 exhibits, timings 10:30 AM-5:30 PM, entry Rs 5 Indians / Rs 50 foreigners / Rs 100 camera confirmed via trawell.in and gujaratexpert.com; closed Wednesdays per trawell.in and MakeMyTrip tripideas.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000456, 332018, 'Junagadh Gate', 'Junagadh Gate', 'The historic triple-arched gateway of Somnath, the ancient entry to the temple town from the Veraval side, built centuries ago with intricate carvings. Tradition holds that Mahmud of Ghazni broke through this gate in 1026 AD during his invasion that destroyed the temple. It remains one of the town''s oldest surviving monuments.', '15-20 minutes', 'Morning or late afternoon for photographs', 'It is on the main road into town — pause here en route between Veraval and the temple rather than making a separate trip.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 3, 3, 20.8946, 70.4142, 'Somnath-Veraval Road, Prabhas Patan, Gujarat 362268', NULL, 0.6);

