INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000457, 332018, 'Chorwad Beach', 'Chorwad Beach (day trip)', 'A quiet beach about 28 km northwest of Somnath on the Porbandar road, far less crowded than the temple-front beach. It is a good half-day add-on for a relaxed seaside stop with fishing boats and wide sands, often paired with the drive toward Madhavpur or Porbandar.', '1-2 hours', 'Late afternoon for sunset; October to March', 'Treat it as a sunset detour on a longer coastal drive — there are few facilities, so carry water and snacks.', NULL, 'Gujarat', 0, 1, NULL, NULL, 'Free', 2, 3, 21.0244, 70.2367, 'Chorwad, Gir Somnath district, Gujarat 362250', NULL, 0.48);

