INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 332000457, 'insert', 'bulk', 'Day-trip beach ~28 km from Somnath on the Porbandar highway, widely listed in Somnath sightseeing guides. No ticketed entry.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000458, 332018, 'Gir National Park', 'Gir National Park (Sasan Gir, day trip)', 'About 65 km east of Somnath, Gir (Sasan Gir) is the only natural home of the Asiatic lion, with ~1,412 sq km of forest and the Devaliya safari zone offering near-guaranteed lion sightings. Declared a wildlife sanctuary in 1965, it is the classic wildlife day trip from Somnath; jungle safaris run morning and afternoon and must be booked well in advance in season.', 'Full day (3-4 hour safari + travel)', 'October to June; the park is closed roughly mid-June to mid-October for the monsoon', 'Book safari permits online well ahead — peak-season slots sell out; carry photo ID matching the booking. Devaliya bus safari is the fallback for guaranteed sightings.', 'Safari permits must be booked in advance online; carry matching photo ID', 'Gujarat', 0, 0, NULL, NULL, NULL, 4, 5, 21.1247, 70.7948, 'Sasan Gir, Talala, Gir Somnath district, Gujarat 362135', NULL, 0.88);

