INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000459, 332018, 'Mahabat Maqbara', 'Mahabat Maqbara (Junagadh, day trip)', 'About 85 km from Somnath in Junagadh, the 19th-century Mahabat Maqbara (built 1878-1892 by Nawab Bahadur Khan III for Mahabat Khan II) is an Indo-Islamic mausoleum fused with Gothic and European detailing — famous for its corkscrew minarets, onion domes, silver doors and stained glass. It is Junagadh''s most photographed monument and the natural anchor of a Junagadh day trip alongside Uparkot Fort.', '1 hour (half day for Junagadh)', 'Morning; October to February', 'Ask at the adjoining Jumma Masjid for someone to open the interior; combine with Uparkot Fort and the Durbar Hall Museum in the same half day.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 3, 4, 21.5188, 70.4592, 'Near Railway Station, Junagadh, Gujarat 362001', NULL, 0.68);

