INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000460, 332018, 'The Swad Restaurant', 'The Swad Restaurant', 'A popular pure-vegetarian multi-cuisine restaurant at Hotel Bliss on the Somnath Bypass Road, serving Gujarati, Punjabi and South Indian dishes with breakfast through late dinner. Listed as open 8:00 AM-11:30 PM daily on Justdial with strong recent ratings (4.4, ~1,728 ratings).', '45-60 minutes', 'Lunch or dinner; dinner crowds peak after 7:30 PM', 'Reliable veg thali and Punjabi options close to the temple bypass — a safe pick for families.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 4, 4, 20.8985, 70.406, 'Hotel Bliss, Somnath Bypass Road, Prabhas Patan, Somnath, Gujarat 362268', NULL, 0.8);

