INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000461, 332018, 'Bhabha Restaurant', 'Bhabha Restaurant (New Bhabha)', 'A long-running modest pure-vegetarian eatery opposite Leelavati Bhavan near the bus station in Prabhas Patan, known for Kathiyawadi and Gujarati comfort food with AC and open seating options. Listed as open 7:00 AM-11:30 PM daily; recommended by travel guides as an affordable, dependable veg joint near the temple.', '30-45 minutes', 'Breakfast or lunch', 'Order Kathiyawadi staples — it is the local-flavour counterpoint to the hotel restaurants.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 4, 3, 20.8946, 70.411, 'Opposite Leelavati Bhavan, Near Bus Station, Prabhas Patan, Somnath, Gujarat 362268', NULL, 0.72);

