INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000462, 332018, 'Sorath Mahal Restaurant', 'Sorath Mahal Restaurant', 'A vegetarian restaurant on the Una-Veraval Road near Somnath Railway Station with long hours (7:00 AM-midnight daily) and a strong rating base (~318 ratings). A convenient stop for travellers arriving by train before heading to the temple.', '30-45 minutes', 'Lunch or dinner', 'Handy if you arrive at Somnath railway station hungry — it is minutes from the station.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 3, 3, 20.8948, 70.4097, 'Una-Veraval Road, near Somnath Railway Station, Prabhas Patan, Gujarat 362268', NULL, 0.6);

