INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000463, 332018, 'Triveni Restaurant', 'Triveni Restaurant (The Fern Residency)', 'The in-house multi-cuisine vegetarian restaurant of The Fern Residency Somnath (4-star hotel behind Somnath railway station on the Veraval bypass), known for satvik-style Gujarati and Indian food with buffet and a la carte options. Confirmed operating by recent guest reviews (Dec 2025 stay) and the hotel''s official pages.', '45-60 minutes', 'Breakfast buffet or dinner', 'The most reliable upscale veg dining option near the temple; non-guests can dine but call ahead to confirm seating.', 'Call the hotel to confirm non-guest dining', 'Gujarat', 0, 0, NULL, NULL, NULL, 4, 4, 20.898, 70.4082, 'The Fern Residency, Behind Somnath Railway Station, Veraval Bypass, Prabhas Patan, Gujarat 362268', NULL, 0.8);

