INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000464, 332018, 'Blue Coriander', 'Blue Coriander (Lords Inn Somnath)', 'The in-house multi-cuisine vegetarian restaurant of Lords Inn Somnath on the Somnath-Veraval Bypass Road, Prabhas Patan — the chain''s signature veg restaurant brand. Shows very high recent enquiry/booking activity (~5,700+ ratings on Justdial), confirming it is currently operating.', '45-60 minutes', 'Lunch or dinner', 'Another dependable hotel-restaurant option on the bypass; pure veg like most Somnath dining.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 3, 4, 20.8988, 70.407, 'Lords Inn Somnath, Somnath-Veraval Bypass Road, Prabhas Patan, Gujarat 362268', NULL, 0.68);

