INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000466, 332019, 'Prag Mahal', 'Prag Mahal', '19th-century palace of Rao Pragmalji II (built 1865–1875) beside Aina Mahal in Bhuj''s old city. Corinthian-arcade facade, 45-foot Durbar Hall hung with taxidermy and royal memorabilia, and a clock tower with city views. Badly damaged in the 2001 earthquake and later restored.', '1.5–2 hours', 'Morning or late afternoon, October to March', 'Buy tickets early in the session; the palace closes for a long midday break and photography rules apply in the Durbar Hall.', 0, 'Gujarat', 0, 0, NULL, NULL, '₹20 per Indian adult (₹50–₹100 for foreign visitors reported)', 5, 4, 23.2552, 69.6693, 'Darbar Gadh Road, old city (beside Aina Mahal), Bhuj, Gujarat 370001', NULL, 0.92);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (332000466, 332000466, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Most travel guides report 9 AM–12 PM and 3–6 PM, but the reported weekly closing day varies (Thursday, Friday, and Saturday are each claimed by different sources). Confirm locally before visiting.');

