INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000467, 332019, 'Aina Mahal', 'Aina Mahal (Hall of Mirrors)', 'The 18th-century ''Palace of Mirrors'' built by Rao Lakhpatji (r. 1741–1760) with Dutch designer Ram Singh Malam, beside Prag Mahal. Venetian-glass mirrors, enamelled tiles, and a famously illuminated pleasure hall on the upper floor; the adjacent chhatri-style court rooms hold royal artefacts.', '1–1.5 hours', 'Morning or late afternoon, October to March', 'The best-lit interiors are on the upper floor; pair with Prag Mahal next door in the same morning or evening session.', 0, 'Gujarat', 0, 0, NULL, NULL, '₹20–₹30 per Indian adult (varies across travel guides)', 5, 5, 23.2553, 69.6688, 'Kodaki Road / Darbar Gadh, old city, Bhuj, Gujarat 370001', NULL, 1.0);

