INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000468, 332019, 'Bhujia Fort & Bhujia Hill', 'Bhujia Fort and Bhujia Hill', 'Hilltop fort (built 1715–1741 under Rao Godji I and Maharao Deshalji I) crowning Bhujia Hill east of the city. Partially ruined ramparts and gateways; the hill is now Bhuj''s most popular free viewpoint, with the city, Hamirsar Lake, and sunset panorama spread below. Bhujia''s shrine sits on the slope.', '2 hours', 'Sunset, or early morning in summer', 'Go 30–45 minutes before sunset for the best light and city views; carry water — the climb is short but exposed.', 0, 'Gujarat', 1, 1, NULL, NULL, 'Free', 4, 5, 23.2466, 69.6907, 'Bhujia Hill, east of Bhuj city, Bhuj, Gujarat 370001', NULL, 0.88);

