INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000469, 332019, 'Kutch Museum', 'Kutch Museum', 'Gujarat''s oldest museum (founded 1877 by Maharao Khengarji III), facing Hamirsar Lake. Holds Kshatrapa inscriptions, Kutchi embroidery and textiles, silverwork, coins, musical instruments, and the famed ''Airavat'' — an 11-sectioned stuffed elephant. Italianate colonial building.', '1–2 hours', 'Morning session, October to March', 'Closed Wednesdays and public holidays; the afternoon session starts at 2:30 PM. Camera ticket is separate.', 0, 'Gujarat', 0, 0, NULL, NULL, '₹5 per Indian visitor, ₹50 foreign, ₹100 for still camera (per travel guide)', 5, 4, 23.2486, 69.6664, 'Opposite Hamirsar Lake, Bhuj, Gujarat 370001', NULL, 0.92);

