INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000470, 332019, 'Hamirsar Lake & Rajendra Park', 'Hamirsar Lake and Rajendra Park', '450-year-old man-made lake at the heart of Bhuj, built in the reign of Rao Khengarji I and named after Rao Hamir. Island garden Rajendra Park (formerly Green Island) sits in the middle; the lakeside promenade is the city''s evening social centre. Overflows in good monsoons (''Augun'') are a local celebration.', '1 hour', 'Evening for the promenade; winter mornings for birds', 'Combine with Kutch Museum and Ramkund Stepwell across the road; the lake overflows in good monsoon years (July–September).', 0, 'Gujarat', 1, 1, NULL, NULL, 'Free', 4, 4, 23.2514, 69.6642, 'Hamirsar Lake, central Bhuj, Gujarat 370001', NULL, 0.8);

