INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000471, 332019, 'Sharadbaug Palace', 'Sharadbaug Palace', 'Early-20th-century palace of the Maharaos of Kutch, residence of the last king Madansingh until 1991, now a small museum. Tomb of the royal family nearby; gardens hold flowering and medicinal plants and attract migratory birds in winter.', '1 hour', 'Morning, October to March', 'Closed Fridays. The gardens are a good birding stop in winter — carry binoculars.', 0, 'Gujarat', 0, 0, NULL, NULL, '₹25 per person (per travel guides)', 3, 4, 23.2518, 69.6588, 'Opp. Khengarji Park, near Hamirsar Lake Road, Bhuj, Gujarat 370001', NULL, 0.68);

