INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000472, 332019, 'Chhatardi (Royal Cenotaphs)', 'Chhatardi – Jadeja Royal Cenotaphs', 'Umbrella-shaped royal cenotaphs (chhatris) of the Jadeja rulers of Kutch, mostly late-18th century, on the Bhuj outskirts. The largest, Rao Lakhpatji''s chhatri, was designed by Dutch architect Ram Singh Malam. Several were damaged in the 2001 earthquake, lending the site a romantic, ruinous air.', '1 hour', 'Morning or late afternoon, October to March', 'Open-access site with no formal entry — best visited in daylight; wear walking shoes as paths are uneven.', 0, 'Gujarat', 0, 1, NULL, NULL, 'Free', 3, 4, 23.2463, 69.6578, 'Near Ranjit Vilas / old city area, Bhuj, Gujarat 370001', NULL, 0.68);

