INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000473, 332019, 'Shri Swaminarayan Mandir Bhuj', 'Shri Swaminarayan Mandir, Bhuj', 'One of the original Swaminarayan Sampraday temples: Nar-Narayan Dev idols were installed here by Swaminarayan himself on 15 May 1823, on land gifted by the Gaekwads. Built near Hamirsar Lake in the old city, it remains a major pilgrimage centre of the sect.', '1 hour', 'Morning darshan; festivals (Janmashtami, Diwali) draw large crowds', 'Dress modestly; published darshan-session timings conflict across sources, so check with the temple office before planning a tight itinerary.', 0, 'Gujarat', 0, 0, NULL, NULL, 'Free', 4, 4, 23.2462, 69.6646, 'Opposite City Police Station, Tirth Dham, Bhuj, Gujarat 370001', NULL, 0.8);

