INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000474, 332019, 'Smritivan Earthquake Memorial & Museum', 'Smritivan Earthquake Memorial and Museum', 'India''s largest memorial-museum complex on 470 acres of Bhujia Hill, honouring the 12,932 victims of the 26 January 2001 Kutch earthquake. A tree was planted for every life lost across the hillside; the 50-acre museum has seven galleries on earthquakes, resilience, and the region''s rebirth. Inaugurated 28 August 2022.', '3–4 hours', 'Morning; museum opens 11 AM, memorial opens 5 AM', 'Closed Mondays. Reach by 9 AM to walk the memorial in cool light, then enter the museum at 11 AM. Carry water — the site is vast and exposed.', 0, 'Gujarat', 1, 1, NULL, NULL, 'Memorial: free 5–9 AM, ₹20/person after 9 AM. Museum: ₹300 adult, ₹100 child (<12), ₹150 college student, ₹1000 foreigner.', 5, 5, 23.2421, 69.6913, 'Bhujio Dungar, Bhuj, Gujarat 370020', 'https://www.smritivanearthquakemuseum.com/', 1.0);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (332000474, 332000474, NULL, 'Memorial 5:00 AM – 11:00 PM; Museum 11:00 AM – 7:00 PM', 'Memorial 5:00 AM – 11:00 PM; Museum 11:00 AM – 7:00 PM', 'Memorial 5:00 AM – 11:00 PM; Museum 11:00 AM – 7:00 PM', 'Memorial 5:00 AM – 11:00 PM; Museum 11:00 AM – 7:00 PM', 'Memorial 5:00 AM – 11:00 PM; Museum 11:00 AM – 7:00 PM', 'Memorial 5:00 AM – 11:00 PM; Museum 11:00 AM – 7:00 PM', 'Per official GSDMA page: closed Mondays. Museum 11 AM–7 PM; memorial grounds 5 AM–11 PM.');

