INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000475, 332019, 'Bharatiya Sanskriti Darshan', 'Bharatiya Sanskriti Darshan (Folk Museum)', 'Folk-art museum and cultural centre on College Road, founded ~60 years ago by Ramsinhji Rathod, scholar of Kutchi folk art. 4,500+ artefacts from Kutch''s villages: embroidery, beadwork, silver, woodwork, musical instruments, weapons, and the Sahitya Chitra library of ~1,500 rare books. Hut-shaped building with a carved stone doorway.', '1 hour', 'Morning or afternoon session, October to March', 'Closed Tuesdays; midday break between sessions — time your visit for 9 AM–12 PM or 3–6 PM.', 0, 'Gujarat', 0, 0, NULL, NULL, '₹5 per person (per travel guide)', 3, 4, 23.2421, 69.6625, 'College Road, Bhuj, Gujarat 370001', NULL, 0.68);

