INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000476, 332019, 'LLDC – Living and Learning Design Centre', 'Living and Learning Design Centre (LLDC)', 'World-class crafts museum by the Shrujan Trust at Ajrakhpur, ~15 km east of Bhuj on the Bhuj–Bhachau highway. Three galleries trace the embroidery and textile traditions of Kutch''s communities (Ahir, Rabari, Mochi, Meghwal and more), with a craft studio, library, gift shop, and vegetarian restaurant.', '2–3 hours', 'Morning, October to March', 'Closed Mondays and public holidays; last entry 5:15 PM. Book the in-house vegetarian restaurant meal in advance.', 0, 'Gujarat', 0, 0, NULL, NULL, '₹200 per adult, ₹50 per child (5–12 years)', 5, 5, 23.2367, 69.7998, '705, Bhuj–Bhachau Highway, Ajrakhpur, Gujarat 370105', 'http://www.shrujanlldc.org/', 1.0);

