INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000477, 332019, 'Bhujodi Weaving Village', 'Bhujodi Weaving Village', 'Living Vankar weaver village ~8 km southeast of Bhuj. Handloom workshops line the main street; watch weavers at pit looms and buy shawls, stoles, and blankets directly from the families who make them. Part of the classic Bhuj craft circuit with LLDC and Ajrakhpur.', '1.5–2 hours', 'Morning, October to March', 'Bargaining is expected but modest; buying directly from weavers (not middlemen) gets the best quality and price.', 0, 'Gujarat', 0, 0, NULL, NULL, 'Free (no entry fee; textiles sold by weavers)', 4, 5, 23.2246, 69.7384, 'Bhujodi village, Bhuj, Gujarat 370020', NULL, 0.88);

