INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000478, 332019, 'Tapkeshwari Devi Temple', 'Tapkeshwari Devi Temple', 'Hilltop shrine to goddess Tapkeshwari (an incarnation of Parvati) at the end of Tapkeshwari Road, ~7–8 km south of Bhuj. Temple at the base, caves and rock trails above; a quiet nature outing and a local favourite for sunset views over the Bhuj plain.', '2 hours', 'Late afternoon for sunset; September to February', 'Carry water and snacks — there are no shops at the site. The short steep path is in front of the temple; the longer valley path on the left suits older visitors.', 0, 'Gujarat', 1, 1, NULL, NULL, 'Free', 3, 4, 23.1801, 69.6651, 'Tapkeshwari Hill, end of Tapkeshwari Road (near Haripar), Bhuj, Gujarat 370015', NULL, 0.68);

