INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000479, 332019, 'Ramkund Stepwell', 'Ramkund Stepwell', 'Ancient square stepwell near Kutch Museum, behind the Ram Dhun Temple — 56 feet on each side. Geometrical carvings along the walls depict Ramayana figures (Ram, Sita, Lakshman, Hanuman) and the ten incarnations of Vishnu. Quiet, photogenic, and an easy add-on to the museum visit.', '30–45 minutes', 'Morning light, October to March', 'Combine with Kutch Museum across the road and Hamirsar Lake; the well is a short walk from both.', 0, 'Gujarat', 0, 0, NULL, NULL, 'Free', 3, 4, 23.2474, 69.6647, 'Near Kutch Museum, behind Ram Dhun Temple, Bhuj, Gujarat 370001', NULL, 0.68);

