INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000480, 332019, 'Great Rann of Kutch / Dhordo', 'Great Rann of Kutch – White Desert at Dhordo', 'Regional day trip (~86 km from Bhuj): the great white salt desert at Dhordo, home of the annual 3-month Rann Utsav festival. Endless white flats under a huge sky, camel-cart rides, folk performances in season, and famous full-moon nights. Dhordo was named a UNWTO Best Tourism Village (Oct 2023).', 'Full day (allow 2–3 hours drive round-trip)', 'November to February; full-moon nights are peak', 'Private vehicles need an entry permit at the checkpoint before Dhordo; carry it for the whole visit. Sunset and moonrise on the salt are the signature moments.', 0, 'Gujarat', 1, 1, NULL, NULL, '₹100 per Indian visitor / ₹200 foreign visitor (white desert entry, per travel guide)', 5, 5, 23.8064, 69.5125, 'Dhordo, Bhuj Taluk, Kutch, Gujarat 370510', NULL, 1.0);

