INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000481, 332019, 'Kalo Dungar & Dattatreya Temple', 'Kalo Dungar (Black Hill) and Dattatreya Temple', 'Regional day trip (~97 km from Bhuj): Kutch''s highest point at 462 m, with a panoramic view stretching to the Great Rann. The 400-year-old Dattatreya temple at the summit draws devotees; the hill is a popular sunset stop on the Dhordo–Bhuj route.', 'Half day; combine with Dhordo/White Rann', 'Sunset, October to March', 'Combine with the White Rann in one day — Kalo Dungar first, then Dhordo for sunset. Carry snacks; facilities are limited.', 0, 'Gujarat', 0, 1, NULL, NULL, 'Free', 4, 4, 23.9342, 69.8139, 'Kalo Dungar, 25 km from Khavda, Bhuj Taluk, Kutch, Gujarat', NULL, 0.8);

