INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000482, 332019, 'Mandvi Beach', 'Mandvi Beach', 'Regional day trip (~60 km from Bhuj): long sandy beach on the Arabian Sea at the historic port town of Mandvi. Camel and horse rides, water sports, and a famous sunset; the town is also known for its 400-year-old wooden dhow-building yards on the river.', 'Half to full day', 'Sunset; October to March', 'Visit in the late afternoon and stay for sunset; camel/horse ride and water-sport vendors are on the beach. The shipbuilding yards are a separate stop in town.', 0, 'Gujarat', 0, 1, NULL, NULL, 'Free (activities charged separately)', 4, 4, 22.8231, 69.3433, 'Rameshwar Colony, Mandvi, Kutch, Gujarat 370465', NULL, 0.8);

