INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000483, 332019, 'Vijay Vilas Palace, Mandvi', 'Vijay Vilas Palace', 'Regional day trip (~60 km from Bhuj, at Mandvi): the Maharaos of Kutch''s 1920–1929 summer palace on a 450-acre estate, built by Maharao Khengarji III for his son Vijayaraji in Rajput Indo-European style reminiscent of Orchha and Datia. Includes a privately owned beach and a heritage tented resort within the estate.', '2–3 hours', 'Morning or late afternoon, October to March', 'Palace visit combines well with Mandvi Beach nearby; Bollywood film shoots use the estate, so some areas may be temporarily closed.', 0, 'Gujarat', 0, 0, NULL, NULL, '₹20 entry; ₹50 camera; ₹10 vehicle (per government film-location listing)', 4, 4, 22.8347, 69.286, 'Vijay Vilas Palace Estate, near Mandvi Airstrip, Mandvi, Kutch, Gujarat 370465', NULL, 0.8);

