INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000484, 332019, 'Kera Shiva Temple', 'Shiva Temple, Kera (Lakheshwara Temple)', 'Regional day trip (~22 km south of Bhuj): 10th-century Chaulukya (Solanki) Shiva temple, also called Lakheshwara temple of Kerakot. Damaged by the earthquakes of 1819 and 2001, yet its spire, inner sanctum, and carvings survive — a state-protected monument (S-GJ-54) with an annual Mahashivratri fair.', '1–1.5 hours', 'Morning; Mahashivratri fair (Feb–Mar)', 'Road from Bhuj is good; the village of Kera has little tourist infrastructure, so carry water. Combine with a Bhujodi craft stop en route.', 0, 'Gujarat', 0, 0, NULL, NULL, 'Free', 3, 4, 23.0881, 69.5937, 'Kera village, Bhuj Taluk, Kutch, Gujarat 370430', NULL, 0.68);

