INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3320072, 332, 332019, 'Rann Utsav', 'November–February', 'Gujarat Tourism''s annual cultural festival on the white salt desert near Dhordo village (~80 km from Bhuj). Folk music and dance, crafts bazaars, camel rides, and full-moon nights on the salt flats; accommodation at the Rann Utsav Tent City. Permits required for private vehicles at the Dhordo checkpoint.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3320073, 332, 332019, 'Navratri', 'September–October', 'Nine nights of garba and dandiya-raas dancing celebrated across Gujarat, including Bhuj''s public grounds and community mandals; the largest Hindu festival of the region''s dance calendar.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3320074, 332, 332019, 'Uttarayan / Makar Sankranti', 'January', 'Gujarat''s international kite festival; the skies over Bhuj and Kutch fill with kites. Travelers are welcome to fly kites from terraces and open grounds.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3320075, 332, 332019, 'Mahashivratri', 'February–March', 'Night-long Shiva worship; the annual fair at the 10th-century Kera Shiva Temple (22 km south of Bhuj) and observances at Tapkeshwari Temple draw large local crowds.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3320076, 332, 332019, 'Augun – Hamirsar Lake Overflow', 'July–September (monsoon-dependent)', 'A uniquely Bhuj celebration: when monsoon rain fills Hamirsar Lake to overflowing (''Augun''), residents gather at the lake for the traditional overflow festivities. Occurs only in good monsoon years.');

