INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000492, 332020, 'Statue of Unity', 'Statue of Unity', 'The world''s tallest statue at 182 metres, dedicated to Sardar Vallabhbhai Patel, India''s first Deputy Prime Minister and the unifier of 565 princely states. Inaugurated on 31 October 2018, it stands on Sadhu Bet island in the Narmada river near the Sardar Sarovar Dam. A viewing gallery at 153 metres offers 360-degree views, and the base houses a museum and audio-visual gallery on Patel''s life.', '3-4 hours', 'October to February; early-morning slots for shorter queues and clearer views', 'Closed every Monday. Book viewing-gallery tickets on the official portal days ahead, especially on weekends and holidays.', 'Recommended - viewing gallery slots sell out on weekends and holidays', 'Gujarat', 0, 1, NULL, '18:30', 'Rs 150 (basic entry; Rs 380 with viewing gallery)', 5, 5, 21.838, 73.7191, 'Statue of Unity, Ekta Nagar, Narmada District, Gujarat 393151', 'http://www.soutickets.in/', 1.0);

