INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000493, 332020, 'Valley of Flowers', 'Valley of Flowers', 'A landscaped floral garden spread over about 17 acres at the base of the Statue of Unity complex, with seasonal flower beds, fountains and manicured lawns. It is most vibrant during monsoon and winter (October to February). Entry is included in the basic Statue of Unity ticket.', '30-60 minutes', 'October to February; monsoon months for peak bloom', 'Visit in the morning for softer light and fewer crowds; included in basic entry so no separate ticket needed.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Rs 150 (included in SoU basic entry ticket)', 5, 4, 21.8417, 73.7139, 'Statue of Unity Complex, Ekta Nagar, Narmada District, Gujarat 393151', NULL, 0.92);

