INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000494, 332020, 'Sardar Sarovar Dam Viewpoint', 'Sardar Sarovar Dam Viewpoint', 'Viewpoint overlooking the Sardar Sarovar Dam, a 163-metre-high concrete gravity dam across the Narmada river that is among the largest in India. The viewpoint is about 3.2 km from the statue and is included in the basic Statue of Unity entry ticket. Morning light gives the clearest views of the dam and reservoir.', '30-45 minutes', 'October to February, mornings for the clearest views', 'Best viewed in morning light; during monsoon the dam gates may be opened, drawing big crowds.', NULL, 'Gujarat', 1, 0, '06:30', NULL, 'Rs 150 (included in SoU basic entry ticket)', 4, 4, 21.8322, 73.7428, 'Sardar Sarovar Dam, Ekta Nagar, Narmada District, Gujarat 393151', NULL, 0.8);

