INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000495, 332020, 'Sardar Patel Zoological Park & Jungle Safari', 'Sardar Patel Zoological Park and Jungle Safari', 'A modern zoological park near the Statue of Unity spread over about 130 hectares, designed with an open natural-habitat layout and zones for African, Asian, Australian and American fauna. It houses around 170 species including Asiatic lions, Bengal tigers, giraffes and zebras, plus a walk-through aviary. Inaugurated in October 2020.', '2-3 hours', 'October to February, 9-11 AM or 4-6 PM when animals are most active', 'Separate ticket from SoU entry; book online on soutickets.in. Allow 2-3 hours - this is the section day-trippers most regret skipping.', 'Recommended on weekends and holidays', 'Gujarat', 0, 0, NULL, NULL, 'Rs 200', 5, 4, 21.835647, 73.735341, 'Statue of Unity Rd, Ekta Nagar, Narmada District, Gujarat 393151', NULL, 0.92);

