INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000496, 332020, 'Ekta Cruise', 'Ekta Cruise', 'Sightseeing and dinner cruises on the Narmada river from the Ekta Nagar jetty, behind Shrestha Bharat Bhavan, with views of the Statue of Unity from the water. Daytime cruises run several times daily, and the premium dinner cruise includes the laser show viewed from the river, Narmada Aarti and onboard dinner with cultural entertainment.', '1-1.5 hours', 'October to February; evening dinner cruise for the laser show view', 'Book the dinner cruise in advance during festive and winter season - demand is high.', 'Recommended, especially for the premium dinner cruise', 'Gujarat', 0, 1, NULL, '18:30', 'Rs 413 (day cruise; Rs 1416 dinner cruise)', 4, 4, 21.872338, 73.693774, 'Ekta Cruise Jetty, behind Shrestha Bharat Bhavan, Ekta Nagar, Narmada District, Gujarat 393151', 'http://www.soutickets.in/', 0.8);

