INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000497, 332020, 'Unity Glow Garden', 'Unity Glow Garden', 'A night garden near the Statue of Unity complex with illuminated LED sculptures of animals, birds and plants, light arches and tunnels, a glowing fountain and a light-up dance floor for children. It comes alive only after dark, so it is best paired with the evening laser show.', '30-45 minutes', '7-10 PM, after the laser show', 'Visit only after sunset - the lights are the whole point. Great for photography and young children.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Rs 100', 3, 3, 21.8485, 73.706, 'Near Valley of Flowers parking, Ekta Nagar, Narmada District, Gujarat 393151', NULL, 0.6);

