INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000498, 332020, 'Cactus Garden', 'Cactus Garden', 'A desert-ecosystem botanical garden at the Statue of Unity site with about 6 lakh plants of 450 cactus and succulent species spread over 25 acres of open land plus a glass dome. It sits across the Narmada river from the main complex, with a viewing gallery overlooking the statue and the Sardar Sarovar Dam. The adjacent Butterfly Garden is visited on the same ticket.', '45-60 minutes', 'October to February, mornings', 'Tickets are sold online only (no counter at the gate) - buy on soutickets.in before boarding the shuttle; it lies across the river so allow time for the shuttle change.', 'Online ticket required in advance (no counter on site)', 'Gujarat', 0, 0, NULL, NULL, 'Rs 60', 4, 4, 21.848, 73.731, 'Cactus Garden, across the Narmada river, Ekta Nagar, Narmada District, Gujarat 393151', 'http://www.soutickets.in/', 0.8);

