INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000500, 332020, 'Vishwa Van', 'Vishwa Van', 'Vishwa Van (Global Forest) is a botanical garden themed on ''unity in biodiversity'', with herbs, shrubs and trees native to all seven continents arranged in continental zones. It sits about 1 km before the Statue of Unity''s main entrance and offers views of the statue.', '45-60 minutes', 'October to February, daytime', 'Walkable from the main entrance (about 1 km); easy to add before or after the statue visit.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Rs 30', 3, 3, 21.8456, 73.7113, 'Vishwa Van, Statue of Unity Rd, Ekta Nagar, Narmada District, Gujarat 393151', NULL, 0.6);

