INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000501, 332020, 'Dino Trail', 'Dino Trail', 'An outdoor trail near the Valley of Flowers with life-size replicas of Rajasaurus Narmadensis, the endemic carnivorous dinosaur whose fossils were found in the Narmada valley. The main replica is about 75 feet long and 25 feet high, built at roughly three times the estimated original size, with displays on the region''s prehistoric flora and fauna.', '30-45 minutes', 'October to February, daytime', 'A good 30-minute add-on near the Valley of Flowers; especially fun for children.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 3, 3, 21.8425, 73.7148, 'Dino Trail, near Valley of Flowers, Ekta Nagar, Narmada District, Gujarat 393151', NULL, 0.6);

