INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000502, 332020, 'Arogya Van', 'Arogya Van', 'An Ayurveda-themed forest garden of about 17 acres with 5 lakh plants of 380 species, organised around traditional medicinal plants. Inaugurated by the Prime Minister as part of the integrated development of Kevadia, it has a Santhigiri wellness centre (Arogya Kutir) offering Ayurveda, Siddha, Yoga and Panchakarma therapies.', '1-2 hours', 'October to February; early mornings for walks', 'Good for an early-morning walk; carts are available for a guided tour of the forest.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Rs 30', 3, 4, 21.879272, 73.701728, 'Arogya Van, Tanakhala Rd, Ekta Nagar, Narmada District, Gujarat 393151', NULL, 0.68);

