INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000503, 332020, 'Ekta Nursery', 'Ekta Nursery', 'A large nursery in the Statue of Unity vicinity growing around a million plants, where visitors can buy seedlings to take home as a ''plant of unity''. It also runs training and employment for local tribal communities in horticulture.', '20-30 minutes', 'October to February, daytime', 'Buy a seedling as a souvenir - the nursery''s whole concept is taking a ''plant of unity'' home.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 2, 3, 21.852, 73.6985, 'Ekta Nursery, Ekta Nagar, Narmada District, Gujarat 393151', NULL, 0.48);

