INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000504, 332020, 'Children Nutrition Park', 'Children Nutrition Park', 'Billed as the world''s first technology-driven nutrition park for children, spread over 35,000 sq ft near Ekta Mall. A ''Nutri Train'' takes children through themed stations (Phalshaka Griham, Payonagari, Annapoorna, Poshan Puran, Swastha Bharatam) with a mirror maze, 5D theatre and augmented-reality games teaching healthy eating on the ''Sahi Poshan, Desh Roshan'' theme.', '1-2 hours', 'October to February, daytime', 'A must for families with school-age children; some game zones are occasionally closed, so check on arrival.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Rs 200', 4, 4, 21.87, 73.694, 'Children Nutrition Park, near Ekta Mall, Ekta Nagar, Narmada District, Gujarat 393151', NULL, 0.8);

