INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000505, 332020, 'Ekta Mall', 'Ekta Mall', 'A handicrafts and handloom mall spread over 35,000 sq ft with 20 emporia, each representing a different Indian state, symbolising ''unity in diversity''. Built in 110 days and inaugurated by the Prime Minister, it is the main souvenir-shopping stop at Ekta Nagar, next to the Ekta Food Court.', '45-60 minutes', 'October to February, afternoons', 'The place for authentic state handicrafts and souvenirs from across India in one building.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 3, 3, 21.8705, 73.6935, 'Ekta Mall, Statue of Unity Rd, Ekta Nagar, Narmada District, Gujarat 393151', NULL, 0.6);

