INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000506, 332020, 'Laser Light and Sound Show', 'Laser Light and Sound Show', 'The evening laser light-and-sound show narrating the story of Sardar Patel and India''s national unity, projected on the Statue of Unity itself. It starts after 6 PM (around 7:30 PM), runs about 25 minutes, and is one of the main reasons visitors stay overnight at Ekta Nagar.', '30 minutes', 'October to February evenings', 'A separate ticket from daytime entry - book it when you book your SoU tickets; entry to the viewing area starts around 6:30 PM.', 'Recommended - seats fill on weekends and holidays', 'Gujarat', 0, 0, NULL, NULL, 'Rs 100', 4, 4, 21.838, 73.7191, 'Statue of Unity, Ekta Nagar, Narmada District, Gujarat 393151', 'http://www.soutickets.in/', 0.8);

