INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000507, 332020, 'Nauka Vihar', 'Nauka Vihar', 'A boating facility at Panchmuli Lake, a water body surrounded by lush forest near Ekta Nagar. Each ride lasts about 45 minutes and around eight rides operate daily, through a landscape rich in flora and fauna. It is a calm, family-friendly add-on to the main SoU circuit.', '45-60 minutes', 'October to February, mornings', 'Morning rides are calmest; carry drinking water as facilities at the lake are basic.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 3, 3, 21.845, 73.746, 'Nauka Vihar, Panchmuli Lake, Ekta Nagar, Narmada District, Gujarat 393151', NULL, 0.6);

