INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000508, 332020, 'Narmada River Rafting', 'Narmada River Rafting (Khalwani)', 'White-water rafting on a 4.5 km controlled stretch of the Narmada between Khalvani and Kevadia, billed as Gujarat''s first river-rafting site, with rapids of grades 2 to 5. Operated by Unity Rafting by Anandam from the Khalwani River Rafting Starting Point. The Khalwani eco-tourism zone around it also offers river crossing, Burma bridge, tubing, rock climbing and rappelling, plus tents and tree houses.', '1-2 hours', 'October to February', 'Rafting depends on water release from the dam - confirm operation on the day before visiting.', 'Recommended - check availability with the operator first', 'Gujarat', 0, 0, NULL, NULL, NULL, 4, 4, 21.869136, 73.717979, 'Khalwani River Rafting Starting Point, Khalwani, Ekta Nagar, Narmada District, Gujarat 393151', 'https://gujaratrafting.com/', 0.8);

