INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000509, 332020, 'Zarwani Waterfall', 'Zarwani Waterfall', 'A scenic waterfall inside the Shoolpaneshwar Wildlife Sanctuary, about 12 km from the Statue of Unity and 28 km from Rajpipla towards Kevadia. The falls drop into a clear pool and are at their fullest during the monsoon (July-September). The adjoining Zarwani eco-campsite, run with the forest department, offers cottages, tents, nature trails and day picnics.', '2-3 hours', 'July to September (monsoon) for full flow', 'Go in the monsoon or just after; wear good footwear - the last stretch involves a walk along the stream.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 4, 4, 21.79, 73.62, 'Zarwani Waterfall, Zarvani village, Narmada District, Gujarat 393155', NULL, 0.8);

