INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000510, 332020, 'Shoolpaneshwar Wildlife Sanctuary', 'Shoolpaneshwar Wildlife Sanctuary', 'A 607.7 sq km protected area in the western Satpura range south of the Narmada, about a 25-30 km day trip from Ekta Nagar, sharing boundaries with Madhya Pradesh and Maharashtra. Established in 1982 initially for the sloth bear, it holds leopards, hyenas, barking deer, rhesus macaques, pangolins and rich birdlife, with moist deciduous and teak forests. Zarwani Waterfall lies deep inside it.', 'Half day', 'October to February', 'Arrange visits through the forest department; the Zarwani eco-campsite is the practical base for treks and day picnics.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 4, 4, 21.7, 73.6, 'Shoolpaneshwar Wildlife Sanctuary, Narmada District, Gujarat', NULL, 0.8);

