INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000511, 332020, 'Nilkanth Dham', 'Nilkanth Dham (Poicha)', 'A Swaminarayan temple and spiritual-cultural campus at Poicha on the banks of the Narmada, about 40 km from the Statue of Unity (roughly an hour''s drive). Spread over 108 acres and opened in October 2013, it includes the main Swaminarayan Mandir, the Sahajanand Universe exhibition, a goshala (Gau Dham) and the Narmada riverfront. A popular day trip or detour for SoU visitors.', '2-3 hours', 'October to February; evenings for aarti', 'Combine with a SoU trip - it lies on the route towards Vadodara/Ahmedabad. Food is available inside the temple campus.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Free', 4, 4, 21.971286, 73.472225, 'Nilkanth Dham, Poicha, Narmada District, Gujarat', NULL, 0.8);

