INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000512, 332020, 'Ekta Food Court', 'Ekta Food Court', 'The main food court inside the Statue of Unity complex, next to Ekta Mall, with counters serving pizza, Indian thalis, South Indian dishes, khichdi and basic snacks. The most convenient sit-down lunch stop between attractions; several food trucks operate nearby as well.', '30-45 minutes', 'Lunch, 12-2 PM', 'Outside food is not allowed inside the campus, so this is the default lunch option - thalis run around Rs 120-180.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 3, 3, 21.8705, 73.6935, 'Statue of Unity Rd, Near Ekta Mall, Kevadia, Gujarat 393151', NULL, 0.6);

