INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000513, 332020, 'Mynt', 'Mynt - Vivanta Ekta Nagar', 'The all-day dining restaurant at Vivanta Ekta Nagar (Taj), serving global cuisine with breakfast, lunch and dinner buffets. Located opposite the GMR Skill Development Center in Vagadia, it is the most reliable sit-down dining option near the statue for non-guests as well as hotel guests.', '1 hour', 'Lunch 12:30-3 PM or dinner 7-11 PM', 'The vegetarian buffet spread is well regarded; reserve ahead on weekends.', 'Recommended on weekends', 'Gujarat', 0, 0, NULL, NULL, NULL, 4, 4, 21.876, 73.69, 'Vivanta Ekta Nagar, Opp. GMR Skill Development Center, Tehsil Gurudeshwar, Vagadia, Ekta Nagar, Narmada, Gujarat 393155', 'https://www.vivantahotels.com/en-in/hotels/vivanta-ekta-nagar/restaurants/mynt-vivanta-ekta-nagar', 0.8);

