INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000514, 332020, 'Rainbow', 'Rainbow - Fortune Statue of Unity', 'The all-day dining restaurant at Fortune Statue of Unity (ITC Fortune) in Ekta Nagar, serving Chinese, North Indian and Continental - a pure-vegetarian restaurant. A reliable mid-range dinner option near the statue, with buffet and a la carte menus.', '1 hour', 'Dinner, 7-10 PM', 'Pure veg restaurant; approximately Rs 800 for two.', NULL, 'Gujarat', 0, 0, NULL, NULL, 'Rs 800 (for two, approx)', 4, 4, 21.871, 73.683, 'Fortune Statue of Unity, Ekta Nagar, Narmada District, Gujarat 393151', NULL, 0.8);

