INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (332000515, 332020, 'River View Cafe', 'River View Cafe - Khalwani', 'The cafe at the Khalwani eco-tourism and river-rafting site on the Narmada, serving breakfast, fixed lunch and fixed dinner to visitors doing rafting and adventure activities. The only organised meal stop in the Khalwani eco-tourism zone.', '45 minutes', 'Lunch during a rafting day trip', 'Meals are fixed-menu; confirm availability when you book rafting.', NULL, 'Gujarat', 0, 0, NULL, NULL, NULL, 3, 3, 21.8691, 73.718, 'River View Cafe, Khalwani Eco-Tourism, Ekta Nagar, Narmada District, Gujarat 393151', NULL, 0.6);

