INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3320077, 332, 332020, 'Rashtriya Ekta Diwas (National Unity Day)', 'October-November', 'Celebrated on 31 October at Ekta Nagar to mark Sardar Vallabhbhai Patel''s birth anniversary, with the PM paying floral tribute at the Statue of Unity. The 2026 edition (150th birth anniversary) features a grand Unity Parade of police, CAPF and NCC contingents, a nationwide Run for Unity, and a fortnight-long cultural festival (31 Oct-15 Nov) with exhibitions of arts, crafts, cuisines and tourism from across India.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3320078, 332, 332020, 'Kalyan Mahotsav', 'October-November', 'Annual festival at Nilkanth Dham, Poicha, held from Bhai Beej to Labh Pancham (in the Kartik month, around Diwali), celebrating the temple with special religious and cultural programmes on its 108-acre campus.');

