INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000002, 838001, 'Lalbagh Botanical Garden', 'Lalbagh Botanical Garden', 'Sprawling 240-acre botanical garden commissioned by Hyder Ali in 1760 and completed by Tipu Sultan, holding over 1,800 plant species. Its glass house, modeled on London''s Crystal Palace, anchors the famous twice-yearly flower shows. A 3,000-million-year-old rock formation and a 200-year-old silk cotton tree sit inside.', '2-4 hours', 'October to February, early mornings', 'Time your visit for the flower shows held around Republic Day (January) and Independence Day (August).', 'no', 'Karnataka', 0, 0, '6:09 AM', '6:11 PM', 'Rs 50', 5, 4, 12.95138, 77.58526, 'Lalbagh Botanical Garden, H C Javaraya Circle, Mavalli, Bengaluru 560004', NULL, 0.92);

