INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000003, 838001, 'Cubbon Park', 'Cubbon Park (Sri Chamarajendra Park)', 'Officially Sri Chamarajendra Park, this 300-acre green lung was laid out in 1870 under British commissioner Mark Cubbon. It holds over 6,000 trees across ~96 species plus the State Central Library, Government Museum and High Court precincts. The city''s favorite morning-walk and picnic ground.', '1-3 hours', 'October to February, early mornings', 'Go on a Sunday morning when internal roads close to traffic - best for cycling and walks; vehicles are restricted 5-8 AM daily.', 'no', 'Karnataka', 0, 0, '6:09 AM', '6:11 PM', NULL, 4, 4, 12.97095, 77.60045, 'Cubbon Park, Papanna Road, Ashok Nagar, Bengaluru 560001', NULL, 0.8);

