INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000004, 838001, 'Tipu Sultan''s Summer Palace', 'Tipu Sultan''s Summer Palace', 'Built entirely of teak in 1781-1791, this Indo-Islamic palace was begun by Hyder Ali and completed by Tipu Sultan as his summer retreat. Carved pillars, arches and floral frescoes survive; the ground floor is now a small ASI museum of Tipu-era artifacts. A quiet, compact heritage stop in old Bangalore.', '45 minutes - 1 hour', 'September to December, mornings', 'Tickets are sold online through the ASI portal; you can also buy at the gate. Pair it with the nearby Bangalore Fort.', 'no', 'Karnataka', 0, 0, '6:09 AM', '6:11 PM', 'Rs 20', 4, 3, 12.95982, 77.57366, 'Tippu Sultan Palace Road, Albert Victor Road, Chamrajpet, Bengaluru 560002', NULL, 0.72);

