INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000005, 838001, 'Bull Temple (Dodda Basavana Gudi)', 'Bull Temple', 'Built in 1537 by Kempe Gowda I, founder of Bengaluru, this Dravidian-style temple houses a 15-foot-tall monolithic Nandi carved from a single granite block - one of the largest Nandi idols in the world. It anchors the annual Kadlekai Parishe groundnut fair. Free entry.', '30-45 minutes', 'October to February, mornings', 'Combine with the adjacent Dodda Ganapathi Temple and Bugle Rock Park, a 5-minute walk away.', 'no', 'Karnataka', 0, 0, '6:09 AM', '6:11 PM', NULL, 4, 3, 12.9419, 77.568, 'Bull Temple Road, N R Colony, Basavanagudi, Bengaluru 560004', NULL, 0.72);

