INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000006, 838001, 'ISKCON Temple Bangalore', 'ISKCON Sri Radha Krishna Temple', 'One of the largest ISKCON temples in the world, inaugurated in 1997 on Hare Krishna Hill in Rajajinagar. Houses shrines to Radha Krishnachandra, Krishna Balarama, Nitai Gauranga, Srinivasa Govinda and Prahlada Narasimha, with a 17-metre gold-plated flag post. Free entry and free prasadam for visitors.', '1-2 hours', 'Year-round; weekday evenings', 'Weekends have no afternoon break but get very crowded; go on a weekday evening for a calmer darshan. Dress modestly.', 'no', 'Karnataka', 0, 0, '6:09 AM', '6:11 PM', NULL, 5, 4, 13.00097, 77.54988, 'Hare Krishna Hill, Chord Road, Rajajinagar, Bengaluru 560010', 'https://www.iskconbangalore.org/', 0.92);

