INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000007, 838001, 'Bannerghatta Biological Park', 'Bannerghatta Biological Park', 'Sprawling 731-hectare wildlife reserve 22 km south of the city, home to about 2,000 animals across 95 species. Highlights are the Grand Safari (tiger, lion, bear and herbivore enclosures) and India''s first butterfly park under a domed conservatory. Book safari slots online, especially on weekends.', '4-5 hours (half day)', 'October to March, mornings', 'Book safari tickets online in advance - slots are limited and sell out on weekends. Arrive early for better animal sightings.', 'yes', 'Karnataka', 0, 0, '6:09 AM', '6:11 PM', 'Rs 120', 5, 4, 12.84133, 77.58827, 'Bannerughatta Biological Park, Bannerghatta Road, Bengaluru 560083', 'https://bannerughattabiopark.org/', 0.92);

