INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000009, 838001, 'Visvesvaraya Industrial and Technological Museum', 'Visvesvaraya Industrial and Technological Museum', 'A unit of the National Council of Science Museums, established 1962 and named for Bharat Ratna M. Visvesvaraya. Four floors of hands-on galleries: Engine Hall, Space Technology (supported by ISRO), Biotechnology, and the Wright Brothers'' flyer simulator. A top family and school-group stop.', '2-3 hours', 'Year-round, weekday mornings', 'Weekday mornings are least crowded; the 3D show, simulator and Science on a Sphere cost extra.', 'no', 'Karnataka', 0, 0, '6:09 AM', '6:11 PM', 'Rs 100', 4, 4, 12.97528, 77.59631, 'Kasturba Road, Ambedkar Veedhi, Bengaluru 560001', 'https://www.vismuseum.gov.in/', 0.8);

