INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000010, 838001, 'National Gallery of Modern Art, Bengaluru', 'National Gallery of Modern Art, Bengaluru', 'Housed in the colonial-era Manikyavelu Mansion on Palace Road, this Ministry of Culture gallery is Bengaluru''s home for modern and contemporary Indian art. Curated gallery walks run on Wednesday and Saturday afternoons; the grounds are a calm, green escape. Entry only Rs 20 for Indians.', '1-2 hours', 'Year-round, weekday afternoons', 'Join the one-hour guided gallery walk (Wed/Sat 4-5 PM) run by curatorial staff - it makes the collection come alive.', 'no', 'Karnataka', 0, 0, '6:09 AM', '6:11 PM', 'Rs 20', 4, 4, 12.98619, 77.59489, '49, Manikyavelu Mansion, Palace Road, Bengaluru 560052', 'http://www.ngmaindia.gov.in/', 0.8);

