INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000011, 838001, 'Museum of Art and Photography', 'Museum of Art and Photography (MAP)', 'South India''s first major private art museum, opened 2023 at 22 Kasturba Road. Runs non-stop exhibitions (e.g. ''A Moving Line: 1500 Years of Indian Visual Storytelling''), plus a research library, auditorium, cafe and fine-dining restaurant. Known for strong accessibility programs. Free entry on Tuesdays.', '2-3 hours', 'Year-round, weekday afternoons', 'Go on a Tuesday for free entry to all exhibitions; last entry is 30 minutes before closing.', 'no', 'Karnataka', 0, 0, '6:09 AM', '6:11 PM', NULL, 4, 4, 12.97474, 77.59711, '22, Kasturba Road, Shanthala Nagar, Bengaluru 560001', 'https://www.map-india.org/', 0.8);

