INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000012, 838001, 'Government Museum, Bengaluru', 'Government Museum, Bengaluru', 'Established in 1865, one of India''s oldest museums and the second oldest in South India, set in a red neo-classical building on Kasturba Road. Archaeological galleries hold sculpture, coins, jewellery and inscriptions - including the Halmidi inscription, the earliest known Kannada inscription. Shares the campus with the Venkatappa Art Gallery.', '1-2 hours', 'Year-round, weekday mornings', 'Combine with Cubbon Park and the Venkatappa Art Gallery next door; call ahead since the museum has faced intermittent renovation closures.', 'no', 'Karnataka', 0, 0, '6:09 AM', '6:11 PM', 'Rs 20', 3, 3, 12.97455, 77.59584, 'Venkatappa Art Gallery Building, Kasturba Road, Ambedkar Veedhi, Bengaluru 560001', 'https://archaeology.karnataka.gov.in/', 0.6);

