INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000013, 838001, 'Vidhana Soudha', 'Vidhana Soudha', 'Completed in 1956, this imposing neo-Dravidian granite edifice houses the Karnataka state legislature and secretariat. An icon of Bengaluru''s civic identity, best appreciated from the outside; it is illuminated on Sunday evenings and public holidays. Interior access is restricted.', '20-30 minutes (exterior)', 'Year-round, evenings', 'View it from the Cubbon Park side at dusk; the building lights up on Sunday evenings and public holidays.', 'no', 'Karnataka', 0, 0, '6:09 AM', '6:11 PM', NULL, 3, 3, 12.97795, 77.58818, 'Ambedkar Veedhi, Sampangi Rama Nagar, Bengaluru 560001', NULL, 0.6);

