INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000014, 838001, 'Bangalore Fort', 'Bangalore Fort', 'Originally a mud fort built in 1537 by Kempe Gowda, rebuilt in stone by Hyder Ali in 1761. Little survives beyond the Delhi Gate, ramparts and a small Ganapathi temple, but it marks the birthplace of the old city. Best paired with the nearby Tipu''s Summer Palace.', '30 minutes', 'October to February, mornings', 'It is mostly a ruin with exterior viewing; combine with Tipu Sultan''s Summer Palace next door.', 'no', 'Karnataka', 0, 0, '6:09 AM', '6:11 PM', NULL, 2, 2, 12.96279, 77.57602, 'K R Main Road, New Tharagupet, Bengaluru 560002', NULL, 0.4);

