INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000015, 838001, 'Nandi Hills', 'Nandi Hills', 'Bengaluru''s beloved hill retreat, about 60 km from the city at ~1,455 m, crowned by Tipu Sultan''s hill fortress. Famous for sunrise above a sea of clouds (best September-February), the Bhoga Nandeeshwara Temple at its foothill, and cycling routes. Entry is about Rs 20 per adult.', 'Half day (full day with cycling)', 'September to February, sunrise', 'Leave the city by 4:30 AM to catch the sunrise; entry gates get crowded on winter weekends.', 'no', 'Karnataka', 1, 0, '6:09 AM', '6:11 PM', 'Rs 20', 5, 4, 13.3863, 77.69826, 'Nandi Hills, Chikkaballapur district, Karnataka 562103', NULL, 0.92);

