INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000016, 838001, 'Ramanagara (Sholay Rocks and Silk Town)', 'Ramanagara', 'About 50 km from Bengaluru, Ramanagara''s granite hills are the iconic filming location of the Bollywood classic Sholay (1975). Today it is a rock-climbing and rappelling hub and a silk-weaving town with one of India''s biggest silk markets. Also known for vulture conservation at Ramadevara Betta.', 'Half to full day', 'November to March, mornings', 'Book climbing/rappelling with a local adventure operator in advance; November-March has the kindest sun.', 'no', 'Karnataka', 0, 0, '6:09 AM', '6:11 PM', NULL, 4, 4, 12.71533, 77.27396, 'Ramanagara, Karnataka 562159', NULL, 0.8);

