INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000017, 838001, 'Savandurga', 'Savandurga', 'About 60 km from Bengaluru, Savandurga is counted among Asia''s largest monolithic hills, formed of two peaks - Karigudda and Biligudda. A moderate-to-difficult trek leads to 12th-century fort ruins and panoramic views; Narasimha and Veerabhadra temples sit at the foothill. Carry plenty of water.', 'Full day', 'October to February, early morning start', 'Start the trek at dawn; parts are steep and exposed, so avoid midday heat and carry 2+ litres of water.', 'no', 'Karnataka', 0, 0, '6:09 AM', '6:11 PM', NULL, 4, 4, 12.91536, 77.29735, 'Savandurga, Magadi, Ramanagara district, Karnataka 561201', NULL, 0.8);

