INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000018, 838001, 'Muthyalamaduvu (Pearl Valley)', 'Muthyalamaduvu (Pearl Valley)', 'A waterfall about 40 km from Bengaluru near Anekal, best visited in the monsoon months (July-October) when it flows full. The descent involves 100+ steps to the falls and a small pool; combine with the nearby Thattekere lake. Carry food and water - facilities are minimal.', 'Half day', 'July to October, mornings', 'Go in monsoon for real flow; avoid weekends if you dislike crowds, and wear shoes with grip for the steps.', 'no', 'Karnataka', 0, 0, '6:09 AM', '6:11 PM', NULL, 3, 3, 12.68583, 77.66462, 'Muthyala Maduvu, Anekal, Bengaluru district, Karnataka 562106', NULL, 0.6);

