INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000019, 838001, 'Devarayanadurga', 'Devarayanadurga', 'A rocky hill about 70 km from Bengaluru near Tumakuru, dotted with ancient temples - the Yoga Narasimha temple at the summit and Bhoga Narasimha at the foothill. Forested trails make it a popular day-trek and temple circuit combined. Monkeys are common; keep food packed away.', 'Full day', 'October to February, mornings', 'Visit both hilltop and foothill temples; the forest stretch is pleasant for a short trek.', 'no', 'Karnataka', 0, 0, '6:09 AM', '6:11 PM', NULL, 3, 3, 13.37349, 77.20763, 'Devarayanadurga, Tumakuru district, Karnataka 572140', NULL, 0.6);

