INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000020, 838001, 'Janapada Loka', 'Janapada Loka (Karnataka Folk Museum)', 'A 15-acre folk heritage campus on the Bengaluru-Mysuru highway (~53 km), run by the Karnataka Janapada Parishath since its founding by H.L. Nagegowda. Holds 5,000+ folk artifacts - puppets, masks, musical instruments, household items - across wings like Loka Mahal and Shilamala. The annual Lokothsava folk festival is held here in February.', '2-3 hours', 'October to March, mornings', 'Combine with lunch at the adjoining Kamat Lokaruchi restaurant, famous for Bidadi thatte idlis and North Karnataka meals.', 'no', 'Karnataka', 0, 0, '6:09 AM', '6:11 PM', 'Rs 100', 3, 3, 12.7003, 77.25197, 'Bangalore-Mysore State Highway, Ramanagara district, Karnataka 562159', 'https://janapadaloka.in/', 0.6);

