INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000021, 838001, 'Vidyarthi Bhavan', 'Vidyarthi Bhavan', 'A Basavanagudi institution since 1943, famous for its crisp-yet-soft masale dosa served with a dollop of white butter. A pure-veg, old-Bangalore tiffin room where queues form before it opens. Budget-friendly and unmissable for dosa lovers.', '30-60 minutes', 'Weekday mornings', 'Arrive before 8 AM to beat the queue; the benne (butter) masala dosa is the signature order.', 'no', 'Karnataka', 0, 0, '6:09 AM', '6:11 PM', NULL, 5, 4, 12.9451, 77.57138, '32, Gandhi Bazaar Main Road, Basavanagudi, Bengaluru 560004', NULL, 0.92);

