INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000022, 838001, 'MTR (Mavalli Tiffin Rooms)', 'Mavalli Tiffin Rooms', 'Serving since 1924 near Lalbagh, MTR is credited with inventing the rava idli during WWII rice shortages. A pure-veg Karnataka-style meals-and-tiffin legend; the full banana-leaf lunch is the classic order. Expect a wait at peak hours.', '45-60 minutes', 'Weekday lunch', 'The full meals (served on a banana leaf) is the definitive order; weekends mean long queues.', 'no', 'Karnataka', 0, 0, '6:09 AM', '6:11 PM', NULL, 5, 4, 12.95508, 77.58542, '14, Lalbagh Road, Mavalli, Bengaluru 560027', NULL, 0.92);

