INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000023, 838001, 'Koshy''s', 'Koshy''s', 'A St Marks Road landmark since 1940, Koshy''s is old Bangalore''s beloved coffee house and restaurant. Serves South Indian staples alongside continental and Anglo-Indian plates (cutlets, roast chicken) under slowly-turning fans. A cultural institution as much as a restaurant.', '45 minutes - 1 hour', 'Weekday mornings', 'The filter coffee and old-school breakfast plates are the draw; it is cash-and-card friendly and unhurried.', 'no', 'Karnataka', 0, 0, '6:09 AM', '6:11 PM', NULL, 4, 4, 12.97302, 77.60126, '39, St Marks Road, Ashok Nagar, Bengaluru 560001', NULL, 0.8);

