INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000024, 838001, 'CTR (Shri Sagar / Central Tiffin Room)', 'Central Tiffin Room', 'Malleshwaram''s legendary tiffin room from the 1920s, famed for the benne (butter) masala dosa - crisp, golden, and unapologetically buttery. Pure veg, old-school, and packed at breakfast. A pilgrimage for Bengaluru dosa traditionalists.', '30-45 minutes', 'Weekday mornings', 'Order the benne masala dosa; go early - it fills up fast and closes between lunch and evening service.', 'no', 'Karnataka', 0, 0, '6:09 AM', '6:11 PM', NULL, 4, 4, 12.99829, 77.56955, '154, 7th Cross Road, Malleshwaram, Bengaluru 560003', NULL, 0.8);

