INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000026, 838001, 'Nagarjuna', 'Nagarjuna', 'Residency Road''s Andhra-food institution, famous for its fiery Andhra meals served on banana leaves, biryanis and boneless chicken starters. Spice-forward, non-veg-leaning, and a long-standing favorite for celebratory lunches.', '1 hour', 'Weekday lunch', 'Go for the Andhra meals on banana leaf; ask about spice levels if you are not used to Andhra heat.', 'no', 'Karnataka', 0, 0, '6:09 AM', '6:11 PM', NULL, 4, 4, 12.97313, 77.60901, 'Nagarjuna, Residency Road, Ashok Nagar, Bengaluru 560001', NULL, 0.8);

