INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8380001, 838, 838001, 'Bengaluru Karaga', 'Mar-Apr', 'One of Bengaluru''s oldest festivals, dedicated to Draupadi, celebrated by the Tigala community with a grand midnight procession from the Dharmaraya Swamy Temple in Thigalarapete. The Karaga bearer balances the sacred pot in a spectacular all-night ritual.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8380002, 838, 838001, 'Kadalekai Parishe (Groundnut Fair)', 'Nov', 'Annual groundnut fair held around the Bull Temple in Basavanagudi, dating to 1537. Farmers offer their first groundnut harvest to Nandi; the temple street fills with groundnut stalls, snacks and nearly a lakh of lamps. Held on the last Monday of Karthika masa.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8380003, 838, 838001, 'Ganesh Chaturthi', 'Aug-Sep', 'Widely celebrated across Bengaluru with large public pandals and processions; Ulsoor Lake is a major immersion (visarjan) center. The city''s markets and streets take on a festive character for the 10-day festival.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8380004, 838, 838001, 'Dasara', 'Sep-Oct', 'Celebrated with devotion across Bengaluru''s temples and neighborhoods; Janapada Loka hosts grand Dasara cultural events. Many Bengalureans also make the day trip to Mysuru for the world-famous Mysuru Dasara procession.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8380005, 838, 838001, 'Deepavali', 'Oct-Nov', 'The festival of lights is celebrated citywide with lamps, fireworks and sweets; temples like ISKCON and the Bull Temple area glow through the week. Markets in Chickpet and Malleshwaram bustle with festive shopping.');

-- city: Mysuru (id 1022)
INSERT OR IGNORE INTO cities (id, state_id, city_name, latitude, longitude) VALUES (838002, 838, 'Mysuru', 12.2958, 76.6394);

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000027, 838002, 'Mysore Palace', 'Mysore Palace', 'The official royal residence of the Wodeyar dynasty and the crown jewel of Mysuru, this 1912 Indo-Saracenic palace is one of India''s most visited monuments, famous for its grand Durbar Hall, Kalyana Mantapa, and the illuminated Sunday-night façade of nearly 100,000 bulbs. A live sound-and-light show runs in the evenings.', '3-4 hours', 'October to March; on Sundays or public holidays for the 7:00-8:00 PM illumination', 'Visit the sound and light show after the daytime tour (Kannada Mon-Wed/Sat 7:00-8:00 PM; English Thu-Sat 7:00-8:00 PM, Sat also 8:15-9:15 PM). Tickets are sold at the gate; carry a valid ID.', 'no', 'Karnataka', 1, 1, '06:19', '18:27', 'Rs 150 (Indian adult), Rs 70 (children 10-18), Rs 1000 (foreign). Sound & light: Rs 100 adult / Rs 40 child (Kannada); Rs 120 adult / Rs 50 child (Sat English show).', 10, 9, 12.3051, 76.6551, 'Sayaji Rao Road, Agrahara, Chamrajpura, Mysuru, Karnataka 570001', 'https://mysorepalace.karnataka.gov.in/', 1.92);

