INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 838000027, 'insert', 'bulk', 'Hours, fees, illumination and sound-and-light schedule taken verbatim from the official Karnataka government palace site, fetched and verified loading on 2026-09-30. Official site belongs to the Mysore Palace Board (mysorepalace.karnataka.gov.in).', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000028, 838002, 'Chamundeshwari Temple', 'Chamundeshwari Temple, Chamundi Hills', 'The 12th-century hilltop shrine of Mysuru''s presiding goddess Chamundeshwari, atop 1,060 m Chamundi Hills about 13 km from the city. The Dravidian temple''s tall gopuram and hilltop views make it the city''s spiritual heart; the descent passes the giant monolithic Nandi and the Mahishasura statue.', '2-3 hours', 'October to March, early morning for the 7:30 AM darshan; during Dasara the temple is the epicentre of festivities', 'General darshan is free and runs in three sessions (7:30 AM-2:00 PM, 3:30-6:00 PM, 7:30-9:00 PM); the Rs 30 special darshan skips the queue. Combine with the Nandi statue and Mahishasura statue on the same hill trip.', 'no', 'Karnataka', 1, 1, '06:19', '18:27', 'Free (general darshan); Rs 30 (special darshan)', 9, 8, 12.2726, 76.6708, 'Chamundi Hills Road, Chamundeshwari Betta, Mysuru, Karnataka 570010', NULL, 1.72);

