INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000029, 838002, 'Brindavan Gardens & KRS Dam', 'Brindavan Gardens and Krishnaraja Sagar Dam', 'The famous terraced gardens laid out below the Krishnaraja Sagar (KRS) Dam on the Kaveri, about 20 km northwest of Mysuru. Lawns, fountains and flower beds come alive in the evening with the illuminated musical fountain — the classic Mysuru day-trip finale.', '3-4 hours', 'October to March; arrive by late afternoon to catch the gardens in daylight and the musical fountain after dark', 'Musical fountain runs 6:30-7:30 PM on weekdays and 6:30-8:00 PM on weekends. Entry is Adults ₹50, children 5-10 ₹15, foreign nationals ₹100 (per Karnataka Tourism). Carry a light jacket in winter evenings.', 'no', 'Karnataka', 1, 1, '06:19', '18:27', 'Adults Rs 50, children (5-10) Rs 15, foreign nationals Rs 100', 9, 8, 12.4227, 76.5728, 'KRS Dam Road, Krishnaraja Sagar, Mandya district (about 20 km from Mysuru)', NULL, 1.72);

