INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000030, 838002, 'St. Philomena''s Cathedral', 'St. Joseph''s Cathedral (St. Philomena''s Church)', 'One of Asia''s largest churches, a neo-Gothic cathedral built 1933-1941 (parish founded 1843) with twin 175-ft spires modelled on Cologne Cathedral. It holds a relic of St. Philomena and is officially St. Joseph''s Cathedral, universally known as St. Philomena''s Church.', '45-60 minutes', 'Year-round; mornings before 10 AM for quiet viewing, and around Christmas when it is decorated', 'Entry is free; open 5:00 AM-6:00 PM daily per a Feb-2026-updated local guide (some aggregates say 6 AM-8 PM — confirm on arrival). Dress modestly; the crypt and stained-glass windows are the highlights.', 'no', 'Karnataka', 1, 1, '06:19', '18:27', 'Free', 8, 8, 12.321, 76.6583, 'Lourdes Nagar, Ashoka Road, Mysuru, Karnataka 570001', 'https://mysorestphilomenachurch.com/', 1.6);

