INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000031, 838002, 'Jaganmohan Palace Art Gallery', 'Sri Jayachamarajendra Art Gallery, Jaganmohan Palace', 'The 1861 royal palace that served as the Wodeyar residence before Mysore Palace was rebuilt, now the Sri Jayachamarajendra Art Gallery. It houses one of South India''s finest art collections, including Raja Ravi Varma and Roerich paintings, royal portraits, and Mysore-style artefacts.', '1.5-2 hours', 'Year-round; pair with Mysore Palace and Devaraja Market in the same morning', 'Entry is Adult Rs 20, Children Rs 10; most recent guides say 10:00 AM-5:30 PM daily (some older guides say 8:30 AM start — arrive after 10 to be safe). Photography may be restricted inside the gallery.', 'no', 'Karnataka', 1, 1, '06:19', '18:27', 'Adult Rs 20, Children Rs 10', 7, 8, 12.3058, 76.6543, 'Jaganmohan Palace Road, Chamrajpura, Mysuru, Karnataka 570005', NULL, 1.48);

