INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000032, 838002, 'Karanji Lake Nature Park', 'Karanji Lake Nature Park', 'A 90-acre lake park at the foot of Chamundi Hills run by the Mysuru Zoo, home to India''s largest walk-through aviary, a butterfly park on an island, and the Regional Museum of Natural History. Pelicans, painted storks and herons make it a birder''s favourite.', '2-3 hours', 'October to March, mornings for bird activity; closed on Tuesdays', 'Entry is Adults Rs 10, children 5-15 Rs 5, senior citizens Rs 5; open 8:30 AM-5:30 PM, closed Tuesdays. Boating and the aviary are the highlights — arrive before 10 AM to see birds at their most active.', 'no', 'Karnataka', 1, 1, '06:19', '18:27', 'Adults Rs 10, children (5-15) Rs 5, senior citizens Rs 5', 7, 8, 12.3022, 76.6652, 'Karanji Kere, Jockey Quarters, Mysuru, Karnataka 570011', NULL, 1.48);

