INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000033, 838002, 'Kukkarahalli Lake', 'Kukkarahalli Lake', 'A 58-hectare J-shaped lake adjoining the University of Mysore''s Manasagangotri campus, with a ~4.5 km shaded perimeter walkway. A beloved morning-walk and birdwatching spot — pelicans, painted storks and egrets — restored in 2003-04 after near-collapse.', '1-2 hours', 'October to March; sunrise for birds, sunset for the light on the water', 'Free entry; gates typically open 6:00 AM-6:00 PM daily. No boating is offered as of recent reports. Combine with the Folklore Museum on the same campus.', 'no', 'Karnataka', 1, 1, '06:19', '18:27', 'Free', 6, 7, 12.3079, 76.637, 'Kukkarahalli Lake View Road, Saraswathipuram, Mysuru, Karnataka 570005', NULL, 1.28);

