INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 838000033, 'insert', 'bulk', 'Free entry confirmed by all guides; hours conflict between 6 AM-6 PM (most guides) and split 5-10 AM / 4-7 PM slots (Justdial listing). Used 6 AM-6 PM with note.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000034, 838002, 'Devaraja Market', 'Devaraja Market', 'Mysuru''s century-old covered bazaar (established ~1916) on Sayaji Rao Road — a sensory riot of flower garlands, sandalwood, Mysore silk, spices, bananas and betel leaves under a heritage wooden-roofed structure. The city''s best spot for souvenir hunting and street photography.', '1-2 hours', 'Mornings 6:00-10:00 AM for the fresh flower and produce trade; evenings for the lit-up market', 'Free to enter. Hours conflict between 6 AM-8 PM and 6 AM-9:30 PM (Mon-Sat) in guides — plan a daytime visit. Bargain politely; the flower section and sandalwood shops are the highlights.', 'no', 'Karnataka', 1, 1, '06:19', '18:27', 'Free', 7, 8, 12.3085, 76.6517, 'Sayaji Rao Road, Devaraja Mohalla, Mysuru, Karnataka 570021', NULL, 1.48);

