INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 838000034, 'insert', 'bulk', 'Hours conflict between guides (6 AM-8 PM vs 6 AM-9:30 PM Mon-Sat); used 6 AM-8 PM daily with note. No official website.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000035, 838002, 'Mysuru Rail Museum', 'Mysuru Rail Museum', 'India''s second railway museum after Delhi, on Krishna Rajendra Road opposite CFTRI. Outdoor exhibits include vintage steam locos, the Maharaja of Mysore''s royal saloon coaches, and a charming mini-train ride for children.', '1-1.5 hours', 'Year-round; late morning for the toy-train rides', 'The official mysore.nic.in page lists 9:30 AM-5:30 PM with Rs 20 adult / Rs 10 child (5-10); some guides report Rs 50 and a Monday/Tuesday closure — carry cash and confirm at the gate. The royal saloons are the must-see exhibit.', 'no', 'Karnataka', 1, 1, '06:19', '18:27', 'Rs 20 (adult), Rs 10 (children 5-10)', 6, 7, 12.3086, 76.6297, 'Princess Road, Opposite CFTRI, KRS Road, Mysuru, Karnataka 570006', NULL, 1.28);

