INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000036, 838002, 'Sand Sculpture Museum', 'Mysore Sand Sculpture Museum', 'India''s first sand sculpture museum, founded 2014 by artist Gowri MN on Chamundi Hill Road — about 150 large themed sand sculptures (Dasara procession, deities, marine life) under a covered shed, all carved from sand and water alone.', '45-60 minutes', 'Year-round; combine with Chamundi Hills in one trip', 'Open 8:30 AM-6:30 PM daily; entry fee is inconsistently published (Rs 40-60 adult, Rs 20-40 child) — confirm at the counter. Best visited in daylight for photography of the sculptures.', 'no', 'Karnataka', 1, 1, '06:19', '18:27', 'Rs 40-60 (adult), Rs 20-40 (child) - published figures conflict', 6, 7, 12.2673, 76.6657, 'Chamundi Hill Road, KC Layout, Mysuru, Karnataka 570010', NULL, 1.28);

