INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000037, 838002, 'Shuka Vana', 'Shuka Vana Parrot Sanctuary', 'A free rehabilitation aviary for parrots and parakeets inside the Avadhoota Datta Peetham (Sri Ganapathi Sachchidananda Ashrama) on Ooty Road — hundreds of rescued birds in large enclosures, run as a conservation and spiritual project.', '1-1.5 hours', 'Year-round; morning session 10:00 AM-12:30 PM or evening 3:30-5:30 PM (closed Wednesdays per guides)', 'Entry is free; phones and cameras must be deposited at the entrance. Sessions per guides: 10:00 AM-12:30 PM and 3:30-5:30 PM, closed Wednesdays — confirm locally. Combine with the ashram''s Bonsai Garden nearby.', 'no', 'Karnataka', 1, 1, '06:19', '18:27', 'Free', 6, 8, 12.327, 76.623, 'Avadhoota Datta Peetham, Sri Ganapathi Sachchidananda Ashrama, Ooty Road, Datta Nagar, Mysuru', NULL, 1.36);

