INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000038, 838002, 'Folklore Museum', 'Folklore Museum, Jayalakshmi Vilas Mansion', 'Karnataka''s great folk-culture repository inside the 1905 Jayalakshmi Vilas Mansion on the University of Mysore''s Manasagangotri campus — Yakshagana costumes, leather puppets, ritual masks, folk musical instruments and rural-life artefacts collected across the state.', '2-3 hours', 'Year-round on weekdays; photography/videography not allowed inside', 'Entry is free. The authoritative Museums of India listing gives Mon-Sat 10:15 AM-5:00 PM with a 1:15-2:30 PM lunch break, closed Sundays; phones are deposited at the entrance. Allow 2-3 hours for the full collection.', 'no', 'Karnataka', 1, 1, '06:19', '18:27', 'Free', 6, 8, 12.3136, 76.6225, 'Jayalakshmi Vilas Mansion, Manasagangotri, University of Mysore, Mysuru, Karnataka 570006', NULL, 1.36);

