INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 838000038, 'insert', 'bulk', 'Hours from the Museums of India portal (shop.museumsofindia.org) — most authoritative published source found. Free entry confirmed by all guides. Coordinates from Mappls listing.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000039, 838002, 'Nandi Statue', 'Monolithic Nandi Statue, Chamundi Hills', 'One of India''s largest monolithic Nandi statues — about 16 ft high and 24 ft long, carved in situ from a single granite boulder in 1659 by Maharaja Dodda Devaraja Wodeyar. It sits beside the Chamundi Hill road near the 700th step, facing the Chamundeshwari temple above.', '30-45 minutes', 'Year-round; early morning or late afternoon for the best light and city views from the steps below', 'Free to visit; guides list roughly 9:00 AM-6:00 PM but the open-air shrine is accessible during daylight. Ask your driver to stop on the way up or down the hill — it''s roadside with fruit and sugarcane stalls nearby.', 'no', 'Karnataka', 1, 1, '06:19', '18:27', 'Free', 7, 7, 12.2745, 76.67, 'Chamundi Hill Road, near the 700th step, Chamundi Hills, Mysuru', NULL, 1.4);

