INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 838000039, 'insert', 'bulk', 'Dimensions (16 ft x 24 ft) and 1659/Dodda Devaraja Wodeyar attribution consistent across published sources. Coordinates approximate (hillside site).', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000040, 838002, 'Lalitha Mahal Palace', 'Lalitha Mahal Palace Hotel', 'The gleaming white 1921 Indo-Saracenic palace built by Krishnaraja Wodeyar IV to host the Viceroy of India (guests included Queen Elizabeth II), now a luxury heritage hotel. Non-residents can visit the grand lobby, corridors, gardens and the famed ballroom for a small entry fee.', '1-2 hours', 'October to March; late afternoon for photos of the white façade against Chamundi Hills', 'Entry for visitors is about Rs 100 per person (confirm at the gate — hotel policy varies). Guides report visiting hours around 10:00 AM-6:00 PM, though figures conflict (9 AM-5:30 PM / 8 AM-5 PM also published). Sections may be restricted to hotel guests; the café is open to visitors.', 'no', 'Karnataka', 1, 1, '06:19', '18:27', 'Rs 100 per person (visitor entry; confirm at gate)', 7, 8, 12.2983, 76.6925, 'Lalitha Mahal Palace Road, Lalithmahal Nagar, Siddhartha Layout, Mysuru, Karnataka 570028', NULL, 1.48);

