INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 838000040, 'insert', 'bulk', 'Official hotel domain lalithamahalpalace.co.in returned by search but NOT fetched — website set null per fetch rule. Hours conflict across guides (10 AM-6 PM vs 9 AM-5:30 PM vs 8 AM-5 PM); used 10 AM-6 PM with confirm-at-gate note. Fee ~Rs 100/person from guides, hotel policy varies.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000041, 838002, 'Srirangapatna', 'Ranganathaswamy Temple, Srirangapatna', 'The island fortress-town on the Kaveri, 18 km from Mysuru — capital of Hyder Ali and Tipu Sultan. Its centrepiece is the 9th-century Sri Ranganathaswamy Temple, one of the Pancharanga Kshetrams, alongside Tipu''s summer palace, the Gumbaz mausoleum and the fortress walls.', '3-4 hours (half-day trip from Mysuru)', 'October to March; early morning darshan before day-trippers arrive', 'General entry to the temple is free; darshan roughly 7:30 AM-1:00 PM and 4:00-8:00 PM with an afternoon break. Daria Daulat Bagh (Tipu''s summer palace, 9 AM-5 PM, Rs 15-20 entry) is 2 km away — combine both in one trip.', 'no', 'Karnataka', 1, 1, '06:19', '18:27', 'Free (temple general entry); Daria Daulat Bagh Rs 15-20 (Indian; published figures conflict)', 9, 8, 12.4247, 76.6764, 'Temple Street, Srirangapatna, Mandya district, Karnataka 571438 (about 18 km from Mysuru)', NULL, 1.72);

