INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000042, 838002, 'Daria Daulat Bagh', 'Daria Daulat Bagh (Tipu''s Summer Palace)', 'Tipu Sultan''s 1784 teakwood summer palace in Srirangapatna, set in manicured lawns — walls painted with floral motifs and battle scenes, now an ASI museum of Tipu-era paintings, coins, weapons and manuscripts.', '1-1.5 hours', 'October to March; combine with the Ranganathaswamy Temple in one Srirangapatna trip', 'Open 9:00 AM-5:00 PM; Indian entry fee published as Rs 15 in some guides and Rs 20 in others — carry both. Photography rules vary by gallery; the painted interiors are the highlight.', 'no', 'Karnataka', 1, 1, '06:19', '18:27', 'Rs 15-20 (Indian adult; published figures conflict)', 7, 7, 12.4377, 76.6976, 'Daria Daulat Bagh Road, Srirangapatna, Mandya district, Karnataka 571438', NULL, 1.4);

