INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 838000042, 'insert', 'bulk', 'Entry fee conflict (Rs 15 vs Rs 20) reported as range. Coordinates approximate.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000043, 838002, 'Somanathapura', 'Chennakeshava Temple, Somanathapura', 'A 13th-century (1258 CE) Hoysala masterpiece on the Kaveri, 35 km from Mysuru — a star-shaped trikuta shrine covered in Ramayana, Mahabharata and Krishna friezes. Part of the UNESCO-listed Sacred Ensembles of the Hoysalas (2023); an ASI-protected monument, not an active worship temple.', '2-3 hours', 'October to March, early morning for the best light on the carvings', 'ASI monument: open about 8:30 AM-5:30 PM daily; entry Rs 25 (Indian) / Rs 250 (foreign), UPI payment only per recent guides (some report Rs 20 Indian). Footwear must be left outside. No food or stays on site — plan meals in Mysuru.', 'no', 'Karnataka', 1, 1, '06:19', '18:27', 'Rs 25 (Indian), Rs 250 (foreign) - ASI ticket; some guides report Rs 20 Indian', 9, 9, 12.2758, 76.8815, 'Keshava Temple Road, Somanathapura, Tirumakudal Narsipur taluk, Mysuru district, Karnataka 571120 (about 35 km from Mysuru)', NULL, 1.8);

