INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 838000043, 'insert', 'bulk', 'Fee conflict Rs 20 vs Rs 25 Indian; used Rs 25 (most recent) with note. Coordinates from meta.ai listing.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000044, 838002, 'Nanjangud', 'Srikanteshwara Temple, Nanjangud', 'The great Shiva temple of Nanjangud on the Kapila river, 25 km south of Mysuru — the largest temple in Karnataka, famed as Dakshina Kashi (''Kashi of the South''). Its 120-ft gopuram and vast pillared halls draw lakhs of pilgrims, especially at Maha Shivaratri.', '2-3 hours', 'October to March; Maha Shivaratri (Feb-Mar) for the festival, weekdays for a calm darshan', 'Free entry; darshan sessions 6:00 AM-1:00 PM and 4:00-8:30 PM (official HRCE/ITMS listing). Multiple abhishekams run through the day (6:30 AM, 9 AM, 11 AM, 12 noon, 6:30 PM, 8 PM). The temple''s own site is nanjangudtemple.kar.nic.in.', 'no', 'Karnataka', 1, 1, '06:19', '18:27', 'Free', 8, 8, 12.1189, 76.6928, 'Rastrapathi Road, Nanjangud, Mysuru district, Karnataka 571301 (about 25 km from Mysuru)', NULL, 1.6);

