INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 838000044, 'insert', 'bulk', 'Hours from the official Karnataka HRCE temple portal itms.kar.nic.in. The temple''s own domain nanjangudtemple.kar.nic.in returned by search but not fetched — website set null per fetch rule. Coordinates from ITMS listing.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000045, 838002, 'Melukote', 'Cheluvanarayana Swamy Temple, Melukote', 'The sacred hill-town of Melukote (Thirunarayanapuram), 50 km from Mysuru — the Cheluvanarayana Swamy temple at the foothills and the Yoga Narasimha temple atop the rocky Yadugiri hill. Associated with Ramanujacharya, famed for the Vairamudi festival and its legendary puliyogare.', '3-4 hours (half-day trip from Mysuru)', 'October to February; Vairamudi Brahmotsava (Mar-Apr) draws lakhs', 'Free entry. Darshan sessions: 7:30 AM-1:00 PM, 4:00-6:00 PM, 7:00-8:00 PM (extended on Sat/Sun/holidays: 7:30-1:30, 3:30-6, 7-8). Men must remove shirts to enter the inner sanctum. Don''t miss the 300-step climb to Yoga Narasimha for valley views, and puliyogare at Subbanna/Annapurneshwari mess.', 'no', 'Karnataka', 1, 1, '06:19', '18:27', 'Free', 8, 8, 12.6602, 76.6477, 'Raja Street, Melukote, Pandavapura taluk, Mandya district, Karnataka 571431 (about 50 km from Mysuru)', NULL, 1.6);

