INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 838000045, 'insert', 'bulk', 'Darshan session timings from detailed published guides; minor conflicts on start times (7:30 vs 8:30 AM) — used 7:30 AM majority. No official website found. Coordinates from meta.ai listing.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000046, 838002, 'Talakad', 'Panchalinga Temples, Talakad', 'The mysterious ''buried temples'' town on the Kaveri, 45 km southeast of Mysuru — some 30 Ganga/Chola/Hoysala temples lie under shifting sand dunes; five excavated Shiva shrines form the Panchalingam. The curse-of-Talakad legend and the once-in-12-years Panchalinga Darshana add to the mystique.', '2-3 hours', 'September to March; early morning before the sand heats up', 'Free entry; darshan roughly 8:30 AM-1:30 PM and 4:30-8:00 PM (per published guides). Reach the temples on foot over the sand — wear sturdy footwear, not slippers. Vaidyeshvara is the largest of the five excavated shrines; the Hoysala Kirti Narayana temple is nearby.', 'no', 'Karnataka', 1, 1, '06:19', '18:27', 'Free', 7, 8, 12.1939, 77.029, 'Talakad, Tirumakudal Narsipur taluk, Mysuru district, Karnataka 571122 (about 45 km from Mysuru)', NULL, 1.48);

