INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000047, 838002, 'Vinayaka Mylari Hotel', 'Vinayaka Mylari Hotel', 'A legendary 80-plus-year-old dosa institution in Nazarbad — the original Mylari dosa: soft, spongy, slathered in butter, served with a mild vegetable sagu and coconut chutney, eaten standing at shared tables. Pure vegetarian and fiercely local.', '30-45 minutes', 'Breakfast or evening tiffin time; expect a queue at peak hours', 'Cash-friendly budget spot; a masala dosa costs around Rs 60. Go early — it often sells out. Filter coffee here is a must alongside the benne (butter) masala dosa.', 'no', 'Karnataka', 1, 1, '06:19', '18:27', 'Budget (dosa ~Rs 60)', 9, 9, 12.3056, 76.6472, 'No. 79, Nazarbad Main Road, near Nazarbad Police Station, Mysuru, Karnataka 570010', NULL, 1.8);

