INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000048, 838002, 'The Old House', 'The Old House', 'A beloved Italian/vegetarian pizzeria in a heritage-style house on Jhansi Rani Lakshmi Bai Road — wood-fired pizzas, pastas and continental plates in a cosy, traveller-friendly setting. A long-standing Mysuru favourite for European comfort food.', '1-1.5 hours', 'Lunch or dinner; evenings are the liveliest', 'Vegetarian-friendly Italian menu. Note: theoldhouse.co is a domain-for-sale page — the restaurant has no verified official website; hours published by aggregates (8 AM-11 PM daily) are unverified, so confirm by phone before visiting.', 'no', 'Karnataka', 1, 1, '06:19', '18:27', 'Mid-range', 7, 8, 12.3028, 76.6402, '451, Jhansi Rani Lakshmi Bai Road, Mysuru, Karnataka', NULL, 1.48);

