INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000049, 838002, 'Gufha', 'Gufha, Hotel Pai Vista', 'Mysuru''s famous cave-themed restaurant at Hotel Pai Vista — dining inside cavern-style interiors inspired by cave art, serving Indian, Chinese and Continental multi-cuisine. A theatrical, family-friendly dinner experience near the palace.', '1-1.5 hours', 'Dinner, when the cave ambience is at its best', 'Official hotel page confirms Indian, Chinese and Continental cuisines. Aggregates report 12:00 PM-11:00 PM daily but the official page publishes no hours — confirm by phone. Halal/non-veg options available; not a pure-veg restaurant.', 'no', 'Karnataka', 1, 1, '06:19', '18:27', 'Mid-range', 7, 8, 12.298, 76.658, 'Hotel Pai Vista, 35/A, Behind Bhima Jewellery, Bangalore Nilgiri Road, Doora, Mysuru, Karnataka 570001', 'https://www.paihotels.com/vista-mysore/restaurants/restaurants.html', 1.48);

