INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000050, 838002, 'La Uppu', 'La Uppu, Grand Mercure Mysore', 'The multi-cuisine all-day restaurant at the Grand Mercure Mysore — a premium, polished dining room serving breakfast, lunch and dinner with Indian and continental spreads. A reliable upscale choice in central Mysuru.', '1-1.5 hours', 'Dinner; also a dependable breakfast stop for hotel guests and walk-ins', 'Premium pricing (about Rs 2600 for two per published listings). Serves halal and non-veg; not vegetarian-only. Not a rooftop restaurant — that claim is incorrect. Confirm hours with the hotel before visiting.', 'no', 'Karnataka', 1, 1, '06:19', '18:27', 'Premium (~Rs 2600 for two)', 6, 7, 12.3042, 76.6548, 'Grand Mercure Mysore, 2203/60, New Sayyaji Rao Road, Mysuru, Karnataka', NULL, 1.28);

