INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000051, 838002, 'Akshaya', 'Akshaya Restaurant, Hotel Dasaprakash', 'The pure-vegetarian South Indian restaurant of the heritage Hotel Dasaprakash at Gandhi Square — classic Mysuru-style meals, dosas, vadas and filter coffee in a no-frills, budget-friendly dining hall popular with locals and pilgrims alike.', '45-60 minutes', 'Breakfast or lunch for the freshest tiffin', 'Pure veg South Indian at budget prices. The group''s website mysoredasaprakashgroup.com failed to load on fetch (2026-09-30), so no official website is listed; hours are unpublished — visit during standard meal times.', 'no', 'Karnataka', 1, 1, '06:19', '18:27', 'Budget', 7, 7, 12.3107, 76.6549, 'Hotel Dasaprakash, Gandhi Square, Mysuru, Karnataka', NULL, 1.4);

