INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000052, 838002, 'Depth N Green', 'Depth N Green Cafe', 'A health-focused vegetarian café in Gokulam — organic salads, smoothies, Buddha bowls, sourdough bakes and vegan options in a green, artsy space with live music evenings. A favourite of yoga travellers and health-conscious visitors.', '1 hour', 'Breakfast through dinner; evenings for live music', 'Vegetarian with strong vegan options. Official site depthngreen.cafe fetched and verified (2026-09-30) — it showcases their sourdough and spice mixes but publishes no hours; third-party listings say 9:00 AM-8:30 PM, closed Mondays (unverified) — confirm before visiting.', 'no', 'Karnataka', 1, 1, '06:19', '18:27', 'Budget to mid-range (~Rs 200-400 per person; ~Rs 600 for two)', 6, 8, 12.3307, 76.6287, '228/3, Gokulam Main Road, near Ganapathi Temple, Gokulam, Mysuru, Karnataka 570002', 'http://depthngreen.cafe/', 1.36);

