INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8380006, 838, 838002, 'Mysuru Dasara', 'Sep-Oct', 'Karnataka''s grandest festival — the 10-day royal Dasara centred on Mysore Palace: the illuminated palace, the Jumbo Savari elephant procession on Vijayadashami, cultural programmes and the Dasara exhibition. The city''s peak season.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8380007, 838, 838002, 'Vairamudi Brahmotsava', 'Mar-Apr', 'The chief annual festival of the Cheluvanarayana Swamy Temple at Melukote, when the deity is adorned with the diamond-studded Vairamudi crown and taken out in procession; attended by lakhs of devotees.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8380008, 838, 838002, 'Teppotsava (Float Festival)', 'Mar-Apr', 'The annual float festival at Melukote, when the temple deities are taken on a decorated float across the temple tank (kalyani) — a major draw alongside the Vairamudi celebrations.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8380009, 838, 838002, 'Maha Shivaratri at Srikanteshwara Temple', 'Feb-Mar', 'The great night of Shiva at Nanjangud''s Srikanteshwara Temple (Dakshina Kashi), with special abhishekams through the night and massive pilgrim crowds.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8380010, 838, 838002, 'Mysuru Literature Festival', 'Dec', 'An annual literary festival in Mysuru hosting authors, panel discussions and book events — a growing cultural fixture of the city''s December calendar.');

-- city: Hampi (id 1023)
INSERT OR IGNORE INTO cities (id, state_id, city_name, latitude, longitude) VALUES (838003, 838, 'Hampi', 15.335, 76.46);

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000053, 838003, 'Virupaksha Temple', 'Virupaksha Temple', 'The oldest continuously functioning temple in Hampi, with origins traced to the 7th century and dedicated to Shiva as Virupaksha, consort of the local goddess Pampadevi. Its 50-metre, nine-tiered eastern gopuram and pillared hall were commissioned by Krishnadevaraya in 1510 AD. Inside, a dark chamber shows the inverted shadow of the gopuram cast 300 feet away, and the temple''s elephant Lakshmi still blesses visitors.', '1-2 hours', 'October to March, early morning or evening', 'Visit for the morning aarti around 7 AM; footwear must be removed inside the complex, so wear easy slip-ons.', 'no', 'Karnataka', 0, 1, '6:19 AM', '5:58 PM', 'Free', 5, 5, 15.335, 76.46, 'River Rd, Hampi, Karnataka 583239', NULL, 1.0);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (838000053, 838000053, '6:00 AM - 1:00 PM, 5:00 PM - 9:00 PM', '6:00 AM - 1:00 PM, 5:00 PM - 9:00 PM', '6:00 AM - 1:00 PM, 5:00 PM - 9:00 PM', '6:00 AM - 1:00 PM, 5:00 PM - 9:00 PM', '6:00 AM - 1:00 PM, 5:00 PM - 9:00 PM', '6:00 AM - 1:00 PM, 5:00 PM - 9:00 PM', '6:00 AM - 1:00 PM, 5:00 PM - 9:00 PM', 'Sanctum closes in the afternoon; special darshan ticket Rs 25 reported by hampitourism.co.in.');

