INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 838000053, 'insert', 'bulk', 'Hours and free entry from hampitourism.co.in; 50 m gopuram height and inverted-shadow phenomenon corroborated by avibrantpalette.com and outlooktraveller.com. One source (templeyatri.in) gives slightly different evening reopening (4 PM vs 5 PM); used the hampitourism schedule. Coordinates are the well-known temple location, within 1 km. Sunrise/sunset times are computed for mid-October, not a published per-place schedule.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000054, 838003, 'Vijaya Vittala Temple', 'Vijaya Vittala Temple', 'The largest and most famous monument complex in Hampi, built in the 15th century under Devaraya II and expanded by Krishnadevaraya, dedicated to Vishnu as Vittala. Its courtyard holds the iconic monolithic Stone Chariot, which appears on the Indian 50-rupee note. The Ranga Mandapa contains 56 musical pillars that once produced different musical notes when tapped, though touching them is now prohibited.', '2-3 hours', 'November to February, morning', 'Electric buggies run from the parking area to the temple since vehicles are not allowed near the complex; carry water as the walk is long and exposed.', 'no', 'Karnataka', 0, 0, '6:19 AM', '5:58 PM', 'Rs 40', 5, 5, 15.3416, 76.4738, 'Vijaya Vittala Temple Rd, Hampi, Karnataka 583239', NULL, 1.0);

