INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 838000054, 'insert', 'bulk', 'Entry fee Rs 40 (Indian/SAARC/BIMSTEC; Rs 600 foreign) and 8:30 AM-6:00 PM from hampitourism.co.in; karnataka.com and trippyigloo.com instead say 8:30 AM-5:00 PM and no fee - used the ASI-consistent figure and flagged the conflict. Rs 40 is the combined ASI ticket covering Zenana Enclosure and the museum too (soulatour.com). Coordinates from published location of the temple complex. Sunrise/sunset times are computed for mid-October, not a published per-place schedule.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000055, 838003, 'Hemakuta Hill Temples', 'Hemakuta Hill Temples', 'A hill immediately south of Virupaksha Temple dotted with a cluster of pre-Vijayanagara shrines dating from the 9th to 14th centuries, many built in the triple-shrine (trikuta) style. The hill is one of Hampi''s classic sunset viewpoints, with the Virupaksha gopuram and boulder-strewn valley framed below. The temples are simple, early Dravidian structures predating the empire''s grand phase.', '1-2 hours', 'October to March, late afternoon for sunset', 'Climb up about 45 minutes before sunset to get a boulder perch; the granite is slippery when wet, so avoid the monsoon climb.', 'no', 'Karnataka', 0, 1, '6:19 AM', '5:58 PM', NULL, 4, 5, 15.3355, 76.4545, 'Hemakuta Hill, Hampi, Karnataka 583239', NULL, 0.88);

