INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000056, 838003, 'Matanga Hill', 'Matanga Hill', 'The highest point in Hampi at about 575 feet, climbed via a stepped path that takes 30-45 minutes, and the town''s signature sunrise viewpoint overlooking the Tungabhadra river, Virupaksha Temple and the Achyutaraya complex. The hill is linked in the Ramayana to the hermitage of the sage Matanga, where Shabari is said to have waited for Rama. It also offers wide sunset panoramas over the boulder landscape.', '2-3 hours', 'October to March, before sunrise', 'Start the climb in the dark with a torch about an hour before sunrise; the steps are uneven and there is no lighting.', 'no', 'Karnataka', 1, 1, '6:19 AM', '5:58 PM', NULL, 4, 5, 15.3377, 76.4633, 'Matanga Hill, near Hampi Bazaar, Hampi, Karnataka 583239', NULL, 0.88);

