INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 838000056, 'insert', 'bulk', 'Sunrise reputation and ~575 ft height from travel guides; Ramayana association widely reported. No official hours or fees published - open hill, left null. Coordinates approximate the hilltop. Sunrise/sunset times are computed for mid-October, not a published per-place schedule.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000057, 838003, 'Lotus Mahal', 'Lotus Mahal', 'An elegant two-storeyed Indo-Islamic pavilion inside the Zenana Enclosure, once part of the royal women''s quarters of the Vijayanagara kings, famous for its cusped arches and lotus-bud-like domed towers. The upper floors have balconies that are believed to have been the queen''s viewing galleries. It shares the ASI combined ticket with the Elephant Stables and the Vittala Temple.', '1 hour', 'October to March, morning', 'Photograph it in the soft morning light before tour buses arrive; the ticket counter is right at the Zenana Enclosure entrance.', 'no', 'Karnataka', 0, 0, '6:19 AM', '5:58 PM', 'Rs 40', 5, 4, 15.317, 76.4706, 'Zenana Enclosure, Kamalapura, Hampi, Karnataka 583221', NULL, 0.92);

