INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000058, 838003, 'Elephant Stables', 'Elephant Stables', 'A long pillared building with eleven large domed chambers that housed the Vijayanagara kings'' ceremonial elephants, each dome in a different Indo-Islamic style. It stands just east of the Zenana Enclosure and is one of the least-damaged major structures in Hampi. The same ASI combined ticket (Rs 40) covers entry.', '45 minutes', 'October to March, morning', 'Combine with the Lotus Mahal in one ticketed visit; the stables are a short walk east of the enclosure gate.', 'no', 'Karnataka', 0, 0, '6:19 AM', '5:58 PM', 'Rs 40', 5, 4, 15.3163, 76.4722, 'Near Zenana Enclosure, Kamalapura, Hampi, Karnataka 583221', NULL, 0.92);

