INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000059, 838003, 'Queen''s Bath', 'Queen''s Bath', 'A small, ornate Indo-Islamic royal bathhouse on the road toward the Zenana Enclosure, built as a secluded pleasure bath for the queens of Vijayanagara. Its arched corridors surround a central pool that was once fed by channels and crowned with a lotus-shaped fountain. The exterior is plain but the interior arches and balconies are finely carved.', '30-45 minutes', 'October to March, daytime', 'Visit on the way to the Lotus Mahal since it sits on the same road; it takes under an hour and needs no ticket.', 'no', 'Karnataka', 0, 0, '6:19 AM', '5:58 PM', NULL, 3, 3, 15.3135, 76.474, 'Queen''s Bath Rd, Kamalapura, Hampi, Karnataka 583221', NULL, 0.6);

