INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000060, 838003, 'Stepped Tank (Pushkarani)', 'Stepped Tank (Pushkarani)', 'A perfectly geometric stepped water tank in the Royal Enclosure near the Hazara Rama Temple, built of chlorite schist slabs in symmetrical descending tiers. It was uncovered during excavations in the 1980s and is believed to have served ritual purposes for the adjoining temples. Its precise geometry makes it one of Hampi''s most photographed structures.', '30 minutes', 'October to March, daytime', 'See it together with the Hazara Rama Temple and the Underground Shiva Temple, all within walking distance in the Royal Enclosure area.', 'no', 'Karnataka', 0, 0, '6:19 AM', '5:58 PM', NULL, 4, 4, 15.3215, 76.4688, 'Royal Enclosure, Kamalapura, Hampi, Karnataka 583221', NULL, 0.8);

