INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000061, 838003, 'Hazara Rama Temple', 'Hazara Rama Temple', 'A 15th-century temple in the Royal Enclosure that served as the private chapel of the Vijayanagara kings, dedicated to Rama. Its outer walls carry the Ramayana carved in sequential panels, and it is the only temple in Hampi with Ramayana scenes on both its exterior and interior walls. The name is commonly explained as ''a thousand Ramas'' from the multitude of Rama carvings.', '45 minutes - 1 hour', 'October to March, daytime', 'Hire the ASI-registered guides near the Royal Enclosure to walk you through the Ramayana panels in story order.', 'no', 'Karnataka', 0, 0, '6:19 AM', '5:58 PM', NULL, 4, 4, 15.3227, 76.4715, 'Royal Enclosure, Kamalapura, Hampi, Karnataka 583221', NULL, 0.8);

