INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000062, 838003, 'Underground Shiva Temple', 'Underground Shiva Temple', 'Also called the Prasanna Virupaksha Temple, a 14th-century Shiva temple near the Royal Enclosure whose sanctum lies several metres below ground level and is often partly submerged in water. Pilgrims wade through the water to reach the inner shrine. The pillared halls and towered sanctum survive largely intact despite centuries of burial.', '30-45 minutes', 'October to March, morning', 'The inner sanctum is frequently waterlogged - roll up trousers or skip the innermost chamber in the monsoon season.', 'no', 'Karnataka', 0, 0, '6:19 AM', '5:58 PM', 'Free', 3, 4, 15.3197, 76.4684, 'Near Royal Enclosure, Kamalapura, Hampi, Karnataka 583221', NULL, 0.68);

