INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000063, 838003, 'Lakshmi Narasimha', 'Lakshmi Narasimha', 'A 6.7-metre monolithic statue of Narasimha, the man-lion avatar of Vishnu, carved from a single boulder in 1528 under Krishnadevaraya - the largest such statue in Hampi. The deity sits in a yogic posture on the coils of the serpent Adishesha; the figure of Lakshmi once seated on his lap is now damaged. It stands in an open enclosure beside the Badavilinga.', '20-30 minutes', 'October to March, daytime', 'Pair it with the Badavilinga Temple right next door; both need only half an hour together.', 'no', 'Karnataka', 0, 0, '6:19 AM', '5:58 PM', NULL, 3, 3, 15.3363, 76.4596, 'Near Hemakuta Hill, Hampi, Karnataka 583239', NULL, 0.6);

