INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000064, 838003, 'Badavilinga Temple', 'Badavilinga Temple', 'A shrine housing a 3-metre monolithic Shiva linga carved from black stone, standing in a stone chamber that is perpetually fed by a water channel so the linga''s base stays submerged. Tradition holds it was commissioned in the 15th century by a poor peasant woman - ''badavi'' meaning poor in Kannada - as an act of devotion. It stands beside the Lakshmi Narasimha statue.', '20-30 minutes', 'October to March, daytime', 'The chamber floor is often under water; remove footwear at the entrance and watch your step on the wet stone.', 'no', 'Karnataka', 0, 0, '6:19 AM', '5:58 PM', NULL, 3, 3, 15.3361, 76.4594, 'Near Hemakuta Hill, Hampi, Karnataka 583239', NULL, 0.6);

