INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000065, 838003, 'Achyutaraya Temple', 'Achyutaraya Temple', 'Built in 1534 by Achyutaraya, successor of Krishnadevaraya, and dedicated to Tiruvengalanatha, a form of Vishnu. Set in a valley between Matanga and Gandhamadana hills near the river, it is reached down a ruined processional street once lined with markets. Being farther from the main circuit, it is quieter than Virupaksha or Vittala and rewards visitors with detailed carvings.', '1-1.5 hours', 'October to March, morning', 'Walk down the old bazaar street to the temple and continue to the riverbank behind it for views back toward Matanga Hill.', 'no', 'Karnataka', 0, 0, '6:19 AM', '5:58 PM', NULL, 3, 4, 15.3381, 76.4658, 'Achyutaraya Temple Rd, Hampi, Karnataka 583239', NULL, 0.68);

