INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000066, 838003, 'Tungabhadra Coracle Ride', 'Tungabhadra Coracle Ride', 'Round, bowl-shaped bamboo coracles ferry passengers across the Tungabhadra between Hampi village and Virupapur Gadde (Hippie Island), a crossing of about 10-15 minutes with views of the riverside ruins. Coracles have been used on this river for centuries and remain the traditional way to cross when the water level permits. Longer joyrides along the riverbank ruins are also offered by local boatmen.', '30 minutes - 1 hour', 'October to March, morning', 'Cross early in the day when the river is calm and boatmen are active; confirm the return crossing time since services thin out by late afternoon.', 'no', 'Karnataka', 0, 1, '6:19 AM', '5:58 PM', NULL, 4, 4, 15.3442, 76.4675, 'Tungabhadra River ferry point, Hampi, Karnataka 583239', NULL, 0.8);

