INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 838000066, 'insert', 'bulk', 'Coracle crossings widely reported by travel guides (outlooktraveller.com). No fixed published fare found - charges are negotiated locally, so cost left null. Coordinates approximate the main ferry point. Sunrise/sunset times are computed for mid-October, not a published per-place schedule.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000067, 838003, 'Hampi Bazaar', 'Hampi Bazaar', 'A roughly 1-km-long ruined market street running east from the Virupaksha Temple toward the foot of Matanga Hill, once the commercial heart where traders from Persia and Portugal did business. Travellers'' accounts claim precious stones were once sold by measure here. Today the colonnaded ruins frame guesthouses, cafes and shops, with a large Nandi statue at the street''s eastern end.', '45 minutes - 1 hour', 'October to March, morning or evening', 'Walk the street at golden hour when the ruins glow; the eastern end near the Nandi is the quietest stretch for photos.', 'no', 'Karnataka', 0, 1, '6:19 AM', '5:58 PM', NULL, 3, 4, 15.3335, 76.4588, 'Hampi Bazaar St, Hampi, Karnataka 583239', NULL, 0.68);

