INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000068, 838003, 'Anjanadri Hill', 'Anjanadri Hill', 'A hill across the river near Anegundi, about 4 km from Hampi, crowned by a whitewashed Hanuman temple and widely believed to be the birthplace of Hanuman (Anjaneya), son of Anjana. Pilgrims climb 575 steps to the summit, which offers sweeping views over paddy fields and the boulder hills of the Hampi landscape. Hanuman Jayanti draws large crowds here.', '2-3 hours', 'October to March, early morning', 'Day trip from Hampi, about 4 km via Anegundi. Climb before 8 AM to avoid the heat; monkeys are bold here, so keep food and bags secured.', 'no', 'Karnataka', 1, 0, '6:19 AM', '5:58 PM', NULL, 4, 4, 15.357, 76.5, 'Anjanadri Hill, Anegundi, Gangavathi, Karnataka 583227', NULL, 0.8);

