INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000069, 838003, 'Pampa Sarovar', 'Pampa Sarovar', 'A sacred lake about 5 km from Hampi on the road to Anegundi, identified in the Ramayana as the place where Shabari waited for and met Rama. Pilgrims consider its waters holy and bathe here; a small Lakshmi temple stands on its bank. The lake is calm and scenic, surrounded by coconut palms and hills.', '45 minutes - 1 hour', 'October to March, morning', 'Day trip from Hampi, about 5 km toward Anegundi. Respectful dress is expected at this pilgrimage spot; combine with Anjanadri Hill nearby.', 'no', 'Karnataka', 0, 0, '6:19 AM', '5:58 PM', NULL, 3, 3, 15.353, 76.486, 'Pampa Sarovar Rd, near Anegundi, Karnataka 583227', NULL, 0.6);

