INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000070, 838003, 'Sanapur Lake', 'Sanapur Lake', 'A reservoir near Sanapur village, about 6 km from Hampi on the north side of the river, set among dramatic boulders and popular with backpackers as a sunset and cliff-jumping spot. The lake''s calm backwaters contrast with the rugged Hampi terrain. It is reached via the Virupapur Gadde side and is a favourite evening hangout.', '1-2 hours', 'October to March, late afternoon', 'Day trip from Hampi, about 6 km via Virupapur Gadde. The rocks are unsupervised - stay well back from cliff edges and do not swim alone.', 'no', 'Karnataka', 0, 1, '6:19 AM', '5:58 PM', NULL, 3, 4, 15.351, 76.493, 'Sanapur, Gangavathi, Karnataka 583234', NULL, 0.68);

