INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000071, 838003, 'Daroji Sloth Bear Sanctuary', 'Daroji Sloth Bear Sanctuary', 'About 20 km from Hampi toward Ballari, India''s first sloth bear sanctuary, established in 1994 across roughly 83 sq km of scrub and boulder hills. Visitors drive in their own vehicle to a watchtower where staff place food on nearby rocks to draw bears out of their caves at dusk; leopards, hyenas, jackals and abundant birdlife also occur. The sanctuary opens only in the afternoon, 2 PM to 6 PM.', '2-3 hours', 'September to February, afternoon', 'Day trip from Hampi, about 20 km. Arrive by 2 PM, bring binoculars or a zoom lens, and book a day ahead at the counter in peak season since entry batches are limited.', 'no', 'Karnataka', 0, 1, '6:19 AM', '5:58 PM', 'Rs 25', 3, 4, 15.2724, 76.4841, 'Daroji, Ballari district, Karnataka 583275', NULL, 0.68);

