INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 838000071, 'insert', 'bulk', 'Afternoon-only opening (2-6 PM) from velpu.com and tripadvisor reviews; 1994 establishment and ~83 sq km widely reported. Entry fee conflicts across sources (Rs 25/adult in a tripadvisor review vs Rs 50/adult on tourmet.com) - used Rs 25 with the review as source and flagged. Watchtower/own-vehicle access per tripadvisor reviews. Coordinates from the meta.ai place listing (15.2718, 76.4836), within 1 km. Sunrise/sunset times are computed for mid-October, not a published per-place schedule.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000072, 838003, 'Tungabhadra Dam and Garden', 'Tungabhadra Dam and Garden', 'About 20 km from Hampi near Hospet, a multipurpose dam built 1949-1953 across the Tungabhadra with 33 crest gates, creating one of the river''s largest reservoirs. The complex includes landscaped gardens, a musical dancing fountain with evening shows, a deer park, aquarium and a hilltop viewpoint with sunset views over the reservoir. A shuttle bus runs from the entrance to the viewpoints.', '2-3 hours', 'October to March, late afternoon to evening', 'Day trip from Hampi, about 20 km via Hospet. Arrive by late afternoon for the viewpoint, then stay for the evening musical fountain show around 7 PM.', 'no', 'Karnataka', 0, 1, '6:19 AM', '5:58 PM', 'Rs 20', 3, 4, 15.2643, 76.3465, 'Tungabhadra Dam, Hospet, Karnataka 583225', NULL, 0.68);

