INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000073, 838003, 'Mango Tree Restaurant', 'Mango Tree Restaurant', 'Hampi''s most famous restaurant, set under the trees near Janatha Plot with low floor seating and a garden ambience. The menu is huge - South Indian thalis, North Indian, Chinese, Continental, Israeli and Tibetan - but the vegetarian South Indian thali and lassis are the signature orders. Barefoot, floor-cushion dining in a relaxed backpacker atmosphere.', '1-1.5 hours', 'October to March, lunch or dinner', 'Arrive early for dinner (around 7 PM) in peak season - it fills up fast; be prepared to remove shoes and possibly share a floor table.', 'no', 'Karnataka', 0, 0, '6:19 AM', '5:58 PM', NULL, 5, 4, 15.334, 76.459, 'Janatha Plot, Hampi Main Road, Hampi, Karnataka 583239', NULL, 0.92);

