INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000074, 838003, 'Gopi Guesthouse and Roof Restaurant', 'Gopi Guesthouse and Roof Restaurant', 'A family-run rooftop restaurant on Janatha Plot, minutes from Virupaksha Temple, with open-air seating facing the temple gopuram and the Tungabhadra. Famous for its banana flower curry and thalis, it serves Indian, Chinese, Mexican and Israeli dishes at backpacker prices. Breakfast on the roof while planning the day''s sightseeing is a Hampi ritual.', '1 hour', 'October to March, breakfast or dinner', 'Sit on the roof for breakfast for the best Virupaksha Temple views; service can be slow at peak hours, so order early.', 'no', 'Karnataka', 0, 0, '6:19 AM', '5:58 PM', NULL, 4, 5, 15.3345, 76.4605, 'Janatha Plot, near Virupaksha Temple, Hampi, Karnataka 583239', NULL, 0.88);

