INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000075, 838003, 'Laughing Buddha Restaurant', 'Laughing Buddha Restaurant', 'A hippie-style cafe on the Virupapur Gadde (north) side of the river with floor cushions, low wooden tables and river views toward Hampi. The menu spans Indian thalis, pizza, pasta, Chinese and Israeli dishes at reasonable prices. Reaching it is part of the experience - a coracle or boat crossing followed by a short walk.', '1-1.5 hours', 'October to March, lunch or evening', 'Arrive by 7 PM for dinner to beat the crowd and get quicker service; plan the river crossing back before dark.', 'no', 'Karnataka', 0, 1, '6:19 AM', '5:58 PM', NULL, 3, 4, 15.3526, 76.3979, 'Main road, Virupapur Gadde, Sanapur, Karnataka 583234', NULL, 0.68);

