INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000076, 838003, 'Shesh Besh', 'Shesh Besh', 'A laid-back restaurant and cafe at Virupapur Gadde on the north side of the river, set among rice fields and palm trees with views of the surrounding hills. The menu covers Indian dishes - both vegetarian and non-vegetarian - plus continental options, in a friendly, oasis-like setting that doubles as a homestay. Named after the backgammon game, with boards available to play.', '1-1.5 hours', 'October to March, daytime', 'A good midday shade stop on the north side; the setting among fields is the draw, so allow an unhurried lunch.', 'no', 'Karnataka', 0, 0, '6:19 AM', '5:58 PM', NULL, 3, 4, 15.353, 76.499, 'Virupapur Gadde, Hampi, Karnataka 583234', NULL, 0.68);

