INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000077, 838003, 'Old Chill Out Ganesh Restaurant', 'Old Chill Out Ganesh Restaurant', 'A vegetarian restaurant on Hampi Road near the Virupaksha Temple area, popular with travellers for its relaxed vibe and Indian vegetarian fare. It is a convenient stop between sightseeing circuits in the main village, with a menu focused on South and North Indian vegetarian dishes at budget prices.', '45 minutes - 1 hour', 'October to March, lunch or dinner', 'Good fallback when the bigger names are packed; stick to the South Indian staples.', 'no', 'Karnataka', 0, 0, '6:19 AM', '5:58 PM', NULL, 3, 3, 15.333, 76.4595, 'Hampi Rd, Hampi, Karnataka 583239', NULL, 0.6);

