INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8380011, 838, 838003, 'Hampi Utsav', 'Nov', 'Karnataka''s state-organized cultural festival recreating the grandeur of the Vijayanagara Empire amid the Hampi ruins - three days of classical and folk music, dance, drama, puppet shows, processions and fireworks around the Virupaksha Temple area.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8380012, 838, 838003, 'Virupaksha Car Festival (Rathotsava)', 'Feb-Mar', 'The annual chariot festival of Virupaksha Temple, when the deity is paraded through Hampi''s streets on a grand wooden chariot pulled by devotees, accompanied by music and dance; the temple''s biggest religious celebration.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8380013, 838, 838003, 'Purandaradasa Aradhana', 'Feb-Mar', 'Annual Carnatic music aradhana honouring the saint-composer Purandaradasa, the ''father of Carnatic music'', who lived and attained samadhi at Hampi; concerts are held in Hampi and organized by the Purandara Dasara Aradhana Samithi Trust.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8380014, 838, 838003, 'Virupaksha-Pampa Wedding Festival (Phalapuja)', 'Dec', 'Annual celebration of the celestial marriage of Lord Virupaksha and goddess Pampadevi at Virupaksha Temple, marked by special pujas and processions.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8380015, 838, 838003, 'Maha Shivaratri at Virupaksha Temple', 'Feb-Mar', 'The great night of Shiva observed with night-long vigils, special abhisheka of the linga and oil-lamp illuminations at Hampi''s principal Shiva temple.');

-- city: Madikeri (id 1024)
INSERT OR IGNORE INTO cities (id, state_id, city_name, latitude, longitude) VALUES (838004, 838, 'Madikeri', 12.424, 75.73172);

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000079, 838004, 'Raja''s Seat', 'Raja''s Seat', 'Madikeri''s iconic sunset viewpoint in town: a garden pavilion on a hilltop where the Kodava kings watched the sunset over the misty Western Ghats. Valley views, seasonal flower beds, a toy train for children and a musical fountain in the evening.', '1-2 hours', 'Sunset, October to March; musical fountain ~7:00 PM weekdays / 6:45 PM weekends', 'Arrive by 5:30 PM to secure a good sunset spot; the musical fountain runs in the evening near the garden entrance.', 'no', 'Karnataka', 1, 1, '06:17', '18:09', 'Rs 5 per adult (conflicting reports of Rs 10-20 on other guides)', 10, 9, 12.4147, 75.73706, 'MG Road, Madikeri, Karnataka 571201', NULL, 1.92);

