INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000080, 838004, 'Abbey Falls', 'Abbey Falls', 'Coorg''s most visited waterfall, about 8 km from Madikeri town: the Kaveri river drops ~70 ft through coffee estates into a gorge. A short walk downhill from the parking leads to a hanging bridge viewpoint facing the falls.', '1-2 hours', 'July to October (post-monsoon flow); mornings to avoid crowds', 'The hanging bridge was reported damaged as of May 2026; bathing and swimming are not permitted. Wear non-slip footwear for the downhill walk.', 'no', 'Karnataka', 1, 1, '06:17', '18:09', 'Rs 30 per person (conflicting report of Rs 15 on one guide)', 10, 8, 12.45621, 75.71712, 'Gaddige Forest Range, Madikeri, Karnataka 571201', NULL, 1.84);

