INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000081, 838004, 'Omkareshwara Temple', 'Omkareshwara Temple', 'An 1820 Shiva temple built by Kodava king Lingarajendra II blending Islamic domes with Gothic and temple architecture, set around a large central water tank. The blend of Hindu and Muslim styles is unique in Coorg.', '45-60 minutes', 'Morning aarti or evening; year-round', 'Dress modestly; photography of the central shrine is restricted. The tank-side walk is peaceful at dusk.', 'no', 'Karnataka', 1, 1, '06:17', '18:09', 'Free', 9, 8, 12.42051, 75.74136, 'Stuart Hill, Madikeri, Karnataka 571201', NULL, 1.72);

