INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 838000081, 'insert', 'bulk', 'Coords geocoded 2026-09-30 (12.42051, 75.74136). Timings 6:30 AM-12 PM and 5-8 PM daily from published guides; free entry. Built 1820 by Lingarajendra II.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000082, 838004, 'Madikeri Fort', 'Madikeri Fort', 'First built as a mud fort by Mudduraja in the late 17th century and rebuilt in stone by Tipu Sultan; the British later added the church (now a museum) and palace within its walls. Today it houses the district museum, government offices, and the stone tortoise and elephant sculptures at the entrance.', '1-2 hours', 'Morning; closed Mondays', 'Combine with Omkareshwara Temple nearby. The museum''s Kodava weapon and artifact collection is the highlight.', 'no', 'Karnataka', 1, 1, '06:17', '18:09', 'Free entry (museum inside charges a nominal fee; conflicting reports Rs 10 vs Rs 20)', 8, 7, 12.42039, 75.73981, 'Madikeri Fort, Madikeri, Karnataka 571201', NULL, 1.52);

