INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 838000082, 'insert', 'bulk', 'Coords geocoded 2026-09-30 (12.42039, 75.73981). Hours 10 AM-5:30 PM, closed Monday from published guides. Museum fee conflicted (Rs 10 vs Rs 20); flagged.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000083, 838004, 'Raja''s Tomb (Gaddige)', 'Raja''s Tomb', 'The 19th-century royal cenotaphs of the Kodava kings at Gaddige: three Indo-Sarcenic domed tombs (Virarajendra, Lingarajendra and the priest Rudrappa) in Islamic style with Nandi bulls, set in a landscaped garden with valley views over Madikeri.', '30-45 minutes', 'Morning or late afternoon; year-round', 'Only one of the three tombs is usually open to visitors. A quiet, quick stop best combined with nearby Abbey Falls.', 'no', 'Karnataka', 1, 1, '06:17', '18:09', 'Rs 10 per person', 7, 7, 12.41812, 75.74067, 'SH 27, Mahadevpet, Madikeri, Karnataka 571201', NULL, 1.4);

