INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000084, 838004, 'Mandalpatti', 'Mandalpatti', 'A high-altitude viewpoint ~18-20 km from Madikeri town in the Pushpagiri range: rolling shola-grassland hills, mist and panoramic valley views, reachable only by 4x4 jeep from the base village (about 30 min off-road). One of Coorg''s best sunrise and sunset spots.', '2-3 hours', 'October to March, at sunrise or sunset; avoid peak monsoon for the jeep track', 'Jeep rides run from the base village; last jeeps leave well before dark. Carry a jacket - it is windy and cold at the top.', 'no', 'Karnataka', 1, 1, '06:17', '18:09', NULL, 9, 9, 12.5461, 75.7019, 'Mandalpatti, Madikeri Taluk, Kodagu, Karnataka 571201', NULL, 1.8);

