INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000085, 838004, 'Dubare Elephant Camp', 'Dubare Elephant Camp', 'A forest-department elephant camp on the banks of the Kaveri, ~30 km from Madikeri: visitors watch the morning bath, feeding and training of captive elephants and can interact with them under mahout supervision. Coracle rides and rafting run nearby in season.', '2-3 hours', 'Morning interaction slot (9-11 AM); October to March', 'Go for the 9 AM slot to see bathing and feeding. Elephant rides are no longer offered; interaction is supervised and time-boxed.', 'no', 'Karnataka', 1, 1, '06:17', '18:09', 'Rs 50 per person entry (conflicting report of Rs 100 on one guide)', 9, 8, 12.36928, 75.90756, 'Dubare Reserve Forest, Kushalnagar, Kodagu, Karnataka 571234', NULL, 1.72);

