INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 838000085, 'insert', 'bulk', 'Coords geocoded 2026-09-30 (12.36928, 75.90756). Interaction timings 9-11 AM and 4:30-5:30 PM from published guides. Entry fee conflicted: Rs 50 (coorgtourism.co.in) vs Rs 100 (suryatara); used Rs 50 and flagged.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000086, 838004, 'Cauvery Nisargadhama', 'Cauvery Nisargadhama', 'A 64-acre river island on the Kaveri near Kushalnagar, ~30 km from Madikeri: bamboo groves, a deer park, rabbit and peacock parks, an orchidarium, boating and a children''s play area. Crossed by a hanging rope bridge; a classic family picnic spot.', '3-4 hours', 'October to March; full day picnic', 'Carry food and water; eateries inside are limited. The rope bridge is the fun entry - photography of the bamboo canopy is best in morning light.', 'no', 'Karnataka', 1, 1, '06:17', '18:09', 'Rs 10 per person entry (conflicting report of Rs 20); elephant ride Rs 25, boating Rs 100, zipline Rs 100', 8, 8, 12.46962, 75.96164, 'Nisargadhama, Kushalnagar, Kodagu, Karnataka 571234', NULL, 1.6);

