INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 838000086, 'insert', 'bulk', 'Coords geocoded 2026-09-30 (12.46962, 75.96164). Hours 9 AM-5 PM daily from majority of guides (kodagu.nic.in says 9 AM-6 PM - flagged). Entry fee conflicted: Rs 10 (three guides) vs Rs 20 (airial); used Rs 10. No dedicated official website found.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000087, 838004, 'Chelavara Falls', 'Chelavara Falls', 'A 150-ft waterfall ~42 km from Madikeri (16 km from Virajpet) formed by a Kaveri tributary, falling over the tortoise-shaped Embepare rock: viewable after a 200 m walk from the parking into the forest. Less crowded than Abbey Falls, near the Tadiandamol base.', '2 hours', 'June to October (monsoon/post-monsoon); best before 2 PM', 'About 20 deaths have been recorded here - never cross the fence or enter the pool; currents are treacherous, especially in monsoon. Visit in daylight and in groups.', 'no', 'Karnataka', 1, 1, '06:17', '18:09', 'Free', 7, 7, 12.2062, 75.67333, 'Cheyyandane, Virajpet - Talakaveri Road (SH 90), Kodagu, Karnataka 571212', NULL, 1.4);

