INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 838000087, 'insert', 'bulk', 'Coords 12.2062, 75.67333 confirmed 2026-09-30 (geocoder + place-directory listing agree; Wikipedia places it at Cheyyandane, 16 km from Virajpet). Free entry, 6 AM-6 PM from thrillophilia. Distance from Madikeri varies by source (37-43 km); used ~42 km.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000088, 838004, 'Honnamana Kere', 'Honnamana Kere', 'The largest natural lake in Coorg, ~46 km from Madikeri near Somwarpet: a serene lake ringed by coffee estates and the Gavi Betta and Mori Betta hills, with a Honnamma Devi temple on its banks. Boating and fishing are possible; newlywed couples visit during the Gowri festival.', '1-2 hours', 'Winter (November to February); evenings', 'Combine with a Somwarpet homestay stay; the lakeside gets deserted after dark, so leave before sunset.', 'no', 'Karnataka', 1, 1, '06:17', '18:09', 'Free', 6, 7, 12.62079, 75.88062, 'Doddamalthe, Somwarpet, Kodagu, Karnataka 571236', NULL, 1.28);

