INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 838000088, 'insert', 'bulk', 'Coords 12.62079, 75.88062 (place-directory listing, 2.9 miles from Somwarpet, consistent with ~46 km from Madikeri per trawell). Timings 8 AM-6 PM and free entry from three guides (one visitor review says open till 8 PM - flagged).', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000089, 838004, 'Harangi Dam', 'Harangi Dam', 'The first dam across the Kaveri, ~36 km from Madikeri near Kushalnagar: 47 m high and 846 m long, set in quiet greenery. A relaxed picnic and photography spot; at its fullest and most scenic in August-September.', '2 hours', 'August to September (reservoir full); mornings', 'Stay out of restricted zones near the dam wall; access can be limited after heavy rains. Pair with Dubare or Nisargadhama the same day.', 'no', 'Karnataka', 1, 1, '06:17', '18:09', 'Rs 10 per adult, Rs 5 per child; parking Rs 10', 6, 7, 12.49396, 75.90543, 'Hudgur, Somwarpet Taluk, Kodagu, Karnataka 571234', NULL, 1.28);

