INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000090, 838004, 'Chiklihole Reservoir', 'Chiklihole Reservoir', 'A small 1985 irrigation reservoir ~24 km from Madikeri with a unique semi-circular dam: when full, water overflows like foam over the curved crest - a striking sight in monsoon. Surrounded by Attur forest; a peaceful sunset picnic spot.', '1-2 hours', 'June to September (full reservoir); sunset', 'Carry your own food and water - no shops nearby. The approach road through the forest is narrow; drive carefully in monsoon.', 'no', 'Karnataka', 1, 1, '06:17', '18:09', 'Free', 6, 7, 12.39633, 75.87867, 'Attur Forest, Nanjarayapattana, Kodagu, Karnataka 571234', NULL, 1.28);

