INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000091, 838004, 'Tadiandamol Peak', 'Tadiandamol Peak', 'Coorg''s highest peak (1,748 m / 5,735 ft): an easy-moderate 15 km round-trip trek from the Nalknad Palace base through shola forest and grasslands to panoramic Western Ghats views. Plastic is counted at entry; online booking via the forest department portal is recommended.', '6-8 hours (full day trek)', 'October to March; start by 7 AM, back by 5:30 PM', 'Cut-off: no entry past the forest checkpost after 2:30 PM. Carry 2L water, ID proof, rain gear and leech socks in monsoon; follow the orange ribbon markers on the final ascent.', 'recommended', 'Karnataka', 1, 1, '06:17', '18:09', 'Rs 100 per person forest entry (conflicting report of Rs 250 on one 2026 guide)', 9, 9, 12.21787, 75.60921, 'Yevakapadi, Kakkabe, Kodagu, Karnataka 571212', NULL, 1.8);

