INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000092, 838004, 'Nalknad Palace', 'Nalknad Palace', 'The 1792-94 hunting lodge and last refuge of the Haleri kings of Kodagu, ~35 km from Madikeri at the foot of Tadiandamol: a two-storey Kodava-style palace with wooden carvings, a low conical roof, ancient wall paintings and a ruined wedding mantapa. Renovated by INTACH; a protected monument.', '1-1.5 hours', 'October to March; pair with the Tadiandamol trek base', 'Visit on the way to or from the Tadiandamol trek - it sits at the trek base. Interiors are modest; come for the architecture and history.', 'no', 'Karnataka', 1, 1, '06:17', '18:09', 'Free', 7, 7, 12.2344, 75.64056, 'Nalknad Palace Road, Yevakapadi, Kakkabe, Kodagu, Karnataka 571214', NULL, 1.4);

