INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000093, 838004, 'Namdroling Monastery (Golden Temple)', 'Namdroling Monastery', 'Day trip ~35 km from Madikeri (towards Kushalnagar): the largest Nyingma Tibetan Buddhist monastery in the world, founded 1963 by Pema Norbu Rinpoche. The Padmasambhava Buddhist Vihara holds giant gilded statues of Buddha, Amitayus and Padmasambhava amid ornate wall paintings. Prayer sessions are open to visitors.', '2-3 hours', 'Morning prayer sessions; year-round', 'Remove footwear before entering the main shrine (Rs 2 deposit counter). Photography is restricted inside the prayer hall; dress modestly.', 'no', 'Karnataka', 1, 1, '06:17', '18:09', 'Free', 10, 9, 12.43092, 75.96814, 'Golden Temple Road, Arlikumari, Bylakuppe, Karnataka 571104', NULL, 1.92);

