INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000094, 838004, 'Talakaveri Temple', 'Talakaveri Temple', 'Day trip ~45-48 km from Madikeri via Bhagamandala: the sacred birthplace of the river Kaveri at 1,276 m on Brahmagiri hill - a small spring (Brahma Kundike) in a temple courtyard, with a shrine to Goddess Kaveramma and a 350-step climb to the hilltop viewpoint. Strict dress code; the misty ghat drive is part of the experience.', '2-3 hours', 'Morning; Tula Sankramana (Oct) for the holy dip', 'No shorts or sleeveless wear - dress modestly. Climb the Brahmagiri steps for the Western Ghats panorama (the upper viewpoint section has been closed at times).', 'no', 'Karnataka', 1, 1, '06:17', '18:09', 'Free entry (donations for pujas)', 9, 9, 12.38573, 75.49241, 'Tala Kaveri, Cherangala, Kodagu, Karnataka 571247', 'https://talakaveritemple.com/', 1.8);

