INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 838000094, 'insert', 'bulk', 'Coords geocoded 2026-09-30 (12.38573, 75.49241; directory listing 12.385439, 75.49117 agrees). Hours 6 AM-6 PM from tripnetra''s detailed schedule (one source says 8:30-12:30 & 2:30-5:30 - flagged). Free entry consistent. Official site talakaveritemple.com fetched 2026-09-30 and belongs to the temple (Karnataka Hindu religious dept managed).', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000095, 838004, 'Bhagamandala', 'Bhagamandala', 'Day trip ~36 km from Madikeri, on the way to Talakaveri: the Triveni Sangama - confluence of the Kaveri, Kannike and the mythical Sujyothi - with the ancient Bhagandeshwara Shiva temple complex. Pilgrims stop here before Talakaveri; the ghat steps and temple tank are the focal points.', '1-2 hours', 'Morning; combine with Talakaveri (8 km further)', 'Visit Bhagamandala and Talakaveri as one trip from Madikeri. Cars pay a small entry fee at the Bhagamandala checkpoint (Rs 20-30 per reviews; not officially confirmed).', 'no', 'Karnataka', 1, 1, '06:17', '18:09', NULL, 7, 7, 12.38527, 75.52759, 'Bhagamandala, Madikeri Taluk, Kodagu, Karnataka 571247', NULL, 1.4);

