INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000096, 838004, 'Iruppu Falls', 'Iruppu Falls', 'Day trip ~75 km from Madikeri via Virajpet and Srimangala: the Lakshmana Tirtha river plunges 170 ft in the Brahmagiri range, reached by a 1 km forest walk. A sacred site linked to the Ramayana (Rama and Lakshmana are said to have stopped here); the Rameshwara temple stands at the entrance.', '2-3 hours', 'June to October (post-monsoon flow)', 'The 1 km walk from the parking is through forest - wear good shoes and carry water. Start early; it is a long drive from Madikeri.', 'no', 'Karnataka', 1, 1, '06:17', '18:09', 'Rs 50 per person (one guide says free - conflict)', 8, 8, 11.97547, 76.00701, 'Srimangala, Virajpet Taluk, Kodagu, Karnataka 571225', NULL, 1.6);

