INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 838000096, 'insert', 'bulk', 'Coords geocoded 2026-09-30 (11.97547, 76.00701). Hours 6 AM-6 PM from guides. Entry fee conflicted: Rs 50 on most guides vs ''free'' on one guide - flagged. Distance ~75-80 km from Madikeri via Virajpet/Srimangala.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000097, 838004, 'Mallalli Falls', 'Mallalli Falls', 'Day trip ~55 km from Madikeri (25 km from Somwarpet): one of Karnataka''s tallest waterfalls - the Kumaradhara river drops ~200 m at the foot of Pushpagiri peak in dense forest. Reached by a steep ~1 km trek down uneven terrain from the viewpoint; the post-monsoon cascade is most forceful.', '3-4 hours', 'June to September (peak flow); avoid the base in heavy monsoon', 'The descent to the base is steep and slippery - wear proper trekking shoes. Currents at the bottom are strong; swim only with caution and carry a change of clothes.', 'no', 'Karnataka', 1, 1, '06:17', '18:09', 'Free', 8, 8, 12.68196, 75.72683, 'Kumarahalli, Somwarpet Taluk, Kodagu, Karnataka 571236', NULL, 1.6);

