INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 838000097, 'insert', 'bulk', 'Coords geocoded 2026-09-30 (12.68196, 75.72683) - Pushpagiri foothills area, approximate. Timings 8:30 AM-5 PM and no entry fee from MakeMyTrip tripideas guide. Distance ~55 km from Madikeri per guide.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000098, 838004, 'Nagarahole National Park', 'Nagarahole National Park', 'Day trip ~90 km from Madikeri: one of India''s premier tiger reserves (a Project Tiger site since 1999), contiguous with Bandipur and Wayanad. Safaris run from Kakanakote, Veeranahosahalli and Nanachi gates; elephants, gaur, wild dogs and leopards are commonly sighted, tigers with luck. Advance safari booking is recommended.', '4-5 hours (safari + travel)', 'November to May (wildlife sightings peak April-May); morning safari', 'Book safaris in advance - slots fill on weekends. From Madikeri, the Nanachi gate is the nearest entry; carry ID for the permit.', 'yes', 'Karnataka', 1, 1, '06:17', '18:09', 'Safari: jeep Rs 500 / bus Rs 300 (Indian); park entry Rs 50; camera Rs 50', 9, 9, 11.99648, 76.07506, 'Nanachi Gate, Nagarahole, Mysuru district, Karnataka 571105', NULL, 1.8);

