INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000099, 838004, 'Taste of Coorg', 'Taste of Coorg', 'A well-known Coorgi restaurant in Madikeri town specialising in authentic Kodava cuisine: pandi curry (pork), bamboo shoot curry, kadambuttu (rice dumplings) and akki ottis. Budget-friendly and popular with both locals and tourists.', '1 hour', 'Lunch or dinner; October to March', 'Order the pandi curry with kadambuttu - the signature combination. Gets busy at dinner; go early.', 'no', 'Karnataka', 1, 1, '06:17', '18:09', 'Rs 200 for two', 9, 8, 12.419557, 75.739305, 'Madikeri, Karnataka 571201', NULL, 1.72);

