INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000100, 838004, 'Raintree Restaurant', 'Raintree Restaurant', 'Coorg''s first elite multi-cuisine restaurant (est. 2010) in the 100-year-old Belliappa House - the heritage home that hosted Mahatma Gandhi in the 1920s. North Indian, tandoor, Oriental, South Indian and Coorg specialties under a rain-tree canopy; signature elaneer payasam (tender coconut dessert) and the Beans N Brews cafe.', '1.5-2 hours', 'Dinner; book ahead on weekends', 'Pet-friendly restaurant. Book a table via the official site; finish with the elaneer payasam.', 'no', 'Karnataka', 1, 1, '06:17', '18:09', NULL, 9, 9, 12.419078, 75.739056, '13-14, Pension Lane, behind Town Hall, Madikeri, Karnataka 571201', 'https://raintreerestaurantcoorg.com/', 1.8);

