INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000104, 838004, 'Hotel Udupi Garden', 'Hotel Udupi Garden', 'A pure-vegetarian Udupi-style restaurant on Main Road, Madikeri: dosas, idlis, vadas, meals and fresh juices - classic Karnataka veg fare in the town centre.', '30-45 minutes', 'Breakfast or lunch', 'Good budget breakfast stop on Main Road. Pure veg.', 'no', 'Karnataka', 1, 1, '06:17', '18:09', 'Rs 350 for two', 6, 6, 12.41981, 75.7399, 'Main Road, Madikeri, Karnataka 571201', NULL, 1.2);

