INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8380016, 838, 838004, 'Madikeri Dasara', 'Sep-Oct', 'Coorg''s most famous festival, distinct from Mysuru''s: ten temples of Madikeri (including Durgaparameshwari) parade their deities on grand mantapas in a midnight procession on Vijayadashami night, drawing lakhs of devotees and tourists. The town''s peak cultural week.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8380017, 838, 838004, 'Tula Sankramana (Kaveri Sankramana)', 'Oct', 'The holiest day at Talakaveri: at the auspicious moment (tula sankramana) the spring at Brahma Kundike is believed to fill with a gush of water; thousands gather for the teertha snana (holy dip) at the birthplace of the river Kaveri.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8380018, 838, 838004, 'Puthari', 'Nov-Dec', 'The Kodava harvest festival: at midnight, the sheaf of new paddy is cut to the sound of a gunshot, then carried home with a procession; homes feast on thambuttu (mashed banana and sesame) and celebrate for days.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8380019, 838, 838004, 'Kailpodh', 'Sep', 'The Kodava festival of weapons: after the transplanting season, families clean and worship their traditional arms (guns, swords, daggers), followed by sporting contests like coconut shooting and feasting on pandi curry.');

-- city: Gokarna (id 1025)
INSERT OR IGNORE INTO cities (id, state_id, city_name, latitude, longitude) VALUES (838005, 838, 'Gokarna', 14.547, 74.319);

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000105, 838005, 'Mahabaleshwar Temple', 'Mahabaleshwar Temple', 'Mahabaleshwar Temple is Gokarna''s principal pilgrimage site, dedicated to Lord Shiva and housing the sacred Atmalinga brought, per legend, by Ravana from Mount Kailash. The temple dates to around the 4th century CE, built in Dravidian style with a 1500-year-old carved stone Shiva deity, and is revered as Dakshina Kashi (Kashi of the South).', '1-2 hours', 'October to February, early morning for darshan', 'Dress traditionally (dhoti/saree; no shorts/jeans); men are typically required to go bare-chested in the sanctum. Photography inside is prohibited.', 'no', 'Karnataka', 0, 0, '6:22 AM', '6:22 PM', NULL, 5, 4, 14.5438, 74.3175, 'Koti Tirtha Road, Gokarna, Karnataka 581326', NULL, 0.92);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (838000105, 838000105, '6:00 AM - 12:30 PM, 5:00 PM - 8:00 PM', '6:00 AM - 12:30 PM, 5:00 PM - 8:00 PM', '6:00 AM - 12:30 PM, 5:00 PM - 8:00 PM', '6:00 AM - 12:30 PM, 5:00 PM - 8:00 PM', '6:00 AM - 12:30 PM, 5:00 PM - 8:00 PM', '6:00 AM - 12:30 PM, 5:00 PM - 8:00 PM', '6:00 AM - 12:30 PM, 5:00 PM - 8:00 PM', 'Temple closes midday; sparsha darshan and abhishekams happen in morning seva hours.');

