INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000106, 838005, 'Maha Ganapati Temple', 'Maha Ganapati Temple', 'The Maha Ganapati Temple stands adjacent to Mahabaleshwar Temple and is dedicated to Lord Ganesha, who is traditionally worshipped first before darshan of the Atmalinga. The ancient temple is known for its intricate carvings and is a key stop on the pilgrim circuit. Pilgrims believe seeking Ganesha''s blessing first is essential for the main darshan.', '30-45 minutes', 'October to February, mornings', 'Visit here before Mahabaleshwar Temple — local tradition holds that the Atmalinga darshan is incomplete without Ganesha''s blessing first.', 'no', 'Karnataka', 0, 0, '6:22 AM', '6:22 PM', NULL, 4, 4, 14.5434, 74.3178, 'Koti Tirtha Road, Gokarna, Karnataka 581326', NULL, 0.8);

