INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000107, 838005, 'Koti Tirtha', 'Koti Tirtha', 'Koti Tirtha is the sacred tank of Gokarna, set opposite the Mahabaleshwar Temple and surrounded by small shrines. Pilgrims take a ritual holy dip here before visiting the Atmalinga, and the tank is believed to have been formed by Lord Shiva. It is central to festival bathing rituals during Shivaratri and Kartika.', '30 minutes', 'October to February, mornings', 'Bathe early morning like the pilgrims do, then walk straight into the Mahabaleshwar Temple for darshan — this is the traditional sequence.', 'no', 'Karnataka', 0, 0, '6:22 AM', '6:22 PM', NULL, 4, 4, 14.5447, 74.3173, 'Koti Tirtha Road, opposite Mahabaleshwar Temple, Gokarna 581326', NULL, 0.8);

