INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000108, 838005, 'Bhadrakali Temple', 'Bhadrakali Temple', 'The Bhadrakali Temple in Gokarna is dedicated to Goddess Uma worshipped in her Bhadrakali (Shakti) form. It is one of the town''s notable spiritual sites, cited for its impressive traditional architecture and divine atmosphere. Devotees visit it as part of the town''s Shakti-and-Shaiva pilgrim circuit.', '30-45 minutes', 'October to February', 'Club it with the Mahabaleshwar and Maha Ganapati temples in a single morning temple walk through town.', 'no', 'Karnataka', 0, 0, '6:22 AM', '6:22 PM', NULL, 3, 3, 14.5462, 74.3152, 'Gokarna town, Uttara Kannada, Karnataka 581326', NULL, 0.6);

