INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000109, 838005, 'Sode Vadiraja Matha', 'Sode Vadiraja Matha', 'Sri Sode Vadiraja Matha''s Gokarna branch is one of the centres of the Sode lineage, one of the eight Ashta Mathas of Udupi founded in the Dvaita Vedanta tradition of Madhvacharya. The matha sits on the Gokarna-Kudle road opposite Koti Tirtha and serves spiritual seekers drawn to the town''s Advaita and Dvaita traditions. Its official site documents 700+ years of lineage with daily darshana rituals.', '45-60 minutes', 'October to March, mornings or evenings', 'Time your visit for the morning suprabhata or evening deeparadhane to experience the daily rituals; dress modestly.', 'no', 'Karnataka', 0, 0, '6:22 AM', '6:22 PM', NULL, 3, 4, 14.5412, 74.3201, 'Gokarna Kudle Road, opposite Koti Theertha, Gokarna 581326', 'https://sodematha.in/', 0.68);

