INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000110, 838005, 'Gokarna Beach (Town Beach)', 'Gokarna Main Beach', 'Gokarna''s town beach, also called Gokarna Main Beach, is the pilgrim beach where devotees bathe after temple darshan before entering the Mahabaleshwar sanctum. It is a long golden-sand stretch lined with coconut palms, flanked by the Kariyappa Temple side, and is calmer and more local than the trekking beaches to the south.', '1-2 hours', 'October to March, mornings and late afternoons', 'Watch the morning temple rituals on the sand, but swim at Om or Kudle instead — this beach has pilgrim footfall and stronger local use.', 'no', 'Karnataka', 0, 1, '6:22 AM', '6:22 PM', NULL, 4, 3, 14.5437, 74.3137, 'Gokarna Beach Road, Gokarna, Karnataka 581326', NULL, 0.72);

