INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000111, 838005, 'Om Beach', 'Om Beach', 'Om Beach is named for its shape: two crescents that together resemble the sacred ॐ (Om) symbol when viewed from above. It is one of Gokarna''s most popular beaches, good for swimming and snorkeling, with a trailhead for the coastal trek to Half Moon and Paradise beaches. The beach has shacks, cafes and sunset-view dining.', '2-3 hours', 'October to March, late afternoons for sunset', 'Take the cliff-top trail south toward Half Moon Beach for the full Om-shape viewpoint, and come back for sunset at one of the beach shacks.', 'no', 'Karnataka', 0, 1, '6:22 AM', '6:22 PM', NULL, 5, 5, 14.5184, 74.317, 'Om Beach Road, Gokarna, Karnataka 581326', NULL, 1.0);

