INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 838000111, 'insert', 'bulk', 'Coordinates approximate (north lobe of Om beach). No published hours. Sunset is directly over the sea here (west-facing coast).', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000112, 838005, 'Kudle Beach', 'Kudle Beach', 'Kudle Beach is known for its golden sands and clear waters and is a favourite of both tourists and locals. The path down to the beach is lined with shacks and huts serving food and drinks, and the beach has a lively yet laid-back tourist scene. It is one of the most accessible and best-serviced beaches in Gokarna.', '2-4 hours', 'October to March, mornings and late afternoons', 'Grab a shack table for lunch and stay through sunset; parking is at the hilltop and the path down is short but steep.', 'no', 'Karnataka', 0, 1, '6:22 AM', '6:22 PM', NULL, 5, 4, 14.5298, 74.3154, 'Kudle Beach, Gokarna, Karnataka 581326', NULL, 0.92);

