INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000113, 838005, 'Half Moon Beach', 'Half Moon Beach', 'Half Moon Beach is a small, relatively less-crowded beach named for its crescent shape. It is reachable only by boat or a trek along the cliff trail from Om Beach, which keeps it quiet. The calm waters and picturesque setting make it a favourite stop on the Gokarna beach trek.', '2-3 hours', 'October to March, mornings', 'Wear trekking footwear and carry water — the Om Beach to Half Moon trail is short but rocky; boats back to Om Beach are available.', 'no', 'Karnataka', 0, 1, '6:22 AM', '6:22 PM', NULL, 4, 5, 14.5021, 74.322, 'Coastal trail between Om Beach and Paradise Beach, Gokarna 581326', NULL, 0.88);

