INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 838000113, 'insert', 'bulk', 'Coordinates approximate (crescent cove south of Om Beach). No published hours. West-facing coast with genuine sunset views.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000114, 838005, 'Paradise Beach', 'Paradise Beach', 'Paradise Beach is the most secluded of Gokarna''s beaches, reachable only by a strenuous forest trek or by boat. Surrounded by hills on three sides with the Arabian Sea on the fourth, it offers pristine sands and clear water. Sources note it as the quietest, most untouched beach in the Gokarna cluster.', 'Half day to full day', 'October to March, full day trek', 'Plan this as a full-day beach trek from Om Beach (through Half Moon) and arrange a boat ride back — trekking the entire return is long.', 'no', 'Karnataka', 0, 1, '6:22 AM', '6:22 PM', NULL, 4, 5, 14.497, 74.325, 'South of Half Moon Beach, accessible via trail or boat, Gokarna 581326', NULL, 0.88);

