INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000115, 838005, 'Small Hell Beach', 'Small Hell Beach', 'Small Hell Beach is a tiny cove on the coastal trail between Half Moon and Paradise beaches. Like its neighbours it is reachable only on foot or by boat and is rarely crowded. It is often mentioned as a hidden stop on the full Om-to-Paradise beach trek.', '30-60 minutes', 'October to March', 'Stop here for a quick dip mid-trek rather than as a destination — there are no shacks or facilities.', 'no', 'Karnataka', 0, 1, '6:22 AM', '6:22 PM', NULL, 2, 4, 14.4937, 74.328, 'Coastal trail near Paradise Beach, Gokarna 581326', NULL, 0.56);

