INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000116, 838005, 'Belekan Beach', 'Belekan Beach', 'Belekan Beach is a rocky cove on the coastal trail between Om and Half Moon beaches. It is wilder and rockier than its neighbours and is known as a quiet detour on the Gokarna beach trek rather than a swimming beach. The rocks and tide pools make it a scenic stop.', '30 minutes', 'October to March', 'Not ideal for swimming due to rocks — treat it as a photo stop on the Om to Half Moon hike.', 'no', 'Karnataka', 0, 1, '6:22 AM', '6:22 PM', NULL, 2, 3, 14.511, 74.329, 'Between Om Beach and Half Moon Beach, Gokarna 581326', NULL, 0.48);

