INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000117, 838005, 'Gogarbha Cave', 'Gogarbha Cave', 'Gogarbha Cave is a Shiva cave shrine set on a hilltop along the path toward Kudle Beach. It is a small, naturally formed cave with religious significance for local devotees and offers elevated views over the coastline. The cave sits along the route that cafes like Om D.S. Cafe reference as a landmark.', '45 minutes', 'October to March, mornings', 'Combine it with the walk to Kudle Beach — the climb is short and the viewpoint at the top is the payoff.', 'no', 'Karnataka', 0, 1, '6:22 AM', '6:22 PM', NULL, 2, 3, 14.5367, 74.3167, 'Hilltop on the Kudle Beach path, Gokarna 581326', NULL, 0.48);

