INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000118, 838005, 'Nirvana Beach', 'Nirvana Beach (Kumta)', 'Nirvana Beach near Kumta, about 20 km south of Gokarna, is one of the quieter beaches on this coast with clean sands and calm waters. It is listed among Gokarna''s extended beach cluster and is a good day-trip alternative when Gokarna''s main beaches are busy. The beach sees mostly local and low-key tourist footfall.', '2-3 hours', 'October to March, late afternoons', 'Day trip (~20 km from Gokarna town) — go by auto or taxi; carry your own food as shacks are sparse.', 'no', 'Karnataka', 0, 1, '6:22 AM', '6:22 PM', NULL, 3, 4, 14.47, 74.345, 'Nirvana Beach Road, Kumta, Uttara Kannada, Karnataka 581339', NULL, 0.68);

