INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 838000118, 'insert', 'bulk', 'Day-trip destination ~20 km from Gokarna. Coordinates approximate. No published hours.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000119, 838005, 'Yana Caves', 'Yana Caves', 'Yana Caves are famous for two massive black crystalline karst limestone formations — Bhairaveshwara Shikhara and Mohini Shikhara — rising from the evergreen forests of the Western Ghats. A cave temple dedicated to Lord Shiva lies at their base, and the site is reached by a scenic forest trek. It is one of the most distinctive geological sights in Karnataka and a standard day trip from Gokarna (about 58 km, roughly 2 hours).', '4-5 hours', 'October to March', 'Leave Gokarna early — the drive is ~2 hours and the forest trek to the formations takes about 45 minutes; pair it with Vibhooti Falls.', 'no', 'Karnataka', 0, 0, '6:22 AM', '6:22 PM', NULL, 5, 5, 14.5865, 74.5655, 'Yana village, Uttara Kannada, Karnataka 581359 (~58 km from Gokarna)', NULL, 1.0);

