INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000120, 838005, 'Mirjan Fort', 'Mirjan Fort', 'Mirjan Fort is a 16th-century fort about 22 km from Gokarna, popularly attributed to Rani Chennabhairadevi, the queen of Gerusoppa (its exact origins are debated). Built in laterite stone, it is known for its architectural elegance — high walls, bastions, four main entrances, moats, watchtowers and secret passages. It is a well-preserved ASI-protected site and a common half-day trip from Gokarna.', '2-3 hours', 'October to March, mornings', 'Carry water and a hat — the fort grounds are large and exposed; a guide helps decode the bastions and moats.', 'no', 'Karnataka', 0, 0, '6:22 AM', '6:22 PM', NULL, 4, 4, 14.4907, 74.4217, 'Mirjan, Kumta taluk, Uttara Kannada, Karnataka 581440 (~22 km from Gokarna)', NULL, 0.8);

