INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000121, 838005, 'Vibhooti Falls', 'Vibhooti Falls', 'Vibhooti Falls is a waterfall tucked in the Western Ghats forests near Yana, about 55 km from Gokarna and roughly 9.7 km from the Yana rock formations. It is a popular post-trek dip spot on the Yana day trip, surrounded by dense forest. Sources describe it as a refreshing natural swimming stop.', '1-2 hours', 'October to January (post-monsoon flow)', 'Go after the monsoon when the flow is strong; wear grip footwear as the forest path and rocks are slippery.', 'no', 'Karnataka', 0, 0, '6:22 AM', '6:22 PM', NULL, 3, 4, 14.5725, 74.535, 'Near Yana, Uttara Kannada, Karnataka (~55 km from Gokarna)', NULL, 0.68);

