INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 838000121, 'insert', 'bulk', 'Day-trip destination ~55 km from Gokarna, usually combined with Yana. Coordinates approximate. No published hours/fees.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000122, 838005, 'Murudeshwar', 'Murudeshwar Temple and Shiva Statue', 'Murudeshwar, about 78 km from Gokarna, is home to one of the world''s tallest Shiva statues (123 ft) and a 20-storey gopuram at the Sri Murudeshwara Temple complex on the coast. The temple is dedicated to Lord Shiva and holds an Atmalinga fragment tied to the same Ravana legend as Gokarna. The statue, sea and temple complex together make it the signature coastal temple day trip from Gokarna.', '4-6 hours', 'October to March', 'Allow a full day (about 2 hours each way); climb the gopuram for the panoramic view of the statue against the sea.', 'no', 'Karnataka', 0, 1, '6:22 AM', '6:22 PM', NULL, 5, 5, 14.0945, 74.4845, 'Murudeshwar, Bhatkal taluk, Uttara Kannada, Karnataka 581350 (~78 km from Gokarna)', NULL, 1.0);

