INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 838000122, 'insert', 'bulk', 'Day-trip destination ~78 km from Gokarna (within 100 km). Coordinates approximate for the temple complex. Temple hours unpublished; left null per policy.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000123, 838005, 'Idagunji Mahaganapati Temple', 'Idagunji Mahaganapati Temple', 'The Idagunji Mahaganapati Temple near Honnavar, about 28 km from Gokarna, is one of coastal Karnataka''s most important and ancient Ganapati shrines. The temple''s Ganesha idol is traditionally associated with the same legend cycle as Gokarna''s Atmalinga (Ganesha''s role in fixing the linga). It draws steady pilgrim traffic year-round.', '1-2 hours', 'October to March', 'Easy half-day trip toward Honnavar; combine with the Mirjan Fort in a single outing.', 'no', 'Karnataka', 0, 0, '6:22 AM', '6:22 PM', NULL, 3, 4, 14.5654, 74.4803, 'Idagunji, Honnavar taluk, Uttara Kannada, Karnataka 581423 (~28 km from Gokarna)', NULL, 0.68);

