INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000124, 838005, 'Sahasralinga', 'Sahasralinga', 'Sahasralinga, about 90 km from Gokarna near Sirsi, is a riverside pilgrimage site where over a thousand Shiva lingas are carved into the rocks of the Shalmala river bed, surrounded by lush forest. The lingas and carved Nandi figures become fully visible in the dry season when the water level drops. It is traditionally visited together with the nearby Madhukeshwara Temple of Banavasi on a Sirsi-region day trip.', '2-3 hours', 'October to March (dry season, lingas visible)', 'Visit in the dry months when the river is low and the carvings are exposed; combine with Banavasi in the same day trip.', 'no', 'Karnataka', 0, 0, '6:22 AM', '6:22 PM', NULL, 3, 4, 14.7247, 74.8078, 'Shalmala river, near Sirsi, Uttara Kannada, Karnataka 581401 (~90 km from Gokarna)', NULL, 0.68);

