INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 838000124, 'insert', 'bulk', 'Day-trip destination ~90 km from Gokarna (within 100 km); distance per tour-itinerary sources (Sirsi ~63 km from Kumta, Sahasralinga ~10 km from Sirsi). Coordinates approximate for the river site. No published hours/fees.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000125, 838005, 'Namaste Cafe', 'Namaste Cafe', 'Namaste Cafe is a heritage beachfront cafe on Om Beach and also offers guest accommodation. It is known for dosas and uttapams, grilled seafood like pomfret, crepes and European breakfast items, plus mocktails and beer served in a large open dining area amid tropical greenery. It is described as the only heritage cafe on Om Beach and is popular with both tourists and people from neighbouring towns.', '1-2 hours', 'October to March, breakfast or dinner', 'Try the masala dosa or uttapam for breakfast and the grilled pomfret at dinner — both are the most recommended items.', 'no', 'Karnataka', 0, 1, '6:22 AM', '6:22 PM', NULL, 4, 4, 14.5195, 74.3186, 'Om Beach Road, Gokarna, Karnataka 581326', NULL, 0.8);

