INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000126, 838005, 'Mantra Cafe', 'Mantra Cafe', 'Mantra Cafe, located at Zostel on Kudle Beach Road near Kudle Beach, is one of Gokarna''s best-known cafes with exotic beachfront views from its hut structure. Travellers recommend the Nutella banana pancakes, paneer butter masala, pizzas and prawns in butter. The cafe is a popular hangout with bonfire seating and sea breezes.', '1-2 hours', 'October to March, evenings', 'Go for the sunset hour on the deck and order the Nutella banana pancakes — the cafe''s most cited dish.', 'no', 'Karnataka', 0, 1, '6:22 AM', '6:22 PM', NULL, 4, 4, 14.5401, 74.315, 'Zostel, Kudle Beach Road, Dandebagh, Gokarna 581326', NULL, 0.8);

