INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000127, 838005, 'Pai Hotel', 'Pai Hotel', 'Pai Hotel is a long-running pure-vegetarian restaurant on Car Street serving South Indian staples at inexpensive prices. It is famous for its masala dosa, veg thali, Mangalore buns and generous refills of filter coffee and milk tea. The simple, crowded dining room is filled with travellers and locals and is considered one of Gokarna town''s beloved budget institutions.', '45-60 minutes', 'Year-round, breakfast and lunch', 'Order the Mangalore buns and masala dosa with filter coffee — the classic budget breakfast; expect a queue at peak hours.', 'no', 'Karnataka', 0, 0, '6:22 AM', '6:22 PM', NULL, 4, 4, 14.5434, 74.3201, 'Car Street, Gokarna, Karnataka 581326', NULL, 0.8);

