INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000128, 838005, 'Sunset Point Cafe', 'Sunset Point Cafe', 'Sunset Point Cafe sits on the coastal trail between Om Beach and Half Moon Beach, and its name reflects its reputation for the best sunset views in Gokarna. The cafe serves Indian, Chinese, Israeli and seafood cuisines and is especially known for its coffee. With prompt service and reasonable prices, it is a favourite stop for trekkers on the beach trail.', '1-2 hours', 'October to March, late afternoon for sunset', 'Time your trek so you arrive 30-45 minutes before sunset and pair the view with their much-recommended coffee.', 'no', 'Karnataka', 0, 1, '6:22 AM', '6:22 PM', NULL, 3, 4, 14.5185, 74.3262, 'Om Beach - Half Moon Beach - Paradise Beach Trail, Gokarna 581326', NULL, 0.68);

