INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000129, 838005, 'Prema', 'Prema', 'Prema (also listed as Prema Restaurant & Prema Hill Top) is a vegetarian eatery near the hilltop on Kudle Beach Road, known for its delectable vegetarian fare including masala dosa and poori bhaji. The property is noted for a beautiful hilltop sunset and sea view, plus clean rooms for staying guests. It is listed as pure veg in business listings.', '1-2 hours', 'October to March, evenings', 'Ask for a table with the sunset view and order the masala dosa and poori bhaji — the most cited dishes.', 'no', 'Karnataka', 0, 1, '6:22 AM', '6:22 PM', NULL, 3, 3, 14.5412, 74.3176, 'Near Hill Top, Kudle Beach Road, Gokarna 581326', NULL, 0.6);

