INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000130, 838005, 'Sunset Cafe', 'Sunset Cafe Beach Stay', 'Sunset Cafe Beach Stay is a cliff-side beachside restaurant on Gokarna''s Main Beach near Kariyappa Temple, known for its cosy ambience and serene sunset views over the sea. It serves Indian, Israeli and seafood dishes, with peri peri chicken strips, chicken tawa fry, masala omelet and Irish coffee shake among the must-try items. It runs split hours (lunch and dinner sessions).', '1-2 hours', 'October to March, sunset dinner session', 'Book a cliff-edge table for the dinner session to watch the sun set into the sea; it is the cafe''s signature experience.', 'no', 'Karnataka', 0, 1, '6:22 AM', '6:22 PM', NULL, 3, 4, 14.5448, 74.3142, 'Main Beach, near Kariyappa Temple, Gokarna 581326', NULL, 0.68);

