INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8380020, 838, 838005, 'Maha Shivaratri', 'Feb-Mar', 'The biggest festival of the year at Mahabaleshwar Temple; thousands of devotees gather for special pujas and the temple''s chariot (ratha) procession honoring Lord Shiva''s Atmalinga.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8380021, 838, 838005, 'Ganesh Chaturthi', 'Sep', 'Lord Ganesha''s birthday celebrated across the town with special pujas at Maha Ganapati Temple; the deity is traditionally worshipped before darshan at Mahabaleshwar Temple.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8380022, 838, 838005, 'Karthika Deepotsava', 'Nov', 'The Kartika-month lamp-lighting festival celebrated at Gokarna''s temples with rows of oil lamps (deepas); pilgrims bathe at Koti Tirtha and visit Mahabaleshwar Temple.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8380023, 838, 838005, 'Deepavali', 'Oct-Nov', 'The festival of lights celebrated town-wide; temples, homes and beachfront establishments are lit with diyas and firecrackers.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8380024, 838, 838005, 'Ugadi', 'Mar-Apr', 'The Kannada New Year (Chandramana Ugadi) marked by special temple pujas, mango-leaf decorations and festive meals in homes across the Uttara Kannada coast.');

