INSERT OR IGNORE INTO photos (id, place_id, source_file, thumbnail_url, thumbnail_width, thumbnail_height, photo_title, photo_author, license, license_url, source_url, credit, usage_terms, description) VALUES (838800036, 838000039, 'File:Nandi Temple (252276307).jpeg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c0/Nandi_Temple_%28252276307%29.jpeg/960px-Nandi_Temple_%28252276307%29.jpeg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 800, 663, 'Nandi Temple (252276307).jpeg', 'Kv Gopalakrishnan', 'CC0', 'http://creativecommons.org/publicdomain/zero/1.0/deed.en', 'https://commons.wikimedia.org/wiki/File%3ANandi_Temple_%28252276307%29.jpeg', 'Imported from 500px ( archived version ) by the Archive Team . ( detail page )', 'Creative Commons Zero, Public Domain Dedication', '500px provided description: Nandi of Mysore This enormous statue of Nandi Bull is more than 350 years old and can be seen on the way to Chamundi Hills in Mysore, Karnataka, India. The statue has been carved out of a single black stone boulder. It has a height of 16 feet and a length of 24 feet and i');

INSERT OR IGNORE INTO photos (id, place_id, source_file, thumbnail_url, thumbnail_width, thumbnail_height, photo_title, photo_author, license, license_url, source_url, credit, usage_terms, description) VALUES (838800037, 838000040, 'File:Lalitha Mahal Palace, Mysuru.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d7/Lalitha_Mahal_Palace%2C_Mysuru.jpg/960px-Lalitha_Mahal_Palace%2C_Mysuru.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 800, 533, 'Lalitha Mahal Palace, Mysuru.jpg', 'Kanad Sanyal', 'CC BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 'https://commons.wikimedia.org/wiki/File%3ALalitha_Mahal_Palace%2C_Mysuru.jpg', 'Own work', 'Creative Commons Attribution-Share Alike 4.0', 'Lalitha Mahal Palace was built in 1921 by the then Maharajah of Mysore for exclusive use by the Governor General during his visits. Located near Chamundi Hills in the eastern part of the city, the palace is now a luxury hotel.');

INSERT OR IGNORE INTO photos (id, place_id, source_file, thumbnail_url, thumbnail_width, thumbnail_height, photo_title, photo_author, license, license_url, source_url, credit, usage_terms, description) VALUES (838800038, 838000041, 'File:Gopura and prakara of Sri Ranganathaswamy temple on the island of Srirangapatna near Mysore in India.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d9/Gopura_and_prakara_of_Sri_Ranganathaswamy_temple_on_the_island_of_Srirangapatna_near_Mysore_in_India.jpg/960px-Gopura_and_prakara_of_Sri_Ranganathaswamy_temple_on_the_island_of_Srirangapatna_near_Mysore_in_India.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 800, 600, 'Gopura and prakara of Sri Ranganathaswamy temple on the island of Srirangapatna near Mysore in India.jpg', 'Adam Jones Adam63', 'CC BY-SA 3.0', 'https://creativecommons.org/licenses/by-sa/3.0', 'https://commons.wikimedia.org/wiki/File%3AGopura_and_prakara_of_Sri_Ranganathaswamy_temple_on_the_island_of_Srirangapatna_near_Mysore_in_India.jpg', 'Own work', 'Creative Commons Attribution-Share Alike 3.0', 'Sri Ranganathaswamy Temple, Island of Srirangapatnam, near Mysore, southern India. June 2008.');

INSERT OR IGNORE INTO photos (id, place_id, source_file, thumbnail_url, thumbnail_width, thumbnail_height, photo_title, photo_author, license, license_url, source_url, credit, usage_terms, description) VALUES (838800039, 838000042, 'File:Tipu Sultan’s Summer Palace, Srirangapatna, Karnataka.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/22/Tipu_Sultan%E2%80%99s_Summer_Palace%2C_Srirangapatna%2C_Karnataka.jpg/960px-Tipu_Sultan%E2%80%99s_Summer_Palace%2C_Srirangapatna%2C_Karnataka.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 800, 470, 'Tipu Sultan’s Summer Palace, Srirangapatna, Karnataka.jpg', 'Ananthmohanram18', 'CC BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 'https://commons.wikimedia.org/wiki/File%3ATipu_Sultan%E2%80%99s_Summer_Palace%2C_Srirangapatna%2C_Karnataka.jpg', 'Own work', 'Creative Commons Attribution-Share Alike 4.0', 'The summer retreat used by former Mysuru ruler, Tipu Sultan. The summer palace is also referred to as Dariya Daulat Bagh and is near Srirangapatna in Karnataka. The palace was built in 6 years, with construction initiated by Tipu Sultan''s father, Hyder Ali in the year 1778 AD. The palace is surround');

