INSERT OR IGNORE INTO photos (id, place_id, source_file, thumbnail_url, thumbnail_width, thumbnail_height, photo_title, photo_author, license, license_url, source_url, credit, usage_terms, description) VALUES (838800044, 838000053, 'File:Complex of Virupaksha Temple, Hampi (01).jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/40/Complex_of_Virupaksha_Temple%2C_Hampi_%2801%29.jpg/960px-Complex_of_Virupaksha_Temple%2C_Hampi_%2801%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 800, 533, 'Complex of Virupaksha Temple, Hampi (01).jpg', 'iMahesh', 'CC BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 'https://commons.wikimedia.org/wiki/File%3AComplex_of_Virupaksha_Temple%2C_Hampi_%2801%29.jpg', 'Own work', 'Creative Commons Attribution-Share Alike 4.0', 'The complex of the Virupaksha Temple in Hampi is a significant architectural marvel and a pivotal site in the region''s rich cultural heritage. This temple is dedicated to Lord Shiva and is one of the oldest functioning temples in India, dating back to the 7th century. The intricate carvings, towering Gopurams, and grand entranceways showcase the remarkable skill of artisans from the Vijayanagara Empire. The complex also features a large courtyard surrounded by various shrines, mandapas, and sacr');

INSERT OR IGNORE INTO photos (id, place_id, source_file, thumbnail_url, thumbnail_width, thumbnail_height, photo_title, photo_author, license, license_url, source_url, credit, usage_terms, description) VALUES (838800045, 838000054, 'File:Hampi Vitthala Temple 3465.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3d/Hampi_Vitthala_Temple_3465.jpg/960px-Hampi_Vitthala_Temple_3465.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 800, 533, 'Hampi Vitthala Temple 3465.jpg', 'Basavaraj M', 'CC BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 'https://commons.wikimedia.org/wiki/File%3AHampi_Vitthala_Temple_3465.jpg', 'Own work', 'Creative Commons Attribution-Share Alike 4.0', 'Vijaya Vitthala Temple, Hampi, Karnataka, India, reflected in a shallow pool filled with rainwater. The Vitthala temple and market complex is over 3 kilometres (1.9 miles) north-east of the Virupaksha temple near the banks of the Tungabhadra River. It is an artistically sophisticated Hindu temple in Hampi, and is part of the sacred centre of Vijayanagara.');

INSERT OR IGNORE INTO photos (id, place_id, source_file, thumbnail_url, thumbnail_width, thumbnail_height, photo_title, photo_author, license, license_url, source_url, credit, usage_terms, description) VALUES (838800046, 838000055, 'File:Hampi - Hemakuta Hill - Temples, Lingam Column.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/61/Hampi_-_Hemakuta_Hill_-_Temples%2C_Lingam_Column.jpg/960px-Hampi_-_Hemakuta_Hill_-_Temples%2C_Lingam_Column.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 800, 533, 'Hampi - Hemakuta Hill - Temples, Lingam Column.jpg', 'Ingo Mehling', 'CC BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 'https://commons.wikimedia.org/wiki/File%3AHampi_-_Hemakuta_Hill_-_Temples%2C_Lingam_Column.jpg', 'Own work', 'Creative Commons Attribution-Share Alike 4.0', 'Hampi / Karnataka - Temples, Lingam Column on Hemakuta Hill');

INSERT OR IGNORE INTO photos (id, place_id, source_file, thumbnail_url, thumbnail_width, thumbnail_height, photo_title, photo_author, license, license_url, source_url, credit, usage_terms, description) VALUES (838800047, 838000056, 'File:Hampi, India, Hampi countryside from Matanga Hill.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f9/Hampi%2C_India%2C_Hampi_countryside_from_Matanga_Hill.jpg/960px-Hampi%2C_India%2C_Hampi_countryside_from_Matanga_Hill.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 800, 533, 'Hampi, India, Hampi countryside from Matanga Hill.jpg', 'Vyacheslav Argenberg', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0', 'https://commons.wikimedia.org/wiki/File%3AHampi%2C_India%2C_Hampi_countryside_from_Matanga_Hill.jpg', 'Own work', 'Creative Commons Attribution 4.0', 'Matanga Hill is one of the holy places described in the epic Ramayana. Hampi, Karnataka, India.');

INSERT OR IGNORE INTO photos (id, place_id, source_file, thumbnail_url, thumbnail_width, thumbnail_height, photo_title, photo_author, license, license_url, source_url, credit, usage_terms, description) VALUES (838800048, 838000057, 'File:Lotus Mahal, Hampi, India.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ab/Lotus_Mahal%2C_Hampi%2C_India.jpg/960px-Lotus_Mahal%2C_Hampi%2C_India.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 800, 535, 'Lotus Mahal, Hampi, India.jpg', 'Agarwalarti', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0', 'https://commons.wikimedia.org/wiki/File%3ALotus_Mahal%2C_Hampi%2C_India.jpg', 'Own work', 'Creative Commons Attribution 4.0', 'Lotus Mahal is an ancient monument in Hampi, India');

INSERT OR IGNORE INTO photos (id, place_id, source_file, thumbnail_url, thumbnail_width, thumbnail_height, photo_title, photo_author, license, license_url, source_url, credit, usage_terms, description) VALUES (838800049, 838000058, 'File:Panorama of Elephant Stables, Hampi.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d4/Panorama_of_Elephant_Stables%2C_Hampi.jpg/960px-Panorama_of_Elephant_Stables%2C_Hampi.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 800, 281, 'Panorama of Elephant Stables, Hampi.jpg', 'iMahesh', 'CC BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 'https://commons.wikimedia.org/wiki/File%3APanorama_of_Elephant_Stables%2C_Hampi.jpg', 'Own work', 'Creative Commons Attribution-Share Alike 4.0', 'The image presents a panoramic view of the Elephant Stables in Hampi, capturing the full length of this grand structure. The stables consist of a series of interconnected domed chambers, each adorned with intricate Indo-Islamic architectural elements. This wide perspective emphasizes the symmetry and scale of the building, reflecting the importance of housing royal elephants in the Vijayanagara Empire. The combination of detailed stonework and expansive design highlights the stables'' significanc');

INSERT OR IGNORE INTO photos (id, place_id, source_file, thumbnail_url, thumbnail_width, thumbnail_height, photo_title, photo_author, license, license_url, source_url, credit, usage_terms, description) VALUES (838800050, 838000059, 'File:Queen''s Bath in Hampi - Rupesh Sarkar -1.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f7/Queen%27s_Bath_in_Hampi_-_Rupesh_Sarkar_-1.jpg/960px-Queen%27s_Bath_in_Hampi_-_Rupesh_Sarkar_-1.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 800, 533, 'Queen''s Bath in Hampi - Rupesh Sarkar -1.jpg', 'Rupeshsarkar', 'CC BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 'https://commons.wikimedia.org/wiki/File%3AQueen%27s_Bath_in_Hampi_-_Rupesh_Sarkar_-1.jpg', 'Own work', 'Creative Commons Attribution-Share Alike 4.0', 'The Queen’s Bath in Hampi is a colossal bath that exemplifies the architectural excellence prevalent during the days of the Vijayanagara Empire. It is located close to the entrance of the Royal Enclosure in Hampi.');

INSERT OR IGNORE INTO photos (id, place_id, source_file, thumbnail_url, thumbnail_width, thumbnail_height, photo_title, photo_author, license, license_url, source_url, credit, usage_terms, description) VALUES (838800051, 838000060, 'File:Stepped Tank , Hampi.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/68/Stepped_Tank_%2C_Hampi.jpg/960px-Stepped_Tank_%2C_Hampi.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 800, 533, 'Stepped Tank , Hampi.jpg', 'Sankalan Ghosh', 'CC BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 'https://commons.wikimedia.org/wiki/File%3AStepped_Tank_%2C_Hampi.jpg', 'Own work', 'Creative Commons Attribution-Share Alike 4.0', 'Pushkarni, also known as Stepped Tank is an ancient water tank in Hampi.');

INSERT OR IGNORE INTO photos (id, place_id, source_file, thumbnail_url, thumbnail_width, thumbnail_height, photo_title, photo_author, license, license_url, source_url, credit, usage_terms, description) VALUES (838800052, 838000061, 'File:Hampi - Hazara Rama Temple - Mandapa - Outside Reliefs - 1.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f4/Hampi_-_Hazara_Rama_Temple_-_Mandapa_-_Outside_Reliefs_-_1.jpg/960px-Hampi_-_Hazara_Rama_Temple_-_Mandapa_-_Outside_Reliefs_-_1.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 800, 533, 'Hampi - Hazara Rama Temple - Mandapa - Outside Reliefs - 1.jpg', 'Ingo Mehling', 'CC BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 'https://commons.wikimedia.org/wiki/File%3AHampi_-_Hazara_Rama_Temple_-_Mandapa_-_Outside_Reliefs_-_1.jpg', 'Own work', 'Creative Commons Attribution-Share Alike 4.0', 'Hampi / Karnataka - Reliefs at Outside of Mandapa of Hazara Rama Temple');

INSERT OR IGNORE INTO photos (id, place_id, source_file, thumbnail_url, thumbnail_width, thumbnail_height, photo_title, photo_author, license, license_url, source_url, credit, usage_terms, description) VALUES (838800053, 838000062, 'File:Garbhagriha reflected in water at Underground Shiva Temple (02).jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c8/Garbhagriha_reflected_in_water_at_Underground_Shiva_Temple_%2802%29.jpg/960px-Garbhagriha_reflected_in_water_at_Underground_Shiva_Temple_%2802%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 800, 533, 'Garbhagriha reflected in water at Underground Shiva Temple (02).jpg', 'iMahesh', 'CC BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 'https://commons.wikimedia.org/wiki/File%3AGarbhagriha_reflected_in_water_at_Underground_Shiva_Temple_%2802%29.jpg', 'Own work', 'Creative Commons Attribution-Share Alike 4.0', 'The image captures the reflection of the Garbhagriha (sanctum sanctorum) in the water at the Underground Shiva Temple in Hampi. The reflection creates a serene and mystical atmosphere, with the submerged temple adding to the unique experience. The Garbhagriha''s stone architecture and intricate carvings are mirrored in the water, enhancing the temple''s spiritual and architectural significance. This rare view emphasizes the temple''s historical importance and its distinctive underground design, whi');

INSERT OR IGNORE INTO photos (id, place_id, source_file, thumbnail_url, thumbnail_width, thumbnail_height, photo_title, photo_author, license, license_url, source_url, credit, usage_terms, description) VALUES (838800054, 838000063, 'File:Hampi - Lakshmi Narasimha Temple - Narasimha Statue.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4e/Hampi_-_Lakshmi_Narasimha_Temple_-_Narasimha_Statue.jpg/960px-Hampi_-_Lakshmi_Narasimha_Temple_-_Narasimha_Statue.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 800, 695, 'Hampi - Lakshmi Narasimha Temple - Narasimha Statue.jpg', 'Ingo Mehling', 'CC BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 'https://commons.wikimedia.org/wiki/File%3AHampi_-_Lakshmi_Narasimha_Temple_-_Narasimha_Statue.jpg', 'Own work', 'Creative Commons Attribution-Share Alike 4.0', 'Hampi / Karnataka - Lakshmi Narasimha Temple - Narasimha Statue');

INSERT OR IGNORE INTO photos (id, place_id, source_file, thumbnail_url, thumbnail_width, thumbnail_height, photo_title, photo_author, license, license_url, source_url, credit, usage_terms, description) VALUES (838800055, 838000064, 'File:Badavilinga Temple Hampi 01.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2b/Badavilinga_Temple_Hampi_01.jpg/960px-Badavilinga_Temple_Hampi_01.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 800, 534, 'Badavilinga Temple Hampi 01.jpg', 'Sclickp', 'CC BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 'https://commons.wikimedia.org/wiki/File%3ABadavilinga_Temple_Hampi_01.jpg', 'Own work', 'Creative Commons Attribution-Share Alike 4.0', 'Badavilinga Temple is a wonderful temple in Hampi dedicated to Lord Shiva. The Hindu deity Shiva is worshipped in the form of a Linga in this temple. The Badavilinga temple is located near the Lakshmi Narasimha Temple. Tourists as well as devotees flock to the temple throughout the year. 
This is the largest Linga image in Hampi. Located next to the Lakshmi Narasimha statue, the Linga is housed inside a chamber with an opening in the front. A close look on this icon can reveal three eyes (depict');

INSERT OR IGNORE INTO photos (id, place_id, source_file, thumbnail_url, thumbnail_width, thumbnail_height, photo_title, photo_author, license, license_url, source_url, credit, usage_terms, description) VALUES (838800056, 838000065, 'File:Achyutaraya Temple - Entrance Gopuram - 2.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f0/Achyutaraya_Temple_-_Entrance_Gopuram_-_2.jpg/960px-Achyutaraya_Temple_-_Entrance_Gopuram_-_2.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 800, 536, 'Achyutaraya Temple - Entrance Gopuram - 2.jpg', 'Ingo Mehling', 'CC BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 'https://commons.wikimedia.org/wiki/File%3AAchyutaraya_Temple_-_Entrance_Gopuram_-_2.jpg', 'Own work', 'Creative Commons Attribution-Share Alike 4.0', 'Achyutaraya Temple / Hampi, Karnataka - Entrance Gopuram');

INSERT OR IGNORE INTO photos (id, place_id, source_file, thumbnail_url, thumbnail_width, thumbnail_height, photo_title, photo_author, license, license_url, source_url, credit, usage_terms, description) VALUES (838800057, 838000066, 'File:Tungabhadra River and Coracle Boats.JPG', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/19/Tungabhadra_River_and_Coracle_Boats.JPG/960px-Tungabhadra_River_and_Coracle_Boats.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 800, 480, 'Tungabhadra River and Coracle Boats.JPG', 'Dey.sandip', 'CC BY-SA 3.0', 'https://creativecommons.org/licenses/by-sa/3.0', 'https://commons.wikimedia.org/wiki/File%3ATungabhadra_River_and_Coracle_Boats.JPG', 'Own work', 'Creative Commons Attribution-Share Alike 3.0', 'Coracle boats are round-shaped non-polluting boats that are used for transport in Tungabhadra river since ages. These boats are very stable by nature and can carry 10-15 persons easily. Navigation is not difficult but it requires skills especially when going upstream. 

Its part of the local lifestyle in Hampi, Karnataka and is an attraction for tourists coming to this part of the world.

Note: This photograph uses Adobe RGB color space. It is recommended that the photograph be viewed in a brows');

INSERT OR IGNORE INTO photos (id, place_id, source_file, thumbnail_url, thumbnail_width, thumbnail_height, photo_title, photo_author, license, license_url, source_url, credit, usage_terms, description) VALUES (838800058, 838000067, 'File:Hampi Bazaar.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/65/Hampi_Bazaar.jpg/960px-Hampi_Bazaar.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 800, 450, 'Hampi Bazaar.jpg', 'Basavaraj M', 'CC BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 'https://commons.wikimedia.org/wiki/File%3AHampi_Bazaar.jpg', 'Own work', 'Creative Commons Attribution-Share Alike 4.0', 'Hampi Bazaar, Hampi, Karnataka. The Hampi Bazaar is a well-known market place that spreads for more than one kilometer. The road passing through the market has series of old pavilions on both sides.');

INSERT OR IGNORE INTO photos (id, place_id, source_file, thumbnail_url, thumbnail_width, thumbnail_height, photo_title, photo_author, license, license_url, source_url, credit, usage_terms, description) VALUES (838800059, 838000068, 'File:Anjanadri Hill in Hampi (01).jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b5/Anjanadri_Hill_in_Hampi_%2801%29.jpg/960px-Anjanadri_Hill_in_Hampi_%2801%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 800, 533, 'Anjanadri Hill in Hampi (01).jpg', 'iMahesh', 'CC BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 'https://commons.wikimedia.org/wiki/File%3AAnjanadri_Hill_in_Hampi_%2801%29.jpg', 'Own work', 'Creative Commons Attribution-Share Alike 4.0', 'The image captures Anjanadri Hill, a prominent landmark in Hampi known for its rich mythological significance. This hill is revered as the birthplace of Lord Hanuman, making it a major pilgrimage site for devotees seeking blessings from the revered deity. The landscape is characterized by rugged terrain and boulders, providing a stunning backdrop for the Hanuman Temple situated at its peak. Visitors to Anjanadri Hill can experience breathtaking views of the surrounding area, including the iconic');

INSERT OR IGNORE INTO photos (id, place_id, source_file, thumbnail_url, thumbnail_width, thumbnail_height, photo_title, photo_author, license, license_url, source_url, credit, usage_terms, description) VALUES (838800060, 838000069, 'File:Pampa Sarovar, Anegundi.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/38/Pampa_Sarovar%2C_Anegundi.jpg/960px-Pampa_Sarovar%2C_Anegundi.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 800, 533, 'Pampa Sarovar, Anegundi.jpg', 'iMahesh', 'CC BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 'https://commons.wikimedia.org/wiki/File%3APampa_Sarovar%2C_Anegundi.jpg', 'Own work', 'Creative Commons Attribution-Share Alike 4.0', 'The image depicts Pampa Sarovar, a significant water tank located in Anegundi, known for its deep cultural and mythological importance. This serene body of water is believed to be associated with the Hindu epic Ramayana, where it is said that the goddess Pampa performed penance. The tank is surrounded by lush greenery and ancient temples, creating a tranquil atmosphere that attracts pilgrims and tourists alike. Pampa Sarovar serves not only as a sacred site for rituals and gatherings but also as');

