INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000131, 838006, 'Udupi Sri Krishna Matha', 'Udupi Sri Krishna Matha', 'The 13th-century Vaishnavite temple founded by philosopher-saint Madhvacharya, among the holiest Krishna pilgrimages in South India. The deity is viewed only through the nine-holed Navagraha Kindi (Kanakana Kindi), a window through which the saint Kanakadasa is said to have been granted darshan. The temple is administered in rotation by the eight Ashta Mathas under the biennial Paryaya system.', '2-3 hours', 'October to March, early morning for darshan', 'Men traditionally remove shirts before the inner sanctum; the temple''s free annadana (meals) runs at lunch and dinner.', 'no', 'Karnataka', 0, 0, '6:20 AM', '6:19 PM', NULL, 5, 5, 13.3412, 74.752, 'Temple Car Street, Thenkpete, Maruthi Veethika, Udupi, Karnataka 576101', NULL, 1.0);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (838000131, 838000131, '4:30 AM - 9:30 PM', '4:30 AM - 9:30 PM', '4:30 AM - 9:30 PM', '4:30 AM - 9:30 PM', '4:30 AM - 9:30 PM', '4:30 AM - 9:30 PM', '4:30 AM - 9:30 PM', 'Sources agree on ~4:30 AM opening with morning darshan till ~1 PM and evening darshan ~3-5 PM to 9-9:30 PM; midday break roughly 1-3 PM. Timings shift on festival days.');

