INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 838000131, 'insert', 'bulk', 'Hours cross-checked across templedarshantime.com, templetimings.in, casualwalker.com and a place listing (4:30 AM - 9:30 PM daily); minor variation in midday break times. Entry is free; no entry fee published. No official website verified - the Matha''s official domain was not confirmed from search results, so left null.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000132, 838006, 'Anantheshwara Temple', 'Anantheshwara Temple', 'An ancient Shiva temple adjoining the Krishna Matha, older than the Matha itself and the place where Madhvacharya received his spiritual education. Devotees traditionally visit it along with the Chandramouleshwara Temple before the Krishna darshan. Its sanctum and pillared hall reflect old coastal Karnataka temple architecture.', '30-45 minutes', 'October to March, morning', 'Combine with Chandramouleshwara Temple opposite it and the Krishna Matha in one visit - all three are within the temple complex.', 'no', 'Karnataka', 0, 0, '6:20 AM', '6:19 PM', NULL, 4, 4, 13.3417, 74.7517, 'Car Street, near Sri Krishna Matha, Udupi, Karnataka 576101', NULL, 0.8);

