INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 838000132, 'insert', 'bulk', 'Coordinates approximate (within the Matha complex, estimated ~100-200 m from Krishna Matha at 13.3412, 74.7520). Hours not published anywhere found - nulls used per rules. Existence and role confirmed by outlooktraveller.com and onefivenine.com.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000133, 838006, 'Chandramouleshwara Temple', 'Chandramouleshwara Temple', 'A Shiva temple standing opposite the Anantheshwara Temple, also predating the Krishna Matha, and regarded as the ''grandfather temple'' of Udupi. Pilgrims traditionally pay respects here before proceeding to the Krishna darshan. The temple''s old stone structure is a quiet, atmospheric stop within the temple quarter.', '30 minutes', 'October to March, morning', 'Visit right after Anantheshwara Temple - the two shrines face each other across the street.', 'no', 'Karnataka', 0, 0, '6:20 AM', '6:19 PM', NULL, 3, 4, 13.3416, 74.7514, 'Car Street, near Sri Krishna Matha, Udupi, Karnataka 576101', NULL, 0.68);

