INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000134, 838006, 'Malpe Beach', 'Malpe Beach', 'Udupi''s best-known beach, about 6 km from the city centre, with golden sand, palm-fringed shoreline and a working fishing harbour. It is the departure point for ferries to St. Mary''s Island and hosts water sports like parasailing and banana-boat rides on the mainland. The sea walk and shacks make it the liveliest evening spot in Udupi.', '2-3 hours', 'October to March, late afternoon for sunset', 'Buy St. Mary''s Island ferry tickets at the jetty counter early in the morning on weekends to avoid long queues.', 'no', 'Karnataka', 0, 1, '6:20 AM', '6:19 PM', NULL, 5, 4, 13.3547, 74.7045, 'Malpe Beach Road, Malpe, Udupi, Karnataka 576108', NULL, 0.92);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (838000134, 838000134, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Beach is open all day; water sports operate roughly 9 AM - 5 PM in season (Oct-May). Ferry hours are set by the boating association.');

