INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 838000134, 'insert', 'bulk', 'Coordinates estimated ~1 km for central Malpe Beach. No beach entry fee published. Water-sport price ranges (Rs 300-1000+) vary by vendor and were not taken from a single published source, so left out. Water sports/fishing harbour confirmed by outlooktraveller.com.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000135, 838006, 'St. Mary''s Island', 'St. Mary''s Island', 'A cluster of four uninhabited islands off Malpe famed for columnar basalt (rhyolitic lava) rock formations, declared a National Geological Monument by the Geological Survey of India. Vasco da Gama is said to have landed here in 1498, naming one island El Padron de Santa Maria. Reached only by ferry from Malpe, with about 60-90 minutes allowed on the island per trip.', '3-4 hours including ferry', 'October to May, morning ferry', 'No food or shade on the island - carry water; boats stop running around 3:30-4 PM for the last onward trip and the island closes after sunset.', 'no', 'Karnataka', 0, 0, '6:20 AM', '6:19 PM', 'Rs 400', 5, 5, 13.3792, 74.6734, 'St. Mary''s Island, off Malpe, Udupi district, Karnataka', 'http://www.malpeboatings.com/', 1.0);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (838000135, 838000135, '9:00 AM - 5:00 PM', '9:00 AM - 5:00 PM', '9:00 AM - 5:00 PM', '9:00 AM - 5:00 PM', '9:00 AM - 5:00 PM', '9:00 AM - 5:00 PM', '9:00 AM - 5:00 PM', 'Per the boating association''s own site: daily trips 9 AM - 5 PM, island closed June-September (monsoon) per travel guides. Last boat to island usually 3:30-4 PM.');

