INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000136, 838006, 'Kapu Beach and Lighthouse', 'Kapu Beach and Lighthouse', 'A scenic, relatively uncrowded beach about 13-15 km south of Udupi on NH-66, famous for its sunsets, rocky shoreline and the 1901 British-era lighthouse standing ~27 metres tall on a rock hillock. The lighthouse, still functional, opens for visitors in the evenings with a narrow spiral stair and steep final ladder to a 360-degree sea-view balcony.', '2-3 hours', 'October to February, evening around sunset', 'The lighthouse is typically open only in the evening (roughly 5-6:30 PM) and stays closed during monsoon - confirm on arrival; rocks near the shore are slippery.', 'no', 'Karnataka', 0, 1, '6:20 AM', '6:19 PM', NULL, 5, 5, 13.2243, 74.7487, 'Kapu Beach Road, Kapu, Udupi district, Karnataka 574106', NULL, 1.0);

