INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000137, 838006, 'Mattu Beach', 'Mattu Beach', 'A quieter stretch of coastline about 9 km north of Udupi, twin to Kapu Beach in character - golden sand, palms and fishing boats, with far fewer crowds than Malpe. It is known locally for the distinctive Mattu Gulla (a variety of brinjal grown in the area''s sandy soil). A good pick for a peaceful swim or sunset walk.', '1-2 hours', 'October to March, late afternoon', 'Few food shacks here - carry water and snacks; there are no lifeguards, so stay in shallow water.', 'no', 'Karnataka', 0, 1, '6:20 AM', '6:19 PM', NULL, 3, 4, 13.2778, 74.7328, 'Mattu, Udupi district, Karnataka', NULL, 0.68);

