INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000138, 838006, 'Delta Beach (Kodi Bengre)', 'Delta Beach (Kodi Bengre)', 'A narrow sandy spit at Kodi Bengre where the Suvarna (Swarna) River meets the Arabian Sea, surrounded on three sides by water - hence the name Delta Beach or ''sangama'' point. It offers backwaters, mangroves, coconut groves and a working fishing village on one side and surf on the other. Quieter than Malpe, with fishermen casting nets at dawn.', '2-3 hours', 'October to March, morning or sunset', 'The approach road is narrow - autos or two-wheelers work best; the river side is calm while the sea side has stronger surf.', 'no', 'Karnataka', 1, 1, '6:20 AM', '6:19 PM', NULL, 4, 4, 13.3855, 74.717, 'Kodi Bengre, Udupi district, Karnataka', NULL, 0.8);

