INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000139, 838006, 'Hasta Shilpa Heritage Village', 'Hasta Shilpa Heritage Village', 'An open-air museum near Manipal founded by conservationist Vijaynath Shenoy, preserving over 20 dismantled-and-rebuilt traditional homes, palaces and shrines from coastal Karnataka and beyond. Visitors walk through furnished ancestral houses with explanatory boards and a downloadable PDF guide. Shoes must be removed before entering each house.', '2-4 hours', 'October to March, 10 AM - 1 PM', 'Last entry is around 3:45 PM and it stays closed on Mondays - arrive before 2 PM to see everything comfortably.', 'no', 'Karnataka', 0, 0, '6:20 AM', '6:19 PM', 'Rs 300', 5, 5, 13.3455, 74.7876, 'Opp. Hotel Lake View, Alevoor-Manipal Road, near Christ Church, Manipal, Karnataka 576104', NULL, 1.0);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (838000139, 838000139, 'Closed', '10:00 AM - 5:00 PM', '10:00 AM - 5:00 PM', '10:00 AM - 5:00 PM', '10:00 AM - 5:00 PM', '10:00 AM - 5:00 PM', '10:00 AM - 5:00 PM', 'Closed Mondays and public holidays; last entry 3:45 PM per airial.travel. Tickets bought at entrance; advance booking generally not required.');

