INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000140, 838006, 'Pajaka Kshetra', 'Pajaka Kshetra', 'The birthplace of Dvaita philosopher Sri Madhvacharya, about 8 km south of Udupi, and a revered pilgrimage spot in its own right. The site preserves his ancestral home, the spot of his Aksharabhyasa (initiation), a banyan tree said to have been planted by him, and a pond believed to have been fed from four nearby ponds. An idol of Madhvacharya installed by Vadiraja is worshipped in the temple.', '1-2 hours', 'October to March, morning', 'Combine with nearby Kunjarugiri Durga Temple on the hillock for views; modest dress expected.', 'no', 'Karnataka', 0, 0, '6:20 AM', '6:19 PM', NULL, 4, 4, 13.2714, 74.7922, 'Pajaka, Udupi taluk, Karnataka', NULL, 0.8);

