INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000141, 838006, 'Manipal Lake', 'Manipal Lake', 'A scenic freshwater lake in the university town of Manipal, about 5 km from Udupi, ringed by a walking path popular with students and morning walkers. Boating has been offered here in season by local operators. It is a calm, green pause between temple and beach itineraries.', '1 hour', 'October to March, morning or evening', 'Best as a sunrise walk or a short evening stop combined with Hasta Shilpa and End Point in Manipal.', 'no', 'Karnataka', 1, 0, '6:20 AM', '6:19 PM', NULL, 3, 3, 13.349, 74.787, 'Manipal, Udupi, Karnataka 576104', NULL, 0.6);

