INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000142, 838006, 'End Point, Manipal', 'End Point, Manipal', 'A clifftop viewpoint at the edge of the Manipal plateau overlooking the Swarna (Suvarna) river valley and the Western Ghats. A favourite sunset spot for students of the university town, with a short walking trail and open laterite-rock vistas. The name comes from its position at the ''end'' of the campus road.', '1 hour', 'October to March, sunset', 'Go about 45 minutes before sunset for the best light; carry water as there are no shops at the viewpoint.', 'no', 'Karnataka', 0, 1, '6:20 AM', '6:19 PM', NULL, 4, 4, 13.3492, 74.7928, 'End Point Road, Manipal, Karnataka 576104', NULL, 0.8);

