INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000143, 838006, 'Malpe Sea Walk', 'Malpe Sea Walk', 'A paved promenade running along the Malpe shoreline near the fishing harbour, popular for evening strolls with views of the sea, anchored boats and St. Mary''s Island on the horizon. Food shacks and the harbour bustle make it livelier than the main beach stretch. It is a favourite local sunset-watching spot.', '1 hour', 'October to March, evening', 'Pair it with dinner at a sea-facing shack after the walk; the harbour side is busiest around 5-7 PM.', 'no', 'Karnataka', 0, 1, '6:20 AM', '6:19 PM', NULL, 3, 4, 13.3555, 74.7015, 'Malpe Beach Road, near Harbour, Malpe, Udupi, Karnataka 576108', NULL, 0.68);

