INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000144, 838006, 'Kunjarugiri Durga Temple', 'Kunjarugiri Durga Temple', 'A hilltop Durga temple near Pajaka, about 8 km south of Udupi, reached by a short climb with views over the surrounding countryside and, on clear days, the Arabian Sea. It sits close to the Pajaka birthplace of Madhvacharya, making the two an easy combined pilgrimage. The hill is also linked in legend to the region''s Parasurama Kshetra tradition.', '1-1.5 hours', 'October to March, morning or sunset', 'The climb is short but steep in places - wear grippy footwear and go early to avoid the midday heat.', 'no', 'Karnataka', 0, 1, '6:20 AM', '6:19 PM', NULL, 3, 4, 13.275, 74.795, 'Kunjarugiri, near Pajaka, Udupi taluk, Karnataka', NULL, 0.68);

