INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000145, 838006, 'Anegudde Sri Vinayaka Temple', 'Anegudde Sri Vinayaka Temple', 'One of the best-known Ganesha temples of coastal Karnataka, on a hillock at Kumbhashi about 30 km north of Udupi on NH-66. The naturally formed rock idol, covered with a gold mask and silver body, is worshipped as Siddhi Vinayaka, the granter of wishes. It is counted among the seven Mukti Sthalas of the Parasurama Kshetra.', '1 hour', 'October to March, morning', 'Day trip from Udupi (~45 min drive); modest dress and bare feet required inside the shrine.', 'no', 'Karnataka', 0, 0, '6:20 AM', '6:19 PM', NULL, 4, 4, 13.5694, 74.7046, 'NH-66, Kumbhashi, Kundapura taluk, Udupi district, Karnataka 576257', NULL, 0.8);

