INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000146, 838006, 'Maravanthe Beach', 'Maravanthe Beach', 'A celebrated coastal stretch about 55 km north of Udupi where NH-66 runs with the Arabian Sea on one side and the Souparnika River on the other - a rare sea-and-river sandwich. The beach is wide, relatively clean and famous for its sunsets. The river side offers calm backwater views and coracle rides.', '2-3 hours', 'October to March, sunset', 'Stop at the highway viewpoint for the classic sea-road-river photo; swim only in the calmer river side.', 'no', 'Karnataka', 0, 1, '6:20 AM', '6:19 PM', NULL, 4, 5, 13.4748, 74.6478, 'Maravanthe, Kundapura taluk, Udupi district, Karnataka', NULL, 0.88);

