INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000147, 838006, 'Kollur Mookambika Temple', 'Kollur Mookambika Temple', 'One of the most important Devi shrines of the Western Ghats, about 70 km northeast of Udupi at the foothills of Kodachadri. Goddess Mookambika is worshipped here in a swayambhu (self-manifested) lingam with a gold face, and the temple draws pilgrims from across South India. It is another of the seven Mukti Sthalas of the Parasurama Kshetra.', '2-3 hours', 'October to March, morning', 'Combine with Kodachadri (base at Kollur) for a full day; temple gets very crowded on weekends and Navaratri.', 'no', 'Karnataka', 0, 0, '6:20 AM', '6:19 PM', NULL, 5, 4, 13.8657, 74.8135, 'Kollur, Kundapura taluk, Udupi district, Karnataka 576220', NULL, 0.92);

