INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000148, 838006, 'Agumbe Sunset Point', 'Agumbe Sunset Point', 'A viewpoint in Agumbe, about 55 km east of Udupi in the Western Ghats, famous for dramatic sunsets over layered ridges - the region is called the ''Cherrapunji of the South'' for its heavy rainfall. Agumbe is also a major king-cobra research area and the gateway to nearby waterfalls like Barkana and Onake Abbi. The ghat drive up is scenic but winding.', 'Half day', 'October to February, sunset', 'Reach 30-45 minutes before sunset; avoid the ghat road after dark and skip monsoon visits when views are clouded out.', 'no', 'Karnataka', 0, 1, '6:20 AM', '6:19 PM', NULL, 4, 4, 13.5159, 75.0879, 'Agumbe, Thirthahalli taluk, Shivamogga district, Karnataka', NULL, 0.8);

