INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000149, 838006, 'Kudlu Teertha Falls', 'Kudlu Teertha Falls', 'A ~200-foot waterfall of the Netravati River in the forests of Hebri taluk, about 70-75 km from Udupi. Reaching it needs a rough forest drive (about 13 km from the Hebri-road gate, roughly an hour) plus a 2-3 km jungle trek with stream crossings. The falls reward the effort with a clear plunge pool and few crowds.', 'Full day', 'October to February; avoid monsoon', 'Not for small children or anyone with mobility issues; wear anti-leech socks in the post-monsoon months and go with a group.', 'no', 'Karnataka', 0, 0, '6:20 AM', '6:19 PM', NULL, 3, 4, 13.4518, 74.754, 'Hebri taluk, Udupi district, Karnataka', NULL, 0.68);

