INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000150, 838006, 'Kodachadri', 'Kodachadri', 'A 1,343-metre peak in the Western Ghats about 100 km from Udupi, forming the scenic backdrop of the Kollur Mookambika Temple. Trekkers climb to the Sarvajna Peetha (said to be Adi Shankaracharya''s meditation spot) and viewpoints over the Arabian Sea on clear days. Jeeps from Kollur offer an alternative to the full trek.', 'Full day', 'October to February', 'Start early from Kollur; jeep rides need prior arrangement through local operators and the trek is moderately difficult.', 'no', 'Karnataka', 1, 1, '6:20 AM', '6:19 PM', NULL, 4, 5, 13.8606, 74.8622, 'Kodachadri, Hosanagara taluk, Shivamogga district, Karnataka', NULL, 0.88);

