INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000151, 838006, 'Mitra Samaj', 'Mitra Samaj', 'A legendary vegetarian eatery inside the Sri Krishna Temple complex, run by the same family since the pre-Independence era and often credited as the mother of Udupi restaurants. It claims to have invented the masala dosa in 1949 and still cooks without onion, garlic or radish. Goli baje, neer dosa, Mangalore buns and filter coffee are the signatures.', '45-60 minutes', 'Breakfast or evening tiffin hours', 'It splits timings with a midday break and stays closed on Wednesdays - plan lunch elsewhere on Wednesdays.', 'no', 'Karnataka', 0, 0, '6:20 AM', '6:19 PM', NULL, 5, 4, 13.3407, 74.7522, 'Sri Krishna Temple Complex, Thenkpete, Maruthi Veethika, Udupi, Karnataka 576101', NULL, 0.92);

