INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000152, 838006, 'Woodlands Restaurant', 'Woodlands Restaurant', 'A long-standing pure-veg institution on Car Street near the Krishna Matha, loved for classic Udupi tiffin - paper-thin crispy dosas, fluffy idlis, Mangalore buns and strong filter coffee. The nostalgic dining hall draws pilgrims straight after darshan. It is consistently rated among Udupi''s top vegetarian restaurants.', '45-60 minutes', 'Breakfast or dinner hours', 'Expect a wait at breakfast on weekends; the bisi bele bath and neer dosa are local favourites.', 'no', 'Karnataka', 0, 0, '6:20 AM', '6:19 PM', NULL, 5, 4, 13.3393, 74.7512, 'Dr. U. R. Rao Complex, Car Street, near Sri Krishna Matha, Udupi, Karnataka', NULL, 0.92);

