INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000153, 838006, 'Diana Restaurant', 'Diana Restaurant', 'A Udupi landmark running for over 60 years (established 1962), known for old-school vegetarian breakfasts - puri sagu, paper masala dosa - and its famous Gadbad ice cream sundae. The Ajjarkad restaurant has a cosy-modern dining room and a ground-floor ice-cream counter that locals swear by. A bus stop is even named after the hotel.', '45-60 minutes', 'Breakfast or evening', 'Order the Gadbad ice cream - it is the signature; the restaurant doubles as a casual lunch and chaat stop.', 'no', 'Karnataka', 0, 0, '6:20 AM', '6:19 PM', NULL, 4, 4, 13.342, 74.7445, 'Near Big Bazar, Jodukatte, Ajjarkad, Udupi, Karnataka 576101', NULL, 0.8);

