INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000154, 838006, 'MTR (Mavalli Tiffin Room), Udupi', 'MTR (Mavalli Tiffin Room), Udupi', 'The Udupi branch of the iconic Bengaluru tiffin house (est. 1924), near Govinda Kalyana Mantapa at Kinnimulki. It serves the classic MTR repertoire - chow chow bath, bisi bele bath, rava idli - plus a famous Sunday-only sweet, Chandrahara. Clean, central and reliably good for families.', '45-60 minutes', 'Breakfast or lunch', 'Try the chow chow bath combo and ask about the Sunday Chandrahara sweet special.', 'no', 'Karnataka', 0, 0, '6:20 AM', '6:19 PM', NULL, 4, 4, 13.3335, 74.742, 'Near Govinda Kalyana Mantapa, Kinnimulki, Udupi, Karnataka', NULL, 0.8);

