INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000155, 838006, 'Kediyoor Gazebo', 'Kediyoor Gazebo', 'A popular multi-cuisine restaurant at Brahmagiri known for tandoori starters, ghee-roast dishes and North Indian-Chinese mains, plus mocktails like the Cinderella. It is one of the few well-rated non-veg options in the city centre and fills up for dinner. Operates split lunch and dinner shifts.', '1-1.5 hours', 'Dinner, 7 PM onwards', 'Go for dinner - it opens at 11 AM for lunch, closes mid-afternoon, and reopens at 6:30 PM.', 'no', 'Karnataka', 0, 0, '6:20 AM', '6:19 PM', NULL, 4, 4, 13.3515, 74.76, 'Brahmagiri, Udupi, Karnataka', NULL, 0.8);

