INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000156, 838006, 'Thimmappa Fish Hotel', 'Thimmappa Fish Hotel', 'A no-frills local favourite on Malpe Road at Adi Udupi serving Mangalorean coastal seafood - fish curry meals, neer dosa with fish curry, and fried fish - at very modest prices. It is the go-to counterpoint to Udupi''s veg scene for travellers wanting authentic coastal non-veg food. Expect simple seating and quick turnover.', '45-60 minutes', 'Lunch or dinner', 'Order the fish curry meals with neer dosa; it is a local lunch spot, so go early for the freshest catch.', 'no', 'Karnataka', 0, 0, '6:20 AM', '6:19 PM', NULL, 4, 4, 13.344, 74.72, 'Malpe Road, Adi Udupi, Udupi, Karnataka', NULL, 0.8);

