INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000157, 838007, 'Mullayanagiri Peak', 'Mullayanagiri Peak', 'Mullayanagiri is the highest peak in Karnataka at 1,930 m, in the Baba Budan Giri range of the Western Ghats, about 15 km from Chikmagalur town. Visitors can drive to the base and climb around 500 steps to the summit, or trek the 3.5 km Sarpadhari trail (3-4 hours, moderate difficulty). The summit has a small Shiva temple and wide views across the Western Ghats.', '3-4 hours', 'October to March, early morning', 'Arrive before 8 AM to beat the crowds and catch clear views; carry a light jacket as the summit is windy and cool.', 'no', 'Karnataka', 1, 1, '6:17 AM', '6:08 PM', NULL, 5, 5, 13.3886, 75.7216, 'Mullayanagiri, near Sarpadhari, Chikmagalur district, Karnataka 577101', NULL, 1.0);

