INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000158, 838007, 'Baba Budangiri', 'Baba Budangiri', 'The Baba Budan Giri range (originally Chandra Drona Parvatha) is named after the 16th-century Sufi saint Baba Budan, credited with bringing the first seven coffee beans from Yemen to India. The Datta Peeta shrine draws both Hindu and Muslim pilgrims, and three caves sanctified by siddhas nearby host an annual jatra (fair). Peaks here include Dattagiri (1,895 m), the second-highest cluster in Karnataka after Mullayanagiri.', '2-3 hours', 'September to March', 'Dress modestly for the shrine; avoid visiting during the Urs (March) and Datta Jayanti (December) when tourist access may be restricted.', 'no', 'Karnataka', 1, 1, '6:17 AM', '6:08 PM', NULL, 5, 4, 13.4917, 75.7503, 'Baba Budangiri Hills, near Attigundi, Chikmagalur district, Karnataka 577101', NULL, 0.92);

