INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000159, 838007, 'Hebbe Falls', 'Hebbe Falls', 'Hebbe Falls drops about 550 feet in two cascading stages inside a private coffee estate near Kemmangundi, roughly 70 km from Chikmagalur town. Entry is free (6 AM to 5 PM), but the last 2 km require a trek or a private jeep hire, reportedly around INR 3,200 return. Visitors can swim in the base pool.', 'Half day', 'October to March (avoid peak monsoon for the approach road)', 'Go early in the day; the jeep operators gather at the Kemmangundi forest checkpost and fill up fast on weekends.', 'no', 'Karnataka', 0, 0, '6:17 AM', '6:08 PM', 'Rs 3,200', 5, 4, 13.5495, 75.737, 'Hebbe Falls, Kemmangundi, Tarikere taluk, Chikmagalur district, Karnataka', NULL, 0.92);

