INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000160, 838007, 'Jhari Falls', 'Jhari Falls', 'Jhari Falls, also called Buttermilk Falls, cascades in a broad milky sheet near Baba Budangiri, reached via Thippanahalli Estate Road near Attigundi. It is best seen after the monsoon when the flow is full, from around September onwards. The approach passes through coffee estates and usually needs a jeep for the final stretch.', '2-3 hours', 'September to February', 'Combine with Baba Budangiri and Manikyadhara Falls in one loop; carry a change of clothes as the spray zone is wide.', 'no', 'Karnataka', 0, 0, '6:17 AM', '6:08 PM', NULL, 4, 4, 13.4833, 75.755, 'Thippanahalli Estate Road, Attigundi, Chikmagalur district, Karnataka', NULL, 0.8);

