INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000161, 838007, 'Kalhatti Falls', 'Kallathigiri Falls', 'Kalhatti (Kallathigiri) Falls in the Chandra Drona hills drops about 122 m in tiers, with a small Veerabhadra temple built directly into the rock at its base. Tiered rocks around the falls are shaped like elephants, and the site is rich in wildlife and monkeys. It lies about 10 km from Chikmagalur town, making it an easy half-day trip.', '2-3 hours', 'September to March', 'Visit in the morning for the best light on the cascades; beware of monkeys snatching food near the temple.', 'no', 'Karnataka', 0, 0, '6:17 AM', '6:08 PM', NULL, 4, 4, 13.368, 75.7106, 'Kallathigiri, near Tarikere Road, Chikmagalur, Karnataka 577101', NULL, 0.8);

