INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 838000162, 'insert', 'bulk', 'Sunset-spot reputation and setting from travelandleisureasia.com. Coordinates approximate (on Mullayanagiri road). No official website; kept null.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000163, 838007, 'Coffee Museum', 'Coffee Museum', 'The Coffee Museum at Dasarahalli, run by the Coffee Board of India about 13 km from Chikmagalur town, traces the bean-to-cup journey with display panels, vintage machinery and equipment demonstrations. Chikmagalur is regarded as the birthplace of Indian coffee, started when Baba Budan brought seven beans from Yemen in the 17th century. Walk-through exhibits and coffee tasting make it a 1-2 hour stop.', '1-2 hours', 'September to March, mid-morning', 'Pair it with a coffee-estate walk; estate homestay tours are best during harvest (November-January) or blossom season (March-April).', 'no', 'Karnataka', 0, 0, '6:17 AM', '6:08 PM', 'Rs 20', 3, 3, 13.3418, 75.772, 'Coffee Board, Dasarahalli, Kadur Road, Chikmagalur, Karnataka 577101', NULL, 0.6);

