INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000164, 838007, 'Bhadra Wildlife Sanctuary', 'Bhadra Wildlife Sanctuary (Muthodi)', 'Bhadra Wildlife Sanctuary, a Project Tiger reserve spread over about 490 sq km in the Western Ghats, is known for tigers, leopards, elephants and Indian gaur, plus over 250 bird species. The Forest Department runs jeep safaris (6 tourists per jeep with guide and driver) and boat safaris on the Bhadra reservoir from the Muthodi side. Safaris run only in morning and evening slots.', 'Half day (2-3 hours per safari)', 'October to May; March-May best for wildlife sightings', 'Book the jeep safari, not the bus, for narrower trails and better sightings; morning slots are quieter and cooler.', 'yes', 'Karnataka', 0, 1, '6:17 AM', '6:08 PM', 'Rs 400', 4, 4, 13.4709, 75.6551, 'Bhadra Wildlife Sanctuary, Muthodi, Chikmagalur district, Karnataka', NULL, 0.8);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (838000164, 838000164, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'CONFLICT on safari pricing and timings: theholidaystory.com (Aug 2026) lists jeep Rs 400/adult with 6:30 AM-4:00 PM slots; Travel+Leisure Asia lists jeep Rs 600/person; chikmagalurtourism.org.in lists jeep Rs 600, bus Rs 500 with 6-9 AM and 3-6 PM slots. Verify current rates before visiting.');

