INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000165, 838007, 'Kudremukh National Park', 'Kudremukh National Park', 'Kudremukh National Park in Chikmagalur district is known for the Kudremukh peak trek (about 18-22 km round trip, moderate-difficult), named because the mountain silhouette resembles a horse''s face (''kudure mukha''). Trekkers need a forest permit and a mandatory local guide; as of the 2026 season permits are online-only via the Karnataka Forest Department''s Aranya Vihaara portal. Day trip from Chikmagalur, roughly 90-110 km by road (sources vary).', 'Full day (9-10 hours for the peak trek)', 'October to February; avoid June-September monsoon (leeches, slippery trails)', 'Book the online permit 7-10 days ahead, especially for weekends; daily trekker numbers are capped around 300.', 'yes', 'Karnataka', 1, 1, '6:17 AM', '6:08 PM', NULL, 5, 4, 13.1313, 75.2921, 'Kudremukh National Park, Kudremukh, Chikmagalur district, Karnataka 577101', NULL, 0.92);

