INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000166, 838007, 'Ayyanakere Lake', 'Ayyanakere Lake', 'Ayyanakere is the largest lake in Chikmagalur district and the second-largest in Karnataka, an ancient lake at the eastern base of the Baba Budan hills near Sakharayapatna, about 25-30 km from town. It is believed to have been constructed by Rukmangada Raya and renovated in 1156 AD under Hoysala rule, and it irrigates over 21,000 hectares. Mountains surround it on three sides, with the conical Shakunagiri peak as a backdrop, and it is known for sunrise and sunset views.', '2-3 hours', 'August to March; post-monsoon for full water', 'Drive via Sakharayapatna on NH173; combine with the nearby Prasanna Balleshwara Hoysala-era temple in Sakharayapatna town.', 'no', 'Karnataka', 1, 1, '6:17 AM', '6:08 PM', 'Rs 0', 3, 3, 13.35, 75.93, 'Ayyanakere, near Sakharayapatna, Chikmagalur district, Karnataka 577135', NULL, 0.6);

