INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000167, 838007, 'Z Point, Kemmangundi', 'Z Point, Kemmangundi', 'Z Point in Kemmangundi is a famous sunrise viewpoint reached by a 5 km return walk through shola forest, free of entry fees. Kemmangundi, also called Sri Krishnarajendra Hill Station (1,434 m), was the summer retreat of Mysore king Krishnaraja Wodeyar IV and is surrounded by waterfalls and valleys. The Raj Bhavan rose garden nearby is another attraction.', '2-3 hours', 'October to March, sunrise', 'Start the walk at least an hour before sunrise; carry a torch as the forest path is dark before dawn.', 'no', 'Karnataka', 1, 1, '6:17 AM', '6:08 PM', NULL, 4, 4, 13.5508, 75.7567, 'Z Point, Kemmangundi, Tarikere taluk, Chikmagalur district, Karnataka 577129', NULL, 0.8);

