INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000168, 838007, 'Manikyadhara Falls', 'Manikyadhara Falls', 'Manikyadhara Falls on the Baba Budangiri hills is a sacred waterfall revered by both Hindu and Muslim pilgrims; the stream forms the Nellikayi (Nallikayi) Theertha, where pilgrims bathe and leave behind one item of clothing per local belief. It lies near Kemmangundi, about 40 km from Chikmagalur town, and is one of the main attractions of the Baba Budan Giri area. Nearby theerthas with epic associations include Gada Theertha and Kamana Theertha near Attigundi.', '1-2 hours', 'September to March', 'Respect the sacred nature of the site; combine with the Baba Budangiri shrine and Galikere lake nearby.', 'no', 'Karnataka', 0, 0, '6:17 AM', '6:08 PM', NULL, 4, 4, 13.4872, 75.762, 'Manikyadhara Falls, Baba Budangiri Hills, Chikmagalur district, Karnataka', NULL, 0.8);

