INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000169, 838007, 'Galikere Lake', 'Galikere Lake', 'Galikere is a small lake near the Baba Budangiri temple, reached by about a 2 km walk from the shrine. The surrounding hills are one of the spots where the rare Kurinji (Neelakurinji) flowers bloom once every 12 years, last seen in 2006 and 2018. It is a quiet picnic and nature stop on the Baba Budangiri circuit.', '1-2 hours', 'September to March', 'Ask your driver or homestay for directions rather than relying only on map pins, as hill-road pins here are often wrong.', 'no', 'Karnataka', 0, 0, '6:17 AM', '6:08 PM', NULL, 3, 3, 13.4878, 75.7535, 'Galikere, Baba Budangiri Range, Chikmagalur district, Karnataka', NULL, 0.6);

