INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000170, 838007, 'Seethalayyanagiri', 'Seethalayyanagiri (Seethala)', 'Seethalayyanagiri, near Baba Budangiri, has a matha (monastery) and the dual shrine temple of Seethala-Mallikarjuna. It is one of the peaks of the Baba Budan Giri range at about 1,810 m, and tourists are barred from the surrounding hill stretch during the annual Urs at the nearby dargah. It pairs well with a visit to the Baba Budangiri caves and shrine.', '1-2 hours', 'September to March', 'Check with the district administration on access during festival periods, when the hill roads may be closed to tourists.', 'no', 'Karnataka', 0, 0, '6:17 AM', '6:08 PM', NULL, 3, 3, 13.47, 75.74, 'Seethalayyanagiri, Baba Budangiri Range, Chikmagalur district, Karnataka', NULL, 0.6);

