INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000171, 838007, 'Sringeri Sharadamba Temple', 'Sri Sharadamba Temple, Sringeri', 'The Sharadamba Temple in Sringeri, about 90 km from Chikmagalur, is the first of the four cardinal mathas founded by Adi Shankaracharya in the 8th century CE; the present granite structure was consecrated in 1916. The golden seated idol of goddess Sharadamba was installed by the 12th Jagadguru Sri Vidyaranya in the 14th century. The nearby Vidyashankara Temple is famed for its 12 zodiac pillars.', 'Half day (as a day trip from Chikmagalur)', 'October to March; during Sharada Navaratri (Sep-Oct) for the grand festival', 'Visit the Vidyashankara Temple and the Sringeri matha library on the temple''s first floor in the same trip; dress modestly.', 'no', 'Karnataka', 0, 0, '6:17 AM', '6:08 PM', NULL, 5, 5, 13.4235, 75.252, 'Sri Sharadamba Temple, Sringeri, Chikmagalur district, Karnataka 577139', NULL, 1.0);

