INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000172, 838007, 'Horanadu Annapoorneshwari Temple', 'Sri Annapoorneshwari Temple, Horanadu', 'The Annapoorneshwari Temple at Horanadu, on the banks of the Bhadra river about 110 km from Chikmagalur, is dedicated to the goddess of food; legend says the icon was established by sage Agastya in the 8th century. Every visitor is served free meals three times a day through the temple''s Anna Daanam scheme, regardless of religion, caste or creed. The deity stands in a standing posture covered in a gold kavasam, holding shanku, chakra, Sri Chakram and Devi Gayatri.', 'Half day (as a day trip from Chikmagalur)', 'October to April; avoid monsoon for the ghat roads', 'Plan your visit around the free Annadanam meal timings; the ghat approach roads are difficult during heavy monsoon rain.', 'no', 'Karnataka', 0, 0, '6:17 AM', '6:08 PM', NULL, 5, 4, 13.272, 75.3428, 'Sri Kshetra Horanadu, on the banks of the Bhadra river, Chikmagalur district, Karnataka 577181', NULL, 0.92);

