INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000173, 838007, 'Chennakeshava Temple, Belur', 'Chennakeshava Temple, Belur', 'The Chennakeshava Temple at Belur, about 25-30 km from Chikmagalur, is a 12th-century Hoysala masterpiece built under King Vishnuvardhana, famed for its intricate soapstone carvings and the Madanika bracket figures on the pillars. Along with Halebidu, it forms a classic heritage day trip from Chikmagalur; the two sites are about 17 km apart. It is part of the UNESCO-listed Sacred Ensembles of the Hoysala.', '2-3 hours', 'October to March, early morning or late afternoon', 'Hire a local guide at the entrance to understand the carvings; early morning light is best for photography of the sculptures.', 'no', 'Karnataka', 0, 0, '6:17 AM', '6:08 PM', NULL, 5, 5, 13.1626, 75.8611, 'Chennakeshava Temple, Belur, Hassan district, Karnataka 573115', NULL, 1.0);

