INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000174, 838007, 'Hoysaleswara Temple, Halebidu', 'Hoysaleswara Temple, Halebidu', 'The Hoysaleswara Temple at Halebidu, about 40 km from Chikmagalur, is the 12th-century twin-shrined Hoysala temple dedicated to Shiva, carved in soapstone with endless friezes of deities, dancers and Hoysala court life. It was twice sacked by Delhi Sultanate armies in the early 14th century, leaving it in a famously unfinished state. The on-site archaeological museum (closed on Fridays) complements the visit.', '2-3 hours', 'October to March; early morning or after 4 PM for light', 'Note the museum closes on Fridays; combine with Belur (17 km away) in a single day trip.', 'no', 'Karnataka', 0, 1, '6:17 AM', '6:08 PM', NULL, 5, 5, 13.2116, 75.0105, 'Hoysaleswara Temple, Halebidu, Hassan district, Karnataka 573121', NULL, 1.0);

