INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000175, 838007, 'Kodanda Rama Temple, Hiremagalur', 'Kodanda Rama Temple, Hiremagalur', 'The Kodandarama Temple at Hiremagalur is one of the old temples within Chikmagalur town, dedicated to Rama, and is often included in town sightseeing itineraries. It is a short drive from MG Road and the town center. Locally it is also referred to as the Kondarama temple.', '30-60 minutes', 'Morning or evening', 'Combine with Hirekolale Lake on the Mullayanagiri road for an easy half-day outing.', 'no', 'Karnataka', 0, 0, '6:17 AM', '6:08 PM', NULL, 3, 3, 13.328, 75.777, 'Kodanda Rama Temple, Hiremagalur, Chikmagalur, Karnataka 577101', NULL, 0.6);

