INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000176, 838007, 'Kavikal Gandi Viewpoint', 'Kavikal Gandi Viewpoint', 'Kavikal Gandi is a viewpoint on the Mullayanagiri road offering sweeping views of the valleys and hills of the Baba Budan Giri range. It is a popular photo stop on the standard Chikmagalur sightseeing circuit, usually visited en route to Mullayanagiri and Baba Budangiri. There is no entry fee and no facilities.', '30-60 minutes', 'October to March, morning', 'Stop here on the way up to Mullayanagiri; visibility is clearest before 10 AM.', 'no', 'Karnataka', 1, 1, '6:17 AM', '6:08 PM', NULL, 4, 4, 13.39, 75.74, 'Kavikal Gandi, on the road to Mullayanagiri, Chikmagalur district, Karnataka 577101', NULL, 0.8);

