INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000177, 838007, 'Town Canteen', 'Town Canteen', 'Town Canteen is one of Chikmagalur''s oldest and most loved eateries, running for over 60 years on IG Road opposite the Government Polytechnic. It is famous for its crisp, buttery benne (butter) masala dosa, served with cardamom-syrup-soaked gulab jamuns and filter coffee; Food Lovers TV priced the benne masala dosa around Rs 70. Seating is about 50 covers and UPI is accepted.', '45-60 minutes', 'Breakfast or evening snacks', 'Order the benne masala dosa with gulab jamun; it gets crowded at breakfast, so go early.', 'no', 'Karnataka', 0, 0, '6:17 AM', '6:08 PM', NULL, 5, 5, 13.333722, 75.773507, 'SH 57, IG Road, opposite Government Polytechnic, Vijayapura, Chikmagalur, Karnataka 577101', NULL, 1.0);

