INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000178, 838007, 'Hotel Mayura Deluxe', 'Hotel Mayura Deluxe', 'Hotel Mayura Deluxe on MG Road is a decades-old local institution popular with both residents and visitors for traditional South Indian tiffin and filter coffee. The menu covers South Indian and North Indian options, with dosas, idlis and masala dosa the most recommended dishes. The ambience is simple and unpretentious with generous portions and reasonable prices.', '45-60 minutes', 'Breakfast or lunch', 'Go for breakfast dosa and filter coffee; service can be slow at peak hours, so allow extra time.', 'no', 'Karnataka', 0, 0, '6:17 AM', '6:08 PM', NULL, 4, 4, 13.3215, 75.7735, 'M.G. Road, Chikmagalur, Karnataka 577101', NULL, 0.8);

