INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000179, 838007, 'Vishnu Delicacy', 'Vishnu Delicacy', 'Vishnu Delicacy on IG Road near the Bank of Baroda main branch is a vegetarian and vegan-friendly Indian restaurant in the town center. It is a simple, neat, budget-friendly spot with self-service on the ground floor and table service on the first floor, popular for South Indian breakfast and meals. It is recommended in several Chikmagalur food lists.', '45-60 minutes', 'Breakfast or lunch', 'Useful central stop on IG Road between sightseeing loops; parking is available in front of the restaurant.', 'no', 'Karnataka', 0, 0, '6:17 AM', '6:08 PM', NULL, 4, 4, 13.320909, 75.77233, 'Indira Gandhi Road, near Bank of Baroda Chikmagalur Main Branch, Chikmagalur, Karnataka 577101', NULL, 0.8);

