INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000180, 838007, 'Khansamaa Restaurant', 'Khansamaa Hyderabadi Restaurant', 'Khansamaa at Maharaja INN on IG Road, Joythinagar, serves North Indian, Chinese and Hyderabadi cuisine, known for its Hyderabadi Zafrani mutton biryani, dum ka murgh, Nizam shahi kebab and regional desserts like shahi tukda. TravelTriangle lists timings of 11:30 AM to 10:30 PM and a cost for two around INR 600. It is one of the better-known non-vegetarian and multi-cuisine options in town.', '1 hour', 'Lunch or dinner', 'The signature dish is the Hyderabadi Zafrani mutton biryani; confirm it is open before visiting as one listing flags possible temporary closure.', 'no', 'Karnataka', 0, 0, '6:17 AM', '6:08 PM', NULL, 4, 4, 13.321325, 75.772232, 'Maharaja INN, Indira Gandhi Road, Joythinagar, Chikmagalur, Karnataka 577101', NULL, 0.8);

