INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000181, 838007, 'Sri Mangala Fish Land', 'Sri Mangala Fish Land and Family Restaurant', 'Sri Mangala Fish Land and Family Restaurant on Barlane Road near IG Road, Adarsha Nagara, is a well-known seafood spot in Chikmagalur, consistently ranked among the town''s top restaurants by travelers. It serves coastal-style fish preparations and family-restaurant fare at budget prices (listed around Rs 310 for two on Justdial). A good pick for visitors wanting coastal/Karnataka seafood in a hill town.', '1 hour', 'Lunch or dinner', 'Order the fish curry meals; it is a family restaurant, so lunch hours are the busiest.', 'no', 'Karnataka', 0, 0, '6:17 AM', '6:08 PM', NULL, 4, 4, 13.32, 75.775, 'Barlane Road, Adarsha Nagara, near IG Road, Chikmagalur, Karnataka 577101', NULL, 0.8);

