INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 838000181, 'insert', 'bulk', 'Address/hours/price-for-two from justdial.com listings (address variants: ''Bar Len Cross Mallandur Road'', ''Barlane Road Indira Gandhi Road'', ''Barlane Road Adarsha Nagara'' - consolidated, approximate). Ranked top seafood spot by wanderlog.com. Coordinates approximate. No official website; kept null.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000182, 838007, 'Siri Coffee', 'Siri Coffee', 'Siri Coffee is a coffee shop and cafe on the outskirts of Chikmagalur town (about 5 km out, Chikkamagaluru sub-district), recommended in local food guides for an authentic Malnad coffee experience. It serves coffee and tea in a calm, green setting and is a popular short-break stop for travelers. Business listings give Sunday hours of 9 AM to 7 PM and 9 AM to 6 PM Monday to Saturday.', '30-45 minutes', 'Mid-morning or afternoon', 'Good coffee-break stop on estate routes; it is a few kilometers outside town, so plan it around sightseeing rather than as a walk-in.', 'no', 'Karnataka', 0, 0, '6:17 AM', '6:08 PM', NULL, 4, 4, 13.366283, 75.753264, 'State Highway 57, Chikkamagaluru sub-district, Chikmagalur, Karnataka', NULL, 0.8);

