INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8380031, 838, 838007, 'Baba Budangiri Urs', 'Mar', 'A three-day annual Urs (fair) at the Sri Guru Dattatreya Bababudan Swamy Dargah in the Baba Budangiri hills, drawing around 8,000 devotees; both Hindu and Muslim pilgrims attend. The district administration restricts tourist traffic to the hill stations (Mullayanagiri, Bababudangiri, Galikere, Manikyadhara) for the three days, so plan hill visits around it.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8380032, 838, 838007, 'Datta Jayanti', 'Dec', 'Datta Jayanti at the Baba Budangiri Datta Peeta draws large crowds of devotees to the hill shrine in December. Tourist access to the surrounding hill areas may be restricted by the district administration during this period.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8380033, 838, 838007, 'Sharada Navaratri', 'Sep-Oct', 'The grand 11-day Navaratri festival at the Sringeri Sharadamba Temple, with Shathachandi Homa Poornahuti performed on Mahanavami day. Special pujas, Carnatic music concerts and Vedanta discourses run through the nine nights, and the temple hosts the Vidyarambham ceremony initiating young children into learning on Vijayadashami.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8380034, 838, 838007, 'Horanadu Brahmarathotsava', 'Feb-Mar', 'The five-day annual Rathotsava (chariot festival) of the Horanadu Annapoorneshwari Temple, held in the Phalguna month, is the temple''s biggest festival and draws heavy crowds. Related celebrations include Navaratri (Sep-Oct) and Deepotsava in the Karthika month.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8380035, 838, 838007, 'Akshaya Tritiya', 'Apr-May', 'Akshaya Tritiya (Akshaya Thadige) is celebrated as the birthday of goddess Annapoorneshwari at the Horanadu temple and is considered the temple''s main festival; tradition holds that the deity''s re-consecration happened on this day. It marks the beginning of Treta Yuga per temple tradition and falls in the Vaishakha month.');

-- city: Badami (id 1028)
INSERT OR IGNORE INTO cities (id, state_id, city_name, latitude, longitude) VALUES (838008, 838, 'Badami', 15.91838, 75.68033);

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000183, 838008, 'Badami Cave Temples', 'Badami Cave Temples', 'Complex of four rock-cut cave temples carved into the red sandstone cliff overlooking Agastya Lake, built 6th-7th century under the Early Chalukya kings. Caves 1-3 are Hindu (Shiva, Vishnu) and Cave 4 is Jain, with inscriptions dating Cave 3 to 578 CE under Kirtivarman I. Maintained by the Archaeological Survey of India and on UNESCO''s tentative World Heritage list since 2014.', '2-3 hours', 'October to March, mornings', 'Climb ~100 rock-cut steps, so go early morning with water and good shoes; hire a local guide near the ticket counter for the carvings'' stories.', 'no', 'Karnataka', 1, 1, '6:58 AM', '6:14 PM', 'Rs 40 (Indian) / Rs 600 (foreign)', 5, 5, 15.91865, 75.68493, 'Badami, Bagalkot district, Karnataka 587201 (caves on the north hill, ASI ticket counter at foothill)', NULL, 1.0);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (838000183, 838000183, '9:00 AM - 5:30 PM', '9:00 AM - 5:30 PM', '9:00 AM - 5:30 PM', '9:00 AM - 5:30 PM', '9:00 AM - 5:30 PM', '9:00 AM - 5:30 PM', '9:00 AM - 5:30 PM', 'Hours conflict across government sources: Karnataka Tourism lists 6 AM-6 PM while Incredible India lists 9 AM-5:30 PM. Safe window is 9:00 AM-5:30 PM; confirm before a long drive.');

