INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 838000183, 'insert', 'bulk', 'Fee conflict: older pages list Rs 25 (Indian)/Rs 300 (foreign); Karnataka Tourism currently publishes Rs 40/Rs 600 and multiple 2026 sources repeat Rs 40/600. Hours conflict between 6 AM-6 PM and 9 AM-5:30 PM. Coords geocoded via map tool (full-address match). Sunrise/sunset computed for Badami coords for 15 Jan (peak season); vary ~30 min through the year.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000184, 838008, 'Agastya Lake', 'Agastya Lake', 'Large artificial lake in the heart of Badami, surrounded by red sandstone cliffs and ringed by temples including the cave temples, the Bhutanatha group and the Mallikarjuna group. Local tradition holds its water has healing powers and a dip is considered auspicious. Its stepped ghats and the sunset reflections of the Bhutanatha temples make it Badami''s most photographed spot.', '1-2 hours', 'October to March, mornings and evenings', 'Best viewed from the cave-temple cliff top in the morning and from the Bhutanatha side at sunset; carry coins for the local sugarcane and coconut vendors.', 'no', 'Karnataka', 1, 1, '6:58 AM', '6:14 PM', NULL, 4, 4, 15.91888, 75.68462, 'Badami town centre, Bagalkot district, Karnataka 587201 (in the valley between the north and south fort hills)', NULL, 0.8);

