INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000185, 838008, 'Bhutanatha Group of Temples', 'Bhutanatha Group of Temples', 'Group of 7th-century sandstone temples on the eastern shore of Agastya Lake, dedicated to Shiva as Bhutanatha (lord of ghosts/spirits), with later shrines including the 11th-century Mallikarjuna group nearby. Its silhouette reflected in the lake against the red cliffs is Badami''s most famous sunset view. The complex blends Early Chalukya and later styles across several centuries of additions.', '1-2 hours', 'October to March, sunset', 'Arrive 30-45 minutes before sunset for the famous lake reflection photos; the walk around the lake takes 1.5-2 hours including the Mallikarjuna shrines.', 'no', 'Karnataka', 0, 1, '6:58 AM', '6:14 PM', NULL, 5, 5, 15.92153, 75.68668, 'East bank of Agastya Lake, Badami, Karnataka 587201 (walk around the lake from the cave temples)', NULL, 1.0);

