INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000186, 838008, 'Mallikarjuna Group of Temples', 'Mallikarjuna Group of Temples', '11th-century group of small shrines on the shore of Agastya Lake next to the Bhutanatha complex, notable for its star-shaped (stellate) plan - a marker of the later Chalukya architectural phase. Usually visited together with the Bhutanatha temples on the lake walk. The templenet temple encyclopedia specifically notes its star-shaped plan and 11th-century date.', '30-45 minutes', 'October to March', 'Combine with the Bhutanatha temples in one lakeside walk rather than planning a separate trip.', 'no', 'Karnataka', 0, 1, '6:58 AM', '6:14 PM', NULL, 3, 3, 15.9206, 75.6873, 'East bank of Agastya Lake, Badami, Karnataka 587201 (adjacent to the Bhutanatha temples)', NULL, 0.6);

