INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 838000186, 'insert', 'bulk', 'Coords approximate: adjacent to the geocoded Bhutanatha group on the lake''s east shore; not independently geocoded. No fee or hours published. Sunrise/sunset computed for Badami coords for 15 Jan; vary ~30 min through the year.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000187, 838008, 'Badami Fort', 'Badami Fort', 'Chalukya-era hill fort crowning the north cliff above Agastya Lake, with massive walls, gateways, granaries, an old cannon and remains of palaces. The climb passes the Lower and Upper Shivalaya temples and ends with a panoramic view of the lake, the cave temples and the Bhutanatha group. An open courtyard inside the fort is noted for its echo effect.', '2-3 hours', 'October to March, morning or late afternoon', 'Steep rocky climb with little shade - carry water and wear gripped shoes; allow time to descend before dark.', 'no', 'Karnataka', 1, 1, '6:58 AM', '6:14 PM', NULL, 4, 4, 15.9192, 75.6865, 'Top of the north fort hill, Badami, Karnataka 587201 (trek up from the Archaeological Museum / Lower Shivalaya side)', NULL, 0.8);

