INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000188, 838008, 'Upper Shivalaya', 'Upper Shivalaya', '7th-century Shiva temple atop the north fort hill, reached by the trek from the Archaeological Museum. Built of the local red sandstone and noted for its sculpted panels and the sweeping view it commands over Agastya Lake, the cave temples and the town. Travel blogs recommend it for sunrise to beat the heat and the crowds.', '1 hour (plus trek time)', 'October to March, sunrise', 'Start the trek early morning from the museum side; the path is rocky and poorly marked in places.', 'no', 'Karnataka', 1, 1, '6:58 AM', '6:14 PM', NULL, 4, 4, 15.92146, 75.68331, 'North fort hill top, Badami, Karnataka 587201', NULL, 0.8);

