INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000189, 838008, 'Lower Shivalaya', 'Lower Shivalaya', 'Small standalone Shiva temple on a flat rocky plateau about halfway up the north-hill trek, below the Upper Shivalaya. Reached by a narrow path tucked between sandstone cliffs; only remnants of parts of the structure survive, but its isolated cliff-edge setting makes it a striking stop on the fort climb.', '30 minutes (plus trek time)', 'October to March, morning', 'Watch for the narrow turn between the cliffs on the way up; easy to miss without a guide.', 'no', 'Karnataka', 0, 1, '6:58 AM', '6:14 PM', NULL, 3, 3, 15.9212, 75.6825, 'North fort hill, midway on the trek from the Archaeological Museum, Badami, Karnataka 587201', NULL, 0.6);

