INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000190, 838008, 'Malegitti Shivalaya', 'Malegitti Shivalaya', '7th-century Shiva temple of the Early Chalukya period, perched on a massive boulder along the southern fort wall with a Dravidian-style tower. Often photographed silhouetted against the sky from the town below; it stands beside the later fortifications added by Tipu Sultan''s era rulers. One of Badami''s oldest surviving structural temples.', '30-45 minutes', 'October to March, morning', 'Photograph it from the town/lake side in the morning when the sandstone glows red.', 'no', 'Karnataka', 1, 1, '6:58 AM', '6:14 PM', NULL, 3, 3, 15.92232, 75.67948, 'SH-14, Badami, Karnataka 587201 (atop the southern fort wall)', NULL, 0.6);

