INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000191, 838008, 'Archaeological Museum, Badami', 'Archaeological Museum, Badami', 'ASI-run museum at the foot of the north hill displaying Chalukya-era sculptures, inscriptions, carved panels and architectural fragments recovered from Badami, Aihole and Pattadakal, plus documentation of ASI restoration work. A useful orientation stop before the caves and fort trek. Photography is prohibited inside.', '45 minutes - 1 hour', 'October to March', 'Carry exact change for the ticket; mobile network near the counter is weak and the trek to Upper Shivalaya starts right behind the museum.', 'no', 'Karnataka', 0, 0, '6:58 AM', '6:14 PM', 'Rs 5', 3, 3, 15.921, 75.68472, 'Near the foothill of the north hill, Badami, Karnataka 587201', NULL, 0.6);

