INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000192, 838008, 'Tipu Sultan Mosque', 'Tipu Sultan Mosque', 'Historic mosque in the Tipu Nagar area of Badami, associated with the town''s 18th-century Muslim heritage (the southern fort also has a dargah and masjid noted by travel writers). A modest working place of worship rather than a monument; listed as a point of interest on Badami attraction lists.', '20-30 minutes', 'October to March', 'A short stop combined with the town walk; dress modestly and avoid prayer times.', 'no', 'Karnataka', 0, 0, '6:58 AM', '6:14 PM', NULL, 2, 2, 15.92471, 75.67969, 'Tipu Nagar, Badami, Karnataka 587201', NULL, 0.4);

