INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000193, 838008, 'Dattatreya Temple', 'Dattatreya Temple', '12th-century Dattatreya temple noted in the Templenet Encyclopedia of Indian Temples among Badami''s noteworthy structural temples (alongside the Mallikarjuna). Travel writers place a Dattatreya temple on the southern fort alongside later-period shrines, a dargah and a masjid. A quiet, rarely visited shrine compared to the cave temples.', '30 minutes', 'October to March', 'Ask a local guide on the fort walk to point it out; it is not signposted like the bigger sites.', 'no', 'Karnataka', 0, 0, '6:58 AM', '6:14 PM', NULL, 2, 2, 15.922, 75.6785, 'Southern fort hill area, Badami, Karnataka 587201', NULL, 0.4);

