INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000194, 838008, 'Badami Rock Climbing', 'Badami Rock Climbing', 'Badami''s fiery red sandstone cliffs are India''s premier sport-climbing destination, with over 150 bolted routes ranging from 5b to 8b+ across cracks, overhangs and technical faces. Local operators and tour companies run guided climbing and rappelling sessions for beginners and experts. Best done October to March to avoid the summer heat.', 'Half day', 'October to March', 'Book through a local operator or adventure tour company; beginners get harnesses and helmets included.', 'no', 'Karnataka', 0, 1, '6:58 AM', '6:14 PM', NULL, 4, 5, 15.9155, 75.6805, 'Red sandstone cliffs around Badami, Karnataka 587201 (climbing sectors on the hills flanking the town)', NULL, 0.88);

