INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000195, 838008, 'Akka-Tangi Falls', 'Akka-Tangi Falls', 'Seasonal waterfall cascading off the cliff behind the Badami cave temples, visible from the cave courtyard area. It flows only during and just after the monsoon and can be dry the rest of the year. A short detour after the caves; best combined with a monsoon-season visit.', '30-45 minutes', 'June to September (monsoon only)', 'Visit only in monsoon months; there may be no water at other times.', 'no', 'Karnataka', 0, 0, '6:58 AM', '6:14 PM', NULL, 2, 3, 15.919498, 75.689491, 'Behind the cave temples, Badami, Karnataka 587201', NULL, 0.48);

