INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000196, 838008, 'Badami Bazaar', 'Badami Bazaar', 'The bustling main bazaar street of Badami town near the cave-temple area, with street-food stalls (khara mandakki/bhel, cut chai), small eateries and shops selling handicrafts and souvenirs. Travel guides list Bidriware metalwork, textiles and jewellery as local shopping options. A good evening stroll after the day''s sightseeing.', '1 hour', 'October to March, evenings', 'Try the local khara mandakki (spicy puffed-rice snack) and cut chai from a street vendor in the evening.', 'no', 'Karnataka', 0, 0, '6:58 AM', '6:14 PM', NULL, 2, 3, 15.919, 75.681, 'Main bazaar area, Badami town, Karnataka 587201', NULL, 0.48);

