INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000197, 838008, 'Mahakuteshwar Temple Complex, Mahakuta', 'Mahakuteshwar Temple Complex, Mahakuta', 'Day trip ~13 km from Badami: a group of 6th-7th century Early Chalukya Shiva temples, including the Mahakuteshwar temple with its Nagara-style tower and a five-faced (Panchamukhi) Shiva lingam. A natural mountain spring feeds the Vishnu Pushkarini tank, where devotees take a holy dip. The complex yielded two important 7th-century inscriptions, including the Mahakuta pillar inscription recording Chalukya grants.', '1-2 hours (half-day trip from Badami)', 'October to March, mornings', 'Carry a towel if you plan the holy dip in the pushkarini; Mahashivaratri (Feb-Mar) is the liveliest time.', 'no', 'Karnataka', 0, 0, '6:58 AM', '6:14 PM', NULL, 4, 4, 15.93359, 75.72136, 'Mahakuta village, Nandikeshwar, Bagalkot district, Karnataka 587201 (~13 km northeast of Badami)', NULL, 0.8);

