INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000198, 838008, 'Banashankari Temple, Cholachagudda', 'Banashankari Temple, Cholachagudda', 'Day trip ~5 km from Badami: famous temple of goddess Banashankari (Shakambhari, a form of Parvati) at Cholachagudda. The present structure is 18th-century Maratha-era with Dravidian-Nagara mix; the black-stone goddess sits on a roaring lion with eight arms. Opposite the entrance is the large Haridra Tirtha tank with a tall lamp tower. It hosts the month-long Banashankari Jatre every Jan-Feb with the Maha Rathotsava chariot procession.', '1-2 hours (half-day trip from Badami)', 'October to March; Jan-Feb for the jatre', 'No official website found; plan around the midday closure gap (1-3 PM) and expect huge crowds during the Jan-Feb jatre.', 'no', 'Karnataka', 0, 0, '6:58 AM', '6:14 PM', NULL, 4, 4, 15.88722, 75.705, 'SH 57, Cholachagudda, Badami, Karnataka 587201 (~5 km from Badami town)', NULL, 0.8);

