INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000199, 838008, 'Pattadakal Group of Monuments', 'Pattadakal Group of Monuments', 'Day trip ~22 km from Badami: UNESCO World Heritage group of 10 major temples built 7th-8th century, blending North Indian Nagara and South Indian Dravidian styles - including the Virupaksha temple built by Queen Lokamahadevi in 742 CE to commemorate a Chalukya victory over the Pallavas. Pattadakal was the Chalukya coronation city; the ASI also maintains a sculpture gallery here. Allow 2-3 hours on foot.', '2-3 hours (half-day trip from Badami)', 'October to March; January for the Pattadakal Dance Festival', 'Buy tickets only at the ASI counter or official QR; the far-end temples (Virupaksha, Mallikarjuna) have the finest carvings - save them for last.', 'no', 'Karnataka', 0, 0, '6:58 AM', '6:14 PM', 'Rs 40 (Indian) / Rs 600 (foreign)', 5, 5, 15.950201, 75.816176, 'Pattadakal village, Bagalkot district, Karnataka 587201 (~22 km from Badami, on the Malaprabha river)', NULL, 1.0);

