INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000200, 838008, 'Aihole - Durga Temple Complex', 'Aihole - Durga Temple Complex', 'Day trip ~34 km from Badami: ''the cradle of Indian temple architecture'', with 120+ temples from the 4th-12th century. The ticketed Durga Temple complex includes the 7th-century apsidal Durga Temple (gajaprastha plan), the Lad Khan temple and the ASI Archaeological Museum (entry ~Rs 5, photography prohibited). Also see the 6th-century rock-cut Ravana Phadi cave and the Meguti Jain temple on the hill, whose 634 CE inscription by Ravikirti praises Pulakeshin II.', '3-4 hours (half to full-day trip from Badami)', 'October to March', 'Visit Ravana Phadi and climb Meguti hill for the inscription and village panorama in the same trip; the museum takes 30-45 minutes.', 'no', 'Karnataka', 0, 0, '6:58 AM', '6:14 PM', 'Rs 20 (Indian) / Rs 200 (foreign) for Durga Temple complex', 5, 4, 16.020699, 75.881927, 'Aihole village, Hungund taluk, Bagalkot district, Karnataka 587124 (~34 km from Badami)', NULL, 0.92);

