INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000201, 838008, 'Kudala Sangama', 'Kudala Sangama', 'Day trip ~50 km from Badami: holy confluence of the Krishna and Malaprabha rivers and the samadhi place of 12th-century Lingayat philosopher Basavanna. The 12th-century Sangameshwara temple stands on the riverbank, with a Shiva lingam mid-river opposite the entrance. The temple trust runs free meals (dasoha) and accommodation; festivals are held in the Magha month with well-known Shivaratri celebrations.', '2-3 hours (full-day trip from Badami, ~1.5 hr drive each way)', 'October to March', 'Plan around the midday closure (12:30-4 PM); free dasoha meals are available - useful for a full-day outing.', 'no', 'Karnataka', 0, 0, '6:58 AM', '6:14 PM', NULL, 3, 4, 16.207138, 76.065861, 'Kudala Sangama, Amingad, Bagalkot district, Karnataka 587112 (~50 km from Badami)', NULL, 0.68);

