INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000202, 838008, 'Alamatti Dam and Gardens', 'Alamatti Dam and Gardens', 'Day trip ~45 km from Badami: the Lal Bahadur Shastri Sagar dam across the Krishna river, the main reservoir of the Upper Krishna Irrigation Project. The attraction for visitors is the cluster of terrace gardens (including the Rock Garden) with musical fountains, boating and an artificial forest - popular as a family picnic spot, especially October-February and during monsoon when the reservoir is full.', '2-3 hours (half-day trip from Badami)', 'October to February; monsoon for a full reservoir', 'Stay back for the evening musical fountain if it is running; carry water and snacks as food options are basic.', 'no', 'Karnataka', 0, 0, '6:58 AM', '6:14 PM', 'Rs 20 (adult) / Rs 10 (child)', 3, 3, 16.335, 75.9, 'Almatti, Nidagundi taluk, Vijayapura district, Karnataka 586213 (~45 km from Badami)', NULL, 0.6);

