INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000204, 838008, 'The Bridge Restaurant (Clarks Inn)', 'The Bridge Restaurant (Clarks Inn)', 'In-house restaurant of Clarks Inn Badami (listed as The Bridge), serving Chinese and Indian cuisine. The most-reviewed restaurant in Badami on Tripadvisor (51 reviews) - reviews are mixed (''average food'') but it is the town''s main multi-cuisine option with veg-friendly choices. Convenient for guests staying at Clarks Inn.', '1 hour', 'October to March', 'The safest bet for Chinese dishes in town; set expectations to small-town standards.', 'no', 'Karnataka', 0, 0, '6:58 AM', '6:14 PM', NULL, 3, 2, 15.9187, 75.68047, 'Clarks Inn Badami, 1755 Veerpulakeshi Circle, Badami Main Road, Badami, Karnataka 587201', NULL, 0.52);

