INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000206, 838008, 'Pakwan Restaurant', 'Pakwan Restaurant', 'Well-reviewed budget vegetarian restaurant in Badami town (4.8 rating, 800+ votes on restaurant aggregators). Serves vegetarian Indian meals at low prices and stays open till about 10:30 PM, making it one of the town''s dependable dinner options for vegetarian travellers.', '1 hour', 'October to March', 'Good budget pure-veg option; confirm location with locals as online address details are thin.', 'no', 'Karnataka', 0, 0, '6:58 AM', '6:14 PM', NULL, 3, 4, 15.92, 75.682, 'Badami town, Karnataka 587201 (exact street address unpublished)', NULL, 0.68);

