INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000207, 838008, 'Hotel Paradise Family Restaurant', 'Hotel Paradise Family Restaurant', 'Family restaurant in Badami serving Indian cuisine, rated 5/5 across a dozen Tripadvisor reviews with praise for tasty, well-presented local food and friendly service. Budget-to-mid pricing. About 2.5 km from the cave temples on the SH-14 side.', '1 hour', 'October to March', 'Ask for local North-Karnataka preparations; highly rated but small - expect a wait at peak dinner hours.', 'no', 'Karnataka', 0, 0, '6:58 AM', '6:14 PM', NULL, 3, 4, 15.93901, 75.67531, 'SH-14, Badami, Karnataka 587201', NULL, 0.68);

