INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000208, 838008, 'Golden Caves', 'Golden Caves', 'Budget restaurant in Badami serving Indian and Asian dishes (dosa and Indo-Chinese mentioned in reviews), rated well by travellers (29 Tripadvisor reviews) as a decent stop after sightseeing in Badami, Aihole and Pattadakal. Cheap-eats pricing near the cave-temple approach road.', '45 minutes', 'October to March', 'Handy budget breakfast/lunch stop on the SH-14 cave-temple route.', 'no', 'Karnataka', 0, 0, '6:58 AM', '6:14 PM', NULL, 2, 3, 15.92381, 75.67936, 'SH-14, Badami, Karnataka 587201', NULL, 0.48);

