INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000209, 838009, 'Shivappa Nayaka Palace Museum', 'Shivappa Nayaka Palace Museum', 'A 17th-century wooden palace on the banks of the Tunga River, built largely of rosewood with a carved Darbar hall of massive wooden pillars. Named for Keladi Nayaka king Shivappa Nayaka (art historian George Michell attributes the bungalow to Hyder Ali). The Government Museum inside displays Hoysala, Chalukya and Keladi-era stone sculptures, inscriptions, hero and Sati stones, plus weapons and coins; it is an ASI-protected monument.', '1-2 hours', 'October to March, mornings', 'Many exhibit labels are Kannada-only — use a camera translate app; ask staff before photographing inside the museum.', 'no', 'Karnataka', 0, 0, '6:10 AM', '6:13 PM', 'Free', 4, 4, 13.9276, 75.5836, 'K.R. Puram, Double Road, Shivamogga, Karnataka 577202', NULL, 0.8);

