INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000210, 838009, 'Sacred Heart Cathedral', 'Sacred Heart Cathedral', 'A major Roman Catholic cathedral in Tank Mohalla on B.H. Road, widely reported as the second-largest church in India. The Roman-Gothic structure spans about 18,000 sq ft with a prayer hall said to hold around 5,000 worshippers. The parish traces back to the 1830s; the church gained cathedral status in 1988 and the current building was completed in 1998.', '1 hour', 'October to March, mornings', 'Dress modestly and keep phones silent; it is an active place of worship with regular Mass services.', 'no', 'Karnataka', 0, 0, '6:10 AM', '6:13 PM', NULL, 4, 4, 13.9318, 75.5743, 'B.H. Road, Tank Mohalla, Shivamogga, Karnataka 577201', NULL, 0.8);

