INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 838000210, 'insert', 'bulk', '''Second-largest church in India'' is a widely repeated local claim (not an official ranking) — repeated across TripHobo, Wanderlog and travel blogs. Coordinates are approximate (Tank Mohalla, B.H. Road) — within ~1 km of the cathedral. ''Second largest church in Asia'' claim on en-academic appears inflated; treated cautiously.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000211, 838009, 'Gandhi Park', 'Gandhi Park', 'Shivamogga''s large, spacious city park, a popular family outing spot. It is reported to house a toy train and an aquarium, with the Kuvempu Rangamandira cultural auditorium nearby hosting frequent cultural programmes.', '1-2 hours', 'October to March, late afternoons', 'Combine with an evening cultural programme at the nearby Kuvempu Rangamandira if one is scheduled.', 'no', 'Karnataka', 0, 0, '6:10 AM', '6:13 PM', NULL, 2, 3, 13.9295, 75.5702, 'Shivamogga, Karnataka', NULL, 0.48);

