INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000212, 838009, 'Old Tunga Bridge', 'Old Tunga Bridge', 'A heritage bridge over the Tunga River in Shivamogga, more than a hundred years old, whose construction was commissioned and supervised by Bharat Ratna Sir M. Visvesvaraya. It stands as an early-20th-century engineering landmark of the city.', '30 minutes', 'October to March, late afternoons', 'Walk across at sunset for river views; watch for traffic as it is still in use.', 'no', 'Karnataka', 0, 1, '6:10 AM', '6:13 PM', NULL, 2, 3, 13.924, 75.578, 'Across the Tunga River, Shivamogga, Karnataka', NULL, 0.48);

