INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000213, 838009, 'Kote Anjaneya Temple', 'Kote Anjaneya Temple', 'A well-known Hanuman (Anjaneya) temple in the Kote area of Shivamogga, one of the city''s noted Hindu religious centres. Devotees visit for daily worship, with bigger crowds on Saturdays and during Hanuman Jayanti.', '1 hour', 'October to March, mornings', 'Visit early morning to avoid crowds; footwear must be removed before entering the temple premises.', 'no', 'Karnataka', 0, 0, '6:10 AM', '6:13 PM', NULL, 2, 3, 13.9289, 75.5704, 'Kote, Shivamogga, Karnataka', NULL, 0.48);

