INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 838000213, 'insert', 'bulk', 'Named among Shivamogga''s notable temples in the en-academic Shivamogga article. Coordinates approximate (Kote locality) — flag as approx. Hours and cost unpublished.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000214, 838009, 'Tyavarekoppa Lion and Tiger Safari', 'Tyavarekoppa Lion and Tiger Safari', 'A wildlife safari park about 10 km from Shivamogga, established in 1988 by the Karnataka Forest Department as the state''s second safari park after Bannerghatta. Spread over roughly 250 hectares, it houses Bengal tigers, Asiatic lions, leopards, a rare black panther born here in 2012, and functions as a rehabilitation centre for rescued circus animals. The complex also includes a small zoo and museum; visitors ride through zones in caged buses.', '2-3 hours', 'October to March, mornings', 'Safaris are reported to run only with 10-15 people — go on weekends if you are in a small group; the park is closed on Tuesdays.', 'no', 'Karnataka', 0, 0, '6:10 AM', '6:13 PM', 'Rs 250', 4, 3, 13.971, 75.489, 'Tyavarekoppa, Thevara Koppa, Shivamogga, Karnataka 577205', NULL, 0.72);

