INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 838000214, 'insert', 'bulk', 'Coordinates averaged from Meta location data (13.971967, 75.493621) and AroundUs (13.96981, 75.48847) — within ~1 km of the park. Ticket price conflicts: airial (2026) lists ~Rs 250 combined, zoo ~Rs 80, safari ~Rs 200; old 2013 Tripadvisor reviews list Rs 20 entry + Rs 50 safari — prices have clearly risen; used the 2026 figure. Reviews are mixed — more zoo-like than a true safari; ratings reflect that.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000215, 838009, 'Sakrebailu Elephant Camp', 'Sakrebailu Elephant Camp', 'An elephant training and ecotourism camp run by the Karnataka Forest Department on the Shimoga-Thirthahalli road, near the Tunga River (about 14 km from the city). Around 25 elephants, including calves, are brought here for bathing in the river by mahouts in the early morning, followed by feeding and close interaction with visitors. The site has a children''s play area and a souvenir shop.', '2-3 hours', 'November to February, early mornings', 'Reach by 8:30 AM to watch the elephants bathe — after about 11:30 AM they are taken back to the forest and activity winds down.', 'no', 'Karnataka', 0, 0, '6:10 AM', '6:13 PM', 'Rs 50', 5, 4, 13.99, 75.53, 'Sakrebyle, Shivamogga, Karnataka 577202', NULL, 0.92);

