INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 838000215, 'insert', 'bulk', 'Timings 8:30 AM-1 PM and Rs 50 adult entry are consistent across thedilli.in (Dec 2024) and Tripadvisor reviews. Coordinates approximate (Sakrebyle village near Gajanur on the Thirthahalli road) — flag as approx. Some sources give 8:30-11 AM as the core window; used the wider published window.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000216, 838009, 'Gajanur Dam', 'Gajanur Dam', 'A dam across the Tunga River about 12 km from Shivamogga on the way to Thirthahalli, near the village of Gajanur. It is a popular picnic spot with reported coracle (country-boat) rides and water-sport options, and lies on the same route as the Sakrebailu Elephant Camp and Mandagadde Bird Sanctuary.', '1-2 hours', 'October to February, afternoons', 'Combine with Sakrebailu (early morning) and Mandagadde on a single Thirthahalli-road day trip.', 'no', 'Karnataka', 0, 1, '6:10 AM', '6:13 PM', NULL, 3, 3, 13.98, 75.545, 'Gajanur, Shivamogga, Karnataka', NULL, 0.6);

