INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000217, 838009, 'Mattur - Sanskrit Village', 'Mattur - Sanskrit Village', 'A village a few kilometres from Shivamogga famed as India''s ''Sanskrit Village''. After a 1983 Samskrita Bharati workshop and the Pejawar seer''s remark that it should become a place ''where whole houses talk in Sanskrit'', residents — mostly Sankethi Brahmins — adopted Sanskrit for everyday communication. The village has one of the district''s best academic records and has produced over 30 Sanskrit professors.', '1-2 hours', 'October to March, daytime', 'This is a living village, not a tourist attraction — greet residents respectfully and ask before photographing homes or people.', 'no', 'Karnataka', 0, 0, '6:10 AM', '6:13 PM', NULL, 3, 4, 13.8734, 75.5847, 'Mattur, Shivamogga, Karnataka', NULL, 0.68);

