INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000218, 838009, 'Mandagadde Bird Sanctuary', 'Mandagadde Bird Sanctuary', 'A tiny 1.14-acre island in the Tunga River, about 30 km from Shivamogga on the Shimoga-Thirthahalli road, and part of the Shettihalli Wildlife Sanctuary. During the nesting season over 5,000 birds arrive — mainly median egrets, darters (snakebirds) and little cormorants. The forest department maintains a watchtower and offers boating; the riverbank viewpoint gives wide photographic views.', '2-3 hours', 'July to October, early mornings', 'Carry binoculars and go early morning when birds are most active; the riverbank viewpoint works even when the island itself is off-limits.', 'no', 'Karnataka', 1, 1, '6:10 AM', '6:13 PM', 'Free', 4, 4, 13.842, 75.647, 'Mandagadde, on Shimoga-Thirthahalli Road, Shivamogga, Karnataka', NULL, 0.8);

