INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000219, 838009, 'Bhadra Dam', 'Bhadra Dam', 'A 194-ft-high dam across the Bhadra River about 28 km from Shivamogga, near Kuvempu University. The reservoir has created a number of small islands, and boat rides around them are a reported attraction. The surrounding area is a quiet picnic and sunset spot.', '1-2 hours', 'October to February, late afternoons', 'Carry food and water — facilities at the dam are minimal.', 'no', 'Karnataka', 0, 1, '6:10 AM', '6:13 PM', NULL, 3, 3, 13.707, 75.639, 'Bhadra Reservoir Project, near Kuvempu University, Shivamogga, Karnataka', NULL, 0.6);

