INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000220, 838009, 'Bhadra Wildlife Sanctuary', 'Bhadra Wildlife Sanctuary', 'A forested wildlife sanctuary of the Western Ghats about 35 km from Shivamogga, centred on the Bhadra reservoir backwaters. It is known for tigers, leopards, elephants, gaur and rich birdlife. The Jungle Lodges & Resorts River Tern Lodge on the reservoir offers jeep safaris and boat-based wildlife viewing.', 'Half day to full day', 'November to April, mornings', 'Safaris through Jungle Lodges & Resorts need advance booking — day-visit forest safaris have limited seats.', 'yes', 'Karnataka', 0, 1, '6:10 AM', '6:13 PM', NULL, 4, 4, 13.685, 75.63, 'Bhadra Wildlife Sanctuary, Shivamogga, Karnataka', NULL, 0.8);

