INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 838000220, 'insert', 'bulk', 'Included as a well-established sanctuary near Shivamogga; River Tern Lodge (Jungle Lodges) is referenced in the Trawell page nav. Coordinates approximate (sanctuary interior) — flag as approx. Ticket prices vary by safari operator and season — left null.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000221, 838009, 'Kavishaila, Kuppalli', 'Kavishaila, Kuppalli', 'A rock monument on a hillock in Kuppalli, the ancestral village of poet Kuvempu (Jnanpith awardee Kuppalli Venkatappa Puttappa), about 35-40 km from Shivamogga via Thirthahalli. Megalithic rocks are arranged in a circle resembling Stonehenge; at the centre stands Kuvempu''s memorial where he was laid to rest. Nearby are Kavimane (his childhood home, now a museum) and the similar memorial of his novelist son Poornachandra Tejaswi. Granite slabs carry engraved poems and quotes of Kuvempu.', '2-3 hours', 'October to March, late afternoons', 'Climb in the late afternoon for the panoramic valley view at sunset; combine with the Kavimane museum below.', 'no', 'Karnataka', 0, 1, '6:10 AM', '6:13 PM', NULL, 4, 4, 13.7294, 75.7415, 'Kuppalli, Thirthahalli Taluk, Shivamogga, Karnataka', NULL, 0.8);

