INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000222, 838009, 'Lakshminarasimha Temple, Bhadravathi', 'Lakshminarasimha Temple, Bhadravathi', 'An early-13th-century Hoysala temple in Bhadravathi, about 20 km southeast of Shivamogga on the east bank of the Bhadra River. Built of soapstone as a trikuta (three-shrine) temple, it has two ''exceptional'' stellate (star-shaped) shrines noted by scholar Adam Hardy, with outer walls richly carved with Vaishnava, Shaiva and Shakta imagery. It is protected by the Karnataka ASI division.', '1-2 hours', 'October to March, mornings', 'Parking is limited in the surrounding residential area — be prepared to park a short walk away.', 'no', 'Karnataka', 0, 0, '6:10 AM', '6:13 PM', NULL, 4, 4, 13.8486, 75.7005, 'Bhadravathi, Shivamogga, Karnataka', NULL, 0.8);

