INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000223, 838009, 'Ikkeri Aghoreshwara Temple', 'Ikkeri Aghoreshwara Temple', 'DAY TRIP (~76 km from Shivamogga). A 16th-century granite Shiva temple in Ikkeri village near Sagar — the sole surviving vestige of Ikkeri, capital of the Keladi Nayakas from about 1560 to 1640. It blends Kadamba, Hoysala, Chalukya, Vijayanagara and Keladi styles, with a majestic glass-polished granite Nandi in axial shrine and stone effigies of three Keladi chiefs before the sanctum. Maintained by the ASI; no entry fee.', '1-2 hours', 'October to March, mornings', 'Carry drinking water and use facilities before arriving — reviewers note there are no toilets or drinking water at the site.', 'no', 'Karnataka', 0, 0, '6:10 AM', '6:13 PM', 'Free', 5, 5, 14.135, 75.0226, 'Ikkeri, Sagara Taluk, Shivamogga, Karnataka', NULL, 1.0);

