INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 838000223, 'insert', 'bulk', 'Coordinates exact from Wikipedia (14.1350, 75.0226). Distance: 99mustsee says 76 km north of Shimoga; Ikkeri is 6 km south of Sagara town. History and architecture cross-verified via Wikipedia, sahasa.in and milesandtrails.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000224, 838009, 'Keladi Rameshwara Temple', 'Keladi Rameshwara Temple', 'DAY TRIP (~84 km from Shivamogga, 7-10 km from Sagar). The temple complex at Keladi, the first capital of the Keladi Nayakas, with 16th-century Rameshwara, Veerabhadra and Parvati shrines in a Hoysala-Dravidian blend. Highlights include the Gandabherunda (twin-headed bird) ceiling motif and intricate relief sculptures; a small Keladi museum nearby holds Nayaka-era artefacts.', '1-2 hours', 'October to March, mornings', 'Combine with Ikkeri (nearby) and Jog Falls on a Sagar-side day trip; dress modestly as it is an active temple.', 'no', 'Karnataka', 0, 0, '6:10 AM', '6:13 PM', NULL, 4, 4, 14.2242, 74.9975, 'Keladi, Sagara Taluk, Shivamogga, Karnataka', NULL, 0.8);

