INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 838000224, 'insert', 'bulk', 'Distance conflict: Rome2Rio gives 84.2 km road distance from Shivamogga, airial.travel says 60-70 km — used the Rome2Rio road figure with the conflict noted. Coordinates approximate (Keladi village) — flag as approx. Entry generally free; kept null since no authoritative price published.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000225, 838009, 'Sigandur Chowdeshwari Temple', 'Sigandur Chowdeshwari Temple', 'DAY TRIP (~75 km from Shivamogga). A revered temple of Goddess Chowdeshwari (Sigandureshwari) set amid the Sharavathi backwaters in Sagar taluk. It was traditionally reached only by a government launch/ferry that carries vehicles and passengers across the backwaters; a new bridge has now eased road access. The goddess is famed for fulfilling wishes, especially over lost valuables and property disputes. Ashada Pooja (June-July) and Navaratri draw huge crowds.', 'Half day', 'October to March, mornings', 'Reach the ferry/launch point before 5-6 PM; check current bridge status — direct road access may now bypass the ferry.', 'no', 'Karnataka', 0, 0, '6:10 AM', '6:13 PM', NULL, 5, 4, 14.145, 74.785, 'Sigandur, Sagara Taluk, Shivamogga, Karnataka', NULL, 0.92);

