INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 838000225, 'insert', 'bulk', 'Launch/ferry crossing, ~29 km from Sagar, Ashada/Nava­ratri peaks confirmed via cultureandheritage.org and Tripadvisor reviews. New bridge detail per cultureandheritage.org (recent connectivity update). Coordinates approximate (backwaters area) — flag as approx. No published entry price.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000226, 838009, 'Jog Falls', 'Jog Falls', 'DAY TRIP (~100-115 km from Shivamogga). The Sharavathi River plunges 253 metres (830 ft) at Jog in Sagar taluk, splitting into four cascades — Raja, Rani, Roarer and Rocket — making it India''s second-highest plunge waterfall. It reopened in May 2025 after a major development project added a viewing tower, modernised entry gate and parking. A 1,400-step trail descends to the base. Best August-December; flow is regulated by the upstream Linganmakki Dam.', '2-3 hours', 'August to December, mornings', 'Go post-monsoon (Oct-Dec) for full flow with clear viewpoints; camera permit costs Rs 100 and drones Rs 500.', 'no', 'Karnataka', 0, 1, '6:10 AM', '6:13 PM', 'Rs 20', 5, 5, 14.2281, 74.8107, 'Jog Falls, Sagar Taluk, Shivamogga, Karnataka', NULL, 1.0);

