INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 838000226, 'insert', 'bulk', 'Entry Rs 20 (Indian adult) / Rs 100 foreign / Rs 10 students is the post-May-2025 rate per StayVista and karnatakatourism.org; older sources list Rs 10-15. Distance conflict: sources say 72/100/115 km from Shivamogga — the road route via Sagar is ~100-110 km; noted as ~100-115 km. Coordinates from Meta location data (14.228139, 74.810691).', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000227, 838009, 'Kunchikal Falls', 'Kunchikal Falls', 'DAY TRIP (~98 km from Shivamogga). Formed by the Varahi River near Nidagodu village in the Masthikatte region of Hosanagara taluk, dropping about 455 metres — among the tallest tiered waterfalls in India. Flow is reduced outside the monsoon by the Mani Dam and underground powerhouse, so it is best seen June-September. It lies inside a restricted KPTCL area, so a gate pass/permission letter is required from the Masthikatte or Hosanagara office (or the Deputy Commissioner).', 'Half day', 'June to September, mornings', 'Secure the KPTCL permission a day ahead and go with a local guide — there are no signposted paths through the forest.', 'yes', 'Karnataka', 0, 0, '6:10 AM', '6:13 PM', 'Free', 4, 4, 13.76, 75.05, 'Near Masthikatte, Hosanagara Taluk, Shivamogga, Karnataka', NULL, 0.8);

