INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 838000227, 'insert', 'bulk', '''Tallest waterfall in India'' (455 m) is the commonly cited claim via World Waterfall Database; older sources say 600 ft/180 m — the 455 m figure is widely used but the falls are tiered, not a single plunge. Coordinates approximate (Masthikatte/Nidagodu area) — flag as approx. Entry itself is free; the permit is mandatory.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000228, 838009, 'Agumbe - Sunset View Point and Rainforest', 'Agumbe - Sunset View Point and Rainforest', 'DAY TRIP (~80 km from Shivamogga). A rainforest village in the Western Ghats among India''s wettest places (about 7,640 mm annual rainfall), called the ''Cherrapunji of the South''. The Sunset View Point on the ghat road offers a famed sunset over the Western Ghats and Arabian Sea. The Agumbe Rainforest Research Station is known for long-running king cobra research; nearby waterfalls include Barkana, Onake Abbi and Jogigundi. The TV series Malgudi Days was shot here.', 'Half day to full day', 'November to February, late afternoons', 'Stay for sunset but drive the ghat road carefully after dark; carry leech protection in monsoon; the research station needs advance booking.', 'no', 'Karnataka', 0, 1, '6:10 AM', '6:13 PM', NULL, 5, 5, 13.5121, 75.0862, 'Agumbe, Thirthahalli Taluk, Shivamogga, Karnataka 577411', NULL, 1.0);

