INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000234, 838009, 'Atithi Pure Vegetarian Family Restaurant', 'Atithi Pure Vegetarian Family Restaurant', 'A family-friendly pure-vegetarian restaurant in the Jewel Rock complex, Durgigudi, with traditional Indian decor. Specialises in dishes like paneer tikka, masala papad and dal tadka; about Rs 200-350 per person.', '1 hour', 'Lunch and dinner hours', 'A safe pick for a fully vegetarian family dinner in Durgigudi.', 'no', 'Karnataka', 0, 0, '6:10 AM', '6:13 PM', 'Rs 200-350 per person', 3, 3, 13.9315, 75.5698, 'Hotel Jewel Rock Complex, Durgigudi, Shivamogga, Karnataka 577201', NULL, 0.6);

