INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8380040, 838, 838009, 'Shivamogga Dasara', 'Sep-Oct', 'Dasara is celebrated every year in Shivamogga with cultural programmes across the city, marking the victory of good over evil during Navaratri-Vijayadashami.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8380041, 838, 838009, 'Mahashivaratri', 'Feb-Mar', 'A major festival at Shivamogga''s Shiva temples — notably the Keladi and Ikkeri temples — with night-long worship, abhisheka and large devotee gatherings.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8380042, 838, 838009, 'Marikamba Festival, Sagara', 'Feb-Mar (once every three years)', 'The Marikamba temple festival in Sagara town (about 75 km away), celebrated once every three years with a large temple-car procession, drawing devotees from across the district.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8380043, 838, 838009, 'Ganesh Chaturthi', 'Aug-Sep', 'Celebrated with enthusiasm across Shivamogga with Ganesha idols installed in homes and public pandals, prayers, cultural programmes and the final Visarjana procession.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8380044, 838, 838009, 'Makara Sankranti', 'Jan', 'Karnataka''s major harvest festival, observed in Shivamogga with kite flying, sesame-jaggery sweets (ellu-bella) and family gatherings.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8380045, 838, 838009, 'Sigandur Ashada Pooja', 'Jun-Jul', 'The major annual festival period at the Sigandur Chowdeshwari Temple, when thousands of devotees gather during Ashada; Navaratri is the other peak pilgrimage period.');

-- city: Beluru (id 1030)
INSERT OR IGNORE INTO cities (id, state_id, city_name, latitude, longitude) VALUES (838010, 838, 'Beluru', 13.16604, 75.86232);

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000235, 838010, 'Shri Chennakeshava Temple', 'Shri Chennakeshava Temple', 'Commissioned by Hoysala king Vishnuvardhana in 1117 CE after his victory over the Cholas at Talakad, this Vishnu temple took 103 years and three generations to complete. Built of soapstone on a star-shaped plan, it is famed for its bracket Madanika (celestial maiden) sculptures, the Darpana Sundari, and a once-rotatable Narasimha pillar. Inscribed in 2023 as part of the UNESCO World Heritage ''Sacred Ensembles of the Hoysalas''.', '2-3 hours', 'October to March, mornings or after 4 PM (stone floors get hot at midday)', 'Hire a local guide at the entrance to decode the sculptures; go early morning for the best light on the carvings.', 'no', 'Karnataka', 0, 0, '6:16 AM', '6:17 PM', 'Free', 5, 5, 13.16293, 75.86059, 'Chennakeshava Temple Complex, Temple Road, Belur, Karnataka 573115', NULL, 1.0);

