INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000236, 838010, 'Kappe Chennigaraya Temple', 'Kappe Chennigaraya Temple', 'Smaller 12th-century Vishnu shrine inside the Chennakeshava complex, built by Queen Shantala Devi, wife of Vishnuvardhana. It is regarded as a prototype or miniature of the main Chennakeshava shrine, simpler in plan but finely carved.', '30-45 minutes', 'October to March, mornings', 'Compare its simpler plan with the main shrine to see the Hoysala design evolution.', 'no', 'Karnataka', 0, 0, '6:16 AM', '6:17 PM', 'Free', 4, 4, 13.16275, 75.86075, 'Chennakeshava Temple Complex (east of main shrine), Temple Road, Belur, Karnataka 573115', NULL, 0.8);

