INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000237, 838010, 'Viranarayana Temple', 'Viranarayana Temple', 'Small but complete 12th-century temple west of the main shrine, measuring about 70 by 56 feet with a navaranga hall and sanctum. Its outer walls carry 59 large reliefs of Vishnu, Shiva, Brahma, Bhairava, Lakshmi, Parvati and Saraswati, including panels of the Bhima story from the Mahabharata.', '20-30 minutes', 'October to March, mornings', 'Look for the Bhima panels on the outer wall reliefs.', 'no', 'Karnataka', 0, 0, '6:16 AM', '6:17 PM', 'Free', 3, 4, 13.16295, 75.86035, 'Chennakeshava Temple Complex (west of main shrine), Temple Road, Belur, Karnataka 573115', NULL, 0.68);

