INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000238, 838010, 'Andal (Ranganayaki) Temple', 'Andal (Ranganayaki) Temple', '12th-century shrine northwest of the main temple, also called the Ranganayaki shrine and known as the Andal Temple. Its outer walls show elephants and nature motifs, and it displays 31 large images from Vaishnavism, Shaivism and Shaktism, including Venugopala, Mohini and Lakshmi, plus friezes of Puranic legends.', '20-30 minutes', 'October to March, mornings', 'Note the elephant friezes on the outer wall, unusual among the complex''s shrines.', 'no', 'Karnataka', 0, 0, '6:16 AM', '6:17 PM', 'Free', 3, 4, 13.1631, 75.86045, 'Chennakeshava Temple Complex (northwest of main shrine), Temple Road, Belur, Karnataka 573115', NULL, 0.68);

