INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000239, 838010, 'Soumyanayaki Temple', 'Soumyanayaki Temple', 'Small 12th-century shrine southwest of the main temple dedicated to Soumyanayaki, a form of Goddess Lakshmi, expanded in later centuries. Local tradition holds its tower is a miniature version of the great tower that once rose over the main Kesava shrine.', '15-20 minutes', 'October to March, mornings', 'Compare its miniature tower with the main shrine''s tower design.', 'no', 'Karnataka', 0, 0, '6:16 AM', '6:17 PM', 'Free', 3, 3, 13.1627, 75.8603, 'Chennakeshava Temple Complex (southwest of main shrine), Temple Road, Belur, Karnataka 573115', NULL, 0.6);

