INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000240, 838010, 'Vishnu Samudra Pushkarani', 'Vishnu Samudra Pushkarani', 'The temple''s large stepped tank, also called the Koneru or Vishnu Samudra, built in the time of Narasimha Raya. Under Krishnadevaraya, chief Basappa Naayaka of Utpatanahalli made its north end quadrangular, added steps on three sides, and built an island mandapa in the middle used for the float festival.', '20 minutes', 'October to March, mornings', 'Walk down the steps on three sides for close-up views of the island mandapa.', 'no', 'Karnataka', 0, 0, '6:16 AM', '6:17 PM', 'Free', 3, 3, 13.16255, 75.8607, 'Chennakeshava Temple Complex, Temple Road, Belur, Karnataka 573115', NULL, 0.6);

