INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000241, 838010, 'Deepa Sthambha and Garuda Sthambha', 'Deepa Sthambha and Garuda Sthambha', 'The complex''s two great free-standing pillars: the 42-ft Deepa Sthambha (Karthika Deepotsava lamp pillar) installed by Vijayanagara commander Bice Dandanayaka in King Devaraya''s reign, which balances on a flat platform by its own weight and is famed as the ''gravity pillar''; and the Garuda Sthambha facing the main shrine, erected by a Vijayanagara king.', '20 minutes', 'October to March, mornings', 'Stand back from the Deepa Sthambha to appreciate how it balances without mortar.', 'no', 'Karnataka', 0, 0, '6:16 AM', '6:17 PM', 'Free', 4, 4, 13.163, 75.8606, 'Chennakeshava Temple Complex courtyard, Temple Road, Belur, Karnataka 573115', NULL, 0.8);

