INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000242, 838010, 'Kalyana Mandapa and Vahana Mandapa', 'Kalyana Mandapa and Vahana Mandapa', 'Two pillared halls inside the Chennakeshava complex added in the 17th century: the Vahana Mandapa and the Kalyana Mandapa (marriage hall). They show the complex''s continued expansion under later rulers, centuries after the 12th-century shrines.', '15 minutes', 'October to March, mornings', 'Notice the contrast between these 17th-century halls and the 12th-century shrines.', 'no', 'Karnataka', 0, 0, '6:16 AM', '6:17 PM', 'Free', 2, 3, 13.16285, 75.86085, 'Chennakeshava Temple Complex, Temple Road, Belur, Karnataka 573115', NULL, 0.48);

