INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000243, 838010, 'Yagachi Dam', 'Yagachi Dam', 'Earthen gravity dam built in 2001 across the Yagachi river, a Kaveri tributary; 1280 m long and 26 m high, supplying irrigation and drinking water to Belur, Chikmagalur and Hassan districts. The reservoir and landscaped surroundings are a popular picnic and sunset spot, with a park beside the dam.', '1-3 hours', 'July to February (full reservoir), evenings for sunset', 'Visit in the evening for sunset photos over the backwaters; weekends get busy.', 'no', 'Karnataka', 0, 1, '6:16 AM', '6:17 PM', 'Rs 200 - Rs 600 (water sports rides)', 4, 4, 13.18143, 75.86937, '2.5 km from Belur Bus Stand, Hassan district, Karnataka', NULL, 0.8);

