INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000244, 838010, 'Yagachi Dam Park', 'Yagachi Dam Park', 'Landscaped park beside Yagachi Dam, about 2.5 km from Belur town, with lawns, viewpoints and walking paths overlooking the reservoir. A relaxed picnic and evening-stroll spot that pairs naturally with the dam viewpoint and the water sports centre in the backwaters.', '45-60 minutes', 'July to February, evenings', 'Combine with the dam viewpoint at sunset; carry drinking water as facilities are basic.', 'no', 'Karnataka', 0, 1, '6:16 AM', '6:17 PM', NULL, 2, 3, 13.1809, 75.8698, 'Yagachi Dam, near Belur, Hassan district, Karnataka', NULL, 0.48);

