INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000245, 838010, 'Yagachi Water Adventure Sports Centre', 'Yagachi Water Adventure Sports Centre', 'Water sports centre set up in the backwaters of Yagachi Dam to draw tourists to the Belur region. Offers banana boat rides, cruise boats, speed boats, kayaking and jet skiing with safety gear provided by staff.', '2-3 hours', 'July to February, mornings to avoid crowds', 'Combo packages for multiple rides usually save money; safety gear is provided.', 'no', 'Karnataka', 0, 1, '6:16 AM', '6:17 PM', 'Rs 200 - Rs 600 (rides)', 4, 4, 13.18898, 75.86689, 'Yagachi backwaters, near Belur, Hassan district, Karnataka', NULL, 0.8);

