INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000246, 838010, 'Lakshmi Devi Temple, Doddagaddavalli', 'Lakshmi Devi Temple, Doddagaddavalli', 'Built in 1113 CE by merchant Kullahana Rahuta and his wife Sahaja Devi under Vishnuvardhana, this is the first major Hoysala temple and the only surviving Chatuskuta (four-shrine) example. Its four shrines honour Mahalakshmi, Shiva (as Boothanatha), Vishnu and Kali under pyramidal Nagara towers, with a serene lake beside the compound. A living, ASI-protected temple, about 25 km southeast of Belur.', '1 hour', 'October to March, weekday mornings', 'Carry a flashlight to appreciate the intricately carved ceilings; there is no food at the site, so eat in Hassan or Belur.', 'no', 'Karnataka', 0, 0, '6:16 AM', '6:17 PM', 'Free', 4, 5, 13.095, 76.0025, 'Doddagaddavalli, Karnataka 573216 (off Hassan-Belur highway, NH 373)', NULL, 0.88);

