INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000247, 838010, 'Belur Temple Street Market', 'Belur Temple Street Market', 'The busy market street leading to the Chennakeshava Temple, lined with shops selling souvenirs, sandalwood items, brassware and panchaloha (five-metal) deity statues. During the annual Rathotsava it hosts a 10-day jatre fair with food and craft stalls.', '30-60 minutes', 'October to March, evenings', 'Bargain politely; the panchaloha statues make distinctive souvenirs.', 'no', 'Karnataka', 0, 0, '6:16 AM', '6:17 PM', NULL, 2, 3, 13.164, 75.8625, 'Temple Road, Belur, Karnataka 573115', NULL, 0.48);

