INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000248, 838010, 'Gorur Dam (Hemavathi Dam)', 'Gorur Dam (Hemavathi Dam)', 'Dam across the Hemavathi river about 35 km southeast of Belur (25 km from Hassan), forming the Hemavathi Reservoir. A long-standing picnic spot known for sunset views over the backwaters; best in monsoon when the gates open. The ancient Yoganarasimha temple in Gorur village stands by the river nearby.', '1-2 hours', 'June to September (gates open), evenings for sunset', 'Combine with the Yoganarasimha temple in Gorur village, about 2 km away.', 'no', 'Karnataka', 0, 1, '6:16 AM', '6:17 PM', 'Free', 2, 3, 12.82307, 76.0566, 'Gorur, Hassan district, Karnataka', NULL, 0.48);

