INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 838000248, 'insert', 'bulk', 'Geocoded at 12.82307, 76.0566 (relevance 70, Hemavathi Dam, Hassan). ~35 km from Belur; included as a regional outing with distance noted in summary. Access to the dam wall may be restricted; viewpoint below the dam per travel guides. No official website -> null.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000249, 838010, 'Hoysaleswara Temple, Halebidu', 'Hoysaleswara Temple, Halebidu', 'The great twin Shiva temples (Hoysaleswara and Shantaleswara) of Halebidu, former Hoysala capital Dwarasamudra. Begun around 1121 CE under Vishnuvardhana and completed around 1160 CE, the soapstone walls carry endless friezes of deities, Ramayana-Mahabharata scenes and animals; the twin Nandi mandapas hold two of India''s largest Nandi statues. Inscribed 2023 in the UNESCO ''Sacred Ensembles of the Hoysalas''.', '2-3 hours', 'October to March; early morning or late afternoon for raking light on carvings', 'Visit at dawn or dusk when low light rakes across the soapstone carvings.', 'no', 'Karnataka', 0, 0, '6:16 AM', '6:17 PM', 'Free', 5, 5, 13.21198, 75.99419, 'Halebidu, Belur taluk, Hassan district, Karnataka 573121 (16 km from Belur)', NULL, 1.0);

