INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000250, 838010, 'Kedareshwara Temple, Halebidu', 'Kedareshwara Temple, Halebidu', 'Shiva temple built in 1219 CE by Hoysala king Veera Ballala II and his queen Abhinava Ketala Devi, a short walk from the Hoysaleswara Temple. Left unfinished, it stands more as a evocative ruin than a complete temple, with Chalukyan-style stone carvings of mythological scenes.', '30-45 minutes', 'October to March, mornings', 'Pair with the Hoysaleswara Temple and Basadi Halli in one Halebidu circuit.', 'no', 'Karnataka', 0, 0, '6:16 AM', '6:17 PM', 'Free', 3, 4, 13.20903, 75.99858, 'Halebidu, Belur taluk, Hassan district, Karnataka 573121', NULL, 0.68);

