INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000251, 838010, 'Basadi Halli (Jain Basadis), Halebidu', 'Basadi Halli (Jain Basadis), Halebidu', 'Cluster of three 12th-century Jain temples between the Hoysaleswara and Kedareshwara temples: Adinatha, Parshwanatha (with a 14-ft black-stone idol sheltered by a seven-headed serpent) and Shanthinatha. Noted for mirror-polished pillars and serene carvings reflecting Jain philosophy, with old monasteries nearby.', '45-60 minutes', 'October to March, mornings', 'Remove footwear before entering the basadis; the polished pillars are worth a close look.', 'no', 'Karnataka', 0, 0, '6:16 AM', '6:17 PM', 'Free', 4, 4, 13.2105, 75.9964, 'Basadi Halli, Halebidu, Belur taluk, Hassan district, Karnataka 573121', NULL, 0.8);

