INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 838000251, 'insert', 'bulk', 'Geocoder only returned district-level match -> coords interpolated between Hoysaleswara (13.21198, 75.99419) and Kedareshwara (13.20903, 75.99858) per nativeplanet''s ''between'' description; approximate. Real site with 3 named basadis. No official website -> null.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000252, 838010, 'Halebidu Archaeological Museum', 'Halebidu Archaeological Museum', 'ASI site museum established in the early 1970s, about 0.5 km from the Hoysaleswara Temple, holding over 1500 sculptures and inscriptions recovered around Halebidu. Displays span closed galleries and an open-air reserve collection, including an 18-ft Tirthankara image, Govardhanagiridhari Krishna, Dancing Shiva, Nataraja and Veena Saraswati, mostly 12th-13th century.', '45-60 minutes', 'October to March, midday (pairs with temple visit)', 'Visit between the two temples; photography may be restricted inside galleries.', 'no', 'Karnataka', 0, 0, '6:16 AM', '6:17 PM', 'Rs 5', 3, 4, 13.213, 75.9945, 'Opposite Hoysaleswara Temple, Halebidu, Karnataka 573121', NULL, 0.68);

