INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000253, 838010, 'Veera Narayana Temple, Belavadi', 'Veera Narayana Temple, Belavadi', 'One of the largest Hoysala temples, built in the 13th century by Veera Ballala II and dedicated to Vishnu in three forms: Veera Narayana (east), Venugopala (north) and Yoga Narasimha (south) in a trikuta layout around a vast pillared hall. Legend says this is where Bhima slew the demon Bakasura; carved elephants flank the entrance and the ceilings show Krishna legends. Free entry; blissfully uncrowded.', '1-2 hours', 'September to March, mornings', 'Go in the morning; the inner sanctum can close in the afternoon, and the priest can share the Bakasura legend.', 'no', 'Karnataka', 0, 0, '6:16 AM', '6:17 PM', 'Free', 4, 5, 13.2822, 75.9983, 'Belavadi, Chikkamagaluru district, Karnataka 577146 (11 km from Halebidu, ~27 km from Belur)', NULL, 0.88);

