INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (838000254, 838010, 'Gommateshwara Statue, Shravanabelagola', 'Gommateshwara Statue, Shravanabelagola', 'The 57-ft monolithic statue of Bahubali (Gommateshwara) atop Vindhyagiri hill, carved in 981 CE under the Western Gangas and among the world''s tallest free-standing stone statues. Reaching it means a barefoot climb of about 600-650 steps; the hilltop also holds Jain basadis and panoramic views. Entry is free; the Mahamastakabhisheka anointing is held every 12 years (next 2030).', '2-3 hours', 'October to March; climb early morning or late afternoon to avoid midday heat', 'Climb barefoot (shoe stand at base); carry water, there is no shade on the steps. Doli (palanquin) service is available for those who cannot climb.', 'no', 'Karnataka', 0, 1, '6:16 AM', '6:17 PM', 'Free', 5, 5, 12.85521, 76.48527, 'Vindhyagiri Hill, Shravanabelagola, Karnataka 573135 (~80 km from Belur)', NULL, 1.0);

