INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8380046, 838, 838010, 'Belur Chennakeshava Rathotsava', 'Mar-Apr', 'Annual car festival of the Chennakeshava Temple, held about 12 days after Ugadi. The Utsava Murti rides a huge wooden chariot for two days (eastern streets on day one, the rest on day two), with a 10-day jatre fair around the temple.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8380047, 838, 838010, 'Hoysala Mahotsava', 'Mar-Apr', 'Karnataka tourism''s annual cultural festival celebrating Hoysala heritage at Belur and Halebidu, with classical dance and music performances staged near the temples.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8380048, 838, 838010, 'Maha Shivaratri', 'Feb-Mar', 'Night-long Shiva worship observed with special fervour at the Hoysaleswara Temple in Halebidu; devotees also gather at Belur''s temples.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8380049, 838, 838010, 'Dasara', 'Sep-Oct', 'Nine-night festival; notably the famous annual festival of the Lakshmi Devi Temple at Doddagaddavalli, and celebrated across Belur''s temples with special pujas.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8380050, 838, 838010, 'Deepavali', 'Oct-Nov', 'Festival of lights; the Chennakeshava Temple complex and town are lit with oil lamps and the Deepa Sthambha is illuminated.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8380051, 838, 838010, 'Mahamastakabhisheka', 'Feb (every 12 years)', 'Grand anointing of the 57-ft Gommateshwara statue at Shravanabelagola with milk, saffron, sandalwood paste and other offerings; draws lakhs of devotees. Last held in 2018, next expected in 2030.');

