INSERT OR IGNORE INTO photos (id, place_id, source_file, thumbnail_url, thumbnail_width, thumbnail_height, photo_title, photo_author, license, license_url, source_url, credit, usage_terms, description) VALUES (838800162, 838000235, 'File:Shri Chennakeshava Temple Belur.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/57/Shri_Chennakeshava_Temple_Belur.jpg/960px-Shri_Chennakeshava_Temple_Belur.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 800, 1067, 'Shri Chennakeshava Temple Belur', 'Prachikittu', 'CC-BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 'https://commons.wikimedia.org/wiki/File:Shri_Chennakeshava_Temple_Belur.jpg', 'Own work', 'Creative Commons Attribution-Share Alike 4.0', 'The Shri Chennakeshava Temple of Belur is a 12th century temple of Lord Vishnu in Hassan district, 200 kms from Bengaluru. It was built in 1163 A.D. by a minister of Hoysala. It has beautiful carving over the stone that depict different stories from Ramayana, Mahabharata and Puranas. It has been proposed to be listed under UNESCO World Heritage Sites.');

INSERT OR IGNORE INTO photos (id, place_id, source_file, thumbnail_url, thumbnail_width, thumbnail_height, photo_title, photo_author, license, license_url, source_url, credit, usage_terms, description) VALUES (838800163, 838000236, 'File:Kappe-Chennigraya Temple (East entrance), Chennakesava Temple complex, Belur 03.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/45/Kappe-Chennigraya_Temple_%28East_entrance%29%2C_Chennakesava_Temple_complex%2C_Belur_03.jpg/960px-Kappe-Chennigraya_Temple_%28East_entrance%29%2C_Chennakesava_Temple_complex%2C_Belur_03.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 800, 534, 'Kappe-Chennigraya Temple (East entrance), Chennakesava Temple complex, Belur 03', 'Rohit14400', 'CC-BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 'https://commons.wikimedia.org/wiki/File:Kappe-Chennigraya_Temple_(East_entrance),_Chennakesava_Temple_complex,_Belur_03.jpg', 'Own work', 'Creative Commons Attribution-Share Alike 4.0', 'The Kappe Chennigraya Temple is located within the Chennakesava Temple complex. Built in the Hoysala architectural style, it was commissioned by Shantaladevi, the queen of King Vishnuvardhana, in the 12th century. The temple is dedicated to Lord Vishnu and houses a beautifully sculpted deity of Kappe Chennigraya.');

INSERT OR IGNORE INTO photos (id, place_id, source_file, thumbnail_url, thumbnail_width, thumbnail_height, photo_title, photo_author, license, license_url, source_url, credit, usage_terms, description) VALUES (838800164, 838000238, 'File:Andal Ranganayaki shrine inside Belur Hindu temples complex Karnataka India.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/39/Andal_Ranganayaki_shrine_inside_Belur_Hindu_temples_complex_Karnataka_India.jpg/960px-Andal_Ranganayaki_shrine_inside_Belur_Hindu_temples_complex_Karnataka_India.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 800, 1067, 'Andal Ranganayaki shrine inside Belur Hindu temples complex Karnataka India', 'Ms Sarah Welch', 'CC-BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 'https://commons.wikimedia.org/wiki/File:Andal_Ranganayaki_shrine_inside_Belur_Hindu_temples_complex_Karnataka_India.jpg', 'Own work', 'Creative Commons Attribution-Share Alike 4.0', 'The Ranganayaki shrine is a Hindu temple in the Vaishnavism tradition. It is in the northwest corner of the temples complex with intricate carvings of Vedic and Puranic legends.');

INSERT OR IGNORE INTO photos (id, place_id, source_file, thumbnail_url, thumbnail_width, thumbnail_height, photo_title, photo_author, license, license_url, source_url, credit, usage_terms, description) VALUES (838800165, 838000239, 'File:Soumyanayaki shrine at the Chennakeshava temple complex in Belur,Karnataka.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0f/Soumyanayaki_shrine_at_the_Chennakeshava_temple_complex_in_Belur%2CKarnataka.jpg/960px-Soumyanayaki_shrine_at_the_Chennakeshava_temple_complex_in_Belur%2CKarnataka.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 800, 572, 'Soumyanayaki shrine at the Chennakeshava temple complex in Belur,Karnataka', 'Swaminathan Natarajan', 'CC-BY-SA 3.0', 'https://creativecommons.org/licenses/by-sa/3.0', 'https://commons.wikimedia.org/wiki/File:Soumyanayaki_shrine_at_the_Chennakeshava_temple_complex_in_Belur,Karnataka.jpg', 'Own work', 'Creative Commons Attribution-Share Alike 3.0', 'This is a photo of ASI monument number');

INSERT OR IGNORE INTO photos (id, place_id, source_file, thumbnail_url, thumbnail_width, thumbnail_height, photo_title, photo_author, license, license_url, source_url, credit, usage_terms, description) VALUES (838800166, 838000240, 'File:Kalyani (stepped water tank), Chennakeshava Temple complex, Belur 01.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/13/Kalyani_%28stepped_water_tank%29%2C_Chennakeshava_Temple_complex%2C_Belur_01.jpg/960px-Kalyani_%28stepped_water_tank%29%2C_Chennakeshava_Temple_complex%2C_Belur_01.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 800, 534, 'Kalyani (stepped water tank), Chennakeshava Temple complex, Belur 01', 'Rohit14400', 'CC-BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 'https://commons.wikimedia.org/wiki/File:Kalyani_(stepped_water_tank),_Chennakeshava_Temple_complex,_Belur_01.jpg', 'Own work', 'Creative Commons Attribution-Share Alike 4.0', 'A stepped water tank, referred to as the Kalyani or Vasudeva-sarovara is located in the northeast corner of the Chennakeshava Temple complex, is accompanied by two smaller shrines and a single main entrance, along with two stone elephants on its side.');

INSERT OR IGNORE INTO photos (id, place_id, source_file, thumbnail_url, thumbnail_width, thumbnail_height, photo_title, photo_author, license, license_url, source_url, credit, usage_terms, description) VALUES (838800167, 838000241, 'File:Garuda Stambha (Pillar) at Chennakeshava Temple, Belur, Karnataka.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/65/Garuda_Stambha_%28Pillar%29_at_Chennakeshava_Temple%2C_Belur%2C_Karnataka.jpg/960px-Garuda_Stambha_%28Pillar%29_at_Chennakeshava_Temple%2C_Belur%2C_Karnataka.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 800, 1200, 'Garuda Stambha (Pillar) at Chennakeshava Temple, Belur, Karnataka', 'Shashank Mehendale', 'CC-BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 'https://commons.wikimedia.org/wiki/File:Garuda_Stambha_(Pillar)_at_Chennakeshava_Temple,_Belur,_Karnataka.jpg', 'Own work', 'Creative Commons Attribution-Share Alike 4.0', 'A low angle view of the Garuda stambha (pillar) with Gopura (tower over entrance) in the background at Chennakeshava temple complex.The Chennakeshava Temple, also referred to as Keshava, Kesava or Vijayanarayana Temple of Belur, is a 12th century Hindu temple in the Hassan district of Karnataka.');

INSERT OR IGNORE INTO photos (id, place_id, source_file, thumbnail_url, thumbnail_width, thumbnail_height, photo_title, photo_author, license, license_url, source_url, credit, usage_terms, description) VALUES (838800168, 838000242, 'File:Pillar with inscription at base in mandapa at the rear.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7b/Pillar_with_inscription_at_base_in_mandapa_at_the_rear.jpg/960px-Pillar_with_inscription_at_base_in_mandapa_at_the_rear.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 800, 1735, 'Pillar with inscription at base in mandapa at the rear', 'Cvijayram', 'CC-BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 'https://commons.wikimedia.org/wiki/File:Pillar_with_inscription_at_base_in_mandapa_at_the_rear.jpg', 'Own work', 'Creative Commons Attribution-Share Alike 4.0', 'Pillar in the vahana mandapa (pavilion) at Chennakesava Temple in Belur, India');

