INSERT OR IGNORE INTO photos (id, place_id, source_file, thumbnail_url, thumbnail_width, thumbnail_height, photo_title, photo_author, license, license_url, source_url, credit, usage_terms, description) VALUES (838800171, 838000246, 'File:Doddagaddavalli Lakshmi temple , Karnataka.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d7/Doddagaddavalli_Lakshmi_temple_%2C_Karnataka.jpg/960px-Doddagaddavalli_Lakshmi_temple_%2C_Karnataka.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 800, 556, 'Doddagaddavalli Lakshmi temple , Karnataka', 'SpeakingArch', 'CC-BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 'https://commons.wikimedia.org/wiki/File:Doddagaddavalli_Lakshmi_temple_,_Karnataka.jpg', 'Own work', 'Creative Commons Attribution-Share Alike 4.0', 'The temple predates Beluru and Halebidu temple and doesn''t have the signature hoysala platform. This is a Chatushkuta temple, which means this temple has four garbhagrihas or sanctum sanctorums.The Lakshmi Devi temple, was built by the Hoysala Empire King Vishnuvardhana in 1114 CE.');

