INSERT OR IGNORE INTO photos (id, place_id, source_file, thumbnail_url, thumbnail_width, thumbnail_height, photo_title, photo_author, license, license_url, source_url, credit, usage_terms, description) VALUES (838800173, 838000249, 'File:Hoysaleswara Temple, Halebidu bhvrvb2k23 (1088).jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/08/Hoysaleswara_Temple%2C_Halebidu_bhvrvb2k23_%281088%29.jpg/960px-Hoysaleswara_Temple%2C_Halebidu_bhvrvb2k23_%281088%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 800, 1067, 'Hoysaleswara Temple, Halebidu bhvrvb2k23 (1088)', 'Vinayaraj', 'CC-BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 'https://commons.wikimedia.org/wiki/File:Hoysaleswara_Temple,_Halebidu_bhvrvb2k23_(1088).jpg', 'Own work', 'Creative Commons Attribution-Share Alike 4.0', 'Belur, Halebidu 2023 January');

INSERT OR IGNORE INTO photos (id, place_id, source_file, thumbnail_url, thumbnail_width, thumbnail_height, photo_title, photo_author, license, license_url, source_url, credit, usage_terms, description) VALUES (838800174, 838000250, 'File:Halebidu temple.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/79/Halebidu_temple.jpg/960px-Halebidu_temple.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 800, 593, 'Halebidu temple', 'Shravan Kamath94', 'CC-BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 'https://commons.wikimedia.org/wiki/File:Halebidu_temple.jpg', 'Own work', 'Creative Commons Attribution-Share Alike 4.0', 'Another beautiful temple built during Hoysala rule in karnataka. Halebidu Kedareshwara temple is renowned for its beautiful carvings and critical spell bounding architectural work. undoubtedly it can be one of the best places to visit for history lovers and architecture admirers.');

INSERT OR IGNORE INTO photos (id, place_id, source_file, thumbnail_url, thumbnail_width, thumbnail_height, photo_title, photo_author, license, license_url, source_url, credit, usage_terms, description) VALUES (838800175, 838000251, 'File:Adinatha temple Basadi Halli.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b5/Adinatha_temple_Basadi_Halli.jpg/960px-Adinatha_temple_Basadi_Halli.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 800, 558, 'Adinatha temple Basadi Halli', 'Lvenkat', 'CC-BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 'https://commons.wikimedia.org/wiki/File:Adinatha_temple_Basadi_Halli.jpg', 'Own work', 'Creative Commons Attribution-Share Alike 4.0', 'The Jains had a prominent presence in the Belur -Halledbedu- Shravanabelgola area of Karnataka. This is an Adinatha temple close to the Hoysaleshwara Temple in Hallebedu');

