INSERT OR IGNORE INTO photos (id, place_id, source_file, thumbnail_url, thumbnail_width, thumbnail_height, photo_title, photo_author, license, license_url, source_url, credit, usage_terms, description) VALUES (838800178, 838000254, 'File:The Gommateshwara Statue, Shravanabelagola 01.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ab/The_Gommateshwara_Statue%2C_Shravanabelagola_01.jpg/960px-The_Gommateshwara_Statue%2C_Shravanabelagola_01.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 800, 1199, 'The Gommateshwara Statue, Shravanabelagola 01', 'Rohit14400', 'CC-BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 'https://commons.wikimedia.org/wiki/File:The_Gommateshwara_Statue,_Shravanabelagola_01.jpg', 'Own work', 'Creative Commons Attribution-Share Alike 4.0', 'The Gommateshwara Statue, located in Shravanabelagola, Karnataka, is a 57-foot-tall monolithic statue of Lord Bahubali, a revered Jain figure. Erected around 983 CE, it is one of the world''s largest free-standing statues.');


