INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8400001, 840, 840001, 'Cochin Carnival', 'Dec-Jan', 'Fort Kochi''s famous year-end carnival (Dec 23/24 - Jan 1): decorated floats, folk performances, beach games, and the midnight burning of the Pappanji effigy on Dec 31 followed by a grand procession on Jan 1.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8400002, 840, 840001, 'Kochi-Muziris Biennale', 'Dec-Mar', 'India''s largest international contemporary art biennale, held across Fort Kochi and Mattancherry venues (principal venue Aspinwall House). Biennial; the 6th edition ran Dec 12, 2025 - Mar 31, 2026.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8400003, 840, 840001, 'Onam (Thiruvonam)', 'Aug-Sep', 'Kerala''s harvest festival celebrated across Kochi with Onam sadhya feasts, pookalam flower carpets, boat races and cultural programmes; the Athachamayam procession at Thripunithura marks its start.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8400004, 840, 840001, 'Athachamayam', 'Aug-Sep', 'Colourful procession at Thripunithura heralding the start of Onam: caparisoned elephants, panchavadyam percussion, folk art forms and floats through the town.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8400005, 840, 840001, 'Ernakulathappan Utsavam', 'Jan-Feb', 'Eight-day annual festival of the Ernakulam Shiva Temple in the Malayalam month of Makaram: kodiyettam flag hoisting, Pakalpooram with caparisoned elephants and panchavadyam, temple arts, and the Arattu holy-bath procession to Durbar Hall Ground.');

-- city: Thiruvananthapuram (id 1042)
INSERT OR IGNORE INTO cities (id, state_id, city_name, latitude, longitude) VALUES (840002, 840, 'Thiruvananthapuram', 8.5241, 76.9366);

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000027, 840002, 'Sree Padmanabhaswamy Temple', 'Sree Padmanabhaswamy Temple', 'One of India''s richest and most sacred temples, dedicated to Lord Vishnu in the Anantha Shayana posture, at East Fort. The Dravidian-Kerala style gopuram and temple complex are the spiritual heart of Thiruvananthapuram. Famous for its immense vaulted treasures; non-Hindus are not allowed in the inner sanctum. Strict dress code (dhoti for men, saree for women), no phones/cameras.', '2-3 hours', 'October to March', 'Join the early-morning darshan (from 3:30 AM) to avoid crowds; men must wear mundu/dhoti and remove shirts, women must wear saree. Foreign/non-Hindu visitors may only enter the outer corridors.', 'Darshan is free at the counter; special darshan can be booked online in advance', 'Kerala', 0, 0, NULL, NULL, 'Free (general darshan); Rs 150 special darshan (Rs 180 with prasadam)', 5.0, 4.0, 8.4824, 76.9434, 'East Fort, Thiruvananthapuram, Kerala 695023, India', 'https://booking.sreepadmanabhaswamytemple.org/', 0.92);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (840000027, 840000027, '3:30 AM - 12:00 PM, 5:00 PM - 7:20 PM', '3:30 AM - 12:00 PM, 5:00 PM - 7:20 PM', '3:30 AM - 12:00 PM, 5:00 PM - 7:20 PM', '3:30 AM - 12:00 PM, 5:00 PM - 7:20 PM', '3:30 AM - 12:00 PM, 5:00 PM - 7:20 PM', '3:30 AM - 12:00 PM, 5:00 PM - 7:20 PM', '3:30 AM - 12:00 PM, 5:00 PM - 7:20 PM', 'Darshan is slot-wise through the day per temple booking portal; timings cross-checked across theindia.co.in, tirumalaonline.in, bharattravelguru.com');

