INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000028, 840002, 'Napier Museum', 'Napier Museum', 'Kerala''s premier art and natural history museum, housed in a striking 19th-century Indo-Saracenic building in the Trivandrum Museum compound. Collections include Travancore royal artefacts, bronze idols, ancient ornaments, ivory carvings and musical instruments; shares the campus with the zoo and Sri Chitra Art Gallery.', '1-2 hours', 'October to March', 'Combine with the adjacent zoo and Sri Chitra Art Gallery in one museum-compound visit; closed on Mondays.', 'Not required; tickets at counter', 'Kerala', 0, 0, NULL, NULL, 'Rs 20 (adult)', 4.5, 4.0, 8.50971, 76.95463, 'Napier Museum Road, Museum, Palayam, Thiruvananthapuram, Kerala 695033, India', NULL, 0.86);

