INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000029, 840002, 'Thiruvananthapuram Zoo', 'Thiruvananthapuram Zoo', 'One of India''s oldest zoos (est. 1859), spread over 55 acres of wooded parkland inside the Museum compound. Home to elephants, tigers, lions, giraffes, hippos and a snake house; a favourite family outing, often combined with Napier Museum.', '2-3 hours', 'October to March, mornings', 'Arrive early morning when animals are most active; wear walking shoes as the campus is large. Closed on Mondays.', 'Not required; tickets at counter', 'Kerala', 0, 0, NULL, NULL, 'Rs 20 (adult), Rs 5 (child 5-12)', 4.0, 4.0, 8.5084, 76.9562, 'Museum Compound, Palayam, Thiruvananthapuram, Kerala 695033, India', NULL, 0.8);

