INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000030, 840002, 'Kuthiramalika Palace', 'Kuthiramalika Palace', 'The ''Mansion of Horses'' - a 19th-century palace built by the poet-king Swathi Thirunal next to the Padmanabhaswamy Temple at East Fort. Famous for its carved wooden horse brackets, ivory cots, Kathakali mannequins and the musical tree that reproduces the seven swaras. The courtyard hosts the annual Swathi Sangeethotsavam music festival in January.', '1-2 hours', 'October to March', 'Visits are guided-tour only; arrive before the 1 PM break. No photography inside.', 'Not required; tickets at counter', 'Kerala', 0, 0, NULL, NULL, 'Rs 50 (Indian adult), Rs 150 (foreign adult)', 4.5, 4.0, 8.48061, 76.9426, 'Kuthiramalika Palace Museum, E Fort Road, East Fort, Thiruvananthapuram, Kerala 695023, India', NULL, 0.86);

