INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000031, 840002, 'Priyadarshini Planetarium', 'Priyadarshini Planetarium', 'The planetarium of the Kerala State Science & Technology Museum (est. 1984) at PMG, Palayam. Sky-theatre shows in Malayalam and English on the universe and astronomy, plus museum galleries, 3D theatre and children''s park on the campus - a solid educational stop for families.', '2 hours', 'Year-round', 'Check the daily show schedule on arrival; the 12 noon English show suits most visitors. Closed on Mondays.', 'Not required; tickets at counter', 'Kerala', 0, 0, NULL, NULL, 'Rs 60', 3.5, 4.0, 8.50929, 76.94984, 'Kerala State Science & Technology Museum, Division Office Road, PMG, Palayam, Thiruvananthapuram, Kerala 695033, India', 'https://www.kstmuseum.com/', 0.74);

