INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000032, 840002, 'Attukal Bhagavathy Temple', 'Attukal Bhagavathy Temple', 'One of Kerala''s most famous Devi temples, dedicated to Goddess Bhagavathy (Bhadrakali/Kannaki), known as the ''Sabarimala of women''. Its architecture blends traditional Tamil and Kerala styles with carvings of Kali, Parvati, Shiva and the Dashavataram. Hosts the annual Attukal Pongala - the world''s largest women''s gathering (Guinness record).', '1-2 hours', 'October to March; Feb-Mar for Attukal Pongala', 'Visit early morning for peaceful darshan; during Pongala (Feb-Mar) the area is extremely crowded and streets fill with cooking hearths.', 'Not required; free darshan', 'Kerala', 0, 0, NULL, NULL, 'Free', 4.5, 4.0, 8.46839, 76.95422, 'Attukal Road, Attukal, Manacaud, Thiruvananthapuram, Kerala 695009, India', 'https://attukal.org/', 0.86);

