INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000033, 840002, 'Veli Tourist Village', 'Veli Tourist Village', 'A popular lakeside park at the confluence of Veli Lake and the Arabian Sea, near the airport. Lawns, pedal boating on the lake, a floating restaurant and sunset views make it a favourite evening spot for families; boating operates 10 AM-5 PM.', '2 hours', 'October to March, evenings', 'Go at sunset for the best views across the lake to the sea; take the pedal boats earlier in the day.', 'Not required; tickets at counter', 'Kerala', 0, 1, NULL, '18:20', 'Rs 5 (above 14 years)', 3.5, 4.0, 8.51001, 76.8896, 'Kochuveli, Thiruvananthapuram, Kerala 695021, India', NULL, 0.74);

