INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000034, 840002, 'Sri Chitra Art Gallery', 'Sri Chitra Art Gallery', 'A gem of the Museum compound showcasing the paintings of Raja Ravi Varma, works of the Roerich family, Mughal and Tanjore miniatures and modern Indian art. Named after the Travancore king who founded it; a must for art lovers visiting the Napier Museum campus.', '1 hour', 'October to March', 'Combine with Napier Museum and the zoo in one trip; the Raja Ravi Varma collection is the highlight. Closed on Mondays.', 'Not required; tickets at counter', 'Kerala', 0, 0, NULL, NULL, 'Rs 25 (adult), Rs 10 (child)', 4.0, 4.0, 8.510843, 76.955273, 'Museum Compound, Palayam, Thiruvananthapuram, Kerala 695033, India', NULL, 0.8);

