INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000035, 840002, 'Shanghumukham Beach', 'Shanghumukham Beach', 'The city beach near the airport, famous for the 35-metre Jalakanyaka (mermaid) sculpture by Kanai Kunhiraman rising from the sand. A relaxed evening spot for sunsets and strolls; swimming is not recommended due to strong currents. The Padmanabhaswamy Temple''s Aarattu procession ends here twice a year.', '1-2 hours', 'October to March, evenings', 'Best at sunset; admire the giant mermaid sculpture. Do not swim - the currents are dangerous.', 'Not required', 'Kerala', 0, 1, NULL, '18:20', 'Free', 4.0, 4.5, 8.47866, 76.91263, 'Airport Road, Vallakadavu, Thiruvananthapuram, Kerala 695008, India', NULL, 0.84);

