INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000037, 840002, 'Thiruvallam Parasurama Temple', 'Thiruvallam Parasurama Temple', 'Kerala''s only Parasurama temple, on the banks of the Karamana River at Thiruvallam. A protected monument under the Kerala Archaeology department, famed for Bali Tharpanam ancestor rites performed on its river ghats - especially crowded during Karkidaka Vavu. The centuries-old Kerala-style architecture is a draw for heritage lovers.', '1-2 hours', 'October to March', 'Combine with a riverside stop; the temple is busiest during Karkidaka Vavu (July-Aug) when Bali Tharpanam rites are performed.', 'Not required; free darshan', 'Kerala', 0, 0, NULL, NULL, 'Free', 3.5, 4.0, 8.4408, 76.95557, 'Thiruvallam, Thiruvananthapuram, Kerala 695027, India', NULL, 0.74);

