INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000038, 840002, 'Vizhinjam Marine Aquarium (Sagarika)', 'Vizhinjam Marine Aquarium (Sagarika)', 'A compact marine aquarium at Vizhinjam harbour, south of the city, showcasing reef fishes, eels, turtles and other Arabian Sea marine life in large tanks. A quick, affordable family stop near the Vizhinjam lighthouse area.', '1 hour', 'October to March', 'Combine with a visit to Vizhinjam lighthouse and harbour; the aquarium is small so an hour suffices.', 'Not required; tickets at counter', 'Kerala', 0, 0, NULL, NULL, 'Rs 20 (adult), Rs 10 (child below 14)', 3.0, 3.5, 8.383573, 76.983443, 'Near Light House Road, Vizhinjam Harbour Road, Vizhinjam, Thiruvananthapuram, Kerala 695521, India', NULL, 0.64);

