INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000039, 840002, 'Chalai Market', 'Chalai Market', 'One of Kerala''s oldest bazaars, established in the late 18th century by Raja Kesavadas, Dewan of Travancore. A dense, atmospheric market street near East Fort selling textiles, spices, vessels, gold and everyday goods - the best place in the city to shop like a local.', '1-2 hours', 'October to March, mornings', 'Go in the morning for the liveliest atmosphere; bargain politely. Pair with a walk through East Fort and the Padmanabhaswamy Temple outer area.', 'Not required', 'Kerala', 0, 0, NULL, NULL, 'Free', 3.5, 4.0, 8.48222, 76.95278, 'Chalai, East Fort, Thiruvananthapuram, Kerala 695036, India', NULL, 0.74);

