INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000040, 840002, 'Magic Planet Theme Park', 'Magic Planet Theme Park', 'The world''s first magic-themed park, founded by magician Gopinath Muthukad at the KINFRA Film & Video Park, Kazhakootam. Magic shows, street magic, illusion exhibits and a science-fiction zone, performed in part by differently-abled artists; a unique family attraction with a social mission.', '4-5 hours', 'October to March', 'Plan for a half day and catch the main stage magic shows; the ticket includes food. Closed on Mondays.', 'Not required; tickets at counter', 'Kerala', 0, 0, NULL, NULL, 'Rs 700 per person (including food)', 3.5, 4.5, 8.58066, 76.87791, 'KINFRA Film & Video Park, Kazhakootam, Thiruvananthapuram, Kerala 695585, India', NULL, 0.78);

