INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000041, 840002, 'Kovalam Beach', 'Kovalam Beach', 'Kerala''s most famous beach, 16 km south of the city - three crescent coves (Lighthouse Beach, Hawa Beach, Samudra Beach) with golden sand, surf and shacks. The 1972 red-and-white Vizhinjam Lighthouse (36 m) offers panoramic views; one of India''s classic beach destinations.', 'Half day', 'October to March', 'Climb the Vizhinjam Lighthouse for the best view; stay for sunset on Lighthouse Beach. Lifeguarded zones are safest for swimming.', 'Not required', 'Kerala', 0, 1, NULL, '18:20', 'Free', 5.0, 4.5, 8.387273, 76.976649, 'Kovalam, Thiruvananthapuram, Kerala 695527, India', NULL, 0.96);

