INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000042, 840002, 'Poovar Island', 'Poovar Island', 'A serene estuary island ~30-36 km south of the city where the Neyyar River, backwaters and the Arabian Sea meet. Reached only by boat from the Poovar jetty; floating cottages, golden beach and backwater cruises make it a romantic half-day or overnight escape.', '3-4 hours', 'October to March', 'Take the backwater boat from Poovar jetty to the island - the island itself has no car access. Morning cruises are calmest.', 'Not required; boats at jetty', 'Kerala', 0, 1, NULL, '18:20', NULL, 4.0, 4.5, 8.3179, 77.0706, 'Poovar, Neyyattinkara, Thiruvananthapuram, Kerala 695525, India', NULL, 0.84);

