INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000043, 840002, 'Neyyar Wildlife Sanctuary and Dam', 'Neyyar Wildlife Sanctuary and Dam', 'A forested sanctuary ~30 km southeast of the city around the Neyyar reservoir. Attractions include the lion safari park, crocodile rehabilitation centre, deer park, elephant rides and reservoir boating; the dam viewpoint overlooks the Western Ghats foothills.', '4-5 hours', 'October to March', 'The lion safari is the main draw - book at the counter on arrival; the sanctuary is closed on Mondays.', 'Not required; safari tickets at counter', 'Kerala', 0, 0, NULL, NULL, 'Rs 250 (adult), Rs 125 (child 5-12) - lion safari', 4.0, 4.0, 8.53507, 77.14096, 'Neyyar Dam, Neyyattinkara, Thiruvananthapuram, Kerala 695572, India', NULL, 0.8);

