INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000044, 840002, 'Varkala', 'Varkala', 'A dramatic red laterite cliff town ~50 km north of the city, topped by a National Geological Monument (the Varkala Formation declared by GSI). Papanasam Beach below the cliff is believed to wash away sins; the Janardhana Swamy Temple (5 AM-12 PM, 5-8 PM) adds a spiritual dimension.', 'Full day', 'October to March', 'Walk the cliff-top path at sunset, then descend to Papanasam Beach; the cliff viewpoint at sunset is spectacular.', 'Not required', 'Kerala', 0, 1, NULL, '18:20', 'Free', 5.0, 4.5, 8.73281, 76.70856, 'Varkala, Chirayinkeezhu, Thiruvananthapuram, Kerala 695141, India', NULL, 0.96);

