INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000045, 840002, 'Padmanabhapuram Palace', 'Padmanabhapuram Palace', 'The 16th-18th century wooden palace of the Travancore kings at Thuckalay, Kanyakumari district, Tamil Nadu (~50-55 km from the city), maintained by the Kerala government. Renowned for its rosewood ceilings, secret passages, mural-painted council chamber and the famous medicinal bed - one of India''s finest wooden palaces.', '2-3 hours', 'October to March', 'Note: this is in Tamil Nadu (Kanyakumari district), ~50-55 km from Thiruvananthapuram. Visits are guided; closed on Mondays.', 'Not required; tickets at counter', 'Kerala', 0, 0, NULL, NULL, 'Rs 35 (Indian adult)', 4.5, 4.5, 8.24479, 77.31994, 'Padmanabhapuram Palace Road, Thuckalay, Kanyakumari, Tamil Nadu 629175, India', NULL, 0.9);

