INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000046, 840002, 'Ponmudi', 'Ponmudi', 'The ''Golden Peak'' hill station ~55-61 km northeast of the city at ~1100 m. Winding 22-hairpin road climbs to tea gardens, the Golden Valley stream, Echo Point and trekking trails through shola forest - the nearest cool-climate escape from Thiruvananthapuram.', 'Full day', 'October to March', 'Start early to enjoy misty morning views; the hairpin drive is the adventure - hire a local driver if unsure of ghat roads.', 'Not required', 'Kerala', 1, 1, '06:25', '18:20', 'Free', 4.5, 4.5, 8.75775, 77.11576, 'Ponmudi Hill Station, Nedumangad, Thiruvananthapuram, Kerala 695551, India', NULL, 0.9);

