INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000047, 840002, 'Villa Maya', 'Villa Maya', 'Thiruvananthapuram''s most celebrated heritage restaurant, set in a restored 18th-century ettukettu manor near the airport. The menu traces Kerala''s spice-trade links with Moroccan, Italian and regional Indian dishes - the Syrian sampler, crab curry and spice-box tandoor platter are signatures. Candlelit courtyard dining at dinner.', '1-2 hours', 'Year-round; dinner', 'Book ahead for weekend dinners; the garden gazebos are the most romantic seats.', 'Recommended for dinner', 'Kerala', 0, 0, NULL, NULL, 'Rs 1,000-1,500 per person', 5.0, 4.5, 8.481915, 76.937096, 'No-120 Palayam Airport Road, Vallakkadavu, Thiruvananthapuram, Kerala 695008, India', 'http://www.villamaya.in/', 0.96);

