INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000048, 840002, 'Mothers Veg Plaza', 'Mothers Veg Plaza', 'A beloved pure-veg landmark at Bakery Junction, famous for its Trivandrum-style Kerala sadya served on banana leaves 365 days a year and 100 varieties of dosa. Buzzing, homely and great value - the go-to spot for an authentic vegetarian lunch near the railway station.', '1 hour', 'Year-round; lunch', 'Arrive before 12:30 PM for the sadya - it gets very crowded and parking is tight at lunchtime.', 'Not required', 'Kerala', 0, 0, NULL, NULL, 'Rs 200-400 per person', 4.5, 4.0, 8.500311, 76.953148, 'Bakery Junction, Near Russian Cultural Center, Thiruvananthapuram, Kerala 695034, India', 'https://mothersvegplaza.in/', 0.86);

