INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000050, 840002, 'Ariya Nivas', 'Ariya Nivas', 'A long-running pure-veg institution at Aristo Junction, Thampanoor, a few hundred metres from the railway station. Famous for its authentic Kerala veg meals, steaming idlis, masala dosas with real-ghee roast and Sunday breakfast crowds.', '45 minutes', 'Year-round; breakfast', 'Sunday mornings are very crowded - go early for the breakfast rush.', 'Not required', 'Kerala', 0, 0, NULL, NULL, 'Rs 200-400 per person', 4.0, 4.0, 8.488752, 76.953752, 'Manorama Road, Aristo Junction, Thampanoor, Thiruvananthapuram, Kerala 695001, India', NULL, 0.8);

