INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000051, 840002, 'Zam Zam Restaurant', 'Zam Zam Restaurant', 'A Trivandrum institution since 1979 for Middle Eastern and Arabian food - credited with introducing the city''s first shawarma and outdoor tandoor counters. Famous for chicken shawaya (grilled chicken with kubbus and mayo), shawarma, and its trademark ice-milk desserts. The Palayam flagship is opposite the MLA Hostel.', '1 hour', 'Year-round; dinner', 'Order the shawaya with extra mayo and kubbus; the restaurant''s own description notes halal chicken and no ajinomoto.', 'Not required', 'Kerala', 0, 0, NULL, NULL, 'Rs 200-400 per person', 4.5, 4.5, 8.503614, 76.949752, 'VJT University Road, Opposite MLA Hostel, Palayam, Thiruvananthapuram, Kerala 695034, India', 'http://www.zamzamrestaurants.com/', 0.9);

