INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000052, 840002, 'Azad Restaurant', 'Azad Restaurant', 'A city landmark since 1947 for dum biryani - the Over Bridge flagship near Thampanoor is where generations of Trivandrum residents have eaten chicken and mutton biryani, kothu parotta, butter chicken and chicken fry. Affordable, fast and always busy at lunch.', '45 minutes', 'Year-round; lunch', 'The chicken dum biryani is the must-order; expect a crowd at lunch and limited parking.', 'Not required', 'Kerala', 0, 0, NULL, NULL, 'Rs 200-400 per person', 4.0, 4.0, 8.4882, 76.94747, 'Over Bridge, Thampanoor, Thiruvananthapuram, Kerala 695001, India', NULL, 0.8);

