INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8400006, 840, 840002, 'Attukal Pongala', 'Feb-Mar', 'Ten-day festival at Attukal Bhagavathy Temple culminating in the world''s largest annual gathering of women (Guinness record, ~4 million participants in 2026). On the main Pongala day, women cook sweet rice in earthen pots over open hearths across a 7-km radius around the temple as an offering to Attukal Amma. Only women participate; the city is transformed by the ritual.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8400007, 840, 840002, 'Onam', 'Aug-Sep', 'Kerala''s official state festival, a 10-day harvest celebration marking the homecoming of the mythical King Mahabali. In Thiruvananthapuram it is celebrated with pookalam floral carpets, Onasadya vegetarian feasts, cultural performances and temple events; the city hosts government-organised Onam week festivities.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8400008, 840, 840002, 'Nishagandhi Dance Festival', 'January', 'Week-long classical dance festival organised by Kerala Tourism at the Nishagandhi open-air auditorium in Kanakakkunnu Palace grounds, usually in the last week of January. Showcases Kathak, Bharatanatyam, Odissi, Kuchipudi, Manipuri, Kathakali and Mohiniyattam by leading exponents; free entry.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8400009, 840, 840002, 'Swathi Sangeethotsavam', 'January', 'Ten-day Carnatic/Hindustani music festival (early January) at Kuthiramalika Palace devoted exclusively to the compositions of Maharaja Swathi Thirunal, organised by Prince Rama Varma and the Travancore Trust. Free, unticketed concerts in the palace courtyard.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8400010, 840, 840002, 'Navaratri at Sree Padmanabhaswamy Temple', 'Sep-Oct', 'Nine-night Navaratri festival at Sree Padmanabhaswamy Temple during September-October. Idols of Goddess Saraswati from Padmanabhapuram Palace, the Munnuttinanka idol from Suchindram and Kumaraswamy from Kumarakovil are brought in a ceremonial procession to the Navaratri Mandapam; daily pujas, Saraswati puja and cultural programmes follow.');

-- city: Munnar (id 1043)
INSERT OR IGNORE INTO cities (id, state_id, city_name, latitude, longitude) VALUES (840003, 840, 'Munnar', 10.0889, 77.0595);

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000053, 840003, 'Eravikulam National Park', 'Eravikulam National Park', 'Eravikulam National Park protects the shola grasslands of Rajamala, home to the largest surviving population of the endangered Nilgiri tahr and the famous Neelakurinji flower. Visitors ride forest department shuttle buses to the Rajamala visitor zone; the park closes each February-March for the tahr calving season.', NULL, 'September to May', NULL, 'yes', 'Kerala', 0, 0, NULL, NULL, NULL, NULL, NULL, 10.14539, 77.03663, NULL, NULL, NULL);

