INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000054, 840003, 'KDHP Tea Museum', 'KDHP Tea Museum', 'The KDHP Tea Museum in Nallathanni Estate traces Munnar''s tea history since 1880, with a working demonstration of orthodox tea processing from withering to drying. Run by Kanan Devan Hills Plantations, it is closed on Mondays and shows old factory machinery and photographs from the colonial plantation era.', NULL, 'September to May', NULL, 'no', 'Kerala', 0, 0, NULL, NULL, NULL, NULL, NULL, 10.0707, 77.0629, NULL, 'https://kdhptea.com', NULL);

