INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000055, 840003, 'Mattupetty Dam', 'Mattupetty Dam', 'Mattupetty Dam is a 1950s hydro-electric reservoir 13 km from Munnar town, framed by tea gardens and grassy hill slopes. It offers paddle, row and speed boat rides, and the nearby Mattupetty dairy farm project gives it a hill-resort feel.', NULL, 'September to May', NULL, 'no', 'Kerala', 0, 0, NULL, NULL, NULL, NULL, NULL, 10.12, 77.12, NULL, NULL, NULL);

