INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000056, 840003, 'Kolukkumalai Tea Estate', 'Kolukkumalai Tea Estate', 'Kolukkumalai is billed as the world''s highest organic tea estate at about 7,900 ft (2,400 m), reached by a pre-dawn 4WD jeep safari from Suryanelli. The payoff is a sunrise above a sea of clouds with the old British-era tea factory nearby.', NULL, 'October to May', NULL, 'yes', 'Kerala', 1, 0, NULL, NULL, NULL, NULL, NULL, 10.0675, 77.211, NULL, NULL, NULL);

