INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000057, 840003, 'Chinnar Wildlife Sanctuary', 'Chinnar Wildlife Sanctuary', 'Chinnar Wildlife Sanctuary is a dry rain-shadow forest about 48 km from Munnar on the Marayoor route, known for wild elephants, grizzled giant squirrels and sandalwood. The guided trek to Thoovanam Falls through the forest is the main activity.', NULL, 'September to May', NULL, 'no', 'Kerala', 0, 0, NULL, NULL, NULL, NULL, NULL, 10.32, 77.17, NULL, NULL, NULL);

