INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000058, 840003, 'Meesapulimala Trek', 'Meesapulimala Trek', 'Meesapulimala is the second-highest peak in South India at 2,640 m, a full-day guided trek run by the Kerala Forest Development Corporation from Rhodo Mansion. Trekkers cross shola grasslands with views stretching to the Tamil Nadu plains.', NULL, 'October to May', NULL, 'yes', 'Kerala', 1, 0, NULL, NULL, NULL, NULL, NULL, 10.101, 77.071, NULL, NULL, NULL);

