INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000059, 840003, 'Lakkam Waterfalls', 'Lakkam Waterfalls', 'Lakkam Waterfalls on the Munnar-Marayoor route drops in multiple streams past tea estates, with a forest-guided trek option for Rs 100. The pool below the falls is a popular bathing spot on the way to Chinnar.', NULL, 'September to May', NULL, 'no', 'Kerala', 0, 0, NULL, NULL, NULL, NULL, NULL, 10.3206, 77.1587, NULL, NULL, NULL);

