INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000060, 840003, 'Top Station', 'Top Station', 'Top Station is the highest point on the Munnar-Kodaikanal road at 1,700 m, famous for panoramic views over the Western Ghats and the Tamil Nadu plains. It was the upper terminus of the 1908 Kundala Valley monorail ropeway that carried tea chests down to the plains.', NULL, 'September to May', NULL, 'no', 'Kerala', 1, 1, NULL, NULL, NULL, NULL, NULL, 10.1266, 77.2061, NULL, NULL, NULL);

