INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000061, 840003, 'CSI Christ Church', 'CSI Christ Church', 'CSI Christ Church, founded in 1910 and consecrated in April 1911, is a stone Gothic Revival church built by the British planters. Its stained-glass windows, brass plaques and quiet churchyard record over a century of Munnar''s plantation history.', NULL, 'September to May', NULL, 'no', 'Kerala', 0, 0, NULL, NULL, NULL, NULL, NULL, 10.0887, 77.058, NULL, NULL, NULL);

