INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8400011, 840, 840003, 'Onam', 'August-September', 'Kerala''s biggest harvest festival, celebrated across Munnar with flower rangolis (pookalam), Onam sadhya feasts and cultural programmes in the tea estates.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8400012, 840, 840003, 'Vishu', 'April', 'Kerala New Year, marked with Vishukkani displays, temple visits and fireworks; celebrated in Munnar''s temples and plantation communities.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8400013, 840, 840003, 'Thiruvathira', 'December-January', 'Women''s festival in the Malayalam month of Dhanu with Thiruvathirakali dance performances; observed in Munnar''s temples and households.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8400014, 840, 840003, 'Christmas and New Year', 'December-January', 'Widely celebrated in Munnar''s tea estates and churches, a legacy of the British planter era, with carols, midnight mass and New Year events in the hill station.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8400015, 840, 840003, 'Neelakurinji Bloom', 'Every 12 years (next expected around 2030; bloom window roughly July-October)', 'Not a festival but Munnar''s signature natural event: the Neelakurinji flower blooms en masse in Eravikulam National Park once every 12 years, carpeting the hills in blue. The last bloom was 2018.');

-- city: Alappuzha (id 1044)
