INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000079, 840004, 'Alappuzha Backwaters & Houseboat Cruise', 'Alappuzha Backwaters & Houseboat Cruise', 'The interlinked network of canals, lagoons and the Vembanad Lake around Alappuzha is Kerala''s most famous backwater destination. Visitors explore it on traditional kettuvallam houseboats or smaller shikara boats, cruising past coconut groves, paddy fields and village life. Cruises typically depart from the Punnamada Finishing Point area on the Alappuzha-Punnamada lake stretch.', '4-6 hours (day cruise); 1 night (houseboat stay)', 'September to March', 'Book private houseboats a day or two ahead in peak season (Dec-Jan); day cruises and shikara rides can be arranged at the Finishing Point jetty the same day.', 'yes', 'Kerala', 1, 1, '6:13 AM', '6:15 PM', NULL, 5, 5, 9.5011, 76.3534, 'Punnamada Finishing Point area, Alappuzha, Kerala 688013', NULL, 1.0);

