INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 840000079, 'insert', 'bulk', 'Place is real and well documented across Kerala Tourism and travel guides. Coordinates approximate to the Punnamada Finishing Point area (houseboat boarding zone), not a single building; actual boarding points vary along the Finishing Point road. No published fixed tariff (rates vary by boat type/operator/season), so cost left null.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000080, 840004, 'Vembanad Lake', 'Vembanad Lake', 'Vembanad is the longest lake in India and the largest in Kerala, forming the heart of the Alappuzha backwaters. It supports houseboat cruises, canoe rides, birdwatching and fishing communities, and hosts the Punnamada stretch where the Nehru Trophy Boat Race is held. The lake lies between Alappuzha and Kottayam districts and feeds the surrounding Kuttanad paddy landscape.', '2-3 hours', 'September to March', 'Combine a Vembanad cruise with Pathiramanal Island in the same boat trip when hiring a shikara for a half day.', 'no', 'Kerala', 1, 1, '6:13 AM', '6:15 PM', NULL, 5, 5, 9.54, 76.4, 'Vembanad Lake, between Alappuzha and Kottayam, Kerala', NULL, 1.0);

