INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 840000080, 'insert', 'bulk', 'Vembanad is well documented (longest lake in India, largest in Kerala) by Kerala Tourism and Wikipedia. Coordinates are a central-lake approximation within ~1 km of the water body; access points differ (Punnamada, Muhamma, Kumarakom). No entry fee.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000081, 840004, 'Alappuzha Beach', 'Alappuzha Beach', 'A palm-fringed Arabian Sea beach in Alappuzha town, popular for evening walks and sunsets. Its landmark is the 137-year-old sea pier built during the port era, jutting into the sea; the Alappuzha Lighthouse stands at the southern end. The beach is busy around New Year when beach festivals and sand art events are held.', '1-2 hours', 'September to March', 'Visit between 5:00-6:30 PM for the sunset; avoid swimming during monsoon when the sea is rough.', 'no', 'Kerala', 0, 1, '6:13 AM', '6:15 PM', NULL, 4, 4, 9.4759, 76.3257, 'Beach Road, Alappuzha, Kerala 688012', NULL, 0.8);

