INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 840000081, 'insert', 'bulk', 'Real, well documented by Kerala Tourism (keralatourism.org Alappuzha Beach page). 137+ year old pier repeatedly cited across sources. Coordinates approximate the beach/pier zone.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000082, 840004, 'Alappuzha Lighthouse', 'Alappuzha Lighthouse', 'Built in 1862 on the coast of Alappuzha, this is one of the oldest lighthouses on India''s south-west coast, from the era when Alappuzha was a major port. Visitors climb a teak spiral staircase to a lookout with panoramic views of the Arabian Sea, backwaters and town. A small museum at the base displays an original double-wick lamp used in the 19th century.', '45 minutes - 1 hour', 'September to March', 'Climbing is steep (many narrow steps), so it may not suit elderly visitors; carry water.', 'no', 'Kerala', 1, 1, '6:13 AM', '6:15 PM', 'Rs 10', 4, 4, 9.493958, 76.320936, 'CCSB Rd, Alappuzha, Kerala 688012', NULL, 0.8);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (840000082, 840000082, 'Closed', '9:00 AM - 5:00 PM', '9:00 AM - 5:00 PM', '9:00 AM - 5:00 PM', '9:00 AM - 5:00 PM', '9:00 AM - 5:00 PM', '9:00 AM - 5:00 PM', 'From the DGLL official page: visitors admitted between 3:00 PM and 4:30 PM on weekdays at Rs 10 admission. Third-party guides (MakeMyTrip) report 3:00-5:00 PM daily - confirm locally.');

