INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000083, 840004, 'Mullakkal Rajarajeswari Temple', 'Mullakkal Rajarajeswari Temple', 'The main deity is Goddess Rajarajeswari (Durga). It is unusual among Kerala temples for having no roof over the sanctum sanctorum - the deity stands exposed to sun and rain. Located in the heart of Alappuzha town, it also houses shrines to Hanuman, Subramanya, Nagaraja, Ganapathi, Sree Krishna and Ayyappa.', '1 hour', 'September to March', 'Evening darshan is calmer; dress modestly as with other Kerala temples.', 'no', 'Kerala', 0, 0, '6:13 AM', '6:15 PM', NULL, 4, 4, 9.4962, 76.3415, 'Mullakkal, Alappuzha, Kerala 688011', NULL, 0.8);

