INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 840000083, 'insert', 'bulk', 'Real and well documented (Wikipedia, Kerala Tourism). Roofless sanctum and deity details confirmed by multiple sources. No published daily opening hours found on a reliable source, so hours left null rather than guessed. Coordinates approximate the Mullakkal town junction.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000084, 840004, 'International Coir Museum', 'International Coir Museum', 'Set up by the Coir Board of India and inaugurated in May 2014, this museum at Kalavoor traces the history and technology of the coir industry that built Alappuzha''s economy. Exhibits cover retting, fibre extraction, spinning and weaving, with life-size machinery models, a short film, and a souvenir shop selling coir mats, rugs and jewellery.', '1-2 hours', 'September to March', 'Photography inside needs a separate Rs 50 permit; morning visits are quieter.', 'no', 'Kerala', 0, 0, '6:13 AM', '6:15 PM', 'Rs 50', 3, 3, 9.563, 76.331, 'Coir Board Complex, Kalavoor, Alappuzha, Kerala 688522', NULL, 0.6);

