INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000085, 840004, 'Revi Karunakaran Memorial Museum', 'Revi Karunakaran Memorial Museum', 'A privately owned museum built in 2003 by Betty Karunakaran in memory of her husband Revi Karunakaran, the industrialist credited with modernising Kerala''s coir industry. It holds one of the largest private collections in the state: Swarovski crystal, ivory and jade artefacts, porcelain, Tanjore paintings, a large vegetable-dye mural and a ''Kerala Room'' with thousands of rare cultural objects.', '1-2 hours', 'September to March', 'Photography is generally not allowed inside; visit early to avoid crowds.', 'no', 'Kerala', 0, 0, '6:13 AM', '6:15 PM', 'Rs 200', 3, 4, 9.497, 76.3305, 'CCSB Rd, Alappuzha, Kerala 688012', NULL, 0.68);

