INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000086, 840004, 'Karumadikkuttan', 'Karumadikkuttan (Buddha Statue, Karumadi)', 'Karumadikkuttan is a granite statue of the Buddha dating to the 11th century, standing in the small village of Karumadi about 3 km east of Alappuzha town. It is a protected monument of the Kerala Archaeology Department and a rare remnant of Kerala''s Buddhist past. Pilgrims and tourists visit the calm open-air site surrounded by paddy fields.', '30 minutes', 'September to March', 'A quick stop combined with a Kuttanad village drive; best in daylight.', 'no', 'Kerala', 0, 0, '6:13 AM', '6:15 PM', NULL, 3, 3, 9.5019, 76.3723, 'Karumadi, Alappuzha, Kerala 688003', NULL, 0.6);

