INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000087, 840004, 'Kuttanad', 'Kuttanad (Rice Bowl of Kerala)', 'Kuttanad is the delta region of paddy fields below sea level stretching across Alappuzha and Kottayam districts, known as the Rice Bowl of Kerala. It is crossed by the backwater network and dotted with narrow canals, village bridges and toddy shops. Visitors drive or cruise through it to see reclaimed farmland (padasekharams), water birds and the R-block lake land reclaimed from the backwaters.', 'Half day', 'September to March', 'Shikara village cruises from Alappuzha into Kuttanad canals give the best close-up view; mornings show the most birdlife.', 'no', 'Kerala', 1, 1, '6:13 AM', '6:15 PM', NULL, 4, 4, 9.613, 76.4778, 'Kuttanad region (Kainakary/Pallathuruthy area), Alappuzha, Kerala', NULL, 0.8);

