INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000088, 840004, 'Vijaya Beach Park', 'Vijaya Beach Park', 'A family park beside Alappuzha Beach with a children''s play area, toy train, jogging track, skating rink and volleyball court. Boating facilities (pedal boats and speed boats) let visitors explore the adjacent backwater canals. The park hosts evening cultural events and concerts and is at its liveliest during the New Year beach festivities.', '1-2 hours', 'September to March', 'Arrive by 4 PM - the park opens only in the afternoon (3-8 PM).', 'no', 'Kerala', 0, 1, '6:13 AM', '6:15 PM', NULL, 3, 3, 9.4813, 76.3255, 'Alappuzha Bypass Rd, Sea View Ward, Alappuzha, Kerala 688007', NULL, 0.6);

