INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000089, 840004, 'Sea View Park', 'Sea View Park', 'A garden park near Alappuzha Beach with boating facilities and a swimming pool, set in a well-kept green space. It offers relaxed walks, pedal and round-boat rides, and is a popular family outing spot. Recent additions include adventure activities like zipline and rope cycling per visitor reviews.', '1-2 hours', 'September to March', 'Good for families with children; combine with Alappuzha Beach in the same evening.', 'no', 'Kerala', 0, 1, '6:13 AM', '6:15 PM', NULL, 3, 3, 9.4742, 76.3259, 'Sea View Park, near Alappuzha Beach, Alappuzha, Kerala 688012', NULL, 0.6);

