INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000090, 840004, 'Thumpoly Beach', 'Thumpoly Beach', 'A quieter beach about 5 km south of Alappuzha town, popular with locals for evening walks and sunsets. It has soft sand and a calmer crowd than Alappuzha Beach, with small food stalls nearby. Like other Kerala beaches it is best visited outside the monsoon.', '1 hour', 'September to March', 'Go for sunset; check local advisories before swimming, especially in monsoon months.', 'no', 'Kerala', 0, 1, '6:13 AM', '6:15 PM', NULL, 3, 3, 9.4565, 76.3191, 'Thumpoly, Alappuzha, Kerala 688008', NULL, 0.6);

