INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000091, 840004, 'Marari Beach', 'Marari Beach', 'A golden-sand beach about 11 km north of Alappuzha at the fishing village of Mararikulam, noted for retaining its pristine, uncrowded character. Coconut palms fringe the shore and a backwater lagoon runs behind it. Several homestays and Ayurvedic resorts cluster nearby, making it a quieter base than town.', 'Half day', 'September to March', 'Stay in one of the beachside homestays for sunrise walks; the fishing village walk at dawn is worthwhile.', 'no', 'Kerala', 0, 1, '6:13 AM', '6:15 PM', NULL, 4, 5, 9.6016, 76.2966, 'Mararikulam, Alappuzha, Kerala 688549', NULL, 0.88);

