INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000092, 840004, 'Punnapra Vayalar Memorial', 'Punnapra Vayalar Memorial', 'A memorial at Punnapra, about 6 km south of Alappuzha, dedicated to the martyrs of the 1946 Punnapra-Vayalar uprising, a landmark communist peasant revolt in Travancore history. The memorial complex marks a significant chapter of Kerala''s political history.', '30-45 minutes', 'September to March', 'Best combined with a short drive south toward Ambalappuzha.', 'no', 'Kerala', 0, 0, '6:13 AM', '6:15 PM', NULL, 2, 2, 9.521, 76.358, 'Punnapra, Alappuzha, Kerala 688004', NULL, 0.4);

