INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 840000092, 'insert', 'bulk', 'Real memorial cited on the Kerala Tourism district guide (keralatourism.guide Alappuzha page). Coordinates approximate Punnapra town. No published hours or entry fee found - left null.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000093, 840004, 'Ambalappuzha Sree Krishna Temple', 'Ambalappuzha Sree Krishna Temple', 'One of Kerala''s most famous Krishna temples, about 14 km south of Alappuzha town, known as the Dwaraka of the South. Built in traditional Kerala style, it is legendary for its daily offering of Palpayasam, a sweet milk-and-rice pudding prasadam. The temple also has deep links to Kerala''s performing arts: the first Ottan Thullal was performed here.', '1 hour', 'September to March', 'Arrive before 11:30 AM if you want Palpayasam (spot bookings, distribution from ~10 AM); men must remove shirts, women wear traditional modest dress.', 'no', 'Kerala', 0, 0, '6:13 AM', '6:15 PM', NULL, 5, 5, 9.3843, 76.3676, 'Ambalappuzha, Alappuzha, Kerala 688561', NULL, 1.0);

