INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 840000093, 'insert', 'bulk', 'Real, very well documented. Timings (3 AM-12 PM, 5-8 PM) consistent across hialappuzha.in, keralahouseboat.com and Wanderlog. Palpayasam Rs 160/litre from recent visitor reviews (not official), so cost left null (no entry fee). Distance from Alappuzha town ~14 km. Coordinates approximate the temple complex.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000094, 840004, 'Pathiramanal Island', 'Pathiramanal Island', 'A 10-acre uninhabited island in Vembanad Lake, about 28 km from Alappuzha town (roughly 1.5 hours by motorboat or 30 minutes by speedboat, also reachable from the Muhamma jetty ~1.5 km away). Its name means ''Sands of Midnight''. It is a birdwatcher''s haven with over 90 local and 50 migratory bird species recorded, plus walking trails through dense vegetation.', '2-3 hours', 'November to March', 'Carry binoculars and water; there are no shops on the island, and birding is best in early morning.', 'no', 'Kerala', 1, 1, '6:13 AM', '6:15 PM', NULL, 4, 5, 9.615, 76.3836, 'Pathiramanal, Vembanad Lake (boat from Muhamma/Kumarakom/Alappuzha), Kerala', NULL, 0.88);

