INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 840000094, 'insert', 'bulk', 'Real island; GPS 9.61500, 76.38361 from AroundUs page; boat access details from forumias/ayurgreenie guides (Muhamma jetty ~1.5 km, 13-28 km from Alappuzha). Bird counts (90+ local, 50 migratory) consistently reported. No published entry fee; boat hire varies by operator - cost null.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000095, 840004, 'Kumarakom Bird Sanctuary', 'Kumarakom Bird Sanctuary', 'A 14-acre bird sanctuary on the eastern bank of Vembanad Lake, about 35 km from Alappuzha town. It hosts resident water birds and migratory species that arrive November-February, best seen from walking trails and boat cruises around the lake edge. The sanctuary sits within the Kumarakom backwater landscape near the lake''s bird-rich western shore.', '2-3 hours', 'November to February', 'Carry binoculars; plastic is prohibited inside the sanctuary.', 'no', 'Kerala', 1, 0, '6:13 AM', '6:15 PM', 'Rs 50', 4, 4, 9.6252, 76.4294, 'Kumarakom, Kottayam, Kerala 686563', NULL, 0.8);

