INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000096, 840004, 'Mannarasala Sree Nagaraja Temple', 'Mannarasala Sree Nagaraja Temple', 'One of the most important serpent temples in India, about 32 km south of Alappuzha near Haripad. Set in a 16-acre sacred forest grove dotted with over 30,000 serpent images, it is dedicated to Nagaraja and his consorts. Uniquely, the main rituals are led by a hereditary female priest, the Valiyamma, and childless couples famously offer ''Uruli Kamazhthal'' here.', '1-2 hours', 'September to March', 'Dress in traditional modest attire; the forest paths have many stone serpent images - watch your step.', 'no', 'Kerala', 0, 0, '6:13 AM', '6:15 PM', NULL, 5, 5, 9.2897, 76.4457, 'Mannarasala P.O, Haripad, Alappuzha, Kerala 690514', 'http://www.mannarasala.org/', 1.0);

