INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000097, 840004, 'Krishnapuram Palace', 'Krishnapuram Palace', 'An 18th-century palace near Kayamkulam, about 47 km south of Alappuzha, built by Travancore king Marthanda Varma and now an archaeological museum. It preserves one of the largest mural panels in Kerala, the Gajendra Moksham, alongside antique sculptures, bronzes, coins and weapons. Built in traditional pathinarukettu Kerala architecture with gabled roofs and narrow corridors.', '1-2 hours', 'November to March', 'Avoid the 1-2 PM closure break; cameras need a separate Rs 25-40 permit.', 'no', 'Kerala', 0, 0, '6:13 AM', '6:15 PM', 'Rs 20', 4, 4, 9.159, 76.4936, 'Krishnapuram, Kayamkulam, Alappuzha, Kerala 690533', NULL, 0.8);

