INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000098, 840004, 'St. Andrew''s Basilica, Arthunkal', 'St. Andrew''s Basilica, Arthunkal', 'A coastal basilica at Arthunkal, about 22 km north of Alappuzha, originally built by Portuguese missionaries in the 16th century (stone church 1597 under Fr. Giacomo Fenicio) and elevated to basilica status in 2010. It houses a revered statue of St. Sebastian brought from Milan in 1647 and is one of Kerala''s major Christian pilgrim centres, famous for the January Arthunkal Perunnal feast.', '1 hour', 'September to March', 'Visit on a weekday morning for a calm visit; the church faces the beach, so walk to the shore behind it.', 'no', 'Kerala', 1, 1, '6:13 AM', '6:15 PM', NULL, 4, 4, 9.6669, 76.2968, 'Arthunkal, Cherthala, Alappuzha, Kerala 688530', NULL, 0.8);

