INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000099, 840004, 'Halais Restaurant', 'Halais Restaurant', 'A long-running, popular family restaurant in Alappuzha town known for its fried fish, chicken biryani and lime chicken, with Indian, Asian, seafood and Arabic dishes. It offers vegetarian-friendly options, is halal-certified, and serves lunch, dinner and brunch in a casual setting.', '1 hour', 'Year round', 'Their grilled fish and biryani are the most recommended; Friday has a midday break (12:00-1:30 PM).', 'no', 'Kerala', 0, 0, '6:13 AM', '6:15 PM', NULL, 4, 4, 9.4925, 76.3417, 'CCSB Road, Near South Police Station, Kodiveedu, Alappuzha, Kerala 688001', NULL, 0.8);

