INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000103, 840004, 'Dreamers Cafe and Restaurant', 'Dreamers Cafe and Restaurant', 'A beach-road cafe near Kaipuram Mosque in Alappuzha, popular with travellers for its seafood platter and relaxed evening ambience. It offers Kerala and continental dishes in a casual setting close to the shore.', '1 hour', 'Year round', 'Go for the seafood platter and an evening meal after the beach.', 'no', 'Kerala', 0, 0, '6:13 AM', '6:15 PM', NULL, 3, 3, 9.468, 76.3245, 'Beach Road, near Kaipuram Mosque, Alappuzha, Kerala 688012', NULL, 0.6);

