INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000104, 840004, 'Kream Korner', 'Kream Korner', 'A popular family restaurant on Mullackal Road in Alappuzha, often called an art cafe for its ambience. It serves Kerala entrees, Mughal biryani, Indo-Chinese and North Indian dishes, and is a favourite with both foreign tourists and locals.', '1 hour', 'Year round', 'Try the biryani and porotta with mutton curry; it opens from late morning so plan lunch or dinner.', 'no', 'Kerala', 0, 0, '6:13 AM', '6:15 PM', NULL, 3, 3, 9.4964, 76.3425, 'Mullackal Rd, Mullakkal, Alappuzha, Kerala 688011', NULL, 0.6);

