INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8400016, 840, 840004, 'Nehru Trophy Boat Race', 'Aug', 'Kerala''s most famous snake boat race, held annually on the second Saturday of August at Punnamada Lake in Alappuzha. Giant chundan vallams (100-120 ft snake boats) with up to 110 oarsmen compete for a silver trophy instituted after Pandit Jawaharlal Nehru''s visit in 1952.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8400017, 840, 840004, 'Champakulam Moolam Boat Race', 'Jun-Jul', 'One of the oldest snake boat races in Kerala, held on the River Pampa at Champakulam on Moolam day of the Malayalam month Midhunam. It marks the day the Krishna idol was brought by boat for installation at the Ambalappuzha Sree Krishna Temple and opens the boat-race season.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8400018, 840, 840004, 'Payippad Jalotsavam', 'Aug-Sep', 'A three-day snake boat race at Payippad Lake, about 35 km from Alappuzha, commemorating the installation of the deity at the Subramanya Swamy Temple, Haripad. Local legend says the idol was found in the Kayamkulam lake after villagers dreamt of it.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8400019, 840, 840004, 'Mullakkal Chirappu', 'Nov-Dec', 'The biggest festival of the Mullakkal Rajarajeswari Temple in Alappuzha town, running 41 days from the start of the Malayalam month Vrishchikam to the 11th of Dhanu, with the last 11 days celebrated as Chirappu - marked by caparisoned elephant parades, cultural programmes and a grand final-day annadanam feast.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8400020, 840, 840004, 'Ambalappuzha Arattu', 'Mar-Apr', 'The 10-day annual festival of the Ambalappuzha Sree Krishna Temple, with caparisoned elephants, panchavadyam percussion ensembles and the ceremonial holy bath (arattu) of the idol in the temple pond, drawing large crowds to the town.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8400021, 840, 840004, 'Arthunkal Perunnal', 'Jan', 'The grand annual feast of St. Sebastian at St. Andrew''s Basilica, Arthunkal (also called Makaram Perunnal), lasting about ten days in January. The highlight is the procession of the Milan-made St. Sebastian statue to the beach and back, with devotees crawling on their knees (nercha) to fulfil vows.');

-- city: Kozhikode (id 1045)
INSERT OR IGNORE INTO cities (id, state_id, city_name, latitude, longitude) VALUES (840005, 840, 'Kozhikode', 11.2588, 75.7804);

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000105, 840005, 'Kozhikode Beach', 'Kozhikode Beach', 'Kozhikode''s main beach, a long stretch of golden sand on the Arabian Sea that has been the city''s evening gathering spot for generations. Known for its sunsets, the old lighthouse, historic stone piers, street-food shacks serving mussels (kallumakaya) and fried fish, plus Lion''s Park and Dolphin''s Point at its northern end.', '2–3 hours', 'October to March; evenings for sunset and sea breeze', 'Go around 4:30–5 PM to walk the old stone piers, then stay for sunset; try the beach shacks'' kallumakaya (mussels) and fried fish. Avoid midday heat and swimming is not advised — the sea is rough with no lifeguards in most stretches.', NULL, 'Kerala', 1, 1, '6:15 AM', '6:18 PM', 'Free', 5, 4, 11.2575, 75.7692, 'Beach Road, Kozhikode, Kerala 673032', NULL, 0.92);

