INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 840000105, 'insert', 'bulk', 'Coordinates approximate (city beach centre, ~11.2575, 75.7692); free entry and 24-hr access widely reported. Sunrise/sunset times for Kozhikode observed 2026-09-30.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000106, 840005, 'Kappad Beach', 'Kappad Beach', 'A serene, palm-fringed Blue Flag beach about 16 km from Kozhikode city, famous as the landing point of Vasco da Gama in May 1498 — a stone plaque on the rocky headland marks the event. Quieter than the city beach, with a small monument, fishing activity, and Olive Ridley turtle nesting in season.', '2–3 hours (half-day trip with drive)', 'October to March', 'Combine with a drive up the coast; the rocky headland at the north end has the best views and the 1498 plaque. Note the historical nuance: Kerala Tourism''s own page notes historians believe da Gama anchored at Kappad but landed at Panthalayini (Koyilandy).', NULL, 'Kerala', 1, 1, '6:15 AM', '6:18 PM', NULL, 5, 5, 11.385, 75.7175, 'Kappad, Kozhikode District, Kerala 673304 (about 16 km north of the city)', NULL, 1.0);

