INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000107, 840005, 'Beypore', 'Beypore', 'Historic port town at the Chaliyar river mouth, famous for building ''Uru'' wooden dhows by hand — a 1,500–2,000-year-old shipbuilding tradition where a single vessel can take 1–4 years. The long stone pier (Pulimutt) stretching into the sea is a favourite sunset walk, and the beach and fishing harbour are lively in the evenings.', '3–4 hours (half-day trip)', 'October to March; late afternoon to sunset', 'Visit a working uru boatyard in the morning to watch shipwrights at work, then return for sunset on the stone pier. The Beypore International Water Fest in December adds speedboat rides and water-sports demos.', NULL, 'Kerala', 0, 1, NULL, '6:18 PM', NULL, 5, 4, 11.1715, 75.8075, 'Beypore, Kozhikode District, Kerala 673015 (about 10–11 km south of the city, at the mouth of the Chaliyar river)', NULL, 0.92);

