INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000108, 840005, 'Thusharagiri Falls', 'Thusharagiri Falls', 'A trio of waterfalls on the Chalippuzha river in the Western Ghats — Thenpara (75 m), Erattumukku and Mazhavil Chattam — surrounded by evergreen forest. A trekker''s paradise with an 8 km trail onward to Vythiri, plus rock-climbing and river-crossing activities in season.', '3–5 hours (full-day trip with drive)', 'September to February (post-monsoon flow); avoid peak monsoon when trails close', 'Go on a weekday morning to avoid crowds; wear shoes with grip as rocks are slippery. Published opening hours conflict (8 AM–5 PM vs 6 AM–6 PM vs 8 AM–4 PM) — confirm locally before driving out.', NULL, 'Kerala', 0, 0, NULL, NULL, 'Rs 30 per adult', 4, 5, 11.4666, 76.052, 'Thusharagiri, Kodenchery, Kozhikode District, Kerala 673580 (about 50 km east of the city)', NULL, 0.88);

