INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000109, 840005, 'Regional Science Centre & Planetarium', 'Regional Science Centre & Planetarium', 'A National Council of Science Museums centre established in 1997, pairing interactive science galleries with a 250-seat Carl Zeiss planetarium running around 1,200 shows a year. Good for families and school groups; tickets are issued at the counter until 5:55 PM.', '2–3 hours', 'Year-round; afternoons are less crowded with school groups than mornings', 'Plan the visit for the afternoon — mornings are usually crowded with school groups. Check the show schedule at the counter on arrival; the planetarium and 3D shows run at fixed times.', NULL, 'Kerala', 0, 0, NULL, NULL, 'Rs 50 onwards (Science Centre only Rs 50; Entry + Planetarium Rs 75; all three Rs 100, individual rates)', 4, 4, 11.2545, 75.783, 'Jaffer Khan Colony Road, Near New Bus Stand, Kozhikode, Kerala 673006', 'https://rscpcalicut.org.in', 0.8);

