INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000110, 840005, 'Mananchira Square', 'Mananchira Square', 'The city''s central public square, built in 1994 around a historic 14th-century temple tank commissioned by Zamorin Mana Vikrama. Landscaped lawns, sculptures, Tipu Sultan''s cannons, a musical fountain and an open-air theatre — and SM Street begins at its south gate.', '1–2 hours', 'Year-round; evenings for the fountain and breeze', 'Combine with an evening stroll down SM Street from the square''s south gate, and look for the bust of writer S.K. Pottekkatt. Published opening hours conflict (3:30–8 PM most-cited vs 8 AM–8 PM vs 11 AM–8:30 PM) — the square is effectively a public park in the evenings.', NULL, 'Kerala', 0, 0, NULL, NULL, 'Free', 4, 4, 11.2538, 75.7817, 'Mananchira, Kozhikode, Kerala 673001', NULL, 0.8);

