INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000111, 840005, 'Tali Maha Shiva Temple', 'Tali Maha Shiva Temple', 'A 14th-century Shiva temple built by the Zamorins, one of the oldest and most important temples in the region, known for its classic Kerala temple architecture, brass work and annual Revathi Pattathanam scholars'' assembly. Strict dress code; men remove shirts before entering the sanctum.', '1–2 hours', 'October to March; early morning for poojas', 'Non-Hindus may be restricted from the inner sanctum — check at the entrance. Photography is not allowed inside. The Revathi Pattathanam (Oct–Nov) is the most culturally significant time to visit.', NULL, 'Kerala', 0, 0, NULL, NULL, 'Free', 4, 4, 11.247794, 75.787572, 'Tali Devaswam, Chalappuram, Kozhikode, Kerala 673002', NULL, 0.8);

