INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000112, 840005, 'Mishkal Mosque', 'Mishkal Mosque', 'A 14th-century mosque built by the Yemeni merchant-shipowner Nakhuda Mithqal, a masterpiece of Kerala-Islamic timber architecture with no dome or minarets — four storeys, 47 doors and 24 carved wooden pillars. Burned by the Portuguese in 1510 and rebuilt in 1578–79; still an active place of worship.', '45 minutes – 1 hour', 'October to March; visit outside prayer times', 'Dress modestly and visit between prayers; the carved wooden pillars and the massive prayer hall (capacity ~400) are the highlights. No official website found.', NULL, 'Kerala', 0, 0, NULL, NULL, 'Free', 5, 4, 11.2454, 75.7723, 'Kuttichira, Kozhikode, Kerala 673001', NULL, 0.92);

