INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000113, 840005, 'Pazhassiraja Museum & Art Gallery', 'Pazhassiraja Museum & Art Gallery', 'Housed in the 1812 East Hill Bungalow and opened as a museum in 1976, this museum is named for Kerala Varma Pazhassi Raja (d. 1805), the ''Lion of Kerala'' who resisted the British. Collections include ancient coins, murals, archaeological finds, and paintings by Raja Ravi Varma in the adjoining art gallery.', '1.5–2 hours', 'October to March; closed Mondays', 'The Raja Ravi Varma paintings in the art gallery are the highlight; allow time for both buildings. Closed on Mondays — plan around it.', NULL, 'Kerala', 0, 0, NULL, NULL, NULL, 3, 4, 11.2793, 75.7816, 'East Hill, Kozhikode, Kerala 673005', NULL, 0.68);

