INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000114, 840005, 'Kadalundi Bird Sanctuary', 'Kadalundi Bird Sanctuary', 'A bird sanctuary spread across islands at the Kadalundi river estuary, home to 100+ resident and around 60 migratory bird species including terns, gulls, herons and sandplovers. Best in the migratory season; small boats can be hired for a closer look at the islands.', '2–3 hours (half-day trip)', 'November to April (migratory season)', 'Bring binoculars and go early morning when birds are most active. Published hours (8 AM–6 PM vs 7 AM–5 PM vs 8 AM–5 PM) and fees conflict — confirm at the gate.', NULL, 'Kerala', 0, 0, NULL, NULL, NULL, 4, 4, 11.1294, 75.8282, 'Kadalundi, Kozhikode District, Kerala 673302 (about 19–20 km south of the city, at the Kadalundi river estuary)', NULL, 0.8);

