INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000115, 840005, 'Sarovaram Bio Park', 'Sarovaram Bio Park', 'An eco-tourism park built around mangrove wetlands, with boating on the canal linking the Korapuzha and Kallayi rivers, a musical fountain, otter park and butterfly park. A calm green escape within the city, popular with families.', '2–3 hours', 'October to March; late afternoon for boating and the fountain', 'The canal boat ride through the mangroves is the best part; the musical fountain runs in the evening. Entry fee of Rs 30/adult comes from a single unofficial source — carry small cash anyway.', NULL, 'Kerala', 0, 0, NULL, NULL, 'Rs 30 per adult (single unofficial source — verify at gate)', 3, 4, 11.269008, 75.790897, 'Mini Bypass Road, near Kottooli, Kozhikode, Kerala 673016', NULL, 0.68);

