INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000116, 840005, 'Sargaalaya Kerala Arts & Crafts Village', 'Sargaalaya Kerala Arts & Crafts Village', 'Kerala Tourism''s 20-acre arts and crafts village, opened on 19 February 2011, with 27 cottages and around 60 stalls where artisans work and sell directly. Hosts the annual International Arts & Crafts Festival (Dec–Jan); the riverside setting makes it a pleasant day outing even outside festival time.', '2–3 hours (half-day trip)', 'October to March; December–January during the crafts festival', 'Bargaining is gentle and expected; many artisans demonstrate their craft live. Closed on Mondays. Hours and entry fee conflict across sources — confirm before visiting.', NULL, 'Kerala', 0, 0, NULL, NULL, NULL, 4, 4, 11.5449, 75.61, 'Iringal, Kozhikode District, Kerala 673521 (about 28 km north of the city, on the Moorad river)', NULL, 0.8);

