INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 840000116, 'insert', 'bulk', 'Coordinates approximate (Iringal). Opening date (19 Feb 2011), 20 acres and closed-Mondays from published sources. Hours (10 AM–8 PM vs 10 AM–6 PM) and fees conflict — both set to null.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000117, 840005, 'S.M. Street (Sweet Meat Street)', 'S.M. Street (Sweet Meat Street)', 'A roughly 600-year-old market street — and one of India''s oldest — founded when the Zamorin invited Gujarati sweet-makers to settle here; the famed Kozhikodan halwa traces to the Arab sweet ''hulw''. Now pedestrianized with a 2017 facelift, it is lined with halwa shops, textile stores and eateries, with a statue of writer S.K. Pottekkatt at one end.', '1–2 hours', 'Year-round; evenings when the street is liveliest', 'Taste-test halwa at a couple of shops before buying — varieties range from black to red to green. The street is about 2 km; start at the Mananchira end and walk to the beach side.', NULL, 'Kerala', 0, 0, NULL, NULL, 'Free', 5, 4, 11.2565, 75.779, 'S.M. Street (Sweet Meat Street), Kozhikode, Kerala 673001', NULL, 0.92);

