INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000118, 840005, 'Valayanad Devi Temple', 'Valayanad Devi Temple', 'The family deity temple of the Zamorins, dedicated to the goddess in the Saktheya (Rurujit) tradition, with four gopurams. Legend says the goddess arrived here as bangles on a devotee''s arms — hence ''Thiruvalayanad'' (holy bangle-land). An important Shakti shrine with centuries of royal patronage.', '45 minutes – 1 hour', 'October to March; Navratri and festival days are busiest', 'A quieter alternative to the busier city temples; the annual festival season draws the biggest crowds. Temple timings were not found in published sources — call ahead or visit in the morning.', NULL, 'Kerala', 0, 0, NULL, NULL, 'Free', 3, 4, 11.24361, 75.80361, 'Valayanad Temple Road, Govindapuram, Kozhikode, Kerala 673007', NULL, 0.68);

