INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000119, 840005, 'Peruvannamuzhi Dam', 'Peruvannamuzhi Dam', 'A dam and reservoir in the Western Ghats foothills, renovated in 2025 with a Rs 3.14 crore upgrade adding a children''s park, solar boats and landscaped gardens. The complex also houses a crocodile shelter, a wild-animal rehabilitation centre and a small bird sanctuary — a full nature day trip.', '3–4 hours (full-day trip with drive)', 'October to March', 'The 2025 renovation added solar boat rides — worth trying. It is a 1.5–2 hour drive each way, so start early and pair it with nearby Kakkayam if time permits. Hours (8 AM–5 PM vs 8 AM–6 PM) and fees conflict — confirm locally.', NULL, 'Kerala', 0, 0, NULL, NULL, NULL, 3, 4, 11.597, 75.825, 'Peruvannamuzhi, Chakkittapara Panchayat, Kozhikode District, Kerala 673595 (about 55–60 km northeast of the city)', NULL, 0.68);

