INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000120, 840005, 'Conolly Canal', 'Conolly Canal', 'An 11.4 km historic canal built in 1848 on the orders of H.V. Conolly, then Malabar Collector, to move goods between the Kuttiyadi and Korapuzha river systems and Kallayi port. A trading artery until the 1950s, it is now mostly a drainage channel with revival efforts underway; the Sarovaram Bio Park sits beside it.', '30–45 minutes', 'October to March', 'Not a conventional sight — best appreciated as a heritage walk along the Sarovaram stretch, where the canal meets the bio park. Do not expect boating; this is for history buffs.', NULL, 'Kerala', 0, 0, NULL, NULL, 'Free', 2, 3, 11.2558, 75.7804, 'Runs through Kozhikode city, from Korapuzha in the north to Kallai (Chaliyar river) in the south', NULL, 0.48);

