INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000121, 840005, 'Varakkal Beach', 'Varakkal Beach', 'The quieter northern stretch of Kozhikode''s coastline near West Hill, entered through a distinctive stone arch with sculpted rocks. Less crowded than the main beach, making it a favourite local sunset spot with an uninterrupted horizon.', '1–2 hours', 'October to March; evenings for sunset', 'Come for sunset rather than swimming — facilities are minimal. The stone arch entrance and rock sculptures make it more photogenic than the main beach.', NULL, 'Kerala', 0, 1, NULL, '6:18 PM', 'Free', 3, 4, 11.295, 75.771, 'Beach Road, West Hill, Kozhikode, Kerala 673005 (about 5 km north of the city centre)', NULL, 0.68);

