INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000122, 840005, 'Azhakodi Devi Temple', 'Azhakodi Devi Temple', 'A prominent Bhadrakali temple (also housing Bhavani Devi) administered by the Malabar Devaswom Board. Originally known as Arikkodikkavu, it was renamed Azhakodi in 1965; legend links the Bhavani idol to Gujarati traders. One of the few Kerala Devi temples where Guruthi is performed inside the sreekovil.', '45 minutes – 1 hour', 'October to March; Navratri is the main festival', 'Morning pooja schedule runs 5 AM (nada opening) through 11 AM closing; evening 5–8 PM with deeparadhana around sunset. The temple also runs a large kalyana mandapam for weddings.', NULL, 'Kerala', 0, 0, NULL, NULL, 'Free', 3, 4, 11.26381, 75.7891, 'Thiruthiyad, Puthiyara, Kozhikode, Kerala 673004', 'https://azhakoditemple.org', 0.68);

