INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000123, 840005, 'Lion''s Park', 'Lion''s Park', 'A small family amusement park right on Kozhikode Beach near the old lighthouse, with basic rides and play equipment for children. Popular as a sunset-time family stop combined with the beach''s street-food shacks.', '1–2 hours', 'Year-round; late afternoon to evening', 'Pair it with sunset on the beach and snacks from the nearby shacks. Entry fee and hours come from a single unofficial source — confirm on arrival.', NULL, 'Kerala', 0, 1, NULL, '6:18 PM', 'Rs 15 adults / Rs 10 children (single unofficial source — verify at gate)', 2, 3, 11.2572, 75.7688, 'Beach Road, near the old lighthouse, Kozhikode, Kerala 673032', NULL, 0.48);

