INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 840000123, 'insert', 'bulk', 'Coordinates approximate (near old lighthouse on Kozhikode Beach). Fee (Rs 15/10) and hours (3–8 PM) from a single unofficial source — recorded with caveat.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000124, 840005, 'Mother of God Cathedral', 'Mother of God Cathedral', 'Locally called Valiya Palli, this is the headquarters of the Roman Catholic congregation in Malabar and one of Kerala''s oldest churches. Founded as ''Matri Dei'' in 1513 under a Portuguese–Zamorin treaty, rebuilt in stone in 1724–25, and made the Cathedral of the Diocese of Calicut in 1923. Italian-designed Gothic/Neo-Roman facade, a 200-year-old portrait of St Mary, and the tomb of Pedro de Covilhany, the first Catholic missionary to visit Kozhikode.', '45 minutes – 1 hour', 'Year-round; mornings are peaceful', 'Dress modestly; visit early morning for the peaceful light. Daily Mass is at 6:30 AM (Mon–Sat) and Sunday Mass runs morning to evening — check timings if you want to attend. No fixed visitor hours published.', NULL, 'Kerala', 0, 0, NULL, NULL, 'Free', 4, 4, 11.2517, 75.7758, 'Convent Road, Near District Court, Mananchira, Kozhikode, Kerala 673032', NULL, 0.8);

