INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 840000124, 'insert', 'bulk', 'Coordinates approximate (Convent Rd near District Court; plus-code 7Q3F+7J9). History corroborated by Kerala Tourism (1513 founding, 1724 rebuild, 1923 cathedral, Italian architects, 200-year-old St Mary portrait). No published visitor hours — set to null.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000125, 840005, 'Paragon Restaurant', 'Paragon Restaurant', 'Kozhikode''s most famous restaurant, founded in 1939 by Govindan Panhikeyil as a Moplah-cuisine eatery. Its Malabar biryani — served with coconut chammandi and Kerala pappadam — was ranked among the world''s most legendary restaurant dishes by TasteAtlas. Now a group with outlets across Kerala and Dubai.', '1–1.5 hours', 'Lunch or dinner; expect a wait at peak hours', 'The chicken biryani is the signature order; prawn dry fry, pan-fried mussels and mango fish curry are standouts. Visit off-peak or reserve — weekend lunches have long waits.', NULL, 'Kerala', 0, 0, NULL, NULL, NULL, 5, 5, 11.262, 75.7785, 'Near CH Over Bridge, Kannur Road, Kozhikode, Kerala 673001', NULL, 1.0);

