INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000126, 840005, 'Hotel Rahmath', 'Hotel Rahmath', 'A simple, no-frills Keralan joint started in 1961, legendary for its beef biryani — widely considered the benchmark Calicut beef biriyani. Also known for milk sarbath, fish fry and generous parking; watch out for similarly-named imitators.', '1 hour', 'Lunch for biryani; open morning to late night', 'Order the beef biriyani — that is what everyone comes for — and finish with the milk sarbath. Many duplicate ''Rahmath'' hotels exist; the original is the Aravind Ghosh Road one near the Mathrubhumi office.', NULL, 'Kerala', 0, 0, NULL, NULL, 'Rs 200–500 per person (unofficial travel site estimate)', 5, 4, 11.251645, 75.779112, 'Aravind Ghosh Road, near Mathrubhumi Office, Mananchira, Kozhikode, Kerala 673001', NULL, 0.92);

