INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 840000126, 'insert', 'bulk', 'Started 1961, beef-biryani fame, address and coordinates from the business''s own Google site (hotelrahmath.business.site, not fetched as a website) — coordinates approximate. Hours (7 AM–11 PM) from the same listing. Cost is an unofficial estimate — recorded with caveat.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000127, 840005, 'Zains Hotel', 'Zains Hotel', 'Kozhikode''s first lady restaurateur — Mrs Zainabi Noor''s homestyle Mappila kitchen, started 32 years ago as a small evening-snacks tea stall and now the city''s address for home-style Malabar Muslim food. Set in a converted house with an all-women kitchen; famous for chicken biryani, erachi pathiri (meat pie) and spiced sulaimani tea.', '1 hour', 'Lunch', 'Do not expect a printed menu — the staff will tell you what is on offer. Try the erachi pathiri, ari kadukka and chicken biryani with sulaimani. No official website found.', NULL, 'Kerala', 0, 0, NULL, NULL, NULL, 4, 5, 11.2498, 75.775, 'Convent Cross Road, Behind Fire Station, Kozhikode, Kerala 673032', NULL, 0.88);

