INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000128, 840005, 'Hotel Sagar', 'Hotel Sagar', 'A Kozhikode institution since the 1970s, describing itself as ''a legacy of Kozhikode flavours''. A huge multi-cuisine menu anchored in Malabar classics — meen molagathu curry, Kozhikodan chicken dum biryani with kaima rice, porotta and idiappam — plus a gourmet store.', '1 hour', 'Lunch or dinner', 'The meen molagathu (spicy-sour fish curry) with rice pathiri is a standout. It is right by the KSRTC stand, so it is the easiest classic meal if you are arriving by bus.', NULL, 'Kerala', 0, 0, NULL, NULL, NULL, 4, 4, 11.259011, 75.781758, 'Mavoor Road, Near KSRTC Bus Stand, Palayam, Kozhikode, Kerala 673004', NULL, 0.8);

