INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 840000128, 'insert', 'bulk', 'Since 1970s per the business''s own Facebook page. Coordinates from the same page (approximate). Hours (7:15 AM–11:45 PM) from justdial single source — recorded with caveat. No official website found.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000129, 840005, 'Topform Restaurant', 'Topform Restaurant', 'One of the classic Malabar trio (with Paragon and Sagar) serving north Kerala cuisine for decades. Known for kozhi nirachathu (thick chicken gravy), avoli moli, mutton biryani and Kerala porotta; family-friendly and affordable with very long operating hours.', '1 hour', 'Lunch or dinner', 'Order the kozhi nirachathu with wheat parotta or pathiri, and the avoli moli if you like fish. The ''Malabar trio'' reputation means it is busy at peak meal times.', NULL, 'Kerala', 0, 0, NULL, NULL, NULL, 3, 4, 11.258744, 75.782153, 'Ground & 1st Floor, Golden Plaza Building, Mavoor Road, Opp KSRTC Bus Stand, Kozhikode, Kerala 673001', NULL, 0.68);

