INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 840000129, 'insert', 'bulk', 'Address and coordinates from topform.in listing (not fetched as a website) — approximate. Hours conflict across sources (6 AM–2 AM vs 11 AM–5:30 AM) — set to null. Price reports suggest ~Rs 200–400 per person (unofficial).', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000130, 840005, 'Arya Bhavan', 'Arya Bhavan', 'A pure-vegetarian institution established in 1945 on S.M. Street, one of Kozhikode''s oldest veg restaurants. Classic South Indian fare — masala dosa, puttu-kadala, vada, pazham pori and veg biryani — at old-school prices, steps from Mananchira Square.', '45 minutes – 1 hour', 'Breakfast or lunch', 'The go-to vegetarian stop near SM Street and Mananchira — try the puttu-kadala breakfast or masala dosa. Hours conflict across sources (7 AM–9 PM vs 10 AM–8 PM) — confirm locally.', NULL, 'Kerala', 0, 0, NULL, NULL, 'Rs 350 for two (unofficial listing estimate)', 4, 4, 11.2565, 75.7805, 'No. 10/87, Mannanchira, S.M. Street, Kozhikode, Kerala 673001', NULL, 0.8);

