INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8400022, 840, 840005, 'Malabar Mahotsavam', 'Jan', 'Kozhikode District Tourism Promotion Council''s flagship cultural festival, held since 1992 across venues including Mananchira Maidan, Kozhikode Beach, Thali Heritage Open Stage and Sarovaram. Four to five days of classical and folk arts, theatre, gazals, rock concerts, martial arts like Kalaripayattu and Theyyam showcases, food stalls serving Malabar cuisine, and amusement rides.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8400023, 840, 840005, 'Revathi Pattathanam', 'Oct–Nov', 'A centuries-old scholarly assembly held at the Tali Maha Shiva Temple, where Vedic scholars gather for debates and recitations. One of Kerala''s oldest continuing intellectual traditions, rooted in the Zamorin era.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8400024, 840, 840005, 'Sargaalaya International Arts & Crafts Festival', 'Dec–Jan', 'Annual international crafts fair at the Sargaalaya Kerala Arts & Crafts Village in Iringal, drawing artisans from across India and abroad. Live craft demonstrations, folk performances and stalls selling handmade textiles, woodwork, metal craft and more.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8400025, 840, 840005, 'Beypore International Water Fest', 'Dec', 'Water-sports and tourism festival at Beypore celebrating the port town''s seafaring heritage. Speedboat service connecting Kozhikode Beach to Beypore, parasailing, kayaking demos, cultural programmes and seafood stalls.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8400026, 840, 840005, 'Theyyam Season', 'Dec–Mar', 'The ritual dance-theatre season of North Malabar, when kavus (sacred groves) and ancestral shrines across the Kozhikode–Kannur region host all-night Theyyam performances — elaborate face paint, towering headgear, chenda drumming and trance worship. Performances are religious rituals, not staged shows; go with a local guide and dress modestly.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8400027, 840, 840005, 'Kerala Literature Festival', 'Jan', 'One of Asia''s largest literature festivals, held on Kozhikode Beach each January. Hundreds of authors, poets and thinkers across sessions in English, Malayalam and other Indian languages, plus cultural performances and book stalls.');

