INSERT OR IGNORE INTO photos (id, place_id, source_file, thumbnail_url, thumbnail_width, thumbnail_height, photo_title, photo_author, license, license_url, source_url, credit, usage_terms, description) VALUES (840800066, 840000093, 'File:Ambalappuzha Sree Krishna Temple 01.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/71/Ambalappuzha_Sree_Krishna_Temple_01.jpg/960px-Ambalappuzha_Sree_Krishna_Temple_01.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 800, 600, 'Ambalappuzha Sree Krishna Temple 01', 'Vijayanrajapuram', 'CC BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 'https://commons.wikimedia.org/wiki/File:Ambalappuzha_Sree_Krishna_Temple_01.jpg', 'Own work', 'Creative Commons Attribution-Share Alike 4.0', 'Sree Krishna Swamy Temple, commonly known as Ambalappuzha Sree Krishna Swamy Temple is an Indian Hindu temple dedicated to Krishna at Ambalappuzha in Alappuzha district of Kerala.');

INSERT OR IGNORE INTO photos (id, place_id, source_file, thumbnail_url, thumbnail_width, thumbnail_height, photo_title, photo_author, license, license_url, source_url, credit, usage_terms, description) VALUES (840800067, 840000094, 'File:View of Pathiramanal Island.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/26/View_of_Pathiramanal_Island.jpg/960px-View_of_Pathiramanal_Island.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 800, 533, 'View of Pathiramanal Island', 'SidhardhRamesh', 'CC BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 'https://commons.wikimedia.org/wiki/File:View_of_Pathiramanal_Island.jpg', 'Own work', 'Creative Commons Attribution-Share Alike 4.0', 'Pathiramanal is a small island in Muhamma panchayat of Alappuzha district. The name Pathiramanal means ''sands of night''. The scenic beauty of both sides of the lake as well as that of the island is mind blowing. It is home to many rare varieties of migratory birds from different parts of the world.');

