INSERT OR IGNORE INTO photos (id, place_id, source_file, thumbnail_url, thumbnail_width, thumbnail_height, photo_title, photo_author, license, license_url, source_url, credit, usage_terms, description) VALUES (840800074, 840000106, 'File:Kappad Beach.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7b/Kappad_Beach.jpg/960px-Kappad_Beach.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 800, 533, 'Kappad Beach.jpg', 'SidhardhRamesh', 'CC BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 'https://commons.wikimedia.org/wiki/File:Kappad_Beach.jpg', 'SidhardhRamesh / Wikimedia Commons (CC BY-SA 4.0)', 'Creative Commons Attribution-Share Alike 4.0', 'Kappad, or Kappakadavu locally, is a beach near Kozhikode, in the district of the same name, Kerala, India. A stone monument installed by government commemorates the "landing" by Vasco da Gama with the inscription, ''Vasco da Gama landed here, Kappakadavu, in the year 1498''.');

INSERT OR IGNORE INTO photos (id, place_id, source_file, thumbnail_url, thumbnail_width, thumbnail_height, photo_title, photo_author, license, license_url, source_url, credit, usage_terms, description) VALUES (840800075, 840000107, 'File:Beypore Beach, Kozhikode, Kerala.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6c/Beypore_Beach%2C_Kozhikode%2C_Kerala.jpg/960px-Beypore_Beach%2C_Kozhikode%2C_Kerala.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 800, 600, 'Beypore Beach, Kozhikode, Kerala.jpg', 'Rahul Bose', 'CC BY-SA 3.0', 'https://creativecommons.org/licenses/by-sa/3.0', 'https://commons.wikimedia.org/wiki/File:Beypore_Beach%2C_Kozhikode%2C_Kerala.jpg', 'Rahul Bose / Wikimedia Commons (CC BY-SA 3.0)', 'Creative Commons Attribution-Share Alike 3.0', 'Located at the mouth of the Chaliyar River in Kozhikode district, Beypore, one of the prominent ports and fishing harbours of ancient Kerala was an important trade and maritime centre. Ancient Beypore was much sought after by merchants from Western Asia, for its ship building industry. The boat building yard here is famous for the construction of the Uru, the traditional Arabian trading vessel.');

