INSERT OR IGNORE INTO photos (id, place_id, source_file, thumbnail_url, thumbnail_width, thumbnail_height, photo_title, photo_author, license, license_url, source_url, credit, usage_terms, description) VALUES (840800079, 840000111, 'File:09192022 Tali Shiva Mahakshetra temples, Kozhikode 220.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/13/09192022_Tali_Shiva_Mahakshetra_temples%2C_Kozhikode_220.jpg/960px-09192022_Tali_Shiva_Mahakshetra_temples%2C_Kozhikode_220.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 800, 600, '09192022 Tali Shiva Mahakshetra temples, Kozhikode 220.jpg', 'Ms Sarah Welch', 'CC0', 'http://creativecommons.org/publicdomain/zero/1.0/deed.en', 'https://commons.wikimedia.org/wiki/File:09192022_Tali_Shiva_Mahakshetra_temples%2C_Kozhikode_220.jpg', 'Ms Sarah Welch / Wikimedia Commons (CC0)', 'Creative Commons Zero, Public Domain Dedication', 'The Thali temple of Kozhikode, also called the Tali Shiva Mahakshetra, is a historic site from the Chera dynasty era. The current complex of temples, mandapam and pushkarini (temple water tank) has roots in the 10th to 12th century Hindu Zamorins period. The site was expanded in the 14th century. The Thali temple of Kozhikode – originally Sthali temple – is among the eighteen Hindu temples along t');

