INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000132, 840006, 'Periyar Lake Boating', 'Periyar Lake Boating', 'The classic Periyar experience: a motorboat cruise on Periyar Lake past drowned-tree snags where elephants, sambar, otters and cormorants come to the water''s edge. Boats run in fixed slots from the jetty inside the reserve; tickets sell out, so book at the counter early in the day.', '2 hours', 'September to March', 'Take the 7:30 AM or 3:30 PM slot for the best light and the highest chance of elephant sightings.', 'yes', 'Kerala', 0, 1, '6:09 AM', '6:12 PM', 'Rs 255 (adult); Rs 85 (child)', 5, 4, 9.59767, 77.17291, 'Boat jetty at the sanctuary entrance, Lake Road, Thekkady 685509 (inside Periyar Tiger Reserve)', NULL, 0.92);

