INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000133, 840006, 'Bamboo Rafting, Periyar Tiger Reserve', 'Bamboo Rafting, Periyar Tiger Reserve', 'The reserve''s signature eco-tourism program: a dawn trek through forest with armed guards followed by bamboo-rafting across the lake''s quieter arms, with chances of wild elephant and gaur sightings. Two shifts run daily; participants report at Bamboo Grove inside the reserve, and the Rs 33 reserve entry is charged on top.', 'Half day to full day', 'September to March', 'Book a day ahead at the forest department eco-tourism counter - seats per shift are limited.', 'yes', 'Kerala', 0, 0, '6:09 AM', '6:12 PM', 'Rs 1,500-2,200 (half day); Rs 2,500-2,900 (full day); +Rs 33 reserve entry', 5, 5, 9.59767, 77.17291, 'Report at Bamboo Grove inside Periyar Tiger Reserve, Thekkady 685509', NULL, 1.0);

