INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000136, 840006, 'Mangaladevi Temple', 'Mangaladevi Temple', 'An ancient stone temple at 1,337 m deep inside the tiger reserve, built in traditional Kerala style. It opens to devotees on just one day a year - Chithra Pournami (April-May full moon) - when thousands trek or take shared jeeps up the forest track; the peak also gives sweeping views over the Tamil Nadu plains.', 'Half day', 'Chithra Pournami day (April-May)', 'If you are in Kumily around the April-May full moon, arrange a jeep the previous evening - seats fill fast.', 'no', 'Kerala', 0, 1, '6:09 AM', '6:12 PM', 'No temple entry fee; shared jeeps approx Rs 150 per person', 4, 5, 9.59883, 77.22092, 'Inside Periyar Tiger Reserve, ~11-15 km by jeep track from Kumily, Idukki, Kerala', NULL, 0.88);

