INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000137, 840006, 'Elephant Junction', 'Elephant Junction', 'Kumily''s best-known elephant experience centre: rides through plantation trails plus bathing, feeding and ''premium'' full/half-day mahout-style programs. Packages run from a 30-minute ride to a full day with the elephants; the bathing session is the highlight most visitors mention.', '2-4 hours', 'September to March', 'Carry a change of dry clothes - the bathing session will soak you.', 'yes', 'Kerala', 0, 0, '6:09 AM', '6:12 PM', 'Rs 700 (30-min ride) to Rs 10,000 (full day); 1-hr Rs 1,500; 1-hr premium Rs 1,700; 1.5-hr premium Rs 2,200; half day Rs 5,500', 4, 4, 9.618405, 77.146384, 'Murukkady P.O., Thekkady, Idukki, Kerala 685509', 'http://elephantjunction.in/', 0.8);

