INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000140, 840006, 'Kumily Spice Market', 'Kumily Spice Market', 'The trading heart of India''s cardamom country - Kerala tourism calls Kumily home to one of the world''s biggest cardamom markets. The market streets around Alady Road are lined with shops selling cardamom, pepper, coffee, tea, dried fruits and ayurvedic products; bargaining is expected.', '1-2 hours', 'Year round', 'Taste before you buy; genuine Kumily cardamom is plump, green and strongly aromatic.', 'no', 'Kerala', 0, 0, '6:09 AM', '6:12 PM', NULL, 4, 3, 9.60953, 77.16002, 'Kumily Alady Road, Kumily, Idukki, Kerala 685509', NULL, 0.72);

