INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000144, 840006, 'Ottakathalamedu Viewpoint', 'Ottakathalamedu Viewpoint', 'A watch-tower and rock viewpoint on Ottakathalamedu View Point Road near 1st Mile Kumily, known for panoramas over Kumily town and glimpses of Thekkady lake. Listed among Thekkady''s trekking/view points by Kerala tourism and local operators.', '1 hour', 'September to March', 'Evening light is best for the town-and-lake panorama from the tower.', 'no', 'Kerala', 0, 1, '6:09 AM', '6:12 PM', NULL, 3, 4, 9.623203, 77.159988, 'Ottakathalamedu View Point Road, Kumily, Idukki, Kerala 685509', NULL, 0.68);

