INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000145, 840006, 'Gavi', 'Gavi', 'A pristine forest enclave inside the Periyar landscape, about 40 km from Kumily and run as an eco-tourism zone by the Kerala Forest Development Corporation. Day packages (around Rs 900) and overnight stays (Rs 2,200-2,500) cover guided treks, birding and the Gavi lake; entry passes are issued at the Vallakkadavu check post. A classic Kumily day trip for serious nature lovers.', 'Full day', 'September to March', 'Book the KFDC package in advance; private vehicles need the check-post pass and forest rules are strict.', 'yes', 'Kerala', 0, 0, '6:09 AM', '6:12 PM', 'Rs 25 per person + Rs 50 per vehicle (entry); KFDC day package ~Rs 900; overnight Rs 2,200-2,500', 5, 5, 9.43873, 77.15942, 'Gavi, Pathanamthitta district, Kerala (~40 km from Kumily; entry pass at Vallakkadavu check post)', NULL, 1.0);

