INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000147, 840006, 'Mullaperiyar Dam', 'Mullaperiyar Dam', 'The historic 1895 masonry gravity dam on the Periyar, 175 ft high and 1,200 ft long, built under a 999-year lease and still operated by Tamil Nadu. A short day trip from Kumily through forest-fringe roads; the reservoir views and the dam''s colonial engineering history are the draw.', '2-3 hours', 'September to March', 'Carry ID; the dam is a high-security installation with restricted zones.', 'no', 'Kerala', 0, 0, '6:09 AM', '6:12 PM', 'Free', 3, 3, 9.529, 77.14375, 'Mullaperiyar, Idukki, Kerala (~23-26 km from Kumily)', NULL, 0.6);

