INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000148, 840006, 'Vandanmedu', 'Vandanmedu', 'A plantation town about 25 km from Kumily that hosts one of the world''s largest cardamom auction centres. Walks through the sprawling cardamom estates and a look at the auction halls show the commercial side of the spice country Kumily is famous for.', 'Half day', 'September to March', 'Visit on an auction day morning to see the cardamom trade in full swing.', 'no', 'Kerala', 0, 0, '6:09 AM', '6:12 PM', NULL, 3, 3, 9.72602, 77.15533, 'Vandanmedu, Idukki, Kerala 685551 (~25 km from Kumily)', NULL, 0.6);

