INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000149, 840006, 'Parunthumpara', 'Parunthumpara', 'Eagle Rock - a sheer cliff viewpoint at about 1,400 m, roughly 30 km from Kumily near Peermade. The eagle-beak-shaped rock overhangs a vast valley panorama; it is famous for sunsets and, during the Sabarimala season, the Makarajyothi flame is visible from here. Free entry, open all day.', '2 hours', 'September to March', 'Time your visit for sunset; stay behind the railings - the drop is sheer.', 'no', 'Kerala', 0, 1, '6:09 AM', '6:12 PM', 'Free', 5, 5, 9.5496, 77.03728, 'Parunthumpara, near Peermade, Idukki, Kerala (~30 km from Kumily, 6 km from Peermade)', NULL, 1.0);

