INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000150, 840006, 'Panchalimedu', 'Panchalimedu', 'A high meadow viewpoint at about 950 m, reached by road from Kumily via Kuttikkanam and Murinjapuzha (roughly 50 km). Named for Panchali of the Mahabharata, who legend says bathed in the Panchalikulam pond here; the Bhuvaneswari temple, grasslands and 360-degree valley views draw trekkers, film crews (the Malayalam hit ''Charlie'' was shot here) and, in season, Sabarimala pilgrims watching for the Makaravilakku. Managed by the Idukki District Tourism Promotion Council.', 'Half day', 'October to January', 'Go on a clear winter morning - mist can hide the valley views by afternoon.', 'no', 'Kerala', 1, 1, '6:09 AM', '6:12 PM', 'Rs 25 (adult); Rs 15 (child 10-15 years, senior citizen); Rs 60 (camera)', 4, 4, 9.52939, 76.97342, 'Panchalimedu, Peerumade, Idukki, Kerala 685532 (~50 km by road from Kumily via Kuttikkanam-Murinjapuzha)', NULL, 0.8);

