INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8400028, 840, 840006, 'Onam', 'Aug-Sep', 'Kerala''s biggest harvest festival, celebrated across Kumily with pookalam (flower carpets), traditional sadhya feasts, folk performances and decorated streets; the town''s markets and homestays are at their liveliest.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8400029, 840, 840006, 'Vishu', 'Apr', 'The Malayalam New Year, marked in Kumily and Peermade with the vishukkani ritual arrangement, temple visits, fireworks and festive meals at the start of the summer season.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8400030, 840, 840006, 'Chithra Pournami at Mangaladevi Temple', 'Apr-May', 'The one day each year the ancient Mangaladevi Temple inside Periyar Tiger Reserve opens to devotees - on the Chithra Pournami full moon. Thousands of pilgrims trek or take shared jeeps from Kumily up the forest track for the festival.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8400031, 840, 840006, 'Sabarimala Mandala-Makaravilakku Season', 'Nov-Jan', 'The annual Sabarimala pilgrim season; Kumily (~40 km by road from Sabarimala) fills with pilgrims, and the sacred Makarajyothi flame is visible from viewpoints like Parunthumpara and Panchalimedu on Makaravilakku day.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8400032, 840, 840006, 'Christmas', 'Dec', 'Celebrated at Kumily and Peermade churches with midnight mass, carols and illuminated streets, coinciding with the peak December tourist season in Thekkady.');

