INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8400033, 840, 1047, 'Onam', 'Aug-Sep', 'Kerala''s state harvest festival; Thiruvananthapuram hosts the official state Onam week celebrations at Kanakakkunnu grounds with cultural programs, food festivals and the famed Pookalam (flower rangoli) displays.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8400034, 840, 1047, 'Attukal Pongala', 'Feb-Mar', 'Mass women''s gathering at Attukal Bhagavathy Temple, Thiruvananthapuram (~16 km) — among the world''s largest single-day women''s congregations. Devotees cook sweet pongala in earthen pots in rows along the streets on the Pooram star of Meenam.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8400035, 840, 1047, 'Soorya Festival', 'Sep-Oct', 'Thiruvananthapuram''s 111-day arts festival by the Soorya Stage and Film Society (2024 edition ran Oct 2, 2024–Jan 21, 2025) — the world''s longest art festival. Opens with a 10-day dance-and-music festival (Oct 1–10) featuring leading classical dancers and musicians; theatre, film, and Parampara segments follow.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8400036, 840, 1047, 'Swathi Sangeethotsavam', 'Jan', 'Week-long Carnatic music festival at Kuthiramalika Palace, Thiruvananthapuram (~16 km), celebrating Maharaja Swathi Thirunal''s compositions, performed on the palace forecourt.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8400037, 840, 1047, 'Nishagandhi Dance Festival', 'Jan', 'Week-long classical dance festival (Jan 20–27, per Kerala Tourism convention) at the Nishagandhi open-air auditorium, Kanakakkunnu Palace grounds, Thiruvananthapuram — Kathak, Bharatanatyam, Odissi, Kuchipudi, Manipuri, Mohiniyattam; free entry.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8400038, 840, 1047, 'Navaratri Mandapam Music Festival', 'Sep-Oct', 'Nine-night Carnatic music festival at the Navaratri Mandapam in the Sree Padmanabhaswamy Temple fort complex, Thiruvananthapuram (~16 km), coinciding with Navaratri/Dussehra.');

