INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000183, 840007, 'Chembra Peak', 'Chembra Peak', 'Chembra Peak, at about 2,100 m, is the highest peak in Wayanad and the most famous trek in the district. The trek passes through tea estates, grasslands and forest to a heart-shaped lake (Chembra lake) midway. Since 2019 the summit itself has been closed to trekkers for ecological reasons; the permitted trek ends at the heart-shaped lake. Permits are issued by the forest department and group sizes are limited.', '5-6 hours (trek)', 'September to March', 'Start the trek before 9 AM - afternoon clouds hide the views; carry water and snacks, there are no shops on the trail.', 'yes', 'Kerala', 1, 1, '6:14 AM', '6:16 PM', 'Rs 4000', 5, 5, 11.51222, 76.08944, 'Near Meppadi, Wayanad, Kerala 673577', NULL, 1.0);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (840000183, 840000183, '7:00 AM - 5:00 PM', '7:00 AM - 5:00 PM', '7:00 AM - 5:00 PM', '7:00 AM - 5:00 PM', '7:00 AM - 5:00 PM', '7:00 AM - 5:00 PM', '7:00 AM - 5:00 PM', 'No entry after 2:00 PM; trekkers must return before 5:00 PM. Forest department permit required, booked at the forest office/check post near Meppadi. Older sources (gowayanad) quoted Rs 750 for a group of 10 - rates have since been revised upward.');

