INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 840000183, 'insert', 'bulk', 'Real; coordinates (11.51222, 76.08944) from Wikipedia (Chembra Peak article). Entry fee conflicts across sources: stayvista (recent) quotes Rs 4,000 for a group of 5 Indians + Rs 800/extra person, Rs 50/person entry, Rs 1,000 student group; older gowayanad quoted Rs 750 for a group of 10 - used the most recent published figures. Summit closed to trekkers since 2019; trek legally ends at the heart-shaped lake. Hours 7 AM-5 PM with no entry after 2 PM.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000184, 840007, 'Edakkal Caves', 'Edakkal Caves', 'The Edakkal Caves are not true caves but a natural rock shelter formed by a huge boulder wedged between two rocks, bearing Neolithic petroglyphs (rock engravings) dating back at least 6,000 years. The carvings - human and animal figures, tools and symbols - make it one of Kerala''s most important prehistoric sites. Reaching it requires a ~1 km uphill walk from the parking area followed by a steep climb up stairs to the rock formation.', '2-3 hours', 'September to March', 'The final climb is steep with uneven steps - wear grippy footwear and avoid the midday heat.', 'no', 'Kerala', 0, 0, '6:14 AM', '6:16 PM', 'Rs 50', 5, 4, 11.6246694, 76.2358, 'Edakkal, near Ambalavayal, Wayanad, Kerala 673593', NULL, 0.92);

