INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000185, 840007, 'Banasura Sagar Dam', 'Banasura Sagar Dam', 'Banasura Sagar is the largest earthen dam in India and the second largest in Asia, built across the Karamanathodu tributary of the Kabini river in the foothills of Banasura Hill. The vast reservoir dotted with small islands is a popular boating and picnic spot, with speed boats, a zipline across the reservoir and views of the Banasura peak reflected in the water.', '3-4 hours', 'September to March', 'Evening light on the reservoir with Banasura Hill behind is the best photo window; boating queues are long on weekends.', 'no', 'Kerala', 1, 1, '6:14 AM', '6:16 PM', 'Rs 40', 5, 4, 11.67, 75.95778, 'Padinjarathara, Wayanad, Kerala 673575', NULL, 0.92);

