INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000186, 840007, 'Soochipara Falls', 'Soochipara Falls', 'Soochipara (Sentinel Rock) Falls is a three-tiered waterfall dropping about 200 m through dense forest near Meppadi, about 22 km from Kalpetta. The lowest pool is a popular natural swimming spot, and the area around the falls has rock-climbing routes. Reaching the base involves a 1-2 km trek downhill from the parking area through forest.', '2-3 hours', 'September to December', 'The steps down to the falls are slippery - wear shoes with grip; carry a change of clothes if you plan to swim.', 'no', 'Kerala', 0, 0, '6:14 AM', '6:16 PM', 'Rs 80', 4, 4, 11.51222, 76.16306, 'Near Meppadi, Wayanad, Kerala 673577', NULL, 0.8);

