INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000187, 840007, 'Pookode Lake', 'Pookode Lake', 'Pookode Lake is a scenic freshwater lake ringed by evergreen forest and rolling hills, about 3 km south of Vythiri and 15 km from Kalpetta. It offers pedal and row boating, a freshwater aquarium, a children''s park and a small handicrafts shop. The lake''s shape is said to resemble the map of India.', '1-2 hours', 'September to March', 'Go in the morning for calm water and better boating slots; the aquarium and park make it a good family stop.', 'no', 'Kerala', 1, 1, '6:14 AM', '6:16 PM', 'Rs 40', 4, 4, 11.5431, 76.0342, 'Pookode, near Vythiri, Wayanad, Kerala 673576', NULL, 0.8);

