INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000188, 840007, 'Kuruva Island', 'Kuruva Island', 'Kuruvadweep (Kuruva Island) is a 950-acre cluster of densely forested islands in the Kabini river near the Kerala-Karnataka border, about 30 km from Kalpetta via Mananthavady. Reached by bamboo raft, it has walking trails through evergreen forest rich in birds, butterflies and orchids. Daily visitor numbers are capped by the forest department and the islands close during the monsoon when the river floods.', '3-4 hours', 'December to April', 'Arrive by 10 AM to beat the daily visitor cap; carry drinking water, there are no shops on the islands.', 'yes', 'Kerala', 0, 0, '6:14 AM', '6:16 PM', 'Rs 80', 4, 4, 11.82167, 76.09222, 'Kuruva Island, near Pulpally, Wayanad, Kerala 673579', NULL, 0.8);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (840000188, 840000188, '9:30 AM - 3:30 PM', '9:30 AM - 3:30 PM', '9:30 AM - 3:30 PM', '9:30 AM - 3:30 PM', '9:30 AM - 3:30 PM', '9:30 AM - 3:30 PM', '9:30 AM - 3:30 PM', 'Ticket counters open 9:30 AM-3:30 PM; visitors are let in until early afternoon. Closed in the monsoon roughly May/June to early December; daily visitor caps mean weekend slots can sell out.');

