INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000189, 840007, 'Lakkidi View Point', 'Lakkidi View Point', 'Lakkidi is a high-altitude gateway pass on the Thamarassery ghat road (NH 766) between Kozhikode and Wayanad, about 24 km from Kalpetta. The viewpoint beside the highway offers sweeping views of the mist-covered valley and the ghat''s hairpin bends, and it is a popular sunrise/sunset photo stop. Monkeys are common around the viewpoint.', '20-30 minutes', 'September to March', 'Stop here on the drive between Kozhikode and Kalpetta - mornings are mistiest; keep food away from the monkeys.', 'no', 'Kerala', 1, 1, '6:14 AM', '6:16 PM', NULL, 3, 4, 11.512201, 76.01892, 'NH 766 (Kozhikode-Kollegal highway), near Vythiri, Wayanad, Kerala', NULL, 0.68);

