INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000190, 840007, 'Phantom Rock', 'Phantom Rock', 'Phantom Rock (Cheengeri Mala) is a skull-shaped rock formation rising about 2,600 ft near Ambalavayal, visible from the road and reached by a short trek. The unusual shape - resembling a human skull - has made it a popular photography stop and sunset viewpoint on the Ambalavayal side of Wayanad.', '1 hour', 'September to March', 'Best photographed from a distance at golden hour; the short climb up needs sturdy shoes.', 'no', 'Kerala', 0, 1, '6:14 AM', '6:16 PM', NULL, 3, 4, 11.636634, 76.204607833, 'Ambalavayal, Wayanad, Kerala 673593', NULL, 0.68);

