INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000191, 840007, 'Meenmutty Falls', 'Meenmutty Falls', 'Meenmutty Falls is one of Wayanad''s tallest waterfalls, plunging about 300 m in three tiers through dense forest near Meppadi, about 29 km from Kalpetta. It is reached by a ~2 km trek from the parking area through forest, and the base pool area is restricted in places for safety. The falls are most spectacular in the post-monsoon months.', '3 hours', 'September to December', 'The 2 km forest trek is moderately steep - go with a group and avoid it in heavy rain.', 'no', 'Kerala', 0, 0, '6:14 AM', '6:16 PM', 'Rs 50', 4, 4, 11.728, 75.886, 'Near Meppadi, Wayanad, Kerala 673577', NULL, 0.8);

