INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 840000191, 'insert', 'bulk', 'Real; coordinates FLAGGED for conflict: Wikipedia gives 11.728, 75.886 while aroundus (Sep 2026) gives 11.67757, 75.93809 - used Wikipedia''s. Fee conflicts: Rs 50 (holidayszone) vs Rs 30 (tripoto) vs Rs 36 (Tripadvisor review) - used Rs 50 with note. Hours conflict: 10-5 vs 8-5 vs 9-5:30 - used 10 AM-5 PM with note.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000192, 840007, 'Neelimala Viewpoint', 'Neelimala Viewpoint', 'Neelimala is a misty hill viewpoint near Vaduvanchal, on the Meppadi-Vaduvanchal side of Wayanad, offering panoramic views of the surrounding valleys, tea estates and distant peaks. It is reached by jeep to a trailhead and then a short guided trek, and is popular for sunrise and sunset views.', '2-3 hours', 'September to March', 'Arrange the jeep a day ahead through your stay; views are clearest in the early morning.', 'no', 'Kerala', 1, 1, '6:14 AM', '6:16 PM', NULL, 3, 4, 11.53, 76.1, 'Near Vaduvanchal, Wayanad, Kerala', NULL, 0.68);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (840000192, 840000192, '9:00 AM - 5:00 PM', '9:00 AM - 5:00 PM', '9:00 AM - 5:00 PM', '9:00 AM - 5:00 PM', '9:00 AM - 5:00 PM', '9:00 AM - 5:00 PM', '9:00 AM - 5:00 PM', 'No official hours published; 9 AM-5 PM is the commonly cited visiting window. Local jeeps (~Rs 500) run from the base to the trailhead; a guide is often needed.');

