INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000193, 840007, 'Wayanad Heritage Museum', 'Wayanad Heritage Museum, Ambalavayal', 'The Wayanad Heritage Museum at Ambalavayal, run by the District Tourism Promotion Council, holds one of Kerala''s largest collections of tribal and archaeological artefacts: Neolithic tools, ancient stone carvings, Veerakallu (hero stones), musical instruments, agricultural implements and everyday objects of Wayanad''s tribal communities. The collection is arranged in four blocks - Veerasmruthi, Gothrasmruthi, Devasmruthi and Jeevanasmruthi.', '1-2 hours', 'Year round', 'Combine with Edakkal Caves and Phantom Rock, all in the Ambalavayal cluster.', 'no', 'Kerala', 0, 0, '6:14 AM', '6:16 PM', 'Rs 50', 3, 3, 11.61937, 76.210622, 'Ambalavayal, Wayanad, Kerala 673593', NULL, 0.6);

