INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000194, 840007, 'Jain Temple, Sultan Bathery', 'Jain Temple, Sultan Bathery', 'The Jain Temple at Sultan Bathery is a 13th-century temple in Vijayanagara architecture dedicated to the Jain Tirthankaras. It is famous as the ammunition store (battery) of Tipu Sultan during his Malabar campaigns - the town''s name ''Sultan Bathery'' derives from it. It is a protected monument of the Archaeological Survey of India.', '45 minutes', 'Year round', 'Visit in daylight and combine with the nearby Sultan Bathery town and Muthanga sanctuary drive.', 'no', 'Kerala', 0, 0, '6:14 AM', '6:16 PM', NULL, 3, 3, 11.660167, 76.250694, 'Sultan Bathery, Wayanad, Kerala 673592', NULL, 0.6);

