INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 840000194, 'insert', 'bulk', 'Real; coordinates (11.660167, 76.250694) from Wikipedia (Jain Temple, Sultan Bathery article). 13th-century Vijayanagara architecture; Tipu Sultan''s ammunition store, origin of the town''s name; ASI protected monument. Free entry; no published opening hours found - hours left null.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000195, 840007, 'Muthanga Wildlife Sanctuary', 'Muthanga (Wayanad Wildlife Sanctuary)', 'Muthanga is the most popular range of the Wayanad Wildlife Sanctuary (a part of the Nilgiri Biosphere Reserve), about 17 km from Sultan Bathery and ~35 km from Kalpetta. Jeep safaris through deciduous forest and grassland offer chances to see elephants, gaur, deer, wild boar and, with luck, tigers and leopards. Safaris run in two slots - morning and late afternoon - and are limited in number.', '3-4 hours', 'November to April', 'Morning safaris give the best wildlife sightings; book the jeep at the counter as soon as you arrive.', 'no', 'Kerala', 1, 1, '6:14 AM', '6:16 PM', 'Rs 20', 5, 4, 11.671605, 76.368651, 'Muthanga, near Sultan Bathery, Wayanad, Kerala 673592', NULL, 0.92);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (840000195, 840000195, '7:00 AM - 10:00 AM; 3:00 PM - 5:00 PM', '7:00 AM - 10:00 AM; 3:00 PM - 5:00 PM', '7:00 AM - 10:00 AM; 3:00 PM - 5:00 PM', '7:00 AM - 10:00 AM; 3:00 PM - 5:00 PM', '7:00 AM - 10:00 AM; 3:00 PM - 5:00 PM', '7:00 AM - 10:00 AM; 3:00 PM - 5:00 PM', '7:00 AM - 10:00 AM; 3:00 PM - 5:00 PM', 'Jeep safari slots 7-10 AM and 3-5 PM; safari jeeps are limited, so arrive early in peak season.');

