INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 840000195, 'insert', 'bulk', 'Real; coordinates (11.671605, 76.368651) from wayanadwildlifesanctuary.com. Entry Rs 20; jeep safari Rs 300/person (~2 hrs); safari slots 7-10 AM and 3-5 PM. Part of the Nilgiri Biosphere Reserve; elephants, gaur, deer commonly sighted.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000196, 840007, 'Karlad Lake', 'Karlad Lake', 'Karlad Lake is Wayanad''s second-largest freshwater lake, set amid coffee plantations near Mananthavady road, about 22 km from Kalpetta. Managed by the DTPC, it is Wayanad''s adventure hub: kayaking, zipline, rock climbing, archery and pedal boating are run alongside the lake. A quieter, less crowded alternative to Pookode Lake.', '2-3 hours', 'September to March', 'Try the zipline and kayaking early in the day when the lake is calmest.', 'no', 'Kerala', 1, 1, '6:14 AM', '6:16 PM', 'Rs 30', 3, 4, 11.65056, 75.98167, 'Karlad, near Mananthavady road, Wayanad, Kerala 670645', NULL, 0.68);

