INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000197, 840007, 'Anantnath Swami Temple', 'Anantnath Swami Jain Temple, Puliyarmala', 'The Anantnath Swami Temple at Puliyarmala, about 6 km from Kalpetta, is a historic Jain temple dedicated to Anantanatha, the 14th Tirthankara. A quiet roadside temple in traditional style, it is an important stop on Wayanad''s Jain heritage trail along with the Sultan Bathery Jain temple and the Jain temple at Kidanganad.', '30 minutes', 'Year round', 'A brief roadside stop on the Kalpetta-Mananthavady route; dress modestly as it is an active place of worship.', 'no', 'Kerala', 0, 0, '6:14 AM', '6:16 PM', NULL, 2, 3, 11.640756, 76.086983, 'Puliyarmala, Kalpetta, Wayanad, Kerala 673121', NULL, 0.48);

