INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000198, 840007, 'Kanthanpara Waterfalls', 'Kanthanpara Waterfalls', 'Kanthanpara is a ~100 ft waterfall near Meppadi, about 19-22 km from Kalpetta, set among bamboo groves, tea gardens and natural forest. It is the quietest of Wayanad''s waterfalls - a serene family spot with a two-level cascade - and the surrounding Meppadi forest range is a birdwatching area (Malabar grey hornbill, woodpeckers, kingfishers). The DTPC also runs bird-watching trips and a riverside trek here.', '2 hours', 'October to February', 'The last stretch is narrow - take a jeep or small car; mornings are best for birdwatching.', 'no', 'Kerala', 0, 0, '6:14 AM', '6:16 PM', 'Rs 40', 3, 4, 11.52, 76.19, 'On Vaduvanchal road, 8 km from Meppadi, Wayanad, Kerala 673577', NULL, 0.68);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (840000198, 840000198, '9:00 AM - 4:30 PM', '9:00 AM - 4:30 PM', '9:00 AM - 4:30 PM', '9:00 AM - 4:30 PM', '9:00 AM - 4:30 PM', '9:00 AM - 4:30 PM', '9:00 AM - 4:30 PM', 'Entry time 9 AM-4:30 PM per the official DTPC Wayanad page. Bird watching 6-9 AM (Rs 1,000 for 5 pax); riverside trek 8 AM-3 PM (Rs 500 for 4 pax) per trawell.in.');

