INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 840000198, 'insert', 'bulk', 'Real; official DTPC Wayanad page (dtpcwayanad.com): entry 9 AM-4:30 PM, Adult Rs 40, Child Rs 30. FLAGGED: coordinates (11.52, 76.19) are approximate (Vaduvanchal road, 8 km from Meppadi, ~19-22 km from Kalpetta) - no published coordinates found. Bird watching Rs 1,000/5 pax, trekking Rs 500/4 pax per trawell.in.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000199, 840007, 'Pakshipathalam', 'Pakshipathalam', 'Pakshipathalam (Pakshipathalam Bird Sanctuary) is a natural rock cave at ~1,740 m in the Brahmagiri hills, deep inside the Thirunelli forest near the Kerala-Karnataka border. The 16 km return trek passes through moist deciduous forest, grasslands and streams rich in birdlife, ending at rock caves once used by rishis for meditation. Forest department permission is mandatory and a guide accompanies every trek.', 'Full day', 'October to February', 'Get the forest permit the day before at the Thirunelli forest office; carry food, water and a torch - there are no facilities on the trail.', 'yes', 'Kerala', 1, 0, '6:14 AM', '6:16 PM', 'Rs 200', 3, 4, 11.927498, 75.997395, 'Thirunelli forest area, near Thirunelli Temple, Wayanad, Kerala 670646', NULL, 0.68);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (840000199, 840000199, '6:00 AM - 6:00 PM', '6:00 AM - 6:00 PM', '6:00 AM - 6:00 PM', '6:00 AM - 6:00 PM', '6:00 AM - 6:00 PM', '6:00 AM - 6:00 PM', '6:00 AM - 6:00 PM', 'Open Jun-Jan daily 6 AM-6 PM per showcaves.com (2023); travalour advises starting the trek around 7 AM to finish in daylight. Permission from the District Forest Office (North Wayanad), ~1 km from Thirunelly Temple; guided trek takes 4-5 hours for 16 km.');

