INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 840000199, 'insert', 'bulk', 'Real; coordinates (11.927498, 75.997395) from Wikidata via GeoHack - FLAGGED: showcaves.com gives 11.9379709, 75.9616449, a ~4 km discrepancy. Permission mandatory from District Forest Office North Wayanad near Thirunelly Temple; 16 km return trek, mandatory guide. Fee conflicts: showcaves 2023 (Adults INR 200 / Indians INR 50) vs a 2014 Tripadvisor review (Rs 2,000 permits) - used 2023 figure. ~55-60 km from Kalpetta via Mananthavady and Thirunelli.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000200, 840007, 'Thirunelly Temple', 'Thirunelly Temple', 'The Thirunelly Temple, dedicated to Lord Vishnu, is an ancient temple set against the Brahmagiri hills about 55 km from Kalpetta via Mananthavady. Known as the ''Dakshina Kashi'', it is one of Kerala''s most important pilgrim centres for Pithru Tharpanam (ancestral rites), performed at the nearby Papanashini stream. Day trip from Kalpetta (~2 hours each way).', 'Half day', 'September to March', 'Combine with a Papanashini visit for the ancestral rites; leave Kalpetta by 6:30 AM to reach before the midday closure.', 'no', 'Kerala', 0, 0, '6:14 AM', '6:16 PM', NULL, 4, 4, 11.911738, 75.995999, 'Thirunelly Post, Mananthavady, Wayanad, Kerala 670646', NULL, 0.8);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (840000200, 840000200, '5:30 AM - 12:30 PM; 5:30 PM - 8:00 PM', '5:30 AM - 12:30 PM; 5:30 PM - 8:00 PM', '5:30 AM - 12:30 PM; 5:30 PM - 8:00 PM', '5:30 AM - 12:30 PM; 5:30 PM - 8:00 PM', '5:30 AM - 12:30 PM; 5:30 PM - 8:00 PM', '5:30 AM - 12:30 PM; 5:30 PM - 8:00 PM', '5:30 AM - 12:30 PM; 5:30 PM - 8:00 PM', 'Timings from gokshetra; closed midday 12:30-5:30 PM. Official site thirunellitemple.org was not fetched, so official_website left null. Entry free.');

