INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 840000200, 'insert', 'bulk', 'Real; coordinates (11.911738, 75.995999) and address (Thirunelly Post, Mananthavady, Wayanad 670646) from thirunellitemple.org. Timings 5:30 AM-12:30 PM & 5:30-8 PM from gokshetra. Entry free; ''Dakshina Kashi''; Pithru Tharpanam at Papanashini. ~55 km from Kalpetta (day trip). Official website not fetched, left null.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000201, 840007, 'Pazhassi Raja Tomb', 'Pazhassi Raja Tomb', 'The Pazhassi Raja Tomb at Mananthavady is the memorial of Kerala Varma Pazhassi Raja, the ''Lion of Kerala'', who led the guerrilla resistance against the British and died in 1805. The tomb sits in a small memorial garden with a museum displaying Pazhassi-era artefacts, weapons and murals. Day trip from Kalpetta (~32 km north).', '1 hour', 'Year round', 'Combine with Mananthavady town and the nearby Valliyoorkkavu temple in the same outing.', 'no', 'Kerala', 0, 0, '6:14 AM', '6:16 PM', 'Rs 20', 3, 3, 11.80122, 76.00082, 'Mananthavady, Wayanad, Kerala 670645', NULL, 0.6);

