INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000202, 840007, 'Kakkayam Dam', 'Kakkayam Dam', 'Kakkayam Dam is a scenic reservoir in the Kozhikode district foothills, about 60 km from Kalpetta, set amid forest with views of the Kuttiadi hills. Managed as an ecotourism spot (Kakkayam Ecotourism), it offers boating and a cool forested picnic setting, often visited as a day trip from Wayanad or Kozhikode. Elephants are occasionally sighted on the approach road.', 'Half day', 'October to March', 'Best October-March; the approach road through forest is narrow, so drive carefully and watch for wildlife.', 'no', 'Kerala', 0, 1, '6:14 AM', '6:16 PM', 'Rs 20', 3, 3, 11.549817, 75.929634, 'Kakkayam, Kozhikode district, Kerala 673615', NULL, 0.6);

