INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000208, 840007, 'Jaleel Kitchen And Restaurant', 'Jaleel Kitchen And Restaurant', 'A budget Malabar-style restaurant on PWD Office Road in Kalpetta, known for affordable beef biryani and Kerala meals. A local favourite for cheap, filling non-veg food.', '45 minutes', 'Year round', 'Budget pick for Malabar biryani; beef biryani is the signature (~Rs 150 per Justdial).', 'no', 'Kerala', 0, 0, '6:14 AM', '6:16 PM', NULL, 3, 3, 11.607, 76.086, 'PWD Office Road, Kalpetta, Wayanad, Kerala 673121', NULL, 0.6);

