INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8400039, 840, 840007, 'Valliyoorkkavu Festival', 'Mar', 'The 14-day annual festival of the Valliyoorkkavu Bhagavathy Temple near Mananthavady (~24 km from Kalpetta), held in March-April (Malayalam month Meenam) in honour of Goddess Durga''s victory over the demon Daruka. Famous for tribal rituals - the Kalamezhuthu ritual on festival nights and folk dances by Wayanad''s tribal communities with native percussion on the final day.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8400040, 840, 840007, 'Kottiyoor Vysakha Mahotsavam', 'May-Jun', 'A 28-day annual pilgrimage festival at the forest shrine of Akkare Kottiyoor, on the Wayanad-Kannur border. The temporary shrine is built each year in the forest by the Bavali river and dismantled after the festival; rituals like Neyyattam, Ilaneer Veypu and Rohini Aradhana draw lakhs of devotees. (2026 edition ran roughly May 29-June 24.)');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8400041, 840, 840007, 'Onam', 'Aug-Sep', 'Kerala''s biggest festival, the 10-day harvest festival honouring King Mahabali, celebrated across Wayanad with Pookalam flower carpets, the Onasadya feast, Vallamkali boat-race telecasts and cultural programmes. Thiruvonam is the main day.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8400042, 840, 840007, 'Puthari', 'Oct-Nov', 'The traditional harvest festival of Wayanad''s tribal communities, celebrating the new rice harvest with feasting, folk songs and community rituals in tribal hamlets across the district.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8400043, 840, 840007, 'Thirunelly Maha Shivaratri', 'Feb-Mar', 'Maha Shivaratri is the biggest annual festival at the Thirunelly Temple (~55 km from Kalpetta), drawing large crowds of pilgrims who bathe in the Papanashini stream and offer ancestral rites (Pithru Tharpanam) at the temple.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8400044, 840, 840007, 'Vishu', 'Apr', 'The Malayali new year, celebrated across Wayanad with the Vishukkani ritual arrangement, Vishu sadya feast and fireworks; temples and homes mark the start of the new agricultural cycle.');

-- city: Thrissur (id 1049)
INSERT OR IGNORE INTO cities (id, state_id, city_name, latitude, longitude) VALUES (840008, 840, 'Thrissur', 10.5276, 76.2144);

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000209, 840008, 'Vadakkunnathan Temple', 'Vadakkunnathan Temple', 'The Vadakkunnathan Temple is one of the largest and oldest Shiva temples in Kerala, dedicated to Lord Vadakkunnathan (Shiva), and stands at the centre of Thrissur''s Swaraj Round with Thekkinkadu Maidan. It is a classic example of traditional Kerala temple architecture with monumental gopurams, mural paintings, and shrines of Shiva, Parvati, Sankaranarayana, Ganapathy and Sree Rama. The temple hosts the Thrissur Pooram festival on its grounds. Entry is restricted to Hindus, with a strict dress code (mundu/saree) and no photography.', '1-2 hours', 'October to March', 'Non-Hindus can admire the architecture from outside; the temple''s elephant enclosure and the Thekkinkadu Maidan are worth a walk.', 'Not required', 'Kerala', 0, 0, NULL, NULL, 'Free', 5.0, 4.7, 10.5243, 76.2138, 'Vadakkunnathan Temple Rd, Swaraj Round, Thrissur, Kerala 680001, India', NULL, 0.976);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (840000209, 840000209, '3:00 AM - 10:30 AM, 5:00 PM - 8:30 PM', '3:00 AM - 10:30 AM, 5:00 PM - 8:30 PM', '3:00 AM - 10:30 AM, 5:00 PM - 8:30 PM', '3:00 AM - 10:30 AM, 5:00 PM - 8:30 PM', '3:00 AM - 10:30 AM, 5:00 PM - 8:30 PM', '3:00 AM - 10:30 AM, 5:00 PM - 8:30 PM', '3:00 AM - 10:30 AM, 5:00 PM - 8:30 PM', 'Sources vary slightly: inheritage.foundation lists 3 AM-10:30 AM & 5-8:30 PM; other sources list morning opening at 4:00 AM. Midday closure standard. Entry restricted to Hindus; dress code (mundu/saree); no photography inside.');

