INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 840000209, 'insert', 'bulk', 'Confirmed real: central temple of Thrissur, venue of Thrissur Pooram. Coordinates approximate (temple sits on Swaraj Round, city centre 10.5276, 76.2144). Hours from published guides, vary by source (3 AM vs 4 AM opening) - noted honestly.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000210, 840008, 'Thrissur Zoo and State Museum', 'Thrissur Zoo and State Museum', 'The Thrissur Zoo and State Museum at Chembukkavu is one of the oldest zoos in India, set in a 5.6-hectare complex that includes a zoological garden, botanical garden, art museum, multipurpose museum and a 3D theatre. Founded in 1885 (Viyyur Park) and moved to Chembukkavu in 1912, the museum houses the skeleton of the famed elephant Chengallur Ranganathan, mural paintings, and archaeological exhibits. Plans are underway to shift animals to a modern zoo at Puthur. The official Kerala Museum & Zoo Department site covers this campus.', '2-3 hours', 'October to March', 'Arrive soon after the 9:30 AM opening for the liveliest animals; combine with Sakthan Thampuran Palace nearby.', 'Not required; tickets at counter', 'Kerala', 0, 0, NULL, NULL, 'Rs 20 (adult) / Rs 5 (child 5-12) / Rs 40 (family); museum Rs 10', 4.0, 4.2, 10.530089, 76.222164, 'Town Hall Rd, Chembukkavu, Thrissur, Kerala 680020, India', 'https://museumandzoo.kerala.gov.in/index.php/thrissur', 0.816);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (840000210, 840000210, 'Closed', '9:30 AM - 5:15 PM', '9:30 AM - 5:15 PM', '9:30 AM - 5:15 PM', '9:30 AM - 5:15 PM', '9:30 AM - 5:15 PM', '9:30 AM - 5:15 PM', 'Closed on Mondays per travel guides. The zoo-museum complex dates to 1885 (Viyyur Park) and moved to Chembukkavu in 1912.');

