INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000211, 840008, 'Sakthan Thampuran Palace', 'Sakthan Thampuran Palace', 'The Sakthan Thampuran Palace is the former residence of Rama Varma IX (Sakthan Thampuran), the 18th-century Maharaja of Cochin who modernised Thrissur and founded the Thrissur Pooram. Built in Kerala-Dutch architectural style, the palace now houses an archaeological museum run by the Cochin Devaswom/Archaeology department, with galleries of old coins, bronze sculptures, temple models, and belongings of the Cochin royal family. It sits near the zoo at Chembukkavu.', '1-2 hours', 'October to March', 'Combine with the zoo and State Museum, both in the same Chembukkavu area.', 'Not required', 'Kerala', 0, 0, NULL, NULL, 'Rs 20 (adult) / Rs 5 (child)', 4.5, 4.3, 10.5225, 76.221, 'Sakthan Thampuran Nagar, Chembukkavu, Thrissur, Kerala 680001, India', NULL, 0.884);

