INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000212, 840008, 'Athirappilly Falls', 'Athirappilly Falls', 'Athirappilly Falls, on the Chalakudy River, is Kerala''s largest waterfall at 80 ft high and 330 ft wide, often called the ''Niagara of India''. Set in dense evergreen forest of the Sholayar ranges, it is a popular filming location and birdwatching spot (great Indian hornbill). It is a day trip from Thrissur (~70 km, 1.5-2 hours) via Chalakudy; the top viewpoint is accessible but the trek to the base is steep and closes during monsoon when flow is dangerous.', '3-4 hours', 'June to September (monsoon flow) and October to February', 'Day trip (~70 km from Thrissur). Visit the top viewpoint; base trek is steep - wear good shoes and avoid the monsoon peak.', 'Not required; forest entry ticket at counter', 'Kerala', 0, 1, NULL, '18:15', 'Rs 40-50 (adult) / Rs 10 (child); foreigners Rs 150-200', 5.0, 4.6, 10.285, 76.5694, 'Athirappilly, Thrissur District, Kerala 680721, India', NULL, 0.968);

