INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000213, 840008, 'Guruvayur Sri Krishna Temple', 'Guruvayur Sri Krishna Temple', 'The Guruvayur Sri Krishna Temple is one of the most important Krishna temples in India, dedicated to Guruvayurappan (a four-armed Vishnu/Krishna idol said to have been worshipped by Krishna himself). Known as the ''Dwarka of the South'', it draws millions of pilgrims yearly and is famous for its elephant processions, Udayasthamana Pooja, and the Guruvayur Ekadasi festival. It is a day trip from Thrissur (~29 km). Entry is restricted to Hindus with a strict mundu dress code; mobile phones are not allowed inside.', '2-3 hours', 'October to March; avoid Ekadasi/Ulsavam festival crowds', 'Day trip (~29 km from Thrissur). Expect long queues on weekends and festival days; early morning darshan is calmest.', 'Not required for general darshan; special darshan tickets at counter', 'Kerala', 0, 0, NULL, NULL, 'Free (special darshan tickets available at counter)', 5.0, 4.8, 10.5946, 76.0394, 'Guruvayur Temple, Guruvayur, Thrissur District, Kerala 680101, India', NULL, 0.984);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (840000213, 840000213, '3:00 AM - 1:30 PM, 4:30 PM - 9:15 PM', '3:00 AM - 1:30 PM, 4:30 PM - 9:15 PM', '3:00 AM - 1:30 PM, 4:30 PM - 9:15 PM', '3:00 AM - 1:30 PM, 4:30 PM - 9:15 PM', '3:00 AM - 1:30 PM, 4:30 PM - 9:15 PM', '3:00 AM - 1:30 PM, 4:30 PM - 9:15 PM', '3:00 AM - 1:30 PM, 4:30 PM - 9:15 PM', 'Sources vary on evening close (9:15 PM to 10:00 PM). Hindus only; mundu dress code; no photography/mobiles. Devaswom site (guruvayurdevaswom.in) presented only a login page when checked - not usable as an official site, so null.');

