INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000214, 840008, 'Punnathur Kotta (Anakkotta)', 'Punnathur Kotta - Guruvayur Elephant Fort', 'Punnathur Kotta, popularly called Anakkotta (elephant fort), is the world''s largest elephant sanctuary/fort, housing 50+ elephants owned by the Guruvayur Devaswom. Located ~3 km from Guruvayur Temple, the former palace of the Punnathur Raja is where the temple''s caparisoned elephants - including famous tuskers - are trained and cared for. Visitors can watch the elephants being bathed and fed; it is a must-visit add-on to a Guruvayur day trip.', '1-2 hours', 'October to March; mornings for bathing/feeding', 'Day trip combined with Guruvayur Temple (~3 km away). Morning visits are best for seeing elephants bathed.', 'Not required', 'Kerala', 0, 0, NULL, NULL, 'Rs 20 (adult); child and camera fees extra', 4.5, 4.4, 10.6143, 76.0299, 'Punnathurkotta, Kottapadi, Guruvayur, Thrissur District, Kerala 680505, India', NULL, 0.892);

