INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000215, 840008, 'Kerala Kalamandalam, Cheruthuruthy', 'Kerala Kalamandalam - Deemed University for Art and Culture', 'Kerala Kalamandalam at Cheruthuruthy (~30 km from Thrissur) is India''s premier deemed university for classical arts, founded in 1930 by poet Vallathol Narayana Menon to revive Kathakali. Visitors can take the ''A day with the masters'' tour to watch students train in Kathakali, Mohiniyattam, Koodiyattam and percussion, and see the Koothambalam theatre, museums and costume galleries. It is a day trip from Thrissur, best experienced on working days when classes are in session.', 'Half day', 'October to March; working days for the ''day with the masters'' tour', 'Day trip (~30 km from Thrissur). Go on a working day - visitor entry for the guided campus tour is typically till ~12:30 PM.', 'Recommended for the guided ''A day with the masters'' program', 'Kerala', 0, 0, NULL, NULL, NULL, 4.5, 4.6, 10.7366, 76.2788, 'Kerala Kalamandalam, Cheruthuruthy, Thrissur District, Kerala 679531, India', NULL, 0.908);

