INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000216, 840008, 'Basilica of Our Lady of Dolours (Puthenpally)', 'Basilica of Our Lady of Dolours', 'The Basilica of Our Lady of Dolours, known locally as Puthenpally (New Church), is one of the tallest churches in India and the third tallest in Asia, with its Bible Tower rising 260 ft. A landmark of Thrissur''s Catholic heritage near the Round, it draws pilgrims and architecture lovers; the adjacent Bible Tower offers panoramic city views from the top.', '1-2 hours', 'October to March', 'Visit the Bible Tower next door for the best aerial view of Thrissur city.', 'Not required', 'Kerala', 0, 0, NULL, NULL, 'Free (church); Bible Tower entry separate ~Rs 20', 4.5, 4.5, 10.5198, 76.2195, 'Our Lady of Dolours Basilica, Puthenpally, Thrissur, Kerala 680001, India', NULL, 0.9);

