INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000217, 840008, 'Bible Tower', 'Bible Tower', 'The 260-ft Bible Tower adjoining the Basilica of Our Lady of Dolours is one of Asia''s tallest church towers, with a lift and 460 steps leading to an observation deck with panoramic views over Thrissur. Built as a monument to the Bible, it displays murals and exhibits on biblical themes and is a popular sunset viewpoint in the city.', '1-2 hours', 'October to March; late afternoon for views', 'Go on a clear late afternoon for the best city panorama from the top.', 'Not required', 'Kerala', 0, 1, NULL, '18:15', 'Rs 20 (approx)', 4.0, 4.2, 10.5209, 76.2186, 'Bible Tower, Puthenpally, Thrissur, Kerala 680001, India', NULL, 0.816);

