INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000218, 840008, 'St. Thomas Forane Church, Palayoor', 'St. Thomas Forane Church, Palayoor', 'St. Thomas Forane Church at Palayoor is traditionally counted among the seven churches founded by St. Thomas the Apostle in 52 AD, making it one of the oldest Christian pilgrimage centres in India. Located ~4 km from Guruvayur (~22-32 km from Thrissur), the church complex includes a museum and the Thaliyakulam (baptismal pond). It is a major Nasrani pilgrimage site, especially during the Palayoor church feast.', '1-2 hours', 'October to March', 'Day trip combined with Guruvayur (4 km away). See the Thaliyakulam pond and the church museum.', 'Not required', 'Kerala', 0, 0, NULL, NULL, 'Free', 4.0, 4.4, 10.581, 76.023, 'Palayoor, Chavakkad, Thrissur District, Kerala 680506, India', NULL, 0.832);

