INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 840000218, 'insert', 'bulk', 'Confirmed real. ''Founded 52 AD by St. Thomas'' is tradition per travel sources. Coordinates approximate (Palayoor, ~4 km from Guruvayur). Hours null - no published source found.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000219, 840008, 'Koodalmanikyam Temple, Irinjalakuda', 'Koodalmanikyam Temple', 'The Koodalmanikyam Temple at Irinjalakuda (~22 km from Thrissur) is dedicated to Bharata, the brother of Lord Rama, and is considered the only major Bharata temple in India and the only Bharata shrine in Kerala. It is the second temple in the Nalambalam pilgrimage circuit (Rama-Bharata-Lakshmana-Shatrughna) and is famed for its ancient murals, grand Nalambalam complex and traditional rituals. The temple''s annual festival falls in Medam (Apr-May).', '1-2 hours', 'October to March', 'Combine with the other Nalambalam temples (Thriprayar, Moozhikkulam, Payammal). Dress code (mundu/saree) applies.', 'Not required', 'Kerala', 0, 0, NULL, NULL, 'Free', 4.5, 4.6, 10.3466, 76.2021, 'Koodalmanikyam Temple, Irinjalakuda, Thrissur District, Kerala 680121, India', NULL, 0.908);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (840000219, 840000219, '3:30 AM - 11:30 AM, 5:00 PM - 8:30 PM', '3:30 AM - 11:30 AM, 5:00 PM - 8:30 PM', '3:30 AM - 11:30 AM, 5:00 PM - 8:30 PM', '3:30 AM - 11:30 AM, 5:00 PM - 8:30 PM', '3:30 AM - 11:30 AM, 5:00 PM - 8:30 PM', '3:30 AM - 11:30 AM, 5:00 PM - 8:30 PM', '3:30 AM - 11:30 AM, 5:00 PM - 8:30 PM', 'Sources vary on morning opening: 3:30 AM vs 4:30 AM. Only temple in Kerala dedicated to Bharata; part of the Nalambalam circuit. koodalmanikyam.com was seen in search results but its fetch was not verified - not set as official site.');

