INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000220, 840008, 'Thriprayar Sree Rama Temple', 'Thriprayar Sree Rama Temple', 'The Thriprayar Sree Rama Temple (~20 km from Thrissur) is dedicated to Lord Rama in a rare four-armed (Chathurbhuja) form holding conch, discus, bow and garland, worshipped here as the triumphant king after defeating Ravana. It is the first and most important temple of the Nalambalam pilgrimage circuit. The temple''s Ekadasi festival (Nov-Dec) and Arattupuzha Pooram participation draw large crowds.', '1-2 hours', 'October to March', 'Visit early morning for the Nirmalya darshan; the four-armed Rama idol is unique.', 'Not required', 'Kerala', 0, 0, NULL, NULL, 'Free', 4.5, 4.6, 10.4302, 76.0905, 'Thriprayar Sree Rama Temple, Thriprayar, Thrissur District, Kerala 680567, India', NULL, 0.908);

