INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000221, 840008, 'Arattupuzha Sree Sastha Temple', 'Arattupuzha Sree Sastha Temple', 'The Arattupuzha Sree Sastha Temple (~15 km from Thrissur) hosts the Arattupuzha Pooram, a 7-day festival in Meenam (Mar-Apr) known as the ''mother of all Poorams'' - the oldest pooram tradition in Kerala, predating Thrissur Pooram. On the final day, 23 deities from neighbouring temples assemble here in a grand procession with 60-80 caparisoned elephants and the Sasthavinte Melam ensemble of ~200 percussion artists.', '1-2 hours (full day during Pooram)', 'March-April during Arattupuzha Pooram', 'Time your visit for the Arattupuzha Pooram (Mar-Apr) to see the grandest elephant and percussion spectacle in Kerala.', 'Not required', 'Kerala', 0, 0, NULL, NULL, 'Free', 4.5, 4.6, 10.4497, 76.1686, 'Arattupuzha Sree Sastha Temple, Arattupuzha, Thrissur District, Kerala 680562, India', NULL, 0.908);

