INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 840000221, 'insert', 'bulk', 'Confirmed real. Coordinates approximate (Arattupuzha, ~15 km from Thrissur). Hours null - no published source.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000222, 840008, 'Peruvanam Mahadeva Temple, Cherpu', 'Peruvanam Mahadeva Temple', 'The Peruvanam Mahadeva Temple at Cherpu (~10 km from Thrissur) is counted among the 108 Shiva temples established by Parasurama and is one of Kerala''s oldest Shiva shrines, with the current structure dated to around the 11th-12th century. The deity is worshipped as ''Irattayappan'' - a rare dual-linga form of Shiva - and the Madathilappan shrine is noted as one of the tallest Srikovils in South India. The Peruvanam Pooram (Apr-May) is one of Kerala''s oldest temple festivals, predating Thrissur Pooram by over a thousand years. Traditional dress code applies.', '1-2 hours', 'October to March; Apr-May for Peruvanam Pooram', 'A short drive from Thrissur (~10 km). Visit during Peruvanam Pooram (Apr-May) for the historic festival.', 'Not required', 'Kerala', 0, 0, NULL, NULL, 'Free', 4.5, 4.5, 10.437419, 76.212024, 'Peruvanam Mahadeva Temple, Cherpu, Thrissur District, Kerala 680561, India', NULL, 0.9);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (840000222, 840000222, '5:00 AM - 10:30 AM, 5:00 PM - 7:30 PM', '5:00 AM - 10:30 AM, 5:00 PM - 7:30 PM', '5:00 AM - 10:30 AM, 5:00 PM - 7:30 PM', '5:00 AM - 10:30 AM, 5:00 PM - 7:30 PM', '5:00 AM - 10:30 AM, 5:00 PM - 7:30 PM', '5:00 AM - 10:30 AM, 5:00 PM - 7:30 PM', '5:00 AM - 10:30 AM, 5:00 PM - 7:30 PM', '5:00-10:30 AM and 5:00-7:30 PM per velpu.com and astroved.com. One source lists evening close at 8:00 PM. Traditional dress code; photography restricted.');

