INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000223, 840008, 'Vazhani Dam', 'Vazhani Dam', 'Vazhani Dam (~22 km from Thrissur, near Wadakkancherry) is an earth/clay dam built in 1962 across the Kechery River, set amid forested hills. It is a popular local picnic spot with a garden and boating, often visited together with the Peechi-Vazhani Wildlife Sanctuary nearby. Simple, scenic and uncrowded - a classic Thrissur weekend outing.', '2-3 hours', 'October to March', 'Combine with Peechi-Vazhani Wildlife Sanctuary. Best after the monsoon when the reservoir is full.', 'Not required', 'Kerala', 0, 1, NULL, '18:15', 'Rs 10-20 (approx); some sources report free entry', 3.5, 4.0, 10.6371, 76.3075, 'Vazhani Dam, Wadakkancherry, Thrissur District, Kerala 680589, India', NULL, 0.74);

