INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000224, 840008, 'Peechi-Vazhani Wildlife Sanctuary', 'Peechi-Vazhani Wildlife Sanctuary', 'The Peechi-Vazhani Wildlife Sanctuary (~20-23 km from Thrissur) was established in 1958 across 125 sq km of the Western Ghats around the Peechi and Vazhani reservoirs. It shelters elephants, leopards, tigers and rich birdlife, and is popular for its butterfly garden, nature trails and the Peechi Dam viewpoint. A favourite weekend escape from the city.', '3-4 hours', 'October to March', 'Pair with Vazhani Dam. Go early morning for the best wildlife sightings.', 'Not required for day visits', 'Kerala', 0, 0, NULL, NULL, 'Rs 10 (adult) / Rs 5 (child)', 4.0, 4.2, 10.5325, 76.379, 'Peechi-Vazhani Wildlife Sanctuary, Peechi, Thrissur District, Kerala 680653, India', NULL, 0.816);

