INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000225, 840008, 'Chimmini Wildlife Sanctuary', 'Chimmini Wildlife Sanctuary', 'Chimmini Wildlife Sanctuary (~40-50 km from Thrissur) was established in 1984 over 85.07 sq km on the western slopes of the Nelliyampathy hills, around the Chimmini reservoir. Home to elephants, tigers, leopards and the lion-tailed macaque, it offers guided treks, birdwatching and bamboo-rafting-style nature experiences through evergreen forest. A full day trip from Thrissur.', 'Full day', 'October to March', 'Day trip (~40-50 km from Thrissur). Guided treks (Rs 150/person, min 3) need prior arrangement at the forest office.', 'Recommended for treks', 'Kerala', 0, 0, NULL, NULL, 'Rs 15 (adult Indian) / Rs 165 (foreigner); camera Rs 55; trek Rs 150/person (min 3)', 4.0, 4.3, 10.4234, 76.4543, 'Chimmini Wildlife Sanctuary, Echippara, Thrissur District, Kerala 680724, India', NULL, 0.824);

