INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000226, 840008, 'Chavakkad Beach', 'Chavakkad Beach', 'Chavakkad Beach (~24-35 km northwest of Thrissur) is famous for the Azhimukham (Azhimugam) - the scenic estuary where a river meets the Arabian Sea. One of Kerala''s cleanest and least crowded beaches, it is fringed with coconut groves, dotted with fishing boats, and backed by the Ramachapadam herb fields. A classic sunset spot, best enjoyed in the evening; swimming is not advised due to currents.', '2-3 hours', 'October to March; evenings for sunset', 'Visit for the Azhimukham river-sea confluence and sunset; swim only in designated safe areas - currents are strong.', 'Not required', 'Kerala', 0, 1, NULL, '18:15', 'Free', 4.0, 4.3, 10.572, 76.008, 'Chavakkad Beach, Chavakkad, Thrissur District, Kerala 680506, India', NULL, 0.824);

