INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000227, 840008, 'Snehatheeram Beach, Azhikode', 'Snehatheeram Beach', 'Snehatheeram (''shore of love'') Beach at Azhikode/Thalikulam (~23-30 km from Thrissur) is an award-winning, family-friendly beach with a well-kept park, children''s play area and landscaped gardens. Known for clean sands, lifeguards and beautiful sunsets, it is one of the most developed and safest beaches near Thrissur.', '2-3 hours', 'October to March; evenings for sunset', 'Good family beach with a park; combine with nearby Chavakkad Beach for a coastal day.', 'Not required', 'Kerala', 0, 1, NULL, '18:15', 'Free (beach); park Rs 3-5', 4.0, 4.3, 10.5515, 76.0035, 'Snehatheeram Beach, Azhikode, Thrissur District, Kerala 680666, India', NULL, 0.824);

