INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000228, 840008, 'Vilangan Kunnu', 'Vilangan Kunnu', 'Vilangan Kunnu (~5-7 km from Thrissur) is a laterite hillock and landscaped park known as the ''Oxygen Jar of Thrissur City''. With walking paths, gardens, an open-air theatre and sweeping views over the city, it is a favourite local sunrise and sunset point, especially popular with morning walkers and families.', '1-2 hours', 'October to March; evenings for sunset views', 'Go in the late afternoon for the city panorama at sunset.', 'Not required', 'Kerala', 0, 1, NULL, '18:15', 'Rs 10-20 (approx)', 3.5, 4.1, 10.557472, 76.168588, 'Vilangan Kunnu, Adat, Thrissur, Kerala 680551, India', NULL, 0.748);

