INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 840000228, 'insert', 'bulk', 'Confirmed real; coordinates from Wikipedia (10.557472, 76.168588). Hours conflict across sources (7 AM-7 PM vs 9 AM-5 PM) - official keralatourism.org figure used.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000229, 840008, 'Hotel Bharath', 'Hotel Bharath', 'Hotel Bharath (established 1964 by K. Balakrishna Menon) is Thrissur''s legendary pure-vegetarian institution on Chembottil Lane, just off the Swaraj Round. Famous for its masala dosa, ghee roast, Kerala meals, North Indian curries and filter coffee, it draws crowds from breakfast through dinner. Spacious dining, parking, and a half-century legacy make it the city''s most trusted veg restaurant.', '1-1.5 hours', 'October to March', 'Come early for breakfast - the masala dosa and ghee roast sell out fast; lunch hours are crowded.', 'Not required; no reservations', 'Kerala', 0, 0, NULL, NULL, 'Rs 400 for two (approx)', 4.5, 4.4, 10.521483, 76.21392, 'Chembottil Ln, Round South, Thrissur, Kerala 680001, India', 'https://www.hotelbharathtcr.com/', 0.892);

