INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000230, 840008, 'Sree Radhakrishna Prasada', 'Sree Radhakrishna Prasada', 'Sree Radhakrishna Prasada is a well-known pure-vegetarian restaurant on Kuruppam Road at Chettiangadi, Thrissur, serving South Indian and North Indian vegetarian fare. A family favourite for homely Kerala meals, dosas and North Indian thalis, it is a staple of the city''s veg dining scene.', '1-1.5 hours', 'October to March', 'Good option for a full vegetarian lunch; parking is available.', 'Not required', 'Kerala', 0, 0, NULL, NULL, 'Rs 600 for two (approx)', 4.0, 4.0, 10.5205, 76.2085, 'Kuruppam Rd, Chettiangadi, Thrissur, Kerala 680001, India', NULL, 0.8);

