INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 840000230, 'insert', 'bulk', 'Confirmed real (Tripadvisor Travellers'' Choice listing, tripfactory.com). Coordinates approximate (Kuruppam Rd, Chettiangadi). Hours from Justdial, not officially published. No official website.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000231, 840008, 'Hotel Pathans', 'Hotel Pathans', 'Hotel Pathans (Pathans Restaurant) is a century-old vegetarian institution on Round South near Vadakkunnathan Temple, at one of Thrissur''s key locations. It serves a wide vegetarian menu - South Indian, North Indian, Chinese, veg biryani and desserts - with meals, dosa, vada and tea as local favourites. Budget-friendly with parking and valet service near the Round.', '1 hour', 'October to March', 'Try the meals, rava dosa and curd vada; closed during Onam/Vishu festival days.', 'Not required', 'Kerala', 0, 0, NULL, NULL, 'Rs 300 for two (approx)', 4.0, 4.2, 10.5195, 76.2145, 'XXV/127, Round South, Poothole, Thrissur, Kerala 680001, India', NULL, 0.816);

