INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 840000231, 'insert', 'bulk', 'Confirmed real. Coordinates approximate (Round South, Poothole). Hours/cost from magicpin (Zomato results seen in search but NOT scraped/used per pipeline rules). No official website.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000232, 840008, 'Sree Radhakrishna Coffee Club', 'Sree Radhakrishna Coffee Club', 'Sree Radhakrishna Coffee Club, started in 1943 on Municipal Office Road near the Round, is one of Thrissur''s oldest vegetarian restaurants and a breakfast legend. Famous for its masala dosa, ghee roast, upma (often called the finest in town) and Mylapore-style filter coffee, it is small, crowded and deeply loved by locals. Open 7:30 AM-9 PM daily.', '45 minutes - 1 hour', 'October to March; mornings for breakfast', 'Order the ghee roast masala dosa and the upma; expect a crowd at peak breakfast hours.', 'Not required', 'Kerala', 0, 0, NULL, NULL, 'Rs 150-200 for two (approx)', 4.5, 4.3, 10.522193, 76.215225, 'Municipal Office Rd, Kuruppam, Round South, Thrissur, Kerala 680001, India', NULL, 0.884);

