INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 840000232, 'insert', 'bulk', 'Confirmed real (est. 1943, Municipal Office Rd). SUBSTITUTION: the task list named ''Ambiswamy''s Restaurant'' but no Ambiswamy''s outlet exists in Thrissur - all branches are in Ernakulam/Kochi (Palarivattom, Kadavanthara, Edapally); only a separate Thrissur-based catering service exists. Replaced with this real Thrissur institution rather than inventing a place. Coordinates from published listing (10.522193, 76.215225).', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000233, 840008, 'Hotel Nalanda (Pure Veg)', 'Hotel Nalanda', 'Hotel Nalanda is a long-standing pure-vegetarian restaurant on Marar Road (Pazhayanadakkavu Road) near Thrissur railway station, known for homely, economical veg meals, chana bhatura, ghee roast and masala dosa. A favourite of daily commuters and locals for quality food at modest prices. Closed on Sundays.', '1 hour', 'October to March', 'Try the chana bhatura and ghee roast; note it is closed on Sundays.', 'Not required', 'Kerala', 0, 0, NULL, NULL, NULL, 4.0, 4.2, 10.523285, 76.211741, 'Narayana Building, Pazhayanadakkavu Rd, Marar Road Area, Thrissur, Kerala 680001, India', NULL, 0.816);

