INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000234, 840008, 'Ming Palace', 'Ming Palace', 'Ming Palace, on the first/second floor of Pathans Building at Round South near Ragam Theatre, is said to be Thrissur''s first restaurant dedicated to Chinese cuisine and has run for over 20 years. Known for generous portions of Indo-Chinese classics - chicken triple rice, American chop suey, chilli chicken - at pocket-friendly prices, plus seafood and biryani. A local favourite for family dinners and group outings.', '1-1.5 hours', 'October to March', 'Order the chicken triple rice or American chop suey; portions are generous - share dishes.', 'Not required', 'Kerala', 0, 0, NULL, NULL, 'Rs 800 for two (approx)', 4.0, 4.2, 10.522377, 76.214083, '2nd Floor, Pathans Building, Round South, Thrissur, Kerala 680001, India', NULL, 0.816);

