INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8400045, 840, 840008, 'Thrissur Pooram', 'Apr-May', 'Thrissur Pooram, held at the Thekkinkadu Maidan around Vadakkunnathan Temple, is Kerala''s grandest temple festival - the ''mother of all Poorams''. Founded in 1797-98 by Sakthan Thampuran (Raja Rama Varma of Cochin), it brings together ten temples in a friendly rivalry led by Paramekkavu and Thiruvambady. Highlights: caparisoned elephants, the Kudamattam parasol exchange, the Ilanjithara Melam percussion ensemble, and a massive midnight fireworks display. Celebrated on the Pooram asterism in the Malayalam month of Medam.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8400046, 840, 840008, 'Pulikali (Tiger Dance)', 'Aug-Sep', 'Pulikali, the tiger dance of Thrissur, is held during the Onam season (fourth day of Onam) on Swaraj Round. Hundreds of performers paint their bodies in vivid tiger stripes and dance to chenda melam rhythms through the streets. Organised by local desams (nine teams in 2026) with Thrissur Corporation support, it is one of Kerala''s most photographed folk art spectacles.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8400047, 840, 840008, 'Arattupuzha Pooram', 'Mar-Apr', 'Arattupuzha Pooram, at the Arattupuzha Sree Sastha Temple (~15 km from Thrissur), is a 7-day festival in the Malayalam month of Meenam and the oldest pooram tradition in Kerala - the ''mother of all Poorams'' that predates Thrissur Pooram. On the final day, 23 deities from neighbouring temples assemble in procession with 60-80 caparisoned elephants and the Sasthavinte Melam of ~200 percussion artists.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8400048, 840, 840008, 'Chembai Sangeetholsavam', 'Nov-Dec', 'The Chembai Sangeetholsavam is a 12-15 day Carnatic music festival held at the Guruvayur Sree Krishna Temple in honour of maestro Chembai Vaidyanatha Bhagavatar, who conducted the festival for nearly 60 years. Now organised by the Guruvayur Devaswom, it draws 2,000-3,000 musicians who perform in an inclusive, non-competitive format, culminating in a group rendition of the Pancharatna Kritis on Guruvayur Ekadasi day (Vrishchikam, mid-November).');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8400049, 840, 840008, 'Guruvayur Ekadasi', 'Nov-Dec', 'Guruvayur Ekadasi is the most important festival of the Guruvayur Sree Krishna Temple, observed on the Ekadasi (11th day) of the bright fortnight in the Malayalam month of Vrishchikam. The temple marks it with Udayasthamana Pooja (dawn-to-dusk worship), Nirmalya Darshan, lamp-lit elephant processions (Vilakku Ekadasi), Dwadasi Panam, and kathakali performances - it commemorates the day Lord Krishna is believed to have revealed the importance of Ekadasi fasting to Arjuna.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8400050, 840, 840008, 'Machad Mamangam (Machad Kuthira Vela)', 'Feb-Mar', 'Machad Mamangam, also called Machad Kuthira Vela, is a temple festival at Thiruvanikkavu near Wadakkancherry in Thrissur district, organised competitively by five desams (Karumathra, Viruppakka, Mangalam, Parlikadu, Manalithara). Instead of live elephants, it features grand processions of giant wooden horses (kuthira) - a tradition born from a local king''s wish to rival the Uthralikkavu Pooram''s elephants without real horses. It begins on the first Friday of the Malayalam month of Kumbham with the main vela on the following Tuesday.');

-- city: Varkala (id 1050)
INSERT OR IGNORE INTO cities (id, state_id, city_name, latitude, longitude) VALUES (840009, 840, 'Varkala', 8.73833, 76.71922);

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000235, 840009, 'Varkala Cliff', 'Varkala Cliff', 'Iconic red laterite cliffs running ~7.5 km (Edava, North and South cliffs) beside the Arabian Sea; the only cliffed coastline in southern Kerala. Designated a National Geological Monument / geo-heritage site by the Geological Survey of India (2015) for its exposed Mio-Pliocene ''Warkalli Formation'' sediments (~2.58 million years old). The cliff-top walkway is lined with cafes, shops and yoga studios and is the town''s prime sunset viewpoint.', NULL, NULL, NULL, NULL, 'Kerala', 0, 0, NULL, NULL, NULL, NULL, NULL, 8.739763, 76.69961, NULL, NULL, NULL);

