INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000236, 840009, 'Papanasam Beach', 'Papanasam Beach', 'Varkala''s sacred beach; a dip here is believed to wash away sins (papanasam = ''destroyer of sins''). Famous for the natural mineral spring at the base of the North Cliff, whose waters are said to have curative properties. Southern section used for Hindu cremation/ancestral rituals; listed by Lonely Planet among the world''s 100 best beaches.', NULL, NULL, NULL, NULL, 'Kerala', 0, 0, NULL, NULL, NULL, NULL, NULL, 8.7344, 76.7023, NULL, NULL, NULL);

