INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000237, 840009, 'Janardanaswamy Temple', 'Janardanaswamy Temple', '2,000-year-old Vishnu temple on the cliffs overlooking the beach, also known as ''Dakshin Kashi''. Built in Kerala architectural style with a circular sanctum and copper-domed conical roof; only Hindus may enter the sanctum. Hosts the annual Arattu festival.', NULL, NULL, NULL, NULL, 'Kerala', 0, 0, NULL, NULL, NULL, NULL, NULL, 8.731887, 76.7099, 'Temple Road, Varkala 695141', NULL, NULL);

