INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000238, 840009, 'Sivagiri Mutt', 'Sivagiri Mutt', 'Ashram founded in 1904 by social reformer Sree Narayana Guru; his mahasamadhi (final resting place) is here, and it is the headquarters of the Sree Narayana Dharma Sangham. Draws lakhs of devotees for the Sivagiri Pilgrimage (Dec 30-Jan 1) and Guru Jayanti/Samadhi day celebrations (Aug-Sep).', NULL, NULL, NULL, NULL, 'Kerala', 0, 0, NULL, NULL, NULL, NULL, NULL, 8.738956, 76.732358, 'Sivagiri Rd, Varkala 695141', NULL, NULL);

