INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000239, 840009, 'Kappil Beach and Kappil Lake Backwaters', 'Kappil Beach and Kappil Lake Backwaters', 'Serene spot ~6-7 km north of Varkala where the backwaters meet the Arabian Sea. The Kappil Lake estuary offers boating, kayaking and stand-up paddleboarding through calm, palm-fringed waters; the bridge across the lake is a celebrated sunset viewpoint. The adjoining beach is uncrowded and peaceful.', NULL, NULL, NULL, NULL, 'Kerala', 0, 0, NULL, NULL, NULL, NULL, NULL, 8.757, 76.6905, NULL, NULL, NULL);

