INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (840000240, 840009, 'Ponnumthuruthu Island', 'Ponnumthuruthu Island', 'Small island in the Anjengo backwaters ~12 km south of Varkala, reached by a ~30-minute boat ride (private operators from Nedunganda). Known for its 100-year-old Shiva-Parvati temple and birdlife; boats are the only access and prices are set by private operators.', NULL, NULL, NULL, NULL, 'Kerala', 0, 0, NULL, NULL, NULL, NULL, NULL, 8.656, 76.697, NULL, 'https://www.keralatourism.org/destination/ponnumthuruthu-island-thiruvananthapuram/248/', NULL);

