INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8400053, 840, 840009, 'Onam', NULL, 'Kerala''s harvest festival, celebrated across Varkala with floral carpets (pookkalam), feasts (Onam sadya) and cultural performances.');

