INSERT OR IGNORE INTO photos (id, place_id, source_file, thumbnail_url, thumbnail_width, thumbnail_height, photo_title, photo_author, license, license_url, source_url, credit, usage_terms, description) VALUES (840800137, 840000197, 'File:Anantnatha Swami Jain temple at Wayanad Kerala India with Jain Tirthankaras and Vaishnava Hindu deities.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/73/Anantnatha_Swami_Jain_temple_at_Wayanad_Kerala_India_with_Jain_Tirthankaras_and_Vaishnava_Hindu_deities.jpg/960px-Anantnatha_Swami_Jain_temple_at_Wayanad_Kerala_India_with_Jain_Tirthankaras_and_Vaishnava_Hindu_deities.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 960, 1280, 'Anantnatha Swami Jain temple at Wayanad Kerala India with Jain Tirthankaras and Vaishnava Hindu deities.jpg', 'Ms Sarah Welch', 'CC BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 'https://commons.wikimedia.org/wiki/File:Anantnatha_Swami_Jain_temple_at_Wayanad_Kerala_India_with_Jain_Tirthankaras_and_Vaishnava_Hindu_deities.jpg', '', 'Creative Commons Attribution-Share Alike 4.0', 'Anantanath Swamy temple is a syncretic building wherein local Jains revere the Tirthankaras of Jainism along with various Jain and Vaishnava Hindu gods and goddesses. 
The syncretic tradition is old, and the sect had a medieval era stone temple that was damaged by the Islamic army of Tipu Sultan and is now in ruins few kilometers away. The community moved and relocated the temple and the deities to the current location. It is an active Jain temple in Puliyarmala, near Kalpetta in the Wayanad district in the state of Kerala in India. 

Photography inside the temple is prohibited by the Governme');

