INSERT OR IGNORE INTO photos (id, place_id, source_file, thumbnail_url, thumbnail_width, thumbnail_height, photo_title, photo_author, license, license_url, source_url, credit, usage_terms, description) VALUES (840800140, 840000200, 'File:Thirunelli Maha Vishnu temple in Wayanad region Kerala India.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/34/Thirunelli_Maha_Vishnu_temple_in_Wayanad_region_Kerala_India.jpg/960px-Thirunelli_Maha_Vishnu_temple_in_Wayanad_region_Kerala_India.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 960, 720, 'Thirunelli Maha Vishnu temple in Wayanad region Kerala India.jpg', 'Ms Sarah Welch', 'CC BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 'https://commons.wikimedia.org/wiki/File:Thirunelli_Maha_Vishnu_temple_in_Wayanad_region_Kerala_India.jpg', '', 'Creative Commons Attribution-Share Alike 4.0', 'Thirunelli Temple is a major Hindu temple in northern Kerala Brahmagiri hills. The temple is notable for being a place where the devotees can perform all the rites-of-passage ceremonies ranging from those related to birth of children to the post-cremation dedication of cremation of ashes into natural water stream.
The temple is also known as ''Sahyamala Kshetram and Kashi of the South. 
Thirunelli Temple is a pilgrimage site, particularly for South Indian Hindus to perform ancestral rites. The rituals are performed on the banks of the stream Papanasini which flows down from Mount Brahmagiri, ul');

