-- ============================================================================
-- TripRaft NATIONAL-SAFE SEED : MADHYA PRADESH
-- Generated: 2026-10-01
--
-- Real TripRaft schema:
--   places = attractions / sights
--   restaurants = restaurants
-- National metadata is stored in sidecar tables.
--
-- Hubs: Bhopal, Indore, Gwalior, Jabalpur, Ujjain, Khajuraho
-- Per hub: 20 attractions + 5 current restaurants
-- Totals: 120 attractions + 30 restaurants = 150 tourism entities
--
-- Verification basis:
-- * Attraction identities: Madhya Pradesh Tourism destination/current pages.
-- * Restaurant identities: current Sep/Oct 2026 Tripadvisor city listings.
-- * Hours/fees/photos are intentionally NULL unless explicitly source-backed.
-- * google_place_id is explicitly NULL in sidecar external-ID tables.
--
-- Preferred new state_id = 842, but the script reuses an existing
-- Madhya Pradesh state row by name if one is already present.
-- ============================================================================

INSERT OR IGNORE INTO countries (id,country_name) VALUES (31,'India');

INSERT INTO states (id,country_id,state_name,latitude,longitude)
SELECT 842,31,'Madhya Pradesh',22.9734,78.6569
WHERE NOT EXISTS (SELECT 1 FROM states WHERE state_name='Madhya Pradesh');

CREATE TABLE IF NOT EXISTS tripraft_state_meta (
 state_id INTEGER PRIMARY KEY,country_name TEXT NOT NULL,country_code TEXT NOT NULL,
 state_name TEXT NOT NULL,state_code TEXT NOT NULL,state_key TEXT NOT NULL UNIQUE,state_hash TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS tripraft_city_meta (
 city_id INTEGER PRIMARY KEY,country_name TEXT NOT NULL,country_code TEXT NOT NULL,
 state_name TEXT NOT NULL,state_code TEXT NOT NULL,city_key TEXT NOT NULL UNIQUE,city_hash TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS tripraft_place_meta (
 place_id INTEGER PRIMARY KEY,country_name TEXT NOT NULL,country_code TEXT NOT NULL,
 state_name TEXT NOT NULL,state_code TEXT NOT NULL,city_key TEXT NOT NULL,
 search_key TEXT NOT NULL,stable_key TEXT NOT NULL UNIQUE,stable_hash TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS tripraft_place_external_ids (
 place_id INTEGER PRIMARY KEY,google_place_id TEXT NULL);
CREATE TABLE IF NOT EXISTS tripraft_restaurant_meta (
 restaurant_id INTEGER PRIMARY KEY,country_name TEXT NOT NULL,country_code TEXT NOT NULL,
 state_name TEXT NOT NULL,state_code TEXT NOT NULL,city_key TEXT NOT NULL,
 search_key TEXT NOT NULL,stable_key TEXT NOT NULL UNIQUE,stable_hash TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS tripraft_restaurant_external_ids (
 restaurant_id INTEGER PRIMARY KEY,google_place_id TEXT NULL);

CREATE INDEX IF NOT EXISTS idx_tripraft_city_geo ON tripraft_city_meta(country_code,state_code,city_key);
CREATE INDEX IF NOT EXISTS idx_tripraft_place_search ON tripraft_place_meta(search_key);
CREATE INDEX IF NOT EXISTS idx_tripraft_place_hash ON tripraft_place_meta(stable_hash);
CREATE INDEX IF NOT EXISTS idx_tripraft_restaurant_search ON tripraft_restaurant_meta(search_key);

