INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000001, 841001, 'Gateway of India', 'Gateway of India', 'Mumbai''s most famous landmark: an Indo-Saracenic basalt arch built 1911-1924 to commemorate the landing of King George V and Queen Mary. It overlooks the Arabian Sea at Apollo Bunder and is the departure point for ferries to the Elephanta Caves.', '1 hour', 'Early morning or late evening', 'Visit at sunset for the best light and combine with a ferry ride to Elephanta Caves from the same jetty.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Free', 10, 8, 18.92217, 72.83387, 'Mahakavi Bhushan Marg, Apollo Bandar, Colaba, Mumbai, Maharashtra 400001', NULL, 1.84);

