INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000002, 841001, 'Elephanta Caves', 'Elephanta Caves', 'UNESCO World Heritage Site on Elephanta Island: 5th-8th century rock-cut Hindu cave temples dedicated to Shiva, including the famous Trimurti sculpture. Reached by an hour-long ferry ride from the Gateway of India.', '3-4 hours (including ferry)', 'November to February (cooler months)', 'Carry water and wear good walking shoes; the climb from the jetty is steep. Avoid Mondays.', NULL, 'Maharashtra', 0, 0, NULL, NULL, '₹40 (Indian), ₹600 (foreign)', 9, 8, 18.96323, 72.93227, 'Elephanta Island (Gharapuri), Mumbai Harbour, Maharashtra', 'https://whc.unesco.org/en/list/244', 1.72);

