INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000012, 841001, 'Mount Mary Basilica', 'Mount Mary Basilica', 'Historic Roman Catholic basilica on a Bandra hilltop overlooking the sea, dedicated to Our Lady of the Mount. Site of the annual Bandra Fair (Feast of the Nativity of Mary) every September, drawing pilgrims of all faiths.', '1-2 hours', 'Morning; September during Bandra Fair', 'Candle-sellers line the steps to the basilica; the sea view from the hilltop is the bonus. Expect big crowds during the September fair.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Free', 8, 8, 19.04655, 72.8224, 'Mount Mary Road, Bandra West, Mumbai, Maharashtra 400050', 'http://www.mountmarybasilicabandra.in/', 1.6);

