INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000024, 841001, 'Bademiya', 'Bademiya', 'Legendary Colaba street-food stall (est. 1946) for Mughlai kebabs and rolls - seekh kebabs, chicken tikka rolls, and boti fry served late into the night opposite the Gateway of India.', '45 minutes', 'Late evening', 'The Colaba stall (not the Horniman Circle fine-dine branch) is the authentic late-night experience. Kebabs are best after 10 PM.', NULL, 'Maharashtra', 0, 0, NULL, NULL, '₹500 for two (approx)', 8, 8, 18.92331, 72.83258, 'Tulloch Road, Apollo Bandar, Colaba, Mumbai, Maharashtra 400001', 'https://bademiya.org/', 1.6);

