INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000025, 841001, 'Swati Snacks', 'Swati Snacks', 'Beloved family-run Gujarati snack institution (since 1963) at Tardeo, famous for panki (banana-leaf steamed pancakes), dahi batata puri, sev puri, and hand-churned ice creams. A Mumbai food rite of passage.', '1 hour', 'Evening snack time', 'Expect a queue - put your name down and snack while you wait. Panki and filter coffee ice cream are must-orders. Pure vegetarian.', NULL, 'Maharashtra', 0, 0, NULL, NULL, '₹400 for two (approx)', 8, 8, 18.96651, 72.81345, '248, Karai Estate, opposite Bhatia Hospital, Tardeo Road, Mumbai, Maharashtra 400007', 'https://www.swatisnacks.com/', 1.6);

