INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000026, 841001, 'Shree Thaker Bhojanalay', 'Shree Thaker Bhojanalay', 'Historic (est. 1945) Gujarati thali restaurant down a crowded Kalbadevi lane: unlimited all-you-can-eat thali with undhiyu, aamras, puran poli, and seasonal specials. A bucket-list meal for vegetarian travellers.', '1-1.5 hours', 'Lunch', 'No reservations; go for lunch and be prepared to queue. The unlimited thali refills make it excellent value.', NULL, 'Maharashtra', 0, 0, NULL, NULL, '₹1,300 for two (approx)', 9, 8, 18.95114, 72.82823, 'Building No 31, Purshottam Niwas, Dadiseth Agyari Lane, Kalbadevi, Mumbai, Maharashtra 400002', 'https://shreethakerbhojanalay.com/', 1.72);

