INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000055, 841003, 'Zero Mile Stone', 'Zero Mile Stone', 'The Zero Mile Stone is a historic sandstone pillar erected in 1907 by the British, marking the geographical centre of colonial India. It is the reason Nagpur is celebrated as the ''Zero Mile City''. The pillar stands in a small landscaped enclosure near the GPO in Civil Lines.', '15-30 min', 'Early morning or evening for photos; anytime during the day', 'Combine with a walk around Civil Lines; look for the distance markings on the pillar itself.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'free', 8, 6, 21.14984, 79.08061, 'Nagpur GPO Rd, Civil Lines, Nagpur', NULL, 1.44);

