INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000056, 841003, 'Deekshabhoomi', 'Deekshabhoomi', 'Deekshabhoomi is the sacred Buddhist stupa where Dr. B. R. Ambedkar embraced Buddhism along with hundreds of thousands of followers on 14 October 1956. It is the spiritual centre of the Neo-Buddhist movement and a symbol of equality, drawing lakhs of pilgrims every year, especially on Dhamma Chakra Pravartan Diwas.', '1.5-2 hours', 'Early morning or evening; 14 Oct for the Dhamma Chakra Pravartan Diwas gathering', 'Shoes must be removed in the stupa area; the complex is large and walking-heavy, so carry water.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'free', 10, 9, 21.128185, 79.066959, 'S Ambazari Rd, Nagpur 440010', 'http://www.deekshabhoomi.org/', 1.92);

