INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000070, 841003, 'Ramtek Temple (Shri Ram Mandir)', 'Ramtek Temple (Shri Ram Mandir)', 'Ancient hilltop temple complex at Ramtek, ~50 km northeast of Nagpur, where legend says Lord Rama rested during his exile. The 600-year-old shrine is linked to Kalidasa''s Meghaduta, and the Kalidas Smarak stands nearby.', '2-3 hours (half-day trip from Nagpur)', 'October-March; early morning for the hill climb', 'Combine with the Kalidas Smarak; plan a half-day trip from Nagpur by cab.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'free', 8, 8, 21.38865, 79.32476, 'Ramtek, Nagpur District', NULL, 1.6);

