INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000072, 841003, 'Pench Tiger Reserve (Sillari Gate)', 'Pench Tiger Reserve (Sillari Gate)', 'The Maharashtra side of the famous Pench Tiger Reserve (the inspiration for Kipling''s The Jungle Book), accessed via Sillari Gate. Morning and evening jeep safaris offer good tiger and leopard sighting chances.', 'Half to full day (safari slots)', 'October-June; March-May for best sightings', 'Book permits on the official Maharashtra forest booking portal well in advance; the reserve closes during the monsoon.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Permit approx ₹1,000-1,500 per vehicle + gypsy approx ₹2,500 + guide approx ₹375', 10, 10, 21.57742, 79.287733, 'Sillari Gate, Pench Tiger Reserve, Maharashtra side', 'https://safaribooking.mahaforest.gov.in/', 2.0);

