INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000073, 841003, 'Shri Poddareshwar Ram Mandir', 'Shri Poddareshwar Ram Mandir', 'Grand 1923 sandstone-and-marble Ram temple built by the Poddar family near Mayo Hospital. It is the starting point of Nagpur''s famous annual Ram Navami Shobha Yatra, now over 60 years old.', '1 hour', 'Morning or evening aarti; Ram Navami (March/April) for the Shobha Yatra', 'On Ram Navami, arrive early — the Shobha Yatra starts from here around 4 PM and the area fills up fast.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'free', 9, 8, 21.15327, 79.0919, 'Central Avenue Road, near Mayo Hospital, Nagpur', NULL, 1.72);

