INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8410009, 841, 841003, 'Marbat Festival', NULL, 'Nagpur''s unique centuries-old festival held in the month of Bhadrapada (Aug-Sep). Giant effigies called Marbats — symbolizing evil forces, social evils and issues troubling society — are paraded through the city with music and chants alongside smaller Badgya effigies, and then set ablaze, symbolizing the triumph of good over evil. It blends cultural tradition with sharp social commentary.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8410010, 841, 841003, 'Dhamma Chakra Pravartan Diwas', NULL, 'Observed on 14-15 October at Deekshabhoomi, commemorating Dr. B. R. Ambedkar''s mass conversion to Buddhism with lakhs of followers on 14 October 1956. Lakhs of Buddhists gather annually (coinciding with Dussehra/Ashoka Vijayadashami); mass conversions continue at the site.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8410011, 841, 841003, 'Ram Navami Shobha Yatra', NULL, 'Grand annual procession on Ram Navami (Chaitra, March-April) starting from Shri Poddareshwar Ram Mandir in Mahal, Nagpur, and passing through Itwari, Mahal, Sitabuldi and Variety Square. Features 90+ jhankis (tableaus) of Ramayana scenes, the Ram Rath, dhol-tasha and lezim performances. A 60+ year tradition (the 60th yatra was held in 2026, attended by the CM and Nitin Gadkari).');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8410012, 841, 841003, 'Kalidas Festival', NULL, 'Organised by MTDC since 1996 at Nagardhan (Nandiwardhan) Fort in Ramtek, honouring the Sanskrit poet Kalidasa — who composed the Meghaduta at Ramtek. A multi-day festival of classical music, dance and drama with national artists, held to promote tourism in the region.');

