INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8410013, 841, 841004, 'Nashik-Trimbakeshwar Simhastha Kumbh Mela', NULL, 'One of the four Simhastha Kumbh sites; millions bathe in the Godavari at Ramkund (Nashik) and at Trimbakeshwar. The next cycle''s ceremony period was announced by the Maharashtra government as 31 Oct 2026-24 Jul 2028, with the main Amrit Snan bathing days in August-September 2027.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8410014, 841, 841004, 'SulaFest', NULL, 'Annual vineyard music festival at Sula Vineyards, Nashik, mixing Indian and international artists, wine, food and camping. The 14th edition was held 1-2 Feb 2025 (after a 5-year break); the 15th edition was held 31 Jan-1 Feb 2026 and sold out.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8410015, 841, 841004, 'Nashik Grape Harvest Festival', NULL, 'Annual 2-day festival organized by Maharashtra Tourism, listed on the Ministry of Tourism''s utsav.gov.in portal: around 50 grape farmers and ~12 wineries showcase the region''s wine and grape culture.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8410016, 841, 841004, 'Saptashrungi Chaitrotsav', NULL, 'The biggest festival at Saptashrungi Devi Temple, Vani (Nashik district), observed from Rama Navami to Chaitra Poornima; up to ~1 million devotees attend over the festival days.');

