INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8410021, 841, 841005, 'Maha Shivaratri at Grishneshwar Jyotirlinga', 'February-March', 'The principal annual festival at the Grishneshwar Jyotirlinga near Ellora: abhishekam, devotional singing and all-night vigils drawing thousands of devotees.');

