INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000133, 841006, 'Upvan Lake', 'Upvan Lake', 'Thane''s largest and most-loved public lake, set against the Yeoor hill foothills in Thane West. A popular sunrise-to-sunset hangout with a promenade, boating, lakeside cafes and the annual Upvan Arts Festival.', '2-3 hours', 'October to February, early morning or late evening', 'Combine with the Yeoor Hills gate nearby for a half-day outing; the lakeside is busiest on winter weekend evenings.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 5, 4, 19.21066, 72.9613, 'Upvan Lake Road, Vartak Nagar, Thane West, Maharashtra 400606', NULL, 0.92);

