INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000137, 841006, 'Ghodbunder Fort', 'Ghodbunder Fort', 'A 17th-century Portuguese-built hill fort overlooking the creek at Ghodbunder, later held by the Marathas and British. Mostly in ruins but evocative, with sweeping creek views and a landmark chimney the village is named after (''ghod-bander'' = horse landing).', '1-2 hours', 'October to February, daytime', 'Go with daylight to spare; the approach is rural and facilities are minimal.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 3, 3, 19.29591, 72.88822, 'Ghodbander Village, Ghodbunder, Mira Bhayander, Maharashtra 401107', NULL, 0.6);

