INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000138, 841006, 'Thane Creek Flamingo Sanctuary', 'Thane Creek Flamingo Sanctuary', 'A Ramsar-listed wetland on Thane Creek famous for its winter flamingos — over 100,000 greater and lesser flamingos arrive November–March, along with waders and raptors. Best experienced from the Airoli-side Coastal and Marine Biodiversity Centre or creek boat rides.', '2-3 hours', 'November to March, low tide mornings for flamingo viewing', 'Carry binoculars; flamingos are tide-dependent, so time your visit around low tide.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 5, 4, 19.14789, 72.98448, 'Coastal & Marine Biodiversity Centre, Sector 10, Airoli, Navi Mumbai, Maharashtra 400708 (sanctuary spans the Thane Creek side)', NULL, 0.92);

