INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000139, 841006, 'Ovalekar Wadi Butterfly Garden', 'Ovalekar Wadi Butterfly Garden', 'A privately developed 2-acre butterfly garden in Ovale village by Rajendra Ovalekar and family — a former paddy plot replanted with hundreds of flowering species, home to 100+ butterfly species with a guided 9:30 AM lifecycle talk on Sundays.', '2-3 hours', 'March–May and September–November (butterfly seasons); Sundays only', 'Reach before 9:30 AM for the guided talk, and bring binoculars and a camera — entry is Sundays only.', NULL, 'Maharashtra', 0, 0, NULL, NULL, '₹100 adults / ₹50 children', 4, 5, 19.26986, 72.95547, 'Owala Takkarada Road, Owale, Ghodbunder Road, Thane West, Maharashtra 400615', NULL, 0.88);

