INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000158, 841006, 'Mahesh Lunch Home (Thane)', 'Mahesh Lunch Home (Thane)', 'The coastal-seafood legend''s Thane outpost — Mahesh Lunch Home''s Mangalorean coastal menu (butter garlic crab, ghee roast, pomfret tawa) in a premium club setting near Vihang Garden. Pricier than the Fort/Mumbai original but the go-to seafood dinner in Thane.', '1-2 hours', 'Dinner; weekends need a table', 'The Thane outlet is at Vihang Garden/Vihang''s Palm Club on Pokhran Road No. 1 — order the butter garlic crab or ghee roast.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 4, 4, 19.20834, 72.963587, 'Vihang Garden / Vihang''s Palm Club, Pokhran Road No. 1, near Raymonds Showroom, Thane West, Maharashtra 400606', 'http://www.maheshlunchhome.com/', 0.8);

