INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000159, 841007, 'Shri Mahalakshmi Temple, Kolhapur', 'Shri Mahalakshmi Temple, Kolhapur', 'One of the three-and-a-half Shaktipeethas, this ancient temple dedicated to Goddess Mahalakshmi (Ambabai) was built by the Chalukya king Karnadeva in the 7th century in Hemadpanti style. Unusually, the idol faces west, and during Kirnotsav the setting sun''s rays fall directly on the deity. It is the spiritual heart of Kolhapur and a major pilgrimage stop on the Tirupati-Kolhapur-Padmawati yatra circuit.', '2-3 hours', 'October-March; Navratri (Sep-Oct) is the grandest but most crowded; Kirnotsav in late Jan/early Feb and November for the sun-ray phenomenon', 'Go very early morning (Kakad aarti ~4:30 AM) for the shortest queues; free chappal stands operate at all four gates, and Mahadwar Road outside is lined with puja shops and Kolhapuri chappal stores.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Free general darshan; paid special-darshan tickets (~Rs 200-300) at the temple counter per third-party booking guide', 5, 5, 16.69748, 74.22407, 'Mahadwar Road, Bhausinghji Road, Shivaji Peth, Kolhapur, Maharashtra 416012', NULL, 1.0);

