INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000159, 'insert', 'bulk', 'Temple existence, Shaktipeetha status and 7th-century Chalukya origin verified via Wikipedia; darshan hours (5 AM-10 PM) cross-checked across meta.ai listing, TripAdvisor reviews and gokshetra.com. The temple trust''s domain www.mahalaxmikolhapur.com currently returns 404 and the alternate domain shreekarveernivasini.com does not resolve, so no official website is listed.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000160, 841007, 'New Palace (Shri Chhatrapati Shahu Museum)', 'New Palace (Shri Chhatrapati Shahu Museum)', 'Built 1877-1884 after the Rajwada fire, this black polished-stone palace blends Jain, Hindu and Victorian architecture with a distinctive clock tower. The ground floor houses the Shri Chhatrapati Shahu Museum - royal costumes, weapons, silver elephant saddles, a Darbar Hall with stained-glass scenes from Shivaji''s life and paintings including Raja Ravi Varma - set in manicured gardens with a small zoo.', '2-3 hours', 'October-February; late afternoon for the best garden light', 'The museum covers only the ground floor - the royal family still resides upstairs; combine the visit with nearby Rankala Lake.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Rs 40 adult, Rs 20 child (trawell.in; some guides list lower - confirm at counter)', 5, 4, 16.71933, 74.23177, 'New Palace, Ramanmala (Chhatrapati Shahu Place), Kolhapur, Maharashtra 416003', NULL, 0.92);

