INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000161, 841007, 'Rankala Lake', 'Rankala Lake', 'A scenic lake on Kolhapur''s west side built by Chhatrapati Shahu Maharaj, with the Shalini Palace on its eastern bank. It is the city''s beloved evening promenade - boating, a chowpatty of street-food stalls, and sunset views over the water make it the default unwind spot for locals and visitors alike.', '1-2 hours', 'Evenings year-round; October-February for pleasant weather', 'Go at sunset for the best light, then walk the chowpatty for local snacks and take a paddle-boat ride.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 4, 4, 16.68986, 74.21065, 'Rankala, Kolhapur, Maharashtra 416012', NULL, 0.8);

