INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000162, 841007, 'Panhala Fort', 'Panhala Fort', 'The largest fort of the Deccan, immortalised by Shivaji''s dramatic 1660 escape from Siddi Johar''s siege and Baji Prabhu Deshpande''s rearguard stand at Pawankhind. Its ramparts hold the Teen Darwaza, Sajja Kothi, Andhar Bavadi stepwell and sweeping views over the Sahyadris - a must for Maratha-history enthusiasts.', 'Half day', 'October-February; monsoon for lush green views (roads can be slippery)', 'Hire a local guide at the fort for the Shivaji-escape stories; easily combined with nearby Jyotiba Temple in one trip.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 5, 4, 16.80873, 74.10764, 'Panhala Fort - Teen Darwaza, Panhala, Kolhapur district, Maharashtra 416205 (approx 20 km northwest of Kolhapur)', NULL, 0.92);

