INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000163, 841007, 'Bhavani Mandap', 'Bhavani Mandap', 'A historic palace complex in the heart of old Kolhapur built under the Chhatrapatis, once the seat of the Kolhapur state''s court. Its courtyards and halls - including the old Rajwada, Faras Khana and a small museum of royal memorabilia - sit within walking distance of the Mahalakshmi Temple and anchor the heritage core of the city.', '1 hour', 'Morning; pair with a Mahalakshmi Temple visit', 'It is minutes on foot from the Mahalakshmi Temple - cover both in one morning walk through old Kolhapur.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 4, 4, 16.69469, 74.22443, 'Bhavani Mandap, M L G High School Road, Shivaji Peth, Kolhapur, Maharashtra 416002', NULL, 0.8);

