INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000164, 841007, 'Town Hall Museum', 'Town Hall Museum', 'Set in a neo-Gothic building erected in 1872-76 as Kolhapur''s Town Hall, this museum displays artefacts excavated at nearby Brahmhapuri Hill. Its seven galleries hold Satavahana-era relics - most famously a bronze figurine of the Greek god Poseidon and elephant-rider figurines - evidence of ancient Indo-Roman trade through this region.', '1-2 hours', 'Weekday mornings for a quiet visit', 'Do not miss the Poseidon figurine - it is the star exhibit and a remarkable trace of Kolhapur''s ancient global links.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Free entry (makemytrip.com)', 3, 4, 16.70137, 74.22494, 'Town Hall Garden, Bhausinghji Road (Kolhapur Station Road), Shukrawar Peth, Kolhapur, Maharashtra 416002', NULL, 0.68);

