INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000165, 841007, 'Jyotiba Temple', 'Jyotiba Temple', 'Hilltop temple of Lord Jyotiba - worshipped as the combined form of Brahma, Vishnu and Mahesh and the kuldaivat of countless Maharashtra families - near Wadi Ratnagiri. It is famed for the annual Chaitra Yatra fair, when lakhs of devotees throw gulaal that turns the whole hill pink, and for the Sasan Kathi bamboo-pole procession to Goddess Yamai''s temple.', '2-3 hours', 'October-March; the Chaitra Yatra (March-April) is spectacular but extremely crowded', 'Shared jeeps and special buses run from Kolhapur during the yatra; at other times hire a cab, as the last stretch is a steep climb.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 5, 5, 16.79472, 74.17639, 'Jyotiba Hill, Wadi Ratnagiri, Panhala taluka, Kolhapur district, Maharashtra 416229 (approx 18 km northwest of Kolhapur)', NULL, 1.0);

