INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000166, 841007, 'Siddhagiri Gramjivan Museum (Kaneri Math)', 'Siddhagiri Gramjivan Museum (Kaneri Math)', 'A 7-acre open-air museum within the Siddhagiri Math at Kaneri depicting pre-industrial Maharashtrian village life through 300+ life-size wax and cement sculptures arranged in about 80 scenes - farming, crafts, festivals, the 12 Balutedar artisan castes. The campus also has an ancient Shiva temple with a 42-foot idol, a goshala of native cattle breeds, gardens and a children''s play area.', '3-4 hours', 'September-February; mornings', 'Wear comfortable shoes - it involves a lot of walking; the on-campus restaurant serves simple Maharashtrian meals and there is a children''s mini-train.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Rs 100 adult, Rs 50 child (triphobo.com/velpu.com; trawell.in lists Rs 100 per person)', 4, 5, 16.612081, 74.265372, 'Shri Kshetra Siddhagiri Math, Kaneri, near Pune-Bangalore Highway, Kolhapur district (approx 14 km from Kolhapur)', NULL, 0.88);

