INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000167, 841007, 'Shalini Palace', 'Shalini Palace', 'An Italianate palace built in 1931-34 for the Kolhapur royals on the eastern bank of Rankala Lake, using black stone and Italian marble. Now operating as a heritage hotel, it is best admired from the Rankala promenade, where its colonnaded facade reflects on the lake at sunset.', '30-45 minutes (exterior)', 'Evening, from the Rankala Lake promenade', 'It is a working hotel - admire it from the lake promenade or ask at reception about dining access for a look inside.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 3, 3, 16.69331, 74.20752, 'Shalini Palace, Phulewadi Main Road, Rankala, Kolhapur, Maharashtra 416012', NULL, 0.6);

