INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000168, 841007, 'Kopeshwar Temple, Khidrapur', 'Kopeshwar Temple, Khidrapur', 'A 12th-century Shilahara-era Shiva temple at Khidrapur on the banks of the Krishna - ''Kopeshwar'' means the angry Shiva. Built in the Bhumija style with a star-shaped plan, its Swargamandapa and richly carved pillars have earned it the nickname ''Khajuraho of Maharashtra''. It is grand yet famously incomplete, with Mahashivratri as its biggest festival.', '2 hours', 'October-March; monsoon is the prettiest; Mahashivratri draws the biggest crowds', 'There are no proper eateries in Khidrapur village - eat in Kolhapur or Kurundwad first; buses are infrequent, so drive or hire a cab.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 4, 5, 16.615898, 74.685138, 'Kopeshwar Temple, Khidrapur village, Shirol taluka, Kolhapur district, Maharashtra (approx 57 km east of Kolhapur, on the Krishna river)', NULL, 0.88);

