INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000169, 841007, 'Narsobawadi (Shri Nrusinha Saraswati Datta Temple)', 'Narsobawadi (Shri Nrusinha Saraswati Datta Temple)', 'The principal Datta kshetra, where Shri Nrusinha Saraswati - the purna avatar of Lord Dattatreya - is believed to have lived for 12 years. There is no idol here; the sacred padukas (footwear) under an Audumbara tree are worshipped. The temple stands at the serene confluence of the Krishna and Panchganga rivers, with Datta Jayanti and Narsimha Jayanti as its major festivals.', '2-3 hours', 'October-March; Datta Jayanti (December) is the biggest festival', 'ST buses run from Kolhapur, Sangli and Miraj (5 AM-11 PM); avoid the monsoon peak when the sangam ghats can flood.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 4, 4, 16.6833, 74.6, 'Narsobawadi (Nrusinhwadi), Shirol taluka, Kolhapur district, Maharashtra 416104 (approx 51 km east of Kolhapur)', NULL, 0.8);

