INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000169, 'insert', 'bulk', 'Village coordinates 16.69, 74.60 from Wikipedia (16°41''N 74°36''E); temple aarti schedule (5 AM-10 PM) and 51 km distance from amazingmaharashtra.com; geocoder returned an unrelated Datta temple inside Kolhapur city and was not used.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000170, 841007, 'Vishalgad Fort', 'Vishalgad Fort', 'A 12th-century Sahyadri hill fort (built by Shilahara ruler Bhoja II) where Shivaji took refuge in 1660 after his escape from Panhala - the escape made possible by Baji Prabhu Deshpande''s famous rearguard stand. Mostly rampart walls remain today, alongside a dargah and the Baji Prabhu memorial, with sweeping valley views from 1,090 m.', 'Half day', 'October-February; avoid monsoon (slippery trails)', 'Check current local conditions/advisories before visiting, start the climb early with water and a local guide - it is a genuine trek.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 3, 4, 16.90611, 73.74333, 'Vishalgad (Khelna) Fort, Shahuwadi taluka, Kolhapur district, Maharashtra (approx 76 km northwest of Kolhapur)', NULL, 0.68);

