INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000171, 841007, 'Temblai Temple (Temlabai Mandir)', 'Temblai Temple (Temlabai Mandir)', 'Hilltop shrine of Goddess Temblai (Tryamboli/Renuka), regarded locally as the sister of Goddess Mahalakshmi. Beyond its spiritual pull, the hill is one of Kolhapur''s best sunset viewpoints, with a large Ganpati idol on the plateau and a children''s park nearby. During Navratri, the Ambabai palanquin procession travels here from the Mahalakshmi Temple.', '1-2 hours', 'Sunrise or sunset; Navratri for the palanquin procession', 'The best city panorama in Kolhapur - go at dusk; make sure your navigation pins the main hilltop shrine, as an older namesake temple exists far away.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Free entry (travelsetu.com)', 3, 4, 16.69792, 74.25862, 'Temblai Hill, Vikramnagar / Uchgaon area, eastern Kolhapur, Maharashtra', NULL, 0.68);

