INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000171, 'insert', 'bulk', 'Temple identity, hill location and Navratri procession verified via Wikipedia and travelsetu.com (hours 5 AM-9 PM, free entry). Geocoder returned an unnamed ''Place of Worship'' on Uchgaon Main Road near the hill (relevance 99); coordinates used but exact pinpoint is approximate - flag for re-verification.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000172, 841007, 'Khasbag Maidan', 'Khasbag Maidan', 'A hundred-year-old wrestling ground and the beating heart of Kolhapur''s kushti tradition, patronized by Chhatrapati Shahu Maharaj. The arena seats around 60,000 around a circular mud ring, with a separate enclosure for the royal family - visit at dawn to watch pehlwans training in the red earth.', '1 hour', 'Early morning to watch training; during kushti tournaments', 'Pair the visit with Khau Galli street food nearby; morning is when the akhada is most alive.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 3, 4, 16.69294, 74.22583, 'Khasbag Maidan, Pratibha Nagar Road, Mangalwar Peth, Kolhapur, Maharashtra 416012 (near Mahalakshmi Temple)', NULL, 0.68);

