INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000173, 841007, 'Binkhambi Ganesh Mandir', 'Binkhambi Ganesh Mandir', 'A much-loved Ganesh shrine on Mahadwar Road, the bazaar street leading to the Mahalakshmi Temple. Pilgrims traditionally stop here before or after Ambabai darshan, and the surrounding street is Kolhapur''s famous shopping strip for Kolhapuri chappals, sweets and puja items.', '30 minutes', 'Morning; combine with Mahadwar Road shopping', 'Mahadwar Road is Kolhapur''s Kolhapuri-chappal and sweet shopping strip - browse the shops after darshan.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 3, 3, 16.6931, 74.22279, 'Binkhambi Ganesh Mandir, Mahadwar Road, Shivaji Peth, Kolhapur, Maharashtra 416012', NULL, 0.6);

