INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000174, 841007, 'Dajipur Wildlife Sanctuary', 'Dajipur Wildlife Sanctuary', 'Dense evergreen forest in the Radhanagari Wildlife Sanctuary, best known as a stronghold of the Indian bison (gaur) - herds are often sighted at dawn. The sanctuary also shelters leopards, sloth bears, wild dogs and giant squirrels, making it the top wildlife day-trip from Kolhapur for nature lovers.', 'Full day', 'October-March; wildlife sightings best at dawn', 'Start early from Kolhapur - it is a long drive each way; carry binoculars and check monsoon access restrictions.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 4, 4, 16.38375, 73.86343, 'Dajipur Wildlife Sanctuary, Radhanagari taluka, Kolhapur district, Maharashtra (approx 80 km south of Kolhapur; part of Radhanagari Wildlife Sanctuary)', NULL, 0.8);

