INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000175, 841007, 'Gaganbawda', 'Gaganbawda', 'A small Sahyadri hill station and ghat-pass town on the winding road from Kolhapur down to the Konkan coast. Misty viewpoints, monsoon waterfalls and cool air make it a refreshing stopover, and it is the gateway to the nearby Gagangad fort - popular with riders and monsoon chasers.', 'Half day / day trip', 'June-February; monsoon for waterfalls and mist', 'Ideal stop en route to the Konkan coast (Vengurla/Malvan); the ghat roads are winding - drive in daylight.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 3, 4, 16.54662, 73.8318, 'Gaganbawda, Kolhapur district, Maharashtra (approx 55 km southwest of Kolhapur, on the Kolhapur-Konkan ghat road)', NULL, 0.68);

