INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000176, 841007, 'Panchganga Ghat', 'Panchganga Ghat', 'The riverside ghats of the Panchganga in Kolhapur city, where temples and stone steps draw locals for evening rituals and quiet reflection. It is a calm, photogenic sunset spot and a window into the everyday spiritual life of the city away from the temple crowds.', '1 hour', 'Evenings, especially around sunset', 'Visit around sunset when the ghats are liveliest; the stone steps can be slippery - wear grippy footwear.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 3, 3, 16.70461, 74.21608, 'Panchganga Ghat, Guru Shankracharya Math Rasta, Sutar Mala, Kolhapur, Maharashtra 416012', NULL, 0.6);

