INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000177, 841007, 'Hotel Dehati', 'Hotel Dehati', 'A Kolhapur institution for fiery non-vegetarian Kolhapuri thalis - mutton thali with unlimited tambda (red) and pandhra (white) rassa, mutton loncha (pickle-style mutton), bhakri and Indrayani rice. Also serves veg thalis. A long-running local favorite near Tararani Chowk that travelers plan meals around.', '1 hour', 'Lunch or dinner', 'Order the mutton thali - the tambda/pandhra rassa refills are the point; the kitchen winds down by about 10:30 PM.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Moderate (Rs Rs price band; thali-focused menu per TripAdvisor)', 5, 4, 16.704179, 74.249371, 'Shop No. 25, Ayodhya Park, Tararani Chowk, Old Pune-Bangalore Highway, Kolhapur, Maharashtra 416005', NULL, 0.92);

