INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000177, 'insert', 'bulk', 'Listed as ''Dehaati'' on TripAdvisor (300+ reviews, Tararani Chowk address, hours 12:15 PM-3 PM / 7:30 PM-10:30 PM) and as ''Hotel Dehati'' in travel blogs (tripoto review: 50 m from Opal Hotel); coordinates 16.704179, 74.249371 from a meta.ai listing at Ayodhya Park, Tararani Chowk. The name is spelled both Dehati and Dehaati locally.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000178, 841007, 'Hotel Opal', 'Hotel Opal', 'Serving authentic Kolhapuri cuisine since 5 December 1968, Hotel Opal is famous for its tambda and pandhra rassa - winning the Times Foodie Award 2012 for best local cuisine. Its large dining hall serves Kolhapuri non-veg thalis and Maharashtrian veg thalis with what the house calls ''hospitality with simplicity''.', '1 hour', 'Lunch or dinner', 'The veg thali with vegetarian pandhra rassa is excellent too - a good pick for mixed veg/non-veg groups.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Rs RsRs (TripAdvisor price range approx Rs 250-800 per person)', 5, 4, 16.70683, 74.24811, '2104-16A, E Ward, Old Pune-Bangalore Road, Near Tararani Chowk, Opp. MAI Hyundai Showroom, Kolhapur, Maharashtra 416005', 'https://hotelopal.co.in/', 0.92);

