INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000179, 841007, 'Hotel Padma', 'Hotel Padma', 'A branch of the 65-year-old Padma Guest House, serving traditional tambda rassa, pandhra rassa, mutton loncha and fry preparations in thali form. An old-city favorite near the highway known for home-style Kolhapuri non-veg cooking, with simple rooms above for overnight stays.', '1 hour', 'Lunch', 'Try the mutton loncha thali - the pickle-style mutton is Padma''s signature dish.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Rs Rs-RsRsRs (TripAdvisor price band)', 4, 4, 16.7147, 74.24351, 'Near Dhairyaprasad Hall, Circuit House Road (Indumati Road), Tarabai Park, Kolhapur, Maharashtra 416003', NULL, 0.8);

