INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000180, 841007, 'Chorage Misal', 'Chorage Misal', 'A Kolhapuri misal institution since 1959, now run by the third generation, steps from the Mahalakshmi Temple. Its fiery misal is built on 50+ home-ground spices with the signature ''kat'' - a layer of spicy red oil - plus fresh farsan, and the house introduced solkadhi as a cooling accompaniment. Live kitchen counter, clean and hygienic setup.', '45 minutes', 'Breakfast or evening snack', 'Ask for extra kat if you like it fiery, and pair the misal with their solkadhi to cool down.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 5, 5, 16.696202, 74.222022, 'Mahadwar Road, near Bank of India, Swarup Chambers, Kolhapur (about 50 steps from Mahalakshmi Temple)', 'https://choragemisal.com/', 1.0);

