INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000181, 841007, 'Phadtare Misal Center', 'Phadtare Misal Center', 'A no-frills, legendary misal joint in Udyam Nagar beloved by locals - thick pav unlike the usual, fresh farsan, fiery rassa and solkadhi served after. It opens only in the morning and shuts by 2 PM, so the limited seating fills fast with devoted regulars.', '45 minutes', 'Morning, before noon', 'Come before noon - it sells out and shuts by 2 PM; parking is tight, so take an auto-rickshaw.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Budget (Rs) (TripAdvisor price band)', 4, 4, 16.694374, 74.233218, '1243, 4th Lane, near Laxmi Ice Factory, Udyam Nagar, Kolhapur', NULL, 0.8);

