INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000182, 841007, 'Bawada Misal', 'Bawada Misal', 'A beloved neighborhood misal spot in Kasaba Bawada serving classic Kolhapuri misal with kat and farsan. A local favorite for breakfast - unpretentious, spicy and true to the Kolhapuri misal tradition.', '45 minutes', 'Morning', 'A local favorite - go early in the morning for the freshest batch.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 4, 4, 16.73138, 74.24247, 'Bawada Misal, Kasaba Bawada Main Road, Kasaba Bawada, Kolhapur, Maharashtra 416006', NULL, 0.8);

