INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8410025, 841, 841007, 'Navratri at Mahalakshmi Temple', 'September-October', 'Sharadiya Navratri is the grandest festival at the Ambabai temple - nine nights of special alankars (decorations), music and massive pilgrim crowds. During Navratri, the goddess''s palanquin procession travels from the Mahalakshmi Temple to the Temblai Temple, her ''sister'' shrine on Temblai Hill.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8410026, 841, 841007, 'Kirnotsav (Sun-Ray Festival)', 'January-February and November', 'Twice a year - around January 31-February 2 and November 9-11 - the setting sun''s rays pass through the Mahadwar and fall directly on the Mahalakshmi idol for three evenings. This celebrated solar-architectural event, noted by the Devasthan committee, draws thousands of devotees to the temple.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8410027, 841, 841007, 'Jyotiba Chaitra Yatra', 'March-April', 'The annual fair on the full moon of Chaitra (and Vaishakha) at the Jyotiba Temple, Wadi Ratnagiri. Lakhs of devotees gather as the hill turns pink with thrown gulaal; highlights include the Sasan Kathi (tall bamboo-pole) procession and the evening palanquin procession of Lord Jyotiba to Goddess Yamai''s temple with fireworks.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8410028, 841, 841007, 'Kolhapur International Film Festival', 'February', 'An annual multi-day international film festival celebrating Kolhapur''s rich cinema heritage, honoring filmmakers with the Kalamaharshi Baburao Painter Award (the 7th edition ran in February 2019 with Hungarian cinema as the focus country). Recent editions could not be verified - confirm the current year''s schedule before planning around it.');

-- city: Solapur (id 1068)
INSERT OR IGNORE INTO cities (id, state_id, city_name, latitude, longitude) VALUES (841008, 841, 'Solapur', 17.65812, 75.90684);

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000183, 841008, 'Shri Siddheshwar Temple', 'Shri Siddheshwar Temple', 'Solapur''s most famous landmark: a 12th-century Shiva temple dedicated to the yogi-saint Shri Siddharameshwar, built on an island in the middle of a large lake he is said to have constructed. The Hemadpanthi-style shrine with its pillared mandapa and surrounding promenade is both the city''s chief pilgrimage site and its most photographed spot. It hosts the annual Gadda Yatra fair at Makar Sankranti.', '1-2 hours', 'October to March; early morning or evening for peaceful darshan', 'Remove footwear before entering and stick to the lakeside promenade path for circumambulation; photography inside the sanctum is usually prohibited.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Free entry (no ticket)', 5, 5, 17.67029, 75.9034, 'Pujya Suggaldevi Chowk, Siddheshwar Temple Talav, Siddheshwar Peth, Solapur 413001', 'https://shrisiddheshwar.org/', 1.0);

