INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000184, 841008, 'Bhuikot Fort (Solapur Fort)', 'Bhuikot Fort (Solapur Fort)', 'A rare land fort (''Bhuikot'' = fort on the ground, not a hill) adjoining the Siddheshwar Temple lake, built in the 14th century under the Bahamanis and later held by the Adil Shahis, Mughals and Marathas. Its massive stone walls, bastions and gateways — including the Daru Darwaza — make it Solapur''s key heritage monument. Visit for the rampart walk and views over the old city.', '1-2 hours', 'October to February, morning or late afternoon', 'Combine with the adjacent Siddheshwar Temple — both are within a 10-minute walk of each other.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 4, 4, 17.67507, 75.90253, 'Ganesh Ghat Road, Solapur Fort, Siddheshwar Peth, Solapur 413001', NULL, 0.8);

