INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000185, 841008, 'Shri Vitthal Rukmini Temple, Pandharpur', 'Shri Vitthal Rukmini Temple, Pandharpur', 'One of Maharashtra''s holiest shrines — the main temple of Lord Vitthal (Vithoba, a form of Vishnu/Krishna) and his consort Rukmini, standing on the banks of the Chandrabhaga river. Pilgrims here can traditionally touch the Lord''s feet (pad-sparsh darshan), a rarity among major temples. It is the destination of the great Wari pilgrimages on Ashadhi and Kartiki Ekadashi.', '2-4 hours (full day with Chandrabhaga ghat)', 'October to March; avoid Wari peak days unless attending the pilgrimage', 'Book a free online darshan pass on the temple committee''s official site well in advance — it lets you skip the long general queue; verify passes at Tukaram Bhavan near Namdev gate.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Free general darshan; free online slot booking available', 5, 5, 17.67743, 75.33612, 'Shri Vitthal Rukmini Mandir Samiti, Pandharpur 413304, Dist. Solapur', 'http://vitthalrukminimandir.org/', 1.0);

