INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000186, 841008, 'Shri Swami Samarth Mandir, Akkalkot', 'Shri Swami Samarth Mandir, Akkalkot', 'The principal shrine of Shri Swami Samarth Maharaj, the 19th-century saint revered as an incarnation of Lord Dattatreya, who lived his last 22 years in Akkalkot. The complex includes the samadhi shrine and the Vatavriksha Mandir enclosing the banyan tree under which the Swami preached. The adjacent Anna Chhatra serves free mahaprasad meals to thousands of pilgrims daily.', 'Half day (with Samadhi Math)', 'October to March; Thursdays and Purnima draw larger crowds', 'Time your visit around the Anna Chhatra meal hours (12-3 PM, 9-11 PM) for the free mahaprasad; accommodation in the trust''s yatri niwas can be booked via the official site.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Free darshan; free mahaprasad at the Anna Chhatra', 5, 5, 17.51979, 76.20717, 'Swami Samarth Mandir, Vidyanagar, Akkalkot, Maharashtra 413216', 'https://swamiannacchatra.org/', 1.0);

