INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000187, 841008, 'Shri Tulja Bhavani Temple, Tuljapur', 'Shri Tulja Bhavani Temple, Tuljapur', 'One of Maharashtra''s 3.5 Shakti Peethas, this Hemadpanthi-style temple is dedicated to Goddess Tulja Bhavani, the family deity (kuldevi) of the Marathas and of Chhatrapati Shivaji Maharaj, who is believed to have received his sword from her. The black-stone shrine draws lakhs during Navratri; Tuesdays, Fridays and Sundays are especially auspicious days here.', '2-3 hours', 'October to March; avoid Navratri week unless attending the festival', 'On Tuesdays, Fridays and Sundays darshan opens very early (from ~1 AM) — go at dawn on regular days to avoid 5-7 hour queues; book the Denagi pass online on the official site for faster access.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Free general darshan; Denagi (priority) darshan pass Rs. 300 per official site', 5, 4, 17.99403, 76.08411, 'Raje Shahaji Mahadwar Road, Jijamata Nagar, Tuljapur 413601', 'https://shrituljabhavani.org/', 0.92);

