INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000188, 841008, 'Great Indian Bustard Sanctuary, Nannaj', 'Great Indian Bustard Sanctuary, Nannaj', 'A grassland wildlife sanctuary famous as one of the last strongholds of the critically endangered Great Indian Bustard, Maharashtra''s state bird. The dry scrub habitat also supports blackbuck, Indian wolf, chinkara and many raptors and migratory birds, making it Solapur district''s prime birdwatching and wildlife destination.', '2-3 hours', 'October to March, early morning for bird activity', 'Go at sunrise with binoculars and a local guide — bustards are shy and hard to spot; carry water as the grassland has no facilities.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 4, 4, 17.82807, 75.86114, 'Nannaj, Solapur North, Maharashtra 413222 (approx 20 km north of Solapur city)', NULL, 0.8);

