INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000189, 841008, 'Solapur Science Centre', 'Solapur Science Centre', 'A regional science centre with interactive exhibits, a planetarium-style sky theatre and 3D/science shows aimed at students and families. A good 1-2 hour educational stop in the city, especially for children, covering physics, astronomy and the human body through hands-on displays.', '1-2 hours', 'Year-round; weekdays are quieter', 'Call ahead to confirm show timings on the day of your visit — planetarium and 3D shows run on fixed schedules.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 3, 3, 17.70756, 75.87847, '33/1 Solapur Road, Raj Hans Nagar, Solapur North 413255', NULL, 0.6);

