INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000190, 841008, 'Hipparga Lake (Ekrukh Hipparga Talav)', 'Hipparga Lake (Ekrukh Hipparga Talav)', 'A large lake (Ekrukh Hipparga Talav) on Solapur''s northern edge, popular as an evening hangout and picnic spot with open water views, migratory birds in winter and sunset points along the bund. A calm nature break close to the city.', '1-2 hours', 'October to March, late afternoon to sunset', 'Visit at sunset and carry snacks — there are few food stalls; combine with the nearby Solapur Science Centre.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 3, 3, 17.71774, 75.91025, 'Tale Hipparaga, Solapur North, Maharashtra 413002', NULL, 0.6);

