INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000191, 841008, 'Dharmaveer Sambhaji Talav (Sambhaji Lake)', 'Dharmaveer Sambhaji Talav (Sambhaji Lake)', 'A city lake and garden complex (Dharmaveer Sambhaji Talav) with boating facilities — pedalos and rowboats — plus a children''s play area and evening food stalls. One of Solapur''s most popular family recreation spots, busy on weekends and holidays.', '1-2 hours', 'October to March, 4-7 PM', 'Boating counters can have long queues on Sunday evenings — go on a weekday afternoon for a relaxed ride.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 3, 4, 17.64647, 75.90059, 'Chatrapati Sambhaji Talav, Kambad Talav, Solapur 413004', NULL, 0.68);

