INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000192, 841008, 'Naldurg Fort', 'Naldurg Fort', 'A formidable 16th-century hill-top fort of the Adil Shahi sultans, later taken by the Mughals and the Nizam, set above the Bori river gorge. Its high bastions, the Hulburz bastion, water pavilions and the waterfall below (in monsoon) make it the best fort excursion near Solapur.', '2-3 hours', 'October to March; waterfall best just after monsoon', 'Wear sturdy shoes — the climb to the bastions is steep; carry water as there are no shops inside the fort.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 4, 4, 17.81546, 76.28446, 'Naldurg, Tuljapur 413602, Dist. Dharashiv (approx 50 km from Solapur)', NULL, 0.8);

