INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000193, 841008, 'Ujjani Dam', 'Ujjani Dam', 'A major earthen dam on the Bhima river (about 100 km northwest of Solapur city) creating a vast reservoir that is one of Maharashtra''s best winter birding sites — flamingos, bar-headed geese and demoiselle cranes arrive in large flocks. The dam top offers sweeping water views and is a popular monsoon/winter picnic drive from Solapur.', 'Half day (day trip from Solapur)', 'November to February for migratory birds', 'Bring binoculars in winter — the reservoir''s backwaters host thousands of migratory waterbirds; it is a long day trip, so start early.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 3, 4, 18.05315, 75.12046, 'Ujjani Dam Office, Pune Solapur Highway, Madha 413212, Dist. Solapur', NULL, 0.68);

