INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000194, 841008, 'Mahatma Gandhi Zoo, Solapur', 'Mahatma Gandhi Zoo, Solapur', 'A small municipal zoo in the city with deer, monkeys, birds and a children''s park attached — a modest but easy family outing, usually combined with the nearby Sambhaji Lake gardens.', '1 hour', 'October to March, morning', 'Manage expectations — this is a small city zoo; pair it with Sambhaji Lake nearby to make a fuller outing.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 2, 3, 17.65095, 75.90052, 'Soni Nagar, Modi Hudko, Solapur 413004', NULL, 0.48);

