INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000195, 841008, 'Revan Siddheshwar Temple', 'Revan Siddheshwar Temple', 'An old Shiva temple near Motibaug Tank dedicated to Revanasiddheshwar, a revered Lingayat saint. The temple and adjoining tank area are known for birdwatching — migratory birds flock to the water in winter — blending a quiet religious stop with nature.', '45-60 minutes', 'October to March, morning for birds', 'Combine with the Motibaug Tank birding area next to the temple in winter months.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 3, 3, 17.64901, 75.89937, 'Revan Siddheshwar Mandir, Vijapur Naka, Solapur 413004', NULL, 0.6);

