INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000196, 841008, 'Hazrat Shah Zahur Dargah', 'Hazrat Shah Zahur Dargah', 'A historic Sufi dargah in Solapur''s old city dedicated to Hazrat Shah Zahur, drawing devotees of all faiths, especially on Thursdays. The shrine''s old-city setting, qawwali evenings and the surrounding lanes make it a window into Solapur''s composite culture.', '45-60 minutes', 'Year-round; Thursday evenings are liveliest', 'Dress modestly and visit in the evening when the shrine is most atmospheric; explore the old Kasba lanes around it on foot.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 3, 3, 17.67767, 75.9064, 'Dakshin Kasba Main Road, South Kasba, Solapur 413001', NULL, 0.6);

