INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000197, 841008, 'Shri Swami Samarth Samadhi Math (Vatavriksha), Akkalkot', 'Shri Swami Samarth Samadhi Math (Vatavriksha), Akkalkot', 'The samadhi (memorial shrine) of Shri Swami Samarth within the Vatavriksha complex at Akkalkot — the banyan-tree temple where the saint lived and preached for 22 years. Pilgrims typically visit this together with the main Swami Samarth Mandir; the math runs accommodation and the annachhatra nearby.', '1-2 hours', 'October to March', 'Visit this and the main temple in one trip — they are minutes apart in Akkalkot town; use the Anna Chhatra for meals and yatri niwas if staying overnight.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Free darshan', 5, 5, 17.52697, 76.2064, 'Navin Rajwada, Akkalkot, Maharashtra 413216', 'https://swamiannacchatra.org/', 1.0);

