INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000198, 841008, 'Hutatma Garden', 'Hutatma Garden', 'A public garden near the fort and Siddheshwar Temple dedicated to the memory of Solapur''s 1930 martyrs — the four freedom fighters hanged after the 1930 uprising, when Solapur briefly enjoyed independence under martial law. The garden has walking paths, lawns and memorial statuary (Char Hutatma Putala nearby), popular for morning walks.', '45-60 minutes', 'October to March, morning or evening', 'Go early morning when local walkers are out; pair with the fort and Siddheshwar Temple, all within walking distance.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 3, 3, 17.67562, 75.90154, 'Laxmi Market Road, Solapur Fort, Siddheshwar Peth, Solapur 413001', NULL, 0.6);

