INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000199, 841008, 'Shri Pundlik Temple, Pandharpur', 'Shri Pundlik Temple, Pandharpur', 'The temple of Pundalik, the devotee on whose brick (vit) Lord Vitthal stands — the very legend behind Pandharpur''s name and the Vitthal cult. Located near the Chandrabhaga river, it is a customary stop after the main Vitthal darshan and gives context to the whole pilgrimage.', '30-45 minutes', 'October to March', 'Visit right after the Vitthal temple — it completes the Pandharpur story; the Chandrabhaga ghat is a short walk away.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Free entry', 4, 4, 17.67805, 75.33235, 'Pandharpur Road, Mahaveer Nagar, Pandharpur 413304', NULL, 0.8);

