INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000200, 841008, 'Bhagwant Temple, Barshi', 'Bhagwant Temple, Barshi', 'An ancient Vishnu temple at Barshi (about 70 km north of Solapur) built in the Hemadpanthi style, famous for its intricately carved stone architecture and inscriptions. One of the finest old temples in Solapur district and a rewarding day trip for heritage lovers.', '1-2 hours (plus drive)', 'October to March', 'Go in daylight to appreciate the stone carvings; Barshi town has basic eateries for lunch.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Free entry', 4, 4, 18.23327, 75.69429, 'Bhagwant Mandir, NH-548C, Barshi 413401, Dist. Solapur', NULL, 0.8);

