INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000201, 841008, 'Parasnath Jain Temple', 'Parasnath Jain Temple', 'An old Jain temple in Solapur''s market quarter dedicated to Parshvanath, noted for its finely carved stone architecture, serene meditation hall and peaceful atmosphere amid busy bazaar lanes. A quiet heritage stop in the old city.', '45-60 minutes', 'Year-round, morning', 'Note the temple closes in the afternoon — plan a morning or early-evening visit; the surrounding lanes are great for old-city walks.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Free entry', 3, 4, 17.66741, 75.90782, 'Rupa Bhavani Rd, Shaniwar Peth, Solapur, Maharashtra 413002', NULL, 0.68);

