INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000202, 841008, 'Jamia Masjid, Solapur', 'Jamia Masjid, Solapur', 'Solapur''s historic congregational mosque in the old city near Begum Peth, serving the city''s large Muslim community. Its old-city setting among traditional markets makes it a notable stop for understanding Solapur''s layered religious heritage.', '30 minutes', 'Year-round; outside prayer hours for a quiet visit', 'Dress modestly and avoid visiting during Friday congregational prayers; explore the Begum Peth market lanes nearby.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 2, 3, 17.67239, 75.9087, 'Jama Masjid Road, Begum Peth, Solapur 413001', NULL, 0.48);

