INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000203, 841008, 'Valsang Vaada Pure Vegetarian Family Restaurant', 'Valsang Vaada Pure Vegetarian Family Restaurant', 'Solapur''s most famous highway restaurant, set like a traditional Maharashtrian wada (courtyard mansion) with open-air and rooftop seating on the Solapur-Akkalkot highway. The pure-veg menu leans into authentic Maharashtrian thalis, bhakri-pithla, zunka and other rural specialities, plus banquet lawns and lodging — a landmark stop for travellers to Akkalkot.', '1-1.5 hours', 'Lunch or dinner; weekends are crowded', 'Expect a wait on weekend evenings — arrive before 8 PM; try the Maharashtrian thali and zunka-bhakri.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Rs. 200-400 per person', 4, 4, 17.5956, 76.06533, 'Solapur - Akkalkot Highway, Valsang, Solapur 413228', NULL, 0.8);

