INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000204, 841008, 'Gadag Express Restaurant', 'Gadag Express Restaurant', 'Solapur''s beloved train-themed vegetarian restaurant — a decades-old Udupi-style eatery reborn inside a railway-coach-themed dining hall near the station. Famous for crisp masala dosas, idli and South Indian breakfast served fast and cheap; a nostalgic city institution.', '45-60 minutes', 'Breakfast and lunch; closed by evening', 'Go for breakfast — masala dosa is the signature; seating is compact, so expect a short wait at peak hours.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Rs. 250 for two', 4, 4, 17.67639, 75.89869, 'Oasis Mall, Station Road (Pune Road), Murarji Peth, Solapur 413001', NULL, 0.8);

