INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000205, 841008, 'Hotel Mezzanine', 'Hotel Mezzanine', 'A popular rooftop multicuisine restaurant on Vijapur Road known for its open-air setting with live music. The menu spans North Indian, Mughlai, Chinese, Kolhapuri and seafood, but locals come for the Malvani mutton handi, chicken biryani and kebabs — one of Solapur''s go-to non-veg family dinner spots.', '1-1.5 hours', 'Dinner; rooftop is best after sunset', 'Order the mutton handi or chicken biryani; request a rooftop table for the evening ambience.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Rs. 200-400 per person', 4, 4, 17.61531, 75.89457, 'Plot No 9, Sai Park, Vijapur Rd, opp. AG Patil Engineering College, Solapur 413008', NULL, 0.8);

