INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000206, 841008, 'Sugran Pure Vegetarian', 'Sugran Pure Vegetarian', 'A long-running pure-veg restaurant near Solapur railway station serving home-style Maharashtrian thalis — dal, kadhi, seasonal sabzis, bhakri and thecha — cooked and served by Marathi women. A traveller favourite for an authentic, affordable Solapuri meal; offers limited and unlimited thali options.', '45-60 minutes', 'Lunch (12-3 PM) or dinner', 'Pick the unlimited thali if you''re hungry — it''s the signature; the small dining hall fills up on weekends, so go early.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 4, 4, 17.66614, 75.89626, '55/56 Station Road, Railway Lines, Solapur 413001', NULL, 0.8);

