INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000207, 841008, 'Hotel Priyanka', 'Hotel Priyanka', 'A Solapur institution for non-veg lovers, famous for its mutton biryani, butter chicken, chicken makrana and kebabs at budget-friendly prices. Bustling, no-frills dining with family AC seating — the place locals recommend first for a hearty non-vegetarian meal.', '1 hour', 'Lunch or dinner', 'Try the mutton biryani and chicken makrana kebab; the crowd skews male groups in the evening — families should ask for the AC family section.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 4, 4, 17.66607, 75.91068, 'Civil Chowk, Near Civil Court, Solapur 413003', NULL, 0.8);

