INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000208, 841008, 'Kamat Restaurant', 'Kamat Restaurant', 'A well-rated pure-veg family restaurant near the railway lines serving North Indian, Chinese and South Indian staples — paneer dishes, veg kurma, dosas and pulao. A dependable mid-range dinner option for vegetarian families staying near the station area.', '1 hour', 'Lunch or dinner', 'Good fallback near the station for a clean veg family meal; paneer preparations and dosas are the safer bets.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 3, 3, 17.66275, 75.90063, 'Sahyadri Shopping Complex, Below State Bank of India, Old Employment Chowk, Railway Lines, Solapur 413007', NULL, 0.6);

