INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8410029, 841, 841008, 'Shri Siddheshwar Yatra (Gadda Yatra)', 'January (Makar Sankranti)', 'Solapur''s biggest annual religious fair, held at the Shri Siddheshwar Temple. The 900-year-old Gadda Yatra centers on a symbolic marriage ritual of Lord Siddheshwar — two Nandi Dhwaja poles (bride and groom) are carried in procession, with the ''marriage'' performed on Makar Sankranti day — followed by a 15-day cultural fair around the temple lake.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8410030, 841, 841008, 'Pandharpur Wari (Ashadhi Ekadashi)', 'June-July (Ashadha month)', 'One of Maharashtra''s largest pilgrimages: lakhs of warkaris walk from Alandi and Dehu to Pandharpur in Solapur district, converging on the Vitthal Rukmini Temple for Ashadhi Ekadashi. Pandharpur is ~70 km from Solapur city and the Wari routes pass through Solapur district.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8410031, 841, 841008, 'Kartiki Ekadashi Yatra, Pandharpur', 'October-November (Kartika month)', 'The second great yatra to Pandharpur, when warkaris again gather at the Vitthal Rukmini Temple on Kartiki Ekadashi. A major pilgrimage event in the Solapur region with special rituals at the temple and on the Chandrabhaga ghats.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8410032, 841, 841008, 'Sharadiya Navratri at Tulja Bhavani, Tuljapur', 'September-October (Ashwin month)', 'The nine-night Sharadiya Navratri festival at the Shri Tulja Bhavani Temple in Tuljapur (~45 km from Solapur), one of Maharashtra''s 3.5 Shakti Peethas. The temple''s own site describes it as the most important worship period of the goddess, drawing lakhs of devotees; a Shakambari Navratri is also celebrated in December-January.');

-- city: Amravati (id 1069)
INSERT OR IGNORE INTO cities (id, state_id, city_name, latitude, longitude) VALUES (841009, 841, 'Amravati', 20.93373, 77.75944);

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000209, 841009, 'Shri Ambadevi Temple', 'Shri Ambadevi Temple', 'Ancient Shakti temple dedicated to Goddess Ambadevi, situated in the heart of Amravati near Gandhi Square and mentioned in old gazetteers; the city is said to be named after this temple. Legend holds that Lord Krishna eloped with Rukmini from this spot. It draws devotees from across Vidarbha, especially during Navratri.', '1-2 hours', 'October to February; Navratri (September-October) for the fair and festivities', 'Parking near the temple is very limited; park near the HVPM ground area and walk in, and visit early morning on Tuesdays and during Navratri to avoid heavy crowds.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 5, 4, 20.92676, 77.74936, 'Ravi Nagar Road, Devdatt Nagar, Patwipura (near Gandhi Square), Amravati 444601, Maharashtra', NULL, 0.92);

