INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000210, 841009, 'Shri Ekvira Devi Temple', 'Shri Ekvira Devi Temple', 'Historic Devi temple located a few steps from the Ambadevi Temple on HVPM Road, traditionally said to have been built around 1660 by Paramhans Shri Janardan Swami. Devotees who visit Ambadevi during Navratri customarily also visit Ekvira Devi. The two temples together form Amravati''s principal Shakti pilgrimage complex.', '30 minutes to 1 hour', 'October to February; Navratri (September-October)', 'Combine with the Ambadevi Temple visit next door; both are walkable from each other near Gandhi Square.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 4, 4, 20.92676, 77.74936, 'H V P M Road, Devdatt Nagar, Patwipura, Amravati 444601, Maharashtra', NULL, 0.8);

