INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000211, 841009, 'Satidham Temple', 'Satidham Temple', 'Popular temple complex in the heart of the city at Rallies Plot with idols of Lord Krishna and Radha, Lord Ram and Sita, Lord Ganesh, Lord Shiva and Rani Satiji. A large fair is organized here every year on Janmashtami, drawing huge crowds of devotees.', '1 hour', 'October to February; Janmashtami for the annual fair', 'Expect very large crowds during the Janmashtami fair; visit on a regular weekday for a calm darshan.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 4, 4, 20.92965, 77.75581, 'Rallies Plot, Hamalpura, Amravati 444601, Maharashtra', NULL, 0.8);

