INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000212, 841009, 'Chatri Talao', 'Chatri Talao', 'Heritage reservoir built in 1888 on a small spring called Kali Nadi to supply drinking water to Amravati (the city now gets water from Upper Wardha Dam). Set about 1 km from Dasturnagar Square on Malkhed Railway Road, it has a small garden and boating facility and is a favourite evening and weekend spot for locals.', '1-2 hours', 'October to March; evenings for the lake ambience', 'Visit between sunrise and sunset for boating and the garden; the lakeside grassland edge is the quietest walking stretch.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 4, 4, 20.90774, 77.76662, 'Amravati Old Bypass, Dastur Nagar, Amravati 444606, Maharashtra', NULL, 0.8);

