INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000213, 841009, 'Wadali Talao', 'Wadali Talao', 'Picturesque suburban reservoir about 3 km from Amravati Camp on Chandur Railway Road, originally built to supply fresh water to the Amravati Camp area. It has a small garden with a zoo and boating, making it one of the city''s best weekend picnic spots, especially for families with kids.', '2-3 hours', 'October to March; weekends for the full picnic atmosphere', 'Go in the morning for the zoo and garden, then do boating in the late afternoon when the light is best for photos.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 4, 4, 20.92819, 77.79298, 'Chandur Railway Road, Wadali, Amravati 444602, Maharashtra', NULL, 0.8);

