INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000214, 841009, 'Shri Bhakti Dham Temple', 'Shri Bhakti Dham Temple', 'Temple on Amravati-Badnera Road with idols of Lord Krishna and Radha and of Sant Jalaram Bappa, set in Bhaktidham Colony. A small children''s park behind the temple makes it a pleasant family stop combining devotion with a short outing for kids.', '1 hour', 'October to February', 'Good to combine with a drive toward Badnera; the children''s park behind the temple keeps young kids engaged.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 3, 3, 20.89908, 77.74836, 'Badnera Road, Bhaktidham Colony, Sai Nagar, Amravati 444607, Maharashtra', NULL, 0.6);

