INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000215, 841009, 'ISKCON Amravati (Sri Sri Rukmini Dwarkadhish Mandir)', 'ISKCON Amravati (Sri Sri Rukmini Dwarkadhish Mandir)', 'ISKCON temple in Amravati dedicated to Sri Sri Rukmini Dwarkadhish (Krishna), located at Saraswati Colony, Rathi Nagar on VMV Road. It holds regular aartis, kirtans and festival celebrations such as Janmashtami and Gaur Purnima, and is an active Krishna-consciousness centre for the city.', '1 hour', 'Year-round; Janmashtami and Gaur Purnima for special celebrations', 'Time your visit for the evening aarti and kirtan for the full ISKCON experience.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 3, 4, 20.95277, 77.76694, 'Saraswati Colony, Rathi Nagar, VMV Road, Amravati 444603, Maharashtra', NULL, 0.68);

