INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000216, 841009, 'Bamboo Garden', 'Bamboo Garden', 'A bamboo garden near Wadali in Amravati, listed among the city''s notable green attractions. It is a calm, shaded spot good for a short nature walk and photography, and pairs well with a visit to nearby Wadali Talao.', '1 hour', 'October to March', 'Combine with Wadali Talao in a single half-day outing; mornings are the most pleasant.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 3, 3, 20.92163, 77.79453, 'Wadali, Amravati 444602, Maharashtra', NULL, 0.6);

