INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000216, 'insert', 'bulk', 'Listed among Amravati''s top places in a Marathi tourist video and on trip.com''s Amravati attractions; geocoder resolved Bamboo Garden, Wadali with 100% relevance.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000217, 841009, 'Melghat Tiger Reserve', 'Melghat Tiger Reserve', 'One of the first nine tiger reserves notified in India under Project Tiger (declared 1974), spread over about 1677 sq km on the southern offshoot of the Satpura range in Amravati district. Its teak-dominated dry deciduous forests shelter Bengal tigers, leopards, sloth bears, dhole, gaur and over 250 bird species. Semadoh is the main tourist centre with jungle camps and safari access.', '2 days (including at least two safaris)', 'December to May for safaris; the reserve is closed during the monsoon and wildlife census periods', 'Book safaris through the Forest Department at Amravati or the Nature Interpretation Centre at Chikhaldara; early-morning and evening safaris give the best wildlife sightings. Wear earthy, non-bright clothing.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 5, 5, 21.51185, 77.30368, 'Semadoh, Dharni Tahsil, Amravati District, Maharashtra 444813', 'https://amravati.gov.in/en/tourism-melghat/', 1.0);

