INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000217, 'insert', 'bulk', 'Verified on the official Amravati district government tourism page (area, 1974 declaration, Semadoh as main centre, safari gates) and Project Tiger references; coordinates geocoded to Semadoh village in the reserve with 97% relevance. Official site fetched and confirmed to belong to the district administration''s Melghat tourism page.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000218, 841009, 'Chikhaldara', 'Chikhaldara', 'The only hill station in the Vidarbha region of Maharashtra, set on a high plateau at about 1100 m above sea level, roughly 85 km from Amravati. It is dotted with viewpoints such as Panchbol Point, Devi Point, Hariken Point, Prospect Point and Malviya (Sunrise) Point, plus Bhimkund, Shakkar Lake and the Vairat safari gate into Melghat. The area is also known for its coffee plantations, unique in Maharashtra.', '2 days', 'October to February for cool weather; monsoon (July-September) for lush greenery and waterfalls', 'Panchbol Point''s natural echo and the sunrise at Malviya Point are must-dos; carry warm clothing for December-January nights when temperatures drop below 10 C.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 5, 5, 21.40126, 77.32664, 'Chikhaldara, Amravati District, Maharashtra 444807', 'https://amravati.gov.in/en/tourism-melghat/', 1.0);

