INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000219, 841009, 'Gavilgad Fort (Gawilgad)', 'Gavilgad Fort', 'Historic hill fort on a 1103 m high spur of the Satpura range, about 2.5 km southeast of Chikhaldara. Originally a mud fort of the Gavli pastoralists, it was rebuilt in stone by Ahmad Shah Wali of the Bahmani dynasty in 1425, passed through Imadshahi, Mughal and Maratha hands, and was stormed by Arthur Wellesley in 1803. It has massive gateways, a Pathan-style mosque, water tanks and old cannons, set against Melghat forest.', '3-4 hours', 'November to March', 'Visit early morning or late evening; wild animals are sometimes seen drinking at the pond outside the fort. Carry water and sun protection as the site is exposed.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 4, 4, 21.38363, 77.33556, 'Near Chikhaldara, Amravati District, Maharashtra 444807', NULL, 0.8);

