INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000220, 841009, 'Bhimkund (Kichakdari)', 'Bhimkund', 'A deep blue natural water tank and waterfall near Chikhaldara, wrapped in Mahabharata legend: it is believed Bhima created the pool by striking the ground after slaying Keechaka. Listed by the district administration among Chikhaldara''s tourist attractions, it is valued for its serenity, striking geology and photography.', '1-2 hours', 'October to February; monsoon for the waterfall at its fullest', 'The approach involves a short walk through forest; wear sturdy footwear and avoid the monsoon-swollen edges of the pool.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 4, 4, 21.39406, 77.34663, 'Near Chikhaldara, Amravati District, Maharashtra 444807', NULL, 0.8);

