INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000221, 841009, 'Gugamal National Park', 'Gugamal National Park', 'National park carved out of the Melghat sanctuary in 1987, forming the core area (about 361 sq km) of the Melghat Tiger Reserve in the Gavilgarh hills of the Satpura range. It protects tigers, leopards, sloth bears, gaur, sambar, wild dogs and a rich birdlife in dense teak and bamboo forest.', '1 day (as part of a Melghat visit)', 'December to May; closed during monsoon', 'Access is regulated as a tiger reserve core area; plan safaris via the Forest Department and the Chikhaldara/Semadoh gates.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 4, 4, 21.46232, 77.16725, 'Chikhaldara, Amravati District, Maharashtra 444807', NULL, 0.8);

