INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000222, 841009, 'Kaundanyapur', 'Kaundanyapur', 'Ancient village about 45 km from Amravati believed to be Kundinpur, the birthplace of Rukmini and the spot from which Krishna eloped with her. The Vitthal Rukmini temple on a hill overlooking the Wardha river is the focal point, alongside smaller temples to Ganesha, Vithala and Ambika. The annual Kaundinyapur Yatra on Kartik Purnima draws thousands of devotees.', 'Half day', 'October to February; November for the annual Kaundinyapur Yatra', 'The temple sits atop a hill; wear comfortable walking shoes and carry water, as facilities around the village are basic.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 4, 3, 20.97584, 78.14145, 'Kaundanyapur, Tiosa Taluka, Amravati District, Maharashtra 444709', NULL, 0.72);

