INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000223, 841009, 'Upper Wardha Dam (Nal Damayanti Sagar)', 'Upper Wardha Dam', 'Large earthfill dam on the Wardha river near Simbhora in Morshi taluka, also called Nal Damayanti Sagar. Built for irrigation, drinking water supply, flood control and hydropower, its vast reservoir is today also Amravati city''s drinking water source and a scenic stop for dam viewpoints and sunset views.', '1-2 hours', 'October to February', 'The Simbhora dam viewpoint (T-point) is popular at sunset; this is an active dam site, so stay within the designated public areas.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 3, 3, 21.27558, 78.05572, 'MDR-42, Near Simbhora, Morshi, Amravati District, Maharashtra 444905', NULL, 0.6);

