INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000224, 841009, 'Narnala Fort', 'Narnala Fort', 'Massive hill fortress on the edge of Melghat, about 12 miles north of Akot in Akola district (Amravati division). Traditionally founded around the 10th century by Gavli kings and repaired by Ahmad Shah Bahmani around 1425, it passed through Bahmani, Imadshahi, Mughal and Maratha hands before the British took it in 1803. Its walls wind for miles around the hill with 22 gates, 360 bastions and perennial water tanks.', 'Half day', 'November to February', 'The fort enclosure is large and overgrown in places; go with a local guide, wear trekking shoes and carry plenty of water.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 4, 4, 20.46288, 76.93986, 'SH-198, Near Patur, Akola District, Maharashtra 444501', NULL, 0.8);

