INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000225, 841009, 'Tukdoji Maharaj Samadhi', 'Tukdoji Maharaj Samadhi', 'Samadhi shrine of Rashtra Sant Tukdoji Maharaj at Mozari on NH-6, a revered spiritual figure of Vidarbha known for his bhajans and social work. The site hosts a major annual yatra drawing tens of thousands of devotees and is an important pilgrimage stop on the Amravati-Nagpur highway.', '1-2 hours', 'October to February; during the annual yatra', 'It is right on NH-6, so it is an easy stopover on the Amravati-Nagpur drive; expect big crowds during the annual yatra.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 3, 3, 21.05705, 78.00432, 'NH-6, Mozari, Tiosa, Amravati District, Maharashtra 444902', NULL, 0.6);

