INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000226, 841009, 'Achalpur Fort', 'Achalpur Fort', 'Historic fort remains at Achalpur (the old Berar capital Ellichpur), about 30 km north of the Gavilgad region. The town was the seat of the Imadshahi dynasty and a key Bahmani-era centre, and the fort ruins are a reminder of its medieval importance on the Deccan plateau.', '1-2 hours', 'October to February', 'Achalpur town itself is historic (old Ellichpur); pair the fort with the town''s old mosques and gateways for a fuller heritage walk.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 3, 3, 21.24887, 77.50248, 'Fort Bag, Salebad, Achalpur, Amravati District, Maharashtra 444806', NULL, 0.6);

