INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000227, 841009, 'The Grand Mehfil', 'The Grand Mehfil', 'One of Amravati''s best-known restaurants and hotels on Camp Road, rated among the city''s most reviewed dining spots. It serves North Indian, Chinese and fast food in a family-friendly setting, with the Spice Kitchen outlet handling lunch service. A reliable pick for celebratory family dinners and visiting guests.', '1-2 hours', 'Lunch and dinner hours', 'It also operates as a hotel, so it is a convenient dinner option if you are staying nearby in the Camp area; weekends can be busy.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Mid-range multi-cuisine (Indian, Chinese, fast food); Spice Kitchen outlet serves lunch 11:00 AM-3:00 PM daily per published listing', 4, 4, 20.93546, 77.7709, 'Camp Road, Behind Daya Sagar Hospital, Girls High School Square, Amravati 444602, Maharashtra', NULL, 0.8);

