INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000228, 841009, 'New Eagle Restaurant', 'New Eagle Restaurant', 'Well-known Punjabi family restaurant in Amravati, listed among the city''s top-rated restaurants with thousands of reviews. It specialises in North Indian and Punjabi dishes in a casual family-dining format, making it a go-to for butter chicken, tandoor and thali-style meals.', '1-1.5 hours', 'Lunch and dinner hours', 'Order the tandoor starters and Punjabi mains; it is popular with families, so arrive before peak dinner hours.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 4, 4, 20.92951, 77.7586, 'Amravati-Chandur Railway Road, Khaparde Bagicha, Hamalpura, Amravati 444606, Maharashtra', NULL, 0.8);

