INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000229, 841009, 'South Kitchen', 'South Kitchen', 'Down-to-earth South Indian restaurant in the Gadage Nagar/Rathi Nagar area specialising in various types of dosa, along with sweets and snacks. A solid pick for breakfast or light meals when you want crisp dosas and filter coffee away from the North Indian-heavy restaurant scene.', '45 minutes to 1 hour', 'Breakfast and evening snack hours', 'Try the special dosa varieties and the sweets counter; it is a casual spot, so expect quick turnover rather than long sit-down dinners.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 3, 4, 20.94717, 77.7647, 'SH-242, Gadage Nagar-Rathi Nagar, Amravati 444603, Maharashtra', NULL, 0.68);

