INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000230, 841009, 'Meet N Melt', 'Meet N Melt', 'Popular pure-veg casual restaurant on Shankar Nagar Road with over a thousand ratings, known for budget-friendly fast food, snacks and North Indian veg fare. A favourite hangout for students and young families looking for an affordable, clean veg meal.', '1 hour', 'Evening snack and dinner hours', 'Good value-for-money veg option; it stays open until 11 PM, handy for late-evening snacks.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Budget-friendly; approx Rs. 210 price for two per published listing', 3, 4, 20.90814, 77.76329, 'Shankar Nagar Road, Vimal Nagar, Amravati 444606, Maharashtra', NULL, 0.68);

