INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000231, 841009, 'Manmohan Family Restaurant', 'Manmohan Family Restaurant', 'Long-running North Indian family restaurant on Maltekdi Road with strong local ratings. It serves Punjabi and North Indian staples at budget-friendly prices and is a dependable neighbourhood choice for family lunches and dinners.', '1-1.5 hours', 'Lunch and dinner hours', 'A good no-frills family dinner spot near the Maltekdi area; pair it with an evening drive around the locality.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Budget-friendly; approx Rs. 210 price for two per published listing', 3, 3, 20.92989, 77.76558, 'Maltekdi Road, Amravati, Maharashtra', NULL, 0.6);

