INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000232, 841009, 'Al Basheer Restaurant', 'Al Basheer Restaurant', 'Mughlai and Indian restaurant near Itwara Chowk in the old city, known for Mughlai-style non-vegetarian dishes. It fills the gap for travellers wanting rich, old-city Mughlai flavours rather than the Punjabi family-restaurant circuit.', '1 hour', 'Lunch and dinner hours', 'It is in the congested old-city Itwara area; use a two-wheeler or auto and avoid peak market hours for easier access.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 3, 3, 20.933016, 77.750576, 'Opp. Sayad Baba Dargah, Main Road, Itwara Chowk, Amravati 444601, Maharashtra', NULL, 0.6);

