INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8410033, 841, 841009, 'Ambadevi Navratri Yatra and Mela', 'September-October', 'The biggest religious fair of Amravati, held over the nine days of Navratri (Ashwin, before Dussehra) at the ancient Ambadevi Temple. The temple authorities and people celebrate with cultural and religious programs, special pujas, and a huge mela that draws visitors from all walks of life across Vidarbha. Devotees also visit the adjacent Ekvira Devi Temple during the festival.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8410034, 841, 841009, 'Kaundinyapur Yatra (Vitthal Rukmini Temple)', 'November', 'Annual pilgrimage held on Kartik Purnima to the Vitthal Rukmini Temple atop the hill at Kaundanyapur, about 45 km from Amravati, believed to be Rukmini''s maternal home. Thousands of devotees from the Vidarbha region walk in groups wearing traditional Marathi caps, chanting abhangs, with women performing the fugdi dance; the yatra runs for two days.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8410035, 841, 841009, 'Rashtra Sant Tukdoji Maharaj Yatra', 'October (approx)', 'Annual three-day yatra at the samadhi of Rashtra Sant Tukdoji Maharaj at Mozari (Tiosa) on NH-6, held around Ashwin Vadya 5. Historical fair records note attendance of around 75,000 devotees over the period, making it one of the major religious gatherings of Amravati district.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8410036, 841, 841009, 'Ner Pinglai Navratra Mahotsav', 'September-October', 'A major Navratra festival celebrated from the 1st to the 9th of Ashwin Shukla at Ner Pinglai in Morshi taluka of Amravati district, recorded in Amravati''s historical fair listings with attendance of around 50,000. It is one of the district''s prominent Devi festivals alongside the Ambadevi Navratri.');

-- city: Shirdi (id 1070)
INSERT OR IGNORE INTO cities (id, state_id, city_name, latitude, longitude) VALUES (841010, 841, 'Shirdi', 19.76523, 74.47416);

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000233, 841010, 'Shri Sai Baba Samadhi Mandir', 'Shri Sai Baba Samadhi Mandir', 'The Samadhi Mandir is the heart of Shirdi — the shrine housing Sai Baba''s mortal remains, installed in 1918 after his Mahasamadhi. Originally built as the Buti Wada (a private mansion by devotee Gopalrao Buti of Nagpur), it now holds Baba''s marble idol beside the samadhi and hosts four daily aartis. Millions of devotees visit annually, making it one of India''s most-visited pilgrimage sites.', '2–4 hours (darshan plus aartis; queues can be long)', 'October to March (pleasant weather); early mornings or weekdays for shorter queues. Thursdays are most auspicious but most crowded.', 'Book darshan and aarti passes in advance only on the trust''s official portal online.sai.org.in — the trust warns of fake websites.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'General darshan free; optional paid darshan/aarti passes booked via the trust''s official portal', 5, 5, 19.76607, 74.47672, 'Pimpalwadi Road, Sai Babuji Nagar, Shirdi 423109', 'https://sai.org.in/', 1.0);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (841000233, 841000233, '04:00-23:15', '04:00-23:15', '04:00-23:15', '04:00-23:15', '04:00-23:15', '04:00-23:15', '04:00-23:15', 'Temple opens 4:00 AM; darshan begins ~5:40 AM; four aartis: Kakad 4:30 AM, Madhyan 12:00 PM, Dhoop at sunset, Shej 10:30 PM; closes ~11:15 PM after night aarti. Hours extend during festivals.');

