INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000233, 'insert', 'bulk', 'Coords geocoded to the temple address (19.76607, 74.47672, Pimpalwadi Road, Shirdi 423109). Official site sai.org.in opened and confirmed as the Shree Saibaba Sansthan Trust''s official website (self-declared; also cited by Wikipedia). Hours from the trust''s published daily programme (via shiridisaibaba.in and travelogyindia.com).', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000234, 841010, 'Dwarkamai', 'Dwarkamai', 'Dwarkamai is the old mosque where Sai Baba lived continuously for about 60 years until his Mahasamadhi. It still holds the sacred dhuni (eternal flame) he lit, the grinding stone, wooden bed, and chariot he used — devotees collect udi (sacred ash) from the dhuni. It stands at the centre of the temple complex and is a must-visit for every pilgrim.', '30–60 minutes', 'Morning, after the Samadhi Mandir darshan; less crowded outside aarti times.', 'Don''t miss the ever-burning dhuni and the grinding stone Baba used — both are inside Dwarkamai.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Free', 5, 5, 19.7659, 74.47737, 'Shirdi Temple Road, Sai Babuji Nagar, Shirdi 423109', NULL, 1.0);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (841000234, 841000234, '04:00-21:45', '04:00-21:45', '04:00-21:45', '04:00-21:45', '04:00-21:45', '04:00-21:45', '04:00-21:45', 'Daily programme: Dhuni Pooja with rice and ghee at 11:30 AM; upper part closes at 9:45 PM (per the trust''s published daily schedule).');

