INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000234, 'insert', 'bulk', 'Coords geocoded to Dwarkamai on Shirdi Temple Road (19.7659, 74.47737). Closing time (upper part 9:45 PM) and Dhuni Pooja from the trust''s published daily programme. No separate official site; official_website set to the Sansthan site.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000235, 841010, 'Shri Chavadi', 'Chavadi', 'Chavadi is the small historic building where Sai Baba slept on alternate nights, processing there from Dwarkamai in a palanquin. It preserves Baba''s belongings, including his wooden seat and a portrait, and the Thursday night palanquin procession (9:15–10:00 PM) still re-enacts his nightly journey. It lies just east of the Samadhi Mandir.', '30 minutes', 'Thursday evening to witness the palanquin procession between Dwarkamai and Chavadi.', 'Plan a Thursday visit around 9 PM to see the decorated palanquin procession of Baba''s photo, padukas, and sataka.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Free', 5, 4, 19.76609, 74.47756, 'Shirdi Temple Road, Sai Babuji Nagar, Shirdi 423109', NULL, 0.92);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (841000235, 841000235, '04:00-21:00', '04:00-21:00', '04:00-21:00', '04:00-21:00', '04:00-21:00', '04:00-21:00', '04:00-21:00', 'Closes at 9:00 PM per the trust''s published daily programme; Thursday palanquin procession 9:15–10:00 PM.');

