INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000235, 'insert', 'bulk', 'Coords geocoded to ''Shri Chavadi'' on Shirdi Temple Road (19.76609, 74.47756, relevance 99). Closing time and Thursday procession from the trust''s published daily programme.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000236, 841010, 'Sai Gurusthan', 'Gurusthan', 'Gurusthan is the sacred spot where a young Sai Baba was first spotted at age 16, marked by the famous margosa (neem) tree described in the Shri Sai Satcharitra. Baba called it his guru''s place; a shrine with his portrait now stands here. Devotees burn incense here on Thursdays and Fridays, believing it cures ailments.', '20–30 minutes', 'Thursday or Friday mornings, when devotees traditionally light incense.', 'Look for the neem tree — the shrine sits beneath it, with Baba''s portrait.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Free', 4, 4, 19.76876, 74.47936, 'Laxminagar, Nimgaon Korhale, Shirdi 423109 (within the temple complex)', NULL, 0.8);

