INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000237, 841010, 'Lendi Garden (Lendi Baug)', 'Lendi Garden', 'Lendi Garden (Lendi Baug) is the peaceful garden where Sai Baba strolled, meditated, and tended plants every morning and evening, drawing water from its well. The Nanda Deep — a lamp Baba himself lit — still burns beside a pipal tree he planted, and a small Datta Mandir stands inside. It''s the quietest corner of the complex.', '30–45 minutes', 'Early morning or late evening for the calmest atmosphere.', 'Best for a slow, quiet walk after darshan — mornings are the most serene.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Free', 4, 4, 19.76613, 74.4758, 'Rahata Road, Sai Babuji Nagar, Shirdi 423109', NULL, 0.8);

