INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000238, 841010, 'Shri Khandoba Temple', 'Khandoba Temple, Shirdi', 'This historic Khandoba temple is where a young Sai Baba first arrived in Shirdi — priest Mhalsapati greeted him with ''Aao Sai'' (''Welcome, Sai''), which gave him the name Sai. Upasani Maharaj also stayed here with Mhalsapati for four years. It remains a significant stop on the Sai pilgrimage circuit.', '30 minutes', 'Morning, before heading to the main temple complex.', 'Ask about the ''Aao Sai'' story at the temple — this is where Baba got his name.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Free', 4, 4, 19.76369, 74.47593, 'Nagar Manmad Road, Vitthalwadi, Shirdi 423109', NULL, 0.8);

