INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000239, 841010, 'Shri Saibhakta Haji Abdulbaba''s Cottage', 'Abdul Baba''s Cottage', 'The preserved cottage of Abdul Baba, Sai Baba''s devoted follower and caretaker of the mosque lamp. It displays photographs and a Koran associated with him, offering a personal glimpse into Baba''s inner circle and the multi-faith character of his following.', '15–20 minutes', 'Daytime, combined with the temple-complex circuit.', 'A quick, quiet stop — photography and souvenir shops cluster nearby.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Free', 3, 3, 19.76606, 74.4778, 'Shirdi Temple Road, Sai Babuji Nagar, Shirdi 423109', NULL, 0.6);

