INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000240, 841010, 'Dixit Wada Museum', 'Dixit Wada Museum', 'The Dixit Wada Museum exhibits Sai Baba''s personal belongings — his robes, photographs, gramophone records, utensils, and other artifacts from his lifetime. It gives the best material context to Baba''s life beyond the temples, and is ideal for visitors wanting a deeper, unhurried understanding of the saint.', '45–60 minutes', 'Late morning or afternoon, when temple queues are longest.', 'Pair it with the Samadhi Mandir visit — the artifacts make Baba''s story feel tangible.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Free', 4, 4, 19.76612, 74.47674, 'Shirdi Temple Road, Sai Babuji Nagar, Shirdi 423109', NULL, 0.8);

