INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000241, 841010, 'Sai Teerth Devotional Theme Park', 'Sai Teerth Devotional Theme Park', 'Sai Teerth is India''s first devotional theme park, an indoor AC park by the Malpani Group (now part of Imagicaaworld). It runs immersive shows on Sai Baba''s life — the giant-screen ''Sabka Malik Ek'', the Teerth Yatra temple ride, the 5D ''Lanka Dahan'' and ''Kaliya Mardan'' experiences, a robotics Dwarkamai show, and laser shows. It blends devotion with family entertainment a few minutes from the temple.', '3–4 hours', 'Afternoon, after morning darshan; allow ~3–4 hours for all shows.', 'Photography is not allowed inside the attractions; book online for the listed rates and check show schedules on arrival.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Regular entry ticket ~₹599 (online) – ₹649 (offline) + 18% GST; children under 3''3" free (reported July 2026; prices/offers change — check the official site)', 4, 4, 19.77389, 74.47715, 'Near Sun-N-Sand Hotel, Post Nighoj, Shirdi, Taluka Rahata, Maharashtra 423109', 'http://saiteerth.in/', 0.8);

