INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000241, 'insert', 'bulk', 'Coords geocoded to Sai Teerth Spiritual Theme Park, Nimgaon Korhale, Shirdi (19.77389, 74.47715). Official site saiteerth.in opened and verified — loads, belongs to the park (address, phone, and timings all match the Shirdi park). Official hours 10:00–18:00 from the site footer.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000242, 841010, 'Sai Heritage Village', 'Sai Heritage Village', 'Opened in July 2014, Sai Heritage Village is a pilgrimage-cum-picnic theme park recreating rural Shirdi as it was in Sai Baba''s time — life-size statues and replicas of key episodes from his life, a toy train, magic and puppet shows, ropeways, and a garden. It''s a relaxed, family-oriented counterpoint to the temple circuit, about 3 km from the main temple.', '2–3 hours', 'Late afternoon (3–6 PM) for comfortable weather and the shows.', 'Carry cash — the ticket counter reportedly doesn''t accept UPI/cards.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Entry ~₹125–150 per adult; free for children under 5 (rides/shows inside charged separately)', 3, 3, 19.74804, 74.47882, 'Shirdi–Ahmednagar Highway, Krishnainagar, Sakuri, Shirdi 423107', NULL, 0.6);

