INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000243, 841010, 'Wet''n''Joy Water Park', 'Wet''n''Joy Water Park, Shirdi', 'Wet''n''Joy is a large water and amusement park (Malpani Group) beside Sai Teerth, about 3–4 km from the temple — with 30+ water slides, India''s largest wave pool, a lazy river, rain-dance zone, kids'' play areas, a food court, and live acrobat shows. It''s the main non-spiritual family outing in Shirdi.', '4–6 hours (full day)', 'November to February for the most comfortable weather; summer holidays for the full water-park season.', 'Wear proper nylon/polyester swimwear (cotton not allowed); costumes and lockers available on rent inside.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Weekdays: ₹799 adult / ₹599 child; weekends & public holidays: ₹899 adult / ₹699 child (per shirditourism.co.in; includes slides + complimentary pav-bhaji lunch; seasonal offers like ₹699 midweek online deals appear on the official site)', 4, 4, 19.7742, 74.47742, 'Near Sun-N-Sand Hotel, Post Nighoj, Shirdi, Taluka Rahata, Maharashtra 423109', 'https://www.shirdi.wetnjoy.in/', 0.8);

