INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000244, 841010, 'Shri Sai Prasadalaya', 'Shri Sai Prasadalaya', 'The Shri Sai Prasadalaya is the Sansthan-run mass dining hall serving simple, sattvic vegetarian meals to thousands of devotees daily — described by visitors as a divine communal experience. It runs one of Asia''s largest solar-powered kitchens, with free meals plus a paid ₹50 section on the first floor. A must-do part of the Shirdi pilgrimage.', '45–60 minutes', 'Off-peak hours (mid-morning or late afternoon) to avoid the lunch rush.', 'Collect your free coupon at the counter first; spoons are not provided — carry one if you need it. The paid first-floor hall needs stairs (no lift).', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Free meal (with token); paid option ₹50/adult, ₹30/child under 10', 5, 4, 19.77078, 74.47203, 'New Prasadalaya Rd, Shirdi 423109 (~1 km from the main temple)', NULL, 0.92);

