INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000245, 841010, 'Maruti Mandir', 'Maruti Mandir, Shirdi', 'The Maruti (Hanuman) Mandir within the Shirdi temple complex is a small, active shrine visited as part of the temple circuit. It reflects the multi-deity character of the complex alongside the Sai shrines.', '15–20 minutes', 'Daytime, as part of the temple-complex visit.', 'Combine with Dwarkamai and Chavadi — all three are within a short walk of each other.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Free', 3, 3, 19.76609, 74.47741, 'Shirdi Temple Road, Sai Babuji Nagar, Shirdi 423109 (within the temple complex)', NULL, 0.6);

