INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000246, 841010, 'Sai Baba''s Art Gallery', 'Sai Baba''s Art Gallery', 'Founded by local artist Hemant Wani, Sai Baba''s Art Gallery displays paintings, prints, and sculptures depicting Sai Baba''s life and teachings. It sits just outside the main complex and offers an artistic, less-crowded perspective on the saint''s story — good for photography and souvenir prints.', '20–30 minutes', 'Daytime; pair with the morning temple circuit.', 'Worth 20 minutes for art lovers; prints make good souvenirs.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Free entry reported; no published ticket price', 2, 3, 19.76427, 74.47749, 'Maulana Azad Chowk, Chatrapati Nagar, Shirdi 423109 (near the temple complex)', NULL, 0.48);

