INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000246, 'insert', 'bulk', 'Coords geocoded to Sai Baba''s Art Gallery, Maulana Azad Chowk, Shirdi (19.76427, 74.47749, relevance 87). Founded by Hemant Wani and located near the temple complex per bestbus.in. Hours from the same published page; entry fee not published.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000247, 841010, 'Upasani Maharaj Ashram (Sakori)', 'Upasani Maharaj Ashram, Sakori', 'The Sakori ashram is the samadhi place of Upasani Maharaj (1870–1941), one of Sai Baba''s foremost disciples, sent here by Baba himself. The ashram houses the samadhis of Upasani Maharaj and his successor Godavari Mata (the ''Zopadi'' building with its havan-kund), and remains a working hermitage where Vedic yajnas are performed. It is a calm half-day extension from Shirdi.', '1–2 hours', 'Morning or late afternoon; allow a half-day with the short drive from Shirdi.', 'Best visited with a private vehicle; combine with a drive on the Shirdi–Ahmednagar highway.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Free', 4, 4, 19.72514, 74.47797, 'Shirdi–Ahmednagar Road (Nagar Manmad Road), near Sakori, Rahta 423107 (~4–5 km from Shirdi)', NULL, 0.8);

