INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000247, 'insert', 'bulk', 'Coords geocoded to ''Shri Upasani Kanyakumari Mandir'' on Nagar Manmad Road, Rahtapimplas, Rahta (19.72514, 74.47797) — ~4.5 km south of Shirdi on the Shirdi–Ahmednagar highway, matching Tripadvisor''s ''4 km from Shirdi'' description. An initial in-town ''Upasani Maharaj Ashram'' geocode result was ambiguous and was not used; the Sakori one is the historically documented ashram. Hours from visitor reviews only.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000248, 841010, 'Shri Shaneshwar Devasthan (Shani Shingnapur)', 'Shri Shaneshwar Devasthan, Shani Shingnapur', 'Shani Shingnapur is the famous open-air shrine of Lord Shani (Saturn) in Nevasa taluka — the deity is a swayambhu (self-manifested) black stone under the open sky rather than inside a sanctum. The village is famed for houses traditionally built without doors or locks, and the temple is the most common day-trip extension from Shirdi.', '1.5–2 hours (plus ~3 hours round-trip drive)', 'October to March; Saturdays (Shani''s day) are the most crowded and considered most auspicious.', 'It''s a ~1.5-hour drive each way from Shirdi — plan it as a separate half-day trip, not squeezed into darshan day.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Free; no published entry fee', 4, 4, 19.38108, 74.85837, 'Shani Shingnapur, Sonai–Shani Shinganapur Road, Nevasa 414105, Ahmednagar district (~74 km by road from Shirdi)', NULL, 0.8);

