INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000249, 841010, 'Woodland Restaurant', 'Woodland Restaurant', 'Woodland Restaurant is a long-running pure-vegetarian restaurant in Shirdi, serving vegetarian delights since 1999 — popular with pilgrims and located a short walk from the temple area. Known for dishes like paneer angara, modak, and a range of dosas.', '45–60 minutes', 'Lunch or dinner; open early (6 AM) for breakfast before darshan.', 'Pure veg since 1999 — a safe bet for family meals near the temple.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 4, 4, 19.770258, 74.478436, 'Hotel Ganpati Palace Rd, Shirdi, Maharashtra', NULL, 0.8);

