INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000250, 841010, 'The Grain Anaaj Restaurant', 'The Grain Anaaj Restaurant', 'The Grain Anaaj is the in-house pure-vegetarian restaurant of Hotel Jivanta, a short distance from the temple on Rui Shiv Road. It serves multi-cuisine vegetarian food including sizzlers, and is marketed as a go-to veg dining option in the Shirdi–Rahata hotel belt.', '45–60 minutes', 'Lunch or dinner.', 'Handy if staying near Sun-N-Sand / the water park side of town.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 3, 4, 19.772236, 74.47925, 'Hotel Jivanta, Rui Shiv Road, Opposite Sun N Sand Hotel, Taluka Rahata, Shirdi, Maharashtra', 'https://www.jivantahotel.com/grain-anaaj', 0.68);

