INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000252, 841010, 'The Flavours', 'The Flavours', 'The Flavours is the pure-veg restaurant of Hotel Sai Miracle on Pimpalwadi Road, very close to the temple complex — covering Indian and South Indian vegetarian dishes for pilgrims who want to eat within walking distance of the mandir.', '45–60 minutes', 'Lunch or dinner; walking distance from the temple.', 'One of the closest sit-down veg restaurants to the temple gates.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 3, 3, 19.766229, 74.479925, 'Hotel Sai Miracle, Pimpalwadi Rd, next to Canara Bank, Shirdi, Maharashtra', NULL, 0.6);

