INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000253, 841010, 'Sai Krishna Udupi Restaurant', 'Sai Krishna Udupi Restaurant', 'Sai Krishna Udupi Restaurant is a well-known South-Indian/vegetarian eatery attached to Hotel Sai Krishna near the temple — a popular pick for dosas, thalis, and quick veg meals before or after darshan.', '30–45 minutes', 'Breakfast (opens 6 AM) or lunch.', 'Good early-breakfast stop before a morning darshan slot.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 3, 3, 19.76445, 74.47648, 'Hotel Sai Krishna, near BSL Office, Shirdi, Maharashtra', NULL, 0.6);

