INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000254, 841010, 'Shiv Bhojnalaya', 'Shiv Bhojnalaya', 'Shiv Bhojnalaya is a popular budget vegetarian eatery on Palkhi Road near the temple — the kind of simple, hearty thali-style place pilgrims rely on for affordable, filling meals.', '30–45 minutes', 'Lunch or dinner; open late (till midnight).', 'Budget-friendly option close to the temple; expect simple thali-style food.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 2, 3, 19.764812, 74.47699, 'Palkhi Rd, Shirdi, Maharashtra', NULL, 0.48);

