INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8410037, 841, 841010, 'Ram Navami', 'March–April', 'One of the three principal festivals of the Shri Saibaba Sansthan Trust, celebrating the birth of Lord Rama. Shirdi holds special processions, kirtans, and programmes across the temple complex, drawing large crowds.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8410038, 841, 841010, 'Guru Purnima (Guru Pournima)', 'July', 'The full-moon day honouring the guru (spiritual teacher), among the biggest observances at the Samadhi Mandir. Devotees gather in large numbers for special aartis and darshan; listed among the trust''s three main festivals on sai.org.in and Wikipedia''s Shirdi temple infobox.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8410039, 841, 841010, 'Shri Sai Baba Punyatithi Utsav', 'September–October (on Vijayadashami)', 'The biggest annual festival in Shirdi, marking the Mahasamadhi (passing) of Sai Baba in October 1918. The trust organises a multi-day Punyatithi Utsav with processions, cultural programmes, and special aartis; lakhs of devotees attend.');

