INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000255, 841011, 'Tiger''s Leap (Waghdari)', 'Tiger''s Leap (Waghdari)', 'Lonavala''s most famous clifftop viewpoint, also called Waghdari, named for a rock formation that looks like a tiger leaping across the valley. It offers sweeping views of the Sahyadri valleys, an echo point, and seasonal waterfalls that spill over the cliff edge in the monsoon. Lion''s Point is a separate but nearby and often-confused viewpoint on the same ridge.', '1-2 hours', 'June to September for monsoon waterfalls; sunrise and sunset year-round', 'Go early morning for mist and fewer crowds, or at sunset for the classic view. Hold onto hats and belongings — monsoon winds are strong at the edge. Chai and chikki vendors line the approach.', 'no', 'Maharashtra', 1, 1, '06:27', '18:26', 'Free entry; paid parking (visitor reports cite approx. Rs 20 for bikes, Rs 50 for cars, Rs 100 for buses)', 9, 8, 18.75426, 73.40111, 'Old Khandala Road, Tungarli, Lonavala, Maharashtra 410401', NULL, 1.72);

