INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000255, 'insert', 'bulk', 'Coordinates from geocoder FULL_ADDRESS match ''Tiger''s Leap, Old Khandala Road, Tungarli, Lonavala 410401''. Waghdari = Tiger''s Leap confirmed via tourmyindia. Sources frequently conflate Tiger''s Leap with nearby Lion''s Point and Khandala''s ''Tiger Point''; this entry covers only Tiger''s Leap (Waghdari). No published gate hours — open clifftop, hours set to null.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000256, 841011, 'Bhushi Dam', 'Bhushi Dam', 'A 19th-century masonry dam built in the 1860s for the Great Indian Peninsular Railway and now owned by Central Railway. In the monsoon, water cascades over its stepped spillway and crowds gather to wade and splash in the outflow — Lonavala''s signature rainy-season ritual. Swimming is strictly prohibited and the rocks are slippery.', '1-2 hours', 'June to September (monsoon); go on a weekday morning to avoid crowds', 'Wading is allowed but swimming is banned — the current is deceptively strong in monsoon. Wear footwear with grip; the steps get very slippery. Carry a change of clothes.', 'no', 'Maharashtra', 1, 1, '06:27', '18:26', 'Free', 8, 7, 18.7227, 73.3965, 'Bhushi Dam, INS Shivaji Road, Lonavala, Maharashtra 410401', NULL, 1.52);

