INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000256, 'insert', 'bulk', 'Coordinates from Wikipedia/mapcarta OSM (18.7227, 73.3965). Hours 7 AM-7 PM from trek.zone. Built in the 1860s for GIP Railway, owned by Central Railway, per trek.zone. No official website found; set to null.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000257, 841011, 'Karla Caves', 'Karla Caves', 'One of India''s greatest ancient Buddhist rock-cut complexes (2nd century BCE to 5th century CE), anchored by the magnificent Great Chaitya — a grand prayer hall with a teak-ribbed vaulted ceiling and a monolithic stupa. The Ekvira Devi Temple stands right beside the caves, so pilgrims and heritage travellers share the 500-step climb. Among the finest Hinayana cave architecture in the Deccan.', '2-3 hours', 'October to March; early morning to beat the crowds and the climb''s heat', 'Combine with the Ekvira Devi Temple next door — one climb covers both. Carry water; the steps are steep and exposed. Photography is allowed but tripods may need permission.', 'no', 'Maharashtra', 1, 1, '06:27', '18:26', 'Rs 25 (Indian adult), Rs 300 (foreign adult); free for children under 15', 10, 9, 18.78324, 73.47035, 'Karla, Ekveera Devi Road, Lonavala, Maharashtra 410405', NULL, 1.92);

