INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000258, 841011, 'Bhaja Caves', 'Bhaja Caves', 'A 2nd-century-BCE Hinayana Buddhist cave complex predating Karla, with 22 rock-cut caves including a chaitya hall with a distinctive horseshoe-arched vault and a group of 14 stupas. Quieter and more rugged than Karla, set in a scenic gorge off the old Mumbai-Pune highway near Malavli.', '2-3 hours', 'October to March; monsoon for the lush gorge and seasonal streams', 'Pair with Lohagad Fort nearby for a full heritage-trek day. The approach involves a short climb; wear sturdy shoes, especially in the monsoon.', 'no', 'Maharashtra', 1, 1, '06:27', '18:26', 'Rs 25 (Indian adult), Rs 300 (foreign adult)', 8, 8, 18.72778, 73.48194, 'Bhaja Caves, Malavli, Lonavala, Maharashtra 410405', NULL, 1.6);

