INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000258, 'insert', 'bulk', 'Coordinates from Wikipedia (18.72778, 73.48194), corroborated by mapcarta OSM (18.72898, 73.48133). Hours 8 AM-6 PM and ASI fees from easeindiatrip.com, 2026-09-30. ASI monument with no per-site official page; website null.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000259, 841011, 'Rajmachi Fort', 'Rajmachi Fort', 'The celebrated twin forts of Shrivardhan and Manaranjan straddling a historic Sahyadri pass, once a strategic Maratha outpost guarding the Bor Ghat trade route. Today it is Lonavala''s classic monsoon trek — a long jungle-and-plateau walk from Lonavala (about 15 km) or a shorter climb from Karjat, ending at panoramic twin summits with the Kondhane caves and Kataldhar waterfall nearby.', '4-6 hours (trek)', 'June to February; monsoon for the full waterfall-and-mist experience', 'This is a full-day trek — start early, carry 2+ litres of water and rain gear in monsoon. The Lonavala route is longer but gentler; the Karjat/Kondhane side is steeper. Local guides are easy to hire at Udhewadi village.', 'no', 'Maharashtra', 1, 1, '06:27', '18:26', 'Free', 9, 9, 18.82763, 73.39687, 'Rajmachi Fort, Maval, Pune district, Maharashtra 410405', NULL, 1.8);

