INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000260, 841011, 'Lohagad Fort', 'Lohagad Fort', 'The ''Iron Fort'' — a compact, highly defensible hill fort captured by Chhatrapati Shivaji in 1648 and later used to guard Surat''s treasury route. Its dramatic Vinchu Kata (scorpion''s tail) rampart curls down the hillside. In 2025 it joined the UNESCO World Heritage list as part of the Maratha Military Landscapes. An easy-moderate trek from Malavli village, ideal for beginners.', '3-4 hours (trek)', 'June to February; monsoon for greenery, winter for clear views', 'Combine with Bhaja Caves and Visapur Fort (its twin) in one outing. The final climb is on stone steps — fine for fit beginners. Avoid the fort in heavy rain when the bastions get slippery.', 'no', 'Maharashtra', 1, 1, '06:27', '18:26', 'Free', 9, 9, 18.70889, 73.47667, 'Lohagad Fort, Malavli, Maval, Maharashtra 410405', NULL, 1.8);

