INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000260, 'insert', 'bulk', 'Coordinates from Wikipedia (18.70889, 73.47667), corroborated by mapcarta OSM. UNESCO World Heritage inscription (Maratha Military Landscapes, 2025) and Shivaji''s 1648 capture per published guides. Free entry, dawn-to-dusk access per eindiatourism.in; no fixed gate hours published, so hours set to null. Sunrise/sunset flags editorial (open summit, classic sunrise trek).', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000261, 841011, 'Visapur Fort', 'Visapur Fort', 'Lohagad''s larger, wilder twin — a sprawling plateau fort with massive stone walls, ruined palaces, water cisterns and a giant stone arch. The British blew up its entrance gates in 1818 after the Maratha defeat, which is why Visapur feels more ruinous and adventurous than neighbouring Lohagad. A moderate trek with big panoramic payoffs.', '3-4 hours (trek)', 'June to February; monsoon for the waterfalls on the cliffs', 'Do Lohagad and Visapur together — the saddle between them is walkable. Visapur''s plateau is large and exposed; carry sun protection and plenty of water outside monsoon.', 'no', 'Maharashtra', 1, 1, '06:27', '18:26', 'Free', 7, 8, 18.72035, 73.48977, 'Visapur Fort, Maval, Pune district, Maharashtra', NULL, 1.48);

