INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000262, 841011, 'Tung Fort', 'Tung Fort', 'A steep conical hill fort (~1,075 m) rising beside the Pawna reservoir, with a tiny summit plateau (Balekilla) and sweeping views over Pawna Lake. The climb is short but sharp — one of the more challenging Sahyadri ascents near Lonavala — and the payoff is a dramatic 360-degree panorama of the lake and surrounding forts.', '3-4 hours (trek)', 'June to February; post-monsoon for the clearest lake views', 'Not for absolute beginners — the final section is steep and exposed. Start early to avoid the midday sun on the bare cone. Combine with a Pawna Lake campsite for a trek-plus-stay weekend.', 'no', 'Maharashtra', 1, 1, '06:27', '18:26', 'Free', 7, 8, 18.65982, 73.46309, 'Tung Fort, Maval, Pune district, Maharashtra', NULL, 1.48);

