INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000263, 841011, 'Korigad Fort', 'Korigad (Koraigad) Fort', 'A compact, beautifully preserved hill fort (~923 m) with nearly 2 km of intact rampart walls you can walk end-to-end, six gates and the Koraidevi temple at the summit. An easy, rewarding trek from Peth Shahapur village off the Aamby Valley road — one of the best-preserved fort wall walks in the Sahyadris.', '2-3 hours (trek)', 'June to February; monsoon for mist on the ramparts', 'The full rampart walk takes about an hour and is the highlight — do it clockwise for the best light. The base village Peth Shahapur has food stalls on weekends.', 'no', 'Maharashtra', 1, 1, '06:27', '18:26', 'Free', 7, 8, 18.62028, 73.38556, 'Korigad Fort, near Peth Shahapur, Aamby Valley Road, Maval, Maharashtra', NULL, 1.48);

