INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000263, 'insert', 'bulk', 'Coordinates from Wikipedia (18.62028, 73.38556). Elevation ~923 m, intact ~2 km perimeter wall walk and Koraidevi temple per published trek guides. Open-access fort, no published hours; hours null. Sunrise/sunset flags editorial.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000264, 841011, 'Lonavala Lake', 'Lonavala Lake', 'A monsoon-fed lake on Lonavala''s edge that fills dramatically in the rains and shrinks in summer. In the wet months its grassy banks become an easy picnic and photography stop with the Sahyadris behind; by late summer it can be nearly dry, so time your visit for the monsoon.', '1 hour', 'June to September when the lake is full; avoid peak summer when it dries up', 'Visit in the monsoon — in summer the lakebed is often dry and disappointing. A quick stop en route to Tiger''s Leap, which is nearby.', 'no', 'Maharashtra', 1, 1, '06:27', '18:26', 'Free', 6, 6, 18.74508, 73.40168, 'Lonavala Lake (TATA Lake), Jalvayu Road, Tungarli, Lonavala, Maharashtra 410401', NULL, 1.2);

