INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000265, 841011, 'Pavana Lake', 'Pavana (Pawna) Lake', 'The vast Pawna reservoir on the Pavana river, ringed by the Tung, Lohagad and Visapur forts. By day a serene photography and boating spot; by night Maharashtra''s most popular lakeside camping destination, with dozens of operators offering tents, bonfires, barbecues and stargazing on the shore.', '2-3 hours (day visit) or overnight (camping)', 'October to February for camping (clear skies, cool nights); June to September for lush monsoon scenery', 'For camping, book a reputed operator in advance on monsoon weekends — the popular sites fill up. Carry warm layers; lakeside nights get cold in winter. Keep the shoreline clean.', 'no', 'Maharashtra', 1, 1, '06:27', '18:26', 'Free for day visits; organised overnight camps typically charge per person (packages vary by operator)', 8, 8, 18.68716, 73.48314, 'Pavana Lake, Maval, Pune district, Maharashtra', NULL, 1.6);

