INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000266, 841011, 'Ryewood Park and Shivaji Udyan', 'Ryewood Park and Shivaji Udyan', 'A 25-acre green lung in the heart of Lonavala — once a botanical garden laid out under a British officer, Mr Rye, now a public park of towering old trees, manicured lawns, a children''s play area with swings, a small pond with a wooden bridge, and the historic Shri Mahadev (Shiv) Mandir. The calm counterpoint to Lonavala''s crowded viewpoints.', '1-2 hours', 'October to March; early morning for birdsong and joggers', 'A good picnic stop between cave visits — about 1 km from Lonavala station. An old Christian cemetery with centuries-old tombstones sits near the park, adding a historical footnote.', 'no', 'Maharashtra', 1, 1, '06:27', '18:26', 'Free', 6, 7, 18.74926, 73.40245, 'Municipal Council Road, near Lonavala Market, Lonavala, Maharashtra 410401', NULL, 1.28);

