INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000266, 'insert', 'bulk', 'Coordinates from geocoder FULL_ADDRESS (18.74926, 73.40245). Hours 8 AM-7 PM daily and free entry corroborated by travelsetu and triponzy (one source lists 9 AM-7 PM; 8 AM used as the majority figure). 25-acre former botanical garden of Mr Rye per lonavalakhandalatourism.in and earthtrip.in.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000267, 841011, 'Sunil''s Celebrity Wax Museum', 'Sunil''s Celebrity Wax Museum', 'Sunil''s Celebrity Wax Museum houses lifelike wax figures of Indian and international celebrities, sportspersons and political leaders in themed poses. A light, air-conditioned family stop on Lonavala''s main market road — popular with children and first-time visitors looking for an easy indoor break.', '1-2 hours', 'Year-round; a good midday or rainy-day indoor option', 'Ticket prices vary across published sources (Rs 200-300) — confirm at the counter. Combine with chikki shopping on MG Road, a short walk away.', 'no', 'Maharashtra', 1, 1, '06:27', '18:26', 'Rs 200 per adult; free for children under 5 (some sources list Rs 250 adult / Rs 150-200 child)', 6, 7, 18.75192, 73.40309, 'Lonavala Square Mall, Main Bazar Road, Lonavala, Maharashtra 410401', NULL, 1.28);

