INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000267, 'insert', 'bulk', 'Coordinates from geocoder ''Sunil''s Celebrity Wax Museum, MG Road'' (18.75192, 73.40309). Timings 9:00 AM-9:30 PM daily per TripAdvisor/lonavalakhandalatourism.in. Fee varies across sources (Rs 200-300 adult); recorded as Rs 200 with the range noted. No official website found; set to null.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000268, 841011, 'Narayani Dham Temple', 'Narayani Dham Temple', 'A striking white-marble temple complex built in 2002 and dedicated to Goddess Narayani, with a four-storeyed gopuram, shrines to Ganapati and Hanuman, fountains along the approach, a goshala, a hall for 10,000 devotees and lodging for pilgrims. One of Lonavala''s biggest religious landmarks, set in the Dhankawadi area near Tungarli.', '1-2 hours', 'October to March; mornings for the 7 AM mangala aarti', 'Timings vary slightly across sources (some list 6:30 AM-1 PM and 4-10 PM) — the 7 AM-1 PM / 3:15-9:30 PM split is the most detailed published schedule. Book prasad meals in advance. Rooms and cottages are available for overnight stays.', 'no', 'Maharashtra', 1, 1, '06:27', '18:26', 'Free (no entry fee); prasad meals available at the canteen (prior booking required for lunch/dinner prasad)', 7, 8, 18.7628, 73.41208, 'Plot No 28/199, Tungarli Road, near Kaivalyadhama, Lonavala, Maharashtra 410401', 'https://narayanidham.in/', 1.48);

