INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000268, 'insert', 'bulk', 'Coordinates from geocoder FULL_ADDRESS (18.7628, 73.41208); place-index data lists 18.763499, 73.413311, ~130 m away — within tolerance. Official site https://narayanidham.in/ fetched and confirmed loading on 2026-09-30 (Shree Narayani Seva Sansthan, Lonavala). Timings 7:00 AM-1:00 PM and 3:15-9:30 PM from lonavalakhandalatourism.in; trawell.in and holidify.com list 6:30 AM-1 PM / 4-10 PM — variation noted in tip.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000269, 841011, 'Ekvira Devi Temple', 'Ekvira Devi Temple, Karla', 'The revered Shakti shrine of Ekvira Devi — an incarnation of Renuka, mother of Parshurama — standing right beside the Karla Caves. Kuldevi of the Koli (fisherfolk) and Agri communities, reached by a climb of about 500 steps. Legend says the Pandavas built it overnight during their exile. The temple explodes into colour during Navratri and Chaitra Navratra, when thousands throng the hill with folk dances and the goddess''s palki procession.', '1-2 hours', 'Navratri (Sep-Oct) and Chaitra Navratra (Mar-Apr) for the festivals; October to March for comfortable darshan', 'The temple closes midday (12-4 PM) — plan the climb for morning or late afternoon. Maha aarti is at 5 AM and 7 PM. Dress modestly and carry water for the steps.', 'no', 'Maharashtra', 1, 1, '06:27', '18:26', 'Free (no entry fee for darshan)', 8, 8, 18.78325, 73.47013, 'Ekvira Devi Road, Karla, Maharashtra 410405', NULL, 1.6);

