INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000269, 'insert', 'bulk', 'Coordinates from geocoder FULL_ADDRESS (18.78325, 73.47013), adjacent to Karla Caves as expected. Timings 5:00 AM-12:00 PM and 4:00-9:00 PM corroborated by banbanjara, thrillophilia, airial.travel and srkvilla.in on 2026-09-30. Navratri/Chaitra Navratra fairs confirmed by templeyatri.in, hindu-blog.com and sadhana108. No official website found; set to null.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000270, 841011, 'Shooting Point', 'Shooting Point, Khandala', 'A popular cliffside viewpoint in Khandala overlooking the deep valleys and the Mumbai-Pune expressway corridor. Favoured for sunrise and sunset photography, with tea and snack stalls nearby. (Note: some travel pages wrongly conflate it with Duke''s Nose — they are separate viewpoints.)', '1 hour', 'October to March for clear valley views; monsoon for mist and waterfalls', 'Arrive before sunrise for the best light and smallest crowds. The edge is unfenced in places — keep children close.', 'no', 'Maharashtra', 1, 1, '06:27', '18:26', 'Free', 7, 7, 18.76063, 73.37399, 'Shooting Point, Khandala, Maharashtra 410301', NULL, 1.4);

