INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000270, 'insert', 'bulk', 'Coordinates from geocoder FULL_ADDRESS ''Shooting Point, Khandala 410301'' (18.76063, 73.37399). Open viewpoint with no published hours; hours null. Sunrise/sunset flags editorial (named viewpoint). One travel page''s claim that Shooting Point ''is also known as Duke''s Nose'' is incorrect — kept as separate entries.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000271, 841011, 'Duke''s Nose', 'Duke''s Nose (Nagphani)', 'A sheer cliff (about 736 m) whose profile resembles the nose of the Duke of Wellington — also called Nagphani (hood of the serpent). A favourite for valley views, rappelling and rock-climbing, with trails leading to the top for panoramic looks over Khandala and the expressway far below.', '2-3 hours (trek to the top)', 'October to March; monsoon for dramatic clouds (climbing only in dry season)', 'The cliff edge is sheer and unfenced — stay well back. For rappelling, go with a certified adventure operator, never solo.', 'no', 'Maharashtra', 1, 1, '06:27', '18:26', 'Free (organised rappelling/trek groups charge separately)', 7, 8, 18.7408, 73.3598, 'Duke''s Nose (Nagphani), near INS Shivaji, Lonavala, Maharashtra 410401', NULL, 1.48);

