INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000271, 'insert', 'bulk', 'Coordinates from mapcarta OSM (18.7408, 73.3598, elev. 736 m); an early geocode hit a wrong ''Khandala'' in Satara district and was discarded. Open cliff with no published hours; hours null. Sunrise/sunset flags editorial (named clifftop viewpoint).', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000272, 841011, 'Della Adventure Park', 'Della Adventure Park', 'India''s largest extreme adventure park, with 70+ activities: bungee jumping, India''s only 100-ft swoop swing, India''s longest 1,250-ft flying fox, ATV and dirt-bike tracks, zorbing, paintball, archery and more. Part of the Della Resorts complex, which also has 8 multi-cuisine restaurants and 325+ rooms. Some high-thrill activities are restricted to the Jumbo Pass and a few shut in the monsoon for safety.', '4-6 hours (full day possible)', 'October to March; avoid monsoon for the full activity menu', 'Book passes online in advance and arrive at opening to beat queues. Wear sports shoes and comfortable clothing; outside food and alcohol are not allowed. Check the park calendar — some activities pause in the monsoon.', 'yes', 'Maharashtra', 1, 1, '06:27', '18:26', 'Day Pass Rs 2000 + GST (adult), Rs 1500 + GST (kids 3 ft-4.6 ft / senior citizens); Jumbo Pass Rs 5500 + GST (adult, unlimited all activities); free for kids under 3 ft', 9, 9, 18.78141, 73.38818, 'Plot No. 130-1, Kunegaon, Lonavala, Maval, Maharashtra 410401', 'https://www.dellaadventure.com/', 1.8);

