INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000272, 'insert', 'bulk', 'Coordinates from geocoder FULL_ADDRESS (18.78141, 73.38818); place-index data lists 18.781401, 73.388926 — within 75 m. Official site https://www.dellaadventure.com/ fetched and confirmed loading on 2026-09-30 (Della Resorts & Adventure, India''s largest extreme adventure park, 70+ activities). Hours 11 AM-7 PM Mon-Thu and 11 AM-9 PM Fri-Sun from official place data and lonavalakhandalatourism.in. Prices from published guides; the Day Pass excludes the top-thrill activities (Swoop Swing, Flying Fox, paintball, ATV, buggy, motocross, gyro).', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000273, 841011, 'Wet N Joy Water Park', 'Wet N Joy Water Park', 'A large water-and-amusement park on the old Mumbai-Pune highway with 25+ rides and slides — the Tornado, Free Fall, Boomerango and Master Blaster speed slides, a wave pool, rain dance, lazy river and the adjoining Magic Mountain thrill rides. Lockers, changing rooms and food courts are inside; outside food is not allowed.', '5-6 hours (full day)', 'October to May (avoid monsoon, when operations can be disrupted); weekdays for shorter queues', 'Bring swimwear, towels and sunscreen; swim caps may be required for some pools. Lockers and costume hire cost extra (approx. Rs 200 + refundable deposit). Tuesday/Thursday bonanza deals and college-student discounts are advertised — check before booking.', 'yes', 'Maharashtra', 1, 1, '06:27', '18:26', 'Water park approx. Rs 1,099 (adult) / Rs 899 (child) on weekdays; Rs 1,299 / Rs 1,099 on weekends; weekend water+amusement combo approx. Rs 1,549 / Rs 1,349; free for children under ~3.3 ft. Prices vary by day and season.', 8, 8, 18.76213, 73.51355, 'Old Pune Mumbai Highway NH-4, Post-Takve, Mundhaware, Maharashtra 410405', 'https://wetnjoy.in/', 1.6);

