INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000273, 'insert', 'bulk', 'Coordinates from geocoder FULL_ADDRESS ''Wet N Joy Water Park, Mundhaware'' (18.76213, 73.51355). Official site https://wetnjoy.in/ fetched and confirmed loading on 2026-09-30 — it lists the park address (Old Pune Mumbai Highway NH-4, Post-Takve, Mundhaware, Lonavala 410405) and official hours Mon-Sun 09:00-18:00. Ticket prices vary across sources and by weekday/weekend/season; recorded as published ranges. One 2025-dated guide noted the amusement section was temporarily closed — verify current ride status before visiting.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000274, 841011, 'Kataldhar Waterfall', 'Kataldhar Waterfall', 'A spectacular ~350-foot seasonal waterfall in the Ulhas Valley near Rajmachi, plunging with a 100-foot overhang and an eye-shaped cave beneath it that is visible when the flow is moderate. Reached by a medium-hard jungle trek from Fanasrai village (about 9 km / 3 hours one way) through dense forest and stream crossings. Strictly a monsoon waterfall — it can go dry within weeks of the rains stopping.', '6-8 hours (trek round trip)', 'June to October (monsoon) — the falls exist only in the rains', 'Go with a guide or an organised batch — the forest trail is easy to lose and the area is prone to flash floods. Do not venture deep into the plunge pool. Wear sturdy trekking shoes; the descent is slippery.', 'no', 'Maharashtra', 1, 1, '06:27', '18:26', 'Free (organised trek batches charge approx. Rs 1000-1400 per person from Lonavala/Mumbai)', 7, 8, 18.81484, 73.40569, 'Kataldhar Waterfall, near Rajmachi, Maval, Maharashtra 410405', NULL, 1.48);

