INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000274, 'insert', 'bulk', 'Coordinates from geocoder FULL_ADDRESS ''Kataldhaar Waterfall'' (18.81484, 73.40569). 350-ft height with 100-ft overhang, Fanasrai base village, ~9 km / 3-hours-one-way medium-hard trek, monsoon-only flow and flash-flood risk corroborated by trekhievers, theterntravellers, logout.world and mumbaitreks on 2026-09-30. Open natural site, no published hours; hours null.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000275, 841011, 'Maganlal Chikki', 'Maganlal Chikki', 'Lonavala''s iconic chikki maker — the peanut-brittle sweet that is the hill station''s signature souvenir. Maganlal has been making chikki since 1927 and now sells dozens of varieties: classic peanut, crushed peanut, coconut, chocolate, rose and strawberry. No Lonavala trip is complete without a box (or five) for the journey home.', '30 minutes', 'Year-round; the main MG Road store is busiest on weekends', 'Taste before you buy — most stores offer samples. The classic roasted-peanut chikki travels best; chocolate varieties can melt in summer heat.', 'no', 'Maharashtra', 1, 1, '06:27', '18:26', 'Priced in-store by variety and pack size', 7, 8, 18.74982, 73.40615, 'MG Road, Lonavala, Maharashtra 410401', 'https://maganlalchikki.com/', 1.48);

