INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000276, 841011, 'Rama Krishna', 'Rama Krishna', 'A Lonavala institution since 1972 — the Ramakrishna group''s flagship vegetarian restaurant on the Mumbai-Pune road, famous for South Indian staples (crisp dosas, idli, uttapam) alongside North Indian and Chinese. The attached hotel makes it a reliable breakfast-to-dinner halt for highway travellers and sightseers alike.', '1-2 hours', 'Year-round; breakfast hours are the liveliest', 'The South Indian breakfast (mysore masala dosa, filter coffee) is the safest, most-loved order. Expect a wait at peak weekend lunch hours.', 'no', 'Maharashtra', 1, 1, '06:27', '18:26', 'Approx. Rs 800 for two', 9, 8, 18.75382, 73.404727, 'Golwada, Mumbai-Pune Road, Lonavala, Maharashtra 410401', 'https://rkhotels.net', 1.72);

