INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000276, 'insert', 'bulk', 'Coordinates 18.75382, 73.404727 from place-index data for Rama Krishna, Golwada, Mumbai-Pune Road, Lonavala 410401. Hours 7:00 AM-11:00 PM daily per TripAdvisor listing. Approx. Rs 800 for two per eazydiner. Official site https://rkhotels.net fetched and confirmed loading on 2026-09-30 — it redirects to rkhotels.com, the Hotel Rama Krishna site (est. 1972, locations in Mumbai, Lonavala and Pune).', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000277, 841011, 'Chandralok', 'Chandralok (Hotel Chandralok)', 'Lonavala''s legendary pure-veg Gujarati thali destination, running for decades next to the bus stand and post office. The unlimited-style thali — dal, kadhi, shaak, rotli, rice, farsan and sweets — is the draw, with thalis priced around Rs 400-600. A pilgrimage for vegetarian travellers on the Mumbai-Pune route.', '1-2 hours', 'Lunch (12-3 PM) for the full thali spread', 'Go for lunch, not dinner, for the widest thali selection. Pure veg and Jain options available. It fills fast on weekends — arrive before 1 PM.', 'no', 'Maharashtra', 1, 1, '06:27', '18:26', 'Approx. Rs 1,300-1,400 for two; thalis Rs 400-600', 9, 9, 18.75348, 73.40557, 'Mumbai Pune Road, near Post Office and Bus Stand, Gavliwada, Lonavala, Maharashtra 410401', NULL, 1.8);

