INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000277, 'insert', 'bulk', 'Coordinates from geocoder FULL_ADDRESS ''Hotel Chandralok Marriage Hall, S T Stand Road, Gavliwada, Lonavala 410401'' (18.75348, 73.40557) — the restaurant sits in the Chandralok complex by the ST bus stand, matching the published ''Mumbai Pune Road, near Post Office & Bus Stand'' address. Hours 11:30 AM-10:00 PM daily per magicpin; ~Rs 1300 for two per magicpin, ~Rs 1400 per justdial (verified business listing). No official website found; set to null.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000278, 841011, 'The Kinara Village Dhaba', 'The Kinara Village Dhaba', 'A landmark village-themed dhaba on the old Mumbai-Pune highway at Vaksai Naka, serving North Indian, Mughlai and tandoor favourites in a rustic setting with live ghazals, a toy shop, tandoori chai and a pure-veg section. A decades-old favourite for highway travellers who want a meal with atmosphere.', '1-2 hours', 'Evenings for the live music and lit-up village ambience', 'Try the tandoori starters and the tandoori chai. There is a heritage stay on the premises if you want to linger. Weekends get crowded — consider an early dinner.', 'no', 'Maharashtra', 1, 1, '06:27', '18:26', 'Approx. Rs 1,200 for two', 8, 8, 18.762017, 73.454596, 'Vaksai Naka, Toll Plaza, Old Mumbai-Pune Highway, Lonavala, Maharashtra 410401', 'https://www.thekinaravillage.com/', 1.6);

