INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000279, 841011, 'Sunny Da Dhaba', 'Sunny Da Dhaba', 'The legendary highway dhaba that pioneered the Mumbai-Pune dhaba culture — a no-frills, open-air institution at Mundhavara Phata, about 12-15 km before Lonavala, famous for tandoori chicken, dal tadka, butter chicken and massive naans at honest prices. Open late into the night, it is the classic truckers-and-travellers halt.', '1-2 hours', 'Late evenings; a perfect dinner halt on the Mumbai-Pune drive', 'Order the tandoori platter and dal khichdi. It stays open past midnight (till 2 AM on weekends) — ideal for late-night drives. Cash and UPI both work.', 'no', 'Maharashtra', 1, 1, '06:27', '18:26', 'Mid-range (TripAdvisor price band Rs Rs - Rs Rs Rs)', 8, 8, 18.75866, 73.51517, 'Mundhavara Phata, Old Mumbai-Pune Highway, Maval, Maharashtra 410405', NULL, 1.6);

