INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000279, 'insert', 'bulk', 'Coordinates from geocoder FULL_ADDRESS ''Sunny da Dhaba, Mawal 410405'' (18.75866, 73.51517, relevance 100) — consistent with TripAdvisor''s ''Mundhavara Phata, Before Lonavala, Old Mumbai-Pune Highway, 410405'' address and the ~12-15 km distance from Lonavala town. Hours 11:00 AM-1:00 AM (Sun-Thu) and 11:00 AM-2:00 AM (Fri-Sat) per TripAdvisor. No official website found; set to null.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000280, 841011, 'Cafe 24 - Della Resorts', 'Cafe 24 - Della Resorts', 'Della Resorts'' round-the-clock multi-cuisine coffee shop and bar — Indian, Oriental and Continental, with elaborate breakfast buffets, live counters, fast food, desserts and ''Under the Weather'' comfort food. The polished, dependable dining option inside the Della complex, praised for its breakfast spreads.', '1-2 hours', 'Breakfast for the buffet; open 24 hours for everything else', 'You don''t need to be a resort guest to dine here — it works as a reliable upscale meal stop near Della Adventure Park. Reservations help on weekends.', 'no', 'Maharashtra', 1, 1, '06:27', '18:26', 'Not published', 7, 8, 18.77923, 73.38872, 'Plot No. 129, Kunegaon, Della Resorts, Lonavala, Maharashtra 410401', 'https://www.dellaadventure.com/', 1.48);

