INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000281, 841011, 'Sheetal Daa Dhaba', 'Sheetal Daa Dhaba', 'A popular highway dhaba at Waksai on the old Mumbai-Pune road, in business for 12 years, serving North Indian, Mughlai, Chinese, Malwani and seafood with a bar, breakfast menu and rooftop seating. Known for generous portions of tandoori and mutton specialities — a solid alternative to the more famous dhabas further down the highway.', '1-2 hours', 'Lunch through late dinner; evenings for the rooftop', 'Must-orders per regulars: dal tadka and the tandoori/grill items. Rooftop seating is the best pick in good weather. Home delivery is available locally.', 'no', 'Maharashtra', 1, 1, '06:27', '18:26', 'Approx. Rs 1,500 for two', 7, 7, 18.76144, 73.45864, 'Gat No. 121-123, Old Mumbai-Pune Highway, Waksai, Lonavala, Maharashtra 410401', NULL, 1.4);

