INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8410040, 841, 841011, 'Navratri at Ekvira Devi Temple, Karla', 'Sep-Oct', 'The 9-day Ashwin Navratri (Shukla Paksha Pratipada to Navami) at the Ekvira Devi Temple beside the Karla Caves is Lonavala''s biggest religious gathering: thousands of Koli and Agri devotees climb the hill with folk dances, music and illumination, and the goddess is taken out in the Ekvira Devi Palki procession on the ninth day (Ashtami and Navami are the most important dates). In 2026 the festival ran October 11-20 with the palki on October 19/20.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8410041, 841, 841011, 'Chaitra Navratra at Ekvira Devi Temple, Karla', 'Mar-Apr', 'The spring Navratra fair at the Ekvira Devi Temple near the Karla Caves — the second peak pilgrimage season after Ashwin Navratri, when Koli folk celebrations and special pujas fill the temple complex.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8410042, 841, 841011, 'Ganesh Chaturthi, Janmashtami and Diwali at Narayani Dham', 'Aug-Nov', 'The white-marble Narayani Dham Temple in Lonavala celebrates Ganesh Chaturthi, Janmashtami and Diwali with special enthusiasm, drawing large devotional crowds to its 5-acre complex.');

