INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8410043, 841, 841012, 'Mapro Strawberry Festival', NULL, 'Yearly festival marking the start of summer, supported by the All India Strawberry Growers Association. Stalls with strawberry-based edibles, folk dance performances, orchestra, watercolour tattoos, mehndi stalls, and strawberry-picking strolls. Thousands attend each year.');

