INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000309, 841013, 'Alibaug Beach', 'Alibaug Beach', 'Alibaug''s main town beach, a long stretch of dark sand on the Arabian Sea directly facing the offshore Kolaba Fort. It is the town''s most visited beach — busy in the mornings with bathers and lined with food stalls in the evening — and the departure point for walks or boat rides to Kolaba Fort at low tide. Sunsets here, with the fort silhouetted offshore, are the classic Alibaug photo.', '1-2 hours', 'October to February; evenings for sunset', 'Time your fort visit with the low-tide window — check the tide chart locally, as the walk to Kolaba Fort is only possible at low tide.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 5, 4, 18.65345, 72.86601, 'Alibaug Beach, Varsoli Beach Road, Naik Ali, Varsoli, Alibag 402201', NULL, 0.92);

