INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000309, 'insert', 'bulk', 'Geocoded to full address on Varsoli Beach Road, Alibag (relevance 99); corroborated as the main town beach by OneFiveNine and Travel+Leisure Asia. No published official hours/fees — beach access is free and open.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000310, 841013, 'Kolaba Fort', 'Kolaba Fort', 'A 17th-century Maratha sea fort (also called Kulaba/Alibag Fort) sitting about 1–2 km offshore, built under Chhatrapati Shivaji Maharaj. Reachable on foot across the seabed at low tide or by boat/horse cart otherwise, it has 25-foot walls, two sea-facing gateways, freshwater wells inside, a Siddhivinayak temple (built 1759) and the dargah of Haji Kamaluddin Shah. It is Alibaug''s signature landmark and best viewpoint of the town beach.', '1-1.5 hours', 'October to March, at low tide (mornings usually best)', 'Carry cash — ASI ticket payments and boat/horse-cart fares are cash-only; return well before the high-tide warning sirens.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Entry: ₹25 per Indian visitor, ₹300 for foreigners (ASI); boat/horse cart ~₹100–200 per person', 5, 4, 18.63973, 72.87098, 'Alibag Beach Road, Lamaye Wadi, Bazaarpeth, Alibag 402201', NULL, 0.92);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (841000310, 841000310, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Open daylight hours, tide-dependent; plan around low tide and be back before high-tide sirens. Closures after ~6 PM reported.');

