INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000311, 841013, 'Nagaon Beach', 'Nagaon Beach', 'A popular 3 km beach about 9 km south of Alibaug town, known for its casuarina (surau) groves, calmer shallow water and water-sport options like jet skiing, parasailing and banana rides. Often cited for scuba diving and snorkelling. It has beach shacks and stays along the road, making it a convenient full-day family beach.', '2-3 hours', 'October to February', 'Bargain for water-sport prices before the ride — rates vary between operators on the beach.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 4, 4, 18.61441, 72.90296, 'Nagaon, Alibag Sub-District 402204', NULL, 0.8);

