INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000312, 841013, 'Kashid Beach', 'Kashid Beach', 'A wide, white-sand beach on the Alibaug–Murud road, widely considered the prettiest and cleanest in the area. Framed by casuarina trees with clear blue water, it is popular for swimming, surfing and beach camping, and stays busy on weekends. The drive from Alibaug passes paddy fields and coastal villages.', '2-3 hours', 'October to February; weekdays to avoid crowds', 'The shore gets deep quickly in spots — swim only in the guarded stretches and keep to the northern end for calmer water.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 5, 5, 18.44632, 72.903, 'Kashid Beach, Murud Janjira 402401', NULL, 1.0);

