INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000312, 'insert', 'bulk', 'Geocoded to full address Kashid Beach (relevance 100). Confirmed as a top Alibaug-region beach by MakeMyTrip and Medium guides. No published hours/fees.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000313, 841013, 'Kihim Beach', 'Kihim Beach', 'A quiet white-sand beach about 11–12 km north of Alibaug town, dotted with shells and backed by dense coconut and casuarina groves. Quieter than the town beach, it is a favourite for sunset walks, evening bonfires and butterfly sightings in the surrounding woods. Several resorts and homestays sit just off the beach.', '2 hours', 'October to February; sunset hours', 'Stay for sunset and ask your resort about bonfire permissions in advance — open fires are not always allowed.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 4, 4, 18.72944, 72.87213, 'Kihim, Alibag Sub-District 402208', NULL, 0.8);

