INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000314, 841013, 'Awas Beach', 'Awas Beach', 'A clean, relatively undeveloped beach north of Kihim on the Mandwa–Alibaug coastal road. With fewer visitors and basic shacks, it suits travellers looking for a quiet picnic or fishing-village atmosphere. It sits near the Awas fishing hamlet and the road to Mandwa jetty.', '1-2 hours', 'October to February', 'Carry your own water and snacks — facilities on the beach are minimal.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 3, 3, 18.76677, 72.86983, 'Awas, Alibag Sub-District 402208', NULL, 0.6);

