INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000315, 841013, 'Akshi Beach', 'Akshi Beach', 'A serene beach about 8 km south of Alibaug town, known for its silvery-white sand and calm shoreline. Less commercialised than Nagaon, it is good for relaxed swimming, long walks and village-side homestays. Often visited together with nearby Nagaon and Kashid beaches.', '1-2 hours', 'October to February', 'Combine with Nagaon Beach in one outing — they are only a few kilometres apart on the same coastal road.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 3, 4, 18.6214, 72.89622, 'Akshi, Alibag Sub-District 402204', NULL, 0.68);

