INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000316, 841013, 'Saswane Beach', 'Saswane Beach', 'A small, offbeat beach north of Alibaug town near the Sasawane fishing village, between Thal and Awas. It sees very few tourists, with fishing boats and a quiet shoreline — a good stop for travellers exploring the northern coastal road towards Mandwa.', '1 hour', 'October to February', 'There are almost no eateries here — plan meals before or after, or continue to Mandwa/Awas.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 3, 3, 18.77027, 72.86922, 'Sasawane, Alibag Sub-District 402208', NULL, 0.6);

