INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000317, 841013, 'Mandwa Beach', 'Mandwa Beach', 'The beach next to Mandwa jetty, where the Mumbai–Mandwa ferries (from Gateway of India / Bhaucha Dhakka) land. Travellers arriving by ferry pass straight through it, and it offers walks, water sports and sunset views. Its ferry link makes it the gateway beach for day-trippers from Mumbai.', '1-2 hours', 'October to February; mornings when ferries arrive', 'If coming from Mumbai, take the ferry to Mandwa jetty — the beach is right by the jetty, then continue by road to Alibaug town.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 4, 4, 18.7964, 72.89739, 'Mandwa, Alibag Sub-District 402209', NULL, 0.8);

