INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000317, 'insert', 'bulk', 'Geocoded to Mandwa village (district-level match, relevance 82); beach is at the jetty immediately west. Ferry connection from Mumbai confirmed by Travel+Leisure Asia and MakeMyTrip. No published hours/fees.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000318, 841013, 'Varsoli Beach', 'Varsoli Beach', 'A quieter beach just north of Alibaug''s main beach, about 1–2 km from town, with sparkling sand, cleaner water and coconut and casuarina vegetation. It offers postcard views of Kolaba, Khanderi and Underi forts offshore and some of the coast''s best sunsets. Popular with walkers and photographers seeking calm away from the town crowds.', '1-2 hours', 'October to February; sunset', 'Walk the length of the beach at sunset for the clearest view of Kolaba Fort offshore.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 4, 4, 18.66605, 72.87546, 'Varsoli, Alibag 402201', NULL, 0.8);

