INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000318, 'insert', 'bulk', 'Geocoded to Varsoli village (district-level match, relevance 86); beach is immediately west. Described as the quieter alternative to the main beach by OneFiveNine and T+L Asia. No published hours/fees.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000319, 841013, 'Murud-Janjira Fort', 'Murud-Janjira Fort', 'A massive unconquered island sea fort off Murud, about 55 km from Alibaug, built by the Siddis (and associated with Malik Ambar) with 22 bastions, huge cannons, a freshwater lake and the ornate main gate with its tiger-and-elephants carving. Reached only by boat from Rajapuri jetty, it is one of India''s strongest marine forts and the big day-trip from Alibaug. Nearby attractions include the Nawab''s palace, Khokari tombs and Phansad sanctuary.', '2-3 hours (plus travel from Alibaug)', 'October to March; avoid monsoon (rough seas)', 'Go early in the day — boats stop before the fort closes and transfers to small boats at the gate can be slow with crowds.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Fort entry: free / no fixed fee (some sources report ₹25); boat from Rajapuri jetty ~₹50–100 per person round trip; parking ~₹30', 5, 4, 18.32499, 72.95754, 'Janjira Fort, Murud Janjira 402401', NULL, 0.92);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (841000319, 841000319, '08:00-16:30', '08:00-16:30', '08:00-16:30', '08:00-16:30', '08:00-16:30', '08:00-16:30', '08:00-16:30', 'Boats operate approx 8:00 AM–4:30 PM depending on sea; fort closes ~5–6 PM. Verify locally before going.');

