INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000319, 'insert', 'bulk', 'Geocoded to full address Janjira Fort, Murud Janjira (relevance 100). Boat timings 8 AM–4:30 PM and ₹50–100 fare from MeghVilla Alibaug guide; free/no-fixed entry confirmed by Nayatrip/Trawell.in. No official fort website.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000320, 841013, 'Murud Beach', 'Murud Beach', 'The beach at Rajapuri village below Murud town, from whose jetty the boats to Janjira Fort depart. A pleasant evening beach with the fort visible offshore, typically visited in combination with the fort trip. Nearby are the Khokari tombs and the Nawab''s palace.', '1-2 hours', 'October to March; evenings', 'Use the beach-side eateries for a seafood lunch while waiting for your return boat from the fort.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 3, 3, 18.31054, 72.9765, 'Rajpuri, Murud Janjira 402401', NULL, 0.6);

