INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000320, 'insert', 'bulk', 'Geocoded to Rajpuri village (district-level match, relevance 82); the beach and fort jetty lie immediately west. Fort-boat departure from Rajapuri confirmed by multiple guides. No published hours/fees.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000321, 841013, 'Korlai Fort and Lighthouse', 'Korlai Fort and Lighthouse', 'A Portuguese-built sea fort (1521, originally ''El Morro'') on a headland at the mouth of Revdanda Creek, later taken by the Marathas in 1740. It keeps eleven gates with Portuguese inscriptions, a ruined 1630 church, water cisterns, cannons and a working lighthouse. Below it, Korlai village still speaks Kristi Creole Portuguese — one of the few such communities in India. The short climb (~15–45 min) gives sweeping sea views.', '2-3 hours', 'October to February; mornings or late afternoons', 'Carry water and wear grippy shoes — the approach road is narrow and the fort paths are uneven; there are few shops nearby.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Fort entry: free; lighthouse ~₹20 per person (approximate, cash)', 5, 5, 18.53773, 72.90604, 'Korlai Fort Road, Murud Janjira 402202', NULL, 1.0);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (841000321, 841000321, '09:00-17:00', '09:00-17:00', '09:00-17:00', '09:00-17:00', '09:00-17:00', '09:00-17:00', '09:00-17:00', 'Fort generally accessible daylight hours; several sources give 9 AM–5/5:30 PM. Lighthouse interior visits are limited (typically afternoon).');

