INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000322, 841013, 'Revdanda Fort', 'Revdanda Fort', 'The 16th-century Portuguese fort at the Revdanda (Chaul) creek mouth, now a compact ruin with old walls, bastions and cannons beside Revdanda Beach''s dark sand. Built by the Portuguese and later contested by the Marathas, it pairs naturally with a beach visit and the historic Chaul town nearby. A quick, peaceful stop — explorable in under an hour.', '30-45 minutes', 'October to February', 'Combine with Revdanda Beach right next door and a drive into historic Chaul village (Rameshwar temple, old churches).', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Free', 4, 4, 18.546819, 72.924721, 'Revdanda, Alibag Sub-District 402202', NULL, 0.8);

