INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000323, 841013, 'Revdanda Beach', 'Revdanda Beach', 'A long, relatively empty beach about 17 km south of Alibaug town, notable for its darker sand, calm waves and the adjoining Revdanda Fort. Known for beach camping with bonfires, sunset views and a peaceful family atmosphere, without the water-sport crowds of Nagaon.', '1-2 hours (or overnight for camping)', 'October to February; sunset', 'If beach camping, book with an established operator — bring warm layers, as the open beach gets windy after dark.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Free (camping operators charge separately)', 3, 4, 18.55531, 72.92464, 'Alibag Revadanda Road, Parnaka, Alibag Sub-District 402202', NULL, 0.68);

