INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000324, 841013, 'Kanakeshwar Temple', 'Kanakeshwar Temple', 'An ancient Shiva temple (Kanakeshwar Devasthan) atop a ~1,200-ft forested hill about 12 km from Alibaug, reached by ~700–750 stone steps (45–60 minutes). One of Raigad''s oldest and most revered Shiva temples, with smaller shrines and the Pushkarna/Bramhakund stepped tank at the top. The climb passes dense teak forest and opens to panoramic views of the coast — popular with trekkers, pilgrims and birdwatchers.', '2-3 hours (climb + darshan)', 'October to February; early morning to beat the heat', 'Start the climb early morning with good-grip shoes and carry water — steps are slippery in monsoon and there are limited washrooms.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Free', 4, 4, 18.742506, 72.918332, 'Kankeshwar Hill, near Mapgaon, Alibag Sub-District 402209', NULL, 0.8);

