INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000325, 841013, 'Sagargad Fort', 'Sagargad Fort', 'A hill fort (Sagargad) in the Sahyadri foothills east of Alibaug, reached by a popular monsoon/day trek from the base village of Sagargad near Khandale. The fort offers fort ruins, forest trails and wide views over the coast and the Arabian Sea — a good active half-day outing from Alibaug town.', '3-4 hours (trek)', 'June to February (monsoon for greenery; winter for clear views)', 'Go with a local guide if it is your first trek — the trail through forest can be confusing, especially after monsoon growth.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Free', 3, 4, 18.67228, 72.92917, 'Sagargad, Alibag Sub-District 402209', NULL, 0.68);

