INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000325, 'insert', 'bulk', 'Geocoded to Sagargad village (district-level match, relevance 69) — the trek base; the fort summit lies further up the hill. Trek popularity confirmed by India Someday. Coordinates are approximate to ~1–2 km of the summit; treat as base-village reference.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000326, 841013, 'Phansad Wildlife Sanctuary', 'Phansad Wildlife Sanctuary', 'A 52 sq km coastal forest sanctuary between Murud and Roha, known for birdwatching, giant squirrels, sambhar and barking deer, with trails to Dharnachi Gaan (wetland birds) and Chikhan Gaan (forest viewpoint). Entry is by foot or bullock cart; the forest department also offers basic tent/dormitory stays and local women''s groups cook meals on order. A quiet nature alternative to the beach circuit.', '3-4 hours (half day)', 'October to March', 'Arrive early morning for the best birding, and book the forest tent/dormitory stay in advance through the forest department.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Entry ~₹30 per adult, ~₹10 per child (parking ~₹100); bullock cart ~₹250–500; tent stay ~₹500', 4, 4, 18.40356, 72.93719, 'Phansad Wildlife Sanctuary, SH-60, Murud Janjira 402401', NULL, 0.8);

