INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000327, 841013, 'Vikram Vinayak Temple, Salav', 'Vikram Vinayak Temple, Salav', 'The Birla-built Vikram Vinayak (Ganesh) temple at Salav, on the Revdanda–Murud road — a well-known stop for pilgrims and tourists combining Murud, Korlai and Kashid in one circuit. Set in maintained grounds, it is a calm midday halt with the familiar Birla temple architecture.', '30-45 minutes', 'October to March; mornings', 'Pair it with Korlai Fort and Kashid Beach — all three sit on the same Revdanda–Murud road stretch.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Free', 3, 3, 18.52462, 72.94881, 'SH-91, Murud Janjira 402202 (Salav)', NULL, 0.6);

