INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000328, 841013, 'Thal Beach', 'Thal Beach', 'A quiet fishing-village beach about 5 km north of Alibaug town, with Khanderi and Underi sea forts visible offshore. Less visited than the main beaches, it offers an isolated shoreline for family outings and is the landing area for views of the twin sea forts. Basic and uncrowded.', '1 hour', 'October to February', 'Look offshore for the Khanderi–Underi twin forts — best viewed with binoculars on a clear day.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 3, 3, 18.68869, 72.87958, 'Thal, Alibag Sub-District 402207', NULL, 0.6);

