INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000329, 841013, 'Sanman Restaurant', 'Sanman Restaurant', 'One of Alibaug''s most famous seafood restaurants, known for Malvani-style fish thalis (surmai, pomfret, bombil fry), prawn thalis, solkadhi and Konkani preparations. Consistently busy at lunch, with AC and non-AC sections; rated among the top restaurants in Alibaug by travellers. A go-to for a first seafood meal in town.', '45-60 minutes', 'Lunch or dinner; arrive early at lunch to beat the queue', 'Expect a wait at peak lunch hours — put your name down and stroll the nearby market.', NULL, 'Maharashtra', 0, 0, NULL, NULL, '₹₹–₹₹₹; roughly ₹500 per head for a seafood meal; ~₹1000 for two', 5, 5, 18.643573, 72.875771, 'Ground Floor, Ganesh Krupa Building, Israil Lane, opp. Chirag Executive, Alibag 402201', NULL, 1.0);

