INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000330, 841013, 'Hotel Guruprasad', 'Hotel Guruprasad', 'A popular budget-friendly family restaurant on the main Alibaug–Pen road, specialising in seafood (pomfret thali, fried fish, solkadhi) alongside South Indian, Chinese, Punjabi and Malvani dishes, with an AC party hall upstairs. Known for fresh preparation, quick service and reasonable rates — a local favourite for seafood thalis.', '45 minutes', 'Lunch or dinner', 'Order the seafood thali if it is your first visit — it is the house speciality and good value.', NULL, 'Maharashtra', 0, 0, NULL, NULL, '~₹550–600 for two', 4, 4, 18.65103, 72.8807, 'In front of Reliance Petrol Pump, Alibag-Pen Road, Chendhare, Alibag 402201', NULL, 0.8);

