INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000333, 841013, 'Bohemyan Blue', 'Bohemyan Blue', 'A laid-back café-style restaurant on the Alibaug–Rewas road with exposed-brick, old-school interiors and al fresco seating. Known for farm-fresh ingredients and a mixed menu — Thai curry, fish and prawn curries, Italian, Konkani and Mediterranean dishes — plus live music on some evenings.', '1 hour', 'Lunch', 'Good stop on the Mandwa/Rewas road before or after the ferry — but call ahead, as one listing source flags the Bohemyan Blue entity as permanently closed.', NULL, 'Maharashtra', 0, 0, NULL, NULL, '~₹600–650 for two', 3, 4, 18.739449, 72.885725, 'Plot #1, Agarsure, Alibag-Rewas Main Road, between Chondhi and Zirad, Alibag Sub-District 402201', NULL, 0.68);

