INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000333, 'insert', 'bulk', 'Exact coordinates (18.739449, 72.885725) from the place listing; active per Justdial (~966 ratings) and LBB''s Alibaug restaurant guide. CAVEAT: a Meta place listing flags the Bohemyan Blue business as permanently closed — verify it is open before visiting. Hours 11 AM–7 PM from Justdial. No verified official site for the café (bohemyanbluestay.com belongs to the stay, also flagged closed) — set to null.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000334, 841013, 'Kasturi Mahila Gruh Udyog', 'Kasturi Mahila Gruh Udyog', 'An all-women-run eatery serving traditional Maharashtrian thali-style food — simple, homely and delicious, with modaks as the must-try. A favourite for authentic local vegetarian fare and Konkani snacks at very reasonable prices.', '45 minutes', 'Lunch', 'Do not skip the modaks — they are the signature item regulars recommend.', NULL, 'Maharashtra', 0, 0, NULL, NULL, '~₹600 for two', 3, 4, 18.65293, 72.8752, 'Rewas Road, Patilwadi, Chendhare, Alibag 402201', NULL, 0.68);

