INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8410045, 841, 841013, 'Ganesh Chaturthi (Konkan Ganeshotsav)', NULL, 'The 10-day Ganeshotsav is celebrated across Alibaug very traditionally — families install Ganpati idols at home and neighbourhoods set up large community idols with processions, music, fireworks and modaks through the ten days.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8410046, 841, 841013, 'Pola (Bail Pola)', NULL, 'The rural Bail Pola festival honours bullocks and oxen: farmers bathe, massage, paint and garland their bulls and worship them, with local competitions and events in Alibaug''s farming villages.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8410047, 841, 841013, 'Alibaug Beach Festival', NULL, 'An annual beachside festival with sand art competitions, boat races, traditional dance and music performances, and food stalls serving local coastal cuisine — organised by local camps and groups, also around Holi and New Year.');

-- city: Matheran (id 1074)
INSERT OR IGNORE INTO cities (id, state_id, city_name, latitude, longitude) VALUES (841014, 841, 'Matheran', 18.98226, 73.26908);

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000335, 841014, 'Panorama Point', 'Panorama Point', 'The most famous viewpoint in Matheran and its longest (the ''king of all points''), located about 6 km from the market on the eastern edge of the plateau. It is Matheran''s classic sunrise point, with views east to Neral and west across Panvel to the Khandala and Bhimashankar ranges on clear days.', '1.5-2 hours', 'Sunrise; October to March for the clearest skies', 'Leave well before dawn - the walk from the market takes 1-1.5 hours; horse rides are available but must be booked early.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 5, 5, 19.00231, 73.2843, 'Neral Matheran Road, Matheran, Maharashtra 410102', NULL, 1.0);

