INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000335, 'insert', 'bulk', 'Geocoded to Panorama Point, Neral Matheran Road (full-address match, ~2.7 km from town centre). Sunrise status, ~6 km distance from market and Khandala/Bhimashankar views corroborated by indiaouting.com and travelspl.com travel guides.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000336, 841014, 'Echo Point', 'Echo Point', 'A natural echo point near Charlotte Lake where voices thrown across the valley bounce back from the surrounding hills. Sitting between King George Point and Louisa Point on the eastern cluster, it is a favourite stop for families and a fixture of the classic Matheran sightseeing circuit.', '30-45 minutes', 'Morning to early evening; monsoon for lush surroundings', 'Shout your name toward the valley and pause for the echo; visit with Charlotte Lake and King George Point in one walk.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 4, 4, 18.98321, 73.26275, 'Matheran, Maharashtra 410102', NULL, 0.8);

