INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000337, 841014, 'Charlotte Lake', 'Charlotte Lake', 'A serene lake about 2 km from the post office and Matheran''s main drinking-water source, ringed by forest and low hills. The ancient Pisarnath (Shiv) Mandir stands to its left and Echo and Louisa Points to its right, making it the hub of the eastern viewpoint circuit and a popular picnic and birdwatching spot.', '45-60 minutes', 'Morning for calm water and birdlife; monsoon for full water levels', 'Combine with Echo Point, King George Point and Pisarnath Mandir, all within an easy walking loop.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 5, 4, 18.98098, 73.26187, 'Matheran, Maharashtra 410102', NULL, 0.92);

