INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000338, 841014, 'Louisa Point', 'Louisa Point', 'A prime western-edge viewpoint with sweeping views of the Prabal Fort, Vishalgad and Rajmachi peaks. In the monsoon and just after (September-October), waterfalls cascade from the Charlotte Lake overflow here, with the Lion''s Head rock formation visible nearby - superb for photography.', '45-60 minutes', 'Monsoon and September-October for waterfalls; late afternoon for light', 'Slippery in monsoon - wear shoes with grip; pair with nearby Honeymoon and Malang Points.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 5, 5, 18.98965, 73.25688, 'Matheran, Maharashtra 410102', NULL, 1.0);

