INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000339, 841014, 'Porcupine Point (Sunset Point)', 'Porcupine Point (Sunset Point)', 'Matheran''s signature sunset viewpoint, named for the porcupine-like silhouette of the hill. About 2 km from the railway station, it offers 360-degree valley views and an unmatched view of the Prabal Fort, with Cathedral Rock as an added attraction. The sunset here is considered one of the finest in the Sahyadris.', '1-1.5 hours', 'Evening for sunset; October to February for clear skies', 'Reach at least 45 minutes before sunset and do not walk back alone after dark - use a horse ride or stay with a group.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 5, 5, 19.002, 73.2623, 'Matheran, Maharashtra 410102', NULL, 1.0);

