INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000340, 841014, 'One Tree Hill Point', 'One Tree Hill Point', 'A viewpoint at Matheran''s southernmost tip marked by a single solitary tree on the hilltop, offering wide panoramas of the valleys and town below. It is one of the more offbeat points, often combined with Belvedere Point and the Olympia racecourse on the southern trail.', '30-45 minutes', 'Morning; October to March', 'Combine with Belvedere Point and the Olympia racecourse ground nearby; horses are the easiest way to cover this longer southern loop.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 3, 4, 18.96344, 73.26314, 'Matheran, Maharashtra 410102', NULL, 0.68);

