INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000350, 841014, 'Neral-Matheran Toy Train', 'Neral-Matheran Toy Train', 'The 21 km narrow-gauge heritage railway climbing from Neral to Matheran in about 2-2.5 hours through forested Western Ghats curves - one of India''s few remaining toy-train routes and the most nostalgic way to reach the hill station. Two train pairs run daily in season plus a shuttle between Matheran and Aman Lodge.', '2.5-3 hours (one way)', 'October to June (services suspended in monsoon, roughly June-October)', 'Tickets are mostly counter-only at Neral - arrive 30-45 minutes early; sit on the left going up for the best valley views.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'First class ₹300, Second class ₹75 (adult one-way, Neral-Matheran); Aman Lodge shuttle ₹45/₹30', 5, 5, 18.9902, 73.27072, 'Matheran Railway Station (MAE), Matheran, Maharashtra 410102', NULL, 1.0);

