INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000351, 841014, 'Belvedere Point', 'Belvedere Point', 'A southern-edge viewpoint on the trail toward One Tree Hill and the Olympia racecourse ground, offering open valley panoramas away from the main crowds. It is usually visited as part of the longer southern loop on foot or horseback.', '30 minutes', 'Morning; October to March', 'Best combined with One Tree Hill Point and the Olympia racecourse on the southern loop; a horse ride makes this long circuit easier.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 3, 3, 18.96954, 73.26598, 'Matheran, Maharashtra 410102', NULL, 0.6);

