INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000352, 841014, 'Olympia Racecourse Ground', 'Olympia Racecourse Ground', 'Matheran''s historic horse-racecourse ground near Belvedere Point, now a large open maidan used for horse rides, picnics and informal sports. In a vehicle-free hill station it is one of the few wide open spaces, and the horse-riding activity centred here is a signature Matheran experience.', '1 hour', 'Morning or late afternoon; October to March', 'Fix the horse-ride price and route before mounting; the open ground is a good spot for family picnics and morning walks.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 3, 4, 18.97008, 73.26604, 'Matheran, Maharashtra 410102', NULL, 0.68);

