INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000354, 841014, 'Shabbir Bhai Biryaniwala', 'Shabbir Bhai Biryaniwala', 'Matheran''s best-known biryani joint on Kasturba Road near Jama Masjid, serving Mughlai, Tandoori and Chinese food with chicken biryani as the signature. It has one of the strongest reputations among the market-area restaurants, with diners praising the food and prices.', '45-60 minutes', 'Lunch (12:00-14:00) or early dinner; year-round', 'Order the chicken biryani and arrive by lunch or early evening - the small hall fills up at peak meal hours.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'INR 200-400 per person', 5, 4, 18.98753, 73.27008, 'Kasturba Rd, near Jama Masjid, Matheran, Maharashtra 410102', NULL, 0.92);

