INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000359, 841014, 'Amantran Corner', 'Amantran Corner', 'A well-regarded Indian restaurant on Kotwal Road in the market area, known for chicken, prawns and fish dishes plus good coffee, with a cozy atmosphere and courteous service. Open from breakfast through late evening, it doubles as a convenient stop after Paymasters Park.', '45-60 minutes', 'Lunch or dinner; open from 08:30 year-round', 'Good non-veg option in the market area - the chicken and seafood preparations are the house strengths.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 4, 4, 18.989407, 73.270285, 'Veer Hutatma Bhai, Kotwal Road Shopping Centre, opp. Sai Heet Hotel, Matheran, Maharashtra 410102', NULL, 0.8);

