INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000360, 841015, 'Ratnadurg Fort', 'Ratnadurg Fort', 'Ratnadurg Fort (also called Ratnagiri Fort or Bhagwati Fort) is a 12th-16th century sea fort spread over ~120 acres on a horseshoe-shaped headland, surrounded by the Arabian Sea on three sides. It houses the Bhagwati Devi temple, a lighthouse, old bastions and laterite walls. It is Ratnagiri''s most scenic historic landmark, famous for panoramic sea views and sunsets.', '1.5-2 hours', 'October to March, early morning or late afternoon', 'Wear comfortable shoes for the walk along the walls and reach before sunset for the best views from the ramparts.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Free entry', 5, 4, 16.99619, 73.27085, 'Ratnadurg Fort, Ratnagiri, Maharashtra 415612', NULL, 0.92);

