INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000360, 'insert', 'bulk', 'Geocoded via map tool to FULL_ADDRESS match (16.99619, 73.27085). Hours 10:00-18:00 and free entry from travelsetu.com; tripxl lists 6 AM-6 PM free — used the more specific daily range with a caveat note. No official website found.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000361, 841015, 'Thibaw Palace', 'Thibaw Palace', 'Thibaw Palace (Thiba Palace) is a three-storey red-laterite palace built by the British in 1910 to house the exiled King Thibaw Min of Burma, who lived here under house arrest until his death in 1916. Now an ASI-maintained museum with the king''s artifacts, furniture and a Buddha idol he brought from Myanmar. The nearby Thiba Point viewpoint offers sunset views over Someshwar creek, Bhatye Bridge and the Arabian Sea.', '1-2 hours', 'October to March, around 3:30 PM so you can tour the museum and then catch sunset at Thiba Point', 'Photography is reported to be prohibited inside the palace building; enjoy the architecture and head to Thiba Point for sunset.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Nominal entry fee applicable (third-party guides cite Rs. 20 adults / Rs. 10 children — verify on arrival)', 5, 4, 16.9839, 73.3113, 'Near DM''s Residence, Ratnagiri, Maharashtra 415612', NULL, 0.92);

