INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000361, 'insert', 'bulk', 'Geocoded via map tool to FULL_ADDRESS match. Hours and entry-fee status taken from the official Ratnagiri district government page (ratnagiri.gov.in), which says 10am-5pm with entry fee applicable; fee amounts come from third-party guides and are flagged as unverified.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000362, 841015, 'Ganpatipule Beach', 'Ganpatipule Beach', 'Ganpatipule Beach is a white-sand beach on the Konkan coast about 25 km from Ratnagiri town, set against green hills and the Arabian Sea. It is one of Maharashtra''s most popular and cleanest beaches, adjacent to the Swayambhu Ganpati temple. Visitors come for swimming, water sports, evening strolls and sunsets.', '2-3 hours', 'October to March; evenings for sunset', 'Swim only in designated safe zones — the sea here can be rough; combine the visit with the Ganpati temple next door.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Free', 5, 5, 17.14539, 73.26629, 'Ganpatipule, Ratnagiri, Maharashtra 415615', NULL, 1.0);

