INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000362, 'insert', 'bulk', 'Geocoded via map tool to FULL_ADDRESS match (17.14539, 73.26629). Beach is a natural open site with no published hours or entry fee; distance of ~25 km from Ratnagiri confirmed across guides.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000363, 841015, 'Swayambhu Ganpati Temple, Ganpatipule', 'Swayambhu Ganpati Temple, Ganpatipule', 'One of Maharashtra''s most revered Ganpati shrines, the ~400-year-old Swayambhu Ganpati temple at Ganpatipule houses a self-manifested (swayambhu) idol of Lord Ganesha that faces west toward the Arabian Sea — unusual for Hindu temples. Pilgrims perform a 1 km pradakshina around the sacred hill behind the temple. It draws huge crowds during Ganesh Chaturthi and Ganesh Jayanti.', '1-2 hours', 'September to February; attend the 7 PM aarti', 'Follow the temple''s dress code (traditional/decent attire; no shorts or beachwear) and do the hill pradakshina early in the day.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'General entry free; special darshan approx Rs. 200 / Rs. 500', 5, 5, 17.14565, 73.26889, 'Ganpatipule, Ratnagiri, Maharashtra 415615', 'https://ganpatipule.co.in/', 1.0);

