INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000364, 841015, 'Jaigad Fort', 'Jaigad Fort', 'Jaigad Fort is a 17th-century sea fort at the mouth of the Shastri river creek, about 45 km from Ratnagiri town, built by the Bijapur Sultanate and later held by the Marathas. Though partly in ruins, it offers sweeping views of the Arabian Sea, the Jaigad creek and the modern Jaigad port. It is usually visited together with the nearby Jaigad Lighthouse.', '1-1.5 hours', 'October to March', 'Combine with the Jaigad Lighthouse next door; carry water as facilities are basic.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Free', 4, 4, 17.29994, 73.22145, 'Jaigad, Ratnagiri, Maharashtra 415614', NULL, 0.8);

