INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000365, 841015, 'Jaigad Lighthouse', 'Jaigad Lighthouse', 'The Jaigad Lighthouse stands on the headland next to Jaigad Fort, guiding ships into the Jaigad creek and port. The surrounding viewpoint offers panoramic views of the Arabian Sea, the creek and the distant coastline, making it a popular photography and sunset stop for visitors to Jaigad.', '30-45 minutes', 'October to March, late afternoon', 'The lighthouse tower interior is not reliably open to visitors; the value is in the headland views, so plan it with the fort.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 3, 4, 17.2998, 73.22169, 'Sakhar Mohalla, Jaigad, Ratnagiri, Maharashtra 415614', NULL, 0.68);

