INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000366, 841015, 'Shri Swami Swaroopanand Samadhi Mandir, Pawas', 'Shri Swami Swaroopanand Samadhi Mandir, Pawas', 'Pawas is a spiritual centre near Ratnagiri known for the samadhi (memorial shrine) and math of Swami Swaroopanand, a revered 20th-century saint of the Datta tradition. Set amid quiet greenery, it draws devotees for darshan, meditation and the ashram atmosphere. Nearby Purnagad Fort and Ganeshghule make Pawas a good stop on a south-Ratnagiri circuit.', '1-2 hours', 'October to March', 'Dress modestly and maintain silence in the samadhi hall; combine with Ganeshghule temple and Purnagad Fort nearby.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Free', 4, 4, 16.86665, 73.32843, 'Pawas, Ratnagiri, Maharashtra 415616', NULL, 0.8);

