INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000367, 841015, 'Mandvi Beach', 'Mandvi Beach', 'Mandvi (Mandavi) Beach is Ratnagiri city''s main beach, a black-sand stretch near the port with views of fishing boats and the old Ratnadurg bastions. Its entrance is flanked by a bastion, giving it the nickname ''gateway to Ratnagiri''. The Marine Aquarium & Museum sits right next to it.', '1-2 hours', 'October to March; evenings', 'Visit the adjacent Marine Aquarium & Museum (10 AM-5 PM) before an evening walk on the beach.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Free', 4, 3, 16.99019, 73.2848, 'Mandvi Beach, Ratnagiri, Maharashtra 415612', NULL, 0.72);

