INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000368, 841015, 'Bhatye Beach', 'Bhatye Beach', 'Bhatye Beach is a long, relatively quiet beach just south of Ratnagiri city near the Bhatye creek, with the Bhatye Bridge visible from Thiba Point. Less crowded than Mandvi, it is a local favourite for evening walks, sunsets and watching fishing activity near the creek mouth.', '1-2 hours', 'October to March; evenings for sunset', 'Pair it with Thiba Point (near Thibaw Palace) for the classic sunset view over Bhatye Bridge.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Free', 3, 4, 16.99189, 73.29425, 'Bhatye, Ratnagiri, Maharashtra 415612', NULL, 0.68);

