INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000369, 841015, 'Malgund Beach', 'Malgund Beach', 'Malgund Beach is a clean, less-crowded sandy beach on the coastal road between Ratnagiri and Ganpatipule. It is known for tranquil walks, clean water, sunset views and seasonal water sports (banana rides, parasailing, horse-cart rides) with snack and coconut-water stalls. Malgund village is also the birthplace of Marathi poet Keshavsut.', '1-2 hours', 'October to March; evenings', 'Water sports operate seasonally — confirm availability on arrival; it is a good sunset stop between Ratnagiri and Ganpatipule.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Free', 3, 4, 17.18113, 73.25477, 'Malgund, Ratnagiri, Maharashtra 415615', NULL, 0.68);

