INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000370, 841015, 'Aare Ware Beach', 'Aare Ware Beach', 'Aare Ware (Arey Ware) is a pair of twin crescent beaches separated by a rocky headland, a short drive north of Ratnagiri city. With clear water and few crowds, it is a favourite for picnics, photography and quiet swimming among locals and offbeat travellers.', '2 hours', 'October to March', 'There are limited food stalls, so carry water and snacks; check sea conditions before swimming.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Free', 3, 4, 17.0682, 73.29963, 'Aare Ware, Ratnagiri, Maharashtra 415629', NULL, 0.68);

