INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000371, 841015, 'Ganeshghule Beach', 'Ganeshghule Beach', 'Ganeshghule Beach is a quiet, scenic beach south of Ratnagiri near the village of Ganeshghule, close to the ancient Ganeshghule Ganpati temple. Fringed by forest and laterite cliffs, it is largely undeveloped and popular with travellers seeking a peaceful, natural coastline.', '1-2 hours', 'October to March', 'Combine with the Ganeshghule Ganpati temple and its famous 70-foot-deep ancient stepped well nearby.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Free', 3, 4, 16.87225, 73.3168, 'Ganeshghule, Ratnagiri, Maharashtra 415616', NULL, 0.68);

