INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000372, 841015, 'Marine Aquarium and Museum, Ratnagiri', 'Marine Aquarium and Museum, Ratnagiri', 'Established in 1985 by the Marine Biological Research Station of Ratnagiri, this museum-cum-aquarium next to Mandvi Beach displays rare marine specimens — seahorses, lionfish, sea turtles, eels, lobsters, sea snakes — plus a freshwater aquarium section and a 55-foot, 5000-kg whale skeleton. A popular educational stop, especially for families.', '45 minutes - 1 hour', 'October to March, mornings', 'Carry a digital payment option — recent visitor reports say only online payment is accepted for tickets.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Nominal: published figures vary (Rs. 5-20 adults, Rs. 3-10 children)', 4, 4, 16.9934, 73.27878, 'Ratnagiri-Bhagwati Mandir Road, near Mandvi Beach, Ratnagiri, Maharashtra 415612', NULL, 0.8);

