INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000373, 841015, 'Prachin Konkan Museum', 'Prachin Konkan Museum', 'Prachin Konkan is an open-air, life-size museum set on a 3-acre wooded campus near Ganpatipule, depicting Konkan life as it was 500 years ago. Guided tours cover traditional homes, occupations, deities, barter trade and sea-fort models, plus a Nakshatra Baug (zodiac garden) and a shell exhibition. Founded in 2004, it is one of Ganpatipule''s top-rated cultural stops.', '1-1.5 hours', 'October to March, morning', 'Free guided tours run through the campus; skip the extra photo fee and just enjoy the walk.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Adult Rs. 40, Child Rs. 40 (per official site; some guides cite Rs. 50)', 4, 5, 17.15046, 73.2757, 'Post Ganpatipule, Ganpatipule, Maharashtra 415615', 'http://prachinkonkan.com/', 0.88);

