INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000374, 841015, 'Patit Pawan Mandir', 'Patit Pawan Mandir', 'Patit Pawan Mandir is a historic temple in Ratnagiri town established by freedom fighter Vinayak Damodar Savarkar during his internment in Ratnagiri (1924-1937), notable as one of the temples he opened to all castes. It remains an active place of worship and a landmark of the social-reform movement in the Konkan.', '30-45 minutes', 'October to March, mornings or evenings', 'Dress modestly; it pairs well with a visit to the nearby Lokmanya Tilak birthplace in town.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Free', 3, 3, 16.99734, 73.29465, 'Patit Pawan Mandir, Ratnagiri, Maharashtra 415612', NULL, 0.6);

