INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000375, 841015, 'Lokmanya Tilak Birthplace', 'Lokmanya Tilak Birthplace', 'The birthplace of Bal Gangadhar Tilak (1856-1920), the freedom fighter and scholar known as Lokmanya, located in Ratnagiri town. Maintained as a memorial (Tilak Smarak), it preserves the house where he was born and is a pilgrimage site for those interested in India''s independence movement.', '30-45 minutes', 'October to March', 'Combine with Patit Pawan Mandir and Ratnadurg Fort for a freedom-history half-day in town.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Free', 3, 3, 16.99618, 73.2911, 'Lokmanya Tilak Birthplace, Ratnagiri, Maharashtra 415612', NULL, 0.6);

