INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000376, 841015, 'Ratnagiri Lighthouse', 'Ratnagiri Lighthouse', 'The Ratnagiri Lighthouse stands on the headland near Ratnadurg Fort, marking the approach to Ratnagiri''s port. The area around it offers dramatic cliff-top views of the Arabian Sea and is a popular sunset viewpoint for visitors to the fort.', '30 minutes', 'October to March, late afternoon', 'Visit together with Ratnadurg Fort; the best photos are from the cliff paths at sunset.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 3, 3, 16.98816, 73.27256, 'Ratnagiri, Maharashtra 415612', NULL, 0.6);

