INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000377, 841015, 'Mirya Beach', 'Mirya Beach', 'Mirya Beach is a quiet beach north of Ratnagiri city near the fishing village of Mirya. Relatively undeveloped, it offers a calm shoreline for walks and solitude away from the busier city beaches.', '1 hour', 'October to March', 'Facilities are minimal, so carry water; best as a short stop on the coastal road north toward Aare Ware.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Free', 2, 3, 17.02555, 73.291, 'Mirya, Ratnagiri, Maharashtra 415629', NULL, 0.48);

