INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000378, 841015, 'Purnagad Fort', 'Purnagad Fort', 'Purnagad is a small, well-preserved 18th-century sea fort (~25 km from Ratnagiri) on a rocky hill at the confluence of the Muchkundi creek and the Arabian Sea, built in 1724 under Maratha admiral Kanhoji Angre as a coastal watchtower guarding the trade route. It has seven bastions, carved dual gates (sun, moon, Ganesha), a Hanuman idol at the entrance and panoramic views of Purnagad beach, the creek and coconut groves. An uncrowded offbeat stop.', '45 minutes - 1.5 hours', 'October to March, early morning or late afternoon', 'The main entrance is not immediately visible — take the road through Purnagad village and ask locals for the fort path.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'No entry fee', 4, 4, 16.808028, 73.314917, 'Purnagad village, near Pawas, Ratnagiri district, Maharashtra', NULL, 0.8);

