INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000378, 'insert', 'bulk', 'Coordinates 16.808028, 73.314917 taken from the published Wikipedia entry (not guessed). Hours 6 AM-6 PM and no entry fee from thrillophilia''s Purnagad guide; fort history verified across Wikipedia, travelkonkan.in and durgbharari.in.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000379, 841015, 'Ganeshghule Ganpati Temple', 'Ganeshghule Ganpati Temple', 'The ~400-year-old Ganpati temple at Ganeshghule, about 22 km from Ratnagiri, is built of laterite stone in a pre-Shivaji-era style. Instead of a carved idol, a self-formed rock is worshipped as Lord Ganesha; local legend says the deity later ''moved'' to Ganpatipule. The complex includes a remarkable 70-foot-deep ancient stepped well carved into the laterite plateau, and the surroundings are quiet and forested.', '1 hour', 'October to March', 'Do not miss the ancient 70-foot stepped well near the temple — a man-made marvel carved into rock.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Free', 3, 4, 16.87225, 73.3168, 'Ganeshghule, Ratnagiri, Maharashtra 415616', NULL, 0.68);

