INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000380, 841015, 'Hotel Amantran', 'Hotel Amantran', 'Hotel Amantran is one of Ratnagiri''s best-known seafood restaurants, famous for authentic Konkani/Malvani fish thalis — Surmai thali, crab preparations, fried prawns and fish masala — plus a veg thali option. A simple, family-friendly dining hall that is consistently rated among the top places to eat in the city.', '1 hour', 'Lunch or dinner, October to May (peak mango/fish season overlap)', 'Order the Surmai (kingfish) thali; expect a wait at peak lunch/dinner hours on weekends.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Approx INR 400 - INR 1,400 per person', 5, 4, 16.99072, 73.30705, 'Juna Mal Naka, opp. Gandhi Petrol Pump, near Vihar Deluxe Hotel, Sanmitra Nagar, Ratnagiri, Maharashtra 415612', NULL, 0.92);

