INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000381, 841015, 'Masala Kitchen', 'Masala Kitchen', 'Masala Kitchen is a well-loved authentic Konkani seafood restaurant near Mandvi Beach, serving surmai, bangda, paplet, prawns, crabs, lobster and local fish varieties cooked Ratnagiri-style, plus kombdi vade and thalis. Simple seaside setting, fresh catch-driven menu and a local crowd.', '1 hour', 'Lunch or dinner', 'The menu changes with the day''s fresh catch — ask the staff what''s freshest; reach early at rush hours.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Budget-friendly; prawn curry reported around Rs. 250 per dish (2019 review)', 4, 4, 16.989661, 73.284669, 'Near Abhiruchi Snacks, Mandvi Beach, Ratnagiri, Maharashtra 415612', NULL, 0.8);

