INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000382, 841015, 'Hotel Matsyam', 'Hotel Matsyam', 'Hotel Matsyam is a popular Malvani seafood restaurant on Airport Road, known for its fish thalis (Malvani fish thali, Ratnagiri fish thali, crab/khekada thali), surmai, prawns and chicken/mutton wade thalis, with a special veg thali too. Bright, family-oriented dining with consistently high ratings.', '1 hour', 'Lunch (11 AM-3:30 PM) or dinner (7-10:45 PM)', 'It closes between lunch and dinner (3:30-7 PM) — plan around the split hours.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Approx INR 400 - INR 1,200 per person', 4, 4, 16.99459, 73.31852, 'Shop No 8 & 9, Asmant Heights, Airport Road, Ratnagiri, Maharashtra 415639', NULL, 0.8);

