INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000383, 841015, 'New Prashant Lunch Home', 'New Prashant Lunch Home', 'New Prashant Lunch Home is a long-running (16+ years) local favourite near Gandhi Colony serving seafood, Maharashtrian and Konkani lunch-home fare — fish thalis, surmai, prawns and chicken dishes at local prices. A classic no-frills ''lunch home'' experience popular with residents.', '45 minutes', 'Lunch, 11:30 AM - 3:30 PM', 'It is lunch-only (closes 3:30 PM) — go early for the freshest fish thali.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 3, 4, 16.994446, 73.291059, 'Shop No 18, Ratnadeep Corner, Near Pramod Mahajan Sankul, Ram Ali Road, Gandhi Colony, Ratnagiri, Maharashtra 415612', NULL, 0.68);

