INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000383, 'insert', 'bulk', 'Verified via Justdial listing (claimed business, 16 years in business, 1000+ ratings) at Ram Ali Road, Gandhi Colony. Hours 11:30 AM-3:30 PM daily from Justdial. Coordinates from a published business listing, approximate to ~1 km; no official website found.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000384, 841015, 'Hotel Vivek', 'Hotel Vivek', 'Hotel Vivek is a long-established (since 1982) hotel on Ratnagiri''s Main Road whose in-house restaurant is a favourite among vegetarians and families, serving North Indian, Chinese and Maharashtrian dishes. Central location opposite the government rest house, with banquet and home-delivery options.', '1 hour', 'Lunch or dinner', 'Good pick for vegetarian families wanting familiar North Indian/Chinese fare in central Ratnagiri.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 3, 3, 16.989835, 73.304929, '540 B/1, Main Road, Ratnagiri, Maharashtra 415612', 'http://www.hotelvivek.in/', 0.6);

