INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000384, 'insert', 'bulk', 'Official website http://www.hotelvivek.in/ fetched and confirmed live (hotel established 18 Oct 1982, Main Road, Ratnagiri). No published restaurant hours found, so hours are null. Restaurant''s veg-friendly reputation from makemytrip''s Ratnagiri food guide.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000385, 841015, 'Pokket Cafe', 'Pokket Cafe', 'Pokket Cafe is a popular 8+ year-old cafe near Maruti Mandir serving pizzas, burgers, pastas, sandwiches, garlic bread, mocktails and coffee in a cozy, budget-friendly setting. A go-to hangout for young travellers and families wanting a break from seafood thalis.', '1 hour', 'Afternoon or evening', 'Try their pizzas and mocktails; it gets busy in the evenings, so expect slower service at peak hours.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 3, 4, 16.990873, 73.314631, 'Shop No 11, Arihant Space Center, Near Lotalikar Hospital, Maruti Mandir, Ratnagiri, Maharashtra 415612', NULL, 0.68);

