INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8410051, 841, 841015, 'Ganesh Chaturthi at Ganpatipule', 'August-September', 'Ganesh Chaturthi is the biggest festival at the Swayambhu Ganpati Temple in Ganpatipule, drawing lakhs of devotees to Ratnagiri district. The temple holds special pujas and celebrations through the 10-day festival, and the town''s beaches and markets come alive with pilgrims.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8410052, 841, 841015, 'Maghi Ganesh Jayanti (Ganesh Jayanti) at Ganpatipule', 'January-February', 'Ganesh Jayanti (Magh Shukla Chaturthi), celebrating Lord Ganesha''s birth, is the second major festival at the Ganpatipule temple, attracting thousands of devotees for special darshan, aartis and the hill pradakshina.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8410053, 841, 841015, 'Narali Pournima', 'July-August', 'The Koli fishing community of the Konkan coast, including Ratnagiri''s Mandvi, Bhatye and Mirya beaches, celebrates Narali Pournima on the Shravana full moon by offering coconuts to the sea god Varuna. Decorated boats, Koli dances and feasts mark the end of the monsoon fishing ban and the reopening of the fishing season.');

