INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000386, 841016, 'Sindhudurg Fort', 'Sindhudurg Fort', 'The 17th-century sea fort built by Chhatrapati Shivaji Maharaj in 1664-1667 on Kurte Island, about 1 km off the Malvan coast. It spans about 48 acres with massive stone walls, 42 bastions and cannons, and uniquely houses a temple dedicated to Shivaji himself along with his hand and footprint impressions. Reached only by boat from Malvan jetty, it is the signature landmark of Malvan and a must-visit for history lovers and photographers.', '2-3 hours (10-15 min boat ride each way plus ~45 min inside the fort)', 'October to February, early morning or late afternoon', 'Go on the first boats of the day for calmer seas and fewer crowds; wear non-slip footwear as the fort''s stone pathways get slippery.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Boat ride + fort entry around Rs. 100-150 per person (tickets bought at Malvan jetty before boarding)', 5, 5, 16.04341, 73.46098, 'Kurte Island, Arabian Sea, off Malvan coast, Malvan 416606', NULL, 1.0);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (841000386, 841000386, '08:00-17:30', '08:00-17:30', '08:00-17:30', '08:00-17:30', '08:00-17:30', '08:00-17:30', '08:00-17:30', 'Boat access from Malvan jetty is tide/season dependent; services usually stop during monsoon (Jun-Sep). Timings from the fort''s social place listing.');

