INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000386, 'insert', 'bulk', 'Coordinates from the fort''s Instagram/social place listing (16.04341, 73.46098), consistent with published coordinates 16.0421, 73.4592. The geocoder''s 16.10671 was ~5 km off and rejected. Hours 8:00 AM-5:30 PM daily from the social place listing; fee ~Rs.100-150 including boat from two independent travel guides. Boats run from Malvan jetty only; no official fort website found.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000387, 841016, 'Tarkarli Beach', 'Tarkarli Beach', 'Tarkarli''s long stretch of white sand with famously clear turquoise water, about 7 km south of Malvan town. It is Maharashtra''s best-known beach for scuba diving and snorkeling, with coral reefs and marine life visible in the clear shallows, plus parasailing and jet-skiing in season. The beach also offers a clear view of Sindhudurg Fort''s southern walls across the water.', 'Half day', 'October to May; avoid monsoon when water sports shut down', 'Book scuba/snorkeling slots in the morning for the clearest water and confirm operators run on your date before coming.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 5, 5, 16.01134, 73.49189, 'Tarkarli, Malvan 416606', NULL, 1.0);

