INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000387, 'insert', 'bulk', 'Coordinates geocoded to Tarkarli Beach (16.01134, 73.49189), full-address match, consistent with its documented position ~7 km south of Malvan. Clear-water/diving reputation and fort view confirmed by multiple travel sources. No official website; no published hours or entry fee.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000388, 841016, 'Devbagh Beach', 'Devbagh Beach', 'A quiet, coconut-fringed beach about 12 km south of Malvan where the Karli River meets the Arabian Sea at the Devbagh Sangam. It is the launch point for boat rides to Tsunami Island and dolphin-watching trips, with calm backwaters ideal for kayaking. Less commercial than Tarkarli, it suits long walks, sunsets and watching fishing boats.', 'Half day', 'October to March', 'Combine it with Tsunami Island and the Karli sangam on one boat trip booked from Devbagh jetty.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 5, 4, 15.96902, 73.50117, 'Devbag Sangam Rd, Devbagh, Malvan 416606', NULL, 0.92);

