INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000388, 'insert', 'bulk', 'Coordinates from a published place listing (15.969016, 73.501171, Devbag Sangam Rd), ~12 km from Malvan town as sources describe. Geocoder fell back to town level for this query, so the listing coordinate was used. Sangam of Karli River and sea confirmed by multiple travel sources. No official website; no published hours or fee.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000389, 841016, 'Tsunami Island', 'Tsunami Island', 'A shifting sandbar in the Karli River delta near Devbagh that appears at low tide and submerges partly at high tide. It is the region''s main backwater water-sports hub: jet skiing, banana boats, kayaking, bumper rides and parasailing, with small shacks serving Malvani snacks. Despite the name it was not formed by a tsunami; the name is a local marketing story.', 'Half day', 'October to March; visit at low tide to walk the sandbar', 'Slippers are banned on the island - carry a bag for them; negotiate water-sport package rates before boarding the boat.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Boat ride from Devbagh about Rs. 500-1200 per boat (6-8 people); water sports priced per activity', 4, 4, 15.97628, 73.50739, 'Karli River backwaters near Devbagh, Malvan 416606', NULL, 0.8);

