INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000389, 'insert', 'bulk', 'Coordinates confirmed twice: reverse geocode of wikimapia''s published 15°58''25"N 73°30''16"E resolved to a named ''Tsunami Island'' POI at 15.97628, 73.50739. Only reachable by boat from Devbagh; water-sports hub status and low-tide dynamics confirmed by travel guides. No official website.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000390, 841016, 'Malvan Beach', 'Malvan Beach', 'Malvan town''s own beach, directly opposite Sindhudurg Fort, and the working base of the town''s fishing fleet. The Malvan jetty here is the sole boarding point for fort boats. It has golden sand, shallow water and is a base for beginner scuba/water-sport training in season.', '1-2 hours', 'October to May; early morning for fishing boats', 'Watch the fishing boats return in the early morning and combine the visit with the nearby fish market at Dandi.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 4, 4, 16.05926, 73.4651, 'SH-118, Malvan 416606', NULL, 0.8);

