INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000391, 841016, 'Chivla Beach', 'Chivla Beach', 'A clean, relatively quiet beach just north of Malvan town along the MSH-4 coast road. Less commercial than Tarkarli, it is popular with locals for evening walks and sunset views. Listed among Malvan taluka''s principal beaches alongside Tarkarli, Malvan and Devbagh.', '1-2 hours', 'October to May; evenings for sunset', 'Good pick for a crowd-free sunset close to town; carry your own snacks as shacks are few.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 3, 4, 16.07866, 73.46937, 'MSH-4, Malvan 416606', NULL, 0.68);

