INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000392, 841016, 'Rock Garden, Malvan', 'Rock Garden, Malvan', 'A landscaped seaside garden on the rocky shore west of Malvan town, known as the town''s sunset point. It offers panoramic views of the Arabian Sea and Sindhudurg Fort on the horizon, making it a favourite evening stop for families and photographers.', '1-2 hours', 'October to May; 30-60 min before sunset', 'Arrive by 5:30 PM in winter to get a bench spot for the sunset over the sea.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 3, 4, 16.06186, 73.45686, 'Sea shore, west of Malvan town, Malvan 416606', NULL, 0.68);

