INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000392, 'insert', 'bulk', 'Coordinates geocoded to ''Rock Garden Malvan'' (16.06186, 73.45686), full-address match at the shore west of town. Sunset-point role confirmed by travel sources. No official website; no published hours or fee.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000393, 841016, 'Padmagad Fort', 'Padmagad Fort', 'A small sea fort on an island off Dandi Beach, built under Chhatrapati Shivaji Maharaj as a shipbuilding base and support fort for Sindhudurg. Now in ruins with eroded outer walls, it holds a renovated Shiva temple and gives unobstructed views of Sindhudurg Fort across the water. A quick, serene stop for history buffs rather than a full-day outing.', '1-2 hours', 'October to May; low tide for the walkable approach', 'Pair it with Sindhudurg Fort on the same day since both leave from the Malvan jetty area.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 3, 4, 16.04739, 73.4647, 'Island off Dandi Beach, Malvan 416606', NULL, 0.68);

