INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000393, 'insert', 'bulk', 'Coordinates from the fort''s published place listing (16.047391, 73.464697), corroborated by the Padmagad Devsthan listing (16.047347, 73.464699). Geocoder substituted an unrelated Ramgad Fort, so listing coordinates were used. History as Shivaji''s shipbuilding base and ruins status confirmed by travel and archaeology sources. No official website; no published fee.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000394, 841016, 'Sarjekot Fort', 'Sarjekot Fort', 'A small land fort on a hillock at the mouth of the Kalavali creek, about 2 km north of Malvan across the Kolamb Creek. Built by Shivaji in 1668 as a support fort for Sindhudurg, it once guarded ship anchorage and shipbuilding. Quiet and off the tourist trail, it appeals to fort enthusiasts exploring the smaller Maratha outposts.', '1-2 hours', 'October to February', 'Reachable by road across Kolamb Creek; combine with a drive up the north coast toward Tondavali.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 2, 3, 16.08548, 73.46177, 'Mouth of Kalavali Creek, Malvan 416606', NULL, 0.48);

