INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000395, 841016, 'Nivti Beach', 'Nivti Beach', 'A secluded cove of white sand and turquoise water about 14 km south of Malvan, overlooked by the hilltop Nivati Fort. With almost no commercial activity, no shacks and few visitors, it is one of the Konkan coast''s most pristine beaches - ideal for solitude, photography and sunset watching. A perennial spring near the fort and dolphin sightings add to its charm.', 'Half day', 'October to May; avoid monsoon', 'Carry all food and drinking water - there are no shops or shacks; climb up to Nivati Fort for the 180-degree view of Bhogwe Beach.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 4, 5, 15.9394, 73.5189, 'Nivti Fort Road, Nivatiwadi, Sindhudurg 416522', NULL, 0.88);

