INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000395, 'insert', 'bulk', 'Coordinates from the published ''Kille Nivti beach view point'' listing (15.939394, 73.518904), consistent with the Nivati Fort''s Wikipedia coordinates (15.939, 73.5116) just inland and multiple independent beach listings around 15.94, 73.52. Geocoder fell back to Chivla, so listing coordinates were used. Open-24-hours from Justdial. No official website; no entry fee.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000396, 841016, 'Bhogwe Beach', 'Bhogwe Beach', 'A long, nearly empty beach north of Nivati Fort on the Sagari Mahamarg between Malvan and Vengurla. Known for silver sand, clear water, dolphin sightings offshore and views of the Karli River meeting the sea. One of the cleanest beaches in the Konkan, it stays practically undiscovered next to busier neighbours.', 'Half day', 'October to May', 'The final approach road is rough - drive slowly; the seabed is rocky in places so wade in carefully.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 4, 5, 15.9596, 73.522, 'Bhogwe village, Vengurla, Sindhudurg 416523', NULL, 0.88);

