INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000396, 'insert', 'bulk', 'Coordinates are the OpenStreetMap Bhogave village point (15.95963, 73.52199), also listed by housing.com as Bhogwe village (15.963618, 73.5183484); the beach runs along the shore immediately west of the village, within ~1 km. Beach''s position north of Nivti Fort and dolphin-habitat reputation confirmed by travel sources. No official website; no published hours or fee.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000397, 841016, 'Talashil-Tondavali Beach', 'Talashil-Tondavali Beach', 'A narrow, palm-lined beach about 4 km north of Malvan where the Gad River runs parallel to the sea before meeting it near Tondavali. Promoted by the local Talashil-Tondavali tourism initiative, it offers a river-on-one-side, sea-on-the-other landscape, dolphin-sighting boat safaris, scuba diving and a quiet island feel away from the crowds.', '1-2 hours', 'October to May', 'Take the boat ride from Revandi across the Gad River mouth for the best views of the river-sea confluence.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 3, 4, 16.10003, 73.45946, 'Talashil-Tondavali, Malvan 416626', NULL, 0.68);

