INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000397, 'insert', 'bulk', 'Coordinates from a published place listing (16.100033, 73.459459); reverse geocode of that point returned a named ''Talashil Tondavali Beach'' POI 484 m away, confirming the location. River-sea confluence setting described by the local tondavalitourism.in site. No official website; no published hours or fee.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000398, 841016, 'Rameshwar Temple', 'Rameshwar Temple', 'A Shiva temple in Malvan town on Chavan Bhardewadi Marg, serving as a local place of worship in the town''s eastern quarter. It is distinct from the more famous ancient Dev Rameshwar temple at Achara village further north.', '30-60 minutes', 'Year-round; mornings and evenings for aarti', 'Visit in the early morning to see the temple at its most peaceful before the town wakes up.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 3, 4, 16.05745, 73.48245, 'Chavan Bhardewadi Marg, Malvan 416606', NULL, 0.68);

