INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000399, 841016, 'Jay Ganesh Temple', 'Jay Ganesh Temple', 'Also called the Jay Suvarna Ganesh Temple, a striking modern temple in Malvan''s Medha locality built by Shri Jayantrao Salgaonkar, the renowned astrologer and creator of the Kalnirnay almanac. The sanctum holds a pure-gold idol of Lord Ganesha flanked by Riddhi and Siddhi, with eight Ganesh idols carved into the hall ceiling. A five-day Ganesh Jayanti festival is celebrated annually on the 4th day of Magh.', '30-60 minutes', 'Year-round; Makar Sankranti morning when sunrays fall directly on the idol', 'Visit on the early morning of Makar Sankranti (Jan 14/15) to see sunlight fall directly on the golden idol.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 4, 4, 16.06401, 73.48277, 'Medha (Dhuriwada), Malvan 416606', NULL, 0.8);

