INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000399, 'insert', 'bulk', 'Temple''s existence, builder (Shri Jayantrao Salgaonkar, Kalnirnay), Medha/Dhuriwada location, gold idol and Ganesh Jayanti festival confirmed by ganapatibappa.com and konkankatta.in. Coordinates geocoded to ''Ganesh Temple, Malwan 416606'' (16.06401, 73.48277) in the Medha area east of town - name is generic in the geocoder, noted as a caveat. No official website; no published hours or fee.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000400, 841016, 'Kunkeshwar Temple', 'Kunkeshwar Temple', 'A revered 12th-century Shiva temple on a cliff overlooking the Arabian Sea, about 35 km north of Malvan in Devgad taluka. Known as the ''Kashi of South Konkan'', it draws pilgrims and sightseers for both its spiritual atmosphere and its dramatic seaside setting. A classic day trip from Malvan.', '2-3 hours including the drive from Malvan', 'October to February', 'Combine it with Devgad Fort and the Devgad beach on a half-day coastal drive.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 4, 5, 16.33365, 73.39209, 'Kunkeshwar, Devgad 416612', NULL, 0.88);

