INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000401, 841016, 'Dhamapur Lake', 'Dhamapur Lake', 'A scenic freshwater lake about 12 km inland from Malvan town, surrounded by greenery and quiet village landscapes. It is a peaceful stop for birdwatching, picnics and short walks, and a pleasant contrast to Malvan''s beaches. Boating has been available here at times.', '1-2 hours', 'October to February', 'Pair it with the Jay Ganesh Temple and Malvan market on an inland half-day loop.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 3, 3, 16.04155, 73.59149, 'Dhamapur, Malvan 416604', NULL, 0.6);

