INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000402, 841016, 'Samarth Scuba Diving', 'Samarth Scuba Diving', 'One of Malvan-Tarkarli''s best-known scuba diving operators (4.9 stars, 2,000+ ratings on Justdial), operating from Dandi beach near Dandeshwar Mandir with boats running dive trips near Sindhudurg Fort. They offer beginner scuba sessions, snorkeling, dolphin-safari boat rides, jet skis and banana rides, with MTDC-trained divers, free underwater photos/video and pickup from Malvan hotels. Dive sites include King Garden Point, Sargasm Point and White Sand Point off the fort.', 'Half day', 'October to May; mornings for best visibility', 'Book a day ahead in peak season (Dec-Jan); carry swimwear and a change of clothes, and confirm weather/visibility before paying.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 5, 5, 16.04686, 73.4686, 'Dandeshwar Mandir, Dandi, Malvan 416606', 'https://scubadivingtarkarli.com', 1.0);

