INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000402, 'insert', 'bulk', 'Official website scubadivingtarkarli.com fetched and confirmed loading with Samarth Scuba Diving branding, dive-site details and contact info; note the homepage shows some injected ''tag heuer replica'' spam text, so treat it as compromised but genuine. Coordinates from the business''s published place listing (16.046855, 73.468601, Dandeshwar Mandir Dandi), matching independent reviews that the meet point is Dandi beach near Dandeshwar Mandir. Ratings and multi-activity offerings from Justdial. No published prices found, so cost is null.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000403, 841016, 'Nivati Fort', 'Nivati Fort', 'A small sea-facing fort on a 300-ft hill above Nivati village, about 10 km south of Malvan. Built by Shivaji Maharaj in 1664 right after Sindhudurg to watch over the Karli creek and Vengurla port, it later changed hands between the Sawants, Portuguese and British. Now in ruins amid dense bushes, it rewards climbers with a sweeping 180-degree view of Nivati and Bhogwe beaches and a perennial spring at its base.', '1-2 hours', 'October to February', 'Wear sturdy shoes and carry water - the path up is overgrown and there are no facilities.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 3, 4, 15.939, 73.51164, 'Nivati village, Malvan, Sindhudurg 416522', NULL, 0.68);

