INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000404, 841016, 'Malvan Fish Market', 'Malvan Fish Market', 'The working fish market at Dandi beach where Malvan''s fishing fleet lands and auctions its daily catch. A lively slice of local life - trawlers unloading, auctioneers calling, and stalls piled with surmai, pomfret, prawns and bombil. A great early-morning stop for photographers and food lovers before heading to the fort jetty.', '1 hour', 'Year-round; early morning (6-9 AM) for the auctions', 'Go before 8 AM to see the boats land and the auctions in full swing; bargain politely if buying.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 3, 4, 16.05435, 73.46691, 'Dandi Beach, Malvan 416606', NULL, 0.68);

