INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000405, 841016, 'Atithi Bamboo', 'Atithi Bamboo', 'One of Malvan''s most loved seafood restaurants (4.5 stars, thousands of ratings), set in a no-frills building off Kacheri Road near the Maghi Ganesh Mandir. Famous for fresh surmai, pomfret, prawns, crab thalis and Malvani-style fried fish at honest prices, with a chalkboard menu and family-run warmth. Expect simple seating and big portions.', '1-1.5 hours', 'Lunch and dinner, October to May', 'Go for lunch to beat the dinner rush; the crab and surmai thalis are the signature orders.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'About Rs. 500 for two (Justdial)', 5, 5, 16.06009, 73.46327, 'Kacheri Road, Malvan 416606', NULL, 1.0);

