INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000406, 841016, 'Chaitanya Authentic Malvani Restaurant', 'Chaitanya Authentic Malvani Restaurant', 'A Malvan institution for authentic Malvani food (4.9 stars, ~2,900 votes on review aggregators), crowded daily for its fish thalis - surmai, pomfret, bangda, prawns and the hard-to-find mushi (shark) preparation - plus chicken thali and unlimited sol kadhi. Small, always-busy tables in the main market; the wait is part of the experience.', '1-1.5 hours', 'Lunch and dinner; arrive early to avoid waiting', 'Expect a wait at peak lunch/dinner - the fish thali with unlimited sol kadhi is the order.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 5, 5, 16.05654, 73.47026, 'Malvan Bazar Peth Road, Malvan 416606', NULL, 1.0);

