INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000407, 841016, 'Hotel Shirgaonkar', 'Hotel Shirgaonkar', 'A long-running family restaurant on Malvan''s main road (3.8 stars, ~1,700 Justdial ratings) serving Malvani seafood and homestyle non-veg alongside vegetarian options. A dependable, mid-priced dinner pick in town with a verified business listing.', '1-1.5 hours', 'Lunch and dinner', 'Handy for an early start - it opens at 7:30 AM, earlier than most seafood places.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'About Rs. 750 for two (Justdial)', 4, 4, 16.05598, 73.4644, 'Malvan Main Road, Somwar Peth, Malvan 416606', NULL, 0.8);

