INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000408, 841016, 'Tamhankars Fresh Fish Restaurant', 'Tamhankars Fresh Fish Restaurant', 'A well-rated fresh-fish restaurant on the Tarkarli road (4.1 stars, ~1,500 Justdial ratings), popular with beachgoers for fried and curried local catch near Tarkarli Beach. A convenient lunch stop between beach and water-sport sessions.', '1-1.5 hours', 'Lunch; October to May', 'Order the catch of the day fried Malvani-style; it is busiest on weekend afternoons.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 4, 4, 16.01223, 73.49398, 'Tarkarli Road, Tarkarli, Malvan 416606', NULL, 0.8);

