INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000410, 841016, 'Swami Family Restaurant', 'Swami Family Restaurant', 'A popular Indian and seafood restaurant on Malvan Exit Road, rated among the town''s vegetarian-friendly dining options on TripAdvisor. Serves Malvani and Indian fare for travellers passing through the town''s eastern exit toward Kudal.', '1-1.5 hours', 'Lunch and dinner', 'Useful stop on the way in or out of town along the Malvan Exit Road.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 4, 4, 16.05832, 73.46696, 'Malvan Exit Road, Malvan 416606', NULL, 0.8);

