INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8410054, 841, 841016, 'Narali Purnima', NULL, 'The coconut festival celebrated on the full-moon day of the Hindu month of Shravana (July-August) by Maharashtra''s Koli fishing communities, including Malvan''s fisherfolk. Coconuts are offered to the sea god Varuna with decorated boats, music and dance, marking the end of the monsoon and the safe reopening of the fishing season. Raksha Bandhan falls on the same day.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8410055, 841, 841016, 'Dashavataar', NULL, 'An 800-year-old folk-theatre art form popular in Sindhudurg and North Goa, especially in and around Malvan, depicting the ten incarnations of Lord Vishnu. Performed by local farmer-artists through the night, mainly during the village ''Saptah'' (the grand annual worship of the village deity), when villagers also sell homemade khaja, kadak ladoo and pickles. The main parvani (event) of Malvan''s villages.');

-- city: Bhandardara (id 1077)
INSERT OR IGNORE INTO cities (id, state_id, city_name, latitude, longitude) VALUES (841017, 841, 'Bhandardara', 19.52917, 73.75139);

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000411, 841017, 'Arthur Lake', 'Arthur Lake', 'Arthur Lake, also called Lake Arthur Hill or Bhandardara Lake, is the reservoir created by Wilson Dam on the Pravara River, named after a British administrator. The long, placid lake is ringed by thick Sahyadri forests and is the scenic heart of Bhandardara, with boating, lakeside camping, birdwatching and the lake-ferry route to Ratanwadi. It holds religious significance as the place where Sage Agastya is said to have meditated.', '2-3 hours (boating + lakeside walk)', 'October to March; monsoon (July-September) for the most dramatic scenery', 'Go for the late-afternoon boat ride (around 4 PM) when the light is best; carry a life jacket and keep phones in a waterproof pouch.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Rs. 200 per person for 1 hour boating', 5, 4, 19.538, 73.749, 'Near Wilson Dam, Bhandardara, Taluka Akole, Ahmednagar, Maharashtra 422604', NULL, 0.92);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (841000411, 841000411, '08:00-19:00', '08:00-19:00', '08:00-19:00', '08:00-19:00', '08:00-19:00', '08:00-19:00', '08:00-19:00', 'Boating timings only (per trawell.in); the lake shore itself has no gate hours.');

