INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000411, 'insert', 'bulk', 'Name, Pravara River source, Wilson Dam relationship and boating timings/fee verified via trawell.in and thelandofwanderlust.com. No published exact lake-center coordinates exist; used a representative reservoir point near the verified dam, cross-checked against lakeside campsites (e.g. Natventures Bhandardara Camping at 19.5406, 73.74838) returned by reverse geocoding.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000412, 841017, 'Wilson Dam', 'Wilson Dam', 'Wilson Dam, also called Bhandardara Dam, is a masonry gravity dam on the Pravara River built by the British between 1910 and 1926, named after Bombay governor Lt. Col. Leslie Orme Wilson. One of India''s oldest dams and among the largest earthen/masonry dams in the country, it creates Arthur Lake. The lush garden at its base and the monsoon overflow cascades make it Bhandardara''s signature man-made landmark.', '1-2 hours', 'July to September (monsoon) for the overflow cascades; October to March for general sightseeing', 'Visit in peak monsoon when the spillway gates are open — that is when the Umbrella Falls form below the dam.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 5, 4, 19.5478, 73.7572, 'Near Maharashtra State Highway 44, Bhandardara, Ahmednagar, Maharashtra 422604', NULL, 0.92);

