INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000412, 'insert', 'bulk', 'Coordinates verified via two published sources (akole.in: 19.5477186, 73.757379; mapsofindia.com: 19.547805, 73.757127) — they agree to within meters. Construction dates 1910-1926 and namesake confirmed across sources.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000413, 841017, 'Umbrella Falls', 'Umbrella Falls', 'Umbrella Falls is a seasonal waterfall that forms when monsoon waters released from Wilson Dam cascade over rocky crags below the dam wall, fanning out like a giant umbrella. Visible from the garden and picnic area at the foot of the dam, it is one of Bhandardara''s most photographed sights — and it exists only while the dam is overflowing.', '1-2 hours', 'July to September (monsoon only)', 'Combine with the Wilson Dam visit in monsoon; the foot of the dam is slippery — wear grip shoes and don''t climb the rocks.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 5, 5, 19.54782, 73.75732, 'Below Wilson Dam, Bhandardara, Ahmednagar, Maharashtra 422604', NULL, 1.0);

