INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000413, 'insert', 'bulk', 'Monsoon-only formation below Wilson Dam and umbrella-shape description confirmed across multiple travel guides (akole.in, outlooktraveller.com, zeezest.com). Coordinates from map geocoder place it at the dam''s downstream face.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000414, 841017, 'Randha Falls', 'Randha Falls', 'Randha Falls is where the Pravara River plunges about 170 feet into a deep gorge, roughly 9-10 km downriver from Bhandardara. A lookout point above the falls offers the main view, and a steep footpath leads down toward the pools at the base. Frequently cited as Maharashtra''s third-largest waterfall, it is at its roaring best in the monsoon.', '2 hours', 'July to September (monsoon); October to February for a calmer visit', 'Stick to the railed lookout and bridges — currents in the plunge pools below are dangerously strong.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 5, 5, 19.53323, 73.79673, 'Rajur-Bhandardara Road (SH-44), near Randha village, Taluka Akole, Ahmednagar, Maharashtra 422604', NULL, 1.0);

