INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000415, 841017, 'Ratangad Fort', 'Ratangad Fort', 'Ratangad, the ''Jewel of the Sahyadris'', is a roughly 400-year-old hill fort at 1,297 m overlooking Bhandardara. Its natural rock peak has a cavity called Nedhe (''Eye of the Needle''), and the fort has four gates — Ganesh, Hanuman, Konkan and Trimbak — reached by a forest trek from Ratanwadi village that crosses iron ladders and rock patches.', 'Full day (trek 5-6 hours round trip)', 'July to February (monsoon to winter)', 'Start from Ratanwadi early morning; carry 2+ litres of water and a rain cover in monsoon — the ladder sections get slippery.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 5, 5, 19.5004, 73.7026, 'Ratanwadi, Taluka Akole, Ahmednagar, Maharashtra 422604', NULL, 1.0);

