INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000416, 841017, 'Kalsubai Peak', 'Kalsubai Peak', 'Kalsubai, at 1,646 m, is the highest peak in Maharashtra — the ''Everest of Maharashtra''. The popular trek starts at Bari village and climbs through grasslands and rocky stretches with iron ladders on the final rock face, ending at a small temple dedicated to the local goddess Kalsubai. Trekkers do it as a day climb, a monsoon cloud-walk, or a night trek for sunrise.', 'Full day (ascent 3-4 hours, descent 2-3 hours)', 'September to February (post-monsoon and winter for clear views)', 'Go on a weekday or start the night trek to beat the weekend crowds; wear shoes with good grip — the ladder and rock sections are exposed.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 5, 5, 19.60148, 73.70902, 'Via Bari village, Taluka Akole, Ahmednagar, Maharashtra 422604', NULL, 1.0);

