INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000417, 841017, 'Amruteshwar Temple', 'Amruteshwar Temple', 'Amruteshwar Temple at Ratanwadi is a 9th-century Shiva temple built by the Shilahara dynasty in the Hemadpanthi style, maintained by the Archaeological Survey of India. Its black-basalt stone carvings, 12-pillared mandapa and half-submerged Shiva linga draw pilgrims and history lovers; it sits on the Pravara''s banks at the base of Ratangad Fort, reachable by road through the forest or by boat across Arthur Lake.', '1-2 hours', 'October to March; Mahashivratri for the festival atmosphere', 'The road through the forest sanctuary is rough — take an SUV or the MTDC/local boat from Shinde across the lake instead.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 5, 4, 19.5177359, 73.7229797, 'Ratanwadi village, Taluka Akole, Ahmednagar, Maharashtra 422604', NULL, 0.92);

