INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000418, 841017, 'Harishchandragad Fort', 'Harishchandragad Fort', 'Harishchandragad is a major hill fort with an ancient hilltop plateau holding the Kedareshwar Cave (a Shiva temple in a rock-cut cave around a linga), the 11th-century Harishchandreshwar Temple, the dramatic overhanging Kokankada cliff, and Taramati Peak — the region''s second-highest point. Multiple trek routes (via Pachnai, Khirewadi or Nalichi Vaat) make it a classic Sahyadri expedition from the Bhandardara area.', '2 days (overnight at the plateau caves or Taramati)', 'September to February', 'This is a serious two-day trek for experienced hikers — go with a local guide and start the ascent early morning.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 4, 5, 19.39152, 73.77955, 'Near Pachnai/Khirewadi, Taluka Akole, Ahmednagar, Maharashtra 422604', NULL, 0.88);

