INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000419, 841017, 'Sandhan Valley', 'Sandhan Valley', 'Sandhan Valley, the ''Valley of Shadows'', is a deep, narrow natural gorge carved between rock walls near Samrad village. Trekkers descend into the slot canyon — scrambling over boulders and wading through pools — and the full traverse continues to Dehene village, usually done as a two-day trek with a night rappel/descent. It is one of the Sahyadris'' most famous canyon treks.', '2 days (full traverse) or a day hike into the gorge', 'November to February (avoid monsoon — flash-flood risk)', 'Never attempt in or just after heavy rain — the gorge floods fast; carry a headlamp as sections stay dark even at midday.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 5, 5, 19.51719, 73.68552, 'Samrad village, Taluka Akole, Ahmednagar, Maharashtra 422604', NULL, 1.0);

