INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000420, 841017, 'Agastya Rishi Ashram', 'Agastya Rishi Ashram', 'Agastya Rishi Ashram in Akole taluka is an ancient religious site on the Pravara River associated with Sage Agastya, who is said to have meditated here for a year; the Ramayana tradition holds that Rama visited him here. The complex includes a Ram Kund, a Lord Ram temple and an Agastya Rishi temple, and hosts Ram Navmi, MahaShivratri and a quarterly Akhand Harinam Saptah. It lies about 35-40 km from Bhandardara village, on the route toward Akole.', '2-3 hours', 'October to March; during Ram Navmi or MahaShivratri for festivals', 'The approach road is poor quality — allow extra travel time and consider combining it with the drive in from Akole.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 3, 3, 19.5381, 73.9929, 'Banks of the Pravara River, Akole, Ahmednagar, Maharashtra 422601', NULL, 0.6);

