INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000420, 'insert', 'bulk', 'Ashram''s Akole location, Pravara riverbank setting, Ramayana association, Ram Kund and festival calendar verified via indiantravelplanner.com and multiple TripAdvisor reviews. Coordinates from a meta.ai place listing (19.538112, 73.99285) — ~35-40 km from Bhandardara village, so treated as a day-trip excursion, not a village attraction. One aggregator listing flagged it ''permanently closed''; treat as unverified and confirm locally.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000421, 841017, 'Ghatghar Viewpoint', 'Ghatghar Viewpoint', 'Ghatghar is a village on the scenic ghat road to Bhandardara whose roadside viewpoints look out over the Sahyadri ridgelines toward Kokankada and the Harishchandragad massif. It is a popular sunrise/sunset and photography stop for travellers driving in from Igatpuri, especially in the monsoon when the hills are wrapped in mist.', '30-60 minutes', 'July to February (monsoon for mist, winter for clear sunrises)', 'Stop on the way into Bhandardara in the morning for the clearest views of Kokankada before the clouds roll in.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 3, 4, 19.54009, 73.80087, 'Ghatghar village, Ghatghar-Bhandardara ghat road, Taluka Akole, Ahmednagar, Maharashtra 422604', NULL, 0.68);

