INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000422, 841017, 'MTDC Lakeview Restaurant', 'MTDC Lakeview Restaurant', 'The on-property restaurant of the MTDC Holiday Resort Bhandardara at Shendi, overlooking Arthur Lake — the best-known sit-down meal option in the village. Tour sources note its Maharashtrian fare, including crab curry and fresh lake fish. It is the default dinner spot for resort guests and day visitors alike.', '1-1.5 hours', 'Year-round', 'Try the crab curry and lake fish if available — they are the dishes the restaurant is known for.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'INR 200-400 per person', 4, 3, 19.55224, 73.755576, 'HQ24+P8X, Shendi, Bhandardhara, Ahmednagar, Maharashtra 422604', NULL, 0.72);

