INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000427, 841017, 'Shubham Bhojnalay', 'Shubham Bhojnalay', 'A simple diner-style bhojnalay near the Pravara boating point, serving home-style meals to lake visitors — the kind of no-frills village eatery Bhandardara''s food scene mostly consists of.', '45 minutes', 'Year-round', 'Pairs well with a morning at the boating point — eat here before or after the lake ride.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 2, 3, 19.550829, 73.756411, 'Near Pravara Boating Club, Bhandardara, Taluka Akole, Ahmednagar, Maharashtra 422604', NULL, 0.48);

