INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8410056, 841, 841017, 'Fireflies Festival (Kajwa Mahotsav)', NULL, 'Annual pre-monsoon firefly season when thousands of fireflies light up the forests around Bhandardara, Arthur Lake and Samrad village. Local camping operators run overnight firefly-camping trips with guided night forest walks, bonfire and meals; peak sightings are the last week of May through the first week of June, roughly mid-May to mid-June.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8410057, 841, 841017, 'Mahashivratri at Amruteshwar Temple', NULL, 'Annual Mahashivratri celebration at the 9th-century Amruteshwar Shiva Temple in Ratanwadi, drawing devotees for prayers and rituals at the ancient Hemadpanthi shrine.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8410058, 841, 841017, 'Navratri at Kalsubai Temple', NULL, 'During Navratri, devotees from nearby villages trek up Kalsubai to the summit temple of Goddess Kalsubai as a religious pilgrimage, making the mountain a major festive gathering point in the Bhandardara region.');

