INSERT OR IGNORE INTO cities (id, state_id, city_name, latitude, longitude) VALUES (841018, 841, 'Igatpuri', 19.69483, 73.5644);

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000428, 841018, 'Dhamma Giri - Vipassana International Academy', 'Dhamma Giri - Vipassana International Academy', 'Dhamma Giri (Hill of Dhamma) is the world''s principal Vipassana meditation centre, founded by S. N. Goenka in 1976. Set on a hill in Igatpuri, its landmark golden pagoda houses over 400 individual meditation cells, and the academy runs 10-day residential Vipassana courses attended by students from across the world. Day visitors can walk the outer campus, see the pagoda and the Buddha-life gallery, making it both a spiritual destination and an architectural landmark.', '1-2 hours', 'October to March; the campus is greenest in monsoon (June-September).', 'Only the outer campus and visitor hall are open to day visitors during visiting hours - the meditation cells and residential zones are off-limits; maintain silence and dress modestly.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Free', 5, 5, 19.69911, 73.55703, 'Dhamma Giri, Igatpuri 422403, Maharashtra, India', 'https://www.dhamma.org', 1.0);

