INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000428, 'insert', 'bulk', 'Coordinates from map geocode with full-address match (relevance 100) for ''Dhamma Giri - Vipassana International Academy, Igatpuri''. Official site dhamma.org fetched and confirmed live; it describes the 10-day courses and states all expenses are met by donations. Visitor timings 9:30 AM-4:30 PM and free entry from trawell.in.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000429, 841018, 'Myanmar Gate', 'Myanmar Gate', 'The Myanmar Gate is the grand ornamental entrance to the Vipassana International Academy (Dhamma Giri), built in 1999 as a gift from Myanmar. Its Burmese-inspired golden carvings, spires and colourful detailing make it look like a slice of Southeast Asia in the Sahyadris, and it is a popular photo stop. Just inside the gate stand the Ashoka Stambh and a visitor hall with paintings depicting the life of the Buddha.', '30 minutes', 'October to March; mornings give the best light for photos.', 'Visit together with the Dhamma Giri campus; morning light is best for photos and it is quietest on weekdays.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 3, 3, 19.698649, 73.557742, 'Dhammagiri Colony, Igatpuri 422403, Maharashtra, India', NULL, 0.6);

