INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000429, 'insert', 'bulk', 'Confirmed as the real entrance gate of Vipassana International Academy (Dhamma Giri) via multiple travel write-ups describing its 1999 Myanmar gift origin; coordinates from a place listing (19.698649, 73.557742), consistent with the Dhamma Giri geocode 700 m away.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000430, 841018, 'Tringalwadi Fort', 'Tringalwadi Fort', 'Tringalwadi is a 3,238-ft hill fort about 10 km from Igatpuri, dating to around the 10th century, built to guard the ancient Thal Ghat trade route between Konkan and Nashik. The mesa-like fort top is reached by an easy 1-1.5 hour trek from Tringalwadi village and offers panoramic views of the Kalsubai and Kulang ranges. At its foothills are rock-cut Jain caves (Pandav Leni) with a carved entrance and a Rishabhanatha idol, plus a rock-cut fort gate, Hanuman shrine and Bhavani Mata temple.', '3-4 hours', 'Monsoon (June-September) and winter (October-February).', 'Start from Tringalwadi village base; carry 2 litres of water and wear trekking shoes - the rock-cut steps near the gate are slippery in monsoon.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 5, 4, 19.73778, 73.53633, 'Tringalwadi village, Igatpuri taluka, Nashik district, Maharashtra 422402, India', NULL, 0.92);

