INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000431, 841018, 'Tringalwadi Lake', 'Tringalwadi Lake', 'Tringalwadi Lake is the reservoir of the Tringalwadi irrigation dam (built 1978) at the base of Tringalwadi Fort, about 7 km from Igatpuri town. The calm water mirrors the fort and surrounding Sahyadri hills, making it a favourite sunrise and photography stop and the usual parking/start point for the fort trek. It is also a known camping and picnic spot, especially in monsoon.', '1 hour', 'June to February; monsoon for full water and greenery.', 'Combine with the Tringalwadi Fort trek - the lake is the natural base/parking point; best in early morning calm.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 3, 4, 19.73215, 73.55826, 'Tringalwadi Dam Road, Tringalwadi, Igatpuri 422402, Maharashtra, India', NULL, 0.68);

