INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000431, 'insert', 'bulk', 'Coordinates from map geocode for ''Tringalwadi Dam, Igatpuri'' (19.73215, 73.55826). Dam built 1978 per Wikipedia; trek guides (justnashik.com, townscript) confirm the lake at the fort base and camping near it.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000432, 841018, 'Camel Valley Viewpoint', 'Camel Valley Viewpoint', 'Camel Valley Viewpoint on the Mumbai-Agra highway, about 4 km from Igatpuri station, overlooks a deep valley named for a rocky cliff shaped like a camel''s head. From the vantage point you get a sweeping panorama of the valley, the Bhatsa River valley beyond, and in monsoon a roaring waterfall cascading about 1,000 feet. It is one of Igatpuri''s most photographed sunset and monsoon viewpoints.', '30-60 minutes', 'Monsoon (June-September) for waterfalls and mist; October-February for clear views.', 'There is no fencing or safety barrier at the viewpoint - stay well back from the edge, especially with children.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Free', 5, 4, 19.696424, 73.526253, 'Agra - Mumbai Hwy (NH-160), near Manas Resort, Igatpuri 422403, Maharashtra, India', NULL, 0.92);

