INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000432, 'insert', 'bulk', 'Coordinates from a place listing for ''Camel Valley Point'' (19.696424, 73.526253), consistent with Camel Valley Resort nearby. Timings 6 AM-6 PM and free entry from trawell.in.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000433, 841018, 'Bhatsa River Valley Viewpoint', 'Bhatsa River Valley Viewpoint', 'The Bhatsa River Valley Viewpoint, about 5 km from Igatpuri station on the Mumbai-Nashik highway, sits at the end of the Thal Ghat and offers a panoramic view of the Bhatsa River winding through a deep green valley. In monsoon the valley turns lush with mist and seasonal waterfalls, and almost every vehicle on the highway stops here. It pairs naturally with the Camel Valley viewpoint 1 km away.', '30 minutes - 1 hour', 'Monsoon (June-September) for the misty, waterfall-dotted valley.', 'Avoid the unfenced edges; sunrise visits are quieter than the busy monsoon midday crowds.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Free', 4, 4, 19.69896, 73.53183, 'Mumbai - Nashik Highway (NH-160), Igatpuri 422403, Maharashtra, India', NULL, 0.8);

