INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000433, 'insert', 'bulk', 'Coordinates from map geocode for ''Bhatsa River Valley Viewpoint, Igatpuri'' (19.69896, 73.53183), ~700 m from the Camel Valley point, matching sources that place the two 1 km apart. Timings and free entry from trawell.in.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000434, 841018, 'Ashoka Waterfall', 'Ashoka Waterfall (Vihigaon Waterfall)', 'Ashoka Waterfall, also called Vihigaon Waterfall, is a monsoon waterfall near Vihigaon village, about 12-13 km from Igatpuri (7-8 km from Kasara). It got its name after a song sequence from the film Ashoka was shot here. The falls drop about 120 feet into a pool reached by a short descent of stone steps, and the site is famous for waterfall rappelling, plus food stalls (maggi, bhutta, chai) near the parking area.', '2-3 hours', 'Monsoon (July-October); the falls are seasonal and may close during very heavy rain.', 'Carry cash - the local gram panchayat collects a modest entry and parking fee; wear grippy footwear for the steep ~200-step descent and skip swimming when the flow is strong.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 4, 4, 19.711548, 73.474708, 'Near Vihigaon village, Kasara-Igatpuri, Nashik district, Maharashtra, India', NULL, 0.8);

