INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000434, 'insert', 'bulk', 'Coordinates from a place listing for ''Vihigaon Ashoka Water Falls'' (19.711548, 73.474708), consistent with sources placing it 11-15 km from Igatpuri and 7-8 km from Kasara. Film-shoot origin, rappelling and local entry/parking fee verified via treksandtrails.org and airial.travel.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000435, 841018, 'Ghatandevi Temple', 'Ghatandevi Temple', 'Ghatandevi Temple, about 5 km from Igatpuri station on the town''s outskirts, is dedicated to Goddess Ghatandevi, worshipped as the protector of the Ghats. Set in a serene valley with the Harihar, Durvar Utvad and Trimak peaks as a backdrop, it draws both pilgrims and photographers. The Tringalwadi Fort trek begins just behind the temple, so the two are often visited together.', '1 hour', 'October to March; early morning for the best views and quiet darshan.', 'Remove footwear outside the temple complex and keep noise low; combine with the Tringalwadi Fort trek behind the temple.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Free', 3, 4, 19.699362, 73.52447, 'Igatpuri, Maharashtra 422403, India', NULL, 0.68);

