INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000435, 'insert', 'bulk', 'Coordinates from a place listing for ''Ghatandevi Mata Mandir, Igatpuri'' (19.699362, 73.52447). Timings 6 AM-6 PM and no entry fee confirmed by both trawell.in and MakeMyTrip; fort-behind-temple detail from theemergingindia.com.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000436, 841018, 'Bhavali Dam', 'Bhavali Dam', 'Bhavali Dam (also spelled Bahuli/Bhawali Dam) is a quiet reservoir south of Igatpuri, surrounded by water, trees and low Sahyadri hills. It is a popular calm picnic and photography spot rather than a developed attraction - visitors sit by the dam, take short walks and enjoy the clean water and cool air. The Bhavli waterfalls on the same road make it an easy combined monsoon outing.', '1-2 hours', 'Monsoon and post-monsoon (July-November).', 'There are few food options around - carry water and snacks; only roadside parking is available.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 3, 4, 19.64204, 73.58286, 'Bhavali, Talegaon, Igatpuri 422403, Maharashtra, India', NULL, 0.68);

