INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000436, 'insert', 'bulk', 'Coordinates from map geocode for ''Bhavali Dam, Igatpuri'' (19.64204, 73.58286). Address ''182, Bhavali, Talegaon, Igatpuri-422403'' and picnic-spot character verified via Justdial listing and igatpurivillas.in.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000437, 841018, 'Bhavli Waterfall', 'Bhavli Waterfall', 'Bhavli Waterfall is a monsoon roadside waterfall near Bhavali Dam on the Igatpuri-Taked road, about 11 km from Igatpuri station. It appears dramatically along the ghat road during the rains and is reached by a short 5-minute walk from roadside parking, making it a favourite quick photo stop. Twin cascades, rocks and the surrounding Sahyadri scenery draw weekend crowds in peak monsoon.', '30-60 minutes', 'Monsoon only (July-September); dry outside the rains.', 'Go on a weekday morning to avoid the monsoon weekend rush and tight roadside parking; it is strictly seasonal, so check flow before driving out.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 4, 4, 19.64313, 73.601255, 'Bahuli, Igatpuri-Taked Road, Igatpuri, Maharashtra 422403, India', NULL, 0.8);

