INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000437, 'insert', 'bulk', 'Coordinates from the primary ''Bhavli Waterfall'' place listing (19.64313, 73.601255, Bahuli, Igatpuri-Taked Road), consistent with a second ''Bhawali Waterfall'' listing 600 m away. Monsoon-seasonality and roadside access verified via airial.travel; hours from the listing only.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000438, 841018, 'Darna Dam', 'Darna Dam', 'Darna Dam is a British-era (1916) gravity dam on the Darna river, about 1.6 km long, northeast of Igatpuri on Aswali Road. The large reservoir (Lake Beale) and its serene backwaters make it a scenic drive and quiet picnic spot with sunset views over the Sahyadris. There are no visitor facilities at the dam site itself, so it suits travellers who carry their own food.', '1-2 hours', 'Monsoon and winter (June-February) for the fullest reservoir.', 'There is no seating, food or information at the dam - pack a picnic; the last stretch of access road is rough, so drive carefully.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 3, 3, 19.7619781, 73.7371876, 'Aswali Road, Igatpuri, Sakur, Maharashtra 422010, India', NULL, 0.6);

