INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000439, 841018, 'Upper Vaitarna Dam', 'Upper Vaitarna Dam', 'Upper Vaitarna Dam, built in 1973 near Saturli village about 30 km from Igatpuri, is a 41-m-high, 2.5-km-long earthfill and gravity dam on the Vaitarna river that supplies water and hydroelectricity to Mumbai. Its vast reservoir (Modak Sagar) spreads across the Vaitarna and Godavari catchments against a Western Ghats backdrop, making it a popular picnic, photography and lakeside-camping destination, especially in monsoon.', '2-3 hours', 'Monsoon (June-September) when the reservoir is full and the hills turn green.', 'It is a 30 km drive from Igatpuri - plan a half-day trip via Saturli village; carry food as facilities are basic.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 3, 3, 19.8143122, 73.5428669, 'Near Saturli village, Igatpuri taluka, Nashik district, Maharashtra, India', NULL, 0.6);

