INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000440, 841018, 'Kavnai Fort', 'Kavnai Fort', 'Kavnai Fort is a lesser-known hill fort on a hillock north of Kavnai village, about 18 km from Igatpuri via Ghoti. At 2,500 ft it is an easy-to-moderate 1.5-2 hour trek through paddy fields and rocky patches, ending in steep rock-cut steps to a summit with a main gate, small pond, ruined mansions and temples to Parvati, Ganesha and Hanuman. The top gives wide views of the Trimbak range and the Vaitarna reservoir.', '3-4 hours', 'June to February; monsoon for greenery, winter for clear views.', 'The final rock-cut steps are steep with a ladder section - wear trekking shoes and avoid in heavy rain; the base village has the small Kapilatirth shrine worth a look.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 3, 4, 19.77308, 73.61939, 'Kavnai village, Igatpuri taluka, Nashik district, Maharashtra 422402, India', NULL, 0.68);

