INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000441, 841018, 'Zaika Family Restaurant', 'Zaika Family Restaurant', 'Zaika Family Restaurant, located inside Hotel Comfort Inn on the Mumbai-Nashik highway at Talegaon, is a popular pure-veg family restaurant in Igatpuri. It is well known for Maharashtrian staples like misal pav and vada pav alongside North Indian, South Indian and Chinese dishes. An easy, affordable stop for travellers on the highway.', '45-60 minutes', 'Open all day; dinner hours are busiest.', 'Try the misal pav and vada pav it is famous for; it opens early (7:30 AM) so works for a breakfast halt too.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Rs 500 for two', 4, 3, 19.691265, 73.549957, 'Plot No 1, Ashwin Nagar, Near Mahindra Auto Factory, Mumbai-Nashik Highway, Talegaon, Igatpuri 422403, Maharashtra, India', NULL, 0.72);

