INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000442, 841018, 'Greenland Pure Veg Family Restaurant', 'Greenland Pure Veg Family Restaurant', 'Greenland Pure Veg Family Restaurant is a well-known vegetarian highway restaurant in Igatpuri serving North Indian food. It features in LBB''s Igatpuri food guide and Tripadvisor''s most-popular list for the town, with its pav bhaji particularly recommended. A reliable pure-veg family halt on the Mumbai-Agra highway.', '45-60 minutes', 'Lunch and dinner hours.', 'Order the pav bhaji - it is the most recommended dish here.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 4, 3, 19.69296, 73.54495, 'Service Road, Mumbai-Agra Highway, Igatpuri 422403, Maharashtra, India', NULL, 0.72);

