INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000443, 841018, 'Tulsi Restaurant Pure Veg & Jain Food', 'Tulsi Restaurant Pure Veg & Jain Food', 'Tulsi Restaurant is a popular pure-veg and Jain-food restaurant on Old Mumbai-Agra Road in Talegaon, Igatpuri. It ranks among Tripadvisor''s three most popular restaurants in town and is a go-to for vegetarian and Jain travellers. Open until 11 PM, it suits late arrivals off the highway.', '45-60 minutes', 'Lunch and dinner; open until 11 PM.', 'A dependable pure-veg/Jain option in town - open till 11 PM, handy if you arrive late.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Rs 750 for two', 4, 4, 19.69355, 73.54958, 'Old Mumbai Agra Road, Talegaon, Igatpuri 422403, Maharashtra, India', NULL, 0.8);

