INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000444, 841018, 'Anand Bhavan', 'Anand Bhavan', 'Anand Bhavan near Igatpuri railway station is a no-frills eatery known for authentic South Indian food - dosas - and Maharashtrian misal pav at affordable prices. With an unpretentious setup and easy parking, it is a favourite quick, tasty budget meal stop for train travellers and locals.', '30-45 minutes', 'Breakfast and lunch.', 'Best for a quick budget breakfast near the station - try the dosa and misal pav combo.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 3, 3, 19.69529, 73.56139, 'Igatpuri Railway Station Road, Igatpuri 422403, Maharashtra, India', NULL, 0.6);

