INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000445, 841018, 'Touchwood Bliss Pure Veg Restaurant', 'Touchwood Bliss Pure Veg Restaurant', 'Touchwood Bliss Pure Veg Restaurant on Bhavali Dam Road is one of Igatpuri''s highest-rated pure-veg restaurants (4.7 with 11,000+ ratings on Justdial) and appears in Tripadvisor''s most-popular list. Set near the Bhavali Dam picnic circuit, it is a natural lunch stop after a dam or waterfall visit.', '45-60 minutes', 'Lunch; opens 9 AM.', 'Plan it as your lunch stop when visiting Bhavali Dam and Bhavli Waterfall - it is on the same road.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 4, 4, 19.66045, 73.5856, 'Bhavali Dam Road, Talegaon, Igatpuri 422403, Maharashtra, India', NULL, 0.8);

