INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000446, 841018, 'Baithak - Multicuisine Restaurant by Manas Lifestyle Resort', 'Baithak - Multicuisine Restaurant by Manas Lifestyle Resort', 'Baithak is the multicuisine restaurant of Manas Lifestyle Resort on the Mumbai-Agra highway near the Camel Valley viewpoint. It is the upscale dining option in the area, open to non-residents, with valley views to go with the meal. LBB also highlights the resort''s Creme fine-dining outlet and 360-degree open-air cafe.', '1-1.5 hours', 'Lunch or dinner; open until 10:30 PM.', 'The resort''s open-air cafe has 360-degree valley views - time your visit around sunset if possible.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Rs 1400 for two', 3, 4, 19.69754, 73.52855, 'Manas Lifestyle Resort, Mumbai-Agra Highway, Igatpuri 422403, Maharashtra, India', NULL, 0.68);

