INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8410059, 841, 841018, 'Igatpuri Fireflies Festival', NULL, 'An annual seasonal nature event in the forests around Igatpuri and Kasara, when lakhs of fireflies light up the pre-monsoon forest. Peak sightings are mid-May to mid-June (roughly May 17 - June 22); campsites around Igatpuri host overnight firefly camping experiences on no-moon nights.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8410060, 841, 841018, 'Nashik-Trimbakeshwar Simhastha (Nashik Kumbh Mela)', NULL, 'One of the four Kumbh Melas, held every 12 years in Nashik district with ritual bathing at Ramkund in Nashik and the Trimbakeshwar Shiva temple on the Godavari. The next edition runs July 17 - August 17, 2027; the Igatpuri-Nashik road is being widened for the expected pilgrim influx.');

-- city: Ajanta (id 1079)
INSERT OR IGNORE INTO cities (id, state_id, city_name, latitude, longitude) VALUES (841019, 841, 'Ajanta', 20.5529, 75.7008);

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000447, 841019, 'Ajanta Caves', 'Ajanta Caves', 'The Ajanta Caves are about 30 rock-cut Buddhist cave monuments carved into a horseshoe-shaped gorge of the Waghora River, dating from the 2nd century BCE to about the 5th century CE. The caves preserve some of the finest surviving examples of ancient Indian painting and sculpture, including murals of the Buddha''s life and the Jataka tales. A UNESCO World Heritage Site since 1983, it is one of India''s most important heritage destinations.', '4-5 hours', 'October to March, when temperatures are mild (20-30C); arrive before 10 AM to beat crowds. Monsoon (June-September) brings seasonal waterfalls in the gorge.', 'Only eco-friendly shuttle buses run from the parking area to the caves; carry water and remove shoes before entering painted caves. Flash photography is banned.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Rs.40 (cash) / Rs.35 (online) per head for Indian, SAARC and BIMSTEC nationals; Rs.600 (cash) / Rs.550 (online) for other foreign visitors; free entry for children below 15 years', 5, 5, 20.5529, 75.7008, 'Ajanta Caves, Ajanta Caves Road, Soegaon, Maharashtra 431117', 'https://asi.nic.in/pages/WorldHeritageAjantaCaves', 1.0);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (841000447, 841000447, NULL, '09:00-17:00', '09:00-17:00', '09:00-17:00', '09:00-17:00', '09:00-17:00', '09:00-17:00', 'Closed on Monday (per ASI). Audio guides in English, French, Spanish, German, Italian, Hindi and Bangla available near the ticket counter.');

