INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000447, 'insert', 'bulk', 'Coordinates 20.5529N 75.7008E geocoded from ''Ajanta Caves'' (FULL_ADDRESS match); consistent with published coordinates 20d33''12"N 75d42''01"E (Wikipedia) and 20d33''9.62"N 75d42''0.68"E (Sahapedia). Timings and fees taken verbatim from the ASI''s official Ajanta Caves page.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000448, 841019, 'Cave 1, Ajanta', 'Cave 1, Ajanta', 'Cave 1 is a 5th-century Mahayana vihara (monastery) and the most famous cave at Ajanta, celebrated for its exquisite murals. It holds the iconic life-size Bodhisattva Padmapani (Avalokiteshvara) and Vajrapani paintings flanking the shrine, plus elaborate ceiling and porch paintings. It is the must-see cave for first-time visitors.', '30-45 minutes', 'October to March; visit early in the day for natural light in the porch and hall.', 'Hire an ASI-authorized guide at the ticket counter; the Jataka and Bodhisattva narratives are hard to read without one.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 5, 5, 20.5529, 75.7008, 'Ajanta Caves, Ajanta Caves Road, Soegaon, Maharashtra 431117', NULL, 1.0);

