INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000448, 'insert', 'bulk', 'Coordinate is the verified Ajanta cave-complex point (20.5529N 75.7008E); individual cave mouths lie along the gorge scarp within the complex, well inside the 1 km tolerance. Cave 1''s Padmapani/Vajrapani murals are documented by the ACSAA (University of Michigan) Ajanta archive and standard ASI descriptions.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000449, 841019, 'Cave 2, Ajanta', 'Cave 2, Ajanta', 'Cave 2 is a 5th-century Mahayana vihara adjoining Cave 1, notable for its highly ornamented painted ceilings and walls. Its murals include the birth of the Buddha and other narrative panels in excellent preservation. Often less crowded than Cave 1, it rewards a slower look.', '20-30 minutes', 'October to March; combine with Cave 1 since they stand side by side.', 'Look up at the ceilings: Cave 2 has some of the most intricate geometric and figural ceiling patterns at the site.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 4, 4, 20.5529, 75.7008, 'Ajanta Caves, Ajanta Caves Road, Soegaon, Maharashtra 431117', NULL, 0.8);

