INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000449, 'insert', 'bulk', 'Coordinate is the verified Ajanta cave-complex point; Cave 2 stands immediately beside Cave 1 in the complex, well within tolerance. Hours/fees per ASI site page.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000450, 841019, 'Cave 4, Ajanta', 'Cave 4, Ajanta', 'Cave 4 is the largest vihara (monastery hall) at Ajanta, with a decorated main entrance leading to a hall carried on twenty-eight pillars. An unfinished but grand 5th-century residence for monks, it shows the scale of the monastic community the site once housed. A key stop for appreciating Ajanta''s rock-cut architecture.', '20-30 minutes', 'October to March; pair with Cave 1 and 2 on the eastern cluster walk.', 'Notice the unfinished areas of Cave 4 - they reveal how the rock was cut and planned, like a frozen construction site.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 4, 4, 20.5529, 75.7008, 'Ajanta Caves, Ajanta Caves Road, Soegaon, Maharashtra 431117', NULL, 0.8);

