INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000450, 'insert', 'bulk', 'Coordinate is the verified Ajanta cave-complex point; Cave 4 lies in the eastern cluster of the complex. ''Largest vihara, 28 pillars'' is a standard published fact cross-checked across sources.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000451, 841019, 'Cave 9, Ajanta', 'Cave 9, Ajanta', 'Cave 9 is one of Ajanta''s earliest prayer halls, a Hinayana chaitya dating to the 2nd-1st century BCE. Its apsidal hall with a central stupa preserves early Buddhist architectural forms, including stone ribs echoing earlier wooden construction. Essential for seeing the oldest phase of the site.', '15-20 minutes', 'October to March; its position near the river bend makes it a natural first stop when walking the chronological route.', 'Walk the caves in chronological order: start at Cave 9/10 (2nd-1st century BCE) at the river bend, then work back toward Cave 1.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 4, 4, 20.5529, 75.7008, 'Ajanta Caves, Ajanta Caves Road, Soegaon, Maharashtra 431117', NULL, 0.8);

