INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000451, 'insert', 'bulk', 'Coordinate is the verified Ajanta cave-complex point; Cave 9 stands at the eastern (river-bend) end of the complex, within tolerance. Early Hinayana date is standard in published descriptions.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000452, 841019, 'Cave 10, Ajanta', 'Cave 10, Ajanta', 'Cave 10 is the oldest chaitya (prayer hall) at Ajanta, a Hinayana rock-cut hall from about the 2nd century BCE stretching nearly 40 metres. Its long nave with stone ribs and central stupa established the chaitya form later refined in Caves 19 and 26. A pilgrimage through time for architecture buffs.', '15-20 minutes', 'October to March; best seen with a guide who can explain the Hinayana-to-Mahayana evolution.', 'Compare Cave 10''s plain early stupa with the ornate Buddha-surmounted stupas of Caves 19 and 26 to see two phases of Buddhist art side by side.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 4, 4, 20.5529, 75.7008, 'Ajanta Caves, Ajanta Caves Road, Soegaon, Maharashtra 431117', NULL, 0.8);

