INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000452, 'insert', 'bulk', 'Coordinate is the verified Ajanta cave-complex point; Cave 10 is adjacent to Cave 9 at the eastern end of the complex. Its status as the oldest chaitya hall is standard in published sources.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000453, 841019, 'Cave 16, Ajanta', 'Cave 16, Ajanta', 'Cave 16 is a 5th-century Mahayana vihara often called the finest monastery at Ajanta, built under Vakataka king Harisena. It holds the celebrated ''dying princess'' (Sundari) mural and finely carved pillars and doorways. Its combination of painting and sculpture makes it one of the most complete caves.', '25-35 minutes', 'October to March; mid-morning light works well for the murals.', 'Ask a guide to point out the ''dying princess'' panel - the emotion in that single mural is among the finest at Ajanta.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 5, 5, 20.5529, 75.7008, 'Ajanta Caves, Ajanta Caves Road, Soegaon, Maharashtra 431117', NULL, 1.0);

