INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000453, 'insert', 'bulk', 'Coordinate is the verified Ajanta cave-complex point; Cave 16 sits in the central cluster, within tolerance. Harisena patronage and the ''dying princess'' mural are standard published facts.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000454, 841019, 'Cave 17, Ajanta', 'Cave 17, Ajanta', 'Cave 17 preserves the largest surviving body of painting at Ajanta, a 5th-century Mahayana vihara covered in murals. Highlights include the Vessantara Jataka narrative, the famous ''Persian embassy'' ceiling panel, and vivid scenes of court life, musicians, and the Buddha''s miracles. If you see only two caves, make it 1 and 17.', '35-45 minutes', 'October to March; allow extra time here - this is the most painting-dense cave.', 'Don''t miss the ceiling ''Persian embassy'' panel - rare evidence of 5th-century contact between India and Persia.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 5, 5, 20.5529, 75.7008, 'Ajanta Caves, Ajanta Caves Road, Soegaon, Maharashtra 431117', NULL, 1.0);

