INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000454, 'insert', 'bulk', 'Coordinate is the verified Ajanta cave-complex point; Cave 17 is in the central cluster, within tolerance. Its record number of surviving paintings and the Vessantara Jataka are standard published facts.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000455, 841019, 'Cave 19, Ajanta', 'Cave 19, Ajanta', 'Cave 19 is a 5th-century Mahayana chaitya whose elaborate carved facade and interior mark the high point of rock-cut Buddhist architecture. Its stupa is fronted by the famous standing Buddha in varada mudra, flanked by yaksha figures and narrative reliefs. Often called the most beautiful chaitya facade at Ajanta.', '25-35 minutes', 'October to March; its facade photographs beautifully in morning light.', 'Study the facade before entering - it is a sculpted sermon in stone, with each panel telling a Jataka story.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 4, 4, 20.5529, 75.7008, 'Ajanta Caves, Ajanta Caves Road, Soegaon, Maharashtra 431117', NULL, 0.8);

