INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000455, 'insert', 'bulk', 'Coordinate is the verified Ajanta cave-complex point; Cave 19 stands in the western half of the complex, within tolerance. Its famous Buddha-fronted stupa is standard in published descriptions.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000456, 841019, 'Cave 26, Ajanta', 'Cave 26, Ajanta', 'Cave 26 is a 5th-century Mahayana chaitya at the far western end of the gorge, home to the colossal reclining Buddha depicting the parinirvana - one of the most photographed sculptures in India. Its pillared nave, Naga king panels, and scenes from the Buddha''s life make it the grand finale of an Ajanta visit.', '30-40 minutes', 'October to March; visit toward the end of your walk, then return via the exit path to the visitor area.', 'Most visitors turn back before Cave 26 because of the walk - go anyway; the reclining Buddha is worth it and crowds thin out here.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 5, 5, 20.5529, 75.7008, 'Ajanta Caves, Ajanta Caves Road, Soegaon, Maharashtra 431117', NULL, 1.0);

