INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000456, 'insert', 'bulk', 'Coordinate is the verified Ajanta cave-complex point; Cave 26 is at the western end of the gorge, within the complex and inside tolerance. The colossal reclining/parinirvana Buddha is documented in published guides.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000457, 841019, 'Middle View Point, Ajanta Caves', 'Middle View Point, Ajanta Caves', 'The Middle View Point sits across the Waghora River from the caves, offering the classic panoramic view of the entire horseshoe-shaped gorge dotted with the cave mouths. Reached by a walkway with footbridges over the river, it is the best spot to grasp the scale and setting of the complex. No separate ticket is required.', '30-45 minutes', 'October to March, early morning or late afternoon for soft light on the gorge; monsoon adds waterfalls but the path can be slippery.', 'Cross the metal footbridges over the Waghora from the cave exit path; carry water - there are limited facilities at the viewpoint itself.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 4, 4, 20.551562, 75.700688, 'Walkway from view point to Caves, Maharashtra 431118, India (plus code HP22+J7W)', NULL, 0.8);

