INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000457, 'insert', 'bulk', 'Coordinates decoded from the published plus code HP22+J7W (Wanderlog listing) using the verified OLC algorithm (checked against Eiffel Tower/Sydney codes) with the cave complex as reference - verified within the locality. The viewpoint''s existence and footbridge route are documented in multiple travel accounts.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000458, 841019, 'Upper View Point, Ajanta Caves', 'Upper View Point, Ajanta Caves', 'The Upper View Point crowns the hill opposite the caves, at the spot where British officer John Smith first sighted the hidden caves in 1819 while hunting - sometimes called Captain''s Point. It offers the highest panoramic sweep over the gorge, river, and forest. Reached by a steep climb or by road; the climb is demanding for elderly visitors.', '45-60 minutes', 'October to March, early morning or late afternoon; spectacular during/after monsoon when the gorge is green and waterfalls run.', 'You can drive up to the viewpoint (recommended for elderly visitors) or hike from the lower viewpoint; wear sturdy shoes for the steep path.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 4, 4, 20.547812, 75.703563, 'GPX3+4CW, View Point, Pimpaldari, Maharashtra 431118, India', NULL, 0.8);

