INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000459, 841019, 'MTDC FootHill Restaurant', 'MTDC FootHill Restaurant', 'The MTDC FootHill Restaurant is the state-tourism-run restaurant at the Ajanta Caves complex, the main sit-down eating option at the site itself. It serves vegetarian and non-vegetarian Indian food at reasonable prices and is the natural lunch stop during a 4-5 hour cave visit. Timings follow the cave complex (closed Monday).', '45-60 minutes', 'Lunchtime during your cave visit (11:30 AM-2 PM).', 'Eat here before the long cave walk or after returning; the only other food at the caves is from vendors near the parking.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 4, 3, 20.551074, 75.703885, 'Ajanta caves, near Ajanta Caves, Soegaon, Maharashtra, IN', NULL, 0.72);

