INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000460, 841019, 'Ajanta Green Restaurant & Resort', 'Ajanta Green Restaurant & Resort', 'Hotel Ajanta Green Restaurant & Resort sits right by the Ajanta T-Point at Fardapur, about 500 m from the cave parking/shuttle area. Its multi-cuisine restaurant serves Indian, Chinese and local Maharashtrian dishes for breakfast, lunch and dinner, with 24/7 room service for guests. A convenient dinner stop on the Fardapur side after the caves close.', '45-75 minutes', 'Lunch or dinner; open through the evening unlike the cave-site restaurant.', 'If staying the night, book directly via the hotel''s WhatsApp for the best rate; the T-Point shuttle buses to the caves run from nearby.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 3, 4, 20.576505, 75.724091, 'Near Ajanta T-Point, Ajanta Caves Road, Fardapur, Maharashtra 431118', 'http://hotelajantagreen.in/', 0.68);

