INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000461, 841019, 'Agrawals Restaurant and Lodging', 'Agrawals Restaurant and Lodging', 'Agrawals Restaurant and Lodging is a long-running eatery and budget lodge on the Jalgaon-Aurangabad highway near the caves, serving Indian vegetarian and non-vegetarian fare. It is one of the few sit-down food options on the Fardapur/Soegaon highway stretch for travellers heading to the caves.', '30-45 minutes', 'Breakfast before the caves or dinner after; on the highway, so it works for drive-through travellers too.', 'Call ahead for group meals; it doubles as lodging if you need a budget night halt on the highway.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 3, 3, 20.586558, 75.725273, 'Near Ajanta Caves, Jalgaon-Aurangabad Highway, Soegaon, Maharashtra, IN', NULL, 0.6);

