INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000462, 841019, 'Shri Rajasthan Dhaba', 'Shri Rajasthan Dhaba', 'Shri Rajasthan Dhaba is a highway dhaba on State Highway 8 near the Ajanta caves turn-off, serving typical dhaba-style North Indian and Rajasthani vegetarian/non-vegetarian food. The affordable, filling thali-style meals make it a practical budget stop for road travellers between Jalgaon, Fardapur and the caves.', '30-45 minutes', 'Lunch or dinner; dhabas on this stretch are busiest at mealtimes.', 'Dhabas here are cash-friendly and quick; pair it with an early-morning cave entry the next day.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 2, 3, 20.592259, 75.723689, 'MH MSH 8, Soegaon, Maharashtra, IN', NULL, 0.48);

