INSERT OR IGNORE INTO cities (id, state_id, city_name, latitude, longitude) VALUES (841020, 841, 'Ellora', 20.02577, 75.17764);

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000463, 841020, 'Ellora Caves', 'Ellora Caves', 'A UNESCO World Heritage Site (listed 1983), the Ellora Caves are one of the largest rock-cut monastery-temple complexes in the world. 34 publicly accessible caves carved from basalt between the 6th and 12th centuries span three faiths: 12 Buddhist (Caves 1-12), 17 Hindu (13-29) and 5 Jain (30-34). The caves stretch along a roughly 2 km cliff near Verul village, about 30 km from Chhatrapati Sambhajinagar (Aurangabad).', '4-5 hours', 'October to February for comfortable weather; monsoon (June-September) brings waterfalls and lush green surroundings', 'Never plan a visit on a Tuesday - the site is closed. Use the Rs.22 shuttle between the Buddhist, Hindu and Jain groups to save walking the 2 km complex.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Rs.40 for Indian/SAARC/BIMSTEC visitors; Rs.600 for foreign nationals; free for children under 15; still camera free; video camera Rs.25 extra', 5, 5, 20.02577, 75.17764, 'Ellora Cave Road, Ellora, Maharashtra 431102, India', 'https://asi.nic.in/pages/WorldHeritageElloraCaves', 1.0);

