INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000463, 'insert', 'bulk', 'Coordinates geocoded to the site address (Ellora 431102). Hours, closure day and fee structure corroborated by multiple 2025-26 travel guides and the ASI''s own page; the ASI page (fetched and confirmed loading) describes the site history and cave numbering.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000464, 841020, 'Kailasa Temple (Cave 16)', 'Kailasa Temple (Cave 16)', 'The largest single monolithic rock excavation in the world, per the Archaeological Survey of India. This massive chariot-shaped temple dedicated to Lord Shiva was carved top-down from a single basalt hill under Rashtrakuta king Krishna I (c. 757-783 CE). Its courtyards are ringed with sculpted panels depicting the two great Hindu epics.', '1-1.5 hours', 'Early morning for soft light on the carvings and fewer crowds; October-February for weather', 'Head straight to Cave 16 first thing in the morning before tour groups arrive, then loop back through the Buddhist and Jain sections.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Rs.40 for Indian/SAARC/BIMSTEC visitors; Rs.600 for foreign nationals; free for children under 15 (same Ellora Caves ticket)', 5, 5, 20.02327, 75.1783, 'Ellora Cave Road, Ellora, Maharashtra 431102, India', NULL, 1.0);

