INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000465, 841020, 'Vishvakarma Cave (Cave 10)', 'Vishvakarma Cave (Cave 10)', 'A Buddhist chaitya griha (prayer hall) whose rock-cut ribs mimic wooden carpentry, earning it the nickname ''Carpenter''s Cave''. Its apsidal hall holds a stupa fronted by a large seated Buddha in teaching pose. The ASI lists Cave 10 among the must-see caves for visitors short on time.', '30-45 minutes', 'Morning; October-February for comfortable exploration', 'Look up at the vaulted ceiling to see the stone ''wooden'' ribs that give the cave its nickname.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Rs.40 for Indian/SAARC/BIMSTEC visitors; Rs.600 for foreign nationals; free for children under 15 (same Ellora Caves ticket)', 4, 4, 20.02091, 75.1794, 'Ellora Cave Road, Ellora, Maharashtra 431102, India', NULL, 0.8);

