INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000466, 841020, 'Dashavatara Cave (Cave 15)', 'Dashavatara Cave (Cave 15)', 'A two-storey Hindu cave celebrated for its sculptures of the ten avatars of Vishnu (Dashavatara) and fine relief panels. The ASI notes the back wall of its front mandapa bears the only definite inscriptional evidence at Ellora, of Rashtrakuta king Dantidurga (c. 753-757 CE). The ASI recommends it for full-day visitors.', '30-45 minutes', 'Morning; October-February', 'Study the upper-storey panels - the sculptural detail here is among the finest in the Hindu group.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Rs.40 for Indian/SAARC/BIMSTEC visitors; Rs.600 for foreign nationals; free for children under 15 (same Ellora Caves ticket)', 3, 4, 20.02577, 75.17764, 'Ellora Cave Road, Ellora, Maharashtra 431102, India', NULL, 0.68);

