INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000466, 'insert', 'bulk', 'The geocoder has no individual record for Cave 15, so coordinates use the verified Ellora Caves site centroid; the cave sits within the complex, well within 1 km of this point. Dashavatara''s importance and Dantidurga inscription are from the ASI''s official Ellora page; no separate official website, so official_website is null.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000467, 841020, 'Rameshvara Cave (Cave 21)', 'Rameshvara Cave (Cave 21)', 'A Hindu cave that predates the Rashtrakutas - the ASI attributes it, along with Caves 1-10, to the Kalachuris of Mahismati. It is among the caves the ASI says visitors with only a few hours ''should not miss'', representing the earlier phase of Ellora''s rock-cut art before the great Kailasa was built.', '30 minutes', 'Morning; October-February', 'Compare its earlier, more austere carving style with the high Rashtrakuta art of the Kailasa - this is Ellora''s oldest layer.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Rs.40 for Indian/SAARC/BIMSTEC visitors; Rs.600 for foreign nationals; free for children under 15 (same Ellora Caves ticket)', 3, 3, 20.02577, 75.17764, 'Ellora Cave Road, Ellora, Maharashtra 431102, India', NULL, 0.6);

