INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000467, 'insert', 'bulk', 'The geocoder has no individual record for Cave 21, so coordinates use the verified Ellora Caves site centroid; the cave sits within the complex, well within 1 km. Its Kalachuri date and must-see status are from the ASI''s official Ellora page; no separate official website, so official_website is null.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000468, 841020, 'Dhumar Lena (Cave 29)', 'Dhumar Lena (Cave 29)', 'One of the largest and most imposing Hindu caves at Ellora, an early excavation at the southern end of the Hindu group. The ASI''s Ellora page notes that the Sita-ki-nahani waterfall lands right next to Cave 29 during the monsoon, when the Elaganga stream is in full flow - making it especially dramatic in the rains. The ASI recommends it for full-day visitors.', '30-45 minutes', 'Monsoon (June-September) to see the Sita-ki-nahani waterfall beside the cave; otherwise October-February', 'Visit in the monsoon if you can - the waterfall crashing down beside this huge cave is a highlight of Ellora.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Rs.40 for Indian/SAARC/BIMSTEC visitors; Rs.600 for foreign nationals; free for children under 15 (same Ellora Caves ticket)', 3, 4, 20.02577, 75.17764, 'Ellora Cave Road, Ellora, Maharashtra 431102, India', NULL, 0.68);

