INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000468, 'insert', 'bulk', 'The geocoder has no individual record for Cave 29, so coordinates use the verified Ellora Caves site centroid; the cave sits within the complex, well within 1 km. Its scale, monsoon waterfall and recommended status are from the ASI''s official Ellora page; no separate official website, so official_website is null.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000469, 841020, 'Indra Sabha (Cave 32)', 'Indra Sabha (Cave 32)', 'The largest and most elaborate of Ellora''s five Jain caves (30-34) at the northern end of the complex. This two-storey excavation, called the ''assembly hall of Indra'', has richly carved pillars, ceilings and shrine images of Jain tirthankaras. The ASI lists Caves 32 and 34 among the must-see caves for short visits.', '45 minutes', 'Morning; October-February. Take the shuttle to the Jain end to save the walk.', 'The Jain caves sit apart at the north end of the 2 km complex - use the site shuttle rather than walking the whole way.', NULL, 'Maharashtra', 0, 0, NULL, NULL, 'Rs.40 for Indian/SAARC/BIMSTEC visitors; Rs.600 for foreign nationals; free for children under 15 (same Ellora Caves ticket)', 4, 4, 20.03281, 75.17359, 'Ellora Cave Road, Ellora, Maharashtra 431102, India', NULL, 0.8);

