INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 841000469, 'insert', 'bulk', 'Coordinates geocoded to ''Caves No 32, Ellora Cave Road, Ellora 431102'', consistent with the Jain group''s position at the northern end of the complex. Must-see status and cave grouping from the ASI''s official Ellora page; no separate official website, so official_website is null.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000470, 841020, 'Grishneshwar Jyotirlinga Temple', 'Grishneshwar Jyotirlinga Temple', 'The 12th and final Jyotirlinga of Lord Shiva, making it the traditional completion point of the Dwadasha Jyotirlinga pilgrimage. The present red-stone temple, built in a rare South-Indian style for Maharashtra, was rebuilt by Ahilyabai Holkar in the 18th century after Maloji Bhosale''s 16th-century reconstruction; it is also an ASI-listed monument. It stands in Verul village, about 1.5 km from the Ellora Caves entrance.', '1-2 hours', 'Early morning for smaller crowds; October-March for weather', 'Combine with the Ellora Caves on the same day - the temple is minutes from the caves'' parking area.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 5, 4, 20.02499, 75.1695, 'Verul village, near Ellora Caves, Aurangabad district, Maharashtra 431102, India', 'http://grishneshwarjyotirling.org/', 0.92);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (841000470, 841000470, '05:30-21:00', '05:30-21:00', '05:30-21:00', '05:30-21:00', '05:30-21:00', '05:30-21:00', '05:30-21:00', 'Darshan 5:30 AM-12:00 PM and 1:00 PM-9:00 PM (midday break 12-1 PM). Extended hours during Shravan.');

