INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000471, 841020, 'Bhadra Maruti Temple', 'Bhadra Maruti Temple', 'A revered Hanuman temple in Khuldabad, about 4-5 km from the Ellora Caves, famous as one of the very few temples in India where Lord Hanuman is worshipped in a reclining/sleeping posture (bhavasana). Local legend holds that Hanuman fell asleep here while listening to King Bhadrasena sing devotional songs of Rama. The present marble temple was rebuilt in the 1960s after earlier structures were destroyed.', '30-45 minutes', 'Early morning or evening; weekdays to avoid Tuesday/Saturday crowds', 'Pair it with Ellora and Grishneshwar in one day - all three are within a few kilometres of each other.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 3, 3, 20.0098, 75.19621, 'Bhadra Hanuman Mandir, Khuldabad, Maharashtra 431101, India', NULL, 0.6);

