INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (841000472, 841020, 'Rasoi Pure Veg', 'Rasoi Pure Veg', 'A pure vegetarian restaurant on the Grishneshwar temple road, minutes from the Ellora Caves entrance. A convenient stop for thalis and typical Indian vegetarian fare between the caves and the temple visit.', '30-60 minutes', 'Lunch or evening', 'Ideal mid-day halt between the Ellora Caves and Grishneshwar temple darshan.', NULL, 'Maharashtra', 0, 0, NULL, NULL, NULL, 2, 3, 20.024869, 75.168466, 'Ghrushneshwar Mandir Rd, Ellora, Maharashtra 431102, India', NULL, 0.48);

