INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8410061, 841, 841020, 'Ellora Ajanta Dance Festival', 'January', 'A real annual festival of Indian classical dance and music organised by the Maharashtra Tourism Development Corporation (MTDC) together with the Aurangabad Festival Committee, spotlighting the Ajanta and Ellora cave heritage. Originally staged against the Kailasa backdrop; recent editions have been held at Soneri Mahal in Aurangabad. Reported in The Hindu BusinessLine (2012 return after a 3-year gap) and recent quiz/heritage references.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8410062, 841, 841020, 'Maha Shivaratri at Grishneshwar', 'February-March', 'Major annual festival at the Grishneshwar Jyotirlinga Temple - special abhishekam rituals, hymns and all-night vigils draw large pilgrim crowds. Shravan month (July-August) also sees very large assemblies and extended temple hours.');

