CREATE TABLE IF NOT EXISTS tripraft_state_meta (
 state_id INTEGER PRIMARY KEY,country_name TEXT NOT NULL,country_code TEXT NOT NULL,
 state_name TEXT NOT NULL,state_code TEXT NOT NULL UNIQUE,state_key TEXT NOT NULL UNIQUE,state_hash TEXT NOT NULL UNIQUE
);
CREATE TABLE IF NOT EXISTS tripraft_city_meta (
 city_id INTEGER PRIMARY KEY,country_name TEXT NOT NULL,country_code TEXT NOT NULL,
 state_name TEXT NOT NULL,state_code TEXT NOT NULL,city_key TEXT NOT NULL UNIQUE,city_hash TEXT NOT NULL UNIQUE
);
CREATE TABLE IF NOT EXISTS tripraft_place_meta (
 place_id TEXT PRIMARY KEY,country_name TEXT NOT NULL,country_code TEXT NOT NULL,
 state_name TEXT NOT NULL,state_code TEXT NOT NULL,city_key TEXT NOT NULL,
 search_key TEXT NOT NULL,stable_key TEXT NOT NULL UNIQUE,stable_hash TEXT NOT NULL UNIQUE
);

CREATE INDEX IF NOT EXISTS idx_tripraft_state_code ON tripraft_state_meta(country_code,state_code);
CREATE INDEX IF NOT EXISTS idx_tripraft_city_geo ON tripraft_city_meta(country_code,state_code,city_key);
CREATE INDEX IF NOT EXISTS idx_tripraft_place_geo ON tripraft_place_meta(country_code,state_code,city_key);
CREATE INDEX IF NOT EXISTS idx_tripraft_place_search_key ON tripraft_place_meta(search_key);
CREATE INDEX IF NOT EXISTS idx_tripraft_place_hash ON tripraft_place_meta(stable_hash);
CREATE INDEX IF NOT EXISTS idx_places_city_category ON places(city_id,category);
CREATE INDEX IF NOT EXISTS idx_places_google_place_id ON places(google_place_id);

