INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000001, 839001, 'Marina Beach', 'Marina Beach', 'Marina Beach is one of the longest urban beaches in the world, stretching about 13 km along the Bay of Bengal from Fort St. George to Besant Nagar. It is Chennai''s most iconic public space, busy at dawn with walkers and in the evening with crowds, food stalls and kite sellers. The beach is unsafe for swimming due to strong currents and undercurrents.', '1-2 hours', 'November to February, early morning or sunset', 'Do not swim — the surf has dangerous undertows; stick to the promenade and the food stalls.', 'no', 'Tamil Nadu', 1, 0, '5:58 AM', '5:58 PM', NULL, 5, 4, 13.05, 80.2824, 'Marina Beach Road, Triplicane, Chennai, Tamil Nadu 600005', NULL, 0.92);

