INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000002, 839001, 'Kapaleeshwarar Temple', 'Kapaleeshwarar Temple', 'Kapaleeshwarar Temple in Mylapore is Chennai''s most famous Shiva temple, dedicated to Lord Kapaleeshwarar and Goddess Karpagambal. The present structure with its 40-metre colourful rajagopuram was rebuilt in the 16th century by Vijayanagara rulers after the original 7th-century Pallava temple was destroyed. The 10-day Panguni Peruvizha (March-April), including the Arubathimoovar procession, is its biggest festival.', '1-2 hours', 'November to February, early morning 6-8 AM', 'Dress modestly and leave footwear at the stand; the west-entrance temple tank area is the calmest spot.', 'no', 'Tamil Nadu', 0, 0, '5:58 AM', '5:58 PM', NULL, 5, 5, 13.0339, 80.2701, '234, Ramakrishna Mutt Road, Mylapore, Chennai, Tamil Nadu 600004', NULL, 1.0);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (839000002, 839000002, '5:30 AM - 12:00 PM, 4:00 PM - 9:30 PM', '5:30 AM - 12:00 PM, 4:00 PM - 9:30 PM', '5:30 AM - 12:00 PM, 4:00 PM - 9:30 PM', '5:30 AM - 12:00 PM, 4:00 PM - 9:30 PM', '5:30 AM - 12:00 PM, 4:00 PM - 9:30 PM', '5:30 AM - 12:00 PM, 4:00 PM - 9:30 PM', '5:30 AM - 12:00 PM, 4:00 PM - 9:30 PM', 'Morning/evening sessions reported by travel sources; the HRCE official temple page failed to load (HTTP 500) so these are unconfirmed against the official schedule. Entry is free.');

