INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 839000002, 'insert', 'bulk', 'Address and coords cross-verified from two search results (234 Ramakrishna Mutt Rd; 13.0337, 80.2698). Official HRCE site mylaikapaleeswarar.hrce.tn.gov.in returned HTTP 500 on fetch attempt — not kept. Hours from tamilagam.in and captureatrip.com, vary slightly across sources.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000003, 839001, 'San Thome Basilica', 'San Thome Basilica', 'San Thome Basilica in Mylapore is built over the tomb of St. Thomas the Apostle, who is believed to have preached in India in 52 AD and was martyred nearby. The present neo-Gothic white church was built in 1893 by the British and elevated to a minor basilica by Pope Pius XII in 1956. It is one of only three churches in the world built over the tomb of an apostle.', '1-2 hours', 'November to February, mornings', 'Descend to the tomb chapel beneath the main altar — it is the spiritual heart of the church; check the website for mass timings.', 'no', 'Tamil Nadu', 0, 0, '5:58 AM', '5:58 PM', NULL, 5, 4, 13.0336, 80.2777, '38, Santhome High Road, Mylapore, Chennai, Tamil Nadu 600004', 'http://www.santhomechurch.org/', 0.92);

