INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000004, 839001, 'Fort St. George and Fort Museum', 'Fort St. George and Fort Museum', 'Fort St. George, built in 1644 by the British East India Company, was the first English fortress in India and is the birthplace of modern Chennai. The complex houses the Fort Museum (est. 1948, ASI-run) with colonial-era weapons, medals, coins, portraits and the first Indian flag hoisted after Independence, plus St. Mary''s Church (1680), the oldest Anglican church in India. Part of the fort still serves as the Tamil Nadu legislative assembly and secretariat.', '1-2 hours', 'November to February, mornings', 'Carry a valid photo ID — the fort is inside a government compound with police screening at the gate.', 'no', 'Tamil Nadu', 0, 0, '5:58 AM', '5:58 PM', 'Rs 20', 4, 3, 13.0797, 80.2873, 'Rajaji Salai, Fort St. George, Chennai, Tamil Nadu 600009', NULL, 0.72);

