INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000005, 839001, 'Government Museum, Egmore', 'Government Museum, Egmore', 'The Government Museum in Egmore, established in 1851, is the second-oldest museum in India after Kolkata''s Indian Museum. Its star exhibits are the Chola bronzes, the Amaravati sculptures, and the largest collection of Roman antiquities outside Europe, spread across six buildings and 46 galleries including the National Art Gallery and a Children''s Museum.', '2-3 hours', 'November to February, mornings', 'Start with the Bronze Gallery (Chola bronzes) — it is the museum''s crown jewel; tickets are cash-only at the counter.', 'no', 'Tamil Nadu', 0, 0, '5:58 AM', '5:58 PM', 'Rs 15', 4, 4, 13.0707, 80.2574, 'Pantheon Road, Egmore, Chennai, Tamil Nadu 600008', NULL, 0.8);

