INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000006, 839001, 'Parthasarathy Temple, Triplicane', 'Parthasarathy Temple', 'The 8th-century Parthasarathy Temple in Triplicane is one of the 108 Divya Desams, dedicated to Lord Krishna as Parthasarathy — Arjuna''s charioteer in the Mahabharata — depicted with a rare moustache. Built by Pallava king Narasimhavarman I and later expanded by the Vijayanagaras, it is one of Chennai''s oldest temples. Its famous prasadam is the Sarkarai Pongal, and the Theppotsavam float festival (February-March) is a major event.', '1-2 hours', 'November to February, early morning', 'Try the temple''s famous Sakkarai Pongal prasadam; photography is not allowed inside the sanctum.', 'no', 'Tamil Nadu', 0, 0, '5:58 AM', '5:58 PM', NULL, 4, 4, 13.0538, 80.277, 'Car Street, Triplicane, Chennai, Tamil Nadu 600005', NULL, 0.8);

