INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000007, 839001, 'Elliot''s Beach (Besant Nagar Beach)', 'Elliot''s Beach', 'Elliot''s Beach at Besant Nagar (called Bessie by locals) is Chennai''s calmer, younger alternative to Marina Beach, popular with joggers, surfers and evening crowds. The Schmidt Memorial and the nearby Ashtalakshmi Temple are its landmarks. It is cleaner and less crowded than Marina, though swimming is still discouraged.', '1-2 hours', 'November to February, evenings', 'Walk south toward the Ashtalakshmi Temple for the quieter stretch; several cafes line the 6th Avenue side for a post-beach coffee.', 'no', 'Tamil Nadu', 1, 0, '5:58 AM', '5:58 PM', NULL, 4, 4, 12.9991, 80.2726, 'Besant Nagar, Chennai, Tamil Nadu 600090', NULL, 0.8);

