INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000008, 839001, 'Arignar Anna Zoological Park (Vandalur Zoo)', 'Arignar Anna Zoological Park', 'Arignar Anna Zoological Park at Vandalur is one of India''s largest zoos, spread over 602 hectares of reserve forest with lion and deer safaris, a butterfly house, reptile house, aquarium and nocturnal animal house. Originally established in 1855 (relocated to Vandalur in 1985), it houses around 2,500 animals including tigers, elephants and endangered species. It is a full-day family outing about 31 km southwest of central Chennai.', '4-5 hours', 'November to February, mornings 9-11 AM', 'Arrive at opening (9 AM) — animals are most active before noon; rent the battery vehicle or cycle because the campus is huge.', 'no', 'Tamil Nadu', 0, 0, '5:58 AM', '5:58 PM', 'Rs 200', 4, 4, 12.8797, 80.0831, 'GST Road, Vandalur, Chennai, Tamil Nadu 600048', NULL, 0.8);

