INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000009, 839001, 'Guindy National Park and Chennai Snake Park', 'Guindy National Park', 'Guindy National Park is one of the very few national parks located inside a city — a 2.7 sq km protected forest in the heart of Chennai, home to blackbuck, spotted deer, jackals and 130+ bird species. Adjacent to it are the Children''s Park and the Chennai Snake Park (Guindy Snake Park), with cobras, pythons, vipers and crocodiles. The park sits on the former Guindy Lodge grounds adjoining Raj Bhavan.', '2-3 hours', 'November to February, mornings', 'Combine the national park walk with the Snake Park next door; both close on Tuesdays.', 'no', 'Tamil Nadu', 0, 0, '5:58 AM', '5:58 PM', 'Rs 20', 3, 3, 13.0069, 80.2315, 'Sardar Patel Road, Guindy, Chennai, Tamil Nadu 600025', NULL, 0.6);

