INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000010, 839001, 'B.M. Birla Planetarium', 'B.M. Birla Planetarium', 'The B.M. Birla Planetarium in Kotturpuram is part of the Periyar Science and Technology Centre campus and a Chennai school-trip staple. It runs English and Tamil sky shows (10:45 AM, 1:15 PM, 3:45 PM English; 12 PM, 2:30 PM Tamil) plus 3D shows, a Science on a Sphere exhibit and an outdoor Science Park. The mechanical projector was replaced with a hybrid digital system during a 2018 renovation.', '1-2 hours', 'Year-round, arrive 30 min before a show', 'Pick your show language in advance — English and Tamil shows run at fixed slots; the Saturday 7-9 PM night-sky observation is a bonus.', 'no', 'Tamil Nadu', 0, 0, '5:58 AM', '5:58 PM', 'Rs 35', 3, 3, 13.0111, 80.2359, 'Gandhi Mandapam Road, Kotturpuram, Chennai, Tamil Nadu 600025', NULL, 0.6);

