INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000011, 839001, 'Valluvar Kottam', 'Valluvar Kottam', 'Valluvar Kottam in Nungambakkam is a memorial to the Tamil poet-saint Thiruvalluvar, author of the Thirukkural, built as a 106-foot stone temple chariot with a life-size statue of the poet. Its Kural Manimandapam hall carries all 1,330 couplets of the Thirukkural carved on granite. The complex was renovated with light-and-sound and musical-fountain shows and reopened in June 2025.', '1-2 hours', 'November to February, evenings for the light show', 'Come after 6:30 PM for the chariot light show and musical fountain (around 7-7:20 PM).', 'no', 'Tamil Nadu', 0, 1, '5:58 AM', '5:58 PM', NULL, 3, 4, 13.0535, 80.2437, '47, Valluvar Kottam High Road, Nungambakkam, Chennai, Tamil Nadu 600034', NULL, 0.68);

