INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000012, 839001, 'Semmozhi Poonga', 'Semmozhi Poonga', 'Semmozhi Poonga (Classical Language Park) on Cathedral Road is Chennai''s first botanical garden, opened in 2010 on the former Woodlands Drive-In site. The 20-acre garden holds over 500 plant species across themed sections — bonsai garden, palm court, butterfly garden, cascade gardens and a duck pond. It is run by the Tamil Nadu Horticulture Department.', '1-2 hours', 'November to February, mornings or evenings', 'Photography is fine for personal use; a separate permit may be needed for professional shoots.', 'no', 'Tamil Nadu', 0, 0, '5:58 AM', '5:58 PM', 'Rs 15', 3, 3, 13.0581, 80.251, 'Cathedral Road, Teynampet, Chennai, Tamil Nadu 600086', NULL, 0.6);

