INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000013, 839001, 'Theosophical Society, Adyar', 'Theosophical Society, Adyar', 'The Adyar campus is the international headquarters of the Theosophical Society, founded in 1875 by Helena Blavatsky and Henry Olcott, spread over about 260 acres of wooded gardens on the Adyar river. Its star attraction is the 450-year-old Adyar Banyan Tree, among the largest in India, plus the Adyar Library with centuries-old manuscripts, a Buddhist shrine and a Zoroastrian temple. It is a rare vehicle-free green refuge in the city.', '2-3 hours', 'November to February, mornings 8:30-10 AM', 'Visiting hours are narrow (mornings and afternoons) and the campus is closed on Sundays — plan around the 8:30-10 AM / 2-4 PM windows.', 'no', 'Tamil Nadu', 0, 0, '5:58 AM', '5:58 PM', NULL, 3, 4, 13.0104, 80.2596, 'Blavatsky Avenue, Adyar, Chennai, Tamil Nadu 600020', 'http://www.ts-adyar.org/', 0.68);

