INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000014, 839001, 'Cholamandal Artists'' Village', 'Cholamandal Artists'' Village', 'Cholamandal Artists'' Village on the East Coast Road, founded in 1966 by painter K.C.S. Paniker, is India''s largest self-supporting artists'' commune and the cradle of the Madras Movement of modern art. The 10-acre campus has art galleries, a museum, an open-air theatre and a sculpture garden, and visitors can often watch resident artists at work. A sales gallery lets artists sell directly — their main source of income.', '2-3 hours', 'November to February, mornings', 'Go in the morning when resident artists are in their studios and open to conversation; combine with Dakshinachitra on the same ECR drive.', 'no', 'Tamil Nadu', 0, 0, '5:58 AM', '5:58 PM', 'Rs 20', 3, 4, 12.9011, 80.2574, 'Injambakkam, East Coast Road, Chennai, Tamil Nadu 600115', NULL, 0.68);

