INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000015, 839001, 'Dakshinachitra Heritage Museum', 'Dakshinachitra Heritage Museum', 'Dakshinachitra on the East Coast Road at Muttukadu is a living-history museum of South Indian heritage, founded by the Madras Craft Foundation and opened in 1996. Its 10-acre campus reconstructs 18+ authentic heritage houses from Tamil Nadu, Kerala, Karnataka and Andhra Pradesh, with craft demonstrations, folk performances and workshops. It sits about 25 km south of Chennai and is best combined with Mahabalipuram.', '3-4 hours', 'November to February, early afternoon when demonstrations are active', 'Closed on Tuesdays and on Diwali; budget half a day and catch the craft demonstrations and the South Indian restaurant inside.', 'no', 'Tamil Nadu', 0, 0, '5:58 AM', '5:58 PM', 'Rs 200', 4, 5, 12.9014, 80.2406, 'East Coast Road, Muttukadu, Chengalpattu District, Tamil Nadu 603110', NULL, 0.88);

