INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 839000015, 'insert', 'bulk', 'Hours 10-6 closed Tuesday agreed across nativeplanet, chennai tourism, thrillophilia. Fee conflicts: nativeplanet Rs 175 weekday/Rs 200 weekend adult vs older Rs 100-120 — used Rs 200 with flag. Official site dakshinachitra.net appeared in search but was not fetched — official_website null per rules. ~25 km south of Chennai (Muttukadu) — counts as a near day-trip but not tallied in the 100-km day-trip set.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000016, 839001, 'Shore Temple, Mahabalipuram (day trip)', 'Shore Temple, Mahabalipuram', 'The Shore Temple at Mahabalipuram (Mamallapuram), about 60 km south of Chennai, is an 8th-century Pallava granite temple complex on the Bay of Bengal and the centrepiece of the UNESCO World Heritage ''Group of Monuments''. Built under Narasimhavarman II (Rajasimha), it combines two Shiva shrines with a Vishnu shrine and rows of Nandi sculptures. One ASI ticket (Rs 40) covers the Shore Temple, Pancha Rathas and other monuments in town.', 'Half day to full day (including Pancha Rathas, Arjuna''s Penance, Krishna''s Butterball)', 'October to February, early morning or sunset; ~60 km / 1.5 hrs from Chennai via ECR', 'Buy one ASI ticket at the Shore Temple — it is valid at the Pancha Rathas too; go at sunrise for the best light and smallest crowds.', 'no', 'Tamil Nadu', 1, 1, '5:58 AM', '5:58 PM', 'Rs 40', 5, 5, 12.616, 80.1993, 'Shore Temple Complex, Mahabalipuram, Chengalpattu District, Tamil Nadu 603104', NULL, 1.0);

