INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 839000016, 'insert', 'bulk', 'Hours 6-6 and fee Rs 40/600 agreed across mytownblog, traveltam, captureatrip, wanderlog reviews; older pages cite Rs 10/250 which are stale. ~60 km from Chennai via ECR — day trip #1 of 5 within 100 km.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000017, 839001, 'Kailasanathar Temple, Kanchipuram (day trip)', 'Kailasanathar Temple, Kanchipuram', 'The Kailasanathar Temple in Kanchipuram, about 75 km southwest of Chennai, is the oldest surviving Pallava temple (early 8th century, built by Narasimhavarman II) and a landmark of early Dravidian architecture in sandstone. Kanchipuram itself is the ''City of Thousand Temples'' — a former Pallava capital and one of Hinduism''s seven sacred cities — and the centre of the famous Kanchipuram silk saree weaving industry. Combine with the Ekambaranathar and Varadaraja Perumal temples in the same town.', 'Full day from Chennai (2-3 temples + silk shopping)', 'November to February; ~75 km / 2 hrs from Chennai', 'Start at Kailasanathar at opening to see the sandstone carvings in soft light, then do Ekambaranathar and the silk-weaver streets.', 'no', 'Tamil Nadu', 0, 0, '5:58 AM', '5:58 PM', NULL, 5, 4, 12.8424, 79.6896, 'Kailasanathar Temple, Kanchipuram, Tamil Nadu 631501', NULL, 0.92);

