INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000018, 839001, 'Pulicat Lake Bird Sanctuary (day trip)', 'Pulicat Lake Bird Sanctuary', 'Pulicat Lake, about 60 km north of Chennai, is India''s second-largest brackish-water lagoon and a Ramsar wetland spanning the Tamil Nadu-Andhra Pradesh border. From October to March it hosts up to 15,000 greater flamingos plus pelicans, painted storks, spoonbills and 220+ bird species. Pulicat town also has Dutch colonial heritage — a 1609 fort and cemetery — and boat rides on the lagoon run from the village.', 'Half day (4-6 hours including travel)', 'October to March, early morning for bird activity; ~60 km / 1.5 hrs from Chennai', 'Visit October-March only — the lake is quiet in other months; carry binoculars and take the boat ride from Pulicat village for flamingo views.', 'no', 'Tamil Nadu', 1, 1, '5:58 AM', '5:58 PM', NULL, 4, 4, 13.4012, 80.3084, 'Pulicat (Pazhaverkadu), Tiruvallur District, Tamil Nadu 601205', NULL, 0.8);

