INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000019, 839001, 'Covelong (Kovalam) Beach (day trip)', 'Covelong Beach', 'Covelong (Kovalam), about 40 km south of Chennai on the ECR, is a historic fishing village turned beach getaway — the site of an 18th-century Dutch/British fort and one of Chennai''s few surfable beaches with surf schools. It is quieter than the city beaches and works as a half-day seaside escape, often combined with Dakshinachitra and Mahabalipuram on the ECR.', 'Half day', 'November to February; ~40 km / 1 hr from Chennai via ECR', 'Book a surf lesson with one of the local surf schools if you are a beginner — Covelong has Chennai''s most consistent beginner waves.', 'no', 'Tamil Nadu', 1, 1, '5:58 AM', '5:58 PM', NULL, 3, 4, 12.79, 80.2542, 'Covelong (Kovalam), Chengalpattu District, Tamil Nadu 603112', NULL, 0.68);

