INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000020, 839001, 'MGR Memorial and Anna Memorial', 'MGR Memorial and Anna Memorial', 'The MGR Memorial and the adjacent Anna Memorial on Marina Beach honour two former Tamil Nadu chief ministers — M.G. Ramachandran and C.N. Annadurai. The MGR Memorial, with its sculpted arch and landscaped plaza, is a landmark at the northern end of Marina Beach. Both are free public memorials and popular photo stops on a Marina walk.', '30-45 minutes', 'November to February, evenings', 'Visit as part of a Marina Beach evening walk — the memorials are lit up after dark.', 'no', 'Tamil Nadu', 0, 1, '5:58 AM', '5:58 PM', NULL, 3, 3, 13.051, 80.2833, 'Marina Beach Road, Chennai, Tamil Nadu 600005', NULL, 0.6);

