INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000021, 839001, 'Hotel Saravana Bhavan, Mylapore', 'Hotel Saravana Bhavan, Mylapore', 'Hotel Saravana Bhavan''s Mylapore outlet, next to the Kapaleeshwarar Temple, is one of the flagship branches of the world''s best-known South Indian vegetarian chain. Famous for ghee roast masala dosa, idli-sambar and strong filter coffee, it is the classic post-temple meal stop. Meals are budget-friendly (around Rs 300-700 for two per listing sites).', '45-60 minutes', 'Breakfast 7-9 AM or lunch 12-2 PM', 'Expect a queue at lunch and dinner — the mini tiffin is the best-value sampler.', 'no', 'Tamil Nadu', 0, 0, '5:58 AM', '5:58 PM', NULL, 5, 4, 13.0346, 80.2689, '70, North Mada Street, Mylapore, Chennai, Tamil Nadu 600004', NULL, 0.92);

