INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000022, 839001, 'Murugan Idli Shop, T. Nagar', 'Murugan Idli Shop, T. Nagar', 'Murugan Idli Shop is a beloved Chennai vegetarian chain famed for pillow-soft idlis, ghee podi idli, crispy ghee-roast dosas and sweet pongal served on banana leaves. The T. Nagar branch (N. Usman Road) is one of its busiest outlets. Food is inexpensive and the kitchen runs through the day, making it a reliable breakfast-through-dinner stop.', '45 minutes', 'Breakfast or evening tiffin time', 'Order the ghee podi idli and sweet pongal together — the signature combination.', 'no', 'Tamil Nadu', 0, 0, '5:58 AM', '5:58 PM', NULL, 4, 4, 13.0365, 80.2307, '91, 93, N. Usman Road, T. Nagar, Chennai, Tamil Nadu 600017', NULL, 0.8);

