INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000023, 839001, 'Adyar Ananda Bhavan (A2B), Adyar', 'Adyar Ananda Bhavan', 'Adyar Ananda Bhavan (A2B) is Chennai''s giant pure-vegetarian restaurant and sweet chain, with dozens of outlets across the city including its home neighbourhood Adyar. It serves South Indian meals, tiffin items and an extensive sweets-and-savouries counter — a one-stop shop for meals plus take-home Mysore pak and mixture. Prices are firmly budget.', '45 minutes', 'Lunch for the meals; evenings for sweets shopping', 'The sweets counter is a destination in itself — take home the ghee Mysore pak.', 'no', 'Tamil Nadu', 0, 0, '5:58 AM', '5:58 PM', NULL, 3, 4, 13.0065, 80.257, 'Adyar, Chennai, Tamil Nadu 600020', NULL, 0.68);

