INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000024, 839001, 'Anjappar Chettinad Restaurant, Nungambakkam', 'Anjappar Chettinad Restaurant', 'Anjappar is Chennai''s best-known Chettinad chain, serving the fiery black-pepper-heavy cuisine of the Chettinad region — chicken 65, mutton varutha curry, crab pepper masala and biryanis. The Nungambakkam outlet (J P Tower, Nungambakkam High Road) is centrally located. Pricing is moderate, family-friendly and the portions are generous.', '1-1.5 hours', 'Lunch 12-3 PM or dinner 7-10 PM', 'Order the nattu kozhi (country chicken) preparations and the parotta — Chettinad heat is real, so pace yourself.', 'no', 'Tamil Nadu', 0, 0, '5:58 AM', '5:58 PM', NULL, 4, 4, 13.0559, 80.2485, 'J P Tower, 7/2, Nungambakkam High Road, Chennai, Tamil Nadu 600034', NULL, 0.8);

