INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000025, 839001, 'Dindigul Thalappakatti, T. Nagar', 'Dindigul Thalappakatti', 'Dindigul Thalappakatti is the Chennai chain famous for Dindigul-style seeraga samba biryani — a short-grain fragrant rice biryani distinct from basmati versions. The T. Nagar outlet (Venkatanarayana Road) serves chicken, mutton and egg biryanis plus parotta and egg karandi. It is the go-to biryani brand for many Chennai locals, at moderate prices.', '1 hour', 'Lunch 12-3 PM', 'The mutton biryani with seeraga samba rice is the signature — skip the basmati biryani variants for the authentic experience.', 'no', 'Tamil Nadu', 0, 0, '5:58 AM', '5:58 PM', NULL, 4, 4, 13.0337, 80.2382, '27, Venkatanarayana Road, T. Nagar, Chennai, Tamil Nadu 600017', NULL, 0.8);

