INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000026, 839001, 'The Marina, Nungambakkam', 'The Marina', 'The Marina on College Road, Nungambakkam is one of Chennai''s best-known standalone seafood restaurants — diners pick fresh fish, prawns, crab and lobster from the display and choose the preparation (Indian or Chinese style). It is upscale (around Rs 2,000 for two per listings) and positions itself around sustainably sourced seafood. Lunch and dinner are served in two sittings with an afternoon break.', '1.5-2 hours', 'Dinner 7-10 PM', 'Go for dinner and pick your fish from the fresh display — prices are by weight, so confirm the cost before it is cooked.', 'yes', 'Tamil Nadu', 0, 0, '5:58 AM', '5:58 PM', NULL, 3, 5, 13.0673, 80.2522, '39, College Road, Nungambakkam, Chennai, Tamil Nadu 600006', NULL, 0.76);

