INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8390001, 839, 839001, 'Pongal', 'January', 'Tamil Nadu''s biggest harvest festival, celebrated over four days (Bhogi, Thai Pongal, Mattu Pongal, Kaanum Pongal). Families cook the sweet pongal dish in new pots at sunrise, decorate homes with kolam, and honour cattle; Jallikattu bull-taming events happen in southern districts.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8390002, 839, 839001, 'Chennai Margazhi Music Season', 'December-January', 'One of the world''s largest classical music festivals, held across hundreds of sabhas in Chennai during the Tamil month of Margazhi. Carnatic music concerts and Bharatanatyam dance performances run from morning to night, drawing artists and rasikas from around the globe.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8390003, 839, 839001, 'Deepavali', 'October-November', 'The festival of lights, celebrated with oil lamps, fireworks, new clothes and sweets. In Tamil Nadu it is traditionally observed a day earlier than in much of North India, and Chennai''s markets and temples are at their liveliest.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8390004, 839, 839001, 'Madras Week', 'August', 'A city heritage celebration around Madras Day (22 August), marking the founding of the city in 1639. It features heritage walks, talks, exhibitions and food trails organised by citizen groups across Chennai.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8390005, 839, 839001, 'Arubathimoovar Festival (Kapaleeshwarar Temple)', 'March-April', 'The grandest day of the 10-day Panguni Peruvizha at Mylapore''s Kapaleeshwarar Temple, when the idols of Lord Kapaleeshwarar, Goddess Karpagambal and the 63 Nayanmar saints are taken in a massive street procession drawing lakhs of devotees.');

-- city: Madurai (id 1032)
INSERT OR IGNORE INTO cities (id, state_id, city_name, latitude, longitude) VALUES (839002, 839, 'Madurai', 9.9252, 78.1198);

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000027, 839002, 'Meenakshi Amman Temple', 'Meenakshi Amman Temple', 'The 2,500-year-old heart of Madurai, dedicated to Goddess Meenakshi and Lord Sundareswarar. Its 14 gopurams - the tallest rising 170 feet - are covered in thousands of brightly painted sculptures, and the complex holds the Hall of Thousand Pillars, the Golden Lotus Tank and a renowned art museum. One of India''s most visited temples and the focal point of the Chithirai festival.', '2-4 hours', 'Early morning (5-8 AM) or evening (4-7 PM)', 'Phones and cameras are prohibited inside; dress modestly and allow time for security lines. Stay for the Palliyarai night ceremony around 9:30 PM if you can.', 'no', 'Tamil Nadu', 0, 0, '6:09 AM', '6:04 PM', 'Free (special darshan Rs 50-100)', 5, 5, 9.9195, 78.1193, 'Madurai Main, Madurai, Tamil Nadu 625001', NULL, 1.0);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (839000027, 839000027, '5:00 AM - 12:30 PM, 4:00 PM - 10:00 PM', '5:00 AM - 12:30 PM, 4:00 PM - 10:00 PM', '5:00 AM - 12:30 PM, 4:00 PM - 10:00 PM', '5:00 AM - 12:30 PM, 4:00 PM - 10:00 PM', '5:00 AM - 12:30 PM, 4:00 PM - 10:00 PM', '5:00 AM - 12:30 PM, 4:00 PM - 10:00 PM', '5:00 AM - 12:30 PM, 4:00 PM - 10:00 PM', 'Standard published pattern 5 AM-12:30 PM & 4-10 PM. Special darshan tickets Rs 50-100 per travel sites; general entry free.');

