INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000028, 839002, 'Thirumalai Nayakkar Mahal', 'Thirumalai Nayakkar Mahal', 'The 17th-century palace of King Thirumalai Nayak (built 1636), famed for its gigantic stuccoed arches, 82-foot-high domed hall and Italian-influenced craftsmanship. An evening sound-and-light show narrates the Nayak dynasty''s history in English and Tamil.', '1-2 hours', 'Morning for photography; evening for the light show', 'Visit the evening sound & light show (English ~6:45 PM, Tamil ~8 PM) - schedules can change, confirm locally.', 'no', 'Tamil Nadu', 0, 0, '6:09 AM', '6:04 PM', 'Rs 10 adults, Rs 50 foreign nationals, Rs 5 children', 5, 4, 9.9151, 78.12375, 'Palace Road, Madurai, Tamil Nadu 625001', NULL, 0.92);

