INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000029, 839002, 'Gandhi Memorial Museum', 'Gandhi Memorial Museum', 'Housed in the historic Tamukkam Palace, this museum chronicles Mahatma Gandhi''s life and the freedom struggle, including the blood-stained dhoti he wore at his assassination. One of India''s five Gandhi Sangrahalayas, with letters, photographs and khadi exhibits.', '1-2 hours', 'Morning', 'Closed Sundays and public holidays per maduraitourism.co.in - plan a weekday visit.', 'no', 'Tamil Nadu', 0, 0, '6:09 AM', '6:04 PM', 'Free', 4, 4, 9.92889, 78.1367, 'Tamukkam Palace, Tallakulam, Madurai, Tamil Nadu 625020', NULL, 0.8);

