INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000030, 839002, 'Vandiyur Mariamman Teppakulam', 'Vandiyur Mariamman Teppakulam', 'A vast 16th-century temple tank built by King Thirumalai Nayak, with a central island shrine (Maiya Mandapam) reached by boat. It hosts the annual Teppam float festival, when the deities of Meenakshi and Sundareswarar are taken around the tank on a decorated float.', '30-60 minutes', 'Evening', 'Combine with the Teppam float festival in Jan-Feb if your dates align; evenings are pleasant.', 'no', 'Tamil Nadu', 0, 0, '6:09 AM', '6:04 PM', NULL, 4, 4, 9.91053, 78.14633, 'Vandiyur, Madurai, Tamil Nadu 625020', NULL, 0.8);

