INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000031, 839002, 'Koodal Azhagar Temple', 'Koodal Azhagar Temple', 'A Vishnu temple in the heart of Madurai and the 47th of the 108 Divya Desams. Its rare ashtanga vimana shrine shows Vishnu in three postures - standing, sitting and reclining - on three tiers. Sangam literature celebrates Koodal as a seat of Tamil and Vaishnavite culture.', '1 hour', 'Morning', 'Climb to each tier to see the three forms of Vishnu; the vimana is the temple''s unique feature.', 'no', 'Tamil Nadu', 0, 0, '6:09 AM', '6:04 PM', 'Free', 4, 4, 9.91437, 78.11416, 'Perumal Koil Sannathi St, Madurai, Tamil Nadu 625001', 'https://koodalalagar.hrce.tn.gov.in/', 0.8);

