INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000032, 839002, 'St. Mary''s Cathedral', 'St. Mary''s Cathedral', 'Madurai''s principal Catholic church, also called the Church of Our Lady of Dolours. Founded in 1840 and built in 1841, it was elevated to a cathedral in 1969. Its twin 42-metre bell towers and blend of European, Roman and Continental styles stand out amid the old city.', '30-60 minutes', 'Morning or evening', 'Footwear is not allowed inside; mornings and evenings have daily services.', 'no', 'Tamil Nadu', 0, 0, '6:09 AM', '6:04 PM', 'Free', 3, 4, 9.913417, 78.12575, 'East Veli Street, Madurai, Tamil Nadu 625001', NULL, 0.68);

