INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000033, 839002, 'Kazimar Big Mosque', 'Kazimar Big Mosque', 'The oldest mosque in Madurai, dating to the 13th century, built by Kazi Syed Tajuddin. It has served the city''s Muslim community for over 700 years and sits close to the Meenakshi temple in the old city.', '30 minutes', 'Morning', 'Visit outside prayer times; dress modestly and remove footwear before entering.', 'no', 'Tamil Nadu', 0, 0, '6:09 AM', '6:04 PM', NULL, 3, 3, 9.91635, 78.11411, 'Kazimar Street, Madurai, Tamil Nadu 625001', NULL, 0.6);

