INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000034, 839002, 'Puthu Mandapam', 'Puthu Mandapam', 'The ''New Hall'' - nearly 400 years old - commissioned by Thirumalai Nayak (1628-1635) opposite the Meenakshi temple''s eastern tower. Its 124 sculpted pillars (330 x 105 ft hall) depict Nayak rulers and deities; today the hall doubles as a bustling market of tailors, book shops and utensil stalls.', '45-60 minutes', 'Morning or late afternoon', 'Look up at the pillars and ceiling carvings - easy to miss amid the market stalls. Bargain with the tailors.', 'no', 'Tamil Nadu', 0, 0, '6:09 AM', '6:04 PM', NULL, 4, 4, 9.92028, 78.12152, 'East Chithirai Street, Madurai, Tamil Nadu 625001', NULL, 0.8);

