INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000035, 839002, 'Samanar Hills', 'Samanar Hills', 'A rocky hillock west of Madurai with Jain caves, beds and Tamil-Brahmi inscriptions dating from the 2nd century BCE to the 9th century CE. An ASI-protected site, it is a quiet climb with ancient carvings and views over the countryside.', '1-2 hours', 'Morning, October-February', 'Go in the morning with water and sturdy shoes; the climb is short but rocky. Combine with nearby Keelakuyilkudi village.', 'no', 'Tamil Nadu', 0, 1, '6:09 AM', '6:04 PM', NULL, 3, 4, 9.92059, 78.04663, 'Keelakuyilkudi, Madurai, Tamil Nadu', NULL, 0.68);

