INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000036, 839002, 'Vilacheri Pottery Village', 'Vilacheri Pottery Village', 'Home of the Velar potter community, where some 200 families have made clay and papier-mache Golu dolls since 1965. Watch artisans mould and hand-paint deities, festival figures and Christmas cribs, and buy directly from the makers. A GI-tag application has been filed for the craft.', '1-2 hours', 'Daytime, September-December', 'Best visited during festival season (Navaratri/Dussehra, Christmas) when workshops are busiest; buy direct for better prices.', 'no', 'Tamil Nadu', 0, 0, '6:09 AM', '6:04 PM', NULL, 3, 4, 9.89452, 78.06042, 'Vilachery Main Road, Madurai, Tamil Nadu 625111', NULL, 0.68);

