INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000037, 839002, 'Thirumogur Kalamegaperumal Temple', 'Thirumogur Kalamegaperumal Temple', 'One of the 108 Divya Desams, over 2,000 years old, dedicated to Kalamega Perumal with consort Mohanavalli. Its fame rests on the Sudarshana Chakra shrine - Chakrathalwar with 16 hands, each holding a weapon - with Yoga Narasimha on the reverse. About 11-12 km northeast of Madurai.', '1-1.5 hours', 'Morning', 'Don''t miss the Chakrathalwar shrine and the Yoga Narasimha behind it. Saturdays are crowded.', 'no', 'Tamil Nadu', 0, 0, '6:09 AM', '6:04 PM', 'Free', 4, 4, 9.95055, 78.20813, 'Thiruvathavur Road, Thirumogur, Madurai, Tamil Nadu 625107', NULL, 0.8);

