INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000039, 839002, 'Goripalayam Dargah', 'Goripalayam Dargah', 'A 13th-century dargah housing the tombs of Sulthan Alauddin and Shamsuddin Badusha, rulers from Oman, alongside a large dome said to be carved from a single stone. One of Madurai''s most important Islamic shrines.', '30-45 minutes', 'Morning', 'Dress modestly; visit in daylight hours. Thursdays and festival days draw the biggest crowds.', 'no', 'Tamil Nadu', 0, 0, '6:09 AM', '6:04 PM', NULL, 3, 3, 9.91746, 78.14086, 'Goripalayam, Madurai, Tamil Nadu 625002', NULL, 0.6);

