INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000041, 839002, 'Thiruparankundram Murugan Temple', 'Thiruparankundram Murugan Temple', 'The first of the six Arupadai Veedu (abodes of Lord Murugan), this rock-cut temple is carved into a 1,048-foot granite hill about 8 km southwest of Madurai. Its mandapams blend Pandyan and Nayak architecture, with shrines to Murugan, Shiva, Vishnu and Durga.', '1.5-2 hours', 'Morning', 'The temple is carved into a hill - expect steps. Skanda Sashti and Karthigai are the big festivals.', 'no', 'Tamil Nadu', 0, 0, '6:09 AM', '6:04 PM', 'Free', 5, 5, 9.880302, 78.071498, 'Thiruparankundram, Madurai, Tamil Nadu 625005', NULL, 1.0);

