INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000042, 839002, 'Alagar Kovil (Kallazhagar Temple)', 'Alagar Kovil (Kallazhagar Temple)', 'A Vishnu temple at the foot of the Alagar hills, about 21 km northeast of Madurai, and one of the 108 Divya Desams. Lord Kallazhagar''s famous procession to the Vaigai river is the climax of Madurai''s Chithirai festival. The temple sits in a forested reserve with natural springs.', '1.5-2 hours', 'Morning', 'Combine with nearby Pazhamudhircholai (4 km away). Festival days in April-May are spectacular but crowded.', 'no', 'Tamil Nadu', 0, 0, '6:09 AM', '6:04 PM', 'Free', 5, 5, 10.074843, 78.213078, 'Alagarkoil, Madurai, Tamil Nadu 625301', 'https://alagarkoilkallalagar.hrce.tn.gov.in/', 1.0);

