INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000048, 839002, 'Amma Mess', 'Amma Mess', 'One of Madurai''s oldest non-vegetarian messes, tracing its roots to a 1936 street stall. Famous for mutton biryani, kola urundai, crab omelette, bone marrow omelette, rabbit roast and river-fish curries - the holy grail for Madurai meat lovers.', '45-60 minutes', 'Lunch 12-2 PM', 'Lunch is the main event; go early as popular dishes sell out. Non-veg only.', 'no', 'Tamil Nadu', 0, 0, '6:09 AM', '6:04 PM', NULL, 5, 5, 9.93227, 78.13427, '136, Alagar Kovil Main Road, Tallakulam, Madurai, Tamil Nadu 625002', NULL, 1.0);

