INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000049, 839002, 'Chandran Mess', 'Chandran Mess', 'A Madurai non-veg institution since 1963, famed for its ayirai meen kuzhambu (tiny river-fish curry), mutton kola urundai and nenju elumbu (goat ribs). Unpretentious dining halls with recipes reportedly unchanged for decades; slightly pricier than a typical mess.', '45 minutes', 'Lunch 12-2 PM', 'Lunch only (closes ~5 PM) - arrive by 1 PM before popular dishes run out.', 'no', 'Tamil Nadu', 0, 0, '6:09 AM', '6:04 PM', NULL, 4, 4, 9.936029, 78.143036, '19 P Vinayaga Nagar, KK Nagar 3rd Street, Opp. District Court, Tallakulam, Madurai, Tamil Nadu 625020', NULL, 0.8);

