INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000051, 839002, 'Meenakshi Bhavan', 'Meenakshi Bhavan', 'A classic old-style vegetarian restaurant on Town Hall Road, serving traditional Tamil meals on banana leaves - 2-3 curries, dal, sambar, rice, pickle, papad and a sweet - plus tiffin items like ven pongal and rava dosa at budget prices.', '30-45 minutes', 'Lunch 12-2 PM', 'The banana-leaf meals are the draw; evenings can be erratic - lunch is the safe bet.', 'no', 'Tamil Nadu', 0, 0, '6:09 AM', '6:04 PM', NULL, 3, 4, 9.91838, 78.11328, 'W496+G3M, Town Hall Road, Madurai, Tamil Nadu 625001', NULL, 0.68);

