INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000052, 839002, 'Konar Mess', 'Konar Mess', 'The birthplace of the Kari Dosa - invented here in the 1940s by butcher-turned-restaurateurs who layered dosa with egg and minced mutton. A cramped, legendary Simmakkal institution also known for brain fry, liver fry and mutton chukka.', '45-60 minutes', 'Dinner', 'It is an evening/night spot - go for dinner. Ask for the Kari Dosa; be ready to wait ~15 min.', 'no', 'Tamil Nadu', 0, 0, '6:09 AM', '6:04 PM', NULL, 5, 5, 9.92519, 78.12019, 'Simmakkal Road, Madurai, Tamil Nadu 625001', NULL, 1.0);

