INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8390006, 839, 839002, 'Chithirai Festival', 'April-May', 'Madurai''s grand month-long festival at the Meenakshi Amman Temple: the coronation of Goddess Meenakshi, her celestial wedding (Thirukalyanam) with Sundareswarar, the car procession, and the climax - Lord Kallazhagar entering the Vaigai river. Attracts millions of devotees.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8390007, 839, 839002, 'Teppam (Float) Festival', 'January-February', 'The float festival at Vandiyur Mariamman Teppakulam: the deities of Meenakshi and Sundareswarar are taken around the great temple tank on a decorated illuminated float.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8390008, 839, 839002, 'Jallikattu (Alanganallur)', 'January', 'The famous bull-taming sport held at Alanganallur near Madurai during the Pongal season - one of Tamil Nadu''s best-known traditional spectacles.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8390009, 839, 839002, 'Navaratri', 'September-October', 'Nine nights of goddess worship, celebrated grandly at the Meenakshi Amman Temple with Golu doll displays - a nod to Vilacheri''s doll-making tradition.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8390010, 839, 839002, 'Avanimoolam', 'August-September', 'Annual temple festival at the Meenakshi Amman Temple during the Tamil month of Avani.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8390011, 839, 839002, 'Karthigai Deepam', 'November-December', 'The festival of lights, celebrated across Madurai''s temples with rows of oil lamps - especially atmospheric at the hill temples.');

-- city: Coimbatore (id 1033)
INSERT OR IGNORE INTO cities (id, state_id, city_name, latitude, longitude) VALUES (839003, 839, 'Coimbatore', 11.0168, 77.0555);

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000053, 839003, 'Marudhamalai Subramaniyaswamy Temple', 'Marudhamalai Subramaniyaswamy Temple', 'Ancient hill temple of Lord Murugan atop 600-ft Marudhamalai hill, about 13-15 km from Coimbatore. One of the most visited Murugan shrines in the Kongu region, with panoramic views of the city and Western Ghats from the hilltop.', '2-3 hours', 'October-March; early morning for cooler climb', 'Take the temple bus from the foothills (around Rs 10) or climb the 1,000+ steps; steps close after 5 PM because of elephant movement in the area.', 'Not required; special darshan tickets (Rs 50) sold at the temple counter.', 'Tamil Nadu', 1, 0, '06:14', NULL, 'Free general entry; special darshan Rs 50; temple bus from foothills ~Rs 10', NULL, NULL, 11.0462, 76.8682, 'Arulmigu Subramanya Swami Thiru Kovil, Marudhamalai, Coimbatore 641046', NULL, NULL);

