INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000054, 839003, 'Perur Pateeswarar Temple', 'Perur Pateeswarar Temple', 'One of Coimbatore''s oldest temples, dedicated to Lord Shiva (Pateeswarar) and built around the 2nd century during the reign of Karikala Chola. Known for its Kanaka Sabha with a golden Nataraja statue, intricate stone sculptures, and its setting near the Noyyal river in Perur, about 7 km from the city.', '2 hours', 'October-March; festival time Panguni Uthiram (Mar-Apr)', 'Combine with a short walk to the Noyyal riverbank nearby; the temple is a hub during Aadi Perukku and Panguni Uthiram.', 'Not required.', 'Tamil Nadu', 0, 0, NULL, NULL, 'Free entry', NULL, NULL, 10.975849, 76.914789, '28, Siruvani Main Road, Perur, Coimbatore 641010', 'https://perurpatteeswarar.hrce.tn.gov.in', NULL);

