INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000055, 839003, 'Eachanari Vinayagar Temple', 'Eachanari Vinayagar Temple', 'Famous Ganesh temple on Pollachi Main Road, about 12 km from Coimbatore, housing a large 6-ft Vinayagar idol dating back to around 1500 AD. A traditional first stop for blessing new vehicles; the temple''s golden chariot (Thanga Ther) procession is a highlight.', '1-2 hours', 'Early morning; avoid festival rush days', 'New vehicles are blessed here daily, so parking can get busy around auspicious hours - arrive early.', 'Not required.', 'Tamil Nadu', 0, 0, NULL, NULL, NULL, NULL, NULL, 10.925, 76.99, 'Pollachi Main Road, Eachanari, Coimbatore 641021', NULL, NULL);

