INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000056, 839003, 'Koniamman Temple', 'Koniamman Temple', 'The guardian-deity temple of Coimbatore in the Town Hall/Raja Street area, tracing its origins to a 13th-century Irula shrine and expanded in the 18th century. The 84-ft rajagopuram completed in 2011 dominates the streetscape; the annual Ther Thiruvizha car festival in the Tamil month of Maasi (Feb-Mar) is a major city event.', '1 hour', 'February-March for the Ther Thiruvizha car festival', 'Pair with the heritage walk covering nearby Athar Jamaath Masjid and St Michael''s Church - all three sit within the old Town Hall quarter.', 'Not required.', 'Tamil Nadu', 0, 0, NULL, NULL, NULL, NULL, NULL, 10.9917, 76.9692, 'Raja Street, Town Hall, Coimbatore 641001', NULL, NULL);

