INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000057, 839003, 'Infant Jesus Church, Kovaipudur', 'Infant Jesus Church, Kovaipudur', 'Well-known parish church in Kovaipudur, about 12-13 km from the city centre, built in 1984 and famous for its Thursday novenas to Infant Jesus that draw devotees from across the Kongu region. Patronal feast on the second Sunday of January.', '1-2 hours', 'Thursday for the novena services', 'Thursday novena timings fill up early - reach well before the 11:30 AM or evening services.', 'Not required.', 'Tamil Nadu', 0, 0, NULL, NULL, NULL, NULL, NULL, 10.9456, 76.96, 'Kovaipudur, Coimbatore 641042', NULL, NULL);

