INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000066, 839003, 'Valankulam Lake & Boat House', 'Valankulam Lake and Boat House', 'Restored urban lake in the heart of the city (near Government Arts College Road), revamped under the Smart City project with walking paths, a boat house, floating decks and a children''s play area. A strong birdwatching spot (little grebes, purple moorhens, painted storks) with Western Ghats views at sunset.', '2-3 hours', 'Early morning for birds; evening for sunset views', 'Boating runs 10 AM-6 PM while the lake promenade opens earlier - plan boating after a morning walk.', 'Not required; boating tickets sold at the boat house counter.', 'Tamil Nadu', 0, 1, NULL, '18:08', 'Lake entry free; row boats Rs 50 per person for 20 minutes (pedal/motor boats extra)', NULL, NULL, 10.993994, 76.970963, '6, 1547/6, Government Arts College Road, Coimbatore 641018', NULL, NULL);

