INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000067, 839003, 'Adiyogi Statue & Isha Yoga Center', 'Adiyogi Statue and Isha Yoga Center', 'The 112-ft Adiyogi bust - a Guinness-record largest bust sculpture - at the Isha Yoga Center in the Velliangiri foothills, about 30-40 km from Coimbatore. The campus also houses the Dhyanalinga meditative space and Linga Bhairavi; the 3D Adiyogi Divya Darshanam light show plays daily at 7 PM.', 'Half day', 'October-March; stay for the 7 PM light show', 'Entry is free but expect long queues on weekends and full-moon days; the 7 PM Divya Darshanam show is the highlight - arrive by 6 PM for seating.', 'Not required; free entry. Paid cottages and programs bookable via Isha.', 'Tamil Nadu', 0, 1, NULL, '18:08', 'Free entry', NULL, NULL, 10.9757, 76.7381, 'Isha Yoga Center, Velliangiri Foothills, Semmedu Post, Coimbatore 641114', NULL, NULL);

