INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000069, 839003, 'Monkey Falls', 'Monkey Falls', '60-ft waterfall on the Pollachi-Valparai road near Aliyar, about 65 km from Coimbatore, named for the monkey troops around the site. A popular bathing and picnic stop on the way to Valparai; trekking in the surrounding forest needs forest-department permission.', '2-3 hours (as a stop en route to Valparai)', 'June-December, after rains', 'Carry a change of clothes if you plan to bathe; monkeys snatch food and bags - keep belongings zipped.', 'Not required for the falls; forest treks need permission ~2 weeks ahead via the Pollachi forest office.', 'Tamil Nadu', 0, 0, NULL, NULL, 'Rs 30-50 entry (sources conflict); parking ~Rs 50 per one listing', NULL, NULL, 10.8296, 76.9686, 'Pollachi-Valparai Road, near Aliyar, Coimbatore district 642101', NULL, NULL);

