INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000070, 839003, 'Aliyar Dam & Reservoir Park', 'Aliyar Dam and Reservoir Park', 'Picturesque dam at the foothills of the Valparai range, about 60-65 km from Coimbatore, inaugurated on 2 October 1962 by Jawaharlal Nehru. The landscaped garden below has a park, aquarium, mini theme park and boating - a standard picnic-and-bath stop on the Valparai route.', '2-3 hours', 'October-March; pleasant all day', 'Boating counters close before the park closes - do the boat ride first, then the garden.', 'Not required.', 'Tamil Nadu', 0, 0, NULL, NULL, '~Rs 10 entry per person, boating ~Rs 40 per trawell; other sources cite Rs 5 or free - conflict', NULL, NULL, 10.9956, 76.9644, 'Aliyar, Pollachi-Valparai Road, Coimbatore district 642101', NULL, NULL);

