INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8390012, 839, 839003, 'Thaipusam at Marudhamalai', 'January-February', 'The biggest festival at the Marudhamalai Murugan temple, drawing huge crowds of devotees to the hill shrine for kavadi processions and special pujas during the Tamil month of Thai.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8390013, 839, 839003, 'Koniamman Ther Thiruvizha', 'February-March', 'Coimbatore''s guardian-deity car festival in the Tamil month of Maasi, when the temple chariot rolls through Raja Street, Oppanakara Street, Vysial Street and Big Bazaar Street amid city-wide celebrations.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8390014, 839, 839003, 'Bannari Mariamman Kundam Festival', 'March-April', 'The famous fire-walking (Kundam) festival at the Bannari Mariamman Temple near Sathyamangalam (~65 km), held in the Tamil month of Panguni; lakhs of devotees attend and Erode district observes a local holiday.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8390015, 839, 839003, 'Panguni Uthiram at Perur Pateeswarar', 'March-April', 'The principal annual festival at the Perur Pateeswarar temple, celebrating the celestial wedding of Shiva and Parvati with processions and special abhishekams.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8390016, 839, 839003, 'Aadi Perukku', 'July-August', 'Monsoon water festival honouring the Noyyal river, observed on the riverbank near Perur with offerings of lamps and flowers as the river swells with the season''s rains.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8390017, 839, 839003, 'Karthigai Deepam', 'November-December', 'The festival of lamps, when rows of oil lamps are lit at Marudhamalai and temples across Coimbatore on the Karthigai full moon, mirroring the celebrations at Tiruvannamalai.');

-- city: Tiruchirappalli (id 1034)
INSERT OR IGNORE INTO cities (id, state_id, city_name, latitude, longitude) VALUES (839004, 839, 'Tiruchirappalli', 10.7905, 78.7047);

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000079, 839004, 'Rockfort Ucchi Pillayar Temple', 'Rockfort Ucchi Pillayar Temple', 'The Rockfort Ucchi Pillayar Temple crowns an 83-metre-high ancient rock in the heart of Tiruchirappalli, reached by a steep flight of rock-cut steps (reported as 344 by some sources and 427-437 by others). The summit shrine is dedicated to Lord Ganesha as Ucchi Pillayar; the rock is geologically among the oldest in the world and its lower slopes hold 7th-century Pallava rock-cut cave temples including the Thayumanavar shrine at its base. The climb is rewarded with sweeping views over the city, Srirangam island and the Cauvery river.', '1-2 hours', 'November to February, early morning or late afternoon; avoid the midday heat', 'Start the climb before 8 AM to beat the heat and the crowds; the summit viewpoint faces Srirangam and is best at sunrise.', 'no', 'Tamil Nadu', 1, 1, '6:04 AM', '6:07 PM', NULL, 5, 5, 10.8283, 78.6977, 'Rockfort, Chinna Kadai Street, Tiruchirappalli, Tamil Nadu 620002', NULL, 1.0);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (839000079, 839000079, '6:00 AM - 8:00 PM', '6:00 AM - 8:00 PM', '6:00 AM - 8:00 PM', '6:00 AM - 8:00 PM', '6:00 AM - 8:00 PM', '6:00 AM - 8:00 PM', '6:00 AM - 8:00 PM', 'Entry free; small pooja/coconut fees only. Climbing the steps takes 20-30 minutes; carry water.');

