INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 839000079, 'insert', 'bulk', 'Coords approximate from search results (geocoder does not resolve the summit shrine separately), flagged within ~1 km. Hours 6 AM-8 PM and free entry agreed across travel sources; step count conflicts (344 vs 427-437) flagged. Official site candidate trichyrockfort.tnhrce.in returned page-not-found - not kept. Sunrise/sunset times are approximate for late September in Trichy.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000080, 839004, 'Thayumanavar Temple (Rockfort Base)', 'Thayumanavar Temple', 'The Thayumanavar Temple sits at the base of the Rockfort, dedicated to Lord Shiva as Thayumanavar - ''he who became a mother'' - with Goddess Mattuvar Kuzhalammai. The 7th-century Pallava rock-cut cave shrine here predates the summit temple and is linked to the legend of Shiva arriving as the devotee''s mother. Pilgrims traditionally worship here before climbing to the Ucchi Pillayar shrine.', '45-60 minutes', 'November to February, mornings 7-10 AM', 'Combine with the Rockfort climb - the cave temple is on the way up and much cooler than the exposed summit steps.', 'no', 'Tamil Nadu', 0, 0, '6:04 AM', '6:07 PM', NULL, 4, 4, 10.82772, 78.6969, 'Rockfort, South Street, Devathanam, Tiruchirappalli, Tamil Nadu 620002', NULL, 0.8);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (839000080, 839000080, '6:00 AM - 12:00 PM, 4:00 PM - 8:00 PM', '6:00 AM - 12:00 PM, 4:00 PM - 8:00 PM', '6:00 AM - 12:00 PM, 4:00 PM - 8:00 PM', '6:00 AM - 12:00 PM, 4:00 PM - 8:00 PM', '6:00 AM - 12:00 PM, 4:00 PM - 8:00 PM', '6:00 AM - 12:00 PM, 4:00 PM - 8:00 PM', '6:00 AM - 12:00 PM, 4:00 PM - 8:00 PM', 'Morning and evening sessions; entry free. Usually visited together with the Rockfort climb.');

