INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000081, 839004, 'Sri Ranganathaswamy Temple, Srirangam', 'Sri Ranganathaswamy Temple, Srirangam', 'The Sri Ranganathaswamy Temple at Srirangam is the largest functioning Hindu temple complex in the world, spread over 156 acres with seven concentric prakarams and 21 gopurams. It is the foremost of the 108 Divya Desams, dedicated to Lord Ranganatha in a reclining posture on the Cauvery island of Srirangam. The 72-metre rajagopuram, rebuilt in 1987, is one of the tallest temple towers in Asia. The 21-day Vaikunta Ekadasi festival (December-January) is its biggest celebration.', '2-3 hours', 'November to February; visit 6-9 AM to see the Viswaroopa Seva', 'Non-Hindus cannot enter the innermost sanctum but can see the outer prakarams; arrive before 7 AM to avoid the ritual-break closures.', 'no', 'Tamil Nadu', 0, 0, '6:04 AM', '6:07 PM', NULL, 5, 5, 10.86042, 78.68995, 'South Uthira Street, Srirangam, Tiruchirappalli, Tamil Nadu 620006', 'https://srirangamranganathar.hrce.tn.gov.in/', 1.0);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (839000081, 839000081, '6:00 AM - 9:00 PM', '6:00 AM - 9:00 PM', '6:00 AM - 9:00 PM', '6:00 AM - 9:00 PM', '6:00 AM - 9:00 PM', '6:00 AM - 9:00 PM', '6:00 AM - 9:00 PM', 'Official HRCE timings: 6:00 AM-9:00 PM with breaks for rituals 7:15-9:00 AM, 12:30-2:15 PM and 5:30-7:00 PM. Entry free; special darshan and seva tickets available.');

