INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 839000081, 'insert', 'bulk', 'Official HRCE site srirangamranganathar.hrce.tn.gov.in fetched and verified (loads, belongs to the temple; timings from the site''s own text). Coords geocoded with exact-name match (relevance 100). Special-darshan/seva tickets can be booked in advance; advanced_booking left ''no'' per schema convention.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000082, 839004, 'Jambukeswarar Temple, Thiruvanaikaval', 'Jambukeswarar Temple, Thiruvanaikaval', 'The Jambukeswarar Temple at Thiruvanaikaval is one of the Pancha Bhoota Sthalas, representing the water element (Appu) - the sanctum houses a Shiva lingam perpetually moistened by an underground spring. Built by the Cholas around the 2nd century CE and later expanded, it is famed for the noon Uchikala puja when the priest dresses as Goddess Akilandeswari to worship Lord Jambukeswara. It is also a Divya Desam-adjacent major Shiva shrine near Srirangam.', '1-2 hours', 'November to February, mornings', 'Time your visit for the noon Uchikala puja - the goddess-dressing ritual is unique to this temple.', 'no', 'Tamil Nadu', 0, 0, '6:04 AM', '6:07 PM', NULL, 4, 5, 10.85383, 78.70384, 'North Ul Veethi, Thiruvanaikovil, Srirangam, Tiruchirappalli, Tamil Nadu 620005', 'https://thiruvanaikavaljambukeswarar.hrce.tn.gov.in/hrcehome/index_temple.php?tid=25706', 0.88);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (839000082, 839000082, '6:00 AM - 1:00 PM, 3:00 PM - 9:00 PM', '6:00 AM - 1:00 PM, 3:00 PM - 9:00 PM', '6:00 AM - 1:00 PM, 3:00 PM - 9:00 PM', '6:00 AM - 1:00 PM, 3:00 PM - 9:00 PM', '6:00 AM - 1:00 PM, 3:00 PM - 9:00 PM', '6:00 AM - 1:00 PM, 3:00 PM - 9:00 PM', '6:00 AM - 1:00 PM, 3:00 PM - 9:00 PM', 'Hours conflict across sources; 6 AM-1 PM and 3-9 PM is the best-supported version (gokshetra.com). Entry free.');

