INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 839000082, 'insert', 'bulk', 'Official HRCE page fetched and verified (tid=25706, loads, belongs to the temple). Coords geocoded with exact-name match (relevance 89). Hours conflict across sources (some say 5:30 AM-12:30 PM / 4-8:30 PM); used the gokshetra.com version with flag. Entry free.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000083, 839004, 'Amma Mandapam (Cauvery Ghat, Srirangam)', 'Amma Mandapam', 'Amma Mandapam is the principal bathing ghat of Srirangam on the southern bank of the Cauvery, the ritual gateway to the Ranganathaswamy Temple. Pilgrims bathe here before temple darshan, and it is the focal point of the Aadi Perukku river festival (July-August) when devotees offer flowers and lamps to the Cauvery. The ghat offers calm river views, especially at sunrise.', '30-45 minutes', 'Year-round at sunrise; July-August for Aadi Perukku', 'Come at sunrise for the quietest experience and to watch the temple priests perform the river rituals.', 'no', 'Tamil Nadu', 1, 0, '6:04 AM', '6:07 PM', NULL, 3, 4, 10.84694, 78.68981, 'Amma Mandapam Road, Srirangam, Tiruchirappalli, Tamil Nadu 620006', NULL, 0.68);

