INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000084, 839004, 'Our Lady of Lourdes Church', 'Our Lady of Lourdes Church', 'Our Lady of Lourdes Church on the St. Joseph''s College campus is a replica of the Basilica of Lourdes in France, built in 1895 by the Jesuits. Its soaring Gothic spires make it one of Trichy''s most distinctive colonial-era landmarks, set in manicured lawns in the heart of the city. It remains an active parish church and a popular stop on heritage walks.', '30-45 minutes', 'Year-round, mornings or late afternoons', 'Walk the church grounds in the late afternoon when the Gothic facade is lit by the low sun; dress modestly as it is an active place of worship.', 'no', 'Tamil Nadu', 0, 1, '6:04 AM', '6:07 PM', NULL, 3, 3, 10.82694, 78.6925, 'St. Joseph''s College Campus, Tiruchirappalli, Tamil Nadu 620002', NULL, 0.6);

