INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000085, 839004, 'Azhagiya Manavala Perumal Temple, Woraiyur', 'Azhagiya Manavala Perumal Temple, Woraiyur', 'The Azhagiya Manavala Perumal Temple in Woraiyur is one of the 108 Divya Desams, dedicated to Lord Vishnu as Azhagiya Manavalan (the beautiful bridegroom). Woraiyur was the early Chola capital, and this temple is one of the oldest Vishnu shrines in the region, set in a quiet neighbourhood away from the Srirangam crowds. Its annual Brahmotsavam is the local highlight.', '45-60 minutes', 'November to February, mornings', 'Combine with the nearby Vekkali Amman Temple in Woraiyur - both are walkable from the Woraiyur bus stand.', 'no', 'Tamil Nadu', 0, 0, '6:04 AM', '6:07 PM', NULL, 3, 4, 10.8269, 78.6734, 'Woraiyur, Tiruchirappalli, Tamil Nadu 620003', NULL, 0.68);

