INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000086, 839004, 'Tropical Butterfly Conservatory, Srirangam', 'Tropical Butterfly Conservatory', 'The Tropical Butterfly Conservatory on the outskirts of Srirangam is a 35-acre Tamil Nadu Forest Department park dedicated to butterflies, set inside a reserve forest. Glasshouses, host-plant gardens, a nakshatra vanam (star forest) and a children''s park make it a pleasant family outing. Over 120 butterfly species have been recorded here, and it pairs well with the nearby Srirangam temples.', '2-3 hours', 'October to March, mornings 9-11 AM when butterflies are most active', 'Visit on a sunny morning - butterflies are inactive on cloudy or rainy days; wear bright colours to attract them.', 'no', 'Tamil Nadu', 0, 0, '6:04 AM', '6:07 PM', NULL, 3, 4, 10.87785, 78.63805, 'Srirangam H O, Tiruchirappalli, Tamil Nadu 620101', NULL, 0.68);

