INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000087, 839004, 'Anna Science Centre-Planetarium', 'Anna Science Centre and Planetarium', 'The Anna Science Centre and Planetarium is Tamil Nadu''s best-known science museum outside Chennai, run by the Tamil Nadu Science and Technology Centre. It has interactive science galleries, a planetarium with daily sky shows in Tamil and English, a 3D theatre and an outdoor science park. It is a school-trip staple and a solid family stop on the Trichy-Madurai highway.', '2-3 hours', 'Year-round; arrive 30 minutes before a planetarium show', 'Check the planetarium show language and timing at the ticket counter before touring the galleries.', 'no', 'Tamil Nadu', 0, 0, '6:04 AM', '6:07 PM', 'Rs 45', 3, 3, 10.76899, 78.70387, 'Panjapur, Trichy-Madurai Highway, Tiruchirappalli, Tamil Nadu 620012', NULL, 0.6);

