INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000088, 839004, 'Government Museum (Rani Mangammal Mahal)', 'Government Museum, Tiruchirappalli', 'The Government Museum of Tiruchirappalli is housed in the Rani Mangammal Mahal, a 17th-century Nayak palace near the Rockfort. Its galleries cover Chola bronzes, stone sculptures, coins, tribal artefacts, geology and the region''s natural history. It is a compact, uncrowded museum that pairs naturally with a Rockfort visit.', '1-2 hours', 'Year-round, mornings', 'Do the museum right after the Rockfort climb - it is a 5-minute walk and the air-conditioned galleries are a good midday break.', 'no', 'Tamil Nadu', 0, 0, '6:04 AM', '6:07 PM', 'Rs 5', 3, 3, 10.8214, 78.69267, 'Rani Mangammal Mahal, near Rockfort, Tiruchirappalli, Tamil Nadu 620002', NULL, 0.6);

