INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000089, 839004, 'Main Guard Gate', 'Main Guard Gate', 'The Main Guard Gate is a colonial-era stone gateway near the Teppakulam, one of the surviving fragments of Trichy''s old fortifications. It is a view-only streetscape landmark - visitors photograph it from the road while walking between the Rockfort, the Teppakulam tank and the Lourdes Church.', '10-15 minutes', 'Year-round, as part of a Rockfort-area walk', 'A quick photo stop, not a destination - combine with the Teppakulam and the Rockfort base temples on foot.', 'no', 'Tamil Nadu', 0, 0, '6:04 AM', '6:07 PM', NULL, 2, 2, 10.8265, 78.69, 'Main Guard Gate, NSB Road, Tiruchirappalli, Tamil Nadu 620002', NULL, 0.4);

