INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000090, 839004, 'Vekkali Amman Temple, Woraiyur', 'Vekkali Amman Temple, Woraiyur', 'The Vekkali Amman Temple in Woraiyur is one of Trichy''s most popular Amman shrines, dedicated to Goddess Vekkali - a fierce form of Parvati. Friday evenings and the Tamil month of Aadi see the heaviest crowds, when devotees offer pongal and perform angapradakshinam. It is the religious heart of the old Woraiyur quarter, the early Chola capital.', '45-60 minutes', 'Fridays and the Tamil month of Aadi (July-August); early mornings', 'Avoid Friday evenings if you dislike crowds - the temple is packed then; weekday mornings are calm.', 'no', 'Tamil Nadu', 0, 0, '6:04 AM', '6:07 PM', NULL, 3, 3, 10.82801, 78.67679, 'Woraiyur, Tiruchirappalli, Tamil Nadu 620003', NULL, 0.6);

