INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000091, 839004, 'Erumbeeswarar Temple, Thiruverumbur', 'Erumbeeswarar Temple, Thiruverumbur', 'The Erumbeeswarar Temple at Thiruverumbur, about 13-14 km east of central Trichy, is a 9th-century Chola Shiva temple on a small hillock - one of the region''s oldest surviving Chola shrines. Its Dravidian architecture and hilltop setting make it a rewarding short excursion, far less crowded than the city temples. The climb is short and the views stretch over the surrounding plains.', '1-1.5 hours', 'November to February, mornings; ~13-14 km / 30 min from central Trichy', 'Go at opening for soft light on the hilltop vimana and the empty courtyard; auto-rickshaws from central Trichy take about 30 minutes.', 'no', 'Tamil Nadu', 1, 1, '6:04 AM', '6:07 PM', NULL, 3, 4, 10.79197, 78.76776, 'Thiruverumbur, Tiruchirappalli, Tamil Nadu 620013', NULL, 0.68);

