INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000092, 839004, 'Mariamman Teppakulam (Trichy Tank)', 'Mariamman Teppakulam', 'The Mariamman Teppakulam is the large temple tank near the Rockfort, the venue of Trichy''s famous Teppam (float) festival when the goddess is taken on a decorated raft across the illuminated water. Outside festival season it is a calm, photogenic water body ringed by streets, best appreciated at sunrise or sunset as part of a Rockfort-area walk.', '30-45 minutes', 'Sunrise or sunset; January-April if you want the float festival', 'Walk the tank bund at sunset for the best light on the water; confirm float-festival dates locally as sources disagree.', 'no', 'Tamil Nadu', 1, 1, '6:04 AM', '6:07 PM', NULL, 3, 3, 10.8285, 78.6915, 'Teppakulam, near Rockfort, Tiruchirappalli, Tamil Nadu 620002', NULL, 0.6);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (839000092, 839000092, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Public temple tank; no published hours or entry fee - viewable from the surrounding streets at any daylight hour. The float festival timing is disputed across sources (January-February vs Panguni, March-April).');

