INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000093, 839004, 'Kallanai (Grand Anicut) (day trip)', 'Kallanai (Grand Anicut)', 'Kallanai, the Grand Anicut, is a 2,000-year-old dam across the Cauvery built by Chola king Karikalan around the 2nd century CE - one of the oldest water-diversion structures in the world still in use. The site offers river views, a small park and the spectacle of the Cauvery splitting into its delta branches. It lies about 15-20 km east of Trichy on the road toward Thanjavur.', '1-2 hours', 'October to February, mornings; ~15-20 km / 40 min from Trichy', 'Combine with the Srirangam temples on the way back - the anicut is a 30-40 minute detour east of the city.', 'no', 'Tamil Nadu', 1, 1, '6:04 AM', '6:07 PM', NULL, 4, 4, 10.8302, 78.8187, 'Kallanai, Thanjavur District, Tamil Nadu 614019', NULL, 0.8);

