INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000094, 839004, 'Samayapuram Mariamman Temple (day trip)', 'Samayapuram Mariamman Temple', 'The Samayapuram Mariamman Temple, about 15-20 km north of Trichy on the Chennai highway, is one of Tamil Nadu''s most powerful and crowded Amman shrines. Devotees believe the goddess cures diseases, and the temple draws lakhs during the Chithirai Brahmotsavam and the Thai Poosam festivals. General darshan is free; a special darshan ticket (Rs 100) shortens the long queues.', '1-2 hours', 'Weekday mornings; avoid festival days if you dislike crowds; ~15-20 km / 30 min from Trichy', 'Buy the Rs 100 special darshan ticket on weekends and festival days - the free queue can take hours.', 'no', 'Tamil Nadu', 0, 0, '6:04 AM', '6:07 PM', NULL, 4, 4, 10.9186, 78.73889, 'S. Kannanur, Manachanallur, Tiruchirappalli, Tamil Nadu 621112', NULL, 0.8);

