INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000095, 839004, 'Mukkombu (Upper Anaicut) (day trip)', 'Mukkombu (Upper Anaicut)', 'Mukkombu, the Upper Anaicut, is a 19th-century British-built regulator dam across the Cauvery about 18 km west of Trichy, where the river splits into the Cauvery and the Kollidam. The site has a small park, a children''s play area and river views, and is a favourite local picnic spot - best in the monsoon and post-monsoon months when the sluices run full.', '2-3 hours', 'October to February when the river is full; ~18 km / 40 min from Trichy', 'Go after the northeast monsoon (November-January) when the sluice gates are open and the river is at its most dramatic.', 'no', 'Tamil Nadu', 0, 1, '6:04 AM', '6:07 PM', NULL, 3, 4, 10.88198, 78.57813, 'Mukkombu, Tiruchirappalli District, Tamil Nadu 639115', NULL, 0.68);

