INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000096, 839004, 'Viralimalai Murugan Temple and Peacock Sanctuary (day trip)', 'Viralimalai Murugan Temple', 'The Viralimalai Murugan Temple sits atop a granite hill about 28 km south of Trichy, dedicated to Lord Murugan as Subramanya. The hill is also a protected peacock sanctuary - peacocks roam the temple courtyards freely, and the climb passes through their habitat. The temple''s official HRCE page lists darshan from 6 AM to noon and 4 to 8 PM, and the hilltop gives wide views over the surrounding plains.', '2-3 hours', 'November to February, mornings for peacock sightings; ~28 km / 45 min from Trichy', 'Climb early in the morning when peacocks are most active around the steps; carry binoculars.', 'no', 'Tamil Nadu', 1, 1, '6:04 AM', '6:07 PM', NULL, 4, 4, 10.6027911, 78.5454032, 'Viralimalai, Pudukkottai District, Tamil Nadu 621316', 'https://hrce.tn.gov.in/hrcehome/index_temple.php?tid=25691', 0.8);

