INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 839000096, 'insert', 'bulk', 'Official HRCE page (tid=25691) fetched and verified with official timings 6-12 / 4-8. Coords from a search-result map listing, flagged approximate within ~1 km. Peacock sanctuary status widely documented. ~28 km south of Trichy - day trip #4 of 6 within 100 km.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000097, 839004, 'Sittanavasal Caves (day trip)', 'Sittanavasal Jain Caves', 'Sittanavasal, about 46-55 km from Trichy, is a 2nd-century BCE Jain rock-cut cave complex - the Arivar Koil - with some of the oldest surviving fresco paintings in South India. The caves, built by Jain monks and later patronised by the Pandyas, hold exquisite ceiling murals of lotus ponds and dancing figures. It is one of Tamil Nadu''s most important Jain heritage sites and an ASI-protected monument.', 'Half day (2-3 hours at the site)', 'November to February, mornings; ~46-55 km / 1.5 hrs from Trichy', 'Bring a torch - the cave interiors are dim and the frescoes reward close looking; photography rules are posted at the gate.', 'no', 'Tamil Nadu', 0, 0, '6:04 AM', '6:07 PM', NULL, 4, 4, 10.4558, 78.7251, 'Sittanavasal, Pudukkottai District, Tamil Nadu 622104', NULL, 0.8);

