INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000098, 839004, 'Puliyancholai Falls (day trip)', 'Puliyancholai Falls', 'Puliyancholai is a forested waterfall and stream at the foothills of the Kolli Hills, about 72-76 km from Trichy - chosen over the Kolli Hills themselves, which lie beyond the 100 km day-trip limit. A shallow stream runs through shady woods with small cascades, making it a popular local picnic and bathing spot. There is no formal entry system; the site is best visited in daylight during the post-monsoon months.', 'Half day to full day', 'October to February, mornings; ~72-76 km / 2 hrs from Trichy', 'Carry swimwear and a change of clothes - the stream pools are the main attraction; avoid the monsoon peak when currents are strong.', 'no', 'Tamil Nadu', 1, 0, '6:04 AM', '6:07 PM', NULL, 3, 4, 11.21886, 78.60615, 'Puliyancholai, Turaiyur Taluk, Tiruchirappalli District, Tamil Nadu 621002', NULL, 0.68);

