INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000099, 839004, 'Shri Sangeethas - Thillai Nagar', 'Shri Sangeethas, Thillai Nagar', 'Shri Sangeethas in Thillai Nagar is one of Trichy''s best-known pure-vegetarian restaurants, famous for its South Indian meals, crisp dosas and filter coffee. The Thillai Nagar branch is centrally located and runs long hours from early morning to late night, making it a reliable breakfast-through-dinner stop. Prices are moderate (around Rs 500 for two per listing sites).', '45-60 minutes', 'Breakfast 7-9 AM or lunch 12-2 PM', 'The ghee roast and the meals (served on banana leaf at lunch) are the orders to go for.', 'no', 'Tamil Nadu', 0, 0, '6:04 AM', '6:07 PM', NULL, 4, 4, 10.826428, 78.685058, 'B1, 1st Cross, Thillai Nagar Road, Tiruchirappalli, Tamil Nadu 620018', NULL, 0.8);

