INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000100, 839004, 'Vasanta Bhavan - NSB Road, Teppakulam', 'Vasanta Bhavan, NSB Road', 'Vasanta Bhavan on NSB Road near the Teppakulam is a long-running pure-vegetarian restaurant in the heart of the old city, a short walk from the Rockfort. It serves South Indian tiffin, meals and sweets at budget prices (around Rs 400 for two per listing sites), and is a favourite with pilgrims doing the Rockfort-Srirangam temple circuit.', '45 minutes', 'Breakfast or lunch; convenient between Rockfort and Srirangam visits', 'Eat here between the Rockfort climb and the Teppakulam walk - it is the closest good veg meal to the old-city sights.', 'no', 'Tamil Nadu', 0, 0, '6:04 AM', '6:07 PM', NULL, 3, 4, 10.826677, 78.69498, 'Opposite Rathna Store, NSB Road, Teppakulam, Tiruchirappalli, Tamil Nadu 620002', NULL, 0.68);

