INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000101, 839004, 'Banana Leaf - Madurai Road', 'Banana Leaf Restaurant', 'Banana Leaf on Madurai Road (near Holy Cross College) is a popular multi-cuisine restaurant serving South Indian, North Indian and Chinese dishes. It is a family-friendly mid-range option in central Trichy with long lunch-to-late-night hours. Both vegetarian and non-vegetarian dishes are served.', '1-1.5 hours', 'Lunch 12-3 PM or dinner 7-10 PM', 'Good fallback for mixed veg/non-veg groups - the menu covers South Indian, North Indian and Chinese.', 'no', 'Tamil Nadu', 0, 0, '6:04 AM', '6:07 PM', NULL, 3, 3, 10.826496, 78.692445, 'Near Holy Cross College, Madurai Road, Tiruchirappalli, Tamil Nadu 620002', NULL, 0.6);

