INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000102, 839004, 'Adyar Ananda Bhavan - Woraiyur (Twin Towers)', 'Adyar Ananda Bhavan, Woraiyur', 'Adyar Ananda Bhavan (A2B) at Twin Towers, Woraiyur is the Trichy outlet of Tamil Nadu''s giant pure-vegetarian chain, serving South Indian tiffin, meals and an extensive sweets-and-savouries counter. The official A2B site lists outlet hours as 7 AM to 10 PM, Monday to Sunday. It is a dependable budget stop for meals plus take-home sweets like Mysore pak.', '45 minutes', 'Breakfast or evening tiffin; lunch for the meals', 'Stock up at the sweets counter - the ghee Mysore pak and mixture travel well.', 'no', 'Tamil Nadu', 0, 0, '6:04 AM', '6:07 PM', NULL, 3, 4, 10.830311, 78.685876, '14, Twin Towers, Annamalai Nagar, Karur Bypass Road, Woraiyur, Tiruchirappalli, Tamil Nadu 620003', 'https://a2b.world/', 0.68);

