INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000103, 839004, 'Ezham Suvai - Cantonment', 'Ezham Suvai, Cantonment', 'Ezham Suvai in Cantonment is a well-regarded pure-vegetarian restaurant known for traditional Tamil Nadu meals and tiffin, with the Collector''s Office Road address confirmed on its official website. It runs 7 AM to 11 PM and is priced in the mid range, popular with both locals and visitors staying in the Cantonment area.', '45-60 minutes', 'Lunch for the traditional meals; evenings for tiffin', 'Order the full traditional meals at lunch - it is the restaurant''s strongest offering.', 'no', 'Tamil Nadu', 0, 0, '6:04 AM', '6:07 PM', NULL, 3, 4, 10.80166, 78.67473, '9, Collector''s Office Road, Cantonment, Tiruchirappalli, Tamil Nadu 620001', 'http://www.ezhamsuvai.com/', 0.68);

