INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000104, 839004, 'Hotel Kannappa - Mannarpuram', 'Hotel Kannappa, Mannarpuram', 'Hotel Kannappa at Mannarpuram is the Trichy branch of the well-known Chettinad restaurant chain (since 2002), serving fiery Chettinad chicken, mutton and seafood preparations plus biryanis. The official site confirms the Mannarpuram branch and 100% halal sourcing. It adds a non-vegetarian option to the city''s restaurant set, at moderate prices, open 11:30 AM to 11 PM.', '1-1.5 hours', 'Lunch 12-3 PM or dinner 7-10 PM', 'The Chettinad pepper chicken and the biryani are the signature orders; the food is genuinely spicy.', 'no', 'Tamil Nadu', 0, 0, '6:04 AM', '6:07 PM', NULL, 3, 4, 10.785349, 78.688942, '22-25, Mannarpuram Tollgate Service Road, Tiruchirappalli, Tamil Nadu 620009', 'http://www.hotelkannappa.com/', 0.68);

