INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8390018, 839, 839004, 'Vaikunta Ekadasi, Srirangam', 'December-January', 'The most important festival at the Sri Ranganathaswamy Temple in Srirangam, celebrated over 21 days in the Tamil month of Margazhi. Lakhs of devotees throng the temple to pass through the Paramapada Vasal (Gate of Paradise), which is opened for this occasion. It is one of the largest Vaishnavite festivals in South India.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8390019, 839, 839004, 'Rockfort Teppam (Float Festival), Teppakulam', 'January-April', 'The float festival at the Mariamman Teppakulam in Tiruchirappalli, when the temple deity is taken on a decorated raft around the illuminated tank. Sources conflict on the exact timing (January-February vs the Tamil month of Panguni, March-April) - treat the window as approximate.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8390020, 839, 839004, 'Samayapuram Chithirai Brahmotsavam and Poochoriyal', 'February-April', 'The Chithirai Brahmotsavam at the Samayapuram Mariamman Temple is one of the temple''s biggest annual festivals, drawing lakhs of pilgrims. The Poochoriyal flower festival in the Tamil month of Masi (February-March) precedes it, when devotees shower the goddess with flowers.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8390021, 839, 839004, 'Thai Poosam', 'January-February', 'The 11-day Thai Poosam festival, celebrated at Murugan temples including Viralimalai and at Samayapuram, when devotees carry kavadi offerings in fulfilment of vows. Temple streets fill with processions and folk performances.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8390022, 839, 839004, 'Jambukeswarar Panguni Brahmotsavam', 'March-April', 'The annual Brahmotsavam at the Jambukeswarar Temple in Thiruvanaikaval during the Tamil month of Panguni, featuring a grand temple car (ther) procession around the Mada streets of this Pancha Bhoota Sthala.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8390023, 839, 839004, 'Aadi Perukku', 'July-August', 'The monsoon festival honouring the Cauvery river, celebrated on the 18th of the Tamil month of Aadi when the river traditionally swells with fresh water. Devotees gather at the Amma Mandapam ghat in Srirangam to offer flowers, lamps and sweet rice to the river.');

-- city: Kanyakumari (id 1035)
