INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000105, 839005, 'Vivekananda Rock Memorial', 'Vivekananda Rock Memorial', 'Kanyakumari''s signature landmark — a rock island memorial 500 m off the mainland where Swami Vivekananda meditated in 1892. Reached only by ferry from the mainland jetty. The memorial has the meditation hall (Dhyana Mandapam), Sripada Mandapam with the goddess''s footprint, and Sabhamandapam. The Vivekananda Kendra runs an official online darshan-coupon booking site. Advance online booking is recommended because ferry queues are long in season.', '2-3 hours', 'October to March; early morning slots have shorter ferry queues', 'Book the darshan coupon online at darshanam.vrmvk.org before you go — entry is subject to ferry availability. Carry water and sun protection; the rock is exposed and hot at midday.', 'yes', 'Tamil Nadu', 1, 1, '6:08 AM', '6:10 PM', 'Ferry ticket Rs 100 standard / Rs 300 priority + Rs 30 memorial entry (per kanyakumaritourism.in)', 10, 9, 8.078131, 77.555272, 'Jetty, Kanyakumari, Tamil Nadu 629702', 'https://darshanam.vrmvk.org/', 1.92);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (839000105, 839000105, '8:00 AM - 4:00 PM', '8:00 AM - 4:00 PM', '8:00 AM - 4:00 PM', '8:00 AM - 4:00 PM', '8:00 AM - 4:00 PM', '8:00 AM - 4:00 PM', '8:00 AM - 4:00 PM', 'Official darshanam site states VRM Darshanam hours 8:00 AM-4:00 PM, entry gate closes 20 min before closing; multiple sources agree');

