INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 839000105, 'insert', 'bulk', 'Coordinates from meta.ai search result (8.078131, 77.555272). Official website fetched 2026-09-30 and verified as belonging to the Vivekananda Kendra''s darshanam/booking service. Hours confirmed on the official site itself. Prices from kanyakumaritourism.in only, not from an official tariff page.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000106, 839005, 'Thiruvalluvar Statue', 'Thiruvalluvar Statue', 'A 133-foot stone statue (95-foot statue on a 38-foot pedestal) of the Tamil poet-philosopher Thiruvalluvar, author of the Thirukkural, standing on a rock islet next to the Vivekananda Rock Memorial. Sculpted by Dr. V. Ganapati Sthapati and unveiled on 1 January 2000. Reached by the same ferry as the Rock Memorial; there is no separate entry ticket.', '30-45 minutes', 'October to March; morning for clear views', 'Combine with the Vivekananda Rock Memorial ferry trip. Climb the pedestal base for panoramic views of the three seas meeting.', 'yes', 'Tamil Nadu', 1, 1, '6:08 AM', '6:10 PM', 'Included in the same ferry ticket as the Vivekananda Rock Memorial (Rs 100 standard / Rs 300 priority per kanyakumaritourism.in); no separate entry fee', 9, 8, 8.0772, 77.5545, 'Rock islet off the Kanyakumari shore, Kanyakumari, Tamil Nadu 629702', NULL, 1.72);

