INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000107, 839005, 'Kumari Amman Temple', 'Devi Kanyakumari (Bhagavathy Amman) Temple', 'The ancient Shakti Peetha temple dedicated to the virgin goddess Kanyakumari (Bhagavathy Amman), from whom the town takes its name. One of the 51 Shakti Peethas, overlooking the sea where the three waters meet. Men must remove upper garments before entering the sanctum area. The temple is the focal point of the Chitra Pournami and Navaratri festivals.', '1-2 hours', 'October to March; attend early morning aarti', 'Men must remove shirts/upper garments; dress conservatively. Go before 8 AM to avoid long darshan queues in peak season.', 'no', 'Tamil Nadu', 0, 0, '6:08 AM', '6:10 PM', NULL, 10, 8, 8.0848, 77.5497, '12/1 Temple Rd, Kanyakumari, Tamil Nadu 629702', NULL, 1.84);

