INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000108, 839005, 'Gandhi Memorial Mandapam', 'Gandhi Memorial Mandapam (Gandhi Mandapam)', 'Memorial built in 1956 where Mahatma Gandhi''s ashes were kept for public viewing before immersion at the sea. Built in Odisha-style architecture with a 79-foot central spire, designed so that on Gandhi''s birthday (2 October) the sun''s rays fall on the exact spot where the urn was placed. Entry is free.', '30-45 minutes', 'October to March; mornings', 'The open central hall and sea-facing location make it a peaceful photo stop. Combine with the nearby Kamarajar Mani Mandapam and Tsunami Memorial.', 'no', 'Tamil Nadu', 0, 1, '6:08 AM', '6:10 PM', 'Free entry', 8, 7, 8.078734, 77.549948, 'NH 44, Kanyakumari, Tamil Nadu 629702', NULL, 1.52);

