INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000109, 839005, 'Kamarajar Mani Mandapam', 'Kamarajar Mani Mandapam', 'Memorial dedicated to K. Kamarajar, former Chief Minister of Tamil Nadu and ''Kingmaker'' of Indian politics. Opened on 2 October 2000. Located adjacent to the Gandhi Memorial Mandapam near the shore, with exhibits on his life and contributions. Entry is free.', '30 minutes', 'October to March; mornings', 'Visit together with the Gandhi Memorial Mandapam next door and the Tsunami Memorial a short walk away.', 'no', 'Tamil Nadu', 0, 1, '6:08 AM', '6:10 PM', 'Free entry', 6, 6, 8.0793, 77.5507, 'Near Gandhi Memorial Mandapam, Kanyakumari, Tamil Nadu 629702', NULL, 1.2);

