INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000110, 839005, 'Our Lady of Ransom Church', 'Our Lady of Ransom Church (Alayal Matha Church)', 'Historic Catholic church on Church Road overlooking the sea. The site traces to a grotto visited by St. Francis Xavier in 1542; the present church was rebuilt in 1700 AD. Its notable feature is a statue of Mother Mary depicted in a sari, reflecting local culture. Weekday Mass is at 6:15 AM.', '30-45 minutes', 'October to March; attend morning Mass', 'The church terrace and surroundings offer good sea views. Dress modestly; keep silence during services.', 'no', 'Tamil Nadu', 1, 0, '6:08 AM', '6:10 PM', 'Free entry', 7, 7, 8.085591, 77.552288, 'Church Rd, Kanyakumari, Tamil Nadu 629702', NULL, 1.4);

