INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000111, 839005, 'Kanyakumari Beach', 'Kanyakumari Beach (Triveni Sangam)', 'The famous beach at India''s southern tip where the Arabian Sea, Bay of Bengal and Indian Ocean are said to meet (Triveni Sangam). Known for multi-coloured sand and the holy confluence waters where pilgrims bathe. It is one of the rare places in India where sunrise and sunset can both be seen over the sea.', '1-2 hours', 'Sunrise and sunset; October to March for weather', 'Swimming is dangerous here due to strong currents and rocks — wade only at the edges. Sunrise over the sea is as famous as the sunset.', 'no', 'Tamil Nadu', 1, 1, '6:08 AM', '6:10 PM', 'Free entry', 9, 8, 8.0785, 77.5545, 'Beach Rd, Kanyakumari, Tamil Nadu 629702', NULL, 1.72);

