INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000112, 839005, 'Sunset Point', 'Sunset View Point, Kanyakumari', 'Kanyakumari''s celebrated sunset viewpoint on the west shore, famous because the sun sets directly over the sea — a rarity on India''s east coast. The best window is roughly 5:30-6:30 PM. The promontory area has a view tower and promenade; it gets crowded on clear evenings.', '1 hour', '5:30-6:30 PM, October to March', 'Arrive by 5:15 PM to get a good spot; clear winter evenings give the best colours. Early-morning sunrise viewing happens from the main beach side.', 'no', 'Tamil Nadu', 0, 1, '6:08 AM', '6:10 PM', 'Free entry', 9, 9, 8.0786, 77.5455, 'West shore promenade, Kanyakumari, Tamil Nadu 629702', NULL, 1.8);

