INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000113, 839005, 'Tsunami Memorial Monument', 'Tsunami Memorial Monument', 'A 16-foot steel memorial near the south shore honouring the victims of the 26 December 2004 Indian Ocean tsunami that devastated the Kanyakumari coast. The sculpture depicts one hand holding back a giant wave while the other cups a lamp of hope. A sombre 10-15 minute stop near the Gandhi Memorial.', '15 minutes', 'Any time; October to March for weather', 'Combine with the Gandhi Memorial Mandapam and Kamarajar Mani Mandapam, all within walking distance.', 'no', 'Tamil Nadu', 0, 0, '6:08 AM', '6:10 PM', 'Free entry', 6, 6, 8.0785, 77.5495, 'Kovalam Beach Rd, near Gandhi Memorial, Kanyakumari, Tamil Nadu 629702', NULL, 1.2);

