INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000114, 839005, 'Mayapuri Wonder Wax Museum', 'Mayapuri Wonder Wax Museum', 'Kanyakumari''s wax museum on Cape Road near the railway station, featuring lifelike wax figures of Indian and international celebrities alongside a 3D art gallery. A popular family stop; VR experiences are offered separately. Address and phone confirmed on the venue''s own website.', '1-1.5 hours', 'Midday or evening; October to March', 'The combined ticket covers the wax museum and 3D art gallery; VR is charged separately. Good for kids and photo fun.', 'no', 'Tamil Nadu', 0, 0, '6:08 AM', '6:10 PM', 'Rs 120 combined ticket (wax museum + 3D art); VR rides ~Rs 400 separate (per airial.travel)', 6, 7, 8.087613, 77.549076, 'Cape Rd, near Railway Station, Kanyakumari, Tamil Nadu 629702', 'https://mayapuriwaxmuseum.com/', 1.28);

