INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000115, 839005, 'Kanyakumari Lighthouse', 'Kanyakumari Lighthouse', 'Working lighthouse on the Kanyakumari beachfront with a glass elevator to the top, offering panoramic views of the shoreline, the rock memorials and the sea confluence. Open in morning and afternoon slots. Entry is a nominal ticket.', '45 minutes - 1 hour', 'Late afternoon slot for sunset views; October to March', 'Time your visit for the 3-6 PM slot to catch sea views in good light. Photography from the top is the main draw.', 'no', 'Tamil Nadu', 0, 1, '6:08 AM', '6:10 PM', 'Rs 15 adult / Rs 5 child (airial.travel; one review reports Rs 10 — conflict noted)', 6, 7, 8.0789, 77.5486, 'Beach Rd, near the shore, Kanyakumari, Tamil Nadu 629702', NULL, 1.28);

