INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000116, 839005, 'Chothavilai Beach', 'Chothavilai Beach', 'A quiet, less-commercialised beach about 10 km from Kanyakumari town, known for shallow waters and sand dunes. Popular with locals for evening outings and sunset views. Swimming is discouraged because of undercurrents; it is more a relaxation and photography spot than a swimming beach.', '1-2 hours', 'Late afternoon for sunset; October to March', 'Do not swim here — undercurrents are dangerous. Carry your own food and water as facilities are minimal.', 'no', 'Tamil Nadu', 0, 1, '6:08 AM', '6:10 PM', 'No entry fee reported', 5, 6, 8.1178, 77.523, 'Chothavilai, Kanyakumari district, Tamil Nadu (approx 10 km from Kanyakumari town)', NULL, 1.08);

