INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000117, 839005, 'Padmanabhapuram Palace', 'Padmanabhapuram Palace', 'A 16th-century wooden palace at Thuckalay, about 30 km from Kanyakumari — the former capital of the Travancore kingdom. Celebrated for its Kerala-style wooden architecture, mural paintings and antique interiors. Timings and entry fees are published on the Kerala Tourism destination page; closed on Mondays.', '2-3 hours', 'October to March; arrive for the 9 AM opening', 'Closed on Mondays and public holidays. The morning slot (9 AM-12:30 PM) is less rushed; hire the audio or local guide at the entrance for context.', 'no', 'Tamil Nadu', 0, 0, '6:08 AM', '6:10 PM', 'Rs 50 Indian adult / Rs 500 foreign adult; Rs 10 Indian child / Rs 100 foreign child (per keralatourism.org)', 8, 9, 8.2583, 77.3247, 'Padmanabhapuram, Thuckalay, Kanyakumari district, Tamil Nadu 629175 (approx 30 km from Kanyakumari)', NULL, 1.68);

