INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000118, 839005, 'Suchindram Temple', 'Thanumalayan (Suchindram) Temple', 'Famous Hindu temple at Suchindram, 11-13 km from Kanyakumari, dedicated to the trimurti as Sthanumalayan — Shiva, Vishnu and Brahma in a single shrine. Renowned for its musical pillars, the Hanuman shrine, and the towering gopuram. Entry is free; men must remove upper garments, a strict dress code applies.', '1.5-2 hours', 'October to March; early morning darshan', 'Men must remove shirts before entering; wear a dhoti or modest clothing. Ask the priest to demonstrate the musical pillars. Photography is restricted inside.', 'no', 'Tamil Nadu', 0, 0, '6:08 AM', '6:10 PM', 'Free entry (darshan free; special poojas charged separately at the counter)', 9, 9, 8.154881, 77.463188, 'North St, Suchindram, Tamil Nadu 629704 (approx 12 km from Kanyakumari)', NULL, 1.8);

