INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000119, 839005, 'Vattakottai Fort', 'Vattakottai Fort', 'An 18th-century circular granite seaside fort built by the Travancore kingdom, about 6-7 km from Kanyakumari. Set on a hilltop with commanding views of the sea, it sits next to a quiet black-sand beach. A good picnic and photography spot; the sea breeze is strong at the ramparts.', '1-1.5 hours', 'Late afternoon for sea views; October to March', 'Combine with Chothavilai Beach nearby. Carry water — there are few shops at the fort. The adjacent black-sand beach is the real highlight.', 'no', 'Tamil Nadu', 0, 1, '6:08 AM', '6:10 PM', NULL, 7, 7, 8.1313, 77.5389, 'Vattakottai, Kanyakumari district, Tamil Nadu (approx 7 km from Kanyakumari town)', NULL, 1.4);

