INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000120, 839005, 'Mathur Aqueduct', 'Mathur Aqueduct (Mathoor Hanging Trough)', 'One of South Asia''s longest and tallest aqueducts, built in 1966 under K. Kamarajar to carry irrigation water across a valley. About 48-50 km from Kanyakumari at Aruvikkarai — roughly 1 km long, 115 feet high, supported on 28 massive pillars. You can walk across the trough on the footpath for sweeping valley views.', '1-2 hours', 'Morning or late afternoon; October to March', 'Walk the full length of the trough for the best views; wear good footwear. It is a full day trip from Kanyakumari — combine with Thirparappu Falls.', 'no', 'Tamil Nadu', 0, 0, '6:08 AM', '6:10 PM', 'Rs 2-5 per person (travel sites conflict; no official tariff found)', 7, 8, 8.336126, 77.294724, 'Aruvikkarai, Tamil Nadu 629177 (approx 50 km from Kanyakumari)', NULL, 1.48);

