INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000121, 839005, 'Thirparappu Falls', 'Thirparappu Waterfalls', 'A 50-foot cascade on the Kodayar river about 55 km from Kanyakumari — semi-artificial, formed by a weir built upstream. The plunge pool at the base is considered safe for bathing, making it a popular family picnic spot. The ancient Mahadevar Temple (9th century, one of the 12 Sivalayas) stands at the entrance.', '2-3 hours', 'June to September (monsoon flow) and October to January', 'Carry a change of clothes and use the changing rooms if you plan to bathe. The temple at the entrance is worth a visit in itself.', 'no', 'Tamil Nadu', 0, 0, '6:08 AM', '6:10 PM', 'Rs 10 per person (mandakashayam, wanderlog, tamilnadutourisminfo, airial.travel; holidify reports Rs 2 — conflict noted)', 7, 8, 8.391578, 77.259545, 'Thirparappu, Kanyakumari district, Tamil Nadu (approx 55 km from Kanyakumari town)', NULL, 1.48);

