INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000122, 839005, 'Udayagiri Fort', 'Udayagiri Fort', 'A 17th-century fort near Padmanabhapuram (about 34 km from Kanyakumari) at Puliyurkurichi, later rebuilt in granite by Marthanda Varma of Travancore under the Dutch commander De Lannoy. Spread over 90 acres, it contains De Lannoy''s tombs, a 16-foot brass cannon, and a biodiversity park. A quieter historical stop often combined with Padmanabhapuram Palace.', '1-2 hours', 'Morning; October to March', 'Pair with Padmanabhapuram Palace, just a few kilometres away. The biodiversity park section is pleasant for a short walk.', 'no', 'Tamil Nadu', 0, 0, '6:08 AM', '6:10 PM', NULL, 5, 6, 8.2419, 77.3301, 'Puliyurkurichi, near Padmanabhapam, Kanyakumari district, Tamil Nadu (approx 34 km from Kanyakumari town)', NULL, 1.08);

