INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000123, 839005, 'Muttom Beach', 'Muttom Beach & Lighthouse', 'A rocky, dramatic shoreline about 32 km from Kanyakumari, very different from the town''s sandy beaches. The British-era lighthouse (built 1857-1882, per Wikipedia) offers views over the rocky coast. Swimming is not allowed; it is a scenery and photography destination, best combined with a coastal drive.', '1-2 hours', 'Late afternoon; October to March', 'Swimming is prohibited — enjoy the rocks and lighthouse views instead. The coastal road drive from Kanyakumari is scenic.', 'no', 'Tamil Nadu', 0, 1, '6:08 AM', '6:10 PM', 'Beach entry nominal Rs 20 (airial.travel); lighthouse entry Rs 10 adult / Rs 3 student (Wikipedia)', 6, 7, 8.13, 77.321, 'Muttom, Kanyakumari district, Tamil Nadu (approx 32 km from Kanyakumari town)', NULL, 1.28);

