INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000124, 839005, 'Nagaraja Temple, Nagercoil', 'Nagaraja Temple, Nagercoil', 'Ancient serpent temple in Nagercoil town, about 20 km from Kanyakumari, dedicated to Lord Nagaraja (Vasuki), the five-headed serpent king — the town''s name derives from ''Naga Raja Coil''. The temple is also noted for Jain Tirthankara idols (Mahavira and Parswanatha) carved on its pillars and unifies Jain, Buddhist, Saivite and Vaishnavite influences. General darshan is free.', '45 minutes - 1 hour', 'Early morning darshan; October to March', 'Men must remove shirts before entering the sanctum. The temple closes in the afternoon (roughly 11:30 AM-5 PM), so time your visit for morning or evening.', 'no', 'Tamil Nadu', 0, 0, '6:08 AM', '6:10 PM', 'Free general darshan (special poojas charged at the counter)', 7, 8, 8.187559, 77.4333, 'N Car St, Nagercoil, Tamil Nadu 629001 (approx 20 km from Kanyakumari town)', NULL, 1.48);

