INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000125, 839005, 'The Ocean Restaurant', 'The Ocean Restaurant (The Seashore Hotel)', 'Rooftop multi-cuisine restaurant on the 7th floor of The Seashore Hotel on East Car Street, overlooking the sea — one of Kanyakumari''s best-known sunset dinner spots. Serves Indian, Chinese and Continental dishes with an emphasis on seafood. Open 6:30 AM to 10:30 PM daily.', '1-1.5 hours', 'Sunset dinner; October to March', 'Request an outdoor table for the sunset sea view. Being a hotel rooftop restaurant, prices run mid-range to premium.', 'no', 'Tamil Nadu', 0, 1, '6:08 AM', '6:10 PM', NULL, 7, 7, 8.082, 77.5519, '7th Floor, The Seashore Hotel, 2/12 E Car St, Kanyakumari, Tamil Nadu 629702', NULL, 1.4);

