INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000126, 839005, 'Sea View Restaurant', 'Sea View Restaurant (Hotel Sea View)', 'Popular tourist restaurant on East Car Street near the beach, run with Hotel Sea View. Serves Indian, Asian and European dishes; reviewers single out the prawn tempura and chicken cheese balls. A reliable mid-range dinner option within walking distance of the main beach.', '1-1.5 hours', 'Dinner', 'Try the prawn tempura and chicken cheese balls, which reviewers praise. Expect a tourist-oriented menu and pricing.', 'no', 'Tamil Nadu', 0, 0, '6:08 AM', '6:10 PM', NULL, 6, 7, 8.0833, 77.552, 'E Car St, near the beach, Kanyakumari, Tamil Nadu 629702', NULL, 1.28);

