INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000127, 839005, 'Zam Zam Restaurant', 'Zam Zam Restaurant', 'Indian and Arabic restaurant on Cape Road near St. Antony''s Higher Secondary School, operating since 2018. Known for biryani, shawarma, kebabs, Al-Faham chicken and falooda, with delivery and catering services. Opening hours 11 AM-11 PM daily are published on its own official website.', '45 minutes - 1 hour', 'Lunch and dinner', 'The shawarma platter and chicken biryani are the most reviewed dishes. Phone: +91 7598665585 for takeaway.', 'no', 'Tamil Nadu', 0, 0, '6:08 AM', '6:10 PM', 'Rs 200-400 per person (per restaurant-guru listing)', 6, 7, 8.085667, 77.549429, '6/4D Cape Rd, near St. Antony''s Higher Secondary School, Kanyakumari, Tamil Nadu 629702', 'http://www.zamzamrestaurantkk.com/', 1.28);

