INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8390024, 839, 839005, 'Chitra Pournami', 'April-May', 'The full-moon festival at the Kumari Amman Temple, drawing lakhs of devotees to Kanyakumari. Special pujas are held through the night and pilgrims take a holy dip at the Triveni Sangam where the three seas meet.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8390025, 839, 839005, 'Navaratri', 'September-October', 'Nine nights of grand celebrations honouring the goddess at the Kumari Amman Temple and the Suchindram Temple, with special alankarams, music, and processions on the final days.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8390026, 839, 839005, 'Cape Festival', 'October', 'Kanyakumari''s three-day tourism cultural festival featuring music, dance and arts performances, organised to showcase the district''s culture to visitors.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8390027, 839, 839005, 'Aadi Amavasai', 'July-August', 'The new-moon day in the Tamil month of Aadi, when thousands gather at the Triveni Sangam for a holy dip and to perform ancestor rites (tarpanam) for the departed.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8390028, 839, 839005, 'Pongal', 'January', 'The four-day Tamil harvest festival (Bhogi, Thai Pongal, Mattu Pongal, Kaanum Pongal) celebrated widely across Kanyakumari district with sweet pongal cooking, cattle honours and family gatherings.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8390029, 839, 839005, 'Masi Car Festival (Suchindram)', 'February-March', 'The annual car festival (therottam) at the Suchindram Thanumalayan Temple in the Tamil month of Masi, when the temple deities are taken out in a grand chariot procession.');

