INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000131, 839006, 'Arulmigu Ramanathaswamy Temple', 'Arulmigu Ramanathaswamy Temple', 'One of the twelve Jyotirlinga shrines and part of the Char Dham, the Ramanathaswamy Temple is dedicated to Lord Shiva, whom Rama is believed to have worshipped here after returning from Lanka. Its third corridor is famed as one of the longest pillared corridors in the world, with about 4,000 ornate pillars, and 22 of Rameswaram''s 64 sacred theerthams lie within the temple complex.', '2-3 hours', 'October to March, early mornings', 'Attend the 5:00-6:00 AM Spadigalinga (crystal lingam) pooja for the most revered darshan; phones and cameras are not allowed inside.', 'no', 'Tamil Nadu', 0, 0, '6:05 AM', '6:05 PM', 'Rs 100 (Swami Sannadhi special entry) / Rs 50 (Ambal Sannadhi special entry)', 5, 4.5, 9.2881, 79.3174, 'Ramanathaswamy Temple, Rameswaram, Ramanathapuram District, Tamil Nadu 623526', 'https://rameswaramramanathar.hrce.tn.gov.in/hrcehome/index_temple.php?tid=35671&action=pooja_info', 0.96);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (839000131, 839000131, '4:00 AM - 1:00 PM, 3:00 PM - 8:00 PM', '4:00 AM - 1:00 PM, 3:00 PM - 8:00 PM', '4:00 AM - 1:00 PM, 3:00 PM - 8:00 PM', '4:00 AM - 1:00 PM, 3:00 PM - 8:00 PM', '4:00 AM - 1:00 PM, 3:00 PM - 8:00 PM', '4:00 AM - 1:00 PM, 3:00 PM - 8:00 PM', '4:00 AM - 1:00 PM, 3:00 PM - 8:00 PM', 'Official HRCE timings. Darshan from 5:00 AM; Spadigalinga pooja 5:00-6:00 AM; bathing in the 22 temple theerthams 5:30 AM-12:30 PM and 3:00-7:00 PM. Traditional dress code; non-Hindus restricted from inner shrine.');

