INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 839000131, 'insert', 'bulk', 'Confirmed real: official HRCE (Hindu Religious & Charitable Endowments, TN govt) temple site fetched 2026-09-30 and loads; timings and fee schedule taken verbatim from it. Jyotirlinga/Char Dham status per Tamil Nadu Tourism. Coordinates are the well-known temple location, not field-verified.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000132, 839006, 'Agni Theertham', 'Agni Theertham', 'The sacred seashore about 100 metres east of the Ramanathaswamy Temple''s east gopuram, where pilgrims take a holy dip before temple darshan. Legend holds that Lord Rama bathed here to purify himself after the battle with Ravana, and that Agni (god of fire) dipped here after returning Sita to Rama. Thousands gather here on Thai Amavasai and Aadi Amavasai to offer rites to departed ancestors.', '1-2 hours', 'November to February, sunrise', 'Go at sunrise for the calmest, most atmospheric visit; carry your own towel and dress for a ritual dip.', 'no', 'Tamil Nadu', 1, 0, '6:05 AM', '6:05 PM', 'Free', 4, 3.5, 9.2907, 79.3184, 'Agni Theertham Beach, East Car Street, Rameswaram, Tamil Nadu 623526', NULL, 0.76);

