INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 839000132, 'insert', 'bulk', 'Confirmed real: described by Tamil Nadu tourism sources and hindu-blog.com (100 m from east gopuram). Visitor reviews note cleanliness can suffer from crowds and ritual offerings. Coordinates approximate for the beachfront east of the temple.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000133, 839006, 'Dhanushkodi Ghost Town', 'Dhanushkodi Ghost Town', 'About 20 km southeast of Rameswaram, Dhanushkodi is the abandoned town destroyed by the December 1964 cyclone that killed around 1,800 people, including 115 passengers of a train washed away; the government declared it unfit for habitation. Its roofless church, railway station, and port-office ruins stand between the Bay of Bengal and the Indian Ocean, and a national highway now runs the length of the strip so visitors can drive in.', '2-3 hours', 'October to March, mornings', 'Combine with Arichal Munai at the tip; carry water and snacks as facilities are minimal, and check wind/current warnings before wading in.', 'no', 'Tamil Nadu', 1, 0, '6:05 AM', '6:05 PM', NULL, 5, 4.5, 9.2177, 79.4139, 'Dhanushkodi, Rameswaram, Ramanathapuram District, Tamil Nadu 623526', NULL, 0.96);

