INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 839000133, 'insert', 'bulk', 'Confirmed real: 1964 cyclone history per The Hindu BusinessLine, Outlook Traveller, and an IOSR journal paper; road access via completed national highway per travel reports. Coordinates are the approximate town/ruins area.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000134, 839006, 'Arichal Munai', 'Arichal Munai', 'Arichal Munai is the land''s end at the tip of Dhanushkodi, about 20 km from Rameswaram, where the waters of the Bay of Bengal and the Indian Ocean visibly meet. Tradition holds this as the spot from which Rama built the Ram Setu (Adam''s Bridge) toward Sri Lanka, whose shoals lie just across the strait. It is one of India''s most photographed sunrise points, with the pillar marking the tip standing at the confluence.', '1-2 hours', 'October to March, sunrise', 'Arrive before sunrise for the confluence view; do not swim here as the currents at the meeting of the two seas are strong.', 'no', 'Tamil Nadu', 1, 0, '6:05 AM', '6:05 PM', NULL, 4.5, 4.5, 9.1753, 79.422, 'Arichal Munai, Dhanushkodi, Ramanathapuram District, Tamil Nadu 623526', NULL, 0.9);

