INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 839000134, 'insert', 'bulk', 'Confirmed real: widely documented as Dhanushkodi''s land end and the Bay of Bengal-Indian Ocean confluence (Testbook/Outlook Traveller). Coordinates approximate for the tip.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000135, 839006, 'New Pamban Rail Bridge', 'New Pamban Rail Bridge', 'Inaugurated on 6 April 2025 (Ram Navami) by Prime Minister Narendra Modi, the new Pamban Bridge is India''s first vertical-lift railway sea bridge, replacing the 1914 Scherzer rolling-lift bridge retired in 2022. The 2.07 km bridge''s 72.5-metre central span lifts 17 metres vertically to let ships pass, and it was built by RVNL to withstand cyclones stronger than the 1964 storm. The parallel Annai Indira Gandhi road bridge (1988) alongside it is the best vantage point to watch trains cross the sea.', '1 hour', 'October to March, late afternoon for sunset views', 'Stop at the road-bridge viewpoint near Pamban to photograph the lift span and watch a train cross over the Palk Strait.', 'no', 'Tamil Nadu', 0, 1, '6:05 AM', '6:05 PM', 'Free', 4.5, 4.5, 9.2796, 79.2089, 'Pamban Bridge, Pamban, Ramanathapuram District, Tamil Nadu 623521', NULL, 0.9);

