INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000136, 839006, 'Dr. A.P.J. Abdul Kalam National Memorial', 'Dr. A.P.J. Abdul Kalam National Memorial', 'Built by the DRDO at Pei Karumbu on the burial site of Dr. A.P.J. Abdul Kalam, India''s 11th President, who died on 27 July 2015 and was laid to rest here on 30 July 2015. Four galleries trace his life from Rameswaram newspaper boy to ''Missile Man of India'', with missile and rocket models, his veena, awards, and a bronze statue; a Mughal-style garden with missile models lines the approach. Photography is prohibited inside the memorial.', '1-2 hours', 'October to March, mornings', 'Leave cameras and phones in your vehicle as photography is strictly banned inside; the exterior gardens are the photo spot.', 'no', 'Tamil Nadu', 0, 0, '6:05 AM', '6:05 PM', 'Free', 4.5, 4.5, 9.2817, 79.2958, 'Dr. APJ Abdul Kalam National Memorial, Dhanushkodi Road, Pei Karumbu, Rameswaram, Tamil Nadu 623529', NULL, 0.9);

