INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000137, 839006, 'House of Kalam (Kalam House Museum)', 'House of Kalam (Kalam House Museum)', 'The modest ancestral home on Mosque Street where Dr. A.P.J. Abdul Kalam spent his childhood, converted into a museum in 2011 and maintained by his elder brother''s family. It displays rare childhood photographs, personal belongings, medals, honours, and exhibits on his DRDO/ISRO research career, with a souvenir shop selling seashell crafts and his books on the ground floor. Visitors enter barefoot and cameras are not allowed inside.', '1 hour', 'October to March, mornings', 'Go right at opening to beat the crowds; carry no camera inside and pick up a seashell souvenir from the ground-floor shop.', 'no', 'Tamil Nadu', 0, 0, '6:05 AM', '6:05 PM', 'Free', 4, 4, 9.2877, 79.313, 'House of Kalam, Mosque Street, Rameswaram, Tamil Nadu 623526', NULL, 0.8);

