INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000138, 839006, 'Panchamukhi Hanuman Temple', 'Panchamukhi Hanuman Temple', 'About 2 km from the Ramanathaswamy Temple, this shrine houses a rare five-faced (Panchamukhi) idol of Lord Hanuman, his five faces symbolising protection from all directions. The temple keeps the famous ''floating stones'' believed to be remnants of the Ram Setu built by Rama''s vanara army, along with idols of Rama, Sita and Hanuman salvaged from Dhanushkodi after the 1964 cyclone.', '1 hour', 'October to March, mornings or late afternoons', 'Ask the priest about the floating stones kept in the water tank on the premises - they are the highlight for most visitors.', 'no', 'Tamil Nadu', 0, 0, '6:05 AM', '6:05 PM', 'Free', 4, 4, 9.2868, 79.311, 'Panchamukhi Hanuman Temple, Rameswaram, Tamil Nadu 623526', NULL, 0.8);

