INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000139, 839006, 'Gandhamadhana Parvatham', 'Gandhamadhana Parvatham', 'The highest point on Rameswaram island, about 3 km from the town, where a small hilltop temple enshrines the sacred footprints of Lord Rama (Ramar Patham). Tradition says Rama surveyed the sea and planned the Lanka campaign from this hill, and Hanuman is believed to have begun his leap to Lanka here. The summit gives a 360-degree panorama of the island, town, and sea, and is a favourite golden-hour spot.', '1 hour', 'October to March, late afternoon', 'Visit in the late afternoon for golden-hour light and sea breeze; wear footwear you can remove before the shrine and watch for monkeys.', 'no', 'Tamil Nadu', 0, 1, '6:05 AM', '6:05 PM', 'Free', 4, 4, 9.2963, 79.3186, 'Gandhamadhana Parvatham, GP Road, Rameswaram, Tamil Nadu 623526', NULL, 0.8);

