INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 839000139, 'insert', 'bulk', 'Confirmed real: TripHobo and Tripadvisor list 6 AM-6 PM; tamilnadutours.net confirms it as the island''s highest point (3 km) with Rama''s footprints. Coordinates approximate for the hilltop.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000140, 839006, 'Kothandaramaswamy Temple', 'Kothandaramaswamy Temple', 'This 500-1000-year-old shrine near Dhanushkodi, about 13 km from Rameswaram, is dedicated to Rama holding his bow (kothandam), with Sita, Lakshmana, Hanuman and Vibhishana. It marks where Vibhishana surrendered to Rama and where Rama crowned him king of Lanka (pattabhishekam), a story painted across the shrine walls; it is one of the 108 Abhimana Kshethrams. It was the only historical structure to survive the 1964 cyclone that destroyed Dhanushkodi, and Swami Vivekananda is believed to have visited after his Chicago trip.', '1-2 hours', 'October to March, mornings', 'Drive the sea-flanked road from Dhanushkodi slowly - the temple sits on a strip surrounded by water on both sides.', 'no', 'Tamil Nadu', 0, 0, '6:05 AM', '6:05 PM', NULL, 4.5, 4.5, 9.24, 79.355, 'Kothandaramaswamy Temple, Dhanushkodi Road, Rameswaram, Tamil Nadu 623526', NULL, 0.9);

