INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000141, 839006, 'Ariyaman Beach (Kushi Beach)', 'Ariyaman Beach (Kushi Beach)', 'About 21-27 km from Rameswaram toward Mandapam, Ariyaman Beach (also called Kushi Beach) is a 2 km calm-water beach on the Palk Bay/Gulf of Mannar side, famous for gentle, nearly waveless water that suits non-swimmers, children and the elderly. Casuarina trees line the shore, and the site has boating, a children''s park, a swimming pool, food stalls, and tourism-department accommodation nearby. Sunset views over the calm water are a highlight.', '2-3 hours', 'October to March, late afternoon', 'Swim only in the shallow marked zone and watch for jellyfish; carry a change of clothes and use the paid shower facilities.', 'no', 'Tamil Nadu', 0, 1, '6:05 AM', '6:05 PM', NULL, 4, 4, 9.274, 79.198, 'Ariyaman Beach, Mandapam, Ramanathapuram District, Tamil Nadu 623518', NULL, 0.8);

