INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 839000141, 'insert', 'bulk', 'Confirmed real: ZeeZest, Sacred Yatra and Tripadvisor confirm location (21-27 km from Rameswaram), calm waters, and facilities. Coordinates approximate for the beach near Mandapam.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000142, 839006, 'Olaikuda Beach', 'Olaikuda Beach', 'Olaikuda is a quiet fishing-village beach east of Rameswaram town, listed by Tamil Nadu tourism coverage among the island''s beautiful beaches alongside Dhanushkodi and Pamban. Far less commercial than the main beaches, it offers an unhurried shoreline where visitors can watch local fishing life. St. Santhiyagu Church stands in the Olaikuda locality.', '1-2 hours', 'October to March, mornings', 'Best for a quiet walk or photography rather than swimming; pair it with the Dhanushkodi road circuit.', 'no', 'Tamil Nadu', 1, 0, '6:05 AM', '6:05 PM', NULL, 3.5, 3.5, 9.313, 79.349, 'Olaikuda, Rameswaram, Ramanathapuram District, Tamil Nadu 623526', NULL, 0.7);

