INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 839000142, 'insert', 'bulk', 'Confirmed as a named Rameswaram beach by tamilnadutours.net (''Beautiful beaches at Olaikuda, Danushkodi and Pamban''). Less documented than other beaches; coordinates approximate for the Olaikuda coastal village.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000143, 839006, 'Lakshmana Theertham', 'Lakshmana Theertham', 'One of Rameswaram''s 64 holy theerthams, about 1-3 km from the Ramanathaswamy Temple, where Lakshmana is believed to have installed and worshipped a Shiva linga to cleanse himself after the war with Ravana. The site has a colourful pillared shrine, a temple pond teeming with fish that devotees feed with rice puffs, and Rama, Sita and Lakshmana shrines. The floating car procession of Ramanathaswamy is organised here during the Thai Poosam festival.', '1 hour', 'October to March, mornings', 'Bring puffed rice to feed the fish in the pond - a popular ritual here - and combine the visit with nearby Rama and Sita Theerthams.', 'no', 'Tamil Nadu', 0, 0, '6:05 AM', '6:05 PM', NULL, 3.5, 3.5, 9.2957, 79.3089, 'Lakshmana Theertham, Rameswaram, Tamil Nadu 623526', NULL, 0.7);

