INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000144, 839006, 'Villondi Theertham', 'Villondi Theertham', 'A seashore theertham on the road toward Pamban, about 7 km from Rameswaram, where a sweet-water spring bubbles up inside the sea. Legend says that when Sita was thirsty, Rama shot an arrow into the sea here and fresh water sprang forth - the spring still flows amid the salt water. Pilgrims stop here for a ritual sip and dip on the Rameswaram temple circuit.', '30 minutes - 1 hour', 'October to March, mornings', 'Taste the sweet water at the spring in the sea - it is the site''s signature experience - and stop here en route to Pamban Bridge.', 'no', 'Tamil Nadu', 0, 0, '6:05 AM', '6:05 PM', NULL, 3.5, 3.5, 9.2668, 79.259, 'Villondi Theertham, Rameswaram-Mandapam Road, Tamil Nadu 623526', NULL, 0.7);

