INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000145, 839006, 'Navapashanam Temple, Devipattinam', 'Navapashanam Temple, Devipattinam', 'A day trip about 65-70 km from Rameswaram, Devipattinam''s Navapashanam is a unique sea temple where nine stones representing the Navagrahas (nine planetary deities) stand in a matrix in the Bay of Bengal, reached by wading through shallow water. Legend says Rama installed the nine planets here with his own hands using local clay before building the bridge to Lanka. The adjacent village temple honours Devi, who slew Mahishasura here - hence the name Devipattinam.', '1-2 hours', 'October to March; visit at low tide (early morning 6-7 AM)', 'Go at low tide/early morning when the nine stones are fully visible; wear footwear you can get wet and carry a change of clothes.', 'no', 'Tamil Nadu', 1, 0, '6:05 AM', '6:05 PM', NULL, 4, 4, 9.4775, 78.8997, 'Navapashanam Temple, Devipattinam, Ramanathapuram District, Tamil Nadu 623514', NULL, 0.8);

