INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 839000145, 'insert', 'bulk', 'Confirmed real: Wikipedia documents the legend, architecture, and 66 km East Coast Road location; distance to Rameswaram 61-70 km per rome2rio/airial. Coordinates are the Devipattinam town location; temple sits on the shore within ~1 km.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000146, 839006, 'Adhi Ratneswarar Temple, Thiruvadanai', 'Adhi Ratneswarar Temple, Thiruvadanai', 'A day trip about 100 km from Rameswaram, Thiruvadanai''s Adhi Ratneswarar Temple is one of the 275 Paadal Petra Sthalams glorified in the Thevaram hymns of Sambandar. The name comes from the legend that the Sun god worshipped Shiva here with a lingam made of sapphire (ratna); during midday abhishekams the deity appears blue. Its 139-foot nine-tier rajagopuram, renovated with patronage from Tamil film actors, is visible from about 10 miles away.', '1-2 hours', 'October to March, mornings', 'Time your visit around midday abhishekam to see the famed blue appearance of the lingam; special Shukra (Venus) homas are held here.', 'no', 'Tamil Nadu', 0, 0, '6:05 AM', '6:05 PM', NULL, 4, 4, 9.7833, 78.9167, 'Adhi Ratneswarar Temple, Thiruvadanai, Ramanathapuram District, Tamil Nadu 623407', NULL, 0.8);

