INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000147, 839006, 'Mangalanathaswamy Temple, Uthirakosamangai', 'Mangalanathaswamy Temple, Uthirakosamangai', 'A day trip about 75 km from Rameswaram (18 km from Ramanathapuram), Uthirakosamangai''s ancient Mangalanathaswamy Temple is famed for its presiding Shiva deity carved from a single emerald. Considered one of the oldest Shiva temples in the region, it draws large crowds for its annual Arudhra festival in December. The temple is also noted for its exquisite stone carvings and serene, less-commercialised atmosphere.', '1-2 hours', 'October to March; December for the Arudhra festival', 'Ask about viewing the emerald (maragatham) deity, which is kept covered with sandal paste most of the year and unveiled on special days.', 'no', 'Tamil Nadu', 0, 0, '6:05 AM', '6:05 PM', NULL, 4, 4, 9.3267, 78.7389, 'Mangalanathaswamy Temple, Uthirakosamangai, Ramanathapuram District, Tamil Nadu 623533', NULL, 0.8);

