INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000148, 839006, 'Erwadi Dargah', 'Erwadi Dargah', 'A day trip about 75 km from Rameswaram, the Erwadi Dargah is the tomb of Sultan Syed Ibrahim Shahid, believed to be an 18th-generation descendant of the Prophet who arrived in the early 12th century to propagate Islam and was martyred here. The annual month-long Santhanakoodu Festival in the Islamic month of Dhu al-Qi''dah commemorates his martyrdom and is observed jointly by Hindu and Muslim devotees, drawing pilgrims from Sri Lanka, Malaysia and Singapore.', '1-2 hours', 'October to March; Dhu al-Qi''dah for the Santhanakoodu festival', 'Dress modestly and respect prayer times; the festival month is crowded, so visit off-season for a calm darshan of the dargah.', 'no', 'Tamil Nadu', 0, 0, '6:05 AM', '6:05 PM', NULL, 3.5, 4, 9.213, 78.723, 'Erwadi Dargah, Erwadi, Ramanathapuram District, Tamil Nadu 623501', NULL, 0.74);

