INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 839000148, 'insert', 'bulk', 'Confirmed real: Wikipedia documents the saint''s history and the Santhanakoodu Festival in Dhu al-Qi''dah; tamilnadutours.net confirms the dargah and festival. Drive from Rameswaram about 75 km per rome2rio (46.4 mi). Coordinates approximate for the dargah complex.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000149, 839006, 'Kanjirankulam Bird Sanctuary', 'Kanjirankulam Bird Sanctuary', 'A day trip about 100 km from Rameswaram near Mudukulathur, Kanjirankulam is a 1.04 sq km protected wetland declared a bird sanctuary in 1989 and a Ramsar site in April 2022. Its babul-tree heronry hosts breeding colonies of painted stork, spot-billed pelican, white and black ibis, and egrets, with over 170 bird types recorded in the migratory season from October to February. Together with adjacent Chitrangudi it forms an Important Bird Area.', '2-3 hours', 'October to February (migratory season)', 'Visit early morning with binoculars in the October-February window; outside the season the wetland may be dry and birdless.', 'no', 'Tamil Nadu', 0, 0, '6:05 AM', '6:05 PM', NULL, 3.5, 3.5, 9.333, 78.483, 'Kanjirankulam Bird Sanctuary, Mudukulathur, Ramanathapuram District, Tamil Nadu 623704', NULL, 0.7);

