INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000150, 839006, 'Chitrangudi Bird Sanctuary', 'Chitrangudi Bird Sanctuary', 'A day trip about 100 km from Rameswaram, adjacent to Kanjirankulam near Mudukulathur, Chitrangudi (locally Chitrangudi Kanmoli) is a protected wetland declared in 1989 around an irrigation tank. Migratory waterbirds - spot-billed pelican, Asian openbill stork, grey and purple herons, pond heron, and little and great egrets - arrive to breed between October and February. It is open year-round and reachable by road, 12 km from Sayalgudi and 45 km from Ramanathapuram.', '2-3 hours', 'October to February (migratory season)', 'Pair it with Kanjirankulam in one trip; the Wildlife Warden, Gulf of Mannar Biosphere Reserve, Mandapam (04567-230079) is the contact for the sanctuary.', 'no', 'Tamil Nadu', 0, 0, '6:05 AM', '6:05 PM', NULL, 3.5, 3.5, 9.354, 78.493, 'Chitrangudi Bird Sanctuary, Mudukulathur, Ramanathapuram District, Tamil Nadu 623704', NULL, 0.7);

