INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000151, 839006, 'Ganesh Mess', 'Ganesh Mess', 'A long-standing pure-vegetarian mess on Middle Street near the Ramanathaswamy Temple, famous for authentic South Indian meals served on banana leaf, plus tiffins like masala dosa, idli and vada. Known for quick, humble service and value-for-money traditional food, it is one of the most recommended eating spots for pilgrims in Rameswaram.', '45 minutes - 1 hour', 'Lunch (12-2 PM) for the full banana-leaf meals', 'Go at off-peak hours as seating is limited; the banana-leaf meals at lunch are the signature order.', 'no', 'Tamil Nadu', 0, 0, '6:05 AM', '6:05 PM', NULL, 4, 4, 9.2885, 79.3135, 'Ganesh Mess, Middle Street, Rameswaram, Tamil Nadu 623526', NULL, 0.8);

