INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000152, 839006, 'Hotel Sri Saravana Bhavan', 'Hotel Sri Saravana Bhavan', 'A pure-vegetarian South Indian restaurant on Old Market Street, a short walk from the Ramanathaswamy Temple''s west gate, serving dosas, idlis, pongal and traditional Tamil meals through the day. Spacious enough for families and groups, it is a reliable breakfast and lunch stop for pilgrims, though it gets crowded at peak meal times.', '45 minutes - 1 hour', 'Breakfast (7-9 AM) to beat the crowds', 'Arrive early for breakfast - dosas, idlis and pongal are served fresh and hot, and crowds build up by late morning.', 'no', 'Tamil Nadu', 0, 0, '6:05 AM', '6:05 PM', NULL, 4, 3.5, 9.288, 79.3115, 'Hotel Sri Saravana Bhavan, Old Market Street, Rameswaram, Tamil Nadu 623526', NULL, 0.76);

