INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000153, 839006, 'Ahaan (Daiwik Hotels Rameswaram)', 'Ahaan (Daiwik Hotels Rameswaram)', 'Ahaan is the pure-vegetarian multi-cuisine restaurant of Daiwik Hotels Rameswaram on the Madurai-Rameswaram Highway (NH49) at Semma Madam, a few kilometres from the temple. It offers a more upscale dining room than the town''s messes, with South and North Indian vegetarian fare, and is rated around Rs 1,200 for two.', '1 hour', 'Lunch or dinner; October to March', 'A good pick for a comfortable sit-down family dinner after temple darshan; table booking is available via the hotel.', 'no', 'Tamil Nadu', 0, 0, '6:05 AM', '6:05 PM', NULL, 3.5, 4, 9.2815, 79.3, 'Ahaan, Daiwik Hotels Rameswaram, Madurai-Rameswaram Highway (NH49), Semma Madam, Rameswaram, Tamil Nadu 623526', NULL, 0.74);

