INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000154, 839006, 'Murugan Mess', 'Murugan Mess', 'A pure-vegetarian mess on North Car Street, listed at the Tamil Nadu Tourism hostel premises, known for simple, affordable South Indian vegetarian food round the clock. A practical option for pilgrims staying near the temple who need food at odd hours.', '45 minutes', 'Any time; useful for late-night or early-morning meals', 'Handy for odd-hour meals near the temple area since it operates round the clock.', 'no', 'Tamil Nadu', 0, 0, '6:05 AM', '6:05 PM', NULL, 3.5, 3.5, 9.29, 79.314, 'Murugan Mess, North Car Street (Tamil Nadu Tourism Hostel), Rameswaram, Tamil Nadu 623526', NULL, 0.7);

