INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8390030, 839, 839006, 'Maha Shivaratri', 'Feb-Mar', 'The biggest festival at the Ramanathaswamy Temple, celebrated over 10 days with the temple filled with Shiva devotees; special abhishekams and night-long worship mark the occasion.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8390031, 839, 839006, 'Thirukalyanam', 'Jul-Aug', 'The divine marriage of Lord Ramanathaswamy and Goddess Vishalakshi (Parvathy), celebrated as an auspicious occasion with large devotee participation at the temple.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8390032, 839, 839006, 'Navaratri', 'Sep-Oct', 'Nine-night festival honouring the Goddess at the Ramanathaswamy Temple, one of its major annual celebrations.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8390033, 839, 839006, 'Vasantholsavam', 'May-Jun', 'The spring festival of the Ramanathaswamy Temple, celebrated with processions and special rituals.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8390034, 839, 839006, 'Aadi Amavasai', 'Jul-Aug', 'On this new-moon day in the Tamil month of Aadi, thousands of pilgrims gather at Agni Theertham to offer prayers and rites to departed ancestors.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8390035, 839, 839006, 'Vibhishana Pattabishekam', 'Jun-Jul', 'Annual coronation festival at the Kothandaramaswamy Temple near Dhanushkodi in the Tamil month of Aani, commemorating Rama crowning Vibhishana as king of Lanka.');

