INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000157, 839007, 'Brihadisvara Temple (Big Temple)', 'Brihadisvara Temple (Big Temple)', 'UNESCO World Heritage site (Great Living Chola Temples), built by Rajaraja Chola I and consecrated around 1009-1010 CE. Massive granite temple with a ~66 m vimana capped by an 80-tonne monolithic cupola; the 8.7 m brihad-linga sits in the sanctum. Famed for Chola murals, inscriptions and life-size deity sculptures. ASI: admission free.', '2-3 hours', 'November to February', 'Entry is free; no fee for handheld-camera photography. Plan 2-3 hours; climb-free vimana view best from the courtyard.', 'no', 'Tamil Nadu', 0, 0, '6:02 AM', '6:04 PM', 'Free', 5, 5, 10.7827, 79.1315, 'Membalam Rd, Thanjavur, Tamil Nadu 613009', 'https://asi.nic.in/pages/WorldHeritageCholaTemples', 1.0);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (839000157, 839000157, '6:30 AM - 8:30 PM', '6:30 AM - 8:30 PM', '6:30 AM - 8:30 PM', '6:30 AM - 8:30 PM', '6:30 AM - 8:30 PM', '6:30 AM - 8:30 PM', '6:30 AM - 8:30 PM', 'ASI official: 6:30 AM to 8:30 PM on all days. Some travel guides report the shrine open 6:00 AM-12:30 PM and 4:00 PM-8:30 PM in two sessions; inner-sanctum darshan timings can vary from complex hours.');

