INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000158, 839007, 'Thanjavur Maratha Palace', 'Thanjavur Maratha Palace', 'Former royal residence of the Thanjavur Marathas (Serfoji II era), housing the Royal Palace Museum, the Thanjavur Art Gallery with Chola bronzes and Tanjore paintings, the Saraswathi Mahal Library and the Sangeetha Mahal. Built over the Nayak palace core, expanded by Marathas.', '2-3 hours', 'November to February', 'One composite ticket (Rs 50 Indians) covers the museum, art gallery and library. Camera fees are reported inconsistently (Rs 50 still / Rs 200 video vs Rs 30 elsewhere) - confirm at the counter.', 'no', 'Tamil Nadu', 0, 0, '6:02 AM', '6:04 PM', 'Rs 50', 5, 4, 10.792, 79.1366, 'East Main Street, Thanjavur, Tamil Nadu 613001', NULL, 0.92);

