INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000159, 839007, 'Saraswathi Mahal Library', 'Saraswathi Mahal Library', 'One of India''s oldest surviving manuscript libraries, begun by the Nayaks and greatly expanded by Maratha king Serfoji II. Holds over 49,000 palm-leaf and paper manuscripts in Sanskrit, Tamil, Telugu and Marathi, plus a museum of illustrated manuscripts, atlases and medical treatises.', '1-2 hours', 'November to February', 'Closed Wednesdays - plan around it. Manuscripts are displayed in the museum; photography of rare folios is restricted.', 'no', 'Tamil Nadu', 0, 0, '6:02 AM', '6:04 PM', 'Rs 50', 5, 5, 10.79178, 79.136569, 'Royal Palace, Thanjavur, Tamil Nadu 613001', NULL, 1.0);

