INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000160, 839007, 'Thanjavur Art Gallery', 'Thanjavur Art Gallery', 'Art gallery set inside the Maratha Palace, exhibiting a celebrated collection of Chola bronze sculptures, stone icons (including masterpieces from Darasuram) and classical Tanjore paintings. One of the finest bronze collections in South India.', '1 hour', 'November to February', 'Visit on the same composite ticket as the palace museum; lighting is dim for conservation - give your eyes time to adjust.', 'no', 'Tamil Nadu', 0, 0, '6:02 AM', '6:04 PM', 'Rs 50 (composite palace ticket)', 4, 5, 10.791042, 79.135979, 'Royal Palace, Thanjavur, Tamil Nadu 613001', NULL, 0.88);

