INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000162, 839007, 'Schwartz Church', 'Schwartz Church', 'Historic church built in 1779 by Raja Serfoji II in memory of Rev. F.C. Schwartz, the Danish missionary who was the king''s mentor. A rare example of a Hindu king building a Christian church, blending European and Indian architectural elements.', '30 minutes', 'November to February', 'About 500 m from the Big Temple near Sivaganga Tank; modest dress recommended as it is an active church.', 'no', 'Tamil Nadu', 0, 0, '6:02 AM', '6:04 PM', 'Free', 3, 4, 10.7877, 79.132, 'Near Sivaganga Tank, Thanjavur, Tamil Nadu 613001', NULL, 0.68);

