INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000163, 839007, 'Sivaganga Park', 'Sivaganga Park', 'Public park and family recreation area around the Sivaganga Tank, a historic water body of the Big Temple created under Rajaraja Chola and developed as a park in 1871-72. Has a toy train, boating on the tank, a small zoo section and play areas; popular sunset spot.', '1-2 hours', 'November to February', 'Evening visits are pleasant for families; the toy train and boating are the main draws. Check Sunday closure locally.', 'no', 'Tamil Nadu', 1, 1, '6:02 AM', '6:04 PM', NULL, 3, 3, 10.784833, 79.131238, 'Sivaganga Tank, Thanjavur, Tamil Nadu 613001', NULL, 0.6);

