INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000164, 839007, 'Punnainallur Mariamman Temple', 'Punnainallur Mariamman Temple', 'Famous Amman temple about 5 km east of Thanjavur town, dedicated to Mariamman manifested as a mud (puthu) anthill idol - the deity is worshipped in her natural mud form without an installed idol. Major crowds during the Aadi festival (July-August).', '1 hour', 'November to February', 'Try the temple''s special darshan if queues are long during Aadi. Shoes and phones follow standard temple rules.', 'no', 'Tamil Nadu', 0, 0, '6:02 AM', '6:04 PM', 'Free', 4, 4, 10.7706, 79.165, 'Punnainallur, Thanjavur, Tamil Nadu 613501', NULL, 0.8);

