INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000165, 839007, 'Poompuhar Handicrafts Emporium', 'Poompuhar Handicrafts Emporium', 'State-run Tamil Nadu Handicrafts Development Corporation showroom (Poompuhar) selling authentic Tanjore paintings, bronze idols, sandalwood carvings and textiles at fixed government prices. The reliable place to buy genuine Thanjavur crafts.', '45 minutes', 'November to February', 'Fixed prices mean no haggling - good benchmark for bargaining at private shops. Tanjore paintings here come with authenticity certification.', 'no', 'Tamil Nadu', 0, 0, '6:02 AM', '6:04 PM', NULL, 4, 4, 10.780463, 79.139914, 'Gandhiji Rd, Graham Nagar, Thanjavur, Tamil Nadu 613001', 'https://poompuhar.com/', 0.8);

