INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000166, 839007, 'Sangeetha Mahal', 'Sangeetha Mahal', 'Early-1600s Nayak-era music hall inside the Maratha Palace, famed for its acoustics - the durbar hall was designed so a whisper carries across the room. Now houses handicraft shops selling Tanjore art and souvenirs.', '30-45 minutes', 'November to February', 'Test the famous acoustics with a soft clap or whisper from the far end. Combine with palace museum visit on the same ticket.', 'no', 'Tamil Nadu', 0, 0, '6:02 AM', '6:04 PM', 'Rs 50 (composite palace ticket)', 3, 4, 10.7915, 79.136, 'Royal Palace, Thanjavur, Tamil Nadu 613001', NULL, 0.68);

