INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000167, 839007, 'Aiyarappar Temple, Thiruvaiyaru', 'Aiyarappar Temple, Thiruvaiyaru', 'About 13 km north of Thanjavur, the Panchanatheeswarar (Aiyarappar) Temple at Thiruvaiyaru is one of the Saptha Sthanam temples and revered as Dakshina Kailasam. It is the venue of the annual Thyagaraja Aradhana, where Carnatic musicians gather at the saint-composer''s samadhi.', '1-2 hours', 'November to February (peak during Thyagaraja Aradhana)', 'Visit during the Thyagaraja Aradhana (Jan-Feb) for the Pancharatna kriti mass rendition - book stay early. Standard temple dress code.', 'no', 'Tamil Nadu', 0, 0, '6:02 AM', '6:04 PM', 'Free', 4, 4, 10.879, 79.105, 'Thiruvaiyaru, Thanjavur district, Tamil Nadu 613204', NULL, 0.8);

