INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000168, 839007, 'Shri 1008 Bhagwan Adinath Digambar Jain Temple', 'Shri 1008 Bhagwan Adinath Digambar Jain Temple', 'Digambar Jain temple at Karunthattankudi (Karanthai area) dedicated to Bhagwan Adinath (Rishabhanatha), the first Tirthankara. Rated 4.9 by visitors; part of Thanjavur''s historic Jain presence.', '45 minutes', 'November to February', 'Modest dress and no leather items inside, per Jain temple custom. Morning aarti is the best time to visit.', 'no', 'Tamil Nadu', 0, 0, '6:02 AM', '6:04 PM', 'Free', 3, 4, 10.804199, 79.135076, 'Door No. 4, Jain Street, Karunthattankudi, Thanjavur, Tamil Nadu 613002', NULL, 0.68);

