INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000170, 839007, 'Thanjavur Palace Durbar Hall', 'Thanjavur Palace Durbar Hall', 'The grand durbar hall of the Maratha palace complex, where the Thanjavur kings held court. Noted for its carved pillars, murals and the blend of Nayak and Maratha architecture; shares the palace complex''s composite ticket.', '30 minutes', 'November to February', 'Included in the palace complex ticket - no separate queue. Guides near the entrance narrate the Maratha court history.', 'no', 'Tamil Nadu', 0, 0, '6:02 AM', '6:04 PM', 'Rs 50 (composite palace ticket)', 4, 4, 10.792, 79.1366, 'Royal Palace, Thanjavur, Tamil Nadu 613001', NULL, 0.8);

