INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000171, 839007, 'Airavatesvara Temple, Darasuram', 'Airavatesvara Temple, Darasuram', 'UNESCO World Heritage (Great Living Chola Temples), built by Rajaraja Chola II (12th century), about 35 km from Thanjavur. A gem of ornate Chola architecture: the front mandapa is conceived as a stone chariot with wheels, pillars are intricately carved, and the steps sing musical notes when tapped.', '1.5-2 hours', 'November to February', 'Tap the musical steps gently - they produce the seven swaras. Pair with a Kumbakonam temple-town visit the same day.', 'no', 'Tamil Nadu', 0, 0, '6:02 AM', '6:04 PM', 'Free', 5, 5, 10.9484, 79.3565, 'Darasuram, near Kumbakonam, Tamil Nadu 612702', 'https://asi.nic.in/pages/WorldHeritageCholaTemples', 1.0);

