INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000172, 839007, 'Brihadisvara Temple, Gangaikonda Cholapuram', 'Brihadisvara Temple, Gangaikonda Cholapuram', 'UNESCO World Heritage temple built by Rajendra Chola I (completed 1035 AD) as the centrepiece of his new capital, about 70 km from Thanjavur. Its 53-m vimana has recessed corners and a graceful upward curve, contrasting with Thanjavur''s severe tower; noted for massive monolithic dvarapalas and exquisite bronzes.', '2 hours', 'November to February', 'Combine with Darasuram and Kumbakonam for the full Great Living Chola Temples circuit. Very little shade - carry water and a hat.', 'no', 'Tamil Nadu', 0, 0, '6:02 AM', '6:04 PM', 'Free', 5, 5, 11.206433, 79.448352, 'Gangaikonda Cholapuram, Ariyalur district, Tamil Nadu 612901', 'https://asi.nic.in/pages/WorldHeritageCholaTemples', 1.0);

