INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000173, 839007, 'Swaminathaswamy Temple, Swamimalai', 'Swaminathaswamy Temple, Swamimalai', 'About 35 km from Thanjavur (5 km from Kumbakonam), one of the six Arupadaiveedu temples of Lord Murugan. Famous for the legend of Murugan expounding the meaning of ''Om'' to his father Shiva; the sanctum sits atop 60 steps representing the 60 Tamil years.', '1-2 hours', 'November to February', 'Climb the 60 steps barefoot like pilgrims; the evening aarti around 6-7 PM is atmospheric. Special darshan tickets (~Rs 100) reported for quicker access.', 'no', 'Tamil Nadu', 0, 0, '6:02 AM', '6:04 PM', 'Free', 4, 4, 10.9578, 79.3239, 'Swamimalai, Thanjavur district, Tamil Nadu 612302', NULL, 0.8);

