INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8390036, 839, 839007, 'Thyagaraja Aradhana', 'Jan-Feb', 'Annual Carnatic music festival at Thiruvaiyaru (~13 km from Thanjavur) honouring saint-composer Thyagaraja at his samadhi; the 176th aradhana''s Pancharatna rendition fell on 2023-01-11. Musicians from across the world perform the Pancharatna kritis in unison - the biggest classical music gathering in the region.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8390037, 839, 839007, 'Sathaya Vizha', 'Oct-Nov', 'Birth anniversary celebrations of Rajaraja Chola I at the Brihadisvara Temple, observed with special pujas and cultural programmes; the 1041st Sathaya Vizha fell around 2026-10-22 per published reports.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8390038, 839, 839007, 'Maha Shivaratri', 'Feb-Mar', 'The great night of Shiva, observed with night-long vigils and special abhishekams at the Brihadisvara Temple and Shiva temples across Thanjavur district.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8390039, 839, 839007, 'Pongal', 'Jan', 'Tamil Nadu''s harvest festival in mid-January (Thai month), celebrated across Thanjavur with the ritual boiling of rice, tributes to the sun and cattle, and family feasts.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8390040, 839, 839007, 'Navarathri', 'Sep-Oct', 'Nine-night festival honouring the goddess, celebrated at Amman temples including Punnainallur Mariamman with special alankarams, kolu displays in homes and cultural programmes.');

