INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 839000209, 'insert', 'bulk', 'Coordinates from geocoder (Lake Road). Hours and entry published on triphobo.com; cost varies widely across sources (Rs 40 TripHobo, Rs 100+ LBB, up to Rs 400-450 in reviews) - used conservative ''starts at Rs 100''. Lake created 1863 per Outlook Traveller; 60 acres per EarthTrip. No official website found.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000210, 839009, 'Coaker''s Walk', 'Coaker''s Walk', 'One-kilometre paved pedestrian promenade along the southern ridge of Kodaikanal, built in 1872 by Lieutenant Coaker. It runs along steep mountain slopes with telescopic viewpoints looking out over the plains, the Vaigai Dam and distant villages on clear mornings.', '1-2 hours', 'October to March, early mornings for clear valley views', 'Visit before 9 AM for the clearest views; mist rolls in later in the day and can block the plains view entirely.', 'no', 'Tamil Nadu', 1, 1, '6:10 AM', '6:20 PM', 'Rs 30', 5, 5, 10.2324, 77.49372, 'Pillar Rocks Road, Kodaikanal, Tamil Nadu 624101', NULL, 1.0);

