INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 839000210, 'insert', 'bulk', 'Coordinates from geocoder (Coaker''s Walk, Pillar Rocks Road). Built 1872 by Lt. Coaker confirmed by multiple travel sources. Hours and fee only from a tour-operator PDF, not an official source - treat as approximate. No official website.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000211, 839009, 'Bryant Park', 'Bryant Park', '20-acre botanical garden on the eastern side of Kodaikanal Lake, laid out in 1908 by H.D. Bryant, a British forest officer. It holds over 325 species of trees and plants, a glasshouse modelled on London''s Crystal Palace, a rose garden with 100+ varieties, and hosts the annual May flower show.', '1-2 hours', 'April to June, especially May for the flower show', 'Combine with the lake in one walk - the park sits right beside it; skip monsoon months when pathways get slippery.', 'no', 'Tamil Nadu', 0, 0, '6:10 AM', '6:20 PM', 'Rs 30', 4, 4, 10.23095, 77.49189, 'Lower Shola Road, Kodaikanal, Tamil Nadu 624101', NULL, 0.8);

