INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 839000211, 'insert', 'bulk', 'Coordinates from geocoder (Bryant Park, Noyce Road). Fee Rs 30 adult/Rs 15 child and 9 AM-6 PM hours consistent across kodaikanaltourism.co.in, crazyhodophile.in and holidayszone.in (one source said Rs 50 adult - older figure). Established 1908 by H.D. Bryant confirmed by multiple sources. No official website found.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000212, 839009, 'Pillar Rocks', 'Pillar Rocks', 'Three massive granite pillars, each about 122 metres (400 ft) tall, standing side by side above forested cliffs roughly 8 km from Kodaikanal Lake. A small fenced viewpoint park surrounds the rocks, and mist frequently shrouds the pillars, making mornings the best time to see them.', '1 hour', 'October to March, mornings or just after rain', 'Arrive before 10 AM - the pillars often disappear into mist by afternoon; watch your belongings around the monkeys here.', 'no', 'Tamil Nadu', 0, 0, '6:10 AM', '6:20 PM', 'Rs 5', 5, 4, 10.21099, 77.47518, 'Pillar Rocks Road, Kodaikanal, Tamil Nadu 624103', NULL, 0.92);

