INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 839000212, 'insert', 'bulk', 'Geocoder resolved only the nearby Golf Course entrance; coordinates marked approximate, within 1 km of the real viewpoint on Pillar Rocks Road. Fee conflicts: Rs 5 (airial.travel) vs Rs 20 (Wanderlog visitor reviews). 122 m height per Outlook Traveller; 400 ft per multiple sources. No official website.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000213, 839009, 'Guna Caves', 'Guna Caves (Devil''s Kitchen)', 'Deep, narrow natural caverns hidden between the Pillar Rocks and Green Valley, also called Devil''s Kitchen. Named after Kamal Haasan''s 1991 Tamil film Guna which was shot here; entry into the caves is strictly prohibited for safety, and visitors view them from a fenced platform at about 2,230 m elevation.', '1 hour', 'April to June; late morning after fog clears', 'Do not try to enter the caves or climb the fences - the trenches are genuinely dangerous; combine with Pillar Rocks in one trip.', 'no', 'Tamil Nadu', 0, 0, '6:10 AM', '6:20 PM', 'Rs 10', 4, 4, 10.2085, 77.4745, 'Pillar Rocks Road, Kodaikanal, Tamil Nadu 624103', NULL, 0.8);

