INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 839000213, 'insert', 'bulk', 'Geocoder returned a wrong town-centre point; coordinates placed near Pillar Rocks (caves sit between Pillar Rocks and Green Valley per sources) - approximate within 1 km. Fee conflict: Rs 10 (kodaikanaltourism.co.in) vs Rs 30 forest ticket covering the whole route (kodaikanaltravelogue.com, Sep 2026). Entry into caves prohibited - confirmed by multiple sources.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000214, 839009, 'Dolphin''s Nose', 'Dolphin''s Nose', 'Flat rocky cliff projecting over the valley in the shape of a dolphin''s nose, reached by a forest trek of about 1-3 km from the Vattakanal area. The trail passes Echo Point and offers sweeping views of the plains below; it is a favourite of trekkers and photographers.', '2-3 hours', 'October to March, mornings', 'Wear proper trekking shoes - the trail is steep and rocky; carry water as there are no shops on the route.', 'no', 'Tamil Nadu', 1, 1, '6:10 AM', '6:20 PM', NULL, 4, 5, 10.21297, 77.4866, 'Vattakanal, Kodaikanal, Tamil Nadu 624101', NULL, 0.88);

