INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000215, 839009, 'Silver Cascade Falls', 'Silver Cascade Falls', '180-foot waterfall on the Laws Ghat Road at the entrance to Kodaikanal, formed by the overflow of Kodaikanal Lake. It is a popular roadside stop for arriving and departing visitors, with refreshment stalls nearby; flow is strongest in the monsoon.', '30 minutes', 'June to September for full flow; avoid peak-monsoon heavy flow', 'Stop here on your way into or out of town - it needs no detour; do not attempt to climb the slippery rocks near the fall.', 'no', 'Tamil Nadu', 0, 0, '6:10 AM', '6:20 PM', NULL, 3, 3, 10.2389, 77.49643, 'Laws Ghat Road, Kodaikanal, Tamil Nadu 624101', NULL, 0.6);

