INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000216, 839009, 'Pine Forest', 'Pine Forest', 'Dense plantation of tall pine trees on the outskirts of Kodaikanal, popular for nature walks and film-style photography. The straight rows of pines create a calm, cinematic atmosphere and the forest floor stays cool even at midday.', '1 hour', 'October to March, late mornings', 'Go in the late morning for the best light filtering through the trees; stick to the main paths and avoid venturing deep alone.', 'no', 'Tamil Nadu', 0, 0, '6:10 AM', '6:20 PM', NULL, 3, 4, 10.23665, 77.50531, 'Kodaikanal, Tamil Nadu 624101', NULL, 0.68);

