INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000217, 839009, 'Shembaganur Museum of Natural History', 'Shembaganur Museum of Natural History', 'Natural history museum near the town entrance, founded in 1895 and maintained by Sacred Heart College, Kodaikanal. It displays taxidermy of over 500 animal species, a herbarium of 2,500 plant species, one of India''s best orchidoriums with around 300 orchid species, and Paliyar tribal artefacts.', '1-2 hours', 'Year-round; mornings 10-11 AM or afternoons 3-5 PM', 'Plan around the short visiting windows - the museum is only open 10-11 AM and 3-5 PM, so time your visit carefully.', 'no', 'Tamil Nadu', 0, 0, '6:10 AM', '6:20 PM', 'Rs 20', 3, 3, 10.23121, 77.50085, 'Shembaganur, Kodaikanal, Tamil Nadu 624101', NULL, 0.6);

