INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 839000217, 'insert', 'bulk', 'Coordinates consistent with Wikipedia infobox (10.23N, 77.5E). Established 1895 and Sacred Heart College ownership confirmed by Wikipedia. Entry Rs 20 from TripAdvisor rate-board photo. Hours 10-11 AM / 3-5 PM from Wikipedia; conflicts with a Justdial listing. No official website found.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000218, 839009, 'Kodaikanal Solar Observatory', 'Kodaikanal Solar Observatory', 'Historic solar observatory on Observatory Road run by the Indian Institute of Astrophysics, founded in 1899. It is where the Evershed effect was discovered; the campus museum displays historical telescopes, solar science exhibits and, on clear days, live solar images with sunspot viewing through special telescopes.', '1-2 hours', 'October to March, clear mornings for solar viewing', 'You need prior approval for a campus visit - write to the observatory in advance; walk-ins are not the norm.', 'yes', 'Tamil Nadu', 0, 0, '6:10 AM', '6:20 PM', 'Rs 50', 3, 4, 10.23028, 77.4639, 'Observatory Road, Kodaikanal, Tamil Nadu 624103', NULL, 0.68);

