INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000219, 839009, 'Moir Point', 'Moir Point', 'Scenic viewpoint on the Pillar Rocks Road, close to the Forest Department check post that regulates the road to Berijam Lake. Named after a British surveyor, it offers valley and plains views and is a standard stop on the Pillar Rocks sightseeing circuit.', '30 minutes', 'October to March, mornings', 'If you plan to continue to Berijam Lake, ask about permits here - the forest check post is right next to this point.', 'no', 'Tamil Nadu', 1, 1, '6:10 AM', '6:20 PM', NULL, 3, 3, 10.2105, 77.4755, 'Pillar Rocks Road, Kodaikanal, Tamil Nadu 624101', NULL, 0.6);

