INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000220, 839009, 'Green Valley View', 'Green Valley View', 'Deep gorge viewpoint on the Pillar Rocks Road with a sheer drop of about 5,000 ft to the plains below, also known as Suicide Point. The gorge fills with mist quickly, so the dramatic view appears and disappears within minutes; monkeys frequent the viewpoint.', '30-45 minutes', 'October to March, mornings before mist sets in', 'Stay well behind the fencing - the drop is real; do not carry food openly as monkeys snatch bags here.', 'no', 'Tamil Nadu', 1, 0, '6:10 AM', '6:20 PM', NULL, 4, 4, 10.21033, 77.47582, 'Pillar Rocks Road, Kodaikanal, Tamil Nadu 624101', NULL, 0.8);

