INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000221, 839009, 'Kurinji Andavar Temple', 'Kurinji Andavar Temple', 'Temple dedicated to Lord Murugan worshipped as Kurinji Andavar, on the outskirts of Kodaikanal town. The temple is closely associated with the Kurinji flower that blooms once in twelve years and carpets the surrounding Palani Hills in blue.', '1 hour', 'October to February; during a Kurinji bloom year the hills are spectacular', 'Dress modestly and remove footwear before entering, as with any active Hindu temple.', 'no', 'Tamil Nadu', 0, 0, '6:10 AM', '6:20 PM', NULL, 3, 3, 10.25297, 77.50192, 'Kodaikanal, Tamil Nadu 624101', NULL, 0.6);

