INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000222, 839009, 'Upper Lake View Point', 'Upper Lake View Point', 'Roadside viewpoint above the lake that gives a panoramic view of the star-shaped Kodaikanal Lake spread out below. It is a standard stop on the town sightseeing route and one of the few spots that clearly shows the lake''s star shape.', '20-30 minutes', 'Year-round, early morning for the clearest lake view', 'Best light for photos is morning when the sun is behind you and the lake is fully lit.', 'no', 'Tamil Nadu', 1, 0, '6:10 AM', '6:20 PM', NULL, 3, 3, 10.23011, 77.47572, 'Upper Lake View Road, Kodaikanal, Tamil Nadu 624101', NULL, 0.6);

