INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000223, 839009, 'Palani Murugan Temple', 'Arulmigu Dhandayuthapani Swamy Temple, Palani', 'Hill temple of Lord Murugan about 65 km from Kodaikanal, one of the most important Murugan shrines and the third of the six Padaiveedu abodes. Pilgrims climb 693 steps or take the winch/rope-car to the sanctum atop Sivagiri hill; it is a major day trip from Kodaikanal.', 'Half day (4-5 hours including travel)', 'November to February; avoid Thai Poosam crowds if you dislike long queues', 'Start from Kodaikanal early (before 7 AM) - the downhill drive takes about 2 hours and darshan queues grow through the morning.', 'no', 'Tamil Nadu', 0, 0, '6:10 AM', '6:20 PM', NULL, 5, 4, 10.59499, 77.45599, 'Palani, Dindigul District, Tamil Nadu 624617', NULL, 0.92);

