INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000224, 839009, 'Berijam Lake', 'Berijam Lake', 'Pristine reservoir about 21-23 km southwest of Kodaikanal inside a protected forest zone, with clear blue water ringed by shola forest. Entry is strictly regulated by the Tamil Nadu Forest Department: permits (about Rs 200 per car) are issued in person on the morning of the visit only, the route is closed on Tuesdays, and visitors must exit by mid-afternoon.', 'Half day (4-5 hours including permit and drive)', 'October to March; arrive at the permit office before 8:30 AM', 'Reach the Moonjikal Forest Department office before 8:30 AM with ID, driving licence, RC and pollution certificate - permits are limited and run out fast in season.', 'no', 'Tamil Nadu', 0, 0, '6:10 AM', '6:20 PM', 'Rs 200', 5, 5, 10.18404, 77.39437, 'Berijam, Kodaikanal, Tamil Nadu 624103', NULL, 1.0);

