INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000225, 839009, 'Mannavanur Lake', 'Mannavanur Lake', 'Quiet high-altitude lake about 30-35 km west of Kodaikanal near the village of Mannavanur, surrounded by rolling grasslands and shola forest. Far less crowded than Kodai Lake, it sits near the government sheep breeding farm and is popular with nature lovers and birdwatchers.', 'Half day (3-4 hours including travel)', 'October to March, mornings', 'Hire a local taxi for the day - public transport is limited and the road is scenic but winding.', 'no', 'Tamil Nadu', 1, 0, '6:10 AM', '6:20 PM', NULL, 3, 4, 10.22347, 77.3443, 'Mannavanur, Kodaikanal, Tamil Nadu 624103', NULL, 0.68);

