INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000226, 839009, 'Poombarai Village', 'Poombarai Village', 'Traditional village about 18 km west of Kodaikanal known for terraced vegetable farms and garlic cultivation. It is home to the ancient Kuzhanthai Velappar Temple dedicated to Lord Murugan, a centuries-old shrine set among the village''s stepped fields.', 'Half day (3-4 hours including travel)', 'October to March, daytime', 'Walk through the terraced farms with a local guide - the trails between fields are the best way to see the village.', 'no', 'Tamil Nadu', 0, 0, '6:10 AM', '6:20 PM', NULL, 3, 4, 10.225, 77.44614, 'Poombarai, Kodaikanal, Tamil Nadu 624103', NULL, 0.68);

