INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000227, 839009, 'Perumal Peak', 'Perumal Peak', 'The highest point in the Kodaikanal region at 2,234 metres (7,329 ft), about 18 km from town, dividing the upper and lower Palani Hills. A favourite trekking spot, the final ascent is a 1-2 hour hike/scramble from the vehicle-accessible base, with panoramic views of the Western Ghats from the summit.', 'Half day (4-5 hours including trek)', 'October to March; start the trek early morning', 'Go with a local guide and start by 7 AM - the trail is steep and rocky in parts and there are no facilities on the peak.', 'no', 'Tamil Nadu', 1, 1, '6:10 AM', '6:20 PM', NULL, 4, 5, 10.30028, 77.56583, 'Perumalmalai, Kodaikanal, Tamil Nadu', NULL, 0.88);

