INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000228, 839009, 'Kumbakkarai Falls', 'Kumbakkarai Falls', 'Two-stage waterfall on the Pambar River in the foothills of the Kodaikanal Hills, about 25 km from Kodaikanal town and 9 km from Periyakulam. Water collects in rock recesses named after animals at the first stage before falling as the main cascade; bathing is allowed and flow is year-round, heaviest in the monsoon.', '2-3 hours', 'October to March; avoid peak monsoon heavy flow', 'Carry a change of clothes if you plan to bathe; plastic and cosmetics are strictly banned inside this forest reserve.', 'no', 'Tamil Nadu', 0, 0, '6:10 AM', '6:20 PM', 'Rs 30', 3, 4, 10.18, 77.53056, 'Kumbakkarai, Theni District, Tamil Nadu', NULL, 0.68);

