INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000229, 839009, 'Cloud Street', 'Cloud Street', 'Wood-fired pizza cafe and restaurant on P.T. Road, operating since 2007 above the Sunday Market. Known for thin-crust pizzas, pasta, lasagna and desserts in a cosy rustic space with a fireplace; weekend live music is a regular feature.', '1-1.5 hours', 'Evenings for dinner; weekends for live music', 'Go on a non-Wednesday - the cafe is closed that day; try the wood-fired pizzas which are the signature.', 'no', 'Tamil Nadu', 0, 0, '6:10 AM', '6:20 PM', NULL, 4, 4, 10.236736, 77.49096, '1st Floor, Opposite Govt. Tourist Office, P.T. Road, Kodaikanal, Tamil Nadu 624101', 'http://www.cloudstreetcafe.com/', 0.8);

