INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 839000234, 'insert', 'bulk', 'Geocoder returned a mismatched business; coordinates approximate (P.T. Road town centre) within 1 km. Pizza/burger reputation from TripAdvisor and local taxi-guide listings. Hours and official website not found in published sources - left null. veg_flag false (not advertised pure-veg; serves burgers).', 'pipeline');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8390047, 839, 839009, 'Kodai Vizha (Kodaikanal Summer Festival)', 'May', 'Kodaikanal''s biggest annual celebration, a 10-day festival organised by the Tamil Nadu Tourism Department at Bryant Park. It features the famous flower show, boat races on Kodaikanal Lake, fruit shows, cultural programs with Bharatanatyam, Oyilattam and Mayilattam dances, food and craft stalls, and adventure sports.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8390048, 839, 839009, 'Flower Show at Bryant Park', 'May', 'The centrepiece of the summer festival, organised by the Department of Horticulture at Bryant Park. It showcases floral sculptures and topiary shaped like animals and famous figures, vegetable creations, and blooms brought from neighbouring villages competing for prizes.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8390049, 839, 839009, 'Pongal', 'mid-January', 'The four-day Tamil harvest festival (Bhogi, Surya Pongal, Mattu Pongal, Kanum Pongal) celebrated across Kodaikanal, dedicated to the Sun God Surya. Households cook the ritual pongal dish of rice, milk and jaggery, and cattle are decorated and honoured on Mattu Pongal.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8390050, 839, 839009, 'Tea and Tourism Festival', 'January', 'A winter festival in Kodaikanal where visitors sample many varieties of tea and enjoy authentic South Indian delicacies, celebrating the hill station''s tea culture and tourism.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8390051, 839, 839009, 'Neelakurinji Bloom', 'Oct-Nov (once every 12 years)', 'The rare Neelakurinji flower blooms only once every 12 years and carpets the Palani Hills around Kodaikanal in blue and purple. The bloom season draws botanists, nature lovers and tourists from across the world for a once-in-a-generation spectacle.');

-- city: Mahabalipuram (id 1040)
INSERT OR IGNORE INTO cities (id, state_id, city_name, latitude, longitude) VALUES (839010, 839, 'Mahabalipuram', 12.6269, 80.1927);

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000235, 839010, 'Shore Temple', 'Shore Temple', 'The Shore Temple is an 8th-century Pallava-era temple complex and part of the UNESCO World Heritage Group of Monuments at Mahabalipuram, built from granite blocks by Narasimhavarman II. It is one of the oldest structural stone temples in South India, with shrines dedicated to Shiva and Vishnu, standing on the Bay of Bengal shoreline. Sunrise and sunset views here are considered among the best in the town.', '2 hours', 'November to February, early morning', 'Arrive at the 6 AM opening for sunrise photos and to beat the midday heat.', 'yes', 'Tamil Nadu', 1, 1, '5:58 AM', '5:58 PM', 'Rs 40', 5, 5, 12.6165, 80.1985, 'Shore Temple Road, Mahabalipuram, Tamil Nadu 603104', NULL, 1.0);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (839000235, 839000235, '6:00 AM - 6:00 PM', '6:00 AM - 6:00 PM', '6:00 AM - 6:00 PM', '6:00 AM - 6:00 PM', '6:00 AM - 6:00 PM', '6:00 AM - 6:00 PM', '6:00 AM - 6:00 PM', 'ASI ticketed monument; one visitor review notes ticket counters stop issuing around 5:15 PM. Online ASI booking uses forenoon/afternoon slots.');

