INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 839000235, 'insert', 'bulk', 'Fee Rs 40 Indians / Rs 600 foreigners per published sources (ticketprice.in, dubaiuae.in); ticket covers all ASI monuments in town. Coordinates estimated within the Shore Temple complex, not from an official source. Hours 6 AM-6 PM reported across sources.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000236, 839010, 'Pancha Rathas', 'Pancha Rathas', 'Pancha Rathas are five monolithic rock-cut temples, each carved from a single granite outcrop, named after the Pandava brothers and Draupadi of the Mahabharata. Built in the 7th century under Pallava kings, each ratha experiments with a different Dravidian architectural form, making them a landmark of early South Indian temple design. They are part of the UNESCO World Heritage Group of Monuments at Mahabalipuram.', '1.5-2 hours', 'November to February, morning', 'Walk the full complex slowly; each of the five rathas has a distinct plan and carving style worth comparing.', 'yes', 'Tamil Nadu', 0, 0, '5:58 AM', '5:58 PM', 'Rs 40', 5, 5, 12.61, 80.1926, 'Five Rathas Road, Mahabalipuram, Tamil Nadu 603104', NULL, 1.0);

