INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000237, 839010, 'Arjuna''s Penance', 'Descent of the Ganges', 'Arjuna''s Penance, also called the Descent of the Ganges, is one of the world''s largest open-air bas-reliefs, carved across two massive granite boulders roughly 29 metres wide and 13 metres tall. The 7th-century Pallava panel depicts over a hundred figures of gods, sages, animals and celestial beings around a natural cleft through which water once flowed. It is a signature stop of the UNESCO monument group.', '1 hour', 'November to February, morning', 'Combine with the nearby cave temples; a local guide adds real value decoding the mythological figures.', 'yes', 'Tamil Nadu', 0, 0, '5:58 AM', '5:58 PM', 'Rs 40', 5, 5, 12.6185, 80.1945, 'Near E Raja Street, Mahabalipuram, Tamil Nadu 603104', NULL, 1.0);

