INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000238, 839010, 'Krishna''s Butter Ball', 'Krishna''s Butter Ball', 'Krishna''s Butter Ball is a giant natural granite boulder balanced precariously on a smooth rock slope near Ganesha Ratha. The boulder is several metres across and has rested in place for centuries, making it one of Mahabalipuram''s most photographed geological oddities. Local legend links it to Lord Krishna''s love of butter.', '30 minutes', 'November to February, morning or evening', 'A quick photo stop; pair it with Ganesha Ratha and the sculpture workshops nearby.', 'no', 'Tamil Nadu', 0, 0, '5:58 AM', '5:58 PM', 'Rs 40', 4, 4, 12.6158, 80.1941, 'E Raja St, Mahabalipuram, Tamil Nadu 603104', NULL, 0.8);

