INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 839000238, 'insert', 'bulk', 'Address ''E Raja St'' from a published place listing. Lies within the ASI monument zone so the common day ticket likely applies, but no source confirms a standalone ticket; cost reflects the shared ticket with a caveat.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000239, 839010, 'Varaha Cave Temple', 'Varaha Cave Temple', 'The Varaha Cave Temple is a 7th-century rock-cut mandapa from the reign of Narasimhavarman I, known for its well-preserved panels of Varaha (Vishnu''s boar avatar) lifting Bhudevi, and of Gajalakshmi. Its columned hall and sculpted shrines make it one of the finest and most intact cave temples of Mahabalipuram. It sits in the cave cluster near Arjuna''s Penance.', '30-45 minutes', 'November to February, morning', 'Visit together with the Trimurti Cave and Mahishasuramardini Cave in one walking loop.', 'yes', 'Tamil Nadu', 0, 0, '5:58 AM', '5:58 PM', 'Rs 40', 4, 4, 12.6179, 80.1953, 'Near Arjuna''s Penance, Mahabalipuram, Tamil Nadu 603104', NULL, 0.8);

