INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000240, 839010, 'Mahishasuramardini Cave', 'Mahishasuramardini Cave', 'The Mahishasuramardini Cave (Mahishasuramardini Mandapa) is a rock-cut shrine famous for its dramatic panel of goddess Durga slaying the buffalo demon Mahisha. It also houses a notable relief of Vishnu reclining on the serpent Ananta (Anantasayana). Carved in the 7th century, it stands on the hill below the lighthouse.', '30-45 minutes', 'November to February, morning', 'Climb the short rock steps above for the path to Olakkannesvara Temple and the new lighthouse.', 'yes', 'Tamil Nadu', 0, 0, '5:58 AM', '5:58 PM', 'Rs 40', 4, 4, 12.6162, 80.1946, 'Mamallapuram Hill, near Lighthouse, Mahabalipuram, Tamil Nadu 603104', NULL, 0.8);

