INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000241, 839010, 'Krishna Mandapam', 'Krishna Mandapam', 'Krishna Mandapam is a mid-7th-century rock-cut cave temple with one of the most vivid narrative panels in Mahabalipuram: Krishna lifting Govardhana hill to shelter villagers and cattle from Indra''s rains. The realism of the carved cows, villagers and the mountain made it a celebrated study of Pallava art. It lies in the cave cluster near Arjuna''s Penance.', '30 minutes', 'November to February, morning', 'Stand back to take in the full Govardhana panel; it reads like a stone storyboard.', 'yes', 'Tamil Nadu', 0, 0, '5:58 AM', '5:58 PM', 'Rs 40', 3, 4, 12.6177, 80.1939, 'Near Arjuna''s Penance, Mahabalipuram, Tamil Nadu 603104', NULL, 0.68);

