INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000242, 839010, 'Ganesha Ratha', 'Ganesha Ratha', 'Ganesha Ratha is a small monolithic temple carved from a single rock, dedicated to Lord Ganesha, standing close to Krishna''s Butter Ball. Dated to the mid-7th century reign of Mahendravarman I, it shows an early Pallava temple form with a distinctive apsidal plan. It is one of the oldest surviving rock-cut shrines in the town.', '30 minutes', 'November to February, morning', 'A quick stop paired with Krishna''s Butter Ball; the carved Shiva lingam inside is still worshipped.', 'yes', 'Tamil Nadu', 0, 0, '5:58 AM', '5:58 PM', 'Rs 40', 3, 3, 12.6157, 80.1938, 'Near Krishna''s Butter Ball, Mahabalipuram, Tamil Nadu 603104', NULL, 0.6);

