INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000243, 839010, 'Olakkannesvara Temple', 'Olakkannesvara Temple', 'Olakkannesvara Temple is a ruined 7th-century Shiva shrine on the summit of the Mamallapuram hill, attributed to Rajasimha (Narasimhavarman II). Beside it stands the Pallava-era stone lighthouse, one of India''s earliest navigational beacons, predating the British-built 1904 lighthouse nearby. The hilltop gives wide views over the town and the Bay of Bengal.', '45 minutes', 'November to February, late afternoon', 'Climb up in the late afternoon for sea views and breeze; wear sturdy shoes on the rock steps.', 'yes', 'Tamil Nadu', 0, 1, '5:58 AM', '5:58 PM', 'Rs 40', 3, 3, 12.6174, 80.1931, 'Mamallapuram Hill, near Lighthouse, Mahabalipuram, Tamil Nadu 603104', NULL, 0.6);

