INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000244, 839010, 'Raya Gopuram', 'Raya Gopuram', 'Raya Gopuram is an unfinished, large-scale gopuram carved partly from living rock, abandoned before completion and standing across from the main cave-temple cluster. Its massive uncarved mass gives visitors a rare look at the Pallava construction process mid-way. It is attributed to the Vijayanagara-era Raya rulers by local tradition.', '20-30 minutes', 'November to February, morning', 'A quick photo stop on the cave-temple walking circuit; interpretive signage is minimal.', 'no', 'Tamil Nadu', 0, 0, '5:58 AM', '5:58 PM', NULL, 2, 3, 12.619, 80.1951, 'E Raja St, Mahabalipuram, Tamil Nadu 603104', NULL, 0.48);

