INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000245, 839010, 'Mahabalipuram Lighthouse and Maritime Heritage Museum', 'Mahabalipuram Lighthouse and Maritime Heritage Museum', 'The modern Mahabalipuram Lighthouse, built by the British in 1904 with a 26-metre masonry tower, is the tallest structure in town and open to visitors for panoramic views of the monuments, town and Bay of Bengal up to Kovalam. The adjoining Maritime Heritage Museum and lighthouse museum display naval artefacts and the region''s seafaring history. Entry is a nominal Rs 10.', '1-1.5 hours', 'November to February, morning or evening', 'Visiting is closed on Mondays and the counter closes midday 1:00-2:30 PM; visitors get limited time at the top due to crowds.', 'yes', 'Tamil Nadu', 1, 1, '5:58 AM', '5:58 PM', 'Rs 10', 4, 4, 12.616306, 80.192539, 'Mahabalipuram Light House, Madha Kovil St, Mahabalipuram, TN, IN', NULL, 0.8);

