INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 839000245, 'insert', 'bulk', 'Address and coordinates from a published place listing (12.616306, 80.192539). Timings 10-1 and 2:30-5:30 with Monday holiday per Sep 2026 DGLL-timing writeup; an older tourism site lists 10-12:30 / 2-4:45, so verify before travel. Fee Rs 10 Indian / Rs 25 foreigner base, excluding GST.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000246, 839010, 'Mahabalipuram Beach', 'Mahabalipuram Beach', 'Mahabalipuram Beach is the town''s main golden-sand beach on the Bay of Bengal, stretching north of the Shore Temple toward the fishing colony. Visitors come for sunrise walks, evening sunsets, and to watch fishermen bring in the day''s catch. Surfing schools operate on the beach, and seafood shacks line the Othavadai Street end.', '2-3 hours', 'November to February, sunrise or evening', 'Swim only in designated stretches; the surf can be rough and lifeguard coverage is patchy.', 'no', 'Tamil Nadu', 1, 1, '5:58 AM', '5:58 PM', 'Free', 3, 3, 12.626, 80.1977, 'Mahabalipuram Beach, near Othavadai St, Mahabalipuram, Tamil Nadu 603104', NULL, 0.6);

