INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000247, 839010, 'Sthalasayana Perumal Temple', 'Sthalasayana Perumal Temple', 'The Sthalasayana Perumal Temple at Thirukadalmallai is one of the 108 Divya Desams, dedicated to Vishnu reclining on Adisesha, and is considered the birthplace of the saint-poet Bhoothathazhwar. It is among the oldest Vaishnavite shrines on this coast, predating or contemporary with the Pallava monuments. Its Masi Magam festival draws thousands to the Mahabalipuram beach.', '1 hour', 'November to February, morning', 'Dress modestly and remove footwear; photography inside the sanctum is restricted.', 'no', 'Tamil Nadu', 0, 0, '5:58 AM', '5:58 PM', 'Free', 3, 3, 12.6233, 80.193, 'Thirukadalmallai, Mahabalipuram, Tamil Nadu 603104', NULL, 0.6);

