INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000248, 839010, 'Government Sculpture Museum', 'Government Sculpture Museum', 'The Government Sculpture Museum on East Raja Street, attached to the Government College of Architecture and Sculpture, holds around 3,000 sculptures in stone, wood, brass, bronze and cement. The collection spans Pallava-era pieces, Hindu and Buddhist imagery, and contemporary student work, including miniature replicas of Mahabalipuram''s monuments. It is a good primer on the town''s living stone-carving tradition.', '1 hour', 'November to February, daytime', 'Pair with a walk through the sculpture workshops on East Raja Street where artisans carve on commission.', 'no', 'Tamil Nadu', 0, 0, '5:58 AM', '5:58 PM', NULL, 3, 3, 12.615808, 80.193656, 'Government College of Architecture and Sculpture, East Raja Street, Mahabalipuram, Tamil Nadu 603104', NULL, 0.6);

