INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000249, 839010, 'Tiger Cave', 'Tiger Cave', 'Tiger Cave at Salavankuppam is a 7th-8th-century rock-cut shrine complex about 4 km north of Mahabalipuram on the East Coast Road. Its main mandapa is framed by carved tiger heads, with elephant figures flanking the front, and a small beach lies just behind the complex. It is an ASI-protected monument and a quieter alternative to the main town sites.', '1 hour', 'November to February, morning', 'Combine with the Crocodile Bank, which is on the same ECR stretch a little further north.', 'no', 'Tamil Nadu', 0, 0, '5:58 AM', '5:58 PM', NULL, 3, 3, 12.6504, 80.2159, 'Salavankuppam, East Coast Road, Chengalpattu district, Tamil Nadu 603104', NULL, 0.6);

