INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000250, 839010, 'Madras Crocodile Bank Trust', 'Madras Crocodile Bank Trust and Centre for Herpetology', 'The Madras Crocodile Bank Trust, founded in 1976 by Romulus Whitaker and Zai Whitaker, is one of the world''s largest reptile zoos, spread over 8.5 acres with 15 of the world''s 25 crocodilian species. Located about 25 km north of Mahabalipuram on the ECR, it draws close to half a million visitors a year and runs conservation breeding, snake-venom demonstrations and night safaris. It is closed on Mondays.', '2-3 hours', 'November to February, morning', 'Go on a non-Monday; carry water since food options inside are limited, and allow an hour for the snake-venom demo.', 'no', 'Tamil Nadu', 0, 0, '5:58 AM', '5:58 PM', 'Rs 100', 4, 4, 12.743406, 80.238704, 'Post Bag 4, Mahabalipuram, Tamil Nadu 603104', 'https://madrascrocodilebank.org/', 0.8);

