INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000251, 839010, 'DakshinaChitra Heritage Museum', 'DakshinaChitra Heritage Museum', 'DakshinaChitra is a living heritage museum about 26 km north of Mahabalipuram at Muttukadu, showcasing traditional houses, crafts and village life from Tamil Nadu, Kerala, Karnataka and Andhra Pradesh. Artisans demonstrate weaving, pottery and other crafts, and the campus hosts cultural performances and workshops. It is closed on Tuesdays.', '3-4 hours', 'October to February, morning', 'Allow at least 3 hours; check the day''s craft-demonstration and performance schedule at the entrance.', 'no', 'Tamil Nadu', 0, 0, '5:58 AM', '5:58 PM', NULL, 4, 4, 12.8686, 80.237, 'SH 49, Muthukadu, Tamil Nadu 603112', NULL, 0.8);

