INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000252, 839010, 'Muttukadu Backwaters and Boat House', 'Muttukadu Backwaters and Boat House', 'Muttukadu is a backwater lagoon about 22 km north of Mahabalipuram on the ECR, where the TTDC-run boat house offers rowboat, pedal-boat and speedboat rides plus windsurfing. The calm estuary lined with casuarina groves is a popular picnic and photography stop. A TTDC restaurant at the boat house serves light refreshments.', '2-3 hours', 'November to February, afternoon', 'Reach by mid-afternoon; boating is weather-dependent and queues build on weekends.', 'no', 'Tamil Nadu', 0, 1, '5:58 AM', '5:58 PM', NULL, 3, 3, 12.8234, 80.2416, 'Muttukadu Boat House, East Coast Road, Tamil Nadu 603112', NULL, 0.6);

