INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000253, 839010, 'Covelong Beach', 'Covelong Beach', 'Covelong (Kovalam) Beach is a crescent-shaped beach about 20 km north of Mahabalipuram on the ECR, known for surfing, windsurfing and jet-skiing. The fishing village behind the beach keeps a working-harbour character, and several surf schools operate on the sand. It is the usual sunset and water-sports add-on to a Mahabalipuram trip.', '2-3 hours', 'November to February, evening', 'Book surf lessons with a school on the beach rather than swimming far out; currents can be strong.', 'no', 'Tamil Nadu', 0, 1, '5:58 AM', '5:58 PM', 'Free', 3, 4, 12.7919, 80.2516, 'Kovalam (Covelong), East Coast Road, Chengalpattu district, Tamil Nadu 603112', NULL, 0.68);

