INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000254, 839010, 'Sadras Dutch Fort', 'Sadras Dutch Fort', 'Sadras Fort at Kalpakkam, about 18 km south of Mahabalipuram, is a 17th-century Dutch East India Company fort built around 1612, one of the earliest Dutch settlements on the Coromandel Coast. The brick-and-stone ruins with bastions and a cemetery are an ASI-protected monument in a quiet coastal setting. It is a short, low-crowd heritage detour.', '1-2 hours', 'November to February, morning', 'Carry water and sun protection; shade and facilities at the fort are minimal.', 'no', 'Tamil Nadu', 0, 0, '5:58 AM', '5:58 PM', NULL, 3, 3, 12.5258, 80.1697, 'Sadras, Kalpakkam, Chengalpattu district, Tamil Nadu 603102', NULL, 0.6);

