INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000255, 839010, 'Moonrakers Restaurant', 'Moonrakers Restaurant', 'Moonrakers is one of Mahabalipuram''s oldest and best-known seafood restaurants, a long-running institution on Othavadai Street near the fishermen''s colony. It serves fresh catch cooked in South Indian and Chettinad styles; diners can pick their seafood (fish, crab, calamari, lobster) and have it prepared to order. The vibe is vintage and unpretentious, with reasonable prices for the quality.', '1-1.5 hours', 'Lunch or dinner, November to February', 'Ask to see the day''s fresh catch and confirm the price per dish before ordering, as seafood pricing can be market-based.', 'no', 'Tamil Nadu', 0, 0, '5:58 AM', '5:58 PM', NULL, 4, 4, 12.619596, 80.196289, '34, Othavadai St, Mahabalipuram, Tamil Nadu 603104', NULL, 0.8);

