INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000256, 839010, 'Bob Marley Cafe and Beach House', 'Bob Marley Cafe and Beach House', 'Bob Marley Cafe and Beach House is a beachfront cafe and guesthouse on Othavadai Street, popular with backpackers for its sea-facing rooms and open-air dining. The kitchen serves Mangalorean-style seafood such as butter-garlic prawns, snapper fish fry and calamari curry alongside cafe fare. Reviews are mixed on pricing and service but consistently praise the location and food.', '1-1.5 hours', 'Evening, November to February', 'Check the bill against menu prices carefully; some reviewers report discrepancies.', 'no', 'Tamil Nadu', 1, 0, '5:58 AM', '5:58 PM', NULL, 4, 3, 12.6205, 80.198168, '182, Othavadai St, Mahabalipuram, Tamil Nadu 603104', NULL, 0.72);

