INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000257, 839010, 'Madras Chronicle', 'Madras Chronicle', 'Madras Chronicle is a 100% vegetarian garden restaurant on Shore Temple Road, describing itself as a ''Taste of Madras'' concept with continental, Italian, Mexican, Chinese and South Indian dishes. It is known for its ambience, pizza and family-friendly dining, and is one of the few upscale vegetarian options near the monuments. Its official website confirms the vegetarian positioning.', '1-1.5 hours', 'Lunch or dinner', 'Good pick for vegetarians near the Shore Temple; try the wood-fired pizza and continental plates.', 'no', 'Tamil Nadu', 0, 0, '5:58 AM', '5:58 PM', NULL, 4, 4, 12.616607, 80.194272, 'New No 2, Old No 210, Shore Temple Road, Mahabalipuram, Tamil Nadu 603104', 'https://madraschronicle.in/', 0.8);

