INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000258, 839010, 'Le Yogi', 'Le Yogi', 'Le Yogi is a well-known Franco-Indian cafe near the Shore Temple, serving vegetarian and non-vegetarian dishes across European, Nepali, North Indian and South Indian cuisines, plus pizzas, pastas, momos and sizzlers. It is popular for its healthy breakfast menu of smoothies, milkshakes and fresh juices, and is listed as vegan-friendly.', '1 hour', 'Breakfast or lunch', 'Go for breakfast; the smoothie and fresh-juice menu is a standout for the town.', 'no', 'Tamil Nadu', 0, 0, '5:58 AM', '5:58 PM', NULL, 4, 4, 12.618, 80.1955, 'Near Shore Temple, Mahabalipuram, Tamil Nadu 603104', NULL, 0.8);

