INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000259, 839010, 'Hotel Mamalla Bhavan', 'Hotel Mamalla Bhavan', 'Hotel Mamalla Bhavan is a long-running pure-vegetarian restaurant near the Sthalasayana Perumal Temple on S Mada Street, operating since 1966. It serves budget-friendly South Indian vegetarian food including dosas and idlis, often on banana leaves, and is a convenient walk from the monuments. It is a family dining staple for vegetarian visitors.', '45 minutes - 1 hour', 'Breakfast or lunch', 'Come for breakfast dosa/idli; it is one of the cheapest full meals near the monuments.', 'no', 'Tamil Nadu', 0, 0, '5:58 AM', '5:58 PM', NULL, 3, 4, 12.6183, 80.1925, 'S Mada St, near Sthala Sayana Perumal Temple, Mahabalipuram, Tamil Nadu 603104', NULL, 0.68);

