INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (839000260, 839010, 'Sea Rock Restaurant', 'Sea Rock Restaurant', 'Sea Rock Restaurant is a beachside seafood restaurant on GKM Street in the fishermen''s colony, listed among Mahabalipuram''s local non-vegetarian seafood options. It serves fresh fish and seafood preparations in South Indian style, close to the main beach. It is a smaller local alternative to the better-known Othavadai Street seafood shacks.', '1 hour', 'Lunch or dinner', 'Confirm the day''s catch and price before ordering; smaller local spots cook to order.', 'no', 'Tamil Nadu', 0, 0, '5:58 AM', '5:58 PM', NULL, 3, 3, 12.617, 80.196, '123, GKM Street, Fisherman Colony (beach side), Mahabalipuram, Tamil Nadu 603104', NULL, 0.6);

