INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8390052, 839, 839010, 'Mamallapuram Dance Festival', 'Dec-Jan', 'Annual 30-day classical dance festival organised by the Tamil Nadu Tourism Department, held on an open-air stage against the Shore Temple and Arjuna''s Penance backdrop. Features Bharatanatyam, Kuchipudi, Kathakali, Mohiniyattam, Odissi and Kathak exponents plus folk dancers, typically on weekends from late December into January.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8390053, 839, 839010, 'Pongal', 'Jan', 'Tamil Nadu''s harvest festival, celebrated in mid-January (Thai month) with the ritual boiling of rice with jaggery and milk, tributes to the sun and cattle, and family feasts. Tourist offices organise celebrations for visitors; it overlaps with the dance festival season in Mahabalipuram.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8390054, 839, 839010, 'Masi Magam', 'Feb-Mar', 'Tamil festival on the Magam nakshatra of the Masi month. At Mahabalipuram it has two faces: the Thirukadalmallai (Sthalasayana Perumal) temple takes the deities in grand procession to the beach for a ceremonial sea bath, and thousands of Irular tribal families gather on the shore for a week of rituals, music and dance by the sea.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8390055, 839, 839010, 'Sthalasayana Perumal Chithirai Festival', 'Apr-May', 'The principal annual brahmotsavam of the Sthalasayana Perumal (Thirukadalmallai) Temple, held in the Tamil month of Chithirai, with processions, special pujas and decorated deity parades through the town.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (8390056, 839, 839010, 'Tamil New Year (Puthandu)', 'Apr', 'The Tamil New Year in mid-April, observed across Tamil Nadu including Mahabalipuram with temple visits, festive meals and family gatherings marking the start of the Chithirai month.');

