--
-- Each hub: 20 attractions + 5 restaurants
-- Total: 150 places = 120 attractions + 30 restaurants
--
-- country_name = India
-- country_code = IN
-- state_name = West Bengal
-- state_code = WB
-- google_place_id = NULL on all rows pending Google Places API access.
--
-- Verification policy:
-- * Attraction identity is grounded primarily in West Bengal Tourism official
--   destination material/current destination inventories.
-- * Restaurant identity/current presence is grounded in September 2026 listings.
