INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000001, 320001, 'Cellular Jail National Memorial', 'Cellular Jail National Memorial', 'The Cellular Jail (Kala Pani), built by the British between 1896 and 1906, was the colonial prison used to exile political prisoners to the Andamans; freedom fighters including Vinayak Damodar Savarkar, Batukeshwar Dutt and Yogendra Shukla were incarcerated here. Today it is a national memorial with preserved cells, a gallery of the freedom movement, and an evening light-and-sound show narrating its history. Located in Sri Vijaya Puram (formerly Port Blair) near the harbour.', '2-3 hours', 'November to February', 'Attend the evening light-and-sound show for the full story; buy show tickets early as evening slots sell out in peak season.', 'yes', 'Andaman and Nicobar Islands', 0, 1, '5:25 AM', '5:20 PM', 'Rs 30', 5, 5, 11.6747, 92.7479, 'Rajiv Gandhi Rd, Sri Vijaya Puram, Andaman and Nicobar Islands 744101', NULL, 1.0);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (320000001, 320000001, 'Closed', '9:00 AM - 12:30 PM, 1:30 PM - 4:45 PM', '9:00 AM - 12:30 PM, 1:30 PM - 4:45 PM', '9:00 AM - 12:30 PM, 1:30 PM - 4:45 PM', '9:00 AM - 12:30 PM, 1:30 PM - 4:45 PM', '9:00 AM - 12:30 PM, 1:30 PM - 4:45 PM', '9:00 AM - 12:30 PM, 1:30 PM - 4:45 PM', 'Closed on national holidays; hours from southandaman.nic.in which lists no Monday hours (treated as closed Monday). Some travel sites claim open all days - confirm locally.');

