INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 320000001, 'insert', 'bulk', 'Real, visitable. Hours conflict: govt site southandaman.nic.in omits Monday (assumed closed); andamanislands.com says open all days except national holidays. Entry Rs 30 widely published; light-and-sound show prices conflict (Rs 50 vs Rs 300 reported) so not included. Sunrise/sunset times computed for lat 11.62, lng 92.73 IST; vary +/-20 min by month.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000002, 320001, 'Ross Island (Netaji Subhas Chandra Bose Island)', 'Ross Island (Netaji Subhas Chandra Bose Island)', 'Ross Island, renamed Netaji Subhas Chandra Bose Dweep in 2018, was the administrative headquarters of the British in the Andamans, once called the ''Paris of the East''. Today its colonial buildings - church, printing press, Chief Commissioner''s house - stand in jungle-clad ruins, home to wild spotted deer. Reached by a 10-15 minute ferry from Aberdeen Jetty / Rajiv Gandhi Water Sports Complex in Port Blair (now Sri Vijaya Puram).', 'Half day (3-4 hours)', 'October to April', 'Combine Ross Island with North Bay Island on one ferry ticket; carry photo ID - it is mandatory for bookings and transfers.', 'yes', 'Andaman and Nicobar Islands', 0, 1, '5:25 AM', '5:20 PM', 'Rs 470 (round-trip ferry); island entry ~Rs 30', 5, 4, 11.6767, 92.7716, 'Ross Island, Sri Vijaya Puram, Andaman and Nicobar Islands 744104 (ferry from Aberdeen Jetty)', NULL, 0.92);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (320000002, 320000002, '9:00 AM - 5:00 PM', '9:00 AM - 5:00 PM', 'Closed', '9:00 AM - 5:00 PM', '9:00 AM - 5:00 PM', '9:00 AM - 5:00 PM', '9:00 AM - 5:00 PM', 'Boats depart roughly 8:30 AM - 2:00/4:00 PM from Aberdeen Jetty / Water Sports Complex; closed Wednesdays per multiple sources. Last return boats around 4-5 PM. Schedules published by ferry operators vary - confirm at the jetty.');

