INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 320000002, 'insert', 'bulk', 'Real, visitable. Ferry price Rs 470/person (Ross only) and combined Rs 870 with North Bay from discoverandaman.in; entry ~Rs 30-50 from other sources. Coordinates approximate for island center (~1 km radius). Sunrise/sunset computed for lat 11.62, lng 92.73; vary by season.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000003, 320001, 'North Bay Island', 'North Bay Island', 'North Bay Island is the water-sports hub near Sri Vijaya Puram (Port Blair), known for coral reefs, snorkeling, glass-bottom boat rides, sea walking and scuba diving. There is no island entry fee; costs are for the ferry from the Rajiv Gandhi Water Sports Complex and the activities. Ferries to North Bay typically leave in the morning and return by mid-afternoon.', 'Half day (3-4 hours)', 'October to May', 'Book on the first morning boat to avoid crowds; buy activity tickets from official counters and carry cash - digital payments may not work on the island.', 'yes', 'Andaman and Nicobar Islands', 0, 0, '5:25 AM', '5:20 PM', 'Rs 0 (island); round-trip boat ~Rs 870 with Ross Island', 4, 4, 11.7078, 92.7473, 'North Bay Island, off Sri Vijaya Puram (boat from Rajiv Gandhi Water Sports Complex)', NULL, 0.8);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (320000003, 320000003, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'No officially published daily hours; island is open during daylight. Ferries depart ~9:00 AM and return ~3:00 PM; water activities run daylight hours. Timings vary by operator and season - confirm at the jetty.');

