INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000004, 320001, 'Corbyn''s Cove Beach', 'Corbyn''s Cove Beach', 'Corbyn''s Cove is the closest beach to Sri Vijaya Puram (formerly Port Blair), about 7-9 km from the city centre, lined with coconut palms on a crescent shoreline. It offers swimming in shallow areas, jet skiing, parasailing and sea karting, plus food stalls and souvenir shops. Entry to the beach is free; water sports and parking are charged.', '2-3 hours', 'October to March', 'Go in the late afternoon for the best light and sunset; swim only in shallow areas and heed lifeguards - currents can be strong beyond the shallows.', 'no', 'Andaman and Nicobar Islands', 1, 1, '5:25 AM', '5:20 PM', 'Rs 0', 4, 4, 11.6445, 92.7499, 'Corbyn''s Cove, Sri Vijaya Puram, Andaman and Nicobar Islands 744101', NULL, 0.8);

