INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000005, 320001, 'Samudrika Naval Marine Museum', 'Samudrika Naval Marine Museum', 'Samudrika, run by the Indian Navy near Haddo in Sri Vijaya Puram (Port Blair), documents the Andaman and Nicobar Islands under history, geography, people, marine life and archaeology. Highlights include a blue-whale skeleton, coral and shell collections, and exhibits on the islands'' tribes and naval heritage. ''Samudrika'' derives from ''Samudra'', meaning sea.', '1-2 hours', 'October to March', 'Avoid Mondays - the museum is closed; combine with the nearby Cellular Jail and Anthropological Museum for a half-day museum circuit.', 'no', 'Andaman and Nicobar Islands', 0, 0, '5:25 AM', '5:20 PM', 'Rs 50', 3, 4, 11.6635, 92.7468, 'Haddo Road, Sri Vijaya Puram, Andaman and Nicobar Islands 744102', NULL, 0.68);

