INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000006, 320001, 'Anthropological Museum (Zonal)', 'Anthropological Museum (Zonal)', 'The Zonal Anthropological Museum in Sri Vijaya Puram (Port Blair), maintained by the Anthropological Survey of India, exhibits the life and culture of the islands'' six indigenous tribes - Onges, Jarawas, Sentinelese, Great Andamanese, Shompens and Nicobarese - through tools, weapons, canoes, ornaments and photographs. Established in 1975, it is a compact 1-hour visit near Phoenix Bay on MG Road.', '1 hour', 'October to March', 'Photography and videography are generally not permitted inside; arrive at least 90 minutes before closing and carry a photo ID.', 'no', 'Andaman and Nicobar Islands', 0, 0, '5:25 AM', '5:20 PM', 'Rs 10', 3, 3, 11.6646, 92.7402, 'MG Road, Phoenix Bay, Sri Vijaya Puram, Andaman and Nicobar Islands 744101', NULL, 0.6);

