INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000007, 320001, 'Chatham Saw Mill', 'Chatham Saw Mill', 'Chatham Saw Mill, on Chatham Island connected to Sri Vijaya Puram (Port Blair) by a 100-metre bridge, began operations in 1883 and is described as Asia''s oldest and largest continuously operational sawmill. Run by the Forest Department, it processes prized Andaman timber such as padauk and houses a Forest Museum plus World War II bomb craters from Japanese bombing.', '1-2 hours', 'October to March', 'Go in the morning - the mill only admits visitors in the first half of the day; it is an active industrial site so expect noise.', 'no', 'Andaman and Nicobar Islands', 0, 0, '5:25 AM', '5:20 PM', 'Rs 10', 3, 3, 11.687, 92.7287, 'Chatham Island, Sri Vijaya Puram, Andaman and Nicobar Islands 744102', NULL, 0.6);

