INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000008, 320001, 'Mahatma Gandhi Marine National Park (Wandoor / Jolly Buoy)', 'Mahatma Gandhi Marine National Park (Wandoor / Jolly Buoy)', 'Mahatma Gandhi Marine National Park, ~25-30 km south of Sri Vijaya Puram (Port Blair) at Wandoor, is a 281 sq km marine protected area of 15 islands. Only Jolly Buoy and Red Skin islands are open to tourists, offering glass-bottom boat rides, snorkeling and pristine beaches over live coral. Permits are limited (about 150 per day, first-come) and collected at Wandoor Jetty; it is a no-plastic zone.', 'Full day (6-7 hours incl. travel)', 'November to May', 'Reach Wandoor Jetty by 8:15 AM for the 9 AM boats - permits are first-come first-served and run out in peak season; carry packed lunch, nothing is available on the island.', 'yes', 'Andaman and Nicobar Islands', 0, 0, '5:25 AM', '5:20 PM', 'Rs 50 (entry); boat Rs 650 per person (Jolly Buoy)', 5, 5, 11.5898, 92.6088, 'Wandoor Jetty, Sri Vijaya Puram tehsil, South Andaman 744301', NULL, 1.0);

