INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000009, 320001, 'Chidiya Tapu (Bird Island)', 'Chidiya Tapu (Bird Island)', 'Chidiya Tapu, about 25 km south of Sri Vijaya Puram (Port Blair) at the southern tip of South Andaman, is the islands'' best-known sunset point, with mangrove forests, rich birdlife and the Munda Pahad trek. The beach and sunset point are free; swimming is not advised due to rocky shores and saltwater crocodile warnings. The nearby Chidiya Tapu Biological Park is ticketed.', '3-4 hours (afternoon + sunset)', 'October to March', 'Arrive by 4 PM for a good sunset spot; pre-book return transport - there is no public transport back after dark and the road is poorly lit.', 'no', 'Andaman and Nicobar Islands', 1, 1, '5:25 AM', '5:20 PM', 'Rs 0 (beach); Biological Park ~Rs 20', 4, 4, 11.516, 92.694, 'Chidiya Tapu, South Andaman, Sri Vijaya Puram 744105', NULL, 0.8);

