INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000010, 320001, 'Fisheries Museum (Fisheries Museum-cum-Aquarium)', 'Fisheries Museum (Fisheries Museum-cum-Aquarium)', 'The Fisheries Museum near the Rajiv Gandhi Water Sports Complex in Sri Vijaya Puram (Port Blair) displays marine species, corals and shells of the Andaman and Nicobar waters, with small aquarium tanks. It is a compact, educational half-hour stop popular with families and students, and is one of the cheapest ticketed attractions in town.', '30 minutes - 1 hour', 'October to March', 'Pair it with the Water Sports Complex and Marina Park in one visit; note it is closed on Mondays and second Saturdays.', 'no', 'Andaman and Nicobar Islands', 0, 0, '5:25 AM', '5:20 PM', 'Rs 5', 2, 3, 11.672, 92.7468, 'Near Rajiv Gandhi Water Sports Complex, Sri Vijaya Puram 744104', NULL, 0.48);

