INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000011, 320001, 'Aberdeen Bazaar', 'Aberdeen Bazaar', 'Aberdeen Bazaar is the main commercial market street of Sri Vijaya Puram (Port Blair), the island capital''s shopping heart for clothes, electronics, groceries and local snacks. It is also the transport hub - the central bus stand at Mohanpura and the Aberdeen Jetty for island ferries are nearby. A practical stop for supplies between sightseeing.', '1-2 hours', 'October to March', 'Shop in the evening when the market is liveliest; fix auto-rickshaw fares before boarding - there are no meters.', 'no', 'Andaman and Nicobar Islands', 0, 0, '5:25 AM', '5:20 PM', NULL, 2, 3, 11.6227, 92.7278, 'Aberdeen Bazaar, Sri Vijaya Puram, Andaman and Nicobar Islands 744101', NULL, 0.48);

