INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000012, 320001, 'Sagarika Emporium', 'Sagarika Emporium', 'Sagarika is the government-run handicrafts emporium (ANIHDC) on MG Road in Sri Vijaya Puram (Port Blair), selling authentic Andamanese handicrafts at fixed prices - shell ornaments, coconut-shell lamps, padauk wood carvings, cane and bamboo work, and Nicobari beadwork. It is the reliable spot for genuine souvenirs supporting local artisans.', '1 hour', 'October to March', 'Prices are fixed and fair - no bargaining needed; visit in the morning for a quieter browse.', 'no', 'Andaman and Nicobar Islands', 0, 0, '5:25 AM', '5:20 PM', 'Rs 0', 3, 3, 11.6239, 92.7268, 'MG Road, DAG Colony, Sri Vijaya Puram, Andaman and Nicobar Islands 744101', NULL, 0.6);

