INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000013, 320001, 'Rajiv Gandhi Water Sports Complex', 'Rajiv Gandhi Water Sports Complex', 'The Rajiv Gandhi Water Sports Complex at Marina Park in Sri Vijaya Puram (Port Blair) is the city''s waterfront promenade and water-sports hub, named after the former PM who visited in 1987. It hosts jet skiing, parasailing, banana rides, snorkeling, scuba diving, sea walking and glass-bottom boats, plus a children''s park, cafeteria and souvenir shops. Entry to the complex is free; activities are ticketed.', '2-4 hours', 'October to March', 'Do water activities in the morning (8 AM-12 PM) when the sea is calmest; buy tickets only from official counters for proper receipts and refunds.', 'no', 'Andaman and Nicobar Islands', 1, 1, '5:25 AM', '5:20 PM', 'Rs 0', 4, 4, 11.6701, 92.7461, 'Marina Park Road, Sri Vijaya Puram, Andaman and Nicobar Islands 744101', NULL, 0.8);

