INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000014, 320001, 'Flag Point', 'Flag Point', 'Flag Point, on the road to Corbyn''s Cove Beach, marks the historic spot where Netaji Subhas Chandra Bose hoisted the national flag on December 30, 1943, declaring the Andaman and Nicobar Islands the first liberated territory of India. A giant 150-foot Tricolour now flies here, dedicated in 2018. It is an open public viewpoint with sea views, liveliest in the evening.', '30 minutes - 1 hour', 'October to March', 'Visit in the evening for sunset photos with the giant Tricolour; it pairs well as a stop on the way to Corbyn''s Cove Beach.', 'no', 'Andaman and Nicobar Islands', 0, 1, '5:25 AM', '5:20 PM', NULL, 3, 3, 11.66, 92.748, 'Corbyn''s Cove Road, Sri Vijaya Puram, Andaman and Nicobar Islands 744101', NULL, 0.6);

