INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000015, 320001, 'Jogger''s Park', 'Jogger''s Park', 'Jogger''s Park at AHW Colony, Shadipur, is a popular public fitness park in Sri Vijaya Puram (Port Blair) with jogging tracks, open lawns and panoramic views of the airport and harbour. Locals use it for morning runs, yoga and evening walks; tourists visit for sunrise and sunset views and plane-spotting. Entry is free.', '1-2 hours', 'October to March', 'Go at sunrise for the best views and local atmosphere; photographing the airport runway itself is not permitted.', 'no', 'Andaman and Nicobar Islands', 1, 1, '5:25 AM', '5:20 PM', 'Rs 0', 2, 3, 11.6488, 92.7348, 'AHW Colony, Shadipur, Sri Vijaya Puram, Andaman and Nicobar Islands 744101', NULL, 0.48);

