INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000016, 320001, 'Japanese Bunkers (Corbyn''s Cove)', 'Japanese Bunkers (Corbyn''s Cove)', 'World War II-era Japanese bunkers stand along the Corbyn''s Cove Beach area in Sri Vijaya Puram (Port Blair), remnants of the Japanese occupation of the Andamans from March 1942 to October 1945. The concrete pillboxes and gun emplacements, set among the palms near the beach, are a quiet heritage stop for history buffs visiting Corbyn''s Cove.', '30 minutes', 'October to March', 'Combine with a Corbyn''s Cove beach visit; the bunkers are easy to miss - ask a local or auto driver for the exact spot.', 'no', 'Andaman and Nicobar Islands', 0, 1, '5:25 AM', '5:20 PM', 'Rs 0', 2, 3, 11.6452, 92.7502, 'Near Corbyn''s Cove Beach, Sri Vijaya Puram, Andaman and Nicobar Islands 744101', NULL, 0.48);

