INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000017, 320001, 'Viper Island', 'Viper Island', 'Viper Island, a 20-minute boat ride from Phoenix Bay Jetty in Sri Vijaya Puram (Port Blair), was the site of the old British jail before the Cellular Jail was built, with a hilltop gallows used for executions. Named after the vessel HMS Viper that brought Lt. Archibald Blair to the Andamans in 1789, its ruins are now a quiet picnic and heritage spot. There is no entry fee; the only cost is the boat fare.', '1-2 hours', 'October to May', 'Visit in the morning to avoid the harsh afternoon sun; carry water and sun protection - there are no eateries on the island.', 'yes', 'Andaman and Nicobar Islands', 0, 1, '5:25 AM', '5:20 PM', 'Rs 75 (ferry; island free)', 3, 3, 11.6599, 92.7001, 'Viper Island, off Phoenix Bay Jetty, Sri Vijaya Puram, Andaman and Nicobar Islands', NULL, 0.6);

