INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000018, 320001, 'Mount Harriet National Park', 'Mount Harriet National Park (now Mount Manipur)', 'Mount Harriet, the highest point in South Andaman and now officially Mount Manipur, offers panoramic views of Sri Vijaya Puram (Port Blair), Ross Island and Havelock from its viewpoint. Reached via ferry from Chatham Jetty to Bamboo Flat and a road climb, the park has nature trails, watchtowers and the Kala Pathar viewpoint. It is about 55 km by road or 15 km by sea from the city.', 'Half day (3-4 hours)', 'October to March', 'Take the morning ferry from Chatham Jetty to Bamboo Flat (~15 min), then a taxi up; start early and plan to be back down by late afternoon.', 'no', 'Andaman and Nicobar Islands', 1, 1, '5:25 AM', '5:20 PM', 'Rs 25', 3, 4, 11.7167, 92.7333, 'Hope Town / Bamboo Flat side, Sri Vijaya Puram, South Andaman 744107', NULL, 0.68);

