INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000019, 320001, 'Baratang Island (Limestone Caves & Mud Volcano)', 'Baratang Island (Limestone Caves & Mud Volcano)', 'Baratang Island, about 100 km north of Sri Vijaya Puram (Port Blair) by the Andaman Trunk Road, is the classic full-day trip for the limestone caves - stalactite and stalagmite formations reached by speedboat through mangrove creeks - and the mud volcano, described as India''s only active one. The road convoy passes through the Jarawa Tribal Reserve, where stopping and photography are strictly prohibited. Permits are handled by tour operators; Indians need only photo ID.', 'Full day (10-12 hours)', 'November to April', 'Start before dawn (3:30-4 AM) to catch the first convoy at Jirkatang; carry a small torch for the caves and do not photograph anything inside the tribal reserve.', 'yes', 'Andaman and Nicobar Islands', 0, 0, '5:25 AM', '5:20 PM', 'Rs 900 (speedboat to Limestone Caves)', 4, 4, 12.1187, 92.7959, 'Nilambur Jetty / Baratang, Middle Andaman, Andaman and Nicobar Islands 744201', NULL, 0.8);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (320000019, 320000019, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'No published gate hours; the trip is convoy-driven. Convoy gates at Jirkatang commonly 6 AM / 9 AM / 12 PM / 3 PM. Day tours ~Rs 1,500-2,500/person all-in; private cab ~Rs 4,500-6,000 - operator prices, vary.');

