INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000020, 320001, 'Kalapani Museum', 'Kalapani Museum', 'Kalapani Museum at Garacharma II in Sri Vijaya Puram (Port Blair) is a private museum showcasing the history of the Andaman and Nicobar Islands through dioramas, photographs and films, including archival material on the Japanese occupation of 1942-1945. Ticketed entry includes a guide, photography charges and tea or coffee. It is open seven days a week, 9 AM to 7 PM.', '1-2 hours', 'October to March', 'Call ahead to confirm it is open on your day; the entry fee includes a guided tour, so take it - it adds a lot of context.', 'no', 'Andaman and Nicobar Islands', 0, 0, '5:25 AM', '5:20 PM', NULL, 2, 3, 11.6108, 92.7162, 'Garacharma II, ATR, Sri Vijaya Puram, Andaman and Nicobar Islands', NULL, 0.48);

