INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000021, 320001, 'New Lighthouse Restaurant', 'New Lighthouse Restaurant', 'New Lighthouse Restaurant at Marina Park near the Rajiv Gandhi Water Sports Complex in Sri Vijaya Puram (Port Blair) is a long-running seafood spot known for its daily-catch dishes like red snapper tawa fry and Chinese-style lobster. Reviews note knowledgeable waiters who help pick from the fresh catch; cash or UPI payments only.', '1-2 hours', 'October to March', 'Ask the waiter for the day''s fresh catch recommendation - that is the strength of the place; carry cash/UPI as cards are not accepted.', 'no', 'Andaman and Nicobar Islands', 0, 1, '5:25 AM', '5:20 PM', NULL, 3, 3, 11.6716, 92.7465, 'Marina Park, Rajiv Gandhi Nagar, Sri Vijaya Puram, Andaman and Nicobar Islands 744104', NULL, 0.6);

