INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000022, 320001, 'Amaya', 'Amaya', 'Amaya is the rooftop restaurant and bar at SeaShell Hotel on Marine Hill in Sri Vijaya Puram (Port Blair), known for live barbecued and grilled seafood, fusion of international and Indian cuisines, live music and city-wide views. It is one of the top-rated evening spots in town, with standouts like garlic lobster and sizzlers.', '2-3 hours', 'October to March', 'Go for dinner to get the rooftop views with live music; reserve on weekends and dry days - it is a popular evening venue.', 'yes', 'Andaman and Nicobar Islands', 0, 1, '5:25 AM', '5:20 PM', NULL, 4, 4, 11.6692, 92.7388, 'SeaShell Hotel, Marine Hill, Sri Vijaya Puram, Andaman and Nicobar Islands 744104', NULL, 0.8);

