INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000023, 320001, 'Annapurna Cafeteria Pure Veg', 'Annapurna Cafeteria Pure Veg', 'Annapurna Cafeteria Pure Veg, opposite Model School on MA Road at Aberdeen Bazaar in Sri Vijaya Puram (Port Blair), is the town''s best-known pure-vegetarian restaurant, serving dosas, idlis, vadas, thalis, North Indian curries and Chinese options. Budget-friendly and open daily 7 AM to 10 PM, it is a local favourite for breakfast and casual family meals.', '30-60 minutes', 'Year-round', 'Try the masala dosa breakfast or a veg thali (around Rs 250-400); it gets crowded at peak hours, so go slightly off-peak.', 'no', 'Andaman and Nicobar Islands', 0, 0, '5:25 AM', '5:20 PM', NULL, 3, 4, 11.6671, 92.7423, '71, MA Rd, opp. Model School, Aberdeen Bazaar, Sri Vijaya Puram, Andaman and Nicobar Islands 744101', NULL, 0.68);

