INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000024, 320001, 'Adi Bengali Hotel', 'Adi Bengali Hotel', 'Adi Bengali Hotel on MA Road at Phoenix Bay in Sri Vijaya Puram (Port Blair) is a no-frills Bengali eatery serving home-style fish curry, rice and Bengali meals. A favourite with locals and budget travellers, it is the place for an authentic, cheap Bengali lunch near the Phoenix Bay jetty area.', '45 minutes - 1 hour', 'Year-round', 'Order the fish curry with rice - the Bengali preparation is the draw; expect simple, canteen-style seating.', 'no', 'Andaman and Nicobar Islands', 0, 0, '5:25 AM', '5:20 PM', NULL, 2, 3, 11.6684, 92.737, '60, MA Rd, Phoenix Bay, Sri Vijaya Puram, Andaman and Nicobar Islands 744101', NULL, 0.48);

