INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000025, 320001, 'Mandalay Restaurant', 'Mandalay Restaurant', 'Mandalay Restaurant, inside the Fortune Resort Bay on Marine Hill in Sri Vijaya Puram (Port Blair), serves Indian, Asian and Chinese fare including a popular buffet drawing both Indian and foreign tourists. Reviewers praise the spicy chicken curry, Chinese stir-fried vegetables and dragon fruit juice; it does not serve alcohol.', '1-2 hours', 'October to March', 'Go for the buffet if you want variety - the spread suits families and groups; confirm current buffet availability when booking.', 'no', 'Andaman and Nicobar Islands', 0, 0, '5:25 AM', '5:20 PM', NULL, 2, 3, 11.668, 92.7395, 'Fortune Resort Bay, Marine Hill, Sri Vijaya Puram, Andaman and Nicobar Islands 744101', NULL, 0.48);

