INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000026, 320001, 'Sea Food Delights', 'Sea Food Delights (Rooftop Seaview Restaurant)', 'Sea Food Delights is a rooftop seafood restaurant on MA Road in Sri Vijaya Puram (Port Blair) offering grilled whole fish, fish curry, crispy prawns and other seafood with a panoramic sea view. Moderately priced and popular for dinner, it is a solid alternative to the Marina Park seafood spots.', '1-2 hours', 'October to March', 'Book an evening table for the rooftop sea view; confirm the day''s specials with the staff before ordering.', 'no', 'Andaman and Nicobar Islands', 0, 1, '5:25 AM', '5:20 PM', NULL, 2, 3, 11.6688, 92.7336, 'MA Rd, Sri Vijaya Puram, Andaman and Nicobar Islands', NULL, 0.48);

