INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3200001, 320, 320001, 'Island Tourism Festival', 'January', 'The flagship annual cultural festival of the Andaman and Nicobar Islands, organised by the A&N Administration in Sri Vijaya Puram (Port Blair), featuring folk dances, music performances, food stalls, handicraft exhibitions and water-sports events.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3200002, 320, 320001, 'Subhas Mela', 'January', 'Annual week-long fair held at Swaraj Dweep (Havelock), commemorating Netaji Subhas Chandra Bose''s association with the islands; includes cultural programmes, exhibitions and local food stalls.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3200003, 320, 320001, 'Beach Festival', 'April', 'Annual festival centred on the beaches of Sri Vijaya Puram such as Corbyn''s Cove, with beach sports, cultural shows, sand-sculpture and entertainment programmes organised by the tourism department.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3200004, 320, 320001, 'Monsoon Music Festival', 'August', 'Annual music festival held in Sri Vijaya Puram (Port Blair) during the monsoon season, featuring local and mainland artists performing across genres.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3200005, 320, 320001, 'World Tourism Day celebrations', 'September', 'The A&N Tourism Department organises events and special programmes across Sri Vijaya Puram and the islands to mark World Tourism Day, including cultural shows and guided heritage walks.');

