INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000027, 320002, 'Radhanagar Beach', 'Radhanagar Beach (Beach No. 7)', 'Radhanagar Beach, locally known as Beach No. 7, is the flagship beach of Swaraj Dweep (formerly Havelock Island) on the island''s western coast, about 12 km from Havelock Jetty. It was named ''Best Beach in Asia'' by Time magazine in 2004 and holds Blue Flag certification for cleanliness, safety and environmental management. No motorised water sports are allowed, so the beach stays calm and quiet, and it is famous for its long stretch of powdery white sand, turquoise water and sunsets.', '3-4 hours', 'October to May', 'Reach by late afternoon to swim first and stay for sunset; carry cash as card networks are patchy and ATMs unreliable.', 'no', 'Andaman and Nicobar Islands', 0, 1, '5:08 AM', '5:09 PM', NULL, 5, 5, 11.982, 92.964, 'Beach No. 7, Radhanagar, Swaraj Dweep (Havelock Island), 744211', NULL, 1.0);

