INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 320000027, 'insert', 'bulk', 'Entry is free (no ticket counter); small parking fee may apply — published on andamantourism.org. Coordinates 11.982, 92.964 are from Wikipedia. Hours not published; beaches open sunrise to sunset per travel guides. Still widely called Havelock Island by locals and ferry operators.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000028, 320002, 'Elephant Beach', 'Elephant Beach', 'Elephant Beach on the northwest coast of Swaraj Dweep (Havelock Island) is the island''s main water-sports hub, reached by a 20-30 minute speedboat ride from Havelock Jetty or a ~2 km forest trek. Its shallow fringing coral reef starts barely 30 metres from the sand, making it the easiest-access snorkeling in the Andamans. Activities on offer include snorkeling, scuba diving, sea walking, parasailing, jet skiing, glass-bottom boat rides and banana boats.', '4-5 hours (half day)', 'October to May', 'Activities run roughly 11 AM to 4 PM; arrive early because you only get about 3 hours on the beach and all activities share the slot.', 'yes', 'Andaman and Nicobar Islands', 0, 1, '5:08 AM', '5:09 PM', 'Rs 1,000', 5, 4, 12.0125, 92.9355, 'Northwest coast, Swaraj Dweep (Havelock Island), 744211', NULL, 0.92);

