INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 320000028, 'insert', 'bulk', 'Boat cost ~Rs 1,000/person round trip published on andamanbliss.com (bookyourferry.com lists Rs 1,250 incl. snorkeling dip). Coordinates are approximate (within ~1 km of published reef position); flagged as approximate. Activity prices vary by vendor and season.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000029, 320002, 'Kalapathar Beach', 'Kalapathar Beach', 'Kalapathar Beach on the eastern shore of Swaraj Dweep (Havelock Island) is named for the black rocks (kala pathar) lining its shore, creating a dramatic contrast with the white sand and turquoise water. It is one of the island''s best sunrise beaches and is ideal for peaceful morning walks and photography. Swimming is discouraged due to strong currents and rocky patches.', '1-2 hours', 'October to May', 'Go at sunrise for the best light; avoid swimming here and stick to the shore walk.', 'no', 'Andaman and Nicobar Islands', 1, 0, '5:08 AM', '5:09 PM', NULL, 4, 4, 11.978, 92.9955, 'Eastern shore, Swaraj Dweep (Havelock Island), 744211', NULL, 0.8);

