INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000030, 320002, 'Vijaynagar Beach', 'Vijaynagar Beach (Beach No. 5)', 'Vijaynagar Beach, known locally as Beach No. 5, is a long stretch of white sand on the east coast of Swaraj Dweep (Havelock Island) near Vijaynagar village. It is quieter than Radhanagar and Elephant Beach, with calm clear water, fringing mahua trees, and good conditions for swimming, beachcombing and bird watching. The beachfront area has some of the island''s popular cafes and eateries.', '2-3 hours', 'October to May', 'Good for a relaxed swim and a meal nearby; combine with a visit to the cafes along Beach No. 5.', 'no', 'Andaman and Nicobar Islands', 1, 0, '5:08 AM', '5:09 PM', NULL, 4, 4, 12.021, 93.009, 'Beach No. 5, Vijaynagar, Swaraj Dweep (Havelock Island), 744211', NULL, 0.8);

