INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000031, 320002, 'Govind Nagar Beach', 'Govind Nagar Beach (Beach No. 3)', 'Govind Nagar Beach, locally Beach No. 3, is a long crescent of powder-soft sand on the eastern shoreline of Swaraj Dweep (Havelock Island), fronting the island''s main village and its cafes, dive stores and homestays. It has shallow swimmable water year round, a fringe reef with parrotfish and clownfish, and a vivid sunrise; knee-deep ruins of a WWII pier can be seen in the lagoon. This is also where several scuba operators run beginner dives, including at Nemo Reef.', '2-3 hours', 'October to May', 'Ideal for a sunrise swim or a morning dive; the village market and cheap dhabas are a short walk away.', 'no', 'Andaman and Nicobar Islands', 1, 0, '5:08 AM', '5:09 PM', NULL, 4, 4, 12.03, 92.997, 'Beach No. 3, Govind Nagar, Swaraj Dweep (Havelock Island), 744211', NULL, 0.8);

