INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000032, 320002, 'Neil''s Cove', 'Neil''s Cove', 'Neil''s Cove is a small secluded lagoon about 1 km north of Radhanagar Beach on Swaraj Dweep (Havelock Island), reached by a 15-20 minute walk past a rocky corner of the main beach. The lagoon has shallow, transparent water, unusual eroded rock formations and colourful fish, and is known for snorkeling at low tide. Sources advise against swimming at dawn and dusk because saltwater crocodiles have been sighted, and against visiting alone.', '1-2 hours', 'October to May', 'Visit only at low tide and in daylight, never alone; carry all water and supplies as there are no shops nearby.', 'no', 'Andaman and Nicobar Islands', 0, 1, '5:08 AM', '5:09 PM', NULL, 3, 4, 11.9885, 92.9625, 'North end of Radhanagar Beach, Swaraj Dweep (Havelock Island), 744211', NULL, 0.68);

