INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000033, 320002, 'Aquarium Dive Site', 'Aquarium (Scuba Dive Site)', 'Aquarium is one of Swaraj Dweep''s (Havelock Island''s) best-known beginner dive sites, a fringing reef about 3 km offshore from Elephant Beach in 6-14 m of water. The reef is dense with hard and soft corals and schooling reef fish — clownfish, parrotfish, moray eels — with occasional reef sharks, in excellent visibility. It is widely used for Discover Scuba Diving (DSD) try-dives and Open Water training.', '2-3 hours (with boat ride)', 'October to May', 'Book with a PADI/SSI-certified dive centre; beginners can do a no-certification Discover Scuba dive with an instructor.', 'yes', 'Andaman and Nicobar Islands', 0, 0, '5:08 AM', '5:09 PM', NULL, 4, 5, 12.031, 92.918, 'Offshore (~3 km from Elephant Beach), Swaraj Dweep (Havelock Island), 744211', NULL, 0.88);

