INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 320000033, 'insert', 'bulk', 'Named dive site published by multiple dive guides (traveltriangle, indiamap, slideserve). Coordinates are estimated from ''3 km offshore from Elephant Beach''; flagged as approximate. No official operator prices — vendor rates vary by season (traveler reports suggest ~Rs 3,500 shore / ~Rs 5,500 boat dives); cost left null.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000034, 320002, 'Scuba Diving at Elephant Beach', 'Scuba Diving at Elephant Beach', 'Scuba diving near Elephant Beach is aimed at first-time and novice divers on Swaraj Dweep (Havelock Island), with shallow shore dives and boat dives over the beach''s fringing reef. Certified PADI/SSI centres on the island run Discover Scuba Diving sessions with an instructor for non-swimmers, while experienced divers head to deeper offshore sites like Aquarium and Dickson''s Pinnacle. The season runs roughly October to May when visibility is best.', '3-4 hours', 'October to May', 'You do not need to know swimming for a Discover Scuba dive; book a day ahead in peak season as slots fill.', 'yes', 'Andaman and Nicobar Islands', 0, 0, '5:08 AM', '5:09 PM', NULL, 4, 5, 12.0125, 92.9355, 'Elephant Beach, Swaraj Dweep (Havelock Island), 744211', NULL, 0.88);

