INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 320000034, 'insert', 'bulk', 'No operator names included per instructions; only generic activity. Traveler-reported pricing (~Rs 3,500 shore dive / ~Rs 5,500 boat dive) found in one Tripadvisor review but is vendor-dependent, so cost left null. Coordinates same as Elephant Beach (approximate).', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000035, 320002, 'Mangrove Kayaking', 'Mangrove Kayaking (Havelock Jetty)', 'Daytime mangrove kayaking on Swaraj Dweep (Havelock Island) starts near Havelock Jetty and paddles into narrow emerald creeks flanked by dense mangrove roots. Guides point out mudskippers, fiddler crabs and kingfishers, and explain how the mangroves protect the island''s coastline. It is beginner-friendly, needs no swimming skill, and life jackets and briefings are provided.', '1.5-2.5 hours', 'October to May', 'Wear quick-dry clothes and bring insect repellent; morning sessions are calmer and cooler.', 'yes', 'Andaman and Nicobar Islands', 1, 0, '5:08 AM', '5:09 PM', 'Rs 2,500-3,500', 4, 4, 12.0413, 92.9826, 'Near Havelock Jetty, Swaraj Dweep (Havelock Island), 744211', NULL, 0.8);

