INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 320000035, 'insert', 'bulk', 'Mangrove kayaking from near Havelock Jetty confirmed on peek.com and world-tourism.org. Price band Rs 2,500-3,500/person published on traveltriangle (2026 guide). Coordinates estimated from jetty area; flagged as approximate.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000036, 320002, 'Bioluminescent Night Kayaking', 'Bioluminescent Night Kayaking', 'On dark, moonless nights on Swaraj Dweep (Havelock Island), paddling the sheltered waters near the jetty sets off flashes of blue-green light from plankton (Noctiluca scintillans), leaving glowing trails behind each paddle stroke. Guided pre-dawn tours typically start around 3:00-3:30 AM and end at sunrise, and operators also run evening slots after sunset. The glow is brightest in the calm November-to-February window, near the new moon.', '1.5-2 hours (pre-dawn)', 'November to February', 'Book for a night close to the new moon — moonlight washes out the glow; personal cameras are usually not allowed on night tours.', 'yes', 'Andaman and Nicobar Islands', 1, 0, '5:08 AM', '5:09 PM', 'Rs 3,500', 4, 5, 12.0413, 92.9826, 'Near Havelock Jetty, Swaraj Dweep (Havelock Island), 744211', NULL, 0.88);

