INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 320000036, 'insert', 'bulk', 'Rs 3,500/person published on andamanbliss.com (all taxes incl.). Pre-dawn schedule (3:00-3:30 AM start, ~2 hours) confirmed on tropicalandamans.com and andamanbliss.com. Glow is a living phenomenon and not guaranteed — noted per source honesty.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000037, 320002, 'Elephant Beach Forest Trek', 'Elephant Beach Forest Trek', 'The alternative, budget way to reach Elephant Beach on Swaraj Dweep (Havelock Island) is a ~2 km trek through coastal forest starting from the trailhead past the Radhanagar road, about 8 km from Havelock Jetty. The easy-moderate walk takes 40-60 minutes each way through tropical greenery and is free; an optional local guide costs a few hundred rupees. The trail can be muddy after rain and may close in monsoon.', '2-3 hours round trip', 'October to May', 'Wear proper footwear with grip and start early — the trail gets muddy after rain and the final stretch can flood at high tide.', 'no', 'Andaman and Nicobar Islands', 0, 0, '5:08 AM', '5:09 PM', NULL, 3, 4, 12.005, 92.945, 'Trailhead off Radhanagar road (~8 km from Havelock Jetty), Swaraj Dweep, 744211', NULL, 0.68);

