INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000038, 320002, 'Sea Walk at Elephant Beach', 'Sea Walking at Elephant Beach', 'Sea walking at Elephant Beach lets visitors walk on the ocean floor in a special helmet that supplies air, watching coral and reef fish up close without any swimming or diving skill. It is one of the fixed-price activities sold at the Elephant Beach counter, alongside snorkeling, parasailing and jet skiing. Traveler reports list the price around Rs 3,200 plus a photo/video charge.', '45 minutes - 1 hour', 'October to May', 'Book your activities at the Havelock Jetty ticket counter before boarding — boats allow only about 3 hours on the beach.', 'yes', 'Andaman and Nicobar Islands', 0, 0, '5:08 AM', '5:09 PM', NULL, 3, 4, 12.0125, 92.9355, 'Elephant Beach, Swaraj Dweep (Havelock Island), 744211', NULL, 0.68);

