INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 320000038, 'insert', 'bulk', 'Activity published on Tripadvisor''s Elephant Beach page. Price (~Rs 3,200) appears only in traveler reviews and varies by vendor, so cost left null. Coordinates same as Elephant Beach (approximate).', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000039, 320002, 'Parasailing at Elephant Beach', 'Parasailing at Elephant Beach', 'Parasailing is offered at Elephant Beach as one of its signature paid activities, lifting riders for a high-altitude view over the reef and the turquoise bay. Traveler reports list the price around Rs 3,200 for about 3 minutes of flight, with an optional photo/video charge; operators do not dip riders in the water for safety reasons. It is sold alongside sea walking, snorkeling and jet skiing at the Elephant Beach activity counter.', '30 minutes (incl. wait)', 'October to May', 'Book early in your 3-hour beach slot and carry cash — some activities at the beach counter sell only on cash.', 'yes', 'Andaman and Nicobar Islands', 0, 0, '5:08 AM', '5:09 PM', NULL, 3, 4, 12.0125, 92.9355, 'Elephant Beach, Swaraj Dweep (Havelock Island), 744211', NULL, 0.68);

