INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000040, 320002, 'Glass-Bottom Boat Ride at Elephant Beach', 'Glass-Bottom Boat Ride at Elephant Beach', 'The glass-bottom boat ride at Elephant Beach lets non-swimmers and families see the shallow coral reef and reef fish through a viewing hull without getting wet. Tickets are sold at the Havelock Jetty or at the Elephant Beach counter alongside other water activities. It is one of the gentler ways to experience the reef, suitable for children and older travelers.', '30-45 minutes', 'October to May', 'Good fallback if the sea is too choppy for snorkeling; book at the jetty counter before boarding.', 'yes', 'Andaman and Nicobar Islands', 0, 0, '5:08 AM', '5:09 PM', NULL, 3, 3, 12.0125, 92.9355, 'Elephant Beach, Swaraj Dweep (Havelock Island), 744211', NULL, 0.6);

