INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000041, 320002, 'Market No. 3', 'Market No. 3, Govind Nagar', 'Market No. 3 in Govind Nagar is the main local market of Swaraj Dweep (Havelock Island), with shops selling souvenirs such as sea-shell and wooden jewellery, plus fresh fruit, vegetables and fish. It is also the practical heart of the island with vegetable and fish markets, small shops, cheap dhabas, petrol sellers, banks and ATMs. Several souvenir shops line the main street opposite Beach 2 resorts.', '1-2 hours', 'October to May', 'Combine with an evening stroll through Govind Nagar village; withdraw cash here as ATMs elsewhere are unreliable.', 'no', 'Andaman and Nicobar Islands', 0, 0, '5:08 AM', '5:09 PM', NULL, 3, 3, 12.033, 92.994, 'Govind Nagar, Swaraj Dweep (Havelock Island), 744211', NULL, 0.6);

