INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000042, 320002, 'Sagarika Emporium at Radhanagar Beach', 'Sagarika Emporium (Radhanagar Beach)', 'Sagarika Emporium is a government-run handicraft stall inside the Radhanagar Beach premises on Swaraj Dweep (Havelock Island), selling authentic local crafts and souvenirs. Being inside the beach complex, it is a convenient stop for picking up fixed-price local items before or after swimming and the sunset. A larger Sagarika Emporium also operates in Port Blair.', '30 minutes', 'October to May', 'Shop here for fixed, government-set prices before bargaining at beachside stalls.', 'no', 'Andaman and Nicobar Islands', 0, 0, '5:08 AM', '5:09 PM', NULL, 2, 3, 11.982, 92.964, 'Radhanagar Beach premises, Swaraj Dweep (Havelock Island), 744211', NULL, 0.48);

