INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000043, 320002, 'Inglis Island Day Trip', 'Inglis Island Day Trip', 'Inglis Island is an uninhabited island about 35 km (1.5-2 hours by boat) from Swaraj Dweep (Havelock Island), run as a day-trip excursion from Havelock Jetty. Travelers describe it as Havelock''s best-kept secret: white-sand beaches, rocky shores and a rock arch, very rich snorkeling with colourful corals and marine life, and a short jungle trail. Trips are seasonal and sea-condition dependent.', 'Full day', 'October to February', 'Go in a group with a registered operator and pack all food and water — there are no facilities on the island.', 'yes', 'Andaman and Nicobar Islands', 0, 0, '5:08 AM', '5:09 PM', NULL, 3, 5, 12.138, 93.1, 'Offshore (~35 km from Havelock Jetty), Swaraj Dweep (Havelock Island), 744211', NULL, 0.76);

