INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 320000043, 'insert', 'bulk', 'Distance (~35 km, 1.5-2 hrs) published on havelockislandbeachresort.com; snorkeling quality from multiple Tripadvisor reviews. Coordinates are a rough island-position estimate; flagged as approximate. No reliable published price for day trips — cost left null.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000044, 320002, 'Shaheed Dweep (Neil Island) Day Trip', 'Shaheed Dweep (Neil Island) Day Trip', 'Shaheed Dweep, still widely called Neil Island, lies about 15 km from Swaraj Dweep (Havelock Island) in Ritchie''s Archipelago and makes a popular day trip by inter-island ferry (about 45-60 minutes). The quieter island offers Laxmanpur Beach''s famous sunset point, Bharatpur Beach''s coral reefs, Sitapur Beach and the natural rock bridge (Howrah Bridge). Travelers often describe it as the slower, more laid-back alternative to Havelock.', 'Full day', 'November to March', 'Book the inter-island ferry in advance in peak season and target Laxmanpur Beach for sunset before the return sailing.', 'yes', 'Andaman and Nicobar Islands', 0, 1, '5:08 AM', '5:09 PM', NULL, 4, 4, 11.832, 93.037, 'Shaheed Dweep (Neil Island), Ritchie''s Archipelago, 744104', NULL, 0.8);

