INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000045, 320002, 'Port Blair Day Trip (Cellular Jail, Ross Island)', 'Port Blair Day Trip (Cellular Jail and Ross Island)', 'Port Blair, officially Sri Vijaya Puram, is about 41 km by sea from Swaraj Dweep (Havelock Island) and makes a long but rewarding day trip by morning ferry. Highlights include the Cellular Jail (Kaala Paani) national memorial with its evening light-and-sound show, Ross Island''s colonial-era ruins and spotted deer, and North Bay''s coral reefs. Government and private ferries connect Havelock with Haddo/Phoenix Bay jetties in 1.5-2.5 hours.', 'Full day', 'October to May', 'Take the earliest ferry out and the evening ferry back; book both ferries a day ahead in peak season.', 'yes', 'Andaman and Nicobar Islands', 0, 0, '5:08 AM', '5:09 PM', NULL, 3, 4, 11.623, 92.726, 'Port Blair (Sri Vijaya Puram), South Andaman, 744101', NULL, 0.68);

