INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000046, 320002, 'Baratang Island Day Trip (Limestone Caves)', 'Baratang Island Day Trip (Limestone Caves)', 'Baratang Island, roughly 100 km by sea-and-road from Swaraj Dweep (Havelock Island), is a full-day excursion combining a ferry crossing with a drive through the Jarawa tribal reserve forest. The main sights are the limestone caves reached via a mangrove-creek boat ride and the Parrot Island sunset point where thousands of parakeets return at dusk. Trips leave very early in the morning with government convoy timings.', 'Full day (early start)', 'October to May', 'This is a dawn-to-dusk trip with reserve convoy rules — go with a registered operator and carry ID.', 'yes', 'Andaman and Nicobar Islands', 0, 0, '5:08 AM', '5:09 PM', NULL, 2, 4, 12.1, 92.78, 'Baratang Island, Middle Andaman, 744201', NULL, 0.56);

