INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000047, 320002, 'Something Different - A Beachside Cafe', 'Something Different - A Beachside Cafe', 'Something Different is the best-known beachside cafe of Swaraj Dweep (Havelock Island), set directly on Beach No. 2 behind the Havelock Power House with open sea views. It serves Indian, Chinese and Continental dishes with milkshakes and light snacks; signature items include fish fry, crab lollipops, almond pudding and pizzas. Reviewers highlight the warm service, free pickup/drop and personal touches like complimentary framed photos.', '1-2 hours', 'October to May', 'Reserve ahead for a romantic beach dinner; ask for the free pickup/drop service from nearby hotels.', 'yes', 'Andaman and Nicobar Islands', 0, 1, '5:08 AM', '5:09 PM', NULL, 5, 5, 12.035722, 92.989741, 'Beach No. 2, behind Havelock Power House, Govind Nagar, Swaraj Dweep, 744211', 'https://somethingdifferenthavelock.com/', 1.0);

