INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000048, 320002, 'Anju Coco Resto', 'Anju Coco Resto', 'Anju Coco Resto is a long-running seafood restaurant on Beach No. 5 (Vijaynagar) of Swaraj Dweep (Havelock Island), known for fresh catch dishes served near the water. It is listed among the island''s most-reviewed eateries (1,000+ reviews) with seafood, Indian and Chinese items, in the mid price band. The setting is a simple thatched beachside restaurant popular with both tourists and locals.', '1-2 hours', 'October to May', 'Go for fresh grilled seafood at dinner; evenings are breezy right by the beach.', 'no', 'Andaman and Nicobar Islands', 0, 1, '5:08 AM', '5:09 PM', NULL, 4, 4, 12.023619, 93.00441, 'Beach No. 5, Vijaynagar, Swaraj Dweep, 744211', NULL, 0.8);

