INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000049, 320002, 'Full Moon Cafe', 'Full Moon Cafe', 'Full Moon Cafe is a much-loved beachside cafe on the Govind Nagar side of Swaraj Dweep (Havelock Island), near Beach No. 3, with an open outdoor seating area facing the sea. It serves Indian, cafe-style and seafood dishes (4.4 rating from 900+ reviews) and is a favourite for long relaxed lunches and evening sessions. Reviewers note friendly staff and generous portions.', '1-2 hours', 'October to May', 'Good for a long lazy lunch by the sea; evenings fill up, so arrive a bit early.', 'no', 'Andaman and Nicobar Islands', 0, 1, '5:08 AM', '5:09 PM', NULL, 4, 4, 12.028167, 93.002874, 'Havelock Beach No. 3, Govind Nagar, Swaraj Dweep, 744211', NULL, 0.8);

