INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000050, 320002, 'Golden Spoon', 'Golden Spoon', 'Golden Spoon is a popular seafood restaurant near Havelock Island Beach Resort on the Govind Nagar beach belt of Swaraj Dweep (Havelock Island). It is known for grilled fish, including the banana-leaf grilled fish, and serves Indian and seafood dishes in the mid price band. Reviewers describe it as a reliable choice for seafood close to the Govind Nagar resorts.', '1-2 hours', 'October to May', 'Order the banana-leaf grilled fish if available; it is the dish reviewers praise most.', 'no', 'Andaman and Nicobar Islands', 0, 1, '5:08 AM', '5:09 PM', NULL, 3, 4, 12.033, 92.996, 'Near Havelock Island Beach Resort, Govind Nagar, Swaraj Dweep, 744211', NULL, 0.68);

