INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000051, 320002, 'Squid Restaurant', 'Squid Restaurant', 'Squid Restaurant is a simple, home-style Indian restaurant in the Govind Nagar area of Swaraj Dweep (Havelock Island), noted in traveler guides as a budget-friendly local option. It serves curries and stir-fries with a homely touch, and is referenced in island guides as a landmark near the Govind Nagar market/ANIIDCO wine shop area. Good for unpretentious, affordable meals.', '1 hour', 'October to May', 'A good budget lunch stop near the Govind Nagar market; mains are modestly priced for the island.', 'no', 'Andaman and Nicobar Islands', 0, 0, '5:08 AM', '5:09 PM', NULL, 3, 3, 12.031, 92.993, 'Govind Nagar, Swaraj Dweep, 744211', NULL, 0.6);

