INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000052, 320002, 'Famous Seafood Restaurant', 'Famous Seafood Restaurant', 'Famous Seafood Restaurant is the highest-rated restaurant in Swaraj Dweep on Tripadvisor (4.9 from ~200 reviews), an Indian/seafood spot on the Govind Nagar beach belt. Reviewers praise crab masala, butter chicken, golden prawns and grilled whole fish, with friendly owners and staff. It is known for delivery and takeaway service on the island.', '1-2 hours', 'October to May', 'Try the crab masala or grilled whole fish; ask about delivery if you are staying nearby.', 'no', 'Andaman and Nicobar Islands', 0, 0, '5:08 AM', '5:09 PM', NULL, 4, 5, 12.034, 92.998, 'Govind Nagar, Swaraj Dweep (Havelock Island), 744211', NULL, 0.88);

