INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3200006, 320, 320002, 'Island Tourism Festival', 'Jan', 'The Andaman & Nicobar Islands'' flagship annual festival, organized by the UT administration, usually held in early-to-mid January over ~5-10 days at the ITF Ground, Port Blair. It features folk dance and music from across India, food fairs, handicraft stalls, water sports and cultural shows — the main cultural event of the season for visitors staying on Swaraj Dweep (Havelock Island).');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3200007, 320, 320002, 'Subhash Mela', 'Jan', 'A week-long fair held around Netaji Subhas Chandra Bose''s birth anniversary (January 23), organized by the administration in Port Blair. It combines cultural programs, exhibitions and local food stalls, and is one of the oldest community celebrations in the islands.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3200008, 320, 320002, 'Andaman Beach Festival', 'Apr', 'A beach carnival typically held in late April at Corbyn''s Cove, Port Blair, celebrating the start of the summer season. It features beach games, water sports, food stalls, music and cultural performances — an easy add-on for Havelock visitors spending time in Port Blair.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3200009, 320, 320002, 'Monsoon Music Festival', 'Jul-Aug', 'A monsoon-season music and food festival held around July-August in the islands, with live music, local cuisine stalls and beach activities despite the rains. It gives monsoon travelers a reason to visit, though sea conditions limit inter-island water sports.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3200010, 320, 320002, 'Onam', 'Aug-Sep', 'The Kerala harvest festival, celebrated by the large Malayali settler community across the Andaman Islands including Swaraj Dweep. Highlights include the traditional sadhya feast, pookalam flower carpets, and cultural programs in community halls and temples.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3200011, 320, 320002, 'Diwali', 'Oct-Nov', 'The festival of lights is celebrated across Swaraj Dweep and the Andaman Islands with lamps, fireworks and community gatherings, coinciding with the start of the peak tourist season. Shops and resorts decorate, and visitors can join the festive evenings in Govind Nagar village.');

