INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000053, 320003, 'Bharatpur Beach', 'Bharatpur Beach', 'Bharatpur Beach is Shaheed Dweep''s busiest and most visitor-friendly beach, about 500 metres from the Neil Island jetty on the east side of the island (formerly Neil Island). Its long stretch of white sand and shallow, clear turquoise water is lined with coral reefs, making it the island''s main hub for swimming, snorkelling, glass-bottom boat rides and seasonal water sports.', '2-3 hours', 'October to May', 'Go early morning or late afternoon to avoid the midday heat and crowds; carry your own water and reef-safe sunscreen.', 'no', 'Andaman and Nicobar Islands', 1, 0, '5:20 AM', '5:25 PM', NULL, 5, 4, 11.8313, 93.0495, 'Bharatpur, Shaheed Dweep (Neil Island), Andaman & Nicobar 744104', NULL, 0.92);

