INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000054, 320003, 'Laxmanpur Beach (Sunset Point)', 'Laxmanpur Beach (Sunset Point)', 'Laxmanpur Beach on the island''s west coast is Shaheed Dweep''s famous sunset beach, split into Laxmanpur 1 (the main sunset stretch) and Laxmanpur 2 (quieter, and the access point for the Natural Bridge at low tide). Its broad white-sand shoreline, coral fragments and calm evening light make it the most photographed evening spot on the island (formerly Neil Island).', '1-2 hours', 'October to May', 'Arrive 45-60 minutes before sunset to find a good spot; at high tide stay out of the water as currents can be strong.', 'no', 'Andaman and Nicobar Islands', 0, 1, '5:20 AM', '5:25 PM', NULL, 5, 5, 11.8203, 93.0093, 'Laxmanpur, Shaheed Dweep (Neil Island), Andaman & Nicobar 744104', NULL, 1.0);

