INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000055, 320003, 'Sitapur Beach (Sunrise Point)', 'Sitapur Beach (Sunrise Point)', 'Sitapur Beach on the east coast of Shaheed Dweep (Neil Island) is known as the island''s sunrise beach, facing open sea with views of the rising sun painting the sky in bright colours. Fringed by tropical vegetation and rocky coastal sections, it is a calm, quiet spot suited to early-morning walks and meditation.', '1-2 hours', 'October to May', 'Arrange transport the previous evening, as taxis and autos are scarce before dawn; reach by 5:15 AM to catch the full sunrise.', 'no', 'Andaman and Nicobar Islands', 1, 0, '5:20 AM', '5:25 PM', NULL, 4, 4, 11.8324, 93.054, 'Sitapur, Shaheed Dweep (Neil Island), Andaman & Nicobar 744104', NULL, 0.8);

