INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 320000055, 'insert', 'bulk', 'Real; consistently described as the sunrise beach on the island''s east side. Coordinates approximate (east coast). Swim only when local conditions are safe - waves can be stronger than at Bharatpur.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000056, 320003, 'Natural Bridge (Howrah Bridge)', 'Natural Bridge (Howrah Bridge)', 'The Natural Bridge, locally nicknamed Howrah Bridge by Bengali settlers, is a natural limestone and living-coral sea arch near Laxmanpur Beach No. 2 on Shaheed Dweep (Neil Island). Reached by a 300-400 m walk over exposed rocky reef, it is accessible only during the day''s low-tide window, when tide pools around it reveal sea cucumbers, crabs, brittle stars and giant clams.', '45-90 minutes', 'November to February', 'Check the local tide schedule or ask a local guide before going; wear grippy footwear for the sharp coral path and do not step on living coral.', 'no', 'Andaman and Nicobar Islands', 0, 1, '5:20 AM', '5:25 PM', 'Free', 5, 4, 11.8215, 93.011, 'Laxmanpur Beach No. 2, Shaheed Dweep (Neil Island), Andaman & Nicobar 744104', NULL, 0.92);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (320000056, 320000056, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'No fixed timings; access depends entirely on the day''s low-tide window. Go early morning or late afternoon within the low-tide period.');

