INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 320000056, 'insert', 'bulk', 'Real and well documented; two arches (larger classic arch plus a smaller one visible at very low tide). Entry is free per published sources; confirm locally as policies can change. Coordinates approximate (Laxmanpur Beach No. 2 area, ~2 km from the jetty).', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000057, 320003, 'Ram Nagar Beach', 'Ram Nagar Beach', 'Ram Nagar Beach is the quieter, less-visited beach on Shaheed Dweep''s (Neil Island''s) northern side, valued for its seclusion, clean sand and calm ambience away from the island''s main tourist spots. The lagoons near Ram Nagar are also listed among the island''s snorkelling areas, and a few beach cafés and dive shops sit along its shore.', '1-2 hours', 'October to May', 'Best for a peaceful picnic or beach walk; carry everything you need, as facilities are fewer here than at Bharatpur.', 'no', 'Andaman and Nicobar Islands', 1, 0, '5:20 AM', '5:25 PM', NULL, 3, 4, 11.8445, 93.0275, 'Ram Nagar, Shaheed Dweep (Neil Island), Andaman & Nicobar 744104', NULL, 0.68);

