INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 320000057, 'insert', 'bulk', 'Real but lower-profile beach; coordinates approximate (north coast). Limited published detail beyond travel guides; hours not published for a public beach.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000058, 320003, 'Neil Kendra Village & Market', 'Neil Kendra Village & Market', 'Neil Kendra is the central village and market area of Shaheed Dweep (Neil Island), where visitors can see daily island life, buy souvenirs, local honey and spices, and eat at small local eateries and sweet shops. Shops here typically open around 9 AM to 6 PM, and the area anchors the island''s modest shopping and dining scene.', '1-2 hours', 'October to May', 'Browse in the late morning when shops are fully open; try Sutapa Sweets in the main market for Indian sweets and samosas.', 'no', 'Andaman and Nicobar Islands', 0, 0, '5:20 AM', '5:25 PM', NULL, 3, 3, 11.8306, 93.0281, 'Neil Kendra village, Shaheed Dweep (Neil Island), Andaman & Nicobar 744104', NULL, 0.6);

