INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 320000058, 'insert', 'bulk', 'Real central village; coordinates approximate (island centre). Shop hours vary by shop; no single published hours set, so hours null.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000059, 320003, 'Shaheed Dweep Jetty', 'Shaheed Dweep Jetty', 'The Shaheed Dweep Jetty (Neil Jetty) is the island''s ferry gateway, handling government ferries and private cruises (Makruzz, Coastal Cruise, Express Bhagya) to Sri Vijaya Puram (Port Blair) and Swaraj Dweep (Havelock). The long jetty walkway over clear blue water offers marine-life views, and glass-bottom boat rides for coral viewing depart from here.', '30-60 minutes', 'October to May', 'Book ferries in advance during peak season (December-February); arrive early for your sailing as boarding is on foot along the jetty.', 'no', 'Andaman and Nicobar Islands', 1, 0, '5:20 AM', '5:25 PM', NULL, 4, 3, 11.831, 93.0465, 'Shaheed Dweep Jetty, Shaheed Dweep (Neil Island), Andaman & Nicobar 744104', NULL, 0.72);

