INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000060, 320003, 'Scuba Diving Sites (K-Rock, Bus Stop, Margherita''s Mischief, Jetty Channel Marker)', 'Scuba Diving Sites (K-Rock, Bus Stop, Margherita''s Mischief, Jetty Channel Marker)', 'The waters around Shaheed Dweep (Neil Island) host several named dive sites listed by the Andaman & Nicobar tourism department: Bus Stop (for beginners and certified divers), Margherita''s Mischief (rocky mounds with potential dugong sightings), Jetty Channel Marker (shallow fringing reef for new divers) and K-Rock (schools of fusiliers, trevallies, butterflyfish, Napoleon wrasse, occasional reef sharks and turtles). Local dive shops including Indian Scuba Explorers, Dive India and Scuba Love run guided dives in these clear, calm waters.', '2-4 hours', 'October to May', 'Book with a certified operator a day ahead; calm, clear water makes this a good island for beginner discover dives too.', 'yes', 'Andaman and Nicobar Islands', 0, 0, '5:20 AM', '5:25 PM', NULL, 4, 5, 11.85, 93.065, 'Offshore dive sites, Shaheed Dweep (Neil Island), Andaman & Nicobar 744104', NULL, 0.88);

