INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000061, 320003, 'Snorkelling Lagoons (Bharatpur & Laxmanpur)', 'Snorkelling Lagoons (Bharatpur & Laxmanpur)', 'The shallow lagoons off Bharatpur Beach and Laxmanpur Beach on Shaheed Dweep (Neil Island) are the island''s go-to snorkelling spots, with clear water, coral gardens and colourful reef fish close to shore. Equipment can be rented from resorts and beach operators; several resorts lend out snorkelling gear to guests.', '1-2 hours', 'October to May', 'Best in calm morning seas; avoid touching or standing on the coral, and check local conditions before entering the water.', 'no', 'Andaman and Nicobar Islands', 0, 0, '5:20 AM', '5:25 PM', NULL, 4, 4, 11.8305, 93.0485, 'Bharatpur & Laxmanpur lagoons, Shaheed Dweep (Neil Island), Andaman & Nicobar 744104', NULL, 0.8);

