INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000062, 320003, 'Glass-Bottom Boat Ride', 'Glass-Bottom Boat Ride', 'Glass-bottom boat rides depart from the Shaheed Dweep Jetty (Neil Island) and give non-swimmers and children a dry view of the coral reefs and marine life through a transparent hull. The typical ride runs about 20 minutes and costs roughly INR 400 to INR 600 per person, per published local guides.', '20-30 minutes', 'October to May', 'Pick a morning ride in calm seas for the clearest views through the glass hull.', 'no', 'Andaman and Nicobar Islands', 0, 0, '5:20 AM', '5:25 PM', 'Rs 400-600 per person', 3, 3, 11.831, 93.0465, 'Shaheed Dweep Jetty, Shaheed Dweep (Neil Island), Andaman & Nicobar 744104', NULL, 0.6);

