INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 320000062, 'insert', 'bulk', 'Real activity operating at the jetty; price range from a published local guide, not an official tariff - confirm locally.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000063, 320003, 'Island Cycling Tour', 'Island Cycling Tour', 'Shaheed Dweep (Neil Island) is small - about 13.7 square kilometres - and famously flat, so cycling is the classic way to explore it, with cycle rentals available around Neil Kendra for roughly INR 100-200 per day. A ride across the island passes paddy fields, banana plantations, quiet villages and the roads linking all three main beaches.', '2-4 hours', 'October to May', 'Start early (by 6-6:30 AM) to combine the ride with a sunrise stop at Sitapur Beach and avoid the midday heat.', 'no', 'Andaman and Nicobar Islands', 1, 1, '5:20 AM', '5:25 PM', 'Rs 100-200 per day (cycle rental)', 3, 4, 11.8306, 93.0281, 'Neil Kendra, Shaheed Dweep (Neil Island), Andaman & Nicobar 744104', NULL, 0.68);

