INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 320000063, 'insert', 'bulk', 'Real, widely recommended way to see the island; cycle rental price is an itinerary estimate, not an official tariff. No single operator, so official_website and hours null.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000064, 320003, 'Stargazing Beaches', 'Stargazing Beaches', 'With minimal light pollution and open sea horizons, the dark beaches of Shaheed Dweep (Neil Island) - especially Laxmanpur and Sitapur - are described by the Andaman & Nicobar tourism department as natural open-air observatories. On clear nights the sky reveals constellations, shooting stars and the Milky Way above swaying palms and gentle waves.', '1-2 hours', 'November to February', 'Pick a moonless, cloud-free night in the dry season and walk a few minutes away from any resort lights for the darkest sky.', 'no', 'Andaman and Nicobar Islands', 0, 0, '5:20 AM', '5:25 PM', NULL, 2, 4, 11.8203, 93.0093, 'Laxmanpur & Sitapur beaches, Shaheed Dweep (Neil Island), Andaman & Nicobar 744104', NULL, 0.56);

