INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000065, 320003, 'Farm Walk - Vegetable Bowl of the Andamans', 'Farm Walk - Vegetable Bowl of the Andamans', 'Shaheed Dweep (Neil Island) is nicknamed the ''Vegetable Bowl of the Andamans'' for its flat, fertile farmland, and guided walks through its paddy fields, banana plantations and village lanes are a standard local experience. The walks show a slower, agricultural side of island life that sets Neil apart from the more resort-driven islands.', '1-2 hours', 'October to May', 'Take a guided walk so you don''t get lost in the field tracks; combine it with a cycle ride through the village lanes.', 'no', 'Andaman and Nicobar Islands', 0, 0, '5:20 AM', '5:25 PM', NULL, 2, 3, 11.833, 93.025, 'Village farmlands, Shaheed Dweep (Neil Island), Andaman & Nicobar 744104', NULL, 0.48);

