INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000066, 320003, 'Water Sports at Bharatpur Beach', 'Water Sports at Bharatpur Beach', 'Bharatpur Beach is Shaheed Dweep''s (Neil Island''s) main water-sports hub, where seasonal operators offer jet skiing, banana boat rides and speed boating over the shallow turquoise lagoon, subject to weather, tides and local permissions. It is the liveliest beach on the island and the easiest place to try motorised water sports without leaving the island.', '1-2 hours', 'October to May', 'Confirm the day''s availability and price with the operator on the beach before paying; rides depend on sea and weather conditions.', 'no', 'Andaman and Nicobar Islands', 0, 0, '5:20 AM', '5:25 PM', NULL, 3, 3, 11.8313, 93.0495, 'Bharatpur Beach, Shaheed Dweep (Neil Island), Andaman & Nicobar 744104', NULL, 0.6);

