INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000067, 320003, 'Radhanagar Beach, Swaraj Dweep (~17 km by sea)', 'Radhanagar Beach, Swaraj Dweep (~17 km by sea)', 'DAY TRIP: Radhanagar Beach on Swaraj Dweep (Havelock Island) is about 17 km by sea from Shaheed Dweep (Neil Island) - roughly an hour by ferry - and was named Asia''s best beach by Time magazine in 2004. Its 2-km stretch of fine white sand, turquoise water and jungle fringe, about 12 km from Havelock''s ferry pier, makes it the Andamans'' most celebrated sunset beach.', 'Half day to full day', 'October to May', 'Take an early ferry so you can spend the afternoon here and still catch a return sailing; carry essentials as the beach has limited shops.', 'no', 'Andaman and Nicobar Islands', 0, 1, '5:20 AM', '5:25 PM', NULL, 5, 5, 11.9843, 92.9494, 'Swaraj Dweep (Havelock Island), Andaman & Nicobar 744211', NULL, 1.0);

