INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000068, 320003, 'Elephant Beach, Swaraj Dweep (~25-30 km by sea)', 'Elephant Beach, Swaraj Dweep (~25-30 km by sea)', 'DAY TRIP: Elephant Beach on Swaraj Dweep (Havelock Island) - about 6 km by sea from the Havelock jetty, reached by a ~45-minute boat ride - is known for some of the Andamans'' best coral reefs and lively underwater marine life. Operators run snorkelling, scuba diving, sea walk, jet skiing and parasailing here on a spot-payment basis, making it the archipelago''s main adventure-water-sports beach.', 'Half day', 'October to May', 'Carry lunch, drinking water and a change of clothes, as suggested by tour operators; book the boat a day ahead in peak season.', 'yes', 'Andaman and Nicobar Islands', 0, 0, '5:20 AM', '5:25 PM', NULL, 4, 4, 12.0247, 92.9522, 'Swaraj Dweep (Havelock Island), Andaman & Nicobar 744211', NULL, 0.8);

