INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000069, 320003, 'Kalapathar Beach, Swaraj Dweep (~20 km by sea)', 'Kalapathar Beach, Swaraj Dweep (~20 km by sea)', 'DAY TRIP: Kalapathar Beach on Swaraj Dweep (Havelock Island) is a sunrise beach of black rocks, white sand and turquoise water, best visited in the early morning before the heat builds. It is a quieter alternative to Radhanagar, typically visited for sunrise views and beach walks on Andaman itineraries combining Havelock and Neil Island.', '1-2 hours', 'October to May', 'Go for sunrise; combine with Radhanagar and Elephant Beach into a full Havelock day if ferry timings allow.', 'no', 'Andaman and Nicobar Islands', 1, 0, '5:20 AM', '5:25 PM', NULL, 3, 4, 11.9664, 92.9935, 'Swaraj Dweep (Havelock Island), Andaman & Nicobar 744211', NULL, 0.68);

