INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000070, 320003, 'Cellular Jail & Sound & Light Show, Sri Vijaya Puram (~40 km)', 'Cellular Jail & Sound & Light Show, Sri Vijaya Puram (~40 km)', 'DAY TRIP: The Cellular Jail (Kala Pani) in Sri Vijaya Puram (Port Blair) - about 36-40 km and 1.5-2 hours by ferry from Shaheed Dweep (Neil Island) - is the three-storeyed colonial prison built in 1906 that held Indian freedom fighters. Its evening Sound & Light Show brings the saga of the freedom struggle alive and is the centrepiece of most Port Blair visits.', 'Half day to full day', 'October to May', 'The Sound & Light Show runs in the evening, so plan a full day: early ferry out, city sights, show at dusk, late ferry back.', 'yes', 'Andaman and Nicobar Islands', 0, 0, '5:20 AM', '5:25 PM', NULL, 5, 4, 11.6743, 92.7491, 'Atlanta Point, Sri Vijaya Puram (Port Blair), Andaman & Nicobar 744104', NULL, 0.92);

