INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000071, 320003, 'Ross Island (Netaji Subhas Chandra Bose Dweep), Sri Vijaya Puram (~40 km)', 'Ross Island (Netaji Subhas Chandra Bose Dweep), Sri Vijaya Puram (~40 km)', 'DAY TRIP: Ross Island (renamed Netaji Subhas Chandra Bose Dweep) near Sri Vijaya Puram - about 40 km by ferry from Shaheed Dweep (Neil Island) - was the British administrative headquarters, nicknamed the ''Paris of the East'', now lying in ruins after earthquakes. Visitors walk among crumbling colonial buildings alongside deer and peacocks, then combine the trip with nearby North Bay (Coral Island) for snorkelling.', 'Half day', 'October to May', 'Combine with a North Bay coral-viewing boat trip in the same harbour cruise day; carry sun protection and water.', 'yes', 'Andaman and Nicobar Islands', 0, 0, '5:20 AM', '5:25 PM', NULL, 4, 4, 11.6773, 92.7714, 'Netaji Subhas Chandra Bose Dweep, Sri Vijaya Puram, Andaman & Nicobar 744102', NULL, 0.8);

