INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000072, 320003, 'Corbyn''s Cove Beach, Sri Vijaya Puram (~40 km)', 'Corbyn''s Cove Beach, Sri Vijaya Puram (~40 km)', 'DAY TRIP: Corbyn''s Cove Beach, about 7 km from Sri Vijaya Puram (Port Blair) - roughly 40 km by ferry from Shaheed Dweep (Neil Island) - is a coconut-palm-fringed beach suited to swimming, sunbathing and water sports. It is the standard beach stop on Port Blair city tours and pairs well with the Cellular Jail visit on the same day.', '2-3 hours', 'October to May', 'Combine with the Cellular Jail and museums on a single Port Blair day trip to make the 1.5-2 hour ferry worthwhile.', 'no', 'Andaman and Nicobar Islands', 0, 0, '5:20 AM', '5:25 PM', NULL, 3, 3, 11.6494, 92.7478, 'Corbyn''s Cove, Sri Vijaya Puram (Port Blair), Andaman & Nicobar 744104', NULL, 0.6);

