INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 320000072, 'insert', 'bulk', 'Real, well-documented Port Blair beach. Ferry distance from Neil approximate (~40 km by sea, 1.5-2 hrs, varies by operator). Public beach; no published hours.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000073, 320003, 'Avisa', 'Avisa', 'Avisa is a pet-friendly beach café behind the ScubaYogi dive shop at Ram Nagar Beach on Shaheed Dweep (Neil Island), open since 2023 and ranked #2 of 21 island restaurants on TripAdvisor with a 5-star rating. Its menu spans Italian, Indian, seafood, pizza, Mediterranean and café dishes (price range about Rs 169-2,500), and reviewers highlight fresh seafood, the laid-back beachfront pavilion and sunset views.', '1-2 hours', 'October to May', 'Head here for sunset dinner; the open-air pavilion is about 50 metres from the beach and fills up in peak season.', 'no', 'Andaman and Nicobar Islands', 0, 1, '5:20 AM', '5:25 PM', NULL, 4, 5, 11.8445, 93.0285, 'Behind ScubaYogi Dive Shop, Ram Nagar Beach, Shaheed Dweep (Neil Island), Andaman & Nicobar 744104', NULL, 0.88);

