INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000074, 320003, 'Garden View Restaurant', 'Garden View Restaurant', 'Garden View Restaurant near the Shaheed Dweep Jetty on Neil Island is a well-known casual eatery famous for its grilled fish, a favourite stop for visitors right after landing. It serves conventional Indian and seafood preparations at budget-friendly prices in a simple, family-run setting.', '45-60 minutes', 'October to May', 'Convenient first meal after the ferry; ask for the day''s fresh catch grilled.', 'no', 'Andaman and Nicobar Islands', 0, 0, '5:20 AM', '5:25 PM', NULL, 3, 3, 11.831, 93.046, 'Near Shaheed Dweep Jetty, Shaheed Dweep (Neil Island), Andaman & Nicobar 744104', NULL, 0.6);

