INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000075, 320003, 'Dugong by SeaShell', 'Dugong by SeaShell', 'Dugong by SeaShell is the restaurant at SeaShell Resorts on Shaheed Dweep (Neil Island), noted for its premium dine-in experience, beachfront setting and a wide selection of Indian, Continental and seafood dishes. Reviewers call out the seafood platter, Neil fish curry, chilli chicken and crispy chilli baby corn as standout orders.', '1-2 hours', 'October to May', 'Reserve ahead for a beachfront dinner table; it is the island''s most upscale dinner option.', 'yes', 'Andaman and Nicobar Islands', 0, 1, '5:20 AM', '5:25 PM', NULL, 4, 4, 11.823, 93.012, 'SeaShell, Beach No 1, Village Road, Shaheed Dweep (Neil Island), Andaman & Nicobar 744104', NULL, 0.8);

