INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 320000075, 'insert', 'bulk', 'Corroborated by travelsetu (food guide) and Wanderlog (premium dine-in, reviews). Address from Wanderlog. Hours and menu prices not published, so null. Advance booking recommended in peak season for dinner seating.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000076, 320003, 'Blue Sea Restaurant', 'Blue Sea Restaurant', 'Blue Sea Restaurant at Laxmanpur Beach on Shaheed Dweep (Neil Island) is known for its creamy coconut prawn curry and other fresh seafood preparations. It is a convenient sunset-time dinner stop for visitors spending the evening on the island''s sunset beach.', '1-1.5 hours', 'October to May', 'Time your meal with the Laxmanpur sunset; order the coconut prawn curry if available.', 'no', 'Andaman and Nicobar Islands', 0, 1, '5:20 AM', '5:25 PM', NULL, 3, 3, 11.821, 93.01, 'Laxmanpur Beach, Shaheed Dweep (Neil Island), Andaman & Nicobar 744104', NULL, 0.6);

