INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000077, 320003, 'Gan Garden Restaurant', 'Gan Garden Restaurant', 'Gan Garden Restaurant, about 500 metres from the main bazaar on the road towards the sunset point on Shaheed Dweep (Neil Island), is a family-run restaurant opposite the football ground with a good choice of meals. The family will happily cook fish you catch or buy from the fish market for a small charge, and also helps arrange snorkelling, fishing and jungle trips.', '45-60 minutes', 'October to May', 'If you fish or buy from the market, ask the family to cook it; ask about their snorkelling and fishing day trips (about Rs 500 per person, full day with lunch).', 'no', 'Andaman and Nicobar Islands', 0, 0, '5:20 AM', '5:25 PM', NULL, 3, 4, 11.83, 93.026, 'About 500 m from Neil Kendra bazaar towards Laxmanpur, Shaheed Dweep (Neil Island), Andaman & Nicobar 744104', NULL, 0.68);

