INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 320000077, 'insert', 'bulk', 'Corroborated by Wikitravel (detailed location) and neilislandresorts listing. Address approximate per Wikitravel''s directions. Hours not published; prices vary by day''s catch, so null.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (320000078, 320003, 'OrganiKa', 'OrganiKa', 'OrganiKa in Ram Nagar on Shaheed Dweep (Neil Island) is the island''s noted vegetarian option, serving a veg thali of local vegetable dishes with rice and chapati made from fresh local produce. It is a useful stop for vegetarian travellers on an island where most eateries lead with seafood.', '45-60 minutes', 'October to May', 'The island''s reliable vegetarian bet; the veg thali showcases the local ''vegetable bowl'' produce.', 'no', 'Andaman and Nicobar Islands', 0, 0, '5:20 AM', '5:25 PM', NULL, 3, 3, 11.8425, 93.0285, 'Ram Nagar, Shaheed Dweep (Neil Island), Andaman & Nicobar 744104', NULL, 0.6);

