INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3200012, 320, 320003, 'Vivekananda Mela', 'Jan', 'Held every year at Neil Island (Shaheed Dweep) in January to mark Swami Vivekananda''s birth anniversary, with cultural programmes and local gatherings; one of the few festivals centred on Neil Island itself.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3200013, 320, 320003, 'Island Tourism Festival', 'Dec-Jan', 'The Andaman & Nicobar Administration''s flagship year-end festival; main venue at Sri Vijaya Puram with programmes staged on Shaheed Dweep too (live bands performed on the island during recent editions). Features cultural performances, food courts, handicraft stalls and children''s activities.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3200014, 320, 320003, 'Subhash Mela', 'Jan', 'Week-long patriotic festival on Swaraj Dweep (Havelock), about 17 km by ferry from Shaheed Dweep, held around Netaji Subhas Chandra Bose''s birth anniversary; folk dances, patriotic songs, sports and exhibitions honouring the freedom movement.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3200015, 320, 320003, 'Beach Festival', 'Apr', 'Island-wide beach celebration promoting beach tourism, with beach volleyball, kabaddi, tug-of-war, local music and dance, sand-art competitions and island-style seafood stalls on the Andaman shores.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3200016, 320, 320003, 'Monsoon Music Festival', 'Jun-Jul', 'Music festival in Sri Vijaya Puram during the rainy months celebrating the islands'' love of music, with live performances from local and mainland musicians across folk, classical, rock and fusion genres.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3200017, 320, 320003, 'Panguni Utthiram', 'Mar-Apr', 'Tamil community festival celebrated across the Andaman & Nicobar Islands in honour of Lord Murugan, with processions of a decorated idol, hymns and drumming through island streets.');

