INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (342000001, 342001, 'Marine Aquarium and Museum', 'Marine Aquarium and Museum', 'The Marine Aquarium and Museum at Kavaratti showcases the underwater life of the Lakshadweep archipelago: colourful fish, corals, sea cucumbers, octopuses, anemones and preserved marine specimens. The museum section displays shells, coral collections and a sperm whale skeleton. It is the island''s main educational attraction for marine biodiversity.', '1 hour', 'October to March', 'Confirm it is open before walking over — the aquarium wing is sometimes closed for maintenance.', 'no', 'Lakshadweep', 0, 0, '6:31 AM', '6:26 PM', NULL, 5, 4, 10.5765, 72.6403, 'Southern end of Kavaratti Island, Lakshadweep 682555', NULL, 0.92);

