INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 342000001, 'insert', 'bulk', 'Real, well-documented. Entry fee consistently described as ''nominal'' but no figure is published anywhere — kept null. Coords conflict: one directory lists 10.576452, 72.640264 while travel writing places it at the island''s southern end; coordinate is approximate (within ~1 km) — flag as approximate. No official website found.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (342000002, 342001, 'Ujra Mosque', 'Ujra Mosque', 'The Ujra (Urja) Mosque is the oldest and most beautiful mosque in Lakshadweep, built in the 17th century by Sheikh Mohammad Kasim. It is famed for its carved wooden pillars and ornate ceiling carved from driftwood, and the sheikh''s tomb lies inside. A well on the premises is believed by locals to have healing properties.', '45 minutes', 'October to March', 'Dress modestly (cover shoulders and knees) and remove footwear; photography inside the prayer hall may be restricted.', 'no', 'Lakshadweep', 0, 0, '6:31 AM', '6:26 PM', NULL, 5, 4, 10.566, 72.64, 'Kavaratti Island, Lakshadweep 682555 (central part of the island)', NULL, 0.92);

