INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (342000003, 342001, 'Kavaratti Lighthouse', 'Kavaratti Lighthouse', 'Kavaratti Lighthouse is a 38-metre reinforced concrete tower built 1984–88, commissioned 28 October 1988, replacing an earlier gas light from 1976. It is one of the major lighthouses of the Lakshadweep group under the Directorate General of Lighthouses and Lightships. Visitors climb it for panoramic views of the island and lagoon.', '1 hour', 'October to March', 'Go on a clear morning for the best panoramic views; carry the DGLL booking reference if you book tickets online.', 'no', 'Lakshadweep', 1, 1, '6:31 AM', '6:26 PM', NULL, 4, 4, 10.567, 72.639, 'Kavaratti Island, Lakshadweep 682555', 'https://lighthouse.nic.in/lighthouses/cochin/kavaratti-lighthouse', 0.8);

