INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (342000004, 342001, 'Kavaratti Lagoon', 'Kavaratti Lagoon', 'The Kavaratti Lagoon is the largest lagoon in Lakshadweep: a shallow expanse of clear blue-green water ringed by coral reefs that shelter the island''s western shore. It is the centre of the island''s water life — swimming, snorkelling, kayaking, windsurfing and canoeing. The lagoon''s sunset points are widely described as postcard-perfect.', '2-3 hours', 'October to March', 'The western side is calmest for swimming; stay for sunset — the lagoon sunset points are the island''s best.', 'no', 'Lakshadweep', 0, 1, '6:31 AM', '6:26 PM', NULL, 5, 5, 10.56, 72.63, 'Western shore of Kavaratti Island, Lakshadweep 682555', NULL, 1.0);

