INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (342000005, 342001, 'Kavaratti Beach', 'Kavaratti Beach', 'Kavaratti''s beaches are narrow ribbons of white sand fringed with coconut palms, backed by the turquoise lagoon. Visitors come for sunbathing, swimming in the calm western lagoon, and relaxed evening walks. Beaches are free to access; water sports gear is hired from nearby centres.', '2-3 hours', 'October to March', 'Bring your own snorkel mask if you can — rental options are limited and basic.', 'no', 'Lakshadweep', 0, 1, '6:31 AM', '6:26 PM', NULL, 5, 4, 10.5667, 72.635, 'Kavaratti Island, Lakshadweep 682555', NULL, 0.92);

