INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (342000006, 342001, 'Dolphin Dive Centre', 'Dolphin Dive Centre', 'The Dolphin Dive Centre at Kavaratti is the island''s established scuba diving facility, operated by SPORTS (the Lakshadweep administration''s tourism body). It offers PADI scuba courses from beginner (Bubblemaker/Discover) to Divemaster, guided reef dives, and glass-bottom boat rides over the coral reefs.', 'Half day', 'October to March', 'Book scuba courses in advance during peak season (Dec–Feb); beginner dives need no prior certification.', 'yes', 'Lakshadweep', 0, 0, '6:31 AM', '6:26 PM', NULL, 5, 5, 10.5772, 72.6397, 'Sandy Beach, Shoukhathattilai Kunnachada, Kavaratti, Lakshadweep 682555', NULL, 1.0);

