INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (342000007, 342001, 'Water Sports Centre, Kavaratti', 'Water Sports Centre, Kavaratti', 'Kavaratti''s Water Sports Centre is the island''s hire hub for kayaks, snorkels, surfboards and other gear, run under the SPORTS tourism setup. Reviewers describe friendly staff and affordable rentals for snorkelling and kayaking, and note that simply sitting at the centre at sunset is worth the visit.', '2-3 hours', 'October to March', 'Go in the late afternoon — do a kayak or snorkel session and stay for the lagoon sunset.', 'no', 'Lakshadweep', 0, 1, '6:31 AM', '6:26 PM', NULL, 4, 4, 10.56, 72.638, 'HJFQ+463, Kavaratti, Lakshadweep 682555', NULL, 0.8);

