INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (342000008, 342001, 'Chicken Neck Point', 'Chicken Neck Point', 'Chicken Neck Point, at the southern end of Kavaratti, is the island''s prime snorkelling and scuba diving spot, reached by boat. The reef here offers some of the clearest water and richest coral viewing on the island. Dives and snorkel trips are run through the Dolphin Dive Centre and resort operators.', 'Half day', 'October to March', 'Go on a calm, clear morning for the best underwater visibility.', 'yes', 'Lakshadweep', 0, 0, '6:31 AM', '6:26 PM', NULL, 4, 5, 10.527, 72.64, 'Southern tip of Kavaratti Island, Lakshadweep 682555', NULL, 0.88);

