INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (342000017, 342001, 'Kasiminte Chayakada', 'Kasiminte Chayakada', 'Kasiminte Chayakada is a popular local tea shop on Kavaratti (4.7 on Justdial) — the island''s equivalent of a Kerala chayakada, serving tea and snacks. It is a good stop for a cheap, authentic local break.', '30 minutes', 'October to March', 'Stop for evening chai and snacks with locals — cheapest authentic bite on the island.', 'no', 'Lakshadweep', 0, 0, '6:31 AM', '6:26 PM', NULL, 2, 4, 10.5665, 72.641, 'Kavaratti, Lakshadweep 682555', NULL, 0.56);

