INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3420001, 342, 342001, 'Eid-ul-Fitr', 'Mar–Apr', 'Marks the end of Ramadan. Celebrated by the whole island with prayers at the mosques followed by feasting on local delicacies; the most widely celebrated festival in Lakshadweep.');

