INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (342000018, 342002, 'Agatti Beach', 'Agatti Beach', 'Agatti Beach is the main beach of Agatti, a 7.5 km long, 1 km wide island in the Lakshadweep archipelago, known for white sand, shallow turquoise lagoons and coral reefs. The island is the gateway to Lakshadweep because it hosts the only airport (AGX) in the territory, with flights from Kochi. The beach and lagoon support swimming, sunbathing, snorkeling, kayaking, scuba diving and glass-bottom boat rides.', '2-3 hours', 'October to March', 'Carry reef-safe sunscreen and arrive before 10 AM for the calmest lagoon water and best snorkeling visibility.', 'no', 'Lakshadweep', 1, 1, '6:30 AM', '6:15 PM', NULL, 5, 4, 10.838, 72.178, 'Agatti Beach, Agatti Island, Lakshadweep 682553', NULL, 0.92);

