INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 342000018, 'insert', 'bulk', 'Real, widely documented across tour operator itineraries (T2I Holidays, ClubTravelscape, HelloTravel packages). Coordinates approximate (south/lagoon stretch of the island, within ~1 km of the actual shoreline). Sunrise/sunset times are rounded estimates for the island, not from a published source.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (342000019, 342002, 'Bangaram Island', 'Bangaram Island', 'Bangaram is a small uninhabited teardrop-shaped island northeast of Agatti, reached in about 30 minutes by private boat. It is ringed by white-sand beaches, a shallow lagoon and coral reefs, and is a day-trip destination for snorkeling, glass-bottom boat rides and swimming. A submerged shipwreck near Bangaram is a popular snorkeling stop en route (weather permitting).', '4-6 hours (day trip)', 'October to March', 'Carry packed food and drinking water; there are no shops or facilities on the uninhabited island.', 'yes', 'Lakshadweep', 1, 1, '6:30 AM', '6:15 PM', NULL, 5, 5, 10.9333, 72.2833, 'Bangaram Island, Lakshadweep 682553', NULL, 1.0);

