INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 342000019, 'insert', 'bulk', 'Real and well documented (coordinates ~10.93N 72.28E match published island data; within ~1 km). Boat access from Agatti is ~30 min per ClubTravelscape package; shipwreck snorkeling stop described by Somans Leisure Tours itinerary. Foreigners/visitors need the island named on their Lakshadweep entry permit.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (342000020, 342002, 'Thinnakara Island', 'Thinnakara Island', 'Thinnakara is an uninhabited island near Bangaram, visited as a day trip from Agatti along with the Bangaram sandbank. It has clear shallow waters with frequent green turtle sightings, coral reefs for snorkeling and a small local family settlement. Tour operators typically pair it with Bangaram in a full-day boat excursion with lunch on the island or boat.', '3-5 hours (day trip)', 'October to March', 'Go in the morning when the sea is calmest; turtles are most often spotted around the island''s lagoon edge.', 'yes', 'Lakshadweep', 1, 1, '6:30 AM', '6:15 PM', NULL, 5, 4, 10.9467, 72.3133, 'Thinnakara Island, Lakshadweep 682553', NULL, 0.92);

