INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (342000021, 342002, 'Kalpitti Island', 'Kalpitti Island', 'Kalpitti (Kalpetti) is a small uninhabited island south of Agatti, reached in about 20 minutes by boat. It is known for its turtle population in the surrounding lagoon, plus coral reefs, kayaking and glass-bottom boat trips. Tour packages from Agatti routinely include a Kalpitti excursion with snorkeling or turtle-watching.', '2-3 hours (day trip)', 'October to March', 'Entry permit rules require the island be named on your Lakshadweep entry permit before travel.', 'yes', 'Lakshadweep', 1, 1, '6:30 AM', '6:15 PM', NULL, 4, 4, 10.7967, 72.1667, 'Kalpitti Island, Lakshadweep 682553', NULL, 0.8);

