INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 342000021, 'insert', 'bulk', 'Real and documented (TripAdvisor review: 20 min boat ride, Rs 750/person for the trip; TravelNGrow: Kalpitti visit + scuba). Coordinates approximate from island location south of Agatti, within ~1 km. Entry-permit naming rule confirmed by lakshadweep-hotels.com.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (342000022, 342002, 'Pitti Bird Sanctuary', 'Pitti Bird Sanctuary', 'Pitti is a tiny uninhabited islet west of Kavaratti/Agatti that has been designated a bird sanctuary, known for its colonies of seabirds including terns. It is visited only as a boat excursion and landing may be restricted during nesting seasons. Birdwatchers combine it with other inter-island boat trips.', '1-2 hours (boat excursion)', 'October to March', 'Bring binoculars and keep a respectful distance; landing restrictions apply in nesting season.', 'yes', 'Lakshadweep', 1, 1, '6:30 AM', '6:15 PM', NULL, 3, 4, 10.772, 72.629, 'Pitti Islet, Lakshadweep 682553', NULL, 0.68);

