INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 342000022, 'insert', 'bulk', 'Real: Pitti is the documented bird sanctuary islet of the archipelago (listed in WanderOn and HelloTravel Agatti guides). Coordinates approximate from published location west of Kavaratti, within ~1 km. Fewer Agatti-specific visitor reports; treated as an excursion option.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (342000023, 342002, 'Scuba Diving at Agatti Reef', 'Scuba Diving at Agatti Reef', 'Agatti''s coral reefs and shipwrecks make it one of Lakshadweep''s scuba diving spots, with sea turtles, reef sharks, rays and colorful coral gardens. Beginner introductory dives run in the shallow lagoon, while certified divers go deeper; PADI-certified operators (e.g. Planet Scuba India) work across Agatti, Kavaratti and Bangaram. Published per-dive prices range from about Rs 2,000 to Rs 6,000 depending on operator.', '2-3 hours', 'September to May', 'Book through a registered operator only - they arrange the required permits; never dive after drinking alcohol.', 'yes', 'Lakshadweep', 0, 0, '6:30 AM', '6:15 PM', 'Rs 4499 per person', 5, 5, 10.835, 72.178, 'South Beach lagoon, Agatti Island, Lakshadweep 682553', NULL, 1.0);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (342000023, 342000023, '8:00 AM - 5:00 PM', '8:00 AM - 5:00 PM', '8:00 AM - 5:00 PM', '8:00 AM - 5:00 PM', '8:00 AM - 5:00 PM', '8:00 AM - 5:00 PM', '8:00 AM - 5:00 PM', 'Operational timing (8 AM - 5 PM) is the published timing of one booking operator (Universal Adventures); actual dives depend on sea conditions and operator schedules. 1-hour session incl. briefing, ~15-20 min underwater, age 10+.');

