INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 342000023, 'insert', 'bulk', 'Real activity with published pricing: Rs 4499 on universaladventures.in (19% off offer price, includes photos/videos); Tripoto cites Planet Scuba India (PADI, Rs 6,000/dive) operating on Agatti; Zee Zest cites Rs 2,000 onwards at Agatti. Hours are operator-published, not a venue''s official hours. Coordinates approximate (dive sites along south/lagoon side), within ~1 km.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (342000024, 342002, 'Snorkeling in Agatti Lagoon', 'Snorkeling in Agatti Lagoon', 'Agatti''s shallow western lagoon is a calm, beginner-friendly snorkeling ground over live coral gardens with parrotfish, clownfish, turtles and rays visible in clear water. Snorkeling sessions are arranged by resorts and water-sports centers, typically including gear and a guide. It is often combined with glass-bottom boat rides and kayaking in package itineraries.', '1-2 hours', 'October to May', 'Do not touch or stand on corals; morning sessions have the best visibility.', 'no', 'Lakshadweep', 0, 1, '6:30 AM', '6:15 PM', 'Rs 500-2000 per session', 5, 4, 10.845, 72.175, 'Lagoon side, Agatti Island, Lakshadweep 682553', NULL, 0.92);

