INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 342000024, 'insert', 'bulk', 'Real, widely offered activity. Price range Rs 500-2000 per session is a published range for Lakshadweep (Medium, Feb 2025); Agatti-specific exact price not published, so range is flagged as island-group level. Coordinates approximate, within ~1 km of lagoon shore.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (342000025, 342002, 'Golden Jubilee Museum', 'Golden Jubilee Museum', 'The Golden Jubilee Museum is the museum dedicated to Lakshadweep''s history, located about 2 km from the beach near Agatti village, a short walk from the Agatti jetty. Its collection includes a model of the traditional Minicoy jagdhoni sailboat, jars, pots, platters and wooden chests recovered from the islands and shipwrecks, two 9th-12th century Buddha busts, and three gold coins said to be issued by Ottoman ruler Suleiman the Magnificent. It is described as the only museum in Lakshadweep.', '1 hour', 'October to March', 'Hire a cycle or two-wheeler from the village to reach it comfortably; carry ID since visitor details are noted at entry.', 'no', 'Lakshadweep', 0, 0, '6:30 AM', '6:15 PM', NULL, 4, 3, 10.868, 72.185, 'Near Agatti village, north Agatti Island, Lakshadweep 682553', NULL, 0.72);

