INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 342000025, 'insert', 'bulk', 'Real, documented by Outlook Traveller (Buddha busts, Ottoman coins, jagdhoni model) and HelloTravel (2 km from beach, large cannon at entrance, aquarium with corals/shells). Sunday closure reported in Encamp itinerary PDF - single source, flagged as unconfirmed. Coordinates approximate (near jetty/village), within ~1 km.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (342000026, 342002, 'Display-cum-Interpretation Facility for Marine Ornamental Organisms', 'Display-cum-Interpretation Facility for Marine Ornamental Organisms', 'This small marine aquarium on Agatti is created and maintained by ICAR and the National Bureau of Fish Genetic Resources, displaying marine ornamental organisms of the islands. Visitors have their details noted and pay a small entry fee; it is a short stop typically included in island sightseeing tours.', '30 minutes - 1 hour', 'October to March', 'Combine it with the Golden Jubilee Museum in the same island-tour leg to save time.', 'no', 'Lakshadweep', 0, 0, '6:30 AM', '6:15 PM', 'Rs 50 per person', 3, 3, 10.86, 72.185, 'Agatti Island, Lakshadweep 682553', NULL, 0.6);

