INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (342000027, 342002, 'Andhaan Beach', 'Andhaan Beach', 'Andhaan (Anthan) Beach is a white-sand beach on Agatti described by visitors as a well-patronized, photogenic stretch of shoreline included in island sightseeing tours. It sits along the regular island tour route alongside the museum and the aquarium facility.', '1-2 hours', 'October to March', 'It is a stop on the standard island tour; ask your guide to include it.', 'no', 'Lakshadweep', 1, 1, '6:30 AM', '6:15 PM', NULL, 3, 3, 10.855, 72.19, 'Agatti Island, Lakshadweep 682553', NULL, 0.6);

