INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 342000027, 'insert', 'bulk', 'Real beach; described in a Wanderlog trip log as ''Anthan (Andhaan) Beach'' on the island tour route, and listed as a sightseeing stop in Somans Leisure Tours'' Agatti itinerary (''Antham Beach''). Coordinates approximate, within ~1 km. A Google-maps-derived ''Andhaan beach restaurant'' listing exists but is not independently verifiable, so it is not included as a restaurant.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (342000028, 342002, 'Eastern Jetty', 'Eastern Jetty', 'The Eastern Jetty on Agatti is the ship embarkation and disembarkation point on the island''s eastern side, where passenger vessels connect Agatti to other islands. It is a regular stop on island sightseeing itineraries, offering clear-water views and photography of the boats and reef-fringed shore.', '30 minutes', 'October to March', 'Best photographed in the morning light; combine with the museum and aquarium in one north-island leg.', 'no', 'Lakshadweep', 1, 0, '6:30 AM', '6:15 PM', NULL, 2, 3, 10.868, 72.187, 'East coast, Agatti Island, Lakshadweep 682553', NULL, 0.48);

