INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (342000029, 342002, 'Western Jetty', 'Western Jetty', 'The Western Jetty on Agatti''s lagoon side is a stop on island sightseeing tours and a vantage point over the shallow western lagoon. It offers sunset views across the lagoon and is a handy reference point for water-sports and boat pickups.', '30 minutes', 'October to March', 'Come at sunset for the best lagoon views.', 'no', 'Lakshadweep', 0, 1, '6:30 AM', '6:15 PM', NULL, 2, 3, 10.855, 72.182, 'West coast (lagoon side), Agatti Island, Lakshadweep 682553', NULL, 0.48);

