INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (342000030, 342002, 'NIOT Seawater Desalination Plant', 'NIOT Seawater Desalination Plant', 'Agatti hosts a seawater thermal desalination plant set up by NIOT (National Institute of Ocean Technology), a working piece of infrastructure included in local sightseeing tours. It demonstrates low-temperature thermal desalination technology supplying fresh water to the island.', '30 minutes', 'October to March', 'Visits may need prior permission - ask your tour operator; it is an active industrial facility.', 'no', 'Lakshadweep', 0, 0, '6:30 AM', '6:15 PM', NULL, 2, 2, 10.86, 72.184, 'Agatti Island, Lakshadweep 682553', NULL, 0.4);

