INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (342000031, 342002, 'Agatti Public Library', 'Agatti Public Library', 'Agatti''s public library is a small civic institution listed among the island''s local sightseeing stops in package itineraries, alongside the museum and jetties. It serves the island''s roughly 7,000 residents and reflects everyday island life beyond the beaches.', '30 minutes', 'October to March', 'Best as a quick cultural stop during the island sightseeing tour; do not expect tourist-oriented exhibits.', 'no', 'Lakshadweep', 0, 0, '6:30 AM', '6:15 PM', NULL, 1, 2, 10.866, 72.186, 'Agatti village, Agatti Island, Lakshadweep 682553', NULL, 0.28);

