INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 342000031, 'insert', 'bulk', 'Real but low-value tourist stop; ''Public Library'' appears in ClubTravelscape''s Day-1 Agatti sightseeing list and HelloTravel''s itinerary. Coordinates approximate (village area), within ~1 km. Included for completeness of the island''s documented sights.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (342000032, 342002, 'Agatti Airport', 'Agatti Airport (AGX)', 'Agatti Airport (IATA: AGX) is the sole airport of Lakshadweep, at the southern tip of the 7.5 km island with flights from Kochi (and seasonally other cities). The short runway surrounded by water on three sides makes the landing itself a noted traveler experience; a partially restored vintage aircraft fuselage is displayed near the gate.', '1 hour', 'October to March', 'Book window seats; the approach over turquoise lagoons is the island''s most photographed aerial view.', 'no', 'Lakshadweep', 0, 1, '6:30 AM', '6:15 PM', NULL, 3, 4, 10.824, 72.176, 'Agatti Airport, southern tip, Agatti Island, Lakshadweep 682553', NULL, 0.68);

