INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 342000032, 'insert', 'bulk', 'Real; AGX coordinates ~10.8237N 72.1764E match published airport data. Southern-tip location and water-on-three-sides approach described by a Wanderlog trip log; vintage aircraft fuselage near the gate also from that log. Included as a transit landmark rather than a destination attraction.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (342000033, 342002, 'Agatti Fish Hatchery', 'Agatti Fish Hatchery', 'Agatti''s fish hatchery facility appears as a local sightseeing stop in island tour itineraries, tied to the island''s fishing economy and marine-research presence (ICAR facilities on the island). It is a minor working-facility stop rather than a developed tourist site.', '30 minutes', 'October to March', 'Ask your guide ahead whether the facility allows visitors that day; it is a working site.', 'no', 'Lakshadweep', 0, 0, '6:30 AM', '6:15 PM', NULL, 1, 2, 10.858, 72.184, 'Agatti Island, Lakshadweep 682553', NULL, 0.28);

