INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 342000033, 'insert', 'bulk', 'Weakly verified: ''Fish Hatchery'' appears once, in Somans Leisure Tours'' Agatti local-sightseeing list alongside Museum, Western side jetty, Eastern Side Jetty, Lagoon Beach, Antham Beach. No independent description found. Included with low priority and this caveat. Coordinates approximate, within ~1 km.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (342000034, 342002, 'Thakkaram Restaurant', 'Thakkaram Restaurant', 'Thakkaram is the multi-cuisine restaurant of the Agatti Island Beach Resort, a short walk from Agatti Airport. It serves Indian, continental, Chinese and Lakshadweep cuisine (including Jain options), with indoor or beachfront outdoor dining and optional barbecue dinners using the day''s catch. It is the most documented dine-in restaurant on Agatti.', '1-2 hours', 'October to March', 'Reserve the outdoor beach barbecue in the evening; non-residents should call ahead.', 'yes', 'Lakshadweep', 0, 1, '6:30 AM', '6:15 PM', NULL, 4, 3, 10.83, 72.178, 'Agatti Island Beach Resort, near Agatti Airport, Agatti Island, Lakshadweep 682553', NULL, 0.72);

