INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 342000034, 'insert', 'bulk', 'Real; ''THAKKARAM'' restaurant documented by IndianIslands.com, KeralaHolidays.com, BackToCulture and NativePlanet as the Agatti Island Beach Resort''s restaurant (Indian/Chinese/continental/Lakshadweep cuisine, beach barbecue option). Coordinates approximate (resort site near airport), within ~1 km. No official website found.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (342000035, 342002, 'Mubarak Hotel', 'Mubarak Hotel', 'Mubarak Hotel is a small local eatery on Agatti described by a traveler as the island''s only standalone restaurant, serving dosas, parottas, fish and chicken dishes. It is a budget local joint catering to residents and visitors staying with locals, unlike the resort restaurants that primarily serve their guests.', '1 hour', 'October to March', 'Expect simple local fare; vegetarian diners should confirm availability ahead.', 'no', 'Lakshadweep', 0, 0, '6:30 AM', '6:15 PM', NULL, 2, 3, 10.864, 72.185, 'Agatti village, Agatti Island, Lakshadweep 682553', NULL, 0.48);

