INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 342000035, 'insert', 'bulk', 'Real but thinly sourced: described in a detailed TripAdvisor.ie Agatti review (''Only one small restaurant Mubarak hotel where you get dosas, parotas, fish and chicken dishes''). No independent corroboration found; coordinates approximate (village area), within ~1 km. Excluded Google-maps-derived names (Fry King, Cucumber City, Patturmal Dweep Shree, Andhaan beach restaurant) as unverifiable beyond third-party listings.', 'pipeline');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3420005, 342, 342002, 'Eid-ul-Fitr (Idul-Fitr)', 'Mar-Apr', 'The grandest celebration in Lakshadweep, marking the end of Ramadan. Islanders gather at mosques for special prayers, wear new clothes, prepare dishes like pathiri, biryani and halwa, and exchange sweets and gifts; Zakatul-Fitr charity is distributed to the needy.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3420006, 342, 342002, 'Eid-ul-Adha (Bakrid)', 'May-Jun', 'The festival of sacrifice commemorating Prophet Ibrahim. Congregational prayers are followed by Qurbani, with meat shared among family, neighbours and the poor, emphasizing charity and community welfare.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3420007, 342, 342002, 'Milad-un-Nabi', 'Aug-Sep', 'The birth anniversary of Prophet Muhammad, observed with religious recitations, sermons and community prayers at decorated mosques, distribution of sweets, and charitable activities.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3420008, 342, 342002, 'Muharram', 'Jun-Jul', 'Solemn observance of Imam Hussain''s martyrdom at Karbala, with special prayers, Majlis gatherings, Quran recitations and chest-beating taziya processions; many devotees distribute food and water (Sabeel) to the public.');

