INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (354000001, 354001, 'Sri Aurobindo Ashram', 'Sri Aurobindo Ashram', 'Spiritual community founded in 1926 by Sri Aurobindo and the Mother (Mirra Alfassa) in White Town. The main building on Rue de la Marine houses the samadhi shrines of Sri Aurobindo and the Mother, covered daily with fresh flowers. Visitors may meditate in the courtyard and visit the ashram bookshop; silence is observed inside.', '1-2 hours', 'October to March', 'Switch off your phone, remove footwear, and observe total silence inside the courtyard; photography is not allowed without permission.', 'no', 'Puducherry', 0, 0, '6:04 AM', '6:12 PM', 'Free entry', 5, 5, 11.9366, 79.83401, '9, Rue de la Marine, White Town, Puducherry 605001, India', 'https://www.sriaurobindoashram.org/', 1.0);

