INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3540001, 354, 354001, 'Pongal', 'mid-January', 'Tamil Nadu''s harvest festival celebrated over four days (Bhogi, Thai Pongal, Mattu Pongal, Kaanum Pongal), with the traditional sweet pongal dish cooked in new clay pots. Homes are decorated with kolams and sugarcane; cattle are honoured on Mattu Pongal.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3540002, 354, 354001, 'International Yoga Festival', 'January', 'Annual four-day festival organised by the Puducherry Department of Tourism since 1992/1993, drawing around a thousand delegates and yoga experts. Features yogasana competitions, discourses, workshops, lecture demonstrations, and cultural programmes, with the valedictory usually at Gandhi Thidal on Beach Road.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3540003, 354, 354001, 'Masi Magam', 'February–March', 'Annual temple festival on the full-moon day of the Tamil month of Masi, when temple deities are taken in procession to the sea for the theerthavari (holy dip). Celebrated grandly at Puducherry''s seafront temples including the Manakula Vinayagar Temple.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3540004, 354, 354001, 'Puducherry Heritage Festival', 'February–March', 'Annual festival led by INTACH Puducherry, People for Pondicherry''s Heritage, and PondyCAN with the Tourism Department, celebrating the city''s built, natural, and living heritage. Programming includes heritage walks, open houses of historic buildings, craft bazaars, food walks, talks, and performances; the 9th edition ran 1 February–15 March.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3540005, 354, 354001, 'Bastille Day', 'July', 'France''s National Day (14 July) celebrated with pride in the former French colony: wreath-laying at the French War Memorial on Beach Road by the District Collector and the French Consul General, with the police band playing the Indian and French anthems. French and Indian flags fly side by side across White Town.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3540006, 354, 354001, 'Deepavali', 'October–November', 'The festival of lights celebrated across Puducherry with oil lamps, fireworks, and festive sweets; temples and White Town streets are illuminated. Dates follow the lunar calendar, usually falling in October or November.');

