INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (354000027, 354002, 'Karaikal Ammaiyar Temple', 'Karaikal Ammaiyar Temple', 'Karaikal''s most sacred shrine, built in 1929 by Malaiperumal Pillai and dedicated to Karaikal Ammaiyar (Punithavathi) - the only woman among the 63 Nayanmar saints, who is said to have walked on her hands to Mount Kailash. The complex also houses shrines of Vinayagar and Murugan, and hosts the famous Mangani Tirunal mango festival each June-July.', '1 hour', 'Early morning or evening; Jun-Jul during the Mangani Tirunal festival', 'Plan a visit during Mangani Tirunal (Aani full-moon, Jun-Jul) when mangoes are showered on the deity''s procession and free mango and curd rice are distributed.', 'no', 'Puducherry', 0, 0, '6:00 AM', '6:00 PM', NULL, 9, 8, 10.92371, 79.83204, 'Bharathiyar Road, Karaikal, Puducherry 609602', NULL, 1.72);

