INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (354000028, 354002, 'Thirunallar Saniswaran Temple', 'Thirunallar Saniswaran Temple (Dharbaranyeswarar Temple)', 'One of Tamil Nadu''s Navagraha temples, dedicated to Saturn (Shani), at Thirunallar about 8 km west of Karaikal. Devotees believe a dip in the Nala Theertham tank relieves Saturn''s afflictions; the temple is renowned for the Emerald Lingam abhishekam performed five times a day. Draws lakhs of pilgrims during Sani Peyarchi (Saturn transit, every ~2.5 years).', '2 hours', 'Early morning to avoid queues; avoid Sani Peyarchi days unless attending the ritual', 'The Emerald Lingam abhishekam happens five times daily; special-queue tickets (Rs 100-150) cut long waits.', 'no', 'Puducherry', 0, 0, '6:00 AM', '6:00 PM', 'Rs 100', 9, 8, 10.97418, 79.77021, 'Thirunallar, Karaikal district, Puducherry 609603', NULL, 1.72);

