INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (354000029, 354002, 'Our Lady of Angels Church', 'Our Lady of Angels Church', 'Neo-Gothic Catholic church on Church Street built by the French in 1822 and rebuilt in 1828, with a 133-ft bell tower added in 1891. The statue of Our Lady of Angels was installed in 1863 and the church consecrated in 1867. Hosts the 10-day Thetheravu Matha festival each August, ending with a chariot procession of the Virgin Mary through Karaikal''s streets.', '45 minutes', 'Morning or evening; August during the Thetheravu Matha festival', 'The August 15 feast is the highlight - Mary''s image is taken in a decorated chariot through the town''s main streets.', 'no', 'Puducherry', 0, 0, '6:00 AM', '6:00 PM', NULL, 7, 7, 10.916889, 79.834206, 'Church Street, Karaikal, Puducherry 609602', NULL, 1.4);

