INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (354000033, 354002, 'Mastan Syed Dawood Dargah', 'Mastan Syed Dawood Dargah', 'Tomb of the Sufi saint Mastan Syed Dawood, who was born in Bukhara (Uzbekistan) and died at Karaikal in February 1829 at a reputed age of about 120. A revered local shrine about 1.2 km from Karaikal railway station; the annual Kandoori festival is celebrated here each November with a flag hoisting, floats and fireworks.', '45 minutes', 'Morning or evening; November during the Kandoori festival', 'Dress modestly and remove footwear before entering the shrine complex.', 'no', 'Puducherry', 0, 0, '6:00 AM', '6:00 PM', NULL, 6, 7, 10.92174, 79.83146, 'Melakasakudy Main Road (near Mastan Palli Street), Karaikal, Puducherry 609602', NULL, 1.28);

