INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (354000035, 354002, 'Nithyakalyana Perumal Temple', 'Nithyakalyana Perumal Temple', 'Ancient Vishnu temple on Perumal Kovil Street (Bharathiyar Street) near the Karaikal Ammaiyar Temple, housing a reclining (Sayana) form of Perumal with Sridevi and Bhudevi. The Chandra Theertham tank lies between this temple and the Ammaiyar temple; the deity''s divine wedding (Nithyakalyana) is celebrated daily.', '45 minutes', 'Morning or evening', 'Combine with the adjacent Karaikal Ammaiyar Temple - both are on the same street.', 'no', 'Puducherry', 0, 0, '6:00 AM', '6:00 PM', NULL, 7, 7, 10.922975, 79.832255, '2, Perumal Kovil Street, Bharathiyar Street, Karaikal, Puducherry 609602', NULL, 1.4);

