INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (354000036, 354002, 'Jadaayupureeswar Temple', 'Jadaayupureeswar Temple, Thirumalairayanpattinam', 'Shiva temple at Thirumalairayanpattinam (T.R. Pattinam) on the Karaikal-Nagapattinam road, about 8 km south of Karaikal, associated in local tradition with Jatayu - the vulture-king of the Ramayana who is said to have been cremated nearby. Free entry; a quiet, offbeat temple stop.', '45 minutes', 'Morning or evening', 'Pair it with the nearby Aayiram Kaliamman Temple in the same town.', 'no', 'Puducherry', 0, 0, '6:00 AM', '6:00 PM', NULL, 6, 7, 10.85943, 79.81916, 'Thirumalairayanpattinam (T.R. Pattinam), Karaikal-Nagapattinam Road, Puducherry', NULL, 1.28);

