INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (354000037, 354002, 'Karaikal Mangrove Forest', 'Karaikal Mangrove Forest (Eco Beach)', 'Mangrove eco-beach on the banks of the Arasalar river about 1.5 km from Karaikal railway station, listed as a key attraction by the Karaikal municipality. A quiet spot for nature walks and birdwatching, with migratory birds visiting in season.', '1 hour', 'Early morning for birds; Nov-Feb for migratory species', 'Bring binoculars in the winter months for migratory birds; pair with the nearby Arasalar Boat House.', 'no', 'Puducherry', 1, 0, '6:00 AM', '6:00 PM', NULL, 6, 7, 10.92, 79.84, 'Near Arasalar river mouth, Karaikal, Puducherry 609602', NULL, 1.28);

