INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (354000040, 354002, 'Karaikal Port', 'Karaikal Port', 'A working private deep-water commercial port at Keezhavanjore village about 10 km north of Karaikal town, operational since April 2009 (developed by MARG) and acquired by Adani Ports in April 2023, with a deep draft of 14.5 m. Not a visitor attraction - no public entry - but a notable landmark of the coast; ships and harbour lights are visible from the shoreline.', '20 minutes', 'Daytime, as a landmark viewed from the shoreline', 'There is no public access to the port itself - view ships and harbour activity from the nearby shoreline.', 'no', 'Puducherry', 0, 0, '6:00 AM', '6:00 PM', NULL, 4, 5, 10.995, 79.866, 'Keezhavanjore village, Karaikal district, Puducherry', NULL, 0.88);

