INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (354000041, 354002, 'Fort Dansborg', 'Fort Dansborg, Tharangambadi', 'Day trip ~35 km north of Karaikal: the 1620 Danish East India Company fort at Tharangambadi (Tranquebar), built under Admiral Ove Gjedde with the Thanjavur king Raghunatha Nayak - the second-largest Danish fort in the world after Kronborg. Entry Rs 5 for Indians and Rs 50 for foreigners; a small museum sits inside. The sea-facing ramparts are a fine sunrise spot over the Bay of Bengal.', '2 hours', 'Morning; arrive by sunrise for the sea-facing ramparts', 'Closed on Fridays. The museum inside covers 400+ years of Danish history in India - allow an hour for it.', 'no', 'Puducherry', 1, 0, '6:00 AM', '6:00 PM', 'Rs 5', 8, 8, 11.024785, 79.855689, 'Tharangambadi (Tranquebar), Nagapattinam district, Tamil Nadu 609313', NULL, 1.6);

