INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (354000042, 354002, 'Nagore Dargah', 'Nagore Dargah (Syed Shahul Hameed Dargah)', 'Day trip ~12 km south of Karaikal: the grand Sufi shrine of Saint Syed Shahul Hameed (1490-1579), famed for its five minarets - the tallest at 131 ft was built by Maratha ruler Pratap Singh. Inner doors open 4:30-7:00 AM and 6:25-9:30 PM (plus Fridays 12-2:30 PM); outer doors stay open. The 14-day Kanduri (Urs) festival is held here each Nov-Dec.', '2 hours', 'Early morning or evening; Nov-Dec during the Kanduri festival', 'The sandalwood (santhanakoodu) procession on the 10th day of the Kanduri festival is the main event - arrive early for a spot.', 'no', 'Puducherry', 0, 0, '6:00 AM', '6:00 PM', NULL, 8, 8, 10.818677, 79.841881, 'Nagore, Nagapattinam district, Tamil Nadu 611002', 'https://www.nagoredargahshariff.com/', 1.6);

