INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (354000043, 354002, 'Basilica of Our Lady of Good Health', 'Basilica of Our Lady of Good Health, Velankanni', 'Day trip ~25 km south of Karaikal: the great Marian basilica of Velankanni, the ''Lourdes of the East'', open 5:00/5:30 AM to 9 PM daily with free entry. The annual feast in Aug-Sep draws around 2 million pilgrims. A major Catholic pilgrimage centre with a beach-side setting.', '2-3 hours', 'Morning; avoid the Aug-Sep feast peak unless attending it', 'The Aug-Sep annual feast draws ~2 million pilgrims - book stay far ahead or visit outside the feast season for a calm darshan.', 'no', 'Puducherry', 0, 0, '6:00 AM', '6:00 PM', NULL, 9, 9, 10.680298, 79.849939, 'Velankanni, Nagapattinam district, Tamil Nadu 611111', 'http://vailankannishrine.net/', 1.8);

