INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (354000044, 354002, 'Poompuhar Beach and Silappathikaram Art Gallery', 'Poompuhar Beach and Silappathikaram Art Gallery', 'Day trip ~50 km north of Karaikal: the ancient Chola port town of Poompuhar, with the striking 7-storey, 50-ft Silappathikaram Art Gallery whose walls depict scenes from the Tamil epic Silappathikaram, sculpted by the Mamallapuram sculpture college. Open 8:30 AM-1 PM and 2:30-8:30 PM; entry was Rs 5 adult/Rs 2 child in a 2017 review. The adjacent beach faces the Bay of Bengal - a good sunrise stop.', '2-3 hours', 'Morning; sunrise at the beach', 'The gallery entry fee in published reviews is from 2017 - confirm the current fee locally before visiting.', 'no', 'Puducherry', 1, 0, '6:00 AM', '6:00 PM', 'Rs 5', 7, 8, 11.1417, 79.8536, 'Poompuhar (Poompuhar), Mayiladuthurai district, Tamil Nadu 609107', NULL, 1.48);

