INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (354000045, 354002, 'Muthupet Mangrove Forest', 'Muthupet Mangrove Forest', 'Day trip ~45 km southwest of Karaikal: a large lagoon mangrove forest where the forest department runs boat rides (about Rs 1500 per trip for up to 10 people per a 2025 travel article - confirm locally) through dense mangrove channels. A birding hotspot with flamingos and migratory birds in season. Forest-department permission/booking is needed - book ahead.', '3 hours', 'Morning; Nov-Feb for migratory birds', 'Book the forest-department boat ride ahead of time and carry binoculars for flamingos and waders.', 'yes', 'Puducherry', 0, 0, '6:00 AM', '6:00 PM', 'Rs 1500', 7, 8, 10.73, 79.52, 'Muthupet lagoon, Thiruvarur district, Tamil Nadu', NULL, 1.48);

