INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (354000046, 354002, 'Sikkal Singaravelar Temple', 'Sikkal Singaravelar Temple (Navaneetheswarar Temple)', 'Day trip ~20 km southwest of Karaikal: the Navaneetheswarar Shiva temple at Sikkal, famous as the place where Lord Murugan (Singaravelar) received his divine spear (vel) from Parvati before slaying the demon Sooran. The annual Soorasamharam festival is famed for the deity''s idol ''sweating'' during the ritual. Open 6 AM-12 noon and 4-9 PM; free entry.', '1-2 hours', 'Morning; October-November for the Soorasamharam festival', 'Visit during the Soorasamharam festival (Oct-Nov) to witness the famous ''sweating'' ritual of the Singaravelar idol.', 'no', 'Puducherry', 0, 0, '6:00 AM', '6:00 PM', NULL, 7, 8, 10.7567, 79.799061, 'Sikkal, Nagapattinam district, Tamil Nadu 611108', NULL, 1.48);

