INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3540007, 354, 354002, 'Mangani Tirunal', 'Jun-Jul', 'The great mango festival of the Karaikal Ammaiyar Temple, celebrated on the full-moon day of the Tamil month of Aani. The deity''s procession is showered with mangoes, and free mangoes and curd rice are distributed to devotees.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3540008, 354, 354002, 'Karaikal Carnival', 'January', 'The district administration''s annual tourism event (held Jan 16-18 in 2026) at the district stadium and Karaikal beach - a food festival, flower show, dog show, art and craft expo, cultural programmes and sports events.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3540009, 354, 354002, 'Kandoori Festival', 'November', 'The annual 10-day festival of the Mastan Syed Dawood Dargah - flag hoisting on a ship-mast-like pole, floats, music and fireworks, drawing devotees of the Sufi saint.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3540010, 354, 354002, 'Thetheravu Matha Festival', 'August', 'The 10-day feast of Our Lady of Angels Church - flag hoisting on Aug 6, feast on Aug 15. The image of the Virgin Mary is taken in a decorated chariot through Karaikal''s streets.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3540011, 354, 354002, 'Sani Peyarchi', 'Varies (Saturn transit cycle; last ~Mar 2026)', 'The transit of Saturn from one zodiac sign to the next, observed every ~2.5 years at the Thirunallar Saniswaran Temple. Special poojas and abhishekams draw lakhs of devotees; expect very large crowds.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3540012, 354, 354002, 'Kanduri Urs (Urus Mubarak)', 'Nov-Dec (Islamic lunar calendar)', 'The 14-day death-anniversary (Urs) festival of Saint Syed Shahul Hameed at the Nagore Dargah - flag hoisting, Quran recitations, fireworks, and the famous sandalwood (santhanakoodu) procession. The 468th edition''s flag hoisting was on 21 Nov 2025 per the dargah''s official site.');

-- city: Mahe (id 1243)
