INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (354000053, 354003, 'St. Teresa''s Shrine', 'St. Teresa''s Shrine', 'One of the oldest shrines in India and probably the oldest in Malabar, dedicated to St. Teresa of Avila, patron of Mahe. The Mahe mission was established by Revd. Father Dominic of St. John of the Cross in 1723 and the shrine was created in 1736, renovated in 1788, with a large clock fixed in 1855. Devotees of all communities visit; the annual feast draws thousands from across South India.', '1-2 hours', 'October to March', 'Visit in the early morning to avoid crowds; the annual feast days (mid-October) are the busiest but most atmospheric time.', 'no', 'Puducherry', 0, 0, '6:17 AM', '6:10 PM', NULL, 5, 4, 11.70293, 75.53453, 'I K Kumaran Master Rd, Mahé, Puducherry 673310', NULL, 0.92);

