INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (354000054, 354003, 'Tagore Park', 'Tagore Park', 'Small beachfront park beside the Government House at the Mayyazhi estuary, named after Rabindranath Tagore. It holds the Statue of Mariame, erected in 1789 to mark the 100th anniversary of the French Revolution, with the slogans ''Liberté, Égalité, Fraternité'' etched on it. A popular sunset and evening leisure spot for locals and visitors.', '1-2 hours', 'October to March', 'Go at sunset for the best views over the Arabian Sea; combine with the adjacent riverside walkway.', 'no', 'Puducherry', 0, 1, '6:17 AM', '6:10 PM', NULL, 4, 4, 11.703329, 75.531907, 'Mahe, Puducherry 673310 (near Government House, estuary side)', NULL, 0.8);

