INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (354000055, 354003, 'Mahe Riverside Walkway', 'Mahe Riverside Walkway', 'A nearly 2 km lit promenade along the banks of the Mayyazhi (Mahe) River, built as a landscaped public walkway with park benches. One end near the Government House carries a visual portrayal of the novel ''Mayyazhippuzhayude Theerangalil'' by M. Mukundan, the ''story teller of Mahe''. Best experienced at dusk when the river and estuary views are calm.', '1-2 hours', 'October to March', 'Evening walk is best; the walkway is well lit and has benches, so plan to linger near Azhimukham at sunset.', 'no', 'Puducherry', 0, 1, '6:17 AM', '6:10 PM', NULL, 4, 5, 11.701, 75.533, 'Riverside, Mahe, Puducherry 673310 (Phase 1 near Manjakkal)', NULL, 0.88);

