INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (354000056, 354003, 'Azhimukham (Mayyazhi Estuary)', 'Azhimukham (Mayyazhi Estuary)', 'The estuary where the Mayyazhi River meets the Arabian Sea; ''Mayyazhi'' itself means ''beautiful estuary''. Flanked by blue wavy ocean on one side and the rippling river on the other, it is Mahe''s signature scenic point. The area was recently redeveloped with a walkway along the river bank toward the sea.', '1-2 hours', 'October to March', 'Visit at low tide and around sunset for the widest beach stretch and the best photographs of river meeting sea.', 'no', 'Puducherry', 0, 1, '6:17 AM', '6:10 PM', NULL, 4, 4, 11.695, 75.5295, 'Estuary mouth, south Mahe, Puducherry 673310', NULL, 0.8);

