INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (354000067, 354003, 'Thalassery Fort', 'Thalassery Fort', 'A 17th-century fort in Thalassery town, about 10 km north of Mahe, built as a British stronghold and now maintained by the Archaeological Survey of India. It sits on a low hill running down to the sea with laterite walls, secret tunnels to the sea, and old cannons. Open to the public 8 AM to 6 PM.', '2-3 hours', 'October to March', 'Combine with the nearby Thalassery beach and the town''s famous biryani eateries; the fort is a short drive from Mahe (~10 km).', 'no', 'Puducherry', 0, 1, '6:17 AM', '6:10 PM', NULL, 5, 4, 11.7475, 75.487, 'Thalassery, Kannur, Kerala 670101', NULL, 0.92);

