INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3540013, 354, 354003, 'Feast of St. Teresa of Avila', 'October', 'The annual feast at St. Teresa''s Shrine, Mahe''s biggest religious festival, drawing thousands of devotees of all communities from across South India. The shrine is dedicated to St. Teresa of Avila, the town''s patron.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3540014, 354, 354003, 'Theyyam Season', 'Nov-Apr', 'Season of Theyyam ritual-art performances at kavus (sacred groves) around the Mahe-Thalassery region, including the famous Sri Muthappan Temple at Parassinikadavu. Night-long performances with elaborate costumes, fire rituals, and drumming.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3540015, 354, 354003, 'Onam', 'Aug-Sep', 'Kerala''s harvest festival, widely celebrated in Mahe with floral pookalams, traditional sadya feasts, and cultural programs, reflecting the town''s Malayali roots.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3540016, 354, 354003, 'Vishu', 'April', 'The Malayali new year, observed in Mahe with the vishukkani ritual arrangement, fireworks, and festive meals.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3540017, 354, 354003, 'Puducherry Liberation Day', 'November', 'Marks the de facto transfer of the French Indian territories, including Mahe, to India on 1 November 1954. Observed across the Union Territory with official ceremonies.');

