INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (354000079, 354004, 'Yanam Beach (Rajiv Gandhi Beach)', 'Yanam Beach', 'Yanam Beach, also known as Rajiv Gandhi Beach, is a riverside beach on the Gautami Godavari in Yanam, about 9 km inland from the Bay of Bengal. The beachfront has a promenade with seating, a cemented area for evening strolls, and a 26-foot bronze statue of Bharat Mata along with idols of Christ the Redeemer and a Shiva Linga between two elephants. Boating and cruise rides to neighbouring islands operate from the beach.', '2-3 hours', 'November to February', 'Go around 5 PM: walk the promenade, then stay for sunset over the Godavari; avoid entering the water, currents near the river mouth are strong.', 'no', 'Puducherry', 0, 1, '5:51 AM', '5:49 PM', NULL, 5, 4.5, 16.72505, 82.21013, 'Ferry Road, Yanam, Puducherry 533464, India', NULL, 0.96);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (354000079, 354000079, '24/7 (open round the clock)', '24/7 (open round the clock)', '24/7 (open round the clock)', '24/7 (open round the clock)', '24/7 (open round the clock)', '24/7 (open round the clock)', '24/7 (open round the clock)', 'traveltriangle.com lists timings as 24/7; river swimming is unsafe, boat rides run daytime/evening only');

