INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 354000079, 'insert', 'bulk', 'Geocoder resolved ''Rajiv Park, Ferry Road, I. Polavaram'' (relevance 75, FULL_ADDRESS) — kept address as Yanam municipality since the beach promenade is Yanam''s; coordinates approximate to the promenade/park area, real beach stretch extends along the riverbank.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (354000080, 354004, 'Godavari Boating Point, Yanam Beach', 'Yanam Beach Boating Point', 'The boating point on the Godavari at Yanam Beach offers motorboat and cruise rides on the river, including trips to the neighbouring islands in the estuary. It is one of the main recreational draws of the Yanam waterfront and is listed as a standalone attraction with over 1,600 ratings on local listings.', '1-2 hours', 'November to February', 'Ask the boat operator for the short island-cruise option if available; morning rides are calmer and better for photos.', 'no', 'Puducherry', 0, 1, '5:51 AM', '5:49 PM', NULL, 4, 4.5, 16.7275, 82.2075, 'Ferry Road, near Yanam Beach, Yanam, Puducherry 533464, India', NULL, 0.84);

