INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (354000081, 354004, 'Yanam Ferry Road', 'Ferry Road', 'The Yanam Ferry Road, inaugurated by Puducherry CM R.V. JanakiRaman on 11 January 2000, runs along the Gautami Godavari and doubles as Yanam''s heritage promenade, with statues of famous personalities installed on the footpath. The ferry landing (Pant) is a working river crossing: over 10,000 passengers travel daily to and from the Konaseema region (Amalapuram side) toward Kakinada.', '1 hour', 'November to February', 'Walk the full footpath in the evening to see the statue row; if curious, watch (or ride) the working ferry Pant crossing the Godavari.', 'no', 'Puducherry', 0, 1, '5:51 AM', '5:49 PM', NULL, 3, 3.5, 16.729, 82.216, 'Ferry Road, Yanam, Puducherry 533464, India', NULL, 0.64);

