INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (354000082, 354004, 'Dariyala Thipa Road', 'Dariyala Thipa Road', 'Dariyala Thipa Road is the riverbank road of the Gautami Godavari running east from Yanam town to Savitri Nagar village, beyond which the river flows into the Bay of Bengal. It is a scenic coconut-grove-lined stretch along the water and is listed among Yanam''s attractions; the road was built by the Andhra Pradesh Roads and Buildings Department.', '1 hour', 'November to February', 'Best done by bicycle or slow two-wheeler ride at sunset; the road is a local route, so keep to the side.', 'no', 'Puducherry', 1, 1, '5:51 AM', '5:49 PM', NULL, 3, 3.5, 16.7265, 82.2135, 'Dariyala Thipa Road, riverbank of Gautami Godavari, Yanam, Puducherry 533464, India', NULL, 0.64);

