INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (354000083, 354004, 'St. Ann''s Catholic Church', 'St. Ann''s Catholic Church', 'St. Ann''s Roman Catholic Church is the French colonial-era church of Yanam, built in 1846. It is the centrepiece of Yanam''s Catholic community and hosts the annual Catholic Festival each March, drawing devotees of all faiths who come to pray to Mother Mary. The church''s French stained-glass heritage and the nearby cemetery with tombs of French nationals make it Yanam''s key colonial landmark.', '30 minutes to 1 hour', 'October to March', 'Visit during the March festival for the full atmosphere, or on a quiet weekday to see the French-era interiors; also note the French cemetery nearby.', 'no', 'Puducherry', 0, 0, '5:51 AM', '5:49 PM', NULL, 4, 4, 16.732, 82.2205, 'Yanam town, Puducherry 533464, India', NULL, 0.8);

