INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (354000084, 354004, 'Sri Rajarajeswara Temple (Sivalayam)', 'Sri Rajarajeswara Temple', 'The Sri Rajarajeswara Temple, known locally as Sivalayam, is a 15th-century temple built by the Chalukya kings of Rajamahendravaram, dedicated to Lord Shiva as Sri Rajarajeswara. Its annual 20-day Kalyanotsavam in the month of Magha (Jan-Feb) — with the Lord dressed as bridegroom, street chariot processions, Rathostavam and Trisulatirtham — is Yanam''s most important festival.', '1-2 hours', 'October to March', 'Plan a January/February visit to witness the Kalyanotsavam; on ordinary days go before 10 AM for darshan.', 'no', 'Puducherry', 0, 0, '5:51 AM', '5:49 PM', NULL, 5, 4.5, 16.7308, 82.2185, 'Banks of Corangi River (Atreya Godavari), Yanam, Puducherry 533464, India', NULL, 0.96);

