INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (354000085, 354004, 'Vishnalayam (Venkanna Babu Temple)', 'Venkateswara Temple (Venkanna Babu)', 'Vishnalayam, also called the Venkanna Babu or Alivelu Manga Sametha Shri Venkateswara Temple, is a 15th-century temple on Vishnalayam Street built by the Chalukya kings of Rajamahendravaram. The presiding idol of Lord Venkateswara is noted for its large moustache, like the Satyanarayana Swamy of Annavaram, and the god is locally called Meesala Venkanna / Chalidikoodu Venkanna. It hosts the annual Venkanna Babu Kalyanotsavam in February-March and a 10-day Brahmotsavam in September-October.', '1-2 hours', 'October to March', 'Time your visit for the Feb-Mar Kalyanotsavam or Sep-Oct Brahmotsavam for the biggest experience; carry offerings for the prasadam counter.', 'no', 'Puducherry', 0, 0, '5:51 AM', '5:49 PM', NULL, 5, 4.5, 16.73125, 82.22765, 'Vishnalayam Street, Yanam, Puducherry 533464, India', NULL, 0.96);

