INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (354000086, 354004, 'Grand Mosque, Yanam', 'Grand Mosque', 'The Grand Mosque of Yanam stands on a site donated by the French Government in 1848; a small mosque was built there then, remodelled in 1956, demolished and rebuilt in 1978, and extended into the present Grand Mosque in 1999-2000. It is Yanam''s main mosque and hosts Ramzan, Bakrid and Milad-un-Nabi functions.', '30 minutes', 'October to March', 'Dress modestly and visit between prayers; the French land-grant history makes it worth a heritage stop.', 'no', 'Puducherry', 0, 0, '5:51 AM', '5:49 PM', NULL, 3, 3, 16.7313, 82.2213, 'Yanam town, Puducherry 533464, India', NULL, 0.6);

