INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (354000088, 354004, 'Yanam District Sunrise View Point', 'Yanam District Sunrise View Point', 'The Yanam District Sunrise View Point is a riverfront spot on the Godavari where locals and visitors gather to watch the sunrise over the water. It is a short morning walk from the beach/Ferry Road precinct and is the town''s best-known dawn viewpoint.', '1 hour', 'November to February', 'Arrive at least 15 minutes before sunrise; the river mist on cool winter mornings makes for the best photos.', 'no', 'Puducherry', 1, 0, '5:51 AM', '5:49 PM', NULL, 4, 4, 16.729, 82.2105, 'Godavari riverfront, Yanam, Puducherry 533464, India', NULL, 0.8);

