INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 354000088, 'insert', 'bulk', 'Listed on JustDial Yanam attractions with ~4.5 rating; coordinates approximate to the eastern riverfront stretch.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (354000089, 354004, 'French Colonial Heritage (Administrator''s Building & Court House)', 'French Colonial Buildings', 'Yanam''s surviving French colonial architecture is modest — the office of the Deputy Collector (Administrator''s building), the Court House built in 1846, and a cemetery with tombs of French nationals, plus villa-style ancestral homes of Franco-Yanam families along narrow lanes. A replica Eiffel Tower was planned by the UT administration to strengthen the French connection. Very few French-era buildings survive, so a walk through the old quarter is a heritage stroll rather than a monument visit.', '1 hour', 'October to March', 'Do this as a 45-minute morning walk through the old town; the buildings are working offices, so admire from outside.', 'no', 'Puducherry', 0, 0, '5:51 AM', '5:49 PM', NULL, 4, 3.5, 16.7325, 82.223, 'Yanam town (Administrator''s Building & Court House), Puducherry 533464, India', NULL, 0.76);

