INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 354000089, 'insert', 'bulk', 'Remnant list (church, administrator''s building, court building, cemetery, Maniam Kankaya''s residence) from Zenodo paper; Caravan notes ''very few surviving buildings''; coordinates approximate to the old town quarter.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (354000090, 354004, 'Yanam Fish Market', 'Yanam Fish Market', 'Yanam''s fish market is one of the town''s liveliest morning sights, stocked with the day''s catch from the Godavari estuary and the Bay of Bengal — mullet, catfish, prawns and local varieties. It is the natural food counterpart to Yanam''s beach-and-boat tourism and a listed local attraction.', '1 hour', 'Year-round', 'Go before 9 AM for the freshest catch and the busiest atmosphere; pick up prawns to have cooked at a local eatery.', 'no', 'Puducherry', 0, 0, '5:51 AM', '5:49 PM', NULL, 3, 3.5, 16.73, 82.224, 'Yanam town, Puducherry 533464, India', NULL, 0.64);

