INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (354000092, 354004, 'Tuesday Market (Marche du mardi)', 'Tuesday Market', 'The Tuesday market (Marche du mardi, or Mangalavaram Santa) was historically famous under French rule: Telugu people from across the Madras Presidency visited Yanam''s Tuesday market to buy foreign and smuggled goods. It remains Yanam''s principal weekly bazaar for local produce, fish, textiles and household goods.', '1-2 hours', 'Year-round', 'Visit on a Tuesday morning for the full market experience; combine with the fish market nearby.', 'no', 'Puducherry', 0, 0, '5:51 AM', '5:49 PM', NULL, 3, 3, 16.731, 82.2225, 'Yanam town, Puducherry 533464, India', NULL, 0.6);

