INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (354000093, 354004, 'Coringa Wildlife Sanctuary', 'Coringa Wildlife Sanctuary', 'The Coringa Wildlife Sanctuary, about 20 km from Yanam, is India''s second-largest stretch of mangrove forest, spread over 235.7 sq km of the Godavari estuary where the river meets the Bay of Bengal. It shelters over 35 mangrove species and 120 bird species plus endangered Smooth Indian otters, fishing cats and Olive ridley turtle nesting beaches. Boats into the mangrove creeks, a 2-km nature trail and an eco-tourism centre are the main draws.', '3-4 hours', 'November to February', 'Book the boat ride first on arrival (boats can be cancelled in rain/flood season); carry binoculars and mosquito repellent, and keep plastic out - it is strictly prohibited.', 'no', 'Puducherry', 0, 0, '5:51 AM', '5:49 PM', 'Rs 20 (adults; Rs 10 children)', 5, 4.5, 16.8804374, 82.2458296, 'Coringa Wild Life Sanctuary Rd, Thallarevu, Andhra Pradesh, India', 'https://forests.ap.gov.in/sanctuaries.php', 0.96);

