INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (354000094, 354004, 'Draksharamam Bhimeswara Swamy Temple', 'Draksharamam Bhimeswara Temple', 'The Bhimeswara Swamy Temple at Draksharamam, about 25-30 km from Yanam, is one of the five Pancharama Kshetras sacred to Lord Shiva. It houses a 14-foot Shiva Lingam visible in two tiers and draws large crowds in Karthika Masam.', '2-3 hours', 'October to March', 'Combine with a Yanam overnight stay in Nov (Karthika Masam); expect crowds on Mondays and Pradosham days.', 'no', 'Puducherry', 0, 0, '5:51 AM', '5:49 PM', NULL, 4, 4.5, 16.79281, 82.06339, 'Bhimeswara Temple, Draksharamam, Ramachandrapuram 533262, Andhra Pradesh, India', NULL, 0.84);

