INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (354000095, 354004, 'Sri Kukkuteswara Swamy Temple, Pithapuram', 'Sri Kukkuteswara Temple, Pithapuram', 'The Sri Kukkuteswara Swamy Temple at Pithapuram, about 50 km from Yanam by road, is an important Shaivite temple and Shakti Peetha (Puruhutika Devi), one of the 18 Ashtadasa Shakti Peethas. Pithapuram is also known for the Dattatreya temple tradition and draws steady pilgrim traffic.', '2 hours', 'October to March', 'Easily combined with a Draksharamam trip; Pithapuram is on the Kakinada corridor so hire a day cab from Yanam.', 'no', 'Puducherry', 0, 0, '5:51 AM', '5:49 PM', NULL, 4, 4, 17.10635, 82.24513, 'Shri Kukkuteshwara Swamy Temple, Kakinada Road, Pithapuram 533450, Andhra Pradesh, India', NULL, 0.8);

