INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (354000096, 354004, 'Annavaram Satyanarayana Swamy Temple', 'Sri Satyanarayana Swamy Temple, Annavaram', 'The Sri Satyanarayana Swamy Temple at Annavaram, about 80 km from Yanam, is regarded as the second most important temple of Andhra Pradesh after Tirupati. Presiding deity Lord Satyanarayana Swamy is famous for the Vrathams performed here, especially by newly married couples seeking blessings. The temple sits atop Ratnagiri hill with views of the surrounding countryside.', 'Full day', 'October to March', 'This is a full-day trip from Yanam (80 km); start early to make the return comfortable, or stay overnight at Annavaram.', 'no', 'Puducherry', 0, 0, '5:51 AM', '5:49 PM', NULL, 5, 4.5, 17.28371, 82.40229, 'Shri Veera Venkata Satyanarayana Swamy Vari Temple, Annavaram, Sankhavaram 533406, Andhra Pradesh, India', NULL, 0.96);

