INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (354000097, 354004, 'Antarvedi Sri Lakshmi Narasimha Swamy Temple', 'Sri Lakshmi Narasimha Temple, Antarvedi', 'The Sri Lakshmi Narasimha Swamy Temple at Antarvedi, about 70-75 km from Yanam, stands where the Godavari meets the Bay of Bengal. The temple and its beachside setting make it a combined pilgrimage-and-coast day trip from Yanam via the Konaseema delta villages.', 'Full day', 'October to March', 'Ask locals for the confluence beach (Sagara Sangamam) point behind the temple; Konaseema roads are scenic but slow, so allow a full day.', 'no', 'Puducherry', 0, 1, '5:51 AM', '5:49 PM', NULL, 4, 4, 16.3356, 81.7256, 'Antarvedi, Konaseema district, Andhra Pradesh, India', NULL, 0.8);

