INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 354000097, 'insert', 'bulk', 'Geocoder missed this temple (returned Karnataka); coordinates 16.3356, 81.7256 are township-level approximations of Antarvedi at the Godavari confluence. Distance from Yanam is a straight-line/road estimate (~70-75 km).', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (354000098, 354004, 'Sri Veereswara Swamy Temple, Muramalla', 'Sri Veereswara Swamy Temple, Muramalla', 'The Sri Veereswara Swamy Temple at Muramalla, about 20-25 km from Yanam, is a hill temple dedicated to Veerabhadra Swamy (a fierce form of Shiva). It is revered by devotees who pray for relief from disease and for health, wealth and prosperity. Published timings are 5 AM to 11:30 AM and 5 PM to 9 PM.', '2-3 hours', 'October to March', 'Climb in the early morning slot; the hilltop setting gives the best views before the heat builds.', 'no', 'Puducherry', 0, 0, '5:51 AM', '5:49 PM', NULL, 3.5, 4, 16.63, 82.255, 'Muramalla, I. Polavaram Mandal, Konaseema district, Andhra Pradesh 533220, India', NULL, 0.74);

INSERT OR IGNORE INTO opening_hours (id, place_id, monday, tuesday, wednesday, thursday, friday, saturday, sunday, notes) VALUES (354000098, 354000098, '5:00 AM - 11:30 AM, 5:00 PM - 9:00 PM', '5:00 AM - 11:30 AM, 5:00 PM - 9:00 PM', '5:00 AM - 11:30 AM, 5:00 PM - 9:00 PM', '5:00 AM - 11:30 AM, 5:00 PM - 9:00 PM', '5:00 AM - 11:30 AM, 5:00 PM - 9:00 PM', '5:00 AM - 11:30 AM, 5:00 PM - 9:00 PM', '5:00 AM - 11:30 AM, 5:00 PM - 9:00 PM', 'From wanderon.in blog; traveltriangle.com shows the same hours with a likely typo (11:30 pm); midday closure is the consistent reading');

