INSERT INTO ingestion_log (entity_type, entity_id, action, source, errors, ingested_by) VALUES ('place', 354000098, 'insert', 'bulk', 'Geocoder missed (returned Tamil Nadu); coordinates are village-level approximations for Muramalla (PIN 533220) in Konaseema. Note: wanderon''s text describes the hill temple ''in Yanam'' but gives the Muramalla address — naming treated as the Muramalla temple with ambiguity flagged.', 'pipeline');

INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (354000099, 354004, 'Aloha Restaurant & Lodge', 'Aloha Restaurant & Lodge', 'Aloha Restaurant & Lodge is Yanam''s highest-rated multicuisine restaurant, serving North Indian, Mughlai, Chinese and seafood dishes on Vishnalayam Street near Chinna Center. Published menu prices include Mutton Mughlai Biryani at Rs 455 and Fish Fried at Rs 470. Also operates as a budget lodge.', '1 hour', 'Year-round', 'The lodge upstairs makes this the practical pick if you are staying overnight in Yanam; lunch is the reliably open service.', 'no', 'Puducherry', 0, 0, '5:51 AM', '5:49 PM', NULL, 4, 4, 16.7315, 82.227, 'Door No 3-100-29/B, Opposite Apollo Pharmacy, Vishnalayam Street, Yanam 533464, India (1st Floor, above Union Bank, Chinna Center)', NULL, 0.8);

