INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (354000100, 354004, 'Shanmukha Family Restaurant', 'Shanmukha Family Restaurant', 'Shanmukha Family Restaurant is Yanam''s best-known biryani and non-vegetarian restaurant, listed on Vishnulayam Street near Chinna Center. restaurant-guru.in describes it as the ''Best Non veg restaurant in Yanam''.', '1 hour', 'Year-round', 'Order the biryani - it is the restaurant''s signature; this is the go-to non-veg dinner spot in town.', 'no', 'Puducherry', 0, 0, '5:51 AM', '5:49 PM', NULL, 4, 4, 16.7305, 82.224, 'Vishnulayam Street / Chinna Center (Black Glass Building), Yanam, East Godavari 533464, India', NULL, 0.8);

