INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (354000101, 354004, 'Seagulls Restaurant Yanam', 'Seagulls Restaurant Yanam', 'Seagulls Restaurant Yanam is a multicuisine restaurant and bar on the Yanam-Savitri Nagar Road, near the ferry/beach side of town. Reviews praise its peaceful environment and prawn dishes (prawns biryani around Rs 235 in one review). It is one of Yanam''s most-reviewed restaurants.', '1-2 hours', 'Year-round', 'Good pick for an evening meal near the beach side of town; try the prawn specials.', 'no', 'Puducherry', 0, 0, '5:51 AM', '5:49 PM', NULL, 3.5, 3.5, 16.730289, 82.217738, '6-2-210, Yanam - Savitri Nagar Rd, Subhadranagar, Kurasempeta, Yanam, Puducherry 533464, India', NULL, 0.7);

