INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (354000102, 354004, 'New Punjabi Family Dhaba', 'New Punjabi Family Dhaba', 'New Punjabi Family Dhaba is a popular budget dhaba in Yanam serving North Indian and Punjabi food with vegetarian options, described by reviewers as cheap and best for foodies. It ranks among Yanam''s top-rated restaurants on aggregator listings.', '1 hour', 'Year-round', 'The cheapest satisfying meal in town - good option for groups wanting North Indian food on a budget.', 'no', 'Puducherry', 0, 0, '5:51 AM', '5:49 PM', NULL, 4, 4, 16.7295, 82.2215, 'Yanam, Puducherry 533464, India', NULL, 0.8);

