INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (354000103, 354004, 'Vinayaka Family Restaurant', 'Vinayaka Family Restaurant', 'Vinayaka Family Restaurant is a family restaurant on Vishnu Street in Neelapalli, near the Venkateswara Temple, known for non-veg starters like chicken kebab, Chicken 65 and chicken lollipop. Listings report late closing (10-11:30 PM).', '1 hour', 'Year-round', 'Handy for a late dinner after temple darshan at Vishnalayam; try the chicken kebab starters.', 'no', 'Puducherry', 0, 0, '5:51 AM', '5:49 PM', NULL, 4, 3.5, 16.731, 82.227, 'Vishnu Street, Neelapalli (near Venkateswara Temple, opposite SBI and Indian Bank), Yanam 533464, India', NULL, 0.76);

