INSERT OR IGNORE INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score) VALUES (354000104, 354004, 'Sri Teja Vindu Bhojanam', 'Sri Teja Vindu Bhojanam', 'Sri Teja Vindu Bhojanam is a vegetarian restaurant in Yanam serving traditional Andhra vegetarian meals (vindu bhojanam = feast meals). It is the main pure-veg option listed among Yanam''s restaurants.', '1 hour', 'Year-round', 'The safe choice for vegetarian travellers and for prasadam-style meals on temple days.', 'no', 'Puducherry', 0, 0, '5:51 AM', '5:49 PM', NULL, 3.5, 3.5, 16.7308, 82.2228, 'Yanam, Puducherry 533464, India', NULL, 0.7);

