INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3540018, 354, 354004, 'Yanam Sri Rajarajeswara Kalyanotsavam', 'Jan-Feb', 'Yanam''s most important annual festival: a 20-day Kalyanotsavam at the 15th-century Sri Rajarajeswara Temple (Sivalayam) in the month of Magha. Kalyanam is performed on Magha Shuddha Dvadashi; the deity is dressed as bridegroom and taken in chariot processions with Rathostavam and Trishulatirtham events.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3540019, 354, 354004, 'Yanam Venkanna Babu Kalyanotsavam', 'Feb-Mar', 'Annual marriage festival (Kalyanotsavam) of Lord Venkanna Babu at Vishnalayam in the month of Phalguna. Commences on Phalguna Shuddha Padyami with the bridegroom-making of the Lord, followed by daily vahanam processions; Ponnavahanam, Ratha Yatra and Chakratirtham are the key events. Draws around 1.5 lakh devotees.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3540020, 354, 354004, 'Catholic Festival at St. Ann''s Church', 'March', 'Annual Catholic festival at St. Ann''s Church. Devotees, including Christians, Hindus and Muslims, come to honour and pray to Mother Mary.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3540021, 354, 354004, 'Brahmotsavam (Venkanna Babu)', 'Sep-Oct', '10-day Brahmotsavam at Vishnalayam for Lord Venkanna Babu, conducted on the lines of the Tirupati Brahmotsavam, drawing large crowds.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3540022, 354, 354004, 'Fete de Pondichery', 'August', 'Three-day annual cultural festival conducted by the Department of Art and Culture, Government of Puducherry, celebrating the territory''s Franco-Tamil cultural fusion. Exact dates are announced each year; the August label is approximate.');

INSERT OR IGNORE INTO festivals (id, state_id, city_id, festival_name, approx_month, description) VALUES (3540023, 354, 354004, 'Yanam People''s Festival', 'January', 'Yanam People''s Festival held in January. Historically linked to the Tuesday market (Marche du mardi / Mangalavaram Santa), when Telugu people from the Madras Presidency visited Yanam to buy foreign goods during the festival.');

