INSERT OR IGNORE INTO photos (id, place_id, source_file, thumbnail_url, thumbnail_width, thumbnail_height, photo_title, photo_author, license, license_url, source_url, credit, usage_terms, description) VALUES (354800002, 354000002, 'File:Rock Beach in Puducherry.jpg', 'https://upload.wikimedia.org/wikipedia/commons/6/61/Rock_Beach_in_Puducherry.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled', 800, 571, 'Rock Beach in Puducherry.jpg', 'Devanshi07', 'CC BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 'https://commons.wikimedia.org/wiki/File:Rock_Beach_in_Puducherry.jpg', 'Own work', 'Creative Commons Attribution-Share Alike 4.0', 'Promenade Beach (or, known as, "Rock Beach") is the popular stretch of beachfront in Puducherry  India, along the Bay of Bengal. It is a 1.2-kilometer-long stretch in Puducherry, starts from War Memorial and end at Dupleix Park on the Goubert Avenue.It is bordered by a street with restaurants, this scenic, rocky beach draws crowds during the evening. Amazing View , Peaceful environment , Nature''s gift super combination. Tourist can enjoy amazing view at rock beach. It''s bordered by a street with restaurants so tourist can enjoy food with nice view. Sunrise and sunset is attraction moments for ');

