INSERT OR IGNORE INTO photos (id, place_id, source_file, thumbnail_url, thumbnail_width, thumbnail_height, photo_title, photo_author, license, license_url, source_url, credit, usage_terms, description) VALUES (354800016, 354000016, 'File:Old Lighthouse, Rock Beach, Pondicherry (Puducherry), India.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/64/Old_Lighthouse%2C_Rock_Beach%2C_Pondicherry_%28Puducherry%29%2C_India.jpg/960px-Old_Lighthouse%2C_Rock_Beach%2C_Pondicherry_%28Puducherry%29%2C_India.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 800, 1067, 'Old Lighthouse, Rock Beach, Pondicherry (Puducherry), India.jpg', 'CommonsNomad', 'CC BY-SA 3.0', 'https://creativecommons.org/licenses/by-sa/3.0', 'https://commons.wikimedia.org/wiki/File:Old_Lighthouse,_Rock_Beach,_Pondicherry_(Puducherry),_India.jpg', 'Own work', 'Creative Commons Attribution-Share Alike 3.0', 'The Old Lighthouse situated on the Rock Beach, Pondicherry (Puducherry), India. Built in 1836, the 29-metre-high lighthouse was the first to guide ships along the Coromandel Coast. It originally operated with oil lamps during the French colonial period before being electrified with rotating beams in 1931. The lighthouse served as a customs office and residence from 1941 before being decommissioned in 1979 when a new lighthouse was built near Pondicherry Marina Beach. The structure has since been renovated and is maintained by the Puducherry CGST Commissionerate as a cultural and heritage centr');

