INSERT OR IGNORE INTO photos (id, place_id, source_file, thumbnail_url, thumbnail_width, thumbnail_height, photo_title, photo_author, license, license_url, source_url, credit, usage_terms, description) VALUES (354800018, 354000018, 'File:Gingee Fort Villuppuram Tamil Nadu 20181001 134507.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/51/Gingee_Fort_Villuppuram_Tamil_Nadu_20181001_134507.jpg/960px-Gingee_Fort_Villuppuram_Tamil_Nadu_20181001_134507.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 800, 600, 'Gingee Fort Villuppuram Tamil Nadu 20181001 134507.jpg', 'Ruby Vishal Mahajan', 'CC BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 'https://commons.wikimedia.org/wiki/File:Gingee_Fort_Villuppuram_Tamil_Nadu_20181001_134507.jpg', 'Own work', 'Creative Commons Attribution-Share Alike 4.0', 'View from the top of Gingee Fort or Senji Fort (also known as Chenji, Chanchi, Jinji or Senchi).It   is one of the surviving forts in Tamil Nadu, India. It lies in Villupuram District, 160 kilometres  from the state capital, Chennai, and is close to the Union Territory of Puducherry. The fort is so fortified, that Shivaji, the Maratha king, ranked it as the "most impregnable fortress in India" and it was called the "Troy of the East" by the British');

INSERT OR IGNORE INTO photos (id, place_id, source_file, thumbnail_url, thumbnail_width, thumbnail_height, photo_title, photo_author, license, license_url, source_url, credit, usage_terms, description) VALUES (354800019, 354000019, 'File:Mamallapuram, Mahabalipuram, Shore Temple, India.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c4/Mamallapuram%2C_Mahabalipuram%2C_Shore_Temple%2C_India.jpg/960px-Mamallapuram%2C_Mahabalipuram%2C_Shore_Temple%2C_India.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 800, 606, 'Mamallapuram, Mahabalipuram, Shore Temple, India.jpg', 'Vyacheslav Argenberg', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0', 'https://commons.wikimedia.org/wiki/File:Mamallapuram,_Mahabalipuram,_Shore_Temple,_India.jpg', 'Own work', 'Creative Commons Attribution 4.0', 'The Shore Temple (8th century AD) of the Pallava dynasty is within the group of monuments at Mahabalipuram on the shore of the Bay of Bengal. It is one of the oldest stone temples in South India. Mamallapuram, Mahabalipuram, Tamil Nadu, India.');

